function RecordNewAirUnitForTeam(iTeam, oUnit)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordNewAirUnitForTeam'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': iTeam='..iTeam..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Unit team='..oUnit:GetAIBrain().AiBotTeam..'; table of active AiBot brains for this team is empty?='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]))) end
    local sTeamTableRef
    --Is this an enemy unit?
    if not(oUnit:GetAIBrain().AiBotTeam == iTeam) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) == false then
        if EntityCategoryContains(AiBotUnitInfo.refCategoryAirToGround, oUnit.UnitId) then
            sTeamTableRef = AiBotTeam.reftoEnemyAirToGround
        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA, oUnit.UnitId) then
            sTeamTableRef = AiBotTeam.reftoEnemyAirAA
        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryTorpBomber, oUnit.UnitId) then
            sTeamTableRef = AiBotTeam.reftoEnemyTorpBombers
        elseif oUnit.UnitId == 'uese0001' then
            --Special unit that is a bit like a novax satellite, except it can be targeted by SMD
            if not(AiBotUtilities.DoesCategoryContainCategory(categories.uese0001, AiBotTeam.tEnemyBigThreatCategories[AiBotTeam.reftEnemyNukeLaunchers], false)) then
                AiBotTeam.tEnemyBigThreatCategories[AiBotTeam.reftEnemyNukeLaunchers] = AiBotTeam.tEnemyBigThreatCategories[AiBotTeam.reftEnemyNukeLaunchers] + categories.uese0001
            end
            AiBotTeam.AddUnitToBigThreatTable(iTeam, oUnit)
            --Also track as mobile TML
            AiBotTeam.RecordMobileTMLThreatForAllEnemyTeams(oUnit)
        else
            sTeamTableRef = AiBotTeam.reftoEnemyAirOther
        end
        if sTeamTableRef then
            if bDebugMessages == true then LOG(sFunctionRef..': About to insert unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; into table sTeamTableRef='..sTeamTableRef) end
            table.insert(AiBotTeam.tTeamData[iTeam][sTeamTableRef], oUnit)
            table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoAllEnemyAir], oUnit)

            local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
            local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
            if aiBrain then

                if iPlateauOrZero == 0 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will add unit to water zone, iLandOrWaterZone='..(iLandOrWaterZone or 'nil')) end
                    AiBotTeam.AddUnitToWaterZoneForBrain(aiBrain, oUnit, iLandOrWaterZone, true)
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Will add unit to land zone, iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; iPlateauOrZero='..(iPlateauOrZero or 'nil')) end
                    AiBotTeam.AddUnitToLandZoneForBrain(aiBrain, oUnit, iPlateauOrZero, iLandOrWaterZone, true)
                end
            end
        end
        --[[local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(oUnit:GetPosition(), false, nil)
        if (iLandZone or 0) == 0 then
            --Does it have a water zone?
            local iSegmentX, iSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oUnit:GetPosition())
            local iWaterZone = AiBotMap.tWaterZoneBySegment[iSegmentX][iSegmentZ]
            if iWaterZone > 0 then
                local aiBrain
                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                    aiBrain = oBrain
                    break
                end
                AiBotTeam.AddUnitToWaterZoneForBrain(aiBrain, oUnit, iWaterZone, true)
            else
                RecordEnemyAirUnitWithNoZone(iTeam, oUnit)
            end
        else
            local aiBrain
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                aiBrain = oBrain
                break
            end
            AiBotTeam.AddUnitToLandZoneForBrain(aiBrain, oUnit, iPlateau, iLandZone, true)
        end--]]
    else
        --Friendly unit
        local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if this is an under construction air experimental, fraction complete='..oUnit:GetFractionComplete()..'; Is enemy='..tostring(IsEnemy(aiBrain:GetArmyIndex(), oUnit:GetAIBrain():GetArmyIndex()))) end
        if EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId) and oUnit:GetFractionComplete() < 1 then
            --Record against list of units in the zone while under construction
            local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
            if (iLandOrWaterZone or 0) > 0 then
                if iPlateauOrZero == 0 then
                    AiBotTeam.AddUnitToWaterZoneForBrain(aiBrain, oUnit, iLandOrWaterZone, false)
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Added unit to land zone '..iLandOrWaterZone) end
                    AiBotTeam.AddUnitToLandZoneForBrain(aiBrain, oUnit, iPlateauOrZero, iLandOrWaterZone, false)
                end
            end
        end
        if oUnit.UnitId == 'uese0001' then
            ForkThread(ManageSpaceship, iTeam, oUnit)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordEnemyAirUnitWithNoZone(iTeam, oUnit)
    local sFunctionRef = 'RecordEnemyAirUnitWithNoZone'
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    AiBotUtilities.ErrorHandler('Obsolete code which wasnt expected to be used')
    table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyUnitsWithNoLZ], oUnit)
    if not(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam]) then
        if not(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam]) then oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam] = {} end
        oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam] = {}
    end
    if not(oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam]) then
        if not(oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam]) then oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam] = {} end
        oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] = {}
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

