function UpdateEnemyAirThreats(iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateEnemyAirThreats'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --Calculate threat ratings
    if bDebugMessages == true then
        LOG(sFunctionRef..': Start of code, gametime='..GetGameTimeSeconds()..'; Is table of enemy air to ground threat empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround])))
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround]) == false then
            for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround] do
                LOG(sFunctionRef..': unit '..iUnit..' in enemy air to ground, ref='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' has an air to ground threat of '..AiBotUnitInfo.GetAirThreatLevel({ oUnit }, true, false, false, true, false, false))
            end
        end
    end
    --Base air threats on the highest enemy team threat, not all enemy teams combined (e.g. relevant where 3+ teams)
                                                                        --GetAirThreatLevel(tUnits,                                             bEnemyUnits,    bIncludeAirToAir, bIncludeGroundToAir, bIncludeAirToGround, bIncludeNonCombatAir, bIncludeAirTorpedo, bBlueprintThreat, bRecordByTeam)
    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] = AiBotUnitInfo.GetAirThreatLevel(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoAllEnemyAir], true,            true,               false,              false,                  false,              false,              nil,                true)
    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] = AiBotUnitInfo.GetAirThreatLevel(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround], true, false,              false,              true,                   false,              false,              nil,                true)
    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyTorpBombersThreat] = AiBotUnitInfo.GetAirThreatLevel(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyTorpBombers], true, false,              false,              false,                  false,              true,              nil,                true)
    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirOtherThreat] = AiBotUnitInfo.GetAirThreatLevel(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirOther], true,       true,               false,              true,                   true,               true,              nil,                true)
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, time='..GetGameTimeSeconds()..'; Enemy AirAA threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]..'; Air to ground threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]..'; Torp bomber threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyTorpBombersThreat]..'; Other threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirOtherThreat]) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateTeamAirThreats(iTeam)
    AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] = 0
    AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] = 0
    AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurExpBomberThreat] = 0
    AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] = 0
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefAirSubteamsInTeam]) == false then
        for iEntry, iAirSubteam in AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefAirSubteamsInTeam] do
            AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurGunshipThreat] + (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat] or 0)
            AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] + (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurT1ToT3BomberThreat] or 0)
            AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurExpBomberThreat] = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurExpBomberThreat] + (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurExpBomberThreat] or 0)
            AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] + (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] or 0)
        end
    end
end

function AirTeamOverseer(iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AirTeamOverseer'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    while not(AiBotMap.bMapLandSetupComplete) or not(AiBotMap.bWaterZoneInitialCreation) do
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitSeconds(5) --extra delay to be safe
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    AssignScoutingIntervalPriorities(iTeam)
    if AiBotTeam.GetFirstActiveAiBotBrain(iTeam).HostileCampaignAI and tonumber(ScenarioInfo.Options.CmpAIDelay) > GetGameTimeSeconds() + 0.2 then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(tonumber(ScenarioInfo.Options.CmpAIDelay) - GetGameTimeSeconds() - 0.2)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end
    while AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 0 do
        if ScenarioInfo.OpEnded and AiBotMap.bIsCampaignMap and GetGameTimeSeconds() <= 120 then
            while ScenarioInfo.OpEnded do
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(1)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) then break end
        end

        ForkThread(RefreshZonelessAir, iTeam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        ForkThread(UpdateEnemyAirThreats, iTeam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        ForkThread(UpdateTeamAirThreats, iTeam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(7)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        --NOTE: Other logic is done on air subteam basis
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        if iExtraTicksToWaitBetweenAirCycles > 0 then WaitTicks(iExtraTicksToWaitBetweenAirCycles) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        tbFullAirTeamCycleRun[iTeam] = true
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AddUnitWantingPriorityScout(oUnit, bDontCheckIfInTable, iAirSubteamIfUnitIsEnemy)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AddUnitWantingPriorityScout'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bAddUnit = true
    local iAirSubteam = iAirSubteamIfUnitIsEnemy or oUnit:GetAIBrain().AiBotAirSubteam
    if not(bDontCheckIfInTable) and AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout]) == false then
        for iExistingUnit, oExistingUnit in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout] do
            if oExistingUnit == oUnit then bAddUnit = false break end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Will add unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to priority table of units wanting scout unless it is already there, bAddUnit='..tostring(bAddUnit)..'; iAirSubteam='..iAirSubteam..'; Time='..GetGameTimeSeconds()) end
    if bAddUnit then
        if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout]) then AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout] = {} end
        table.insert(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout], oUnit)
        oUnit[refiTimeLastWantedPriorityAirScout] = GetGameTimeSeconds()
    end
end

function RemoveUnitFromPriorityScoutTable(oUnit, iAirSubteamIfUnitIsEnemy)
    local iAirSubteam = iAirSubteamIfUnitIsEnemy or oUnit:GetAIBrain().AiBotAirSubteam
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout]) == false then
        for iExistingUnit, oExistingUnit in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout] do
            if oExistingUnit == oUnit then table.remove(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout], iExistingUnit) break end
        end
    end
end

function AssignScoutingIntervalPriorities(iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AssignScoutingIntervalPriorities'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Make all enemy start positions a high priority
    local iPlateauOrZero, iLandOrWaterZone
    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains] do
        if bDebugMessages == true then LOG(sFunctionRef..': About to get closest plateau and zone for the enemy start position, oBrain='..oBrain.Nickname..'; start point='..repru(AiBotMap.GetPlayerStartPosition(oBrain))..'; Map plyaable area='..repru(AiBotMap.rMapPlayableArea)..'; Map size='..repru(ScenarioInfo.size)..'; rMapPotentialPlayableArea='..repru(AiBotMap.rMapPotentialPlayableArea)) end
        --Check if are within the playable area
        local tStartPoint = AiBotMap.GetPlayerStartPosition(oBrain)
        if not(AiBotMap.bIsCampaignMap) or AiBotMap.InPlayableArea(tStartPoint) then
            iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tStartPoint)
            if bDebugMessages == true then LOG(sFunctionRef..': setting P'..iPlateauOrZero..'Z'..iLandOrWaterZone..' to be a high scouting priority') end
            if iPlateauOrZero == 0 then
                AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][iTeam][AiBotMap.refiScoutingPriority] = AiBotMap.subrefiScoutingHighPriority
            else
                AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.refiScoutingPriority] = AiBotMap.subrefiScoutingHighPriority
            end
        end
    end

    --Make any land zone with a mex a medium priority
    for iPlateau, tPlateauSubtable in AiBotMap.tAllPlateaus do
        for iLandZone, tLZData in tPlateauSubtable[AiBotMap.subrefPlateauLandZones] do
            local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
            if not(tLZTeamData[AiBotMap.refiScoutingPriority]) then
                if tLZData[AiBotMap.subrefLZOrWZMexCount] > 0 then
                    tLZTeamData[AiBotMap.refiScoutingPriority] = AiBotMap.subrefiScoutingMediumPriority
                else
                    tLZTeamData[AiBotMap.refiScoutingPriority] = AiBotMap.subrefiScoutingLowPriority
                end
            end
        end
    end

    --Same for water zones with mexes
    for iPond, tPondSubtable in AiBotMap.tPondDetails do
        for iWaterZone, tWZData in tPondSubtable[AiBotMap.subrefPondWaterZones] do
            local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
            if not(tWZTeamData[AiBotMap.refiScoutingPriority]) then
                if tWZData[AiBotMap.subrefLZOrWZMexCount] > 0 then
                    tWZTeamData[AiBotMap.refiScoutingPriority] = AiBotMap.subrefiScoutingMediumPriority
                else
                    tWZTeamData[AiBotMap.refiScoutingPriority] = AiBotMap.subrefiScoutingLowPriority
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AirTeamInitialisation(iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AirTeamInitialisation'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoAllEnemyAir] = {}
    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirAA] = {}
    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround] = {}
    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyTorpBombers] = {}
    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirOther] = {}
    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyUnitsWithNoLZ] = {}
    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] = 0
    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] = 0
    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyTorpBombersThreat] = 0
    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirOtherThreat] = 0

    ForkThread(AirTeamOverseer, iTeam)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AirSubteamInitialisation(iTeam, iAirSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AirSubteamInitialisation'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for iTeam='..iTeam..'; iAirSubteam='..iAirSubteam..'; Time='..GetGameTimeSeconds()..'; will call air subteamoverseer') end
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] = true
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] = false
    --Set default values for rally points (for campaign where we might not have started main logic yet)
    local oFirstBrain
    for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
        oFirstBrain = oBrain
        break
    end
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint] = AiBotMap.GetPlayerStartPosition(oFirstBrain)
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = AiBotMap.GetPlayerStartPosition(oFirstBrain)
    ForkThread(AirSubteamOverseer, iTeam, iAirSubteam)
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordTorpedoBomberPriorityLocations(iTeam, iAirSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordTorpedoBomberPriorityLocations'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iMaxAdjacencySearchLevel
    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then iMaxAdjacencySearchLevel = 3
    elseif AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then iMaxAdjacencySearchLevel = 2
    else iMaxAdjacencySearchLevel = 1
    end

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, Time='..GetGameTimeSeconds()..'; iMaxAdjacencySearchLevel='..iMaxAdjacencySearchLevel..'; AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiLastTorpBomberAdjacencyLevel]='..(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiLastTorpBomberAdjacencyLevel] or 'nil')) end
    if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiLastTorpBomberAdjacencyLevel] == iMaxAdjacencySearchLevel) then
        AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiLastTorpBomberAdjacencyLevel] = iMaxAdjacencySearchLevel
        AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftiTorpedoDefenceWaterZones] = {}

        local tbAddedZones = {}
        local tiMinZoneLevelRecorded = {}
        local iCurAdjacencyLevel
        function AddWaterZoneToTorpedoDefenceZones(iWZToAdd, iLevelRecordedAt)
            if not(tbAddedZones[iWZToAdd]) then
                table.insert(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftiTorpedoDefenceWaterZones], iWZToAdd)
                tbAddedZones[iWZToAdd] = true
            end
            tiMinZoneLevelRecorded[iWZToAdd] = math.min((tiMinZoneLevelRecorded[iWZToAdd] or iLevelRecordedAt), iLevelRecordedAt)
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code for iAirSubteam '..iAirSubteam..' in iTeam '..iTeam..' at the game time='..GetGameTimeSeconds()) end
        for iPond, tPondSubtable in AiBotMap.tPondDetails do
            AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiRallyPointWaterZonesByPond][iPond] = {}
            for iWaterZone, tWZData in tPondSubtable[AiBotMap.subrefPondWaterZones] do
                local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                if tWZTeamData[AiBotMap.subrefWZbContainsNavalBuildLocation] or (AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])) == false) then
                    iCurAdjacencyLevel = 0
                    if not(tbAddedZones[iWaterZone]) or tiMinZoneLevelRecorded[iWaterZone] > iCurAdjacencyLevel then
                        AddWaterZoneToTorpedoDefenceZones(iWaterZone, iCurAdjacencyLevel)

                        if bDebugMessages == true then LOG(sFunctionRef..': Added WZ '..iWaterZone..'; is table of adj WZ empty='..tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZAdjacentWaterZones]))) end
                        if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false and (tWZTeamData[AiBotMap.subrefWZbContainsNavalBuildLocation] or iMaxAdjacencySearchLevel > 1) then
                            for _, iAdjWZ in tWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                                iCurAdjacencyLevel = 1
                                if not(tbAddedZones[iAdjWZ]) or tiMinZoneLevelRecorded[iAdjWZ] > iCurAdjacencyLevel then
                                    AddWaterZoneToTorpedoDefenceZones(iAdjWZ, iCurAdjacencyLevel)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Added iAdjWZ='..iAdjWZ..'; are we far behind on air='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir])) end
                                    --Include zones adjacent to this if not far behind on air
                                    if iMaxAdjacencySearchLevel > iCurAdjacencyLevel then
                                        for _, iSecondAdjWZ in AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZAdjacentWaterZones] do
                                            iCurAdjacencyLevel = 2
                                            if (not(tbAddedZones[iSecondAdjWZ]) or tiMinZoneLevelRecorded[iSecondAdjWZ] > iCurAdjacencyLevel or (not(tWZTeamData[AiBotMap.subrefWZbContainsNavalBuildLocation]) and (iCurAdjacencyLevel == 2 or iCurAdjacencyLevel >= 2))) then
                                                AddWaterZoneToTorpedoDefenceZones(iSecondAdjWZ, iCurAdjacencyLevel)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Added iSecondAdjWZ='..iSecondAdjWZ..'; Do we have air control='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl])) end
                                                --If have significant torpedo threat then consider adding the next line
                                                if iMaxAdjacencySearchLevel > iCurAdjacencyLevel then
                                                    for _, iThirdAdjWZ in AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iSecondAdjWZ][AiBotMap.subrefWZAdjacentWaterZones] do
                                                        iCurAdjacencyLevel = 3
                                                        if not(tbAddedZones[iThirdAdjWZ]) or tiMinZoneLevelRecorded[iThirdAdjWZ] > iCurAdjacencyLevel then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Added iThirdAdjWZ='..iThirdAdjWZ) end
                                                            AddWaterZoneToTorpedoDefenceZones(iThirdAdjWZ, iCurAdjacencyLevel)
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftiTorpedoDefenceWaterZones]='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftiTorpedoDefenceWaterZones])) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ReassessTorpBomberPriorityLocations(iTeam, iAirSubteam)
    local iCurCount = 0
    while iCurCount <= 10 do
        iCurCount = iCurCount + 1
        WaitSeconds(1)
        if iCurCount >= 10 then
            iCurCount = 0
            ForkThread(RecordTorpedoBomberPriorityLocations, iTeam, iAirSubteam)
        end
    end

end

function AirSubteamOverseer(iTeam, iAirSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AirSubteamOverseer'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    while not(AiBotMap.bMapLandSetupComplete) or not(AiBotMap.bWaterZoneInitialCreation) or (not(AiBotMap.bRecordedIslands) and GetGameTimeSeconds() <= 15) do
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    WaitSeconds(5) --extra delay to be safe
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotTeam.GetFirstActiveAiBotBrain(iTeam).HostileCampaignAI and tonumber(ScenarioInfo.Options.CmpAIDelay) > GetGameTimeSeconds() + 0.1 then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(tonumber(ScenarioInfo.Options.CmpAIDelay) - GetGameTimeSeconds() -0.1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end

    if ScenarioInfo.OpEnded and AiBotMap.bIsCampaignMap and GetGameTimeSeconds() <= 120 then
        while ScenarioInfo.OpEnded do
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end

    --Record torpedo bomber locations to defend
    RecordTorpedoBomberPriorityLocations(iTeam, iAirSubteam)
    ForkThread(ReassessTorpBomberPriorityLocations, iTeam, iAirSubteam)

    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] = 0
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiOurGunshipAAThreat] = 0
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat] = 0
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurTorpBomberThreat] = 0
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurT1ToT3BomberThreat] = 0
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurExpBomberThreat] = 0

    while AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains]) == false do
        if ScenarioInfo.OpEnded and AiBotMap.bIsCampaignMap and GetGameTimeSeconds() <= 120 then
            while ScenarioInfo.OpEnded do
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                WaitSeconds(1)
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            end
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains]) then break end
        end

        ForkThread(UpdateAirRallyAndSupportPoints, iTeam, iAirSubteam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        ForkThread(ManageAirAAUnits, iTeam, iAirSubteam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        ForkThread(ManageBombers, iTeam, iAirSubteam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        ForkThread(ManageGunships, iTeam, iAirSubteam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        ForkThread(ManageTorpedoBombers, iTeam, iAirSubteam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        ForkThread(ManageAirScouts, iTeam, iAirSubteam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        ForkThread(ManageTransports, iTeam, iAirSubteam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        ForkThread(ManageNovax, iTeam, iAirSubteam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        ForkThread(ManageExperimentalBomber, iTeam, iAirSubteam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        ForkThread(ManageOtherAir, iTeam, iAirSubteam) --e.g. mercies
        ForkThread(AiBotTeam.CheckForHidingACU, iTeam, iAirSubteam)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitTicks(1)
        if iExtraTicksToWaitBetweenAirCycles > 0 then WaitTicks(iExtraTicksToWaitBetweenAirCycles) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        tbFullAirSubteamCycleRun[iAirSubteam] = true
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AddPriorityAirDefenceTarget(oUnit)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AddPriorityAirDefenceTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Dont try and defend novax satellite
    if not(EntityCategoryContains(categories.UNTARGETABLE, oUnit.UnitId)) then

        local iAirSubteam = oUnit:GetAIBrain().AiBotAirSubteam
        if not(iAirSubteam) or (not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam]) and not(oUnit:GetAIBrain().AiBotAI)) then
            --Search for AiBot brain that is an ally
            local aiBrain = oUnit:GetAIBrain()
            for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
                if IsAlly(oBrain:GetArmyIndex(), aiBrain:GetArmyIndex()) then
                    iAirSubteam = oBrain.AiBotAirSubteam
                    if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam]) then AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam] = {} end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iAirSubteam='..(iAirSubteam or 'nil')..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; brain='..(oUnit:GetAIBrain().Nickname or 'nil')) end
        --Check not already in table
        local bInTableAlready = false
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam]) == false then
            for iExistingUnit, oExistingUnit in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam] do
                if oExistingUnit == oUnit then
                    bInTableAlready = true
                    break
                end
            end
        end
        if not(bInTableAlready) then
            if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam]) then AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam] = {} end --redundancy - above should already cover
            table.insert(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam], oUnit)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RefreshPriorityAirDefenceTargets(iAirSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RefreshPriorityAirDefenceTargets'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam]) then
        --Presumably first time we have run this as should ahve ACUs - add ACUs
        for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
            local tACUs = oBrain:GetListOfUnits(categories.COMMAND, false, true)
            if AiBotUtilities.IsTableEmpty(tACUs) == false then
                for iACU, oACU in tACUs do
                    AddPriorityAirDefenceTarget(oACU)
                end
            else
                if ScenarioInfo.Options.Victory == "demoralization" then
                    AiBotUtilities.ErrorHandler('oBrain '..(oBrain.Nickname or 'nil')..' has no ACUs')
                end
            end
        end
    else
        --Check if unit still valid
        local iExistingEntries = table.getn(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam])

        for iCurUnit = iExistingEntries, 1, -1 do
            if not(AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam][iCurUnit])) then
                table.remove(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam], iCurUnit)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function IsAirUnitInCombat(oUnit, iTeam, tTargetOverride)
    --Intended for deciding if a low health unit belonging to AiBotTeam iTeam should return to air staging or not
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'IsAirUnitInCombat'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tLastOrder = oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]]
    if AiBotUtilities.IsTableEmpty(tLastOrder) then
        if bDebugMessages == true then LOG(sFunctionRef..': Air unit has no last orders so returning false') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return false
    else
        if not(oUnit[refoAirAACurTarget]) and EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA, oUnit.UnitId) then
            if bDebugMessages == true then LOG(sFunctionRef..': AirAA unit with no AACurTarget so returning false') end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return false
        else
            local iDistToTarget, tOrderTarget
            if tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack then
                if AiBotUnitInfo.IsUnitValid(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) then
                    tOrderTarget = tTargetOverride or tLastOrder[AiBotOrders.subrefoOrderUnitTarget]:GetPosition()
                    iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tOrderTarget)
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': last order was to attack but no valid unit to target so returning false') end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return false
                end
            elseif tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueMove or tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAggressiveMove then
                if oUnit[refoAirAACurTarget] and AiBotUnitInfo.IsUnitValid(oUnit[refoAirAACurTarget]) then
                    tOrderTarget = tTargetOverride or oUnit[refoAirAACurTarget]:GetPosition()
                    iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tOrderTarget)
                else
                    tOrderTarget = tTargetOverride or tLastOrder[AiBotOrders.subreftOrderPosition]
                    iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tOrderTarget)
                end
            else
                --Other target so treat as not in combat/wanting to refuel
                if bDebugMessages == true then LOG(sFunctionRef..': Unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' has different command to move or attack so will treat as not in combat as it may be refueling') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return false
            end
            if bDebugMessages == true then
                LOG(sFunctionRef..': Considering if air unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is in combat, iDistToTarget='..iDistToTarget..'; tLastOrder[AiBotOrders.subrefoOrderUnitTarget]='..(tLastOrder[AiBotOrders.subrefoOrderUnitTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) or 'nil')..'; oUnit[refoAirAACurTarget]='..(oUnit[refoAirAACurTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit[refoAirAACurTarget]) or 'nil')..'; Time='..GetGameTimeSeconds()..'; Time since last weapon event='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0)..'; VDist3='..VDist3(oUnit:GetPosition(), tOrderTarget)..'; refiAARange='..(oUnit[AiBotUnitInfo.refiAARange] or 'nil'))
                if oUnit[refoAirAACurTarget] then LOG(sFunctionRef..': Dist to oUnit[refoAirAACurTarget]='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnit[refoAirAACurTarget]:GetPosition())..'; VDist3='..VDist3(oUnit:GetPosition(),oUnit[refoAirAACurTarget]:GetPosition())) end
            end
            if iDistToTarget < 100 then
                local iDistThreshold = 100
                if EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA, oUnit.UnitId) then
                    iDistThreshold = math.min((oUnit[AiBotUnitInfo.refiAARange] or 35) - 5, 50)
                    if oUnit[refoAirAACurTarget].UnitId then
                        if oUnit[refoAirAACurTarget].Dead then
                            if bDebugMessages == true then LOG(sFunctionRef..': Our AirAA target is dead so returning false') end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return false
                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryBomber + AiBotUnitInfo.refCategoryTransport - categories.EXPERIMENTAL, oUnit[refoAirAACurTarget].UnitId) then
                            iDistThreshold = 55
                        elseif EntityCategoryContains(categories.EXPERIMENTAL, oUnit[refoAirAACurTarget].UnitId) then
                            iDistThreshold = 70
                            --asfs about to engage with each other
                        elseif iDistToTarget > iDistThreshold and iDistToTarget <= 60 and EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA, oUnit[refoAirAACurTarget].UnitId) then
                            --Get angle dif - if we are both almost facing each other then likely to be in range before can turn around, and have less time to adjust targets
                            local iAngleToTarget = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oUnit[refoAirAACurTarget]:GetPosition())
                            local iOurUnitFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oUnit)
                            if bDebugMessages == true then LOG(sFunctionRef..': iAngleToTarget='..iAngleToTarget..'; iOurUnitFacingAngle='..iOurUnitFacingAngle..'; Dif='..AiBotUtilities.GetAngleDifference(iAngleToTarget, iOurUnitFacingAngle)) end
                            if AiBotUtilities.GetAngleDifference(iAngleToTarget, iOurUnitFacingAngle) <= 35 then
                                local iEnemyUnitFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oUnit[refoAirAACurTarget])
                                if bDebugMessages == true then LOG(sFunctionRef..': iEnemyUnitFacingAngle='..iEnemyUnitFacingAngle..'; Dif='..AiBotUtilities.GetAngleDifference(iAngleToTarget + 180, iEnemyUnitFacingAngle)) end
                                if AiBotUtilities.GetAngleDifference(iAngleToTarget + 180, iEnemyUnitFacingAngle) <= 35 then
                                    iDistThreshold = 60
                                end
                            end
                        end
                    end
                elseif EntityCategoryContains(categories.TECH1, oUnit.UnitId) then iDistThreshold = 50
                elseif EntityCategoryContains(categories.TECH2, oUnit.UnitId) then iDistThreshold = 65
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iDistThreshold='..iDistThreshold..'; iDistToTarget='..iDistToTarget) end
                if iDistToTarget > iDistThreshold then
                    if bDebugMessages == true then LOG(sFunctionRef..': too far from target so not in combat') end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return false
                else
                    --Our target is relatively close, if we are not an airAA unit then treat as in combat if we have an attack order
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA, oUnit.UnitId) then
                        if oUnit[refoAirAACurTarget] then
                            if EntityCategoryContains(AiBotUnitInfo.refCategoryAirScout, oUnit[refoAirAACurTarget].UnitId) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Targeting air scout so will be available for new orders') end
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return false
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': We are an AirAA unit close to a target htat isnt an air scout so will commit to that target') end
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return true
                            end
                            --Treat as in combat if nearby enemy air to the target; not sure if below code is actually used?
                        elseif tOrderTarget then
                            local iPlateau, iLandZone, iWaterZone
                            iPlateau, iLandZone =  AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tOrderTarget)
                            if iPlateau then
                                if (iLandZone or 0) == 0 then
                                    iWaterZone = AiBotMap.GetWaterZoneFromPosition(tOrderTarget)
                                    if (iWaterZone or 0) == 0 then
                                        --unlikely we are going to a rally point or air staging if it isnt on land or water that can be pathed to by ground
                                        if bDebugMessages == true then LOG(sFunctionRef..': Order target not on valid zone, will return that are in combat') end
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                        return true
                                    else
                                        --Check if enemy air in water zone
                                        local tWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone][AiBotMap.subrefWZTeamData][iTeam]
                                        if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.reftWZEnemyAirUnits]) == false then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy has air units in the target water zone, so assuming we are in combat') end
                                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                            return true
                                        end
                                    end
                                else
                                    --Check if enemy air in land zone
                                    local tLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam]
                                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]) == false then
                                        if bDebugMessages == true then LOG(sFunctionRef..': enemy has air units in the LZ that we are in, so returning true') end
                                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                        return true
                                    end
                                end
                            else
                                --unlikely we are going to a rally point or air staging if it isnt on land or water that can be pathed to by ground
                                if bDebugMessages == true then LOG(sFunctionRef..': Order target not on valid plateau, will return that are in combat') end
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return true
                            end
                        end
                    else
                        --Bomber so unavailable if attack order
                        if tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack then
                            if bDebugMessages == true then LOG(sFunctionRef..': Bomber has attack order so returning true') end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        end
                    end
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef..': no dist to target so returning false') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return false
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code - returning false') end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function AddAssignedAttacker(oTarget, oNewBomber)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AddAssignedAttacker'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..'; Start of code, About to add assigned strike damage to oTarget='..(oTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTarget) or 'nil')..'; oOldBomber='..(oNewBomber.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNewBomber) or 'nil')..'; Time='..GetGameTimeSeconds()) end
    if not(oNewBomber[AiBotUnitInfo.refiStrikeDamage]) then
        --Redundancy for campaign where presumably there's a slight delay in recording a unit that gets cheated in by the map script
        AiBotUnitInfo.RecordUnitRange(oNewBomber)
    end
    local bRecordNewStrikeDamage = true
    if oNewBomber[refoStrikeDamageAssigned] then
        if not(oNewBomber[refoStrikeDamageAssigned] == oTarget) then --redundancy - AiBotOrders should already clear when issuing a clear commands
            RemoveAssignedAttacker(oNewBomber[refoStrikeDamageAssigned], oNewBomber)
        else
            bRecordNewStrikeDamage = false
        end
    end
    if bRecordNewStrikeDamage then
        if bDebugMessages == true then LOG(sFunctionRef..': oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..'; Existing strike damage='..(oTarget[refiStrikeDamageAssigned] or 0)..'; oNewBomber='..oNewBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNewBomber)..'; oNewBomber strike damage='..(oNewBomber[AiBotUnitInfo.refiStrikeDamage] or 'nil')..'; Bomber brain owner='..oNewBomber:GetAIBrain().Nickname) end
        oTarget[refiStrikeDamageAssigned] = (oTarget[refiStrikeDamageAssigned] or 0) + oNewBomber[AiBotUnitInfo.refiStrikeDamage]
        oNewBomber[refoStrikeDamageAssigned] = oTarget
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code after assigning oNewBomber '..oNewBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNewBomber)..' to target oTarget '..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..'; Strike damage assigned='..oTarget[refiStrikeDamageAssigned]..'; Time='..GetGameTimeSeconds()) end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RemoveAssignedAttacker(oTarget, oOldBomber)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RemoveAssignedAttacker'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..'; Start of code, About to remove assigned strike damage from oTarget='..(oTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTarget) or 'nil')..'; oOldBomber='..(oOldBomber.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oOldBomber) or 'nil')..'; Time='..GetGameTimeSeconds()) end
    if not(oOldBomber[AiBotUnitInfo.refiStrikeDamage]) then
        AiBotUtilities.ErrorHandler('Bomber '..(oOldBomber.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oOldBomber) or 'nil')..' doesnt have any strike damage, will reset unit strike damage assignment')
        oTarget[refiStrikeDamageAssigned] = 0
    else
        oTarget[refiStrikeDamageAssigned] = math.max(0, (oTarget[refiStrikeDamageAssigned] or 0) - oOldBomber[AiBotUnitInfo.refiStrikeDamage])
    end
    oOldBomber[refoStrikeDamageAssigned] = nil

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end


function GetAvailableLowFuelAndInUseAirUnits(iTeam, iAirSubteam, iCategory, bRecordInTorpBomberWaterZoneList, bLowHealthThresholdDueToSnipeTarget)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetAvailableLowFuelAndInUseAirUnits'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local tAvailableUnits = {}
    local tUnitsForRefueling = {}
    local tInUseUnits = {}
    local tSpecialLogicUnits = {}
    local iLowFuelThreshold = 0.25
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbActiveDefenseObjective] then iLowFuelThreshold = 0.2 end
    local iLowHealthThreshold = iProjectileLowHealthThreshold
    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbOrigRallyOutsidePlayableArea] or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDontHaveBuildingsOrACUInPlayableArea] then
        local bHaveAirStaging = false
        for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
            if oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirStaging) > 0 then
                bHaveAirStaging = true
                break
            end
        end
        if not(bHaveAirStaging) then
            iLowFuelThreshold = 0
            iLowHealthThreshold = 0
        end
    end
    if bLowHealthThresholdDueToSnipeTarget or (GetGameTimeSeconds() <= 300 and iLowHealthThreshold > 0 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] == 1) then
        iLowFuelThreshold = math.min(iLowFuelThreshold, 0.05)
        iLowHealthThreshold = math.min(iLowHealthThreshold, 0.1)
    end
    local bIncludeBombersInSpecialLogic

    for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
        if oBrain.AiBotAI then
            local tCurUnits = oBrain:GetListOfUnits(iCategory, false, true)

            local iFuelPercent
            local iHealthPercent
            local bSendUnitForRefueling
            local iSegmentX, iSegmentZ
            local bProceed
            if bDebugMessages == true then LOG(sFunctionRef..': Is tCurUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tCurUnits))..'; oBrain='..oBrain.Nickname..'; iTeam='..iTeam..'; iAirSubteam='..iAirSubteam) end
            if AiBotUtilities.IsTableEmpty(tCurUnits) == false then
                if bIncludeBombersInSpecialLogic == nil then
                    bIncludeBombersInSpecialLogic = false
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis]) == false then
                        for iWZ, iBombersWanted in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis] do
                            if iBombersWanted > 0 then bIncludeBombersInSpecialLogic = true break end
                        end
                    end
                end
                for iUnit, oUnit in tCurUnits do
                    if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() >= 1 then --Needed as sometimes an invalid unit is included from getlistofunits; also because underproduction units are included with getlistofunits
                        if bRecordInTorpBomberWaterZoneList then
                            iSegmentX, iSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oUnit:GetPosition())
                            if AiBotMap.tWaterZoneBySegment[iSegmentX][iSegmentZ] then
                                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftWaterZonesHasFriendlyTorps][AiBotMap.tWaterZoneBySegment[iSegmentX][iSegmentZ]] = true
                            end
                        end
                        if oUnit[AiBotUnitInfo.refbSpecialMicroActive] or oUnit[refbBomberUsingMexHunterLogic] then
                            table.insert(tInUseUnits, oUnit)
                            if bDebugMessages == true then LOG(sFunctionRef..': Special micro is active or doing bomber special logic') end
                        else
                            local tLastOrder = oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]]
                            local oExistingValidAttackTarget
                            if oUnit[refoStrikeDamageAssigned] then
                                if AiBotUnitInfo.IsUnitValid(oUnit[refoStrikeDamageAssigned]) then oExistingValidAttackTarget = oUnit[refoStrikeDamageAssigned] end
                            elseif oUnit[refoAirAACurTarget] then
                                if AiBotUnitInfo.IsUnitValid(oUnit[refoAirAACurTarget]) then oExistingValidAttackTarget = oUnit[refoAirAACurTarget] end
                            elseif tLastOrder and tLastOrder[AiBotOrders.subrefoOrderUnitTarget] and (tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack or tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueGroundAttack) and AiBotUnitInfo.IsUnitValid(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) then
                                oExistingValidAttackTarget = tLastOrder[AiBotOrders.subrefoOrderUnitTarget]
                            end

                            --Gunship projectile logic - update table/flag
                            if oUnit[AiBotUnitInfo.refbProjectilesMeanShouldRefuel] then
                                local iTotalDamage = 0
                                if AiBotUtilities.IsTableEmpty(oUnit[AiBotUnitInfo.reftoEnemyProjectiles]) == false then
                                    for iCurProjectile = table.getn(oUnit[AiBotUnitInfo.reftoEnemyProjectiles]), 1, -1 do
                                        local oCurProjectile = oUnit[AiBotUnitInfo.reftoEnemyProjectiles][iCurProjectile]
                                        if oCurProjectile:BeenDestroyed() then
                                            table.remove(oUnit[AiBotUnitInfo.reftoEnemyProjectiles], iCurProjectile)
                                        else
                                            iTotalDamage = iTotalDamage + (oCurProjectile.DamageData.DamageAmount or 0)
                                        end
                                    end
                                end
                                if iTotalDamage == 0 then
                                    --Are we low health?
                                    if AiBotUnitInfo.GetUnitHealthPercent(oUnit) > iProjectileLowHealthThreshold then
                                        oUnit[AiBotUnitInfo.refbProjectilesMeanShouldRefuel] = false
                                    end
                                end
                            end

                            if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Is unit attached='..tostring(oUnit:IsUnitState('Attached'))..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; LastOrder type='..(tLastOrder[AiBotOrders.subrefiOrderType] or 'nil')..'; subreftOrderPosition='..repru(tLastOrder[AiBotOrders.subreftOrderPosition] or {'nil'})..'; subrefoOrderUnitTarget='..(tLastOrder[AiBotOrders.subrefoOrderUnitTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) or 'nil')..'; Is oExistingValidAttackTarget valid='..tostring(AiBotUnitInfo.IsUnitValid(oExistingValidAttackTarget))..'; refoStrikeDamageAssigned='..(oUnit[refoStrikeDamageAssigned].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(refoStrikeDamageAssigned) or 'nil')) end
                            if oUnit:IsUnitState('Attached') then
                                --Clear any orders it might have as it is refueling
                                if tLastOrder and tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderRefuel then
                                    AiBotOrders.IssueTrackedClearCommands(oUnit)
                                end
                                table.insert(tInUseUnits, oUnit)
                            elseif tLastOrder and tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderRefuel and AiBotUnitInfo.IsUnitValid(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) and (not(EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA, oUnit.UnitId)) or oUnit:GetFuelRatio() <= iLowFuelThreshold + 0.25 or not(AiBotUnitInfo.IsUnitValid(tLastOrder[AiBotOrders.subrefoOrderUnitTarget])) or AiBotUtilities.GetDistanceBetweenPositions(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]:GetPosition(), oUnit:GetPosition()) <= 150 or oUnit[refiProjectileHealthOverridePercent] or AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= iLowHealthThreshold + 0.1 or (oUnit[refiProjectileHealthOverridePercent] and iLowHealthThreshold < oUnit[refiProjectileHealthOverridePercent] and AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= oUnit[refiProjectileHealthOverridePercent] + 0.1)) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Unit is already on its way to refuel so will treat as being in use, unit health percent='..AiBotUnitInfo.GetUnitHealthPercent(oUnit)..'; Unit fuel percent='..oUnit:GetFuelRatio()..'; Dist to refuel target='..AiBotUtilities.GetDistanceBetweenPositions(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]:GetPosition(), oUnit:GetPosition())) end
                                --Unit on its way to refuel
                                table.insert(tInUseUnits, oUnit)
                                --Also update unit orders in case something has happened so next cycle it will try again
                                AiBotOrders.UpdateRecordedOrders(oUnit)
                                --Torp bombers and bombers - treat as unavailable if are targeting a valid unit that is on land (bomber) or water (torp bomber) and are close to it (within 90); for bombers also consider ground attacks simialr to unit targets
                            elseif tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueGroundAttack and (tLastOrder[AiBotOrders.subrefoOrderUnitTarget] and not(AiBotUnitInfo.IsUnitValid(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]))) then
                                if bDebugMessages == true then LOG(sFunctionRef..' Unit with ground attack order was linked to target that is dead so will be made available') end
                                table.insert(tAvailableUnits, oUnit)
                            elseif (tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueGroundAttack and tLastOrder[AiBotOrders.subreftOrderPosition] and AiBotUtilities.GetDistanceBetweenPositions(tLastOrder[AiBotOrders.subreftOrderPosition], oUnit:GetPosition()) <= 90)
                                    or (oExistingValidAttackTarget and ( (EntityCategoryContains(AiBotUnitInfo.refCategoryTorpBomber, oUnit.UnitId) and (AiBotMap.GetWaterZoneFromPosition(oExistingValidAttackTarget:GetPosition()) or 0) > 0) or (EntityCategoryContains(AiBotUnitInfo.refCategoryBomber, oUnit.UnitId) and not(AiBotUnitInfo.IsUnitUnderwater(oExistingValidAttackTarget)))) and AiBotUtilities.GetDistanceBetweenPositions(oExistingValidAttackTarget:GetPosition(), oUnit:GetPosition()) <= 90) then
                                AiBotOrders.UpdateRecordedOrders(oUnit)
                                if bDebugMessages == true then LOG(sFunctionRef..': Have bomber or torp bomber with valid last attack target that is relatively nearby, dist to target='..AiBotUtilities.GetDistanceBetweenPositions( tLastOrder[AiBotOrders.subreftOrderPosition], oUnit:GetPosition())..'; angle to target='..AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(),  tLastOrder[AiBotOrders.subreftOrderPosition])..'; Unit facing direction='..AiBotUnitInfo.GetUnitFacingAngle(oUnit)..'; Speed='..AiBotUnitInfo.GetUnitSpeed(oUnit)..'; Time since last fired bomb='..GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastBombFired] or 0)..'; refiTimeBetweenBombs='..(oUnit[AiBotUnitInfo.refiTimeBetweenBombs] or 'nil')) end
                                --Ahwassa - had a rare issue where given a target that is outside its range, it flies straight towards it and never drops its bomb; based on logs of the distance it is when at full speed and the typical speed per the (unreliable) getunitspeed function, the below should hopefully catch cases where it isn't firing early enough that it is of some benefit, without badly affecting too many normal cases and causing the bomb to not fire due to the redndancy
                                if oUnit.UnitId == 'xsa0402' and (oUnit[AiBotUnitInfo.refiBomberRange] or 0) >= 80 and AiBotUtilities.IsTableEmpty(tLastOrder[AiBotOrders.subreftOrderPosition]) == false and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLastOrder[AiBotOrders.subreftOrderPosition]) <= 64 and AiBotUnitInfo.GetUnitSpeed(oUnit) >= 17.5 and GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastBombFired] or 0) > oUnit[AiBotUnitInfo.refiTimeBetweenBombs] + 2 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Doesnt look like ahwassa is going to drop its bomb so will treat sa available again') end
                                    table.insert(tAvailableUnits, oUnit)
                                    --Strats - if are close to the enemy target and havent fired then assume terrain prevented us
                                elseif oExistingValidAttackTarget and EntityCategoryContains(AiBotUnitInfo.refCategoryBomber * categories.TECH3, oUnit.UnitId) and GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastBombFired] or 0) > (oUnit[AiBotUnitInfo.refiTimeBetweenBombs] or 0) + 1 and AiBotUtilities.bFAFActive and not(oUnit[AiBotUnitInfo.refbEasyBrain]) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oExistingValidAttackTarget:GetPosition()) <= math.min(30, (oUnit[AiBotUnitInfo.refiBomberRange] or 30) * 0.5) and VDist3(oUnit:GetPosition(), oExistingValidAttackTarget:GetPosition()) <= (oUnit[AiBotUnitInfo.refiBomberRange] or 30) - 10 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Strat bomber appears to have failed to launch bomb at target, will tyr hoverbombing instead, oUnit (bomber)='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; oExistingValidAttackTarget='..oExistingValidAttackTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oExistingValidAttackTarget)..'; Time='..GetGameTimeSeconds()) end
                                    ForkThread(AiBotMicro.T1OrT3HoverBombTarget, oUnit, oExistingValidAttackTarget, false, false, false)
                                else
                                    table.insert(tInUseUnits, oUnit)
                                end
                                --[[elseif tLastOrder and tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderUnloadTransport then
                                table.insert(tInUseUnits, oUnit)
                                oUnit[refiEngisWanted] = 0
                                AiBotOrders.UpdateRecordedOrders(oUnit)--]]
                            else
                                --Bombers - remove any assigned strike damage; AirAA - still treat as available
                                if oExistingValidAttackTarget then
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryBomber + AiBotUnitInfo.refCategoryTorpBomber, oUnit.UnitId) then
                                        RemoveAssignedAttacker(oExistingValidAttackTarget, oUnit)
                                    end
                                end

                                --AirAA with a combat target that it is near - add to special logic table (as will need to consider updating its move order)
                                if oExistingValidAttackTarget and EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA, oUnit.UnitId) and IsAirUnitInCombat(oUnit, iTeam) then
                                    table.insert(tSpecialLogicUnits, oUnit)
                                    if bDebugMessages == true then LOG(sFunctionRef..': AirAA unit is in combat so added it to table of special logic units, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; oUnit.Dead='..tostring(oUnit.Dead or false)) end
                                else
                                    bProceed = true
                                    --Transports - treat as unavailable if have a target island or WZ drop point and are close to it
                                    if oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderUnloadTransport then
                                        if oUnit[refbEmergencyDropActive] and AiBotUtilities.IsTableEmpty(oUnit:GetCargo()) == false then
                                            bProceed = false
                                            table.insert(tInUseUnits, oUnit)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Transport doign emergency drop so including in table of in use units') end
                                        elseif (oUnit[refiTargetZoneForDrop] or oUnit[refiTargetIslandForDrop]) and AiBotUtilities.IsTableEmpty(oUnit:GetCargo()) == false then
                                            --Are we close to the destination?
                                            local tOrderTarget = oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition]
                                            if tOrderTarget then
                                                local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tOrderTarget)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Dist to target='..iDistToTarget..'; Combat drop='..tostring(oUnit[refbCombatDrop] or false)) end
                                                if iDistToTarget <= 30 or (iDistToTarget <= 60 and oUnit[refbCombatDrop]) then
                                                    bProceed = false
                                                    table.insert(tInUseUnits, oUnit)
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding to table of in use units') end
                                                    --Update orders
                                                    AiBotOrders.UpdateRecordedOrders(oUnit)
                                                end
                                            end
                                        end
                                    end
                                    if bProceed then

                                        bSendUnitForRefueling = false
                                        --Consider if want to send unit to refuel
                                        if not(EntityCategoryContains(categories.CANNOTUSEAIRSTAGING + categories.EXPERIMENTAL, oUnit.UnitId)) then
                                            if oUnit[AiBotUnitInfo.refbProjectilesMeanShouldRefuel] then
                                                bSendUnitForRefueling = true
                                                if bDebugMessages == true then LOG(sFunctionRef..': Unit is expecting to take damage from projectiles so will send for refueling') end
                                            else
                                                if oUnit.GetFuelRatio then
                                                    iFuelPercent = oUnit:GetFuelRatio()
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Unit fuel ratio='..iFuelPercent) end
                                                else iFuelPercent = 1
                                                end
                                                if iFuelPercent < iLowFuelThreshold and iFuelPercent >= 0 then
                                                    --Send unit to refuel unless it is attacking a nearby enemy and isnt a gunship
                                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryGunship, oUnit.UnitId) or not(IsAirUnitInCombat(oUnit, iTeam)) then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Unit has low fuel so will send for refueling') end
                                                        bSendUnitForRefueling = true
                                                    end
                                                else
                                                    iHealthPercent = AiBotUnitInfo.GetUnitHealthPercent(oUnit)
                                                    if iHealthPercent <= iLowHealthThreshold or (oUnit[refiProjectileHealthOverridePercent] and iHealthPercent <= oUnit[refiProjectileHealthOverridePercent]) then
                                                        if EntityCategoryContains(AiBotUnitInfo.refCategoryGunship, oUnit.UnitId) or not(IsAirUnitInCombat(oUnit, iTeam)) then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Unit has low health so will send to refuel') end
                                                            bSendUnitForRefueling = true
                                                        end
                                                    elseif iHealthPercent <= 0.75 and oUnit[AiBotUnitInfo.refiHealthSecondLastCheck] and EntityCategoryContains(AiBotUnitInfo.refCategoryGunship, oUnit.UnitId) then
                                                        --Gunships - send for refueling if expect to be below 55% health soon, based on how much our health has decreased
                                                        if (oUnit:GetHealth() - (oUnit[AiBotUnitInfo.refiHealthSecondLastCheck] - oUnit:GetHealth())) / oUnit:GetMaxHealth() <= iLowHealthThreshold or (oUnit[refiProjectileHealthOverridePercent] and (oUnit[refiProjectileHealthOverridePercent] > iLowHealthThreshold and (oUnit:GetHealth() - (oUnit[AiBotUnitInfo.refiHealthSecondLastCheck] - oUnit:GetHealth())) / oUnit:GetMaxHealth() <= oUnit[refiProjectileHealthOverridePercent])) then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Gunship health is getting low and expected to drop below the low health threshold soon so will refuel') end
                                                            bSendUnitForRefueling = true
                                                        end
                                                    end
                                                end
                                            end
                                        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryGunship * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryCzar, oUnit.UnitId) then
                                            --If have shield but its health is low then send for refueling
                                            local iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit, false)
                                            if iMaxShield > 0 and iCurShield <= iMaxShield * 0.15 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Unit has low shield so will send to recharge') end
                                                bSendUnitForRefueling = true
                                            elseif iMaxShield == 0 then
                                                if not(oUnit[refiProjectileHealthOverridePercent]) then
                                                    local iHealthRegen = AiBotUnitInfo.GetUnitHealthRegenRate(oUnit)
                                                    oUnit[refiProjectileHealthOverridePercent] = 0.2
                                                    if iHealthRegen >= 50 then oUnit[refiProjectileHealthOverridePercent] = 0.3 end
                                                end
                                                local iExpHealthThreshold = oUnit[refiProjectileHealthOverridePercent]
                                                if oUnit[AiBotUnitInfo.refbWantToHealUp] then
                                                    iExpHealthThreshold = math.max(0.5, oUnit[refiProjectileHealthOverridePercent])
                                                end

                                                if AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= iExpHealthThreshold then
                                                    bSendUnitForRefueling = true
                                                    oUnit[AiBotUnitInfo.refbWantToHealUp] = true
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Unit low health so want it to try and heal up') end
                                                else
                                                    oUnit[AiBotUnitInfo.refbWantToHealUp] = nil
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': iHealthRegen='..AiBotUnitInfo.GetUnitHealthRegenRate(oUnit)..'; iExpHealthThreshold='..iExpHealthThreshold) end
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': iCurShield='..iCurShield..'; iMaxShield='..iMaxShield..'; bSendUnitForRefueling='..tostring(bSendUnitForRefueling)) end
                                        else
                                            if EntityCategoryContains(AiBotUnitInfo.refCategoryTransport, oUnit.UnitId) and oUnit:GetFuelRatio() < iLowFuelThreshold and (oUnit:GetFuelRatio() < 0.05 or AiBotUtilities.IsTableEmpty(oUnit:GetCargo())) then
                                                bSendUnitForRefueling = true --will unload and ctrl-K transports that are low on fuel
                                            end
                                        end

                                        if bDebugMessages == true then LOG(sFunctionRef..': bSendUnitForRefueling='..tostring(bSendUnitForRefueling or false)..'; bIncludeBombersInSpecialLogic='..tostring(bIncludeBombersInSpecialLogic or false)) end
                                        if bSendUnitForRefueling then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Unit will be sent for refueling') end
                                            table.insert(tUnitsForRefueling, oUnit)
                                        else
                                            --Unit is available
                                            if (bIncludeBombersInSpecialLogic or AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 1) and EntityCategoryContains(AiBotUnitInfo.refCategoryBomber * categories.TECH1, oUnit.UnitId) then
                                                table.insert(tSpecialLogicUnits, oUnit)
                                            else
                                                if bDebugMessages == true then LOG(sFunctionRef..' Unit will be made available') end
                                                table.insert(tAvailableUnits, oUnit)
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then
        LOG(sFunctionRef..': End of code, is tAvailableUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableUnits))..'; Is tUnitsForRefueling empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsForRefueling))..'; Is tInUseUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tInUseUnits)))
        if AiBotUtilities.IsTableEmpty(tUnitsForRefueling) == false then
            for iUnit, oUnit in tUnitsForRefueling do
                LOG(sFunctionRef..': Units for refueling '..iUnit..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit))
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    return tAvailableUnits, tUnitsForRefueling, tInUseUnits, tSpecialLogicUnits
end

function GetRallyPointValueOfLandZone(iTeam, tLZData, tLZTeamData, iPlateau, tOptionalLRAirAAUnitsToAvoid)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetRallyPointValueOfLandZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iCurAAValue
    local iCurFactor = 1
    if tLZTeamData[AiBotMap.subrefbDangerousEnemiesInAdjacentWZ] or tLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then iCurFactor = 0.5 end
    iCurAAValue = (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) * iCurFactor - (tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) * 4 - (tLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)
    --Factor in adjacent threat
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
            iCurAAValue = iCurAAValue - (tAdjLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) * 2 - (tAdjLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)
        end
    end
    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
        local iAdjPond, iAdjWaterZone
        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
            iAdjWaterZone = tSubtable[AiBotMap.subrefAWZRef]
            iAdjPond = AiBotMap.tiPondByWaterZone[iAdjWaterZone]
            local tAdjWZTeamData = AiBotMap.tPondDetails[iAdjPond][AiBotMap.subrefPondWaterZones][iAdjWaterZone][AiBotMap.subrefWZTeamData][iTeam]
            iCurAAValue = iCurAAValue - tAdjWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] * 2 - (tAdjWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)
        end
    end
    --Include LRAA threat
    if tOptionalLRAirAAUnitsToAvoid then
        for iLRAA, oLRAA in tOptionalLRAirAAUnitsToAvoid do
            if AiBotUtilities.GetDistanceBetweenPositions(oLRAA:GetPosition(), tLZData[AiBotMap.subrefMidpoint]) <= oLRAA[AiBotUnitInfo.refiAARange] + 25 then
                if AiBotUtilities.bCPUPerformanceMode then
                    iCurAAValue = iCurAAValue - (oLRAA[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oLRAA))
                else
                    iCurAAValue = iCurAAValue - AiBotUnitInfo.GetAirThreatLevel({ oLRAA }, true, true, false, false, false, false)
                end
            end
        end
    end

    if iCurAAValue >= 0 and tLZTeamData[AiBotMap.subrefLZFortify] then iCurAAValue = math.max(iCurAAValue + 3000, iCurAAValue * 3) end


    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iCurAAValue
end
function GetRallyPointValueOfWaterZone(iTeam, tWZData, tWZTeamData, tOptionalLRAirAAUnitsToAvoid)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetRallyPointValueOfWaterZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iCurAAValue
    local iCurFactor = 1
    if tWZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentWZ] then iCurFactor = 0.5 end
    iCurAAValue = (tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) * iCurFactor - (tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) * 10 - (tWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) * 6
    --Factor in adjacent threat
    if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefAdjacentLandZones]) == false then
        for iEntry, tSubtable in tWZData[AiBotMap.subrefAdjacentLandZones] do
            local tAdjLZTeamData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]][AiBotMap.subrefLZTeamData][iTeam]
            iCurAAValue = iCurAAValue - (tAdjLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) * 5 - (tWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) * 3
        end
    end
    if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
        local iAdjPond
        for iEntry, iAdjWaterZone in tWZData[AiBotMap.subrefWZAdjacentWaterZones] do
            iAdjPond = AiBotMap.tiPondByWaterZone[iAdjWaterZone]
            local tAdjWZTeamData = AiBotMap.tPondDetails[iAdjPond][AiBotMap.subrefPondWaterZones][iAdjWaterZone][AiBotMap.subrefWZTeamData][iTeam]
            iCurAAValue = iCurAAValue - tAdjWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] * 5 - (tWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) * 3
        end
    end
    --Include LRAA threat
    if tOptionalLRAirAAUnitsToAvoid then
        for iLRAA, oLRAA in tOptionalLRAirAAUnitsToAvoid do
            if AiBotUtilities.GetDistanceBetweenPositions(oLRAA:GetPosition(), tWZData[AiBotMap.subrefMidpoint]) <= oLRAA[AiBotUnitInfo.refiAARange] + 25 then
                if AiBotUtilities.bCPUPerformanceMode then
                    iCurAAValue = iCurAAValue + (oLRAA[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oLRAA))
                else
                    iCurAAValue = iCurAAValue + AiBotUnitInfo.GetAirThreatLevel({ oLRAA }, true, true, false, false, false, false)
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iCurAAValue
end

function IsThereAAInZone(tLZOrWZTeamData, bIgnoreAirAA, iGroundAAThreatThreshold, iAirAAThreatThreshold, bAddEnemyGroundAAToAirAAThreat, tOptionalDetailedGroundAAPositionCheck, iIncludeForDetailedIfWithinThisDistOfBeingInRange)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'IsThereAAInZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Too much AirAA threat?
    if not(bIgnoreAirAA) and (iAirAAThreatThreshold or 0) > 0 and (tLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) > 0 then
        if tLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] >= math.max(40, (iAirAAThreatThreshold or 0) + (tLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) * 0.5) then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        elseif bAddEnemyGroundAAToAirAAThreat and (tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) > 0 and iAirAAThreatThreshold and tLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] + tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] * 3 > iAirAAThreatThreshold then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        end
    end
    --Too much groundAA threat?
    -- -1 groundAA threat threshold means infinite
    if ((iGroundAAThreatThreshold or 0) >= 0 and (tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) > (iGroundAAThreatThreshold or 0)) then
        if tOptionalDetailedGroundAAPositionCheck then
            if not(iIncludeForDetailedIfWithinThisDistOfBeingInRange) then
                AiBotUtilities.ErrorHandler('Havent specified iIncludeForDetailedIfWithinThisDistOfBeingInRange, will return true')
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return true
            else
                local toGroundAAInRange = {}
                if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                    for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits] do
                        if not(oUnit.Dead) and (oUnit[AiBotUnitInfo.refiAARange] or 0) > 0 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering AA oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Dist to detailed position check='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tOptionalDetailedGroundAAPositionCheck)..'; AA range='..oUnit[AiBotUnitInfo.refiAARange]..'; CLose enough='..tostring(AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tOptionalDetailedGroundAAPositionCheck) - oUnit[AiBotUnitInfo.refiAARange] <= iIncludeForDetailedIfWithinThisDistOfBeingInRange)) end
                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tOptionalDetailedGroundAAPositionCheck) - oUnit[AiBotUnitInfo.refiAARange] <= iIncludeForDetailedIfWithinThisDistOfBeingInRange then
                                table.insert(toGroundAAInRange, oUnit)
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy groundAA in range='..AiBotUnitInfo.GetAirThreatLevel(toGroundAAInRange, true, false, true, false, false, false)..'; iGroundAAThreatThreshold='..iGroundAAThreatThreshold) end
                    if AiBotUtilities.IsTableEmpty(toGroundAAInRange) == false and AiBotUnitInfo.GetAirThreatLevel(toGroundAAInRange, true, false, true, false, false, false) >= iGroundAAThreatThreshold then
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        return true
                    end
                end
            end
        else
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function CalculateAirTravelPath(iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone)
    --Plateau refs should be 0 if dealing with a water zone
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'CalculateAirTravelPath'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time '..GetGameTimeSeconds()..'; iStartPlateauOrZero='..(iStartPlateauOrZero or 'nil')..'; iStartLandOrWaterZone='..(iStartLandOrWaterZone or 'nil')..'; iEndPlateauOrZero='..(iEndPlateauOrZero or 'nil')..'; iEndLandOrWaterZone='..(iEndLandOrWaterZone or 'nil')..'; Is tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone][iEndPlateauOrZero][iEndLandOrWaterZone] nil='..tostring(tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone][iEndPlateauOrZero][iEndLandOrWaterZone] == nil)) end

    if not(tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone][iEndPlateauOrZero][iEndLandOrWaterZone]) then
        --AiBotProfiler.FunctionProfiler(sFunctionRef..': TabSetup', AiBotProfiler.refProfilerStart)
        if not(tAirZonePathingFromZoneToZone[iStartPlateauOrZero]) then tAirZonePathingFromZoneToZone[iStartPlateauOrZero] = {} end
        if not(tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone]) then tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone] = {} end
        if not(tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone]) then tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone] = {} end
        if not(tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone][iEndPlateauOrZero]) then tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone][iEndPlateauOrZero] = {} end
        --AiBotProfiler.FunctionProfiler(sFunctionRef..': TabSetup', AiBotProfiler.refProfilerEnd)

        --Do we already have the path in the opposite direction?
        if bDebugMessages == true then LOG(sFunctionRef..': Do we already have pathing in the opposite direction? Is tAirZonePathingFromZoneToZone[iEndPlateauOrZero][iEndLandOrWaterZone][iStartPlateauOrZero][iStartLandOrWaterZone] nil='..tostring(tAirZonePathingFromZoneToZone[iEndPlateauOrZero][iEndLandOrWaterZone][iStartPlateauOrZero][iStartLandOrWaterZone] == nil)) end
        if AiBotUtilities.IsTableEmpty(tAirZonePathingFromZoneToZone[iEndPlateauOrZero][iEndLandOrWaterZone][iStartPlateauOrZero][iStartLandOrWaterZone]) == false then
            --AiBotProfiler.FunctionProfiler(sFunctionRef..': TabMirror', AiBotProfiler.refProfilerStart)
            if bDebugMessages == true then LOG(sFunctionRef..': Will use pathing in opposite direction,='..repru(tAirZonePathingFromZoneToZone[iEndPlateauOrZero][iEndLandOrWaterZone][iStartPlateauOrZero][iStartLandOrWaterZone])) end
            tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone][iEndPlateauOrZero][iEndLandOrWaterZone] = tAirZonePathingFromZoneToZone[iEndPlateauOrZero][iEndLandOrWaterZone][iStartPlateauOrZero][iStartLandOrWaterZone]

            --AiBotProfiler.FunctionProfiler(sFunctionRef..': TabMirror', AiBotProfiler.refProfilerEnd)
        else
            AiBotProfiler.FunctionProfiler(sFunctionRef..': Detail', AiBotProfiler.refProfilerStart)
            tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone][iEndPlateauOrZero][iEndLandOrWaterZone] = {} --need here not above or else we end up thinking there is an entry already

            --Determine the path - move in a straight line from the start point towards the end point in periodic intervals, checking for the zones to include
            local tiLandZonesByPlateau = {}
            local tiWaterZones = {}
            local tStart
            local tStartLZOrWZData
            if iStartPlateauOrZero > 0 then
                --Dealing with land zone
                tStartLZOrWZData = AiBotMap.tAllPlateaus[iStartPlateauOrZero][AiBotMap.subrefPlateauLandZones][iStartLandOrWaterZone]
                tStart = tStartLZOrWZData[AiBotMap.subrefMidpoint]
                tiLandZonesByPlateau[iStartPlateauOrZero] = {}
                tiLandZonesByPlateau[iStartPlateauOrZero][iStartLandOrWaterZone] = true
            else
                --Dealing with water zone
                tStartLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iStartLandOrWaterZone]
                tStart = tStartLZOrWZData[AiBotMap.subrefMidpoint]
                tiWaterZones[iStartLandOrWaterZone] = true
            end
            local tEnd
            if iEndPlateauOrZero > 0 then
                --Dealing with land zone
                tEnd = AiBotMap.tAllPlateaus[iEndPlateauOrZero][AiBotMap.subrefPlateauLandZones][iEndLandOrWaterZone][AiBotMap.subrefMidpoint]
                tiLandZonesByPlateau[iEndPlateauOrZero] = {}
                tiLandZonesByPlateau[iEndPlateauOrZero][iEndLandOrWaterZone] = true
            else
                --Dealing with water zone
                tEnd = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iEndLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iEndLandOrWaterZone][AiBotMap.subrefMidpoint]
                tiWaterZones[iEndLandOrWaterZone] = true
            end
            if bDebugMessages == true then LOG(sFunctionRef..': tStart='..repru(tStart)..'; tEnd='..repru(tEnd)) end
            local iAngleStartToEnd = AiBotUtilities.GetAngleFromAToB(tStart, tEnd)
            local iSearchInterval = 15
            local iSearchDistance = math.floor(AiBotUtilities.GetDistanceBetweenPositions(tStart, tEnd) / iSearchInterval) * iSearchInterval
            local iMaxCycle = math.max(1, iSearchDistance / iSearchInterval)
            local iCurPlateau, iCurLandZone, iCurWaterZone, iCurSegmentX, iCurSegmentZ
            local iSidewaysDistance = 100 --tried with 65 and were ignoring LZ that had nearby enemy AirAA
            local iBackupSidewaysDistance = 70 --For land zones - in addition to checking adjacent zones will also check this far away
            local iSidewaysSegmentDistance = math.ceil(iSidewaysDistance / AiBotMap.iLandZoneSegmentSize)
            local iSidewaysPlateauOrZero, iSidewaysZone
            local bIncludeMinorPlateaus = true
            if AiBotMap.iPlateauCount >= 500 then bIncludeMinorPlateaus = false end
            if bDebugMessages == true then LOG(sFunctionRef..': Considering iStartPlateauOrZero='..iStartPlateauOrZero..'; iStartLandOrWaterZone='..iStartLandOrWaterZone..'; iEndPlateauOrZero='..iEndPlateauOrZero..'; iEndLandOrWaterZone='..iEndLandOrWaterZone..'; iSearchDistance='..iSearchDistance..'; iSidewaysSegmentDistance='..iSidewaysSegmentDistance..'; iAngleStartToEnd='..iAngleStartToEnd..'; iMaxCycle='..iMaxCycle) end
            if iSearchDistance > 0 then
                for iCycle = 0, iMaxCycle, 1 do
                    local tPositionAlongPath = AiBotUtilities.MoveInDirection(tStart, iAngleStartToEnd, iCycle * iSearchInterval, true, false, false)
                    iCurPlateau, iCurLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tPositionAlongPath)
                    if bDebugMessages == true then
                        LOG(sFunctionRef..': tPositionAlongPath='..repru(tPositionAlongPath)..'; iCurPlateau='..(iCurPlateau or 'nil')..'; iCurLandZone='..(iCurLandZone or 'nil')..'; Waterzonebyposition='..(AiBotMap.GetWaterZoneFromPosition(tPositionAlongPath) or 'nil'))
                        AiBotUtilities.DrawLocation(tPositionAlongPath)
                    end
                    if (iCurPlateau or 0) > 0 and (bIncludeMinorPlateaus or not(AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefbMinorPlateau])) then
                        if (iCurLandZone or 0) > 0 then
                            if not(tiLandZonesByPlateau[iCurPlateau]) then tiLandZonesByPlateau[iCurPlateau] = {} end
                            tiLandZonesByPlateau[iCurPlateau][iCurLandZone] = true
                            --Add any adjacent land zones or water zones if their min/max would get within iSidewaysDistance of here
                            local tBaseLZData = AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iCurLandZone]
                            --If we consider adjacent land zones are there any near to tPositionAlongPath?
                            iCurSegmentX, iCurSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tPositionAlongPath)
                            if AiBotUtilities.IsTableEmpty(tBaseLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                for iEntry, iAdjLZ in tBaseLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                    local tAdjLZ = AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                    --If draw a square around the land zone, based in segments, do we come within iSidewaysSegmentDistance of this?
                                    if iCurSegmentX >= tAdjLZ[AiBotMap.subrefLZMinSegX] - iSidewaysSegmentDistance and iCurSegmentX <= tAdjLZ[AiBotMap.subrefLZMaxSegX] + iSidewaysSegmentDistance
                                            and iCurSegmentZ >= tAdjLZ[AiBotMap.subrefLZMinSegZ] - iSidewaysSegmentDistance and iCurSegmentZ <= tAdjLZ[AiBotMap.subrefLZMaxSegZ] + iSidewaysSegmentDistance then
                                        --Are near enough, so include this LZ
                                        tiLandZonesByPlateau[iCurPlateau][iAdjLZ] = true
                                    end
                                end
                            end

                            --Do similar for water zones
                            if AiBotUtilities.IsTableEmpty(tBaseLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                                for iEntry, tSubtable in tBaseLZData[AiBotMap.subrefAdjacentWaterZones] do
                                    local iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                                    local tAdjWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ]
                                    if iCurSegmentX >= tAdjWZData[AiBotMap.subrefWZMinSegX] - iSidewaysSegmentDistance and iCurSegmentX <= tAdjWZData[AiBotMap.subrefWZMaxSegX] + iSidewaysSegmentDistance
                                            and iCurSegmentZ >= tAdjWZData[AiBotMap.subrefWZMinSegZ] - iSidewaysSegmentDistance and iCurSegmentZ <= tAdjWZData[AiBotMap.subrefWZMaxSegZ] + iSidewaysSegmentDistance then
                                        --Are near enough, so include this WZ
                                        tiWaterZones[iAdjWZ] = true
                                    end
                                end
                            end
                        else
                            iCurWaterZone = AiBotMap.GetWaterZoneFromPosition(tPositionAlongPath)
                            if bDebugMessages == true then LOG(sFunctionRef..': tPositionAlongPath='..repru(tPositionAlongPath)..'; iCurWaterZone='..(iCurWaterZone or 'nil')..'; iCycle='..iCycle..'; tiWaterZones[iCurWaterZone]='..tostring((tiWaterZones[iCurWaterZone] or false))) end
                            if (iCurWaterZone or 0) > 0 then
                                tiWaterZones[iCurWaterZone] = true
                                --If we consider adjacent land zones are there any near to tPositionAlongPath?
                                local tBaseWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurWaterZone]][AiBotMap.subrefPondWaterZones][iCurWaterZone]
                                iCurSegmentX, iCurSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tPositionAlongPath)
                                if bDebugMessages == true then LOG(sFunctionRef..': is table of adjacent land zones empty='..tostring(AiBotUtilities.IsTableEmpty(tBaseWZData[AiBotMap.subrefAdjacentLandZones]))..'; is table of adjacent water zones empty='..tostring(AiBotUtilities.IsTableEmpty(tBaseWZData[AiBotMap.subrefWZAdjacentWaterZones]))) end
                                if AiBotUtilities.IsTableEmpty(tBaseWZData[AiBotMap.subrefAdjacentLandZones]) == false then
                                    for iEntry, tSubtable in tBaseWZData[AiBotMap.subrefAdjacentLandZones] do
                                        local iAdjPlateau = tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]
                                        local iAdjLZ = tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]
                                        local tAdjLZ = AiBotMap.tAllPlateaus[iAdjPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                        --If draw a square around the land zone, based in segments, do we come within iSidewaysSegmentDistance of this?
                                        if bDebugMessages == true then LOG(sFunctionRef..': iAdjLZ='..(iAdjLZ or 'nil')..'; iAdjPlateau='..(iAdjPlateau or 'nil')..'; iCurSegmentX='..iCurSegmentX..'; iCurSegmentZ='..iCurSegmentZ..'; tAdjLZ[AiBotMap.subrefLZMinSegX]='..tAdjLZ[AiBotMap.subrefLZMinSegX]..'; tAdjLZ[AiBotMap.subrefLZMaxSegX]='..tAdjLZ[AiBotMap.subrefLZMaxSegX]..'; tAdjLZ[AiBotMap.subrefLZMinSegZ]='..tAdjLZ[AiBotMap.subrefLZMinSegZ]..'; tAdjLZ[AiBotMap.subrefLZMaxSegZ]='..tAdjLZ[AiBotMap.subrefLZMaxSegZ]) end
                                        if iCurSegmentX >= tAdjLZ[AiBotMap.subrefLZMinSegX] - iSidewaysSegmentDistance and iCurSegmentX <= tAdjLZ[AiBotMap.subrefLZMaxSegX] + iSidewaysSegmentDistance
                                                and iCurSegmentZ >= tAdjLZ[AiBotMap.subrefLZMinSegZ] - iSidewaysSegmentDistance and iCurSegmentZ <= tAdjLZ[AiBotMap.subrefLZMaxSegZ] + iSidewaysSegmentDistance then
                                            --Are near enough, so include this LZ
                                            if not(tiLandZonesByPlateau[iAdjPlateau]) then tiLandZonesByPlateau[iAdjPlateau] = {} end
                                            tiLandZonesByPlateau[iAdjPlateau][iAdjLZ] = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': Including iAdjLZ='..iAdjLZ..' in the table of near enough land zones by plateau') end
                                        elseif bDebugMessages == true then LOG(sFunctionRef..': iAdjLZ '..iAdjLZ..' is too far away so wont include')
                                        end
                                    end
                                end
                                --Do similar for water zones
                                if AiBotUtilities.IsTableEmpty(tBaseWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                                    for iEntry, iAdjWZ in tBaseWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                                        local tAdjWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ]
                                        if bDebugMessages == true then LOG(sFunctionRef..': iAdjWZ='..(iAdjWZ or 'nil')..'; iCurSegmentX='..iCurSegmentX..'; iCurSegmentZ='..iCurSegmentZ..'; tAdjWZData[AiBotMap.subrefWZMinSegX]='..tAdjWZData[AiBotMap.subrefWZMinSegX]..'; tAdjWZData[AiBotMap.subrefWZMaxSegX]='..tAdjWZData[AiBotMap.subrefWZMaxSegX]..'; tAdjWZData[AiBotMap.subrefWZMinSegZ]='..tAdjWZData[AiBotMap.subrefWZMinSegZ]..'; tAdjWZData[AiBotMap.subrefWZMaxSegZ]='..tAdjWZData[AiBotMap.subrefWZMaxSegZ]) end
                                        if iCurSegmentX >= tAdjWZData[AiBotMap.subrefWZMinSegX] - iSidewaysSegmentDistance and iCurSegmentX <= tAdjWZData[AiBotMap.subrefWZMaxSegX] + iSidewaysSegmentDistance
                                                and iCurSegmentZ >= tAdjWZData[AiBotMap.subrefWZMinSegZ] - iSidewaysSegmentDistance and iCurSegmentZ <= tAdjWZData[AiBotMap.subrefWZMaxSegZ] + iSidewaysSegmentDistance then
                                            --Are near enough, so include this WZ
                                            tiWaterZones[iAdjWZ] = true
                                        end
                                    end
                                end
                            end
                        end
                    end
                    --Backup - also check for potentially further away land zones as sometimes can have a thin LZ adjacent to us meaning the other one that is nearby doesnt get considered (not such an issue for water zones given their size)
                    for iSidewaysAngleAdjust = -90, 90, 180 do
                        local tNearbySideways = AiBotUtilities.MoveInDirection(tPositionAlongPath, iAngleStartToEnd + iSidewaysAngleAdjust, iBackupSidewaysDistance, true, false, false)
                        if AiBotConditions.IsLocationInPlayableArea(tNearbySideways) then
                            if bDebugMessages == true then LOG(sFunctionRef..': tPositionAlongPath='..repru(tPositionAlongPath)..'; Angle='..iAngleStartToEnd + iSidewaysAngleAdjust..'; iBackupSidewaysDistance='..iBackupSidewaysDistance..'; tNearbySideways='..repru(tNearbySideways)..'; Playable area='..repru(AiBotMap.rMapPlayableArea)) end
                            iSidewaysPlateauOrZero, iSidewaysZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tNearbySideways)
                            if bDebugMessages == true then LOG(sFunctionRef..': Checking sideways points, iSidewaysAngleAdjust='..iSidewaysAngleAdjust..'; iSidewaysPlateauOrZero='..(iSidewaysPlateauOrZero or 'nil')..'; iSidewaysZone='..(iSidewaysZone or 'nil')) end
                            --Only include land zones (as water zones are much larger)
                            if (iSidewaysPlateauOrZero or 0) > 0 and (iSidewaysZone or 0) > 0 and (bIncludeMinorPlateaus or not(AiBotMap.tAllPlateaus[iSidewaysPlateauOrZero][AiBotMap.subrefbMinorPlateau])) then
                                if not(tiLandZonesByPlateau[iSidewaysPlateauOrZero]) then tiLandZonesByPlateau[iSidewaysPlateauOrZero] = {} end
                                tiLandZonesByPlateau[iSidewaysPlateauOrZero][iSidewaysZone] = true
                            end
                        end
                    end
                end
            else
                --E.g. if are trying to get the pathing around this particular zone - just include all adjacent zones in that case
                iCurSegmentX, iCurSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tStartLZOrWZData[AiBotMap.subrefMidpoint])
                if iStartPlateauOrZero == 0 then
                    --Dealing with water zone - include all adjacent land and water (ignore distance check) - want to use similar method to above to avoid cases where we include far more zones when re reach the target LZ/WZ than if we are appraoching it (which would lead to gunships aborting the attack and dying while doing nothing)
                    if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefAdjacentLandZones]) == false then
                        for iEntry, tSubtable in tStartLZOrWZData[AiBotMap.subrefAdjacentLandZones] do
                            local iAdjPlateau = tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]
                            local iAdjLZ = tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]
                            local tAdjLZ = AiBotMap.tAllPlateaus[iAdjPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                            --If draw a square around the land zone, based in segments, do we come within iSidewaysSegmentDistance of this?
                            if bDebugMessages == true then LOG(sFunctionRef..': iAdjLZ='..(iAdjLZ or 'nil')..'; iAdjPlateau='..(iAdjPlateau or 'nil')..'; iCurSegmentX='..iCurSegmentX..'; iCurSegmentZ='..iCurSegmentZ..'; tAdjLZ[AiBotMap.subrefLZMinSegX]='..tAdjLZ[AiBotMap.subrefLZMinSegX]..'; tAdjLZ[AiBotMap.subrefLZMaxSegX]='..tAdjLZ[AiBotMap.subrefLZMaxSegX]..'; tAdjLZ[AiBotMap.subrefLZMinSegZ]='..tAdjLZ[AiBotMap.subrefLZMinSegZ]..'; tAdjLZ[AiBotMap.subrefLZMaxSegZ]='..tAdjLZ[AiBotMap.subrefLZMaxSegZ]) end
                            if iCurSegmentX >= tAdjLZ[AiBotMap.subrefLZMinSegX] - iSidewaysSegmentDistance and iCurSegmentX <= tAdjLZ[AiBotMap.subrefLZMaxSegX] + iSidewaysSegmentDistance
                                    and iCurSegmentZ >= tAdjLZ[AiBotMap.subrefLZMinSegZ] - iSidewaysSegmentDistance and iCurSegmentZ <= tAdjLZ[AiBotMap.subrefLZMaxSegZ] + iSidewaysSegmentDistance then
                                --Are near enough, so include this LZ
                                if not(tiLandZonesByPlateau[iAdjPlateau]) then tiLandZonesByPlateau[iAdjPlateau] = {} end
                                tiLandZonesByPlateau[iAdjPlateau][iAdjLZ] = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Including iAdjLZ='..iAdjLZ..' in the table of near enough land zones by plateau') end
                            elseif bDebugMessages == true then LOG(sFunctionRef..': iAdjLZ '..iAdjLZ..' is too far away so wont include')
                            end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                        for iEntry, iAdjWZ in tStartLZOrWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                            local tAdjWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ]
                            if bDebugMessages == true then LOG(sFunctionRef..': Same start and end: iAdjWZ='..(iAdjWZ or 'nil')..'; iCurSegmentX='..iCurSegmentX..'; iCurSegmentZ='..iCurSegmentZ..'; tAdjWZData[AiBotMap.subrefWZMinSegX]='..tAdjWZData[AiBotMap.subrefWZMinSegX]..'; tAdjWZData[AiBotMap.subrefWZMaxSegX]='..tAdjWZData[AiBotMap.subrefWZMaxSegX]..'; tAdjWZData[AiBotMap.subrefWZMinSegZ]='..tAdjWZData[AiBotMap.subrefWZMinSegZ]..'; tAdjWZData[AiBotMap.subrefWZMaxSegZ]='..tAdjWZData[AiBotMap.subrefWZMaxSegZ]) end
                            if iCurSegmentX >= tAdjWZData[AiBotMap.subrefWZMinSegX] - iSidewaysSegmentDistance and iCurSegmentX <= tAdjWZData[AiBotMap.subrefWZMaxSegX] + iSidewaysSegmentDistance
                                    and iCurSegmentZ >= tAdjWZData[AiBotMap.subrefWZMinSegZ] - iSidewaysSegmentDistance and iCurSegmentZ <= tAdjWZData[AiBotMap.subrefWZMaxSegZ] + iSidewaysSegmentDistance then
                                --Are near enough, so include this WZ
                                tiWaterZones[iAdjWZ] = true
                            end
                        end
                    end
                else
                    --Dealing with start and end zone that are the same (if dist between htem is 0) - so only need to consider 1 point along path
                    iCurPlateau = iStartPlateauOrZero
                    iCurLandZone = iStartLandOrWaterZone
                    if not(tiLandZonesByPlateau[iCurPlateau]) then tiLandZonesByPlateau[iCurPlateau] = {} end
                    tiLandZonesByPlateau[iCurPlateau][iCurLandZone] = true
                    --Add any adjacent land zones or water zones if their min/max would get within iSidewaysDistance of here
                    --If we consider adjacent land zones are there any near to tPositionAlongPath?
                    if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for iEntry, iAdjLZ in tStartLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZ = AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                            --If draw a square around the land zone, based in segments, do we come within iSidewaysSegmentDistance of this?
                            if iCurSegmentX >= tAdjLZ[AiBotMap.subrefLZMinSegX] - iSidewaysSegmentDistance and iCurSegmentX <= tAdjLZ[AiBotMap.subrefLZMaxSegX] + iSidewaysSegmentDistance
                                    and iCurSegmentZ >= tAdjLZ[AiBotMap.subrefLZMinSegZ] - iSidewaysSegmentDistance and iCurSegmentZ <= tAdjLZ[AiBotMap.subrefLZMaxSegZ] + iSidewaysSegmentDistance then
                                --Are near enough, so include this LZ
                                tiLandZonesByPlateau[iCurPlateau][iAdjLZ] = true
                            end
                        end
                    end
                    --Do similar for water zones
                    if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                        for iEntry, tSubtable in tStartLZOrWZData[AiBotMap.subrefAdjacentWaterZones] do
                            local iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                            local tAdjWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ]
                            if iCurSegmentX >= tAdjWZData[AiBotMap.subrefWZMinSegX] - iSidewaysSegmentDistance and iCurSegmentX <= tAdjWZData[AiBotMap.subrefWZMaxSegX] + iSidewaysSegmentDistance
                                    and iCurSegmentZ >= tAdjWZData[AiBotMap.subrefWZMinSegZ] - iSidewaysSegmentDistance and iCurSegmentZ <= tAdjWZData[AiBotMap.subrefWZMaxSegZ] + iSidewaysSegmentDistance then
                                --Are near enough, so include this WZ
                                tiWaterZones[iAdjWZ] = true
                            end
                        end
                    end
                end
            end

            --Should now have tables of all land and water zones that come near the path from start to end; record all of these in a table
            local tBaseTableRef = tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone][iEndPlateauOrZero][iEndLandOrWaterZone]
            if bDebugMessages == true then LOG(sFunctionRef..': Finished calculating alnd and water zones in path, tiWaterZones='..repru(tiWaterZones)..'; tiLandZonesByPlateau='..repru(tiLandZonesByPlateau)) end
            if AiBotUtilities.IsTableEmpty(tiWaterZones) == false then
                tBaseTableRef[subreftWaterZonesInPath] = {}
                for iWaterZone, bIncluded in tiWaterZones do
                    table.insert(tBaseTableRef[subreftWaterZonesInPath], iWaterZone)
                end
            end
            if AiBotUtilities.IsTableEmpty(tiLandZonesByPlateau) == false then
                tBaseTableRef[subreftPlateauAndLandZonesInPath] = {}
                for iPlateau, tLandZones in tiLandZonesByPlateau do
                    for iLandZone, bIncluded in tLandZones do
                        table.insert(tBaseTableRef[subreftPlateauAndLandZonesInPath], {iPlateau, iLandZone})
                    end
                end
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef..': Detail', AiBotProfiler.refProfilerEnd)

            if bDebugMessages == true then LOG(sFunctionRef..': Finished updating tBaseTableRef, WaterZonesInPath='..repru(tBaseTableRef[subreftWaterZonesInPath])..'; Land zones in path='..repru(tBaseTableRef[subreftPlateauAndLandZonesInPath])) end
        end

        if bDebugMessages == true then LOG(sFunctionRef..': Finished calculating path, tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone][iEndPlateauOrZero][iEndLandOrWaterZone]='..repru(tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone][iEndPlateauOrZero][iEndLandOrWaterZone])) end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function IsThereNearbyAirAA(iTeam, iPlateau, iLandOrWaterZone, bIsWaterZone, iSearchDistance, iAirAAThreshold, tSearchPoint)
    --Intended for ahwassa (although could also work for gunships and bombers if wanted) - longer range airaa check
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'IsThereNearbyAirAA'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local tStartLZOrWZData, tStartLZOrWZTeamData
    if bIsWaterZone then
        tStartLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
        tStartLZOrWZTeamData = tStartLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
    else
        tStartLZOrWZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
        tStartLZOrWZTeamData = tStartLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
    end
    local iCumulativeAirAAThreat = (tStartLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)
    local bHaveAirAAWithinSearchDistance
    if iCumulativeAirAAThreat > 0 then
        if iCumulativeAirAAThreat > iAirAAThreshold then
            if bDebugMessages == true then LOG(sFunctionRef..': Large airaa threat in cur zone so will return true') end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        else
            bHaveAirAAWithinSearchDistance = true
        end
    end
    local iSimpleZoneSearchRadius = iSearchDistance + 60
    RecordOtherLandAndWaterZonesByDistance(tStartLZOrWZData)
    if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
        local iOtherPlateauOrZero, iOtherLZOrWZ, tClosestZoneAirUnits, tOtherNearbyAirUnits
        if bDebugMessages == true then LOG(sFunctionRef..': About to search other zones from StartPlateau='..iPlateau..'Z'..iLandOrWaterZone..'; iAirAAThreshold='..iAirAAThreshold) end
        for iEntry, tPathingDetails in tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
            if tPathingDetails[AiBotMap.subrefiDistance] > iSimpleZoneSearchRadius then
                break
            end
            iOtherPlateauOrZero = tPathingDetails[AiBotMap.subrefiPlateauOrPond]
            iOtherLZOrWZ = tPathingDetails[AiBotMap.subrefiLandOrWaterZoneRef]
            if tPathingDetails[AiBotMap.subrefbIsWaterZone] then iOtherPlateauOrZero = 0 end
            if iOtherLZOrWZ then
                local tOtherLZOrWZData
                local tOtherLZOrWZTeamData
                if iOtherPlateauOrZero == 0 then
                    tOtherLZOrWZData = AiBotMap.tPondDetails[tPathingDetails[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][iOtherLZOrWZ]
                    tOtherLZOrWZTeamData = tOtherLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                else
                    tOtherLZOrWZData = AiBotMap.tAllPlateaus[iOtherPlateauOrZero][AiBotMap.subrefPlateauLandZones][iOtherLZOrWZ]
                    tOtherLZOrWZTeamData = tOtherLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                end
                --Check actual midpoint is close enough to our unit
                if bDebugMessages == true then LOG(sFunctionRef..': Considering P'..iOtherPlateauOrZero..'Z'..iOtherLZOrWZ..'; Enemy AirAAThreat='..(tOtherLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)..'; iCumulativeAirAAThreat before this='..iCumulativeAirAAThreat..'; Dist between zones='..tPathingDetails[AiBotMap.subrefiDistance]) end
                if (tOtherLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) > 0 then
                    if not(tClosestZoneAirUnits) or iCumulativeAirAAThreat <= 300 then
                        if not(tClosestZoneAirUnits) then
                            tClosestZoneAirUnits = tOtherLZOrWZTeamData[AiBotMap.reftLZEnemyAirUnits]
                        else
                            if not(tOtherNearbyAirUnits) then tOtherNearbyAirUnits = {} end
                            for iUnit, oUnit in tOtherLZOrWZTeamData[AiBotMap.reftLZEnemyAirUnits] do
                                table.insert(tOtherNearbyAirUnits, oUnit)
                            end
                        end
                    end
                    iCumulativeAirAAThreat = iCumulativeAirAAThreat + tOtherLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat]
                    if iCumulativeAirAAThreat > iAirAAThreshold then
                        break
                    end
                end
            end
        end
        if iCumulativeAirAAThreat > iAirAAThreshold then
            if not(bHaveAirAAWithinSearchDistance) and AiBotUtilities.IsTableEmpty(tClosestZoneAirUnits) == false then
                for iUnit, oUnit in tClosestZoneAirUnits do
                    if not(oUnit.Dead) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering how close enemy oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is to tSearchPoint, dist='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tSearchPoint)) end
                        if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tSearchPoint) <= iSearchDistance then
                            bHaveAirAAWithinSearchDistance = true
                            break
                        end
                    end
                end
                if not(bHaveAirAAWithinSearchDistance) and AiBotUtilities.IsTableEmpty(tOtherNearbyAirUnits) == false then
                    for iUnit, oUnit in tOtherNearbyAirUnits do
                        if not(oUnit.Dead) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering how close other enemy oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is to tSearchPoint, dist='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tSearchPoint)) end
                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tSearchPoint) <= iSearchDistance then
                                bHaveAirAAWithinSearchDistance = true
                                break
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bHaveAirAAWithinSearchDistance='..tostring(bHaveAirAAWithinSearchDistance)) end
            if bHaveAirAAWithinSearchDistance then
                if bDebugMessages == true then LOG(sFunctionRef..': Returning true due to enemy air threat that is sufficiently close') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return true
            end
        end
    else
        --Dont have pathing so revert to the simpler adjacent zone check
        if bDebugMessages == true then LOG(sFunctionRef..': No valid pathing so defaulting to adjacent zone check') end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return IsThereAANearLandOrWaterZone(iTeam, iPlateau, iLandOrWaterZone, bIsWaterZone, nil, iAirAAThreshold, nil, tSearchPoint)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function IsThereAANearLandOrWaterZone(iTeam, iPlateau, iLandOrWaterZone, bIsWaterZone, iOptionalGroundThreatThreshold, iOptionalAirAAThreatThreshold, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, bIncludeEnemyGroundAAInAirAAThreat, tOptionalDetailedGroundAAPositionCheck, iIncludeForDetailedIfWithinThisDistOfBeingInRange)
    --returns true if enemy has AA threat in current zone or adjacent land or water zone
    --e.g. used to determine air rally points and support locations, doesnt factor in the path
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'IsThereAANearLandOrWaterZone'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iAdjacentAirAAThreatThreshold = iOptionalAirAAThreatThreshold
    if bIsWaterZone then
        local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
        local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]

        if IsThereAAInZone(tWZTeamData, false, iOptionalGroundThreatThreshold, iOptionalAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat, tOptionalDetailedGroundAAPositionCheck, iIncludeForDetailedIfWithinThisDistOfBeingInRange) then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        else
            if iOptionalAirAAThreatThreshold and iOptionalAirAAThreatThreshold > 0 then iAdjacentAirAAThreatThreshold = math.max(0, iOptionalAirAAThreatThreshold -  (tWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0))  end
            --Cycle through every adjacent water zone
            if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                local bIncludeCurZone
                for _, iAdjWZ in tWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                    if not(iOptionalMaxDistToEdgeOfAdjacentZone) then bIncludeCurZone = true
                    else
                        bIncludeCurZone = AiBotConditions.IsPositionCloseToZoneEdge(0, iAdjWZ, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone)
                    end
                    if bIncludeCurZone then
                        local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                        if IsThereAAInZone(tAdjWZTeamData, false, iOptionalGroundThreatThreshold, iAdjacentAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat, tOptionalDetailedGroundAAPositionCheck, iIncludeForDetailedIfWithinThisDistOfBeingInRange) then
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        elseif iAdjacentAirAAThreatThreshold then
                            iAdjacentAirAAThreatThreshold = iAdjacentAirAAThreatThreshold - (tAdjWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)
                        end
                    end
                end
            end
            --Cycle through every adjacent land zone
            if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefAdjacentLandZones]) == false then
                local bIncludeCurZone
                for iEntry, tSubtable in tWZData[AiBotMap.subrefAdjacentLandZones] do
                    local iAdjPlateau = tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]
                    local iAdjLZ = tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]

                    if not(iOptionalMaxDistToEdgeOfAdjacentZone) then bIncludeCurZone = true
                    else
                        bIncludeCurZone = AiBotConditions.IsPositionCloseToZoneEdge(iAdjPlateau, iAdjLZ, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone)
                    end
                    if bIncludeCurZone then
                        local tLZTeamData = AiBotMap.tAllPlateaus[iAdjPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                        if IsThereAAInZone(tLZTeamData, false, iOptionalGroundThreatThreshold, iAdjacentAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat, tOptionalDetailedGroundAAPositionCheck, iIncludeForDetailedIfWithinThisDistOfBeingInRange) then
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        elseif iAdjacentAirAAThreatThreshold then
                            iAdjacentAirAAThreatThreshold = iAdjacentAirAAThreatThreshold - (tLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)
                        end
                    end
                end
            end
        end
    else
        --Dealing with a land zone
        local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
        local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
        if bDebugMessages == true then LOG(sFunctionRef..': About to check if there is AA in land zone, iOptionalGroundThreatThreshold='..(iOptionalGroundThreatThreshold or 'nil')..'; iOptionalAirAAThreatThreshold='..(iOptionalAirAAThreatThreshold or 'nil')..'; tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]='..(tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')..'; tLZTeamData[AiBotMap.refiEnemyAirAAThreat]='..(tLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 'nil')..'; tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]='..(tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 'nil')) end
        if IsThereAAInZone(tLZTeamData, false, iOptionalGroundThreatThreshold, iOptionalAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat, tOptionalDetailedGroundAAPositionCheck, iIncludeForDetailedIfWithinThisDistOfBeingInRange) then
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            return true
        else
            if iOptionalAirAAThreatThreshold and iOptionalAirAAThreatThreshold > 0 then
                iAdjacentAirAAThreatThreshold = math.max(0, iOptionalAirAAThreatThreshold -  (tLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0))
                if bDebugMessages == true then LOG(sFunctionRef..': setting iAdjacentAirAAThreatThreshold='..iAdjacentAirAAThreatThreshold) end
            end
            --Cycle through every adjacent land zone
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                local bIncludeCurZone

                for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                    if not(iOptionalMaxDistToEdgeOfAdjacentZone) then bIncludeCurZone = true
                    else
                        bIncludeCurZone = AiBotConditions.IsPositionCloseToZoneEdge(iPlateau, iAdjLZ, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone)
                    end
                    if bIncludeCurZone then

                        local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                        if bDebugMessages == true then LOG(sFunctionRef..': About to check if there is AA in land zone, iOptionalGroundThreatThreshold='..(iOptionalGroundThreatThreshold or 'nil')..'; iOptionalAirAAThreatThreshold='..(iOptionalAirAAThreatThreshold or 'nil')..'; tAdjLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]='..(tAdjLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')..'; tAdjLZTeamData[AiBotMap.refiEnemyAirAAThreat]='..(tAdjLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 'nil')..'; tAdjLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]='..(tAdjLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 'nil')) end
                        if IsThereAAInZone(tAdjLZTeamData, false, iOptionalGroundThreatThreshold, iAdjacentAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat, tOptionalDetailedGroundAAPositionCheck, iIncludeForDetailedIfWithinThisDistOfBeingInRange) then
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        elseif iAdjacentAirAAThreatThreshold then
                            iAdjacentAirAAThreatThreshold = iAdjacentAirAAThreatThreshold - (tAdjLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)
                        end
                    end
                end
            end
            --Cycle through every adjacent water zone
            if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                local bIncludeCurZone

                for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                    local iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]

                    if not(iOptionalMaxDistToEdgeOfAdjacentZone) then bIncludeCurZone = true
                    else
                        bIncludeCurZone = AiBotConditions.IsPositionCloseToZoneEdge(0, iAdjWZ, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone)
                    end
                    if bIncludeCurZone then
                        local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                        if IsThereAAInZone(tAdjWZTeamData, false, iOptionalGroundThreatThreshold, iAdjacentAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat, tOptionalDetailedGroundAAPositionCheck, iIncludeForDetailedIfWithinThisDistOfBeingInRange) then
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        elseif iAdjacentAirAAThreatThreshold then
                            iAdjacentAirAAThreatThreshold = iAdjacentAirAAThreatThreshold - (tAdjWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false
end

function RecordOtherLandAndWaterZonesByDistance(tStartLZOrWZData)
    --Records all other land and water zones in order of straight line distance to tStartLZOrWZData, if not already recorded (using subrefOtherLandAndWaterZonesByDistance)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordOtherLandAndWaterZonesByDistance'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local tStartMidpoint = tStartLZOrWZData[AiBotMap.subrefMidpoint]

    if bDebugMessages == true then LOG(sFunctionRef..': Start time='..GetGameTimeSeconds()..'; Is table of other land and water zones empty='..tostring(AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]))) end
    if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) then
        if AiBotUtilities.IsTableEmpty(tStartLZOrWZData) then AiBotUtilities.ErrorHandler('Trying to record other land and water zones when we dont have valid LZOrWZData entry')
        else
            AiBotProfiler.FunctionProfiler(sFunctionRef..'Detail', AiBotProfiler.refProfilerStart)
            tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] = {}
            local tTableToSort = {}
            --Add all land zones in the map
            local bIncludeMinorPlateaus = true
            if AiBotMap.iPlateauCount >= 2000 then bIncludeMinorPlateaus = false end
            for iPlateau, tPlateauData in AiBotMap.tAllPlateaus do
                if AiBotUtilities.IsTableEmpty(tPlateauData[AiBotMap.subrefPlateauLandZones]) == false and (bIncludeMinorPlateaus or not(tPlateauData[AiBotMap.subrefbMinorPlateau])) then
                    --tAllPlateaus[iPlateau][subrefPlateauLandZones][iLandZone]
                    for iLandZone, tLZData in tPlateauData[AiBotMap.subrefPlateauLandZones] do
                        table.insert(tTableToSort, { [AiBotMap.subrefiPlateauOrPond] = iPlateau, [AiBotMap.subrefiLandOrWaterZoneRef] = iLandZone, [AiBotMap.subrefbIsWaterZone] = false, [AiBotMap.subrefiDistance] = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tStartMidpoint)})
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Size of tTableToSort after adding all land zones='..table.getn(tTableToSort)) end
            --Add all water zones in the map
            for iPond, tPondSubtable in AiBotMap.tPondDetails do
                for iWaterZone, tWZData in tPondSubtable[AiBotMap.subrefPondWaterZones] do
                    table.insert(tTableToSort, { [AiBotMap.subrefiPlateauOrPond] = iPond, [AiBotMap.subrefiLandOrWaterZoneRef] = iWaterZone, [AiBotMap.subrefbIsWaterZone] = true, [AiBotMap.subrefiDistance] = AiBotUtilities.GetDistanceBetweenPositions(tWZData[AiBotMap.subrefMidpoint], tStartMidpoint)})
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Size of tTableToSort after adding all water zones='..table.getn(tTableToSort)) end
            --Sort the table from low to high
            for iEntry, tValue in AiBotUtilities.SortTableBySubtable(tTableToSort, AiBotMap.subrefiDistance, true) do
                table.insert(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance], tValue)
            end
            if bDebugMessages == true then LOG(sFunctionRef..': reprs of table after sorting='..reprs(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance])) end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef..'Detail', AiBotProfiler.refProfilerEnd)
    end
end

function UpdateAirRallyAndSupportPoints(iTeam, iAirSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateAirRallyAndSupportPoints'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    RefreshPriorityAirDefenceTargets(iAirSubteam)
    --Get the land or water zone of the priority unit that is closest to the enemy base that is closest to the air rally point and determine if its safe as a rally point

    --Get the safest start point as a rally point:
    --If we have any air staging structures that are in a land zone with fixed AA, or a core base, with no adjacent enemy AA threat, then pick here
    --Otherwise pick the start position with the smallest number when taking adjacent enemy AA threat less current land zone friendly ground AA.
    --If no land zone start points, then pick the first water zone as a backup

    if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains]) == false then
        local bDontCheckPlayableArea = not(AiBotMap.bIsCampaignMap)
        local tPreferredRallyPoint
        local iPlateau, iLandZone, iWaterZone
        local iBestRallyValue = -10000000 --we multiply enemy AA threat by up to 10, so want this really ow to avoid no rally point at all
        local iCurRallyValue
        local bDontMoveCloserToEnemyBase = false
        local oPriorityUnitBeingSupported

        local tLongRangeEnemyAirAAUnits --For now just used to avoid czars; if want to add land based units to this then will need to either expand the recorded AA threat codes (since air and ground AA are done separately meaning will get an error if try getting this threat value), or to have 2 tables one for LR AirAA, one for LR GroundAA
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyAirExperimentals]) == false then
            for iAirExp, oAirExp in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyAirExperimentals] do
                if (oAirExp[AiBotUnitInfo.refiAARange] or 0) >= 100 then
                    if not(tLongRangeEnemyAirAAUnits) then tLongRangeEnemyAirAAUnits = {} end
                    table.insert(tLongRangeEnemyAirAAUnits, oAirExp)
                end
            end
        end
        local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
        for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
            local tStartPoint = AiBotMap.GetPlayerStartPosition(oBrain)
            iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tStartPoint)
            if bDebugMessages == true then LOG(sFunctionRef..': Considering brain '..oBrain.Nickname..'; iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')..'; Start point='..repru(AiBotMap.GetPlayerStartPosition(oBrain))..'; iAirSubteam='..iAirSubteam) end
            if (iLandZone or 0) == 0 then
                iWaterZone = AiBotMap.GetWaterZoneFromPosition(tStartPoint)
                if bDebugMessages == true then LOG(sFunctionRef..': iWaterZone='..(iWaterZone or 'nil')) end
                if (iWaterZone or 0) > 0 then
                    local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone]
                    if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tWZData[AiBotMap.subrefMidpoint]) then
                        local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                        iCurRallyValue = GetRallyPointValueOfWaterZone(iTeam, tWZData, tWZTeamData, tLongRangeEnemyAirAAUnits)
                        if bDebugMessages == true then LOG(sFunctionRef..': iCurRallyValue='..(iCurRallyValue)) end
                        if iCurRallyValue > iBestRallyValue then
                            iBestRallyValue = iCurRallyValue
                            tPreferredRallyPoint = {tWZData[AiBotMap.subrefMidpoint][1], tWZData[AiBotMap.subrefMidpoint][2], tWZData[AiBotMap.subrefMidpoint][3]}
                            if bDebugMessages == true then LOG(sFunctionRef..': Updating preferred rally point to water zone '..iWaterZone..' start point, rally point='..repru(tPreferredRallyPoint)) end
                        end
                    end
                end
            else
                --Have a land zone - check for groundAA
                local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]) then
                    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                    iCurRallyValue = GetRallyPointValueOfLandZone(iTeam, tLZData, tLZTeamData, iPlateau, tLongRangeEnemyAirAAUnits)
                    if iCurRallyValue > iBestRallyValue then
                        iBestRallyValue = iCurRallyValue
                        tPreferredRallyPoint = {tLZData[AiBotMap.subrefMidpoint][1], tLZData[AiBotMap.subrefMidpoint][2], tLZData[AiBotMap.subrefMidpoint][3]}
                        if bDebugMessages == true then LOG(sFunctionRef..': Updating preferred rally point to land zone start point '..repru(tPreferredRallyPoint)) end
                    end
                end
            end
        end
        if not(tPreferredRallyPoint) then --redundancy in case really negative rally point value
            tPreferredRallyPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
        end
        --Consider nearest friendly base to rally point, if different
        if tPreferredRallyPoint and iBestRallyValue < 0 then
            local tRallyPointLZOrWZData, tRallyPointLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(tPreferredRallyPoint, true, iTeam)
            if AiBotUtilities.GetDistanceBetweenPositions(tPreferredRallyPoint, tRallyPointLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 20 then
                local tClosestBaseLZOrWZData, tClosestBaseLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(tRallyPointLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], true, iTeam)
                if GetTerrainHeight(tRallyPointLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][1], tRallyPointLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][3]) < AiBotMap.iMapWaterHeight then
                    iCurRallyValue = GetRallyPointValueOfWaterZone(iTeam, tClosestBaseLZOrWZData, tClosestBaseLZOrWZTeamData, tLongRangeEnemyAirAAUnits)
                else
                    iCurRallyValue = GetRallyPointValueOfLandZone(iTeam, tClosestBaseLZOrWZData, tClosestBaseLZOrWZTeamData, iPlateau, tLongRangeEnemyAirAAUnits)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iBestRallyValue currently='..iBestRallyValue..'; iCurRallyValue of closest friendly base to this='..iCurRallyValue..'; Rally point before update='..repru(tPreferredRallyPoint)) end
                if iCurRallyValue > iBestRallyValue then
                    iBestRallyValue = iCurRallyValue
                    tPreferredRallyPoint = {tRallyPointLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][1], tRallyPointLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][2], tRallyPointLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][3]}
                    if bDebugMessages == true then LOG(sFunctionRef..': Closest base is better so will switch to that, tRallyPointLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]='..repru(tRallyPointLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])) end
                end
            end
            if iCurRallyValue < 0 then
                --Consider other zones around the original rally point in case they are better
                RecordOtherLandAndWaterZonesByDistance(tRallyPointLZOrWZData)
                if bDebugMessages == true then LOG(sFunctionRef..': will consider other zones around the rally point due to cur zone being negative') end
                if AiBotUtilities.IsTableEmpty(tRallyPointLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                    local iDistThreshold
                    if AiBotMap.bIsCampaignMap then iDistThreshold = math.max(350, AiBotMap.iMapSize * 0.7)
                    else iDistThreshold = math.max(250, AiBotMap.iMapSize * 0.5)
                    end
                    for iEntry, tSubtable in tRallyPointLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                        if bDebugMessages == true then LOG(sFunctionRef..': considering other zones around rally point, cur dist='..tSubtable[AiBotMap.subrefiDistance]..'; iDistThreshold='..iDistThreshold) end
                        if tSubtable[AiBotMap.subrefiDistance] >= iDistThreshold then break end
                        local tAltLZOrWZData, tAltLZOrWZTeamData
                        local iCurLZOrWZRef = tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]
                        local iPlateauOrZero
                        if tSubtable[AiBotMap.subrefbIsWaterZone] then
                            tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurLZOrWZRef]][AiBotMap.subrefPondWaterZones][iCurLZOrWZRef]
                            tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                            iPlateauOrZero = 0
                        else
                            tAltLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][iCurLZOrWZRef]
                            tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                            iPlateauOrZero = tSubtable[AiBotMap.subrefiPlateauOrPond]
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering zone '..(iCurLZOrWZRef or 'nil')..'; Plateua or pond='..(tSubtable[AiBotMap.subrefiPlateauOrPond] or 'nil')..'; is water zone='..tostring(tSubtable[AiBotMap.subrefbIsWaterZone] or false)..'; In playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tAltLZOrWZData[AiBotMap.subrefMidpoint]))..'; Rally value if LZ='..GetRallyPointValueOfLandZone(iTeam, tAltLZOrWZData, tAltLZOrWZTeamData, iPlateauOrZero, tLongRangeEnemyAirAAUnits)..'; Rally value if WZ='..GetRallyPointValueOfWaterZone(iTeam, tAltLZOrWZData, tAltLZOrWZTeamData, tLongRangeEnemyAirAAUnits)) end
                        if AiBotConditions.IsLocationInPlayableArea(tAltLZOrWZData[AiBotMap.subrefMidpoint]) then
                            if iPlateauOrZero == 0 then
                                iCurRallyValue = GetRallyPointValueOfWaterZone(iTeam, tAltLZOrWZData, tAltLZOrWZTeamData, tLongRangeEnemyAirAAUnits)
                            else
                                iCurRallyValue = GetRallyPointValueOfLandZone(iTeam, tAltLZOrWZData, tAltLZOrWZTeamData, iPlateauOrZero, tLongRangeEnemyAirAAUnits)
                            end
                            if iCurRallyValue > iBestRallyValue then
                                iBestRallyValue = iCurRallyValue
                                tPreferredRallyPoint = {tAltLZOrWZData[AiBotMap.subrefMidpoint][1], tAltLZOrWZData[AiBotMap.subrefMidpoint][2], tAltLZOrWZData[AiBotMap.subrefMidpoint][3]}
                                if iCurRallyValue >= 0 then break end
                            end
                        end
                    end
                end
            end
        end
        --Consider zones to fortify as potential rally points
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have zones to fortify we want to use as a rally point, is reftiFortifyZonesByPlateau empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiFortifyZonesByPlateau]))) end
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiFortifyZonesByPlateau]) == false then
            local tBaseRallyPoint = {tPreferredRallyPoint[1], tPreferredRallyPoint[2], tPreferredRallyPoint[3]}
            local iStartPlateau, iStartZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tBaseRallyPoint)
            if iStartPlateau and iStartZone then
                local iGroundAAThreatAlongPathThreshold = math.min(1500, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat] * 0.1)
                local iCurFortifyZoneDistFromBaseRally
                local iBiggestFortifyZoneDistFromBaseRally = 0
                for iPlateauOrZero, tZones in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiFortifyZonesByPlateau] do
                    for iZone, bZone in tZones do
                        --Only include if we have friendly SValue in the zone
                        local tAltLZOrWZData
                        local tAltLZOrWZTeamData
                        if iPlateauOrZero > 0 then
                            tAltLZOrWZData  = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iZone]
                            tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                        else
                            --Water zone
                            tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iPlateauOrZero]][AiBotMap.subrefPondWaterZones][iZone]
                            tAltLZOrWZTeamData = tAltLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                        end
                        if tAltLZOrWZTeamData[AiBotMap.subrefLZSValue] > 0 and (tAltLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) == 0 and (tAltLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) == 0 then
                            if iPlateauOrZero == 0 then
                                iCurRallyValue = GetRallyPointValueOfWaterZone(iTeam, tAltLZOrWZData, tAltLZOrWZTeamData, tLongRangeEnemyAirAAUnits)
                            else
                                iCurRallyValue = GetRallyPointValueOfLandZone(iTeam, tAltLZOrWZData, tAltLZOrWZTeamData, iPlateauOrZero, tLongRangeEnemyAirAAUnits)
                            end
                            iCurFortifyZoneDistFromBaseRally = AiBotUtilities.GetDistanceBetweenPositions(tAltLZOrWZData[AiBotMap.subrefMidpoint], tBaseRallyPoint)
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering zone to fortify P='..iPlateauOrZero..'Z='..iZone..'; iCurRallyValue='..iCurRallyValue..'; iBestRallyValue='..iBestRallyValue..'; DoesEnemyHaveAAThreatAlongPath='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateau, iStartZone, iPlateauOrZero, iZone, false, iGroundAAThreatAlongPathThreshold, 500, false, iAirSubteam, true, false, nil, false, nil, false, false, nil))..'; iCurFortifyZoneDistFromBaseRally='..iCurFortifyZoneDistFromBaseRally..'; iBiggestFortifyZoneDistFromBaseRally='..iBiggestFortifyZoneDistFromBaseRally) end
                            if iCurRallyValue >= 0 and iCurFortifyZoneDistFromBaseRally > iBiggestFortifyZoneDistFromBaseRally and (iBiggestFortifyZoneDistFromBaseRally <= 0 or iCurRallyValue > iBestRallyValue) then
                                if not(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateau, iStartZone, iPlateauOrZero, iZone, false, iGroundAAThreatAlongPathThreshold, 500, false, iAirSubteam, true, false, nil, false, nil, false, false, nil)) then
                                    iBestRallyValue = iCurRallyValue
                                    tPreferredRallyPoint = {tAltLZOrWZData[AiBotMap.subrefMidpoint][1], tAltLZOrWZData[AiBotMap.subrefMidpoint][2], tAltLZOrWZData[AiBotMap.subrefMidpoint][3]}
                                    iBiggestFortifyZoneDistFromBaseRally = iCurFortifyZoneDistFromBaseRally
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have preferred rally value') end
                                end
                            end
                        end
                    end
                end
            end
        end
        AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbOrigRallyOutsidePlayableArea] = false
        if AiBotUtilities.IsTableEmpty(tPreferredRallyPoint) == false then
            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint] = tPreferredRallyPoint
        else
            --Dont have a rally point, find the zone closest to our base that is in the playable area
            local oFirstBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
            local tPlayerStartPosition = AiBotMap.GetPlayerStartPosition(oFirstBrain)
            if AiBotConditions.IsLocationInPlayableArea(tPlayerStartPosition) then
                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint] = {tPlayerStartPosition[1], tPlayerStartPosition[2], tPlayerStartPosition[3]}
            else
                local iStartPlateauOrZero, iStartLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tPlayerStartPosition)
                local tStartLZOrWZData
                if iStartPlateauOrZero == 0 then
                    tStartLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iStartLandOrWaterZone]
                else
                    tStartLZOrWZData = AiBotMap.tAllPlateaus[iStartPlateauOrZero][AiBotMap.subrefPlateauLandZones][iStartLandOrWaterZone]
                end
                if not(tStartLZOrWZData) then AiBotUtilities.ErrorHandler('unable to find a valid zone for player start position, iStartPlateauOrZero='..(iStartPlateauOrZero or 'nil')..'; iStartLandOrWaterZone='..(iStartLandOrWaterZone or 'nil')..'; Player='..(oFirstBrain.Nickname or 'nil')..' at position X'..(tPlayerStartPosition[1] or 'nil')..'Z'..(tPlayerStartPosition[3] or 'nil')) end
                if AiBotConditions.IsLocationInPlayableArea(tStartLZOrWZData[AiBotMap.subrefMidpoint]) then
                    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint] = {tStartLZOrWZData[AiBotMap.subrefMidpoint][1], tStartLZOrWZData[AiBotMap.subrefMidpoint][2], tStartLZOrWZData[AiBotMap.subrefMidpoint][3]}
                else
                    --Check if we have air staging or factory HQs anywhere on the team, and if so then set this as the air rally point
                    local oUnitAsRallyPoint
                    local iHighestLandTech = 0
                    local iCurLandTech
                    for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                        local tFactoriesAndAirStaging = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAllHQFactories + AiBotUnitInfo.refCategoryAirStaging, false, true)
                        if AiBotUtilities.IsTableEmpty(tFactoriesAndAirStaging) == false then

                            for iUnit, oUnit in tFactoriesAndAirStaging do
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryNavalFactory, oUnit.UnitId) then iCurLandTech = 0.5 else iCurLandTech = AiBotUnitInfo.GetUnitTechLevel(oUnit) end
                                if iCurLandTech > iHighestLandTech then
                                    iHighestLandTech = iCurLandTech
                                    oUnitAsRallyPoint = oUnit
                                    if iCurLandTech >= 3 then break end
                                end
                            end
                        end
                        if iCurLandTech >= 3 then break end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Does anyone on our team have an air staging faciltiy to be used as the rally point? oUnitAsRallyPoint='..(oUnitAsRallyPoint.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnitAsRallyPoint) or 'nil')) end
                    if oUnitAsRallyPoint then
                        AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbOrigRallyOutsidePlayableArea] = oUnitAsRallyPoint:GetPosition()
                    else
                        AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbOrigRallyOutsidePlayableArea] = true
                        RecordOtherLandAndWaterZonesByDistance(tStartLZOrWZData)
                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of other Land and water zones by distance empty='..tostring(AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]))) end
                        if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                            for iEntry, tSubtable in tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                                local tAltLZOrWZData
                                local iCurLZOrWZRef = tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]
                                if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                    tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurLZOrWZRef]][AiBotMap.subrefPondWaterZones][iCurLZOrWZRef]
                                else
                                    tAltLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][iCurLZOrWZRef]
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering zone '..(iCurLZOrWZRef or 'nil')..'; Plateua or pond='..(tSubtable[AiBotMap.subrefiPlateauOrPond] or 'nil')..'; is water zone='..tostring(tSubtable[AiBotMap.subrefbIsWaterZone] or false)..'; In playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tAltLZOrWZData[AiBotMap.subrefMidpoint]))) end
                                if AiBotConditions.IsLocationInPlayableArea(tAltLZOrWZData[AiBotMap.subrefMidpoint]) then
                                    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint] = {tAltLZOrWZData[AiBotMap.subrefMidpoint][1], tAltLZOrWZData[AiBotMap.subrefMidpoint][2], tAltLZOrWZData[AiBotMap.subrefMidpoint][3]}
                                    break
                                end
                            end
                        end
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]) then
                if AiBotUtilities.IsTableEmpty(tPreferredRallyPoint) then
                    tPreferredRallyPoint = {tPlayerStartPosition[1], tPlayerStartPosition[2], tPlayerStartPosition[3]}
                    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint] = {tPlayerStartPosition[1], tPlayerStartPosition[2], tPlayerStartPosition[3]}
                    if bDebugMessages == true then LOG(sFunctionRef..': Still couldnt find preferred rally point or subrallypoint so setting to first brain start position='..repru(tPlayerStartPosition)) end
                else
                    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint] = {tPreferredRallyPoint[1],tPreferredRallyPoint[2],tPreferredRallyPoint[3]}
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Tried finding revised rally point, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint] after update='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])) end

            --[[AiBotAir.RecordOtherLandAndWaterZonesByDistance(tLZOrWZData, tLZOrWZData[AiBotMap.subrefMidpoint])
            if AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) then
                AiBotUtilities.ErrorHandler('No other zones found')
            else
                for iEntry, tSubtable in tLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do--]]
        end

        if bDebugMessages == true then LOG(sFunctionRef..': Set air rally point to rpeferred rally point for now='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])) end

        --Support rally point - move closer to units to support (if we have any) assuming we have a safe rally point
        local tSupportRallyPoint
        local tUnitsToProtect = {}
        if iCurRallyValue >= 0 then
            if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam]) then
                for iUnit, oUnit in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam] do
                    if bDebugMessages == true then LOG(sFunctionRef..': Adding unit to protect='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to air support team, unit owner='..oUnit:GetAIBrain().Nickname) end
                    table.insert(tUnitsToProtect, oUnit)
                end
            end
            if AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]) then
                if bDebugMessages == true then LOG(sFunctionRef..': Adding front gunship='..AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship])..' owned by '..AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetAIBrain().Nickname..' to air support team') end
                table.insert(tUnitsToProtect, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship])
            end
            --[[if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoSpecialUnitsToProtect]) then
            for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoSpecialUnitsToProtect] do
                table.insert(tUnitsToProtect, oUnit)
            end
        end--]]
            if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; About to get support location, is table of units to protect='..tostring(AiBotUtilities.IsTableEmpty(tUnitsToProtect))) end
            local iFriendlyAAFromUnitToProtect = 0
            if AiBotUtilities.IsTableEmpty(tUnitsToProtect) == false then
                local iCurLZOrWZ, iCurPlateauOrZero
                local iClosestDistToEnemyBase = 100000
                local iCurDistToEnemyBase
                local tClosestMidpoint
                local tClosestBase
                for iUnit, oUnit in tUnitsToProtect do
                    iCurDistToEnemyBase = 100000
                    iCurPlateauOrZero, iCurLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': COnsidering unit to protect='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurLZOrWZ='..(iCurLZOrWZ or 'nil')..'; position='..repru(oUnit:GetPosition())) end
                    if (iCurPlateauOrZero or 0) == 0 then
                        if (iCurLZOrWZ or 0) > 0 then
                            local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurLZOrWZ]][AiBotMap.subrefPondWaterZones][iCurLZOrWZ]
                            if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tWZData[AiBotMap.subrefMidpoint]) then
                                local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                                iCurDistToEnemyBase = AiBotUtilities.GetDistanceBetweenPositions(tWZData[AiBotMap.subrefMidpoint], tWZTeamData[AiBotMap.reftClosestEnemyBase])
                                if bDebugMessages == true then LOG(sFunctionRef..': Unit is in a water zone, iCurDistToEnemyBase='..(iCurDistToEnemyBase or 'nil')..'; tWZTeamData[AiBotMap.reftClosestEnemyBase]='..repru(tWZTeamData[AiBotMap.reftClosestEnemyBase])..'; WZ midpoint='..repru(tWZData[AiBotMap.subrefMidpoint])) end
                                if iCurDistToEnemyBase <   iClosestDistToEnemyBase then
                                    oPriorityUnitBeingSupported = oUnit
                                    iClosestDistToEnemyBase = iCurDistToEnemyBase
                                    tClosestMidpoint = {tWZData[AiBotMap.subrefMidpoint][1], tWZData[AiBotMap.subrefMidpoint][2], tWZData[AiBotMap.subrefMidpoint][3]}
                                    tClosestBase = {tWZTeamData[AiBotMap.reftClosestFriendlyBase][1], tWZTeamData[AiBotMap.reftClosestFriendlyBase][2], tWZTeamData[AiBotMap.reftClosestFriendlyBase][3]}
                                end
                            end
                        end
                    else
                        --Have a valid land zone
                        local tLZData = AiBotMap.tAllPlateaus[iCurPlateauOrZero][AiBotMap.subrefPlateauLandZones][iCurLZOrWZ]
                        if bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]) then
                            local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                            if bDebugMessages == true then LOG(sFunctionRef..': Have a valid land zone, iCurLZ='..(iCurLZOrWZ or 'nil')..'; iCurPlateau='..(iCurPlateauOrZero or 'nil')..'; LZ midpoint='..repru(tLZData[AiBotMap.subrefMidpoint])..'; Closest enemy base='..repru(tLZTeamData[AiBotMap.reftClosestEnemyBase])..'; iTeam='..(iTeam or 'nil')) end
                            iCurDistToEnemyBase = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], tLZTeamData[AiBotMap.reftClosestEnemyBase])
                            if iCurDistToEnemyBase < iClosestDistToEnemyBase then
                                oPriorityUnitBeingSupported = oUnit
                                iClosestDistToEnemyBase = iCurDistToEnemyBase
                                tClosestMidpoint = {tLZData[AiBotMap.subrefMidpoint][1], tLZData[AiBotMap.subrefMidpoint][2], tLZData[AiBotMap.subrefMidpoint][3]}
                                tClosestBase = {tLZTeamData[AiBotMap.reftClosestFriendlyBase][1], tLZTeamData[AiBotMap.reftClosestFriendlyBase][2], tLZTeamData[AiBotMap.reftClosestFriendlyBase][3]}
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..' Finished considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Unit position='..repru(oUnit:GetPosition())..'; iCurPlateau='..(iCurPlateauOrZero or 'nil')..'; iCurWZ='..(iCurLZOrWZ or 'nil')..'; iCurDistToEnemyBase='..(iCurDistToEnemyBase or 'nil')..'; iClosestDistToEnemyBase='..(iClosestDistToEnemyBase or 'nil')..'; tClosestMidpoint='..repru(tClosestMidpoint)) end
                end

                if oPriorityUnitBeingSupported then
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryAirNonScout, oPriorityUnitBeingSupported.UnitId) then
                        iFriendlyAAFromUnitToProtect = AiBotUnitInfo.GetAirThreatLevel({ oPriorityUnitBeingSupported }, false, true, false)
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryGunship, oPriorityUnitBeingSupported.UnitId) then
                            iFriendlyAAFromUnitToProtect = math.max(iFriendlyAAFromUnitToProtect, (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiOurGunshipAAThreat] or 0))
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished going through all units to protect, tClosestMidpoint, being the zone midpoint for the priority unit to protect='..repru(tClosestMidpoint)) end
                local tAlternativeToZoneMidpointOverride --Used if want to be partway between base and air unit, due to zone midpoint itself being too dangerous
                if tClosestMidpoint then
                    --Change the closest base if it isn't safe and we have another base that is safe
                    local iBasePlateau, iBaseLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tClosestBase)
                    local bBaseIsNotSafe = true
                    if (iBaseLandOrWaterZone or 0) > 0 then
                        if not(IsThereAANearLandOrWaterZone(iTeam, iBasePlateau, iBaseLandOrWaterZone, iBasePlateau == 0, 0, 0)) then bBaseIsNotSafe = false end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': tClosestBase='..repru(tClosestBase)..'; bBaseIsNotSafe='..tostring(bBaseIsNotSafe)) end
                    if bBaseIsNotSafe then
                        local tClosestSafeMidpoint
                        local iCurBaseDist
                        local iClosestBaseDist = 100000
                        for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                            local tStartPoint = AiBotMap.GetPlayerStartPosition(oBrain)
                            iBasePlateau, iBaseLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tStartPoint)
                            if (iBaseLandOrWaterZone or 0) > 0 then
                                iCurBaseDist = AiBotUtilities.GetDistanceBetweenPositions(tStartPoint, tClosestMidpoint)
                                if iCurBaseDist < iClosestBaseDist then
                                    if not(IsThereAANearLandOrWaterZone(iTeam, iBasePlateau, iBaseLandOrWaterZone, iBasePlateau == 0, 0, 0)) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Closest base is dangerous, but have a safe base at position '..repru(AiBotMap.GetPlayerStartPosition(oBrain))..' for AiBot brain '..oBrain.Nickname) end
                                        iClosestBaseDist = iCurBaseDist
                                        tClosestSafeMidpoint = {tStartPoint[1], tStartPoint[2], tStartPoint[3]}
                                    end
                                end
                            end
                        end
                        if tClosestSafeMidpoint then tClosestBase = tClosestSafeMidpoint
                        else
                            --We couldnt find any safer bases; however its possible our unit itself is just too dangerous to try and support, so consider switching to another air subteam just based on in zone threat
                            --Update closest base if enemy threats in it, to cover scenario where e.g. it is for a non-air subteam member who has just died (but not had their base entirely wiped out)
                            if AiBotUtilities.IsTableEmpty(tClosestBase) == false and table.getn(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains]) > 1 then
                                local tClosestBaseLZData, tClosestBaseLZTeamData = AiBotMap.GetLandOrWaterZoneData(tClosestBase, true, iTeam)
                                if bDebugMessages == true then LOG(sFunctionRef..': tClosestBaseLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]='..(tClosestBaseLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')) end
                                if tClosestBaseLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ] and tClosestBaseLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] > 0 then
                                    --Find another safer base
                                    local tAltBase, iCurDist
                                    local iClosestAltBase = 100000
                                    for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                                        local tStartPosition = AiBotMap.GetPlayerStartPosition(oBrain)
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tStartPosition, tClosestBase)
                                        if iCurDist < iClosestAltBase and iCurDist > 5 then
                                            local tAltBaseLZData, tAltBaseLZTeamData = AiBotMap.GetLandOrWaterZoneData(tStartPosition, true, iTeam)
                                            if bDebugMessages == true then LOG(sFunctionRef..': considering start position for brain '..oBrain.Nickname..'; Enemy GroundAA in this s tart='..(tAltBaseLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)) end
                                            if (tAltBaseLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) == 0 then
                                                iClosestAltBase = iCurDist
                                                tAltBase = tStartPosition
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Closest base is dangerous so looking for alt base, is table of tAltBase empty='..tostring(AiBotUtilities.IsTableEmpty(tAltBase))..'; iClosestAltBase='..iClosestAltBase) end
                                    if AiBotUtilities.IsTableEmpty(tAltBase) == false then
                                        tClosestBase = {tAltBase[1], tAltBase[2], tAltBase[3]}
                                    end
                                end
                            end

                        end
                    end


                    --Move from the closest base to the support point until no longer find a safe land/water zone, and then abort
                    local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(tClosestBase, tClosestMidpoint)
                    if bDebugMessages == true then LOG(sFunctionRef..': iDistToTarget='..iDistToTarget..'; tClosestBase='..repru(tClosestBase)) end
                    if iDistToTarget <= 50 then
                        --If closest base isn't safe then use rally point
                        local iPlateau, iLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tClosestBase)
                        local iWaterZone
                        local bClosestBaseIsSafe = true
                        if iPlateau and (iLandZone or 0) == 0 then
                            iWaterZone = AiBotMap.GetWaterZoneFromPosition(tClosestBase)
                            if (iWaterZone or 0) > 0 then
                                if IsThereAANearLandOrWaterZone(iTeam, iPlateau, iWaterZone, true) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering water zone for the closest base and it isnt safe') end
                                    bClosestBaseIsSafe = false
                                end
                            end
                        else
                            if IsThereAANearLandOrWaterZone(iTeam, iPlateau, iLandZone, false) then
                                bClosestBaseIsSafe = false
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering land zone for the closest base and it isnt safe') end
                            end
                        end
                        if tLongRangeEnemyAirAAUnits and bClosestBaseIsSafe then
                            for iLRAA, oLRAA in tLongRangeEnemyAirAAUnits do
                                if AiBotUtilities.GetDistanceBetweenPositions(oLRAA:GetPosition(), tClosestBase) <= oLRAA[AiBotUnitInfo.refiAARange] + 25 then
                                    bClosestBaseIsSafe = false
                                    break
                                end
                            end
                        end
                        if bClosestBaseIsSafe then
                            if bDebugMessages == true then LOG(sFunctionRef..': CLosest base is safe so will use as the starting point for support rally point') end
                            tSupportRallyPoint = tClosestBase
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Closest base isnt safe so will use preferred rally point as the support rally point') end
                            bDontMoveCloserToEnemyBase = true
                            tSupportRallyPoint = tPreferredRallyPoint
                        end
                    else
                        local iAngleToTarget = AiBotUtilities.GetAngleFromAToB(tClosestBase, tClosestMidpoint)
                        local iSearchInterval = 10
                        local iDistToPriorityUnitFromBase = 10000
                        if oPriorityUnitBeingSupported then iDistToPriorityUnitFromBase = AiBotUtilities.GetDistanceBetweenPositions(oPriorityUnitBeingSupported:GetPosition(), tClosestBase) end
                        local iRoundedDist = math.floor(iDistToTarget / iSearchInterval) * iSearchInterval
                        local tCurTarget
                        local iPrevPlateau, iPrevLandZone, iPrevWaterZone
                        local bCurTargetTooDangerous
                        local tbWaterZonesConsidered = {}
                        local tbPlateauAndLandZonesConsidered = {}
                        local iCurPlateau, iCurZone
                        local iGroundAAThreshold
                        local iAirAAThreshold
                        local bDoDetailedCheck = false
                        local iStartPlateauOrZero, iStartLandOrWaterZone
                        if tClosestBase then iStartPlateauOrZero, iStartLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tClosestBase) end
                        local bFarBehindOnAir = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]
                        if bFarBehindOnAir and iFriendlyAAFromUnitToProtect > 0 then
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] + iFriendlyAAFromUnitToProtect > (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiFarBehindFactor] or 0.8) * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] then
                                bFarBehindOnAir = false
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Although normally we are far behind on air, want to consider if there is sufficient AA around the unit we want to protect to justify staying close to it, bFarBehindOnAir='..tostring(bFarBehindOnAir)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat]..'; iFriendlyAAFromUnitToProtect='..iFriendlyAAFromUnitToProtect..'; AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiFarBehindFactor]='..AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiFarBehindFactor]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]) end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Will consider moving closer to priority unit to protect unless are far behind on air, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] or false)) end
                        if not(bFarBehindOnAir) then
                            local iAirToGroundThreat = (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat] or 0) + (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurT1ToT3BomberThreat] or 0)
                            if oPriorityUnitBeingSupported then
                                --If we are supporting a gunship or experimental air unit then have much higher thresholds
                                if iStartPlateauOrZero and iStartLandOrWaterZone then bDoDetailedCheck = true end
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oPriorityUnitBeingSupported.UnitId) and AiBotUtilities.IsTableEmpty(oPriorityUnitBeingSupported[AiBotLand.reftoAssignedMAAGuards]) == false then
                                    iAirAAThreshold = math.max(3000, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] + iFriendlyAAFromUnitToProtect)
                                    iGroundAAThreshold = math.min(math.max(iAirToGroundThreat * 0.1,  AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] * 0.1, 1000), 3000)
                                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryAirToGround, oPriorityUnitBeingSupported.UnitId) then
                                    local iCap = 2500
                                    if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then iCap = 1500 end
                                    iGroundAAThreshold = math.min(iAirToGroundThreat * 0.15,  AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] * 0.075, iCap)
                                    iAirAAThreshold = math.max(iAirToGroundThreat * 0.1, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] * 1.2, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] + iFriendlyAAFromUnitToProtect)
                                else
                                    iGroundAAThreshold = math.min(iAirToGroundThreat * 0.05,  AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] * 0.04, 1000)
                                    iAirAAThreshold = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] + iFriendlyAAFromUnitToProtect
                                end
                            elseif AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] and iAirToGroundThreat >= 3000 then
                                iGroundAAThreshold = math.min(iAirToGroundThreat * 0.08,  AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] * 0.07, 3000)
                                iAirAAThreshold = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] * 0.1
                            end
                        end
                        local iZoneGroundAAThreshold = (iGroundAAThreshold or 0) * 0.1 --threshold for doing a more detailed check
                        local iZoneAirAAThreshold --threshold for doing a more detailed check
                        local tPreviousSafePositionNeeded
                        local bInRangeOfLRAA = false
                        iZoneAirAAThreshold = iAirAAThreshold
                        iZoneGroundAAThreshold = (iGroundAAThreshold or 0) * 0.75

                        for iDist = iSearchInterval, iRoundedDist, iSearchInterval do
                            bCurTargetTooDangerous = false
                            tCurTarget = AiBotUtilities.MoveInDirection(tClosestBase, iAngleToTarget, iDist, true, false, false)
                            iCurPlateau, iCurZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tCurTarget)
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering moving closer to the unit to protects zone, iDist='..iDist..'; tCurTarget='..repru(tCurTarget)..'; iCurPlateau='..(iCurPlateau or 'nil')..'; iCurZone='..(iCurZone or 'nil')..'; iDistToPriorityUnitFromBase='..iDistToPriorityUnitFromBase) end
                            if iCurPlateau and iCurZone then
                                if iCurPlateau == 0 then
                                    --iCurWZ = AiBotMap.GetWaterZoneFromPosition(tCurTarget)
                                    if bDebugMessages == true then LOG(sFunctionRef..': iCurZone='..(iCurZone or 'nil')) end
                                    if not(tbWaterZonesConsidered[iCurZone]) then
                                        --Have a valid water zone, check if it is dangerous
                                        tbWaterZonesConsidered[iCurZone] = true
                                        --IsThereAANearLandOrWaterZone(iTeam, iPlateau, iLandOrWaterZone, bIsWaterZone, iOptionalGroundThreatThreshold, iOptionalAirAAThreatThreshold, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone)
                                        bCurTargetTooDangerous = IsThereAANearLandOrWaterZone(iTeam, iCurPlateau, iCurZone, true,         iZoneGroundAAThreshold,         iZoneAirAAThreshold,                nil,                                    nil)
                                        bInRangeOfLRAA = false
                                        if not(bCurTargetTooDangerous) and tLongRangeEnemyAirAAUnits then
                                            for iLRAA, oLRAA in tLongRangeEnemyAirAAUnits do
                                                if AiBotUtilities.GetDistanceBetweenPositions(oLRAA:GetPosition(), tCurTarget) <= oLRAA[AiBotUnitInfo.refiAARange] + 25 then
                                                    bCurTargetTooDangerous = true
                                                    bInRangeOfLRAA = true
                                                    break
                                                end
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iCurPlateau='..iCurPlateau..'; iCurZone='..iCurZone..'; bCurTargetTooDangerous='..tostring(bCurTargetTooDangerous)..'; bDoDetailedCheck (i.e. if this is dangerous then will do more precise check)='..tostring(bDoDetailedCheck)..'; bInRangeOfLRAA='..tostring(bInRangeOfLRAA)) end
                                        if bCurTargetTooDangerous and bDoDetailedCheck and not(bInRangeOfLRAA) then
                                            bCurTargetTooDangerous = DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iCurPlateau, iCurZone, not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]), iGroundAAThreshold, iZoneAirAAThreshold, false, iAirSubteam, true)
                                            if bCurTargetTooDangerous and oPriorityUnitBeingSupported and EntityCategoryContains(AiBotUnitInfo.refCategoryAirNonScout, oPriorityUnitBeingSupported.UnitId) then
                                                local tCurWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurZone]][AiBotMap.subrefPondWaterZones][iCurZone][AiBotMap.subrefWZTeamData][iTeam]
                                                if tCurWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] < 0.5 * iGroundAAThreshold then
                                                    bCurTargetTooDangerous = DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iCurPlateau, iCurZone, not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]), iGroundAAThreshold, iZoneAirAAThreshold, false, iAirSubteam, true, nil, nil, nil, tCurTarget)
                                                    if bDebugMessages == true then LOG(sFunctionRef..': bCurTargetTooDangerous after second detailed check='..tostring(bCurTargetTooDangerous)) end
                                                    if not(bCurTargetTooDangerous) then
                                                        tPreviousSafePositionNeeded = {tCurTarget[1], tCurTarget[2], tCurTarget[3]}
                                                    end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': bCurTargetTooDangerous is too dangerous after detailed WZ check, is it too dangerous after adjusting midpoint to be tcurposition='..tostring(bCurTargetTooDangerous)..';  tCurWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]='..( tCurWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')) end
                                            elseif not(bCurTargetTooDangerous) then
                                                tPreviousSafePositionNeeded = nil
                                            end
                                        elseif not(bCurTargetTooDangerous) then
                                            tPreviousSafePositionNeeded = nil --we are ok to use midpoint
                                        end

                                        if bCurTargetTooDangerous then
                                            if bDebugMessages == true then
                                                local tWZData, tWZTeamData = AiBotMap.GetLandOrWaterZoneData(tCurTarget, true, iTeam)
                                                LOG(sFunctionRef..': Water Zone is too dangerous so will stop looking further, refiEnemyAirAAThreat='..(tWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 'nil')..'; subrefiThreatEnemyGroundAA='..(tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil'))
                                            end
                                            break
                                        else
                                            --Record this as the 'previous' entry so if we run into a dnagerous location later on we will use this
                                            iPrevPlateau = iCurPlateau
                                            iPrevWaterZone = iCurZone
                                            iPrevLandZone = nil
                                            if bDebugMessages == true then LOG(sFunctionRef..': This water zone seems ok to treat as the support point, P='..iCurPlateau..'; Z='..iCurZone) end
                                        end
                                    end
                                else
                                    --Have a valid land zone
                                    if bDebugMessages == true then LOG(sFunctionRef..': tbPlateauAndLandZonesConsidered[iCurPlateau][iCurZone]='..tostring(tbPlateauAndLandZonesConsidered[iCurPlateau][iCurZone] or false)..'; iCurPlateau='..(iCurPlateau or 'nil')..'; iCurZone='..(iCurZone or 'nil')) end
                                    if not(tbPlateauAndLandZonesConsidered[iCurPlateau][iCurZone]) then
                                        if not(tbPlateauAndLandZonesConsidered[iCurPlateau]) then tbPlateauAndLandZonesConsidered[iCurPlateau] = {} end
                                        tbPlateauAndLandZonesConsidered[iCurPlateau][iCurZone] = true
                                        bCurTargetTooDangerous = IsThereAANearLandOrWaterZone(iTeam, iCurPlateau, iCurZone, false,         iZoneGroundAAThreshold, iZoneAirAAThreshold)
                                        bInRangeOfLRAA = false
                                        if not(bCurTargetTooDangerous) and tLongRangeEnemyAirAAUnits then
                                            for iLRAA, oLRAA in tLongRangeEnemyAirAAUnits do
                                                if AiBotUtilities.GetDistanceBetweenPositions(oLRAA:GetPosition(), tCurTarget) <= oLRAA[AiBotUnitInfo.refiAARange] + 25 then
                                                    bCurTargetTooDangerous = true
                                                    bInRangeOfLRAA = true
                                                    break
                                                end
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iCurPlateau='..iCurPlateau..'; iCurZone='..iCurZone..'; bCurTargetTooDangerous before detailed check='..tostring(bCurTargetTooDangerous)..'; bDoDetailedCheck='..tostring(bDoDetailedCheck)) end
                                        if bCurTargetTooDangerous and bDoDetailedCheck and not(bInRangeOfLRAA) then
                                            --DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck)
                                            bCurTargetTooDangerous = DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iCurPlateau, iCurZone, not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]), iGroundAAThreshold, iZoneAirAAThreshold, false, iAirSubteam, true)
                                            if bCurTargetTooDangerous and oPriorityUnitBeingSupported and EntityCategoryContains(AiBotUnitInfo.refCategoryAirNonScout, oPriorityUnitBeingSupported.UnitId) then
                                                local tCurLZTeamData = AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iCurZone][AiBotMap.subrefLZTeamData][iTeam]
                                                if tCurLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] < 0.5 * iGroundAAThreshold then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': About to do second detailed check, with optioanl start='..repru(tCurTarget)) end
                                                    --_______________________DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat,                                     iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck, bReturnGroundAAUnitsAlongsideAAThreat, tOptionalEndMidpointAdjustForDetailedCheck, bOptionalIgnoreOppositeDirectionZones, bIncludeEnemyGroundAAInAirAAThreat, bAssumeWontTargetInterimAAForDetailedCheck)
                                                    bCurTargetTooDangerous = DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iCurPlateau,         iCurZone, not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]), iGroundAAThreshold, iZoneAirAAThreshold,   false,              iAirSubteam, true,                  nil,                            nil,                                            nil,                                tCurTarget)
                                                    if bDebugMessages == true then LOG(sFunctionRef..': bCurTargetTooDangerous after second detailed check for LZ='..tostring(bCurTargetTooDangerous)) end
                                                    if not(bCurTargetTooDangerous) then
                                                        tPreviousSafePositionNeeded = {tCurTarget[1], tCurTarget[2], tCurTarget[3]}
                                                    end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': bCurTargetTooDangerous is too dangerous after detailed LZ check, is it too dangerous after adjusting midpoint to be tcurposition='..tostring(bCurTargetTooDangerous)..';  tCurWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]='..( tCurLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')) end
                                            elseif not(bCurTargetTooDangerous) then
                                                tPreviousSafePositionNeeded = nil
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': bCurTargetTooDangerous after detailed check='..tostring(bCurTargetTooDangerous)) end
                                        elseif not(bCurTargetTooDangerous) then
                                            tPreviousSafePositionNeeded = nil
                                        end
                                        if bCurTargetTooDangerous then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Land Zone is too dangerous so will stop looking further') end
                                            break
                                        else
                                            --Record this as the 'previous' entry so if we run into a dnagerous location later on we will use this
                                            iPrevPlateau = iCurPlateau
                                            iPrevWaterZone = nil
                                            iPrevLandZone = iCurZone
                                            if bDebugMessages == true then LOG(sFunctionRef..': This land zone seems ok to treat as the support point, P='..iCurPlateau..'; Z='..iCurZone) end
                                        end
                                    end
                                end
                            else
                                --No valid plateau so ignore this position
                            end
                            if iDist > iDistToPriorityUnitFromBase then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will a bort as increasing iDist further means we go past the gunship (on way from our base to it)') end
                                break
                            end
                        end
                        if bCurTargetTooDangerous and bDoDetailedCheck and oPriorityUnitBeingSupported and tClosestBase and EntityCategoryContains(AiBotUnitInfo.refCategoryAirToGround, oPriorityUnitBeingSupported.UnitId) then

                            local iDistFromBaseToMidpoint
                            if not(iPrevPlateau) then iDistFromBaseToMidpoint = 0
                            else
                                local tSupportLZOrWZData
                                if iPrevLandZone then
                                    tSupportLZOrWZData = AiBotMap.tAllPlateaus[iPrevPlateau][AiBotMap.subrefPlateauLandZones][iPrevLandZone]
                                else
                                    tSupportLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iPrevWaterZone]][AiBotMap.subrefPondWaterZones][iPrevWaterZone]
                                end
                                iDistFromBaseToMidpoint = AiBotUtilities.GetDistanceBetweenPositions(tSupportLZOrWZData[AiBotMap.subrefMidpoint], tClosestBase)
                            end
                            local iUnitDistToBase = AiBotUtilities.GetDistanceBetweenPositions(oPriorityUnitBeingSupported:GetPosition(), tClosestBase)
                            local iBaseDistanceThreshold = 60
                            if iUnitDistToBase - iDistFromBaseToMidpoint > iBaseDistanceThreshold then
                                local iMaxSearchRange = math.floor((iUnitDistToBase - iDistFromBaseToMidpoint)/10)*10
                                local bDangerousUsingPreciseCheck
                                if bDebugMessages == true then LOG(sFunctionRef..': Will do more precise support zone check, iDistFromBaseToMidpoint='..iDistFromBaseToMidpoint..'; iUnitDistToBase='..iUnitDistToBase..'; iMaxSearchRange='..iMaxSearchRange) end
                                for iDist = iDistFromBaseToMidpoint + 10, iDistFromBaseToMidpoint + iMaxSearchRange - (iBaseDistanceThreshold - 10), 10 do
                                    --Using a precise point instead of a midpoint, can we find a safe location that is closer to our experimental bomber?
                                    tCurTarget = AiBotUtilities.MoveInDirection(tClosestBase, iAngleToTarget, iDist, true, false, false)
                                    iCurPlateau, iCurZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tCurTarget)
                                    if iCurPlateau and iCurZone then
                                        --DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck)
                                        bDangerousUsingPreciseCheck = DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iCurPlateau, iCurZone, not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]), iGroundAAThreshold, iAirAAThreshold, false, iAirSubteam, true,        false,                          tCurTarget)
                                        if bDebugMessages == true then LOG(sFunctionRef..': More precise support shadowing check, iDist='..iDist..'; bDangerousUsingPreciseCheck='..tostring(bDangerousUsingPreciseCheck or false)) end
                                        if not(bDangerousUsingPreciseCheck) then
                                            --Check LR units
                                            local iLRThreatInRange = 0
                                            if tLongRangeEnemyAirAAUnits then
                                                local tLRAlmostInRange = {}
                                                for iLRAA, oLRAA in tLongRangeEnemyAirAAUnits do
                                                    if AiBotUtilities.GetDistanceBetweenPositions(oLRAA:GetPosition(), tCurTarget) <= oLRAA[AiBotUnitInfo.refiAARange] + 16 then --Reduced range since we are protecting an air exp
                                                        table.insert(tLRAlmostInRange, oLRAA)
                                                    end
                                                end
                                                if AiBotUtilities.IsTableEmpty(tLRAlmostInRange) == false then
                                                    if AiBotUtilities.bCPUPerformanceMode then
                                                        iLRThreatInRange = AiBotUnitInfo.GetMassCostOfUnits(tLRAlmostInRange)
                                                    else
                                                        iLRThreatInRange = AiBotUnitInfo.GetAirThreatLevel(tLRAlmostInRange, true, true, true, false, false, false)
                                                    end
                                                end
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..' iLRThreatInRange='..iLRThreatInRange..'; iAirAAThreshold='..iAirAAThreshold) end
                                            if iLRThreatInRange == 0 or iLRThreatInRange < 0.5 * iAirAAThreshold then

                                                if bDebugMessages == true then LOG(sFunctionRef..': Using a precise location we have a more appropriate point, iDist='..iDist..'; tAlternativeToZoneMidpointOverride='..repru(tAlternativeToZoneMidpointOverride)) end
                                                tAlternativeToZoneMidpointOverride = {tCurTarget[1], tCurTarget[2], tCurTarget[3]}
                                            end
                                        else
                                            break
                                        end
                                    end
                                end
                            end
                        end

                        if bDebugMessages == true then LOG(sFunctionRef..': Finished checking for support location, iPrevWaterZone='..(iPrevWaterZone or 'nil')..'; iPrevLandZone='..(iPrevLandZone or 'nil')..'; tAlternativeToZoneMidpointOverride='..repru(tAlternativeToZoneMidpointOverride)) end
                        if bCurTargetTooDangerous then bDontMoveCloserToEnemyBase = true end
                        --Update the support rally point, and record pathing of other land and air zones to it if havent previously
                        if not(iPrevWaterZone) and not(iPrevLandZone) then
                            --Use closest base
                            tSupportRallyPoint = tClosestBase
                        elseif tAlternativeToZoneMidpointOverride then
                            tSupportRallyPoint = {tAlternativeToZoneMidpointOverride[1], tAlternativeToZoneMidpointOverride[2], tAlternativeToZoneMidpointOverride[3]}
                        else
                            --We have a valid support zone
                            local tSupportLZOrWZData
                            if iPrevLandZone then
                                tSupportLZOrWZData = AiBotMap.tAllPlateaus[iPrevPlateau][AiBotMap.subrefPlateauLandZones][iPrevLandZone]
                            else
                                tSupportLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iPrevWaterZone]][AiBotMap.subrefPondWaterZones][iPrevWaterZone]
                            end
                            if tPreviousSafePositionNeeded then
                                tSupportRallyPoint = {tPreviousSafePositionNeeded[1], tPreviousSafePositionNeeded[2], tPreviousSafePositionNeeded[3]}
                                if bDebugMessages == true then LOG(sFunctionRef..': The last plateau and zone we located we required a detailed check based on a non-midpoint position to be safe') end
                                bDontMoveCloserToEnemyBase = true
                            else
                                tSupportRallyPoint = {tSupportLZOrWZData[AiBotMap.subrefMidpoint][1], tSupportLZOrWZData[AiBotMap.subrefMidpoint][2], tSupportLZOrWZData[AiBotMap.subrefMidpoint][3]}
                            end
                            --Redundancy - check for enemy ground AA within range of the destination; if have any then move back towards base by 50
                            local bMoveCloserToRally = false
                            local tNearbyEnemyAA
                            if aiBrain.GetUnitsAroundPoint then
                                --Increased range to 85 for v90 from 78 to allow for air units turning around
                                tNearbyEnemyAA = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryGroundAA, tSupportRallyPoint, 85, 'Enemy')
                                if bDebugMessages == true then LOG(sFunctionRef..': Is tNearbyEnemyAA empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyEnemyAA))) if AiBotUtilities.IsTableEmpty(tNearbyEnemyAA) == false then LOG(sFunctionRef..': Mass cost of nearby AA='..AiBotUnitInfo.GetMassCostOfUnits(tNearbyEnemyAA, true)..'; AiBotUnitInfo.GetAirThreatLevel(tNearbyEnemyAA, true, false, true, false, false, false)='..AiBotUnitInfo.GetAirThreatLevel(tNearbyEnemyAA, true, false, true, false, false, false)..'; iGroundAAThreshold='..iGroundAAThreshold)  end end
                                if AiBotUtilities.IsTableEmpty(tNearbyEnemyAA) == false and (not(iGroundAAThreshold) or AiBotUnitInfo.GetAirThreatLevel(tNearbyEnemyAA, true, false, true, false, false, false) > iGroundAAThreshold) then
                                    for iAA, oAA in tNearbyEnemyAA do
                                        if bDebugMessages == true then LOG(sFunctionRef..': oAA Nearby='..oAA.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAA)..'; AA range='..oAA[AiBotUnitInfo.refiAARange]..'; Dist to support rally='..AiBotUtilities.GetDistanceBetweenPositions(oAA:GetPosition(), tSupportRallyPoint)) end
                                        if oAA[AiBotUnitInfo.refiAARange] >= 65 or AiBotUtilities.GetDistanceBetweenPositions(oAA:GetPosition(), tSupportRallyPoint) - (oAA[AiBotUnitInfo.refiAARange] or 0) <= 18 then
                                            bMoveCloserToRally = true
                                            break
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': bMoveCloserToRally after check for neraby groundAA that have intel of='..tostring(bMoveCloserToRally or false)) end
                                if bMoveCloserToRally then
                                    bDontMoveCloserToEnemyBase = true
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have managed to end up with a support point wiht nearby enemy groundAA so will move support point back a bit, tSupportRallyPoint pre update='..repru(tSupportRallyPoint)) end
                                    tSupportRallyPoint = AiBotUtilities.MoveInDirection(tSupportRallyPoint, AiBotUtilities.GetAngleFromAToB(tSupportRallyPoint, tClosestBase), 50, true, false, AiBotMap.bIsCampaignMap)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Rally point post update='..repru(tSupportRallyPoint)) end
                                end
                            end

                            if bDebugMessages == true then LOG(sFunctionRef..': tSupportRallyPoint after updating for zones closer to a unit to support and having a vlocation closer than the nearest friendly base='..repru(tSupportRallyPoint)) end
                        end

                    end
                end
            end
        end

        --Check that we have a location with a valid zone (if we have a support rally point)
        if bDebugMessages == true then LOG(sFunctionRef..': tSupportRallyPoint='..repru(tSupportRallyPoint)..'; tPreferredRallyPoint='..repru(tPreferredRallyPoint)) end
        if not(tSupportRallyPoint) then
            if AiBotUtilities.IsTableEmpty(tPreferredRallyPoint) == false and (bDontCheckPlayableArea or AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]) or AiBotConditions.IsLocationInPlayableArea(tPreferredRallyPoint)) then
                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = tPreferredRallyPoint
            else
                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = {AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][1], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][2], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][3]}
            end
        else
            --Move the support rally point if not on a land or water zone
            local iSupportPlateau, iSupportLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tSupportRallyPoint)
            local iRevisedSegmentX, iRevisedSegmentZ
            if not(iSupportPlateau) then
                local iSegmentX, iSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tSupportRallyPoint)
                iSupportLZOrWZ = nil
                if bDebugMessages == true then LOG(sFunctionRef..': Trying to move support rally point to a location that is on a valid land or water zone, iSegmentX='..iSegmentX..'; iSegmentZ='..iSegmentZ..'; tSupportRallyPoint before change='..repru(tSupportRallyPoint)) end
                for iAdjustBase = 1, 30 do
                    for iCurSegmentX = iSegmentX - iAdjustBase, iSegmentX + iAdjustBase, 1 do
                        for iCurSegmentZ = iSegmentZ - iAdjustBase, iSegmentZ + iAdjustBase, iAdjustBase * 2 do
                            if iCurSegmentX >= 0 and iCurSegmentZ >= 0 then
                                if bDebugMessages == true then
                                    LOG(sFunctionRef..': Considering iCurSegmentX='..iCurSegmentX..'; iCurSegmentZ='..iCurSegmentZ..'; Position='..repru(AiBotMap.GetPositionFromPathingSegments(iCurSegmentX, iCurSegmentZ))..'; AiBotMap.tLandZoneBySegment[iCurSegmentX][iCurSegmentZ]='..(AiBotMap.tLandZoneBySegment[iCurSegmentX][iCurSegmentZ] or 'nil')..'; iAdjustBase='..iAdjustBase)
                                    if not(AiBotMap.tWaterZoneBySegment[iCurSegmentX][iCurSegmentZ]) and not(AiBotMap.tLandZoneBySegment[iCurSegmentX][iCurSegmentZ]) then
                                        AiBotUtilities.DrawLocation(AiBotMap.GetPositionFromPathingSegments(iCurSegmentX, iCurSegmentZ), 2)
                                    end
                                end
                                if AiBotMap.tWaterZoneBySegment[iCurSegmentX][iCurSegmentZ] and not(AiBotMap.tLandZoneBySegment[iCurSegmentX][iCurSegmentZ]) then
                                    iSupportPlateau = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, AiBotMap.GetPositionFromPathingSegments(iCurSegmentX, iCurSegmentZ))
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have a water zone segment='..(AiBotMap.tWaterZoneBySegment[iCurSegmentX][iCurSegmentZ] or 'nil')..'; iSupportPlateau='..(iSupportPlateau or 'nil')) end
                                    if iSupportPlateau then
                                        iSupportLZOrWZ = AiBotMap.tWaterZoneBySegment[iCurSegmentX][iCurSegmentZ]
                                        iRevisedSegmentX = iCurSegmentX
                                        iRevisedSegmentZ = iCurSegmentZ
                                        break
                                    end
                                elseif AiBotMap.tLandZoneBySegment[iCurSegmentX][iCurSegmentZ] then
                                    iSupportPlateau = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, AiBotMap.GetPositionFromPathingSegments(iCurSegmentX, iCurSegmentZ))
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have a land zone segment='..(AiBotMap.tLandZoneBySegment[iCurSegmentX][iCurSegmentZ] or 'nil')..'; iSupportPlateau='..(iSupportPlateau or 'nil')) end
                                    if iSupportPlateau then
                                        iSupportLZOrWZ = AiBotMap.tLandZoneBySegment[iCurSegmentX][iCurSegmentZ]
                                        iRevisedSegmentX = iCurSegmentX
                                        iRevisedSegmentZ = iCurSegmentZ
                                        break
                                    end
                                end
                            end
                        end
                        if iSupportLZOrWZ then break end
                    end
                    if iSupportLZOrWZ then break end
                    --Then do the left and right row (excl corners which ahve already done per the above)
                    for iCurSegmentX = iSegmentX - iAdjustBase, iSegmentX + iAdjustBase, iAdjustBase * 2 do
                        for iCurSegmentZ = iSegmentZ - iAdjustBase + 1, iSegmentZ + iAdjustBase - 1, 1 do
                            if iCurSegmentX >= 0 and iCurSegmentZ >= 0 then
                                if AiBotMap.tWaterZoneBySegment[iCurSegmentX][iCurSegmentZ] then
                                    iSupportPlateau = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, AiBotMap.GetPositionFromPathingSegments(iCurSegmentX, iCurSegmentZ))
                                    if iSupportPlateau then
                                        iRevisedSegmentX = iCurSegmentX
                                        iRevisedSegmentZ = iCurSegmentZ
                                        iSupportLZOrWZ = AiBotMap.tWaterZoneBySegment[iCurSegmentX][iCurSegmentZ]
                                        break
                                    end
                                elseif AiBotMap.tLandZoneBySegment[iCurSegmentX][iCurSegmentZ] then
                                    iSupportPlateau = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, AiBotMap.GetPositionFromPathingSegments(iCurSegmentX, iCurSegmentZ))
                                    if iSupportPlateau then
                                        iSupportLZOrWZ = AiBotMap.tLandZoneBySegment[iCurSegmentX][iCurSegmentZ]
                                        iRevisedSegmentX = iCurSegmentX
                                        iRevisedSegmentZ = iCurSegmentZ
                                        break
                                    end
                                end
                            end
                        end
                        if iSupportLZOrWZ then break end
                    end
                    if iSupportLZOrWZ then break end
                end
                if not(iSupportLZOrWZ) or not(iRevisedSegmentX) or not(iRevisedSegmentZ) then
                    AiBotUtilities.ErrorHandler('We have tried searching for nearby valid segment and failed to find one, may result in errors, wont update the support rally point', true, true)
                    tSupportRallyPoint = nil
                else
                    --Update tSupportRallyPoint
                    if bDebugMessages == true then LOG(sFunctionRef..': Will use segment nearby that has a valid zone, iCurSegment: X'..iRevisedSegmentX..'Z'..iRevisedSegmentZ..' at position '..repru(AiBotMap.GetPositionFromPathingSegments(iRevisedSegmentX, iRevisedSegmentZ))) end
                    tSupportRallyPoint = AiBotMap.GetPositionFromPathingSegments(iRevisedSegmentX, iRevisedSegmentZ)
                end
            end
            if iSupportLZOrWZ and iSupportPlateau then
                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = tSupportRallyPoint
                if bDebugMessages == true then LOG(sFunctionRef..': Have valid plateau and zone so setting subsupportpoint to supportrallypoint') end
            else
                --Do nothing - i.e. retain the previous rally point unless we dont have one
                local bUsePreferredRallyInstead = false
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]) then
                    bUsePreferredRallyInstead = true
                else
                    local iSupportPlateauOrZero, iSupportLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])
                    if not(iSupportPlateauOrZero) or not(iSupportLandOrWaterZone) then
                        bUsePreferredRallyInstead = true
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': Wont change air sub support point from what it was last cycle as it appears to have a valid plateau and water zone') end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Will use previous support point if we have one as a redundancy, iAirSubteam='..iAirSubteam..'; AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])='..repru(AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]))..'; bUsePreferredRallyInstead='..tostring(bUsePreferredRallyInstead)) end
                if bUsePreferredRallyInstead then
                    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = tPreferredRallyPoint
                    if bDebugMessages == true then LOG(sFunctionRef..': Updated support poitn to preferred rally point='..repru(tPreferredRallyPoint)) end
                end
            end
        end

        --Larger maps - consier keeping AirAA very close to a t3 bomber with a target - if not supporting an experimental or ACU, or it is close to the nearest friendly base, and we have a stronger air force than enemy, then consider supporting a front t3 bomber that has an active target
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to stay close to front bomber, is frontt3bomber valid='..tostring(AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber]))..'; Bomber threat='..AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurT1ToT3BomberThreat]..'; Does front bomber have a valid target='..tostring(AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber][refoStrikeDamageAssigned]))..'; OurAirAAThreat='..AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat]..'; EnemyAirAAThreat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]..'; MapSize='..AiBotMap.iMapSize..'; oPriorityUnitBeingSupported='..(oPriorityUnitBeingSupported.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oPriorityUnitBeingSupported) or 'nil')) end
        local bConsideredForT3Bomber = false
        function ConsiderChangingSupportPointToSupportBomber(oBomber, bConsideringTorpBomber)
            local bDontWantToSupportExpOrACUInstead = false
            local tPotentialBomberSupportPoint
            local bCheckedForPotentialSupportPoint = false
            function GetPotentialBomberSupportPoint(bUpdateAirSupportPointIfValid)
                if not(bCheckedForPotentialSupportPoint) then
                    bCheckedForPotentialSupportPoint = true
                    local bFoundValidPoint = false
                    local iAngleToBomber = AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])

                    for iDist = 30, 60, 5 do
                        tPotentialBomberSupportPoint = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iAngleToBomber, iDist, true, false, AiBotMap.bIsCampaignMap)
                        if AiBotUtilities.IsTableEmpty(tPotentialBomberSupportPoint) == false then
                            if (NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tPotentialBomberSupportPoint) or 0) > 0 and ((NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeAmphibious, tPotentialBomberSupportPoint) or 0) > 0 or (NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeNavy, tPotentialBomberSupportPoint) or 0) > 0) then
                                --Double-check
                                local iStartPlateau, iStartLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tPotentialBomberSupportPoint)
                                if iStartPlateau and iStartLZOrWZ then
                                    bFoundValidPoint = true
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will change air support point to be close to the t3 bomber if bUpdateAirSupportPointIfValid is true, iDist='..iDist..'; bUpdateAirSupportPointIfValid='..tostring(bUpdateAirSupportPointIfValid or false)) end
                                    break
                                end
                            end
                        end
                    end
                    if bFoundValidPoint then
                        if bUpdateAirSupportPointIfValid then AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = {tPotentialBomberSupportPoint[1], tPotentialBomberSupportPoint[2],tPotentialBomberSupportPoint[3]} end
                    else
                        tPotentialBomberSupportPoint = nil
                    end
                elseif bUpdateAirSupportPointIfValid and tPotentialBomberSupportPoint then
                    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = {tPotentialBomberSupportPoint[1], tPotentialBomberSupportPoint[2],tPotentialBomberSupportPoint[3]}
                end
            end
            if not(oPriorityUnitBeingSupported) or not(EntityCategoryContains(categories.COMMAND + categories.EXPERIMENTAL, oPriorityUnitBeingSupported.UnitId)) then
                bDontWantToSupportExpOrACUInstead = true
            else
                local tPriorityLZOrWZData, tPriorityLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oPriorityUnitBeingSupported:GetPosition(), true, iTeam)
                if bDebugMessages == true then LOG(sFunctionRef..': Dist between oPriorityUnitBeingSupported and closest friendly base='..AiBotUtilities.GetDistanceBetweenPositions(oPriorityUnitBeingSupported:GetPosition(), tPriorityLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])) end
                if AiBotUtilities.GetDistanceBetweenPositions(oPriorityUnitBeingSupported:GetPosition(), tPriorityLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) < 150 then
                    bDontWantToSupportExpOrACUInstead = true
                else
                    --If our t3 bomber threat is so high that it counts as an experimental, and it is closer to enemy base than priority unit to protect, then still consider shadowing the bombers
                    local iPriorityDistToEnemyBase = AiBotUtilities.GetDistanceBetweenPositions(oPriorityUnitBeingSupported:GetPosition(), tPriorityLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])
                    if bDebugMessages == true then LOG(sFunctionRef..': iPriorityDistToEnemyBase='..iPriorityDistToEnemyBase..'; Dist from front bomber to closest enemy base to priority unit='..AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tPriorityLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])) end
                    if iPriorityDistToEnemyBase >= 100 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] >= 20000 and not(EntityCategoryContains(categories.AIR, oPriorityUnitBeingSupported.UnitId)) and AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tPriorityLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]) <= iPriorityDistToEnemyBase + 10 then
                        bDontWantToSupportExpOrACUInstead = true
                        if bDebugMessages == true then LOG(sFunctionRef..': Will support bomber instead of priority unit') end
                    elseif tPriorityLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] <= 100 and AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]) >= 100 then
                        --Would moving to shadow our t3 bomber bring us closer to the priority unit to support?
                        GetPotentialBomberSupportPoint(false)
                        if bDebugMessages == true then LOG(sFunctionRef..': tPotentialBomberSupportPoint='..repru(tPotentialBomberSupportPoint))
                            if tPotentialBomberSupportPoint then LOG(sFunctionRef..': Dist between tPotentialBomberSupportPoint and priority unit='..AiBotUtilities.GetDistanceBetweenPositions(tPotentialBomberSupportPoint, oPriorityUnitBeingSupported:GetPosition())..'; Dist between priority unit and current air support point='..AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint], oPriorityUnitBeingSupported:GetPosition())) end
                        end
                        if tPotentialBomberSupportPoint and
                                (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] <= 1000 or
                                        (AiBotUtilities.GetDistanceBetweenPositions(tPotentialBomberSupportPoint, oPriorityUnitBeingSupported:GetPosition()) <= 10 + AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint], oPriorityUnitBeingSupported:GetPosition()))) then
                            bDontWantToSupportExpOrACUInstead = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Will decide to support bomber instead of priority unit') end
                            --If we are protecting a friendly land exp, and our bomber threat has a greater mass value, then consider making the support point somewhere inbetween the two locations if it seems safe
                        elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] >= 9000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] >= 1500 and not(EntityCategoryContains(categories.AIR, oPriorityUnitBeingSupported.UnitId)) then
                            --May want to protect t3 bomber in priority to the enemy experimental
                            local iBomberToAARatio = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 2 / AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat]
                            local iEnemyAirVsExpRatio = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] / (oPriorityUnitBeingSupported[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oPriorityUnitBeingSupported))
                            if bDebugMessages == true then LOG(sFunctionRef..': iBomberToAARatio='..iBomberToAARatio..'; iEnemyAirVsExpRatio='..iEnemyAirVsExpRatio) end
                            if iBomberToAARatio > iEnemyAirVsExpRatio then
                                bDontWantToSupportExpOrACUInstead = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Bombers are in greater threat from enemy air than our experimental/unit to protect') end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bDontWantToSupportExpOrACUInstead='..tostring(bDontWantToSupportExpOrACUInstead)..'; Dist to support from t3 bomber='..AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])) end
            if bDontWantToSupportExpOrACUInstead then
                --Is our front bomber far from the support location?
                if AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]) >= 90 then
                    --Is the front bomber closer to the enemy than our front gunship?
                    local bBomberCloserThanGunship = false
                    local tFrontBomberData, tFrontBomberTeamData = AiBotMap.GetLandOrWaterZoneData(oBomber:GetPosition(), true, iTeam)
                    if tFrontBomberTeamData and AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tFrontBomberTeamData[AiBotMap.reftClosestFriendlyBase]) <= 125 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Bomber close enough to friendly base that dont need to worry about protecting it') end
                    else
                        if AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]) then
                            local tFrontGunshipData, tFrontGunshipTeamData = AiBotMap.GetLandOrWaterZoneData(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition(), true, iTeam)
                            local iDistToEnemyFromGunship = AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition(), tFrontGunshipTeamData[AiBotMap.reftClosestEnemyBase])
                            local iDistToEnemyFromBomber =  AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), (tFrontBomberTeamData[AiBotMap.reftClosestEnemyBase] or tFrontGunshipTeamData[AiBotMap.reftClosestEnemyBase]))
                            if bDebugMessages == true then LOG(sFunctionRef..': iDistToEnemyFromBomber='..iDistToEnemyFromBomber..'; iDistToEnemyFromGunship='..iDistToEnemyFromGunship) end
                            if iDistToEnemyFromBomber < 30 + iDistToEnemyFromGunship then
                                bBomberCloserThanGunship = true
                            elseif tFrontGunshipTeamData[AiBotMap.refiEnemyAirToGroundThreat] == 0 and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurT1ToT3BomberThreat] >= 6000  then
                                --If bomber support position woudl be closer then to gunship than the air rally point then use bomber support position
                                GetPotentialBomberSupportPoint(false)
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if gunship would be closer to bomber support than normal air support, tPotentialBomberSupportPoint='..repru(tPotentialBomberSupportPoint)) end
                                if tPotentialBomberSupportPoint then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Gunship dist to air support point='..AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])..'; Gunship dist to bomber support point='..AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition(), tPotentialBomberSupportPoint)) end
                                    if AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]) > AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition(), tPotentialBomberSupportPoint) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': If we shadow our strats we end up closer to our gunships than if we were at the air support point') end
                                        bBomberCloserThanGunship = true
                                    end
                                end
                            end
                        else
                            bBomberCloserThanGunship = true
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': bBomberCloserThanGunship='..tostring(bBomberCloserThanGunship)..'; tFrontBomberTeamData=nil='..tostring(tFrontBomberTeamData == nil)) end
                        if bBomberCloserThanGunship then
                            --Do we likely have multiple bombers assigned (strike damage 5k+), indicating a significant bomber attack?
                            local iStrikeDamage = 0
                            local iThreshold = 5000
                            local bHaveEnoughTargets = false
                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoActiveBomberTargets]) == false then
                                for iTarget, oTarget in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoActiveBomberTargets] do
                                    if bDebugMessages == true then LOG(sFunctionRef..': Currently targeting oTarget='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)..' with refiStrikeDamageAssigned='..(oTarget[refiStrikeDamageAssigned] or 'nil')) end
                                    iStrikeDamage = iStrikeDamage + (oTarget[refiStrikeDamageAssigned] or 0)
                                    if iStrikeDamage >= iThreshold then
                                        bHaveEnoughTargets = true
                                        break
                                    end
                                end
                            end
                            if bHaveEnoughTargets then
                                --Move the support point to be closer to the bomber, assuming can find a valid location
                                GetPotentialBomberSupportPoint(true)
                            end
                        end
                    end
                end
            end
        end
        local bDualGapBomberEscort = false
        for _, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
            if oBrain.AiBotDualGapRole == 'top_air' or oBrain.AiBotDualGapRole == 'bottom_air' or oBrain.AiBotDualGapRole == 'eco' then
                bDualGapBomberEscort = true
                break
            end
        end
        if AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber]) and (bDualGapBomberEscort or (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurT1ToT3BomberThreat] >= 4000 and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] and AiBotMap.iMapSize >= 512 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] >= 1500)) and (AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber][refoStrikeDamageAssigned]) or (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber][AiBotUnitInfo.refiLastBombFired] and GetGameTimeSeconds() - AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber][AiBotUnitInfo.refiLastBombFired] <= 15)) then
            bConsideredForT3Bomber = true
            ConsiderChangingSupportPointToSupportBomber(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber])
        end
        --Torp bombers

        if bDebugMessages == true then LOG(sFunctionRef..': Considering if should try and support torp bomber, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]='..(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]) or 'nil')..'; Have air control='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl])..'; AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber][refoStrikeDamageAssigned]='..(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber][refoStrikeDamageAssigned].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber][refoStrikeDamageAssigned]) or 'nil')..'; AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber][AiBotUnitInfo.refiLastBombFired]='..(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber][AiBotUnitInfo.refiLastBombFired] or 'nil')..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]) end
        if AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]) and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] and (AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber][refoStrikeDamageAssigned]) or (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber][AiBotUnitInfo.refiLastBombFired] and GetGameTimeSeconds() - AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber][AiBotUnitInfo.refiLastBombFired] <= 15)) and AiBotMap.iMapSize >= 512 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] >= 1500 then
            --Ignore if t3 bomber is almost further from rally than torp bomber
            local iTorpDistToRally = AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
            if iTorpDistToRally >= 50 and (not(bConsideredForT3Bomber) or AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber]:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]) + 40 < iTorpDistToRally) then
                if bDebugMessages == true then LOG(sFunctionRef..': Will consider a support point for torpedo bombers') end
                ConsiderChangingSupportPointToSupportBomber(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber], true)
            end
        end

        --Update the recorded support rally point to reflect the above, and record pathing of other land and air zones to it if havent previously
        local tStartLZOrWZData
        if bDebugMessages == true then LOG(sFunctionRef..': About to get the plateau and zone for air support point='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])..'; reftAirRallyPoint='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])..'; tPreferredRallyPoint='..repru(tPreferredRallyPoint)) end
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]) then
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]) then
                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = {tPreferredRallyPoint[1], tPreferredRallyPoint[2], tPreferredRallyPoint[3]}
            else
                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = {AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][1], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][2], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][3]}
            end
            if bDebugMessages == true then
                local iSupportPlateau, iSupportLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])
                LOG(sFunctionRef..': Updated air support point to be the rally point as we didnt have a support point from before, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])..'; AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])..'; Post change iSupportPlateau='..(iSupportPlateau or 'nil')..'; iSupportLZOrWZ='..(iSupportLZOrWZ or 'nil'))
            end
        end
        local tStartMidpoint = {AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][1], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][2], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][3]}
        if AiBotUtilities.IsTableEmpty(tStartMidpoint) == false then
            local iStartPlateau, iStartLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tStartMidpoint)
            if not(iStartPlateau) or not(iStartLZOrWZ) then
                --Record new land zone if we have a plateau, dont have a LZOrWZ, but do ahve an island (as e.g. we may have discounted it before due to being too small)
                if iStartPlateau and NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tStartMidpoint) then
                    local iSegmentX, iSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tStartMidpoint)
                    local tSegmentMidpoint = AiBotMap.GetPositionFromPathingSegments(iSegmentX, iSegmentZ)
                    local iSegmentPlateau, iSegmentZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tSegmentMidpoint)
                    if iSegmentPlateau and not(iSegmentZone) then
                        AiBotMap.CreateNewLandZoneAtSegment(iSegmentX, iSegmentZ, iSegmentPlateau)
                    end
                end

                --Need to adjust support point to a valid location
                local iAngleToBase = AiBotUtilities.GetAngleFromAToB(tStartMidpoint, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
                for iDistance = 10, 100, 10 do
                    tStartMidpoint = AiBotUtilities.MoveInDirection(tStartMidpoint, iAngleToBase, iDistance, true, false, not(AiBotMap.bIsCampaignMap))
                    iStartPlateau, iStartLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tStartMidpoint)
                    if bDebugMessages == true then LOG(sFunctionRef..': Trying to find a valid location, iDistance='..iDistance..'; iAngleToBase='..iAngleToBase..'; iStartPlateau='..(iStartPlateau or 'nil')..'; iStartLZOrWZ='..(iStartLZOrWZ or 'nil'))
                        if iStartPlateau and iStartLZOrWZ then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will update air sub support point to the revised tStartMidpoint='..repru(tStartMidpoint)) end
                            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = {tStartMidpoint[1], tStartMidpoint[2], tStartMidpoint[3]}
                            break
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iStartPlateau='..(iStartPlateau or 'nil')..'; iStartLZOrWZ='..(iStartLZOrWZ or 'nil')) end
            local tStartLZOrWZTeamData
            if ((iStartPlateau or 0) > 0 and (iStartLZOrWZ or 0) == 0) or iStartPlateau == 0 then
                iStartLZOrWZ = AiBotMap.GetWaterZoneFromPosition(tStartMidpoint)
                tSupportRallyPoint = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLZOrWZ]][AiBotMap.subrefPondWaterZones][iStartLZOrWZ][AiBotMap.subrefMidpoint]
                tStartLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLZOrWZ]][AiBotMap.subrefPondWaterZones][iStartLZOrWZ]
                tStartLZOrWZTeamData = tStartLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
            else
                tSupportRallyPoint = AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iStartLZOrWZ][AiBotMap.subrefMidpoint]
                tStartLZOrWZData = AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iStartLZOrWZ]
                tStartLZOrWZTeamData = tStartLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
            end
            if tStartLZOrWZData then
                --Move the support rally point towards the enemy base if we have air control and not close to LR enemy air
                if tLongRangeEnemyAirAAUnits and not(bDontMoveCloserToEnemyBase) then
                    for iLRAA, oLRAA in tLongRangeEnemyAirAAUnits do
                        if AiBotUtilities.GetDistanceBetweenPositions(oLRAA:GetPosition(), tStartMidpoint) <= oLRAA[AiBotUnitInfo.refiAARange] + 25 then
                            bDontMoveCloserToEnemyBase = true
                            break
                        end
                    end
                end
                if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] and not(bDontMoveCloserToEnemyBase) then
                    if tStartLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.5 then
                        local iDistToEnemyBase = AiBotUtilities.GetDistanceBetweenPositions(tStartMidpoint, tStartLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])
                        if iDistToEnemyBase >= 100 then
                            local iDistToOurBase = AiBotUtilities.GetDistanceBetweenPositions(tStartMidpoint, tStartLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])
                            local iMaxDistToTravel = math.min(iDistToEnemyBase - 100, (iDistToOurBase + iDistToEnemyBase) * 0.5 -  iDistToOurBase)
                            if iMaxDistToTravel >= 40 then
                                local iIntervalSize = 40
                                local iAngleToSupport = AiBotUtilities.GetAngleFromAToB(tStartMidpoint, tStartLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])
                                local iRallyPlateau, iRallyLZOrWZ
                                local tLastSafeRally
                                if bDebugMessages == true then LOG(sFunctionRef..': iAngleToSupport='..iAngleToSupport..'; base rally point='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])..'; Playable area='..repru(AiBotMap.rMapPlayableArea)..'; iMaxDistToTravel='..iMaxDistToTravel) end
                                --NOTE: Added alternative code in v240 largely as a redundancy - but could consider to siwtching to that approach meaning are much closer to ahwassa; danger is asfs all group together around the support point, and die to enemy SAMs; flipside is ahwassa dies to enemy air before our asfs can support; potential middle ground would be to stay c.60 between the priority unit to support and the rally point, and do a getunitsaroundpoint check to make sure not large amount of groundAA
                                for iCurDist = iIntervalSize, math.floor(iMaxDistToTravel / iIntervalSize) * iIntervalSize, iIntervalSize do
                                    local tPotentialNewRally = AiBotUtilities.MoveInDirection(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint], iAngleToSupport, iCurDist, true, false, true)
                                    if tPotentialNewRally then
                                        if bDebugMessages == true then LOG(sFunctionRef..': iCurDist='..iCurDist..'; tPotentialNewRally='..repru(tPotentialNewRally)) end
                                        iRallyPlateau, iRallyLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tPotentialNewRally)
                                        if (iRallyLZOrWZ or 0) > 0 then
                                            --Is this safe?
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering new plateau='..iRallyPlateau..'; new zone='..iRallyLZOrWZ..'; Does enemy have AA threat along path to here='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateau, iStartLZOrWZ, iRallyPlateau, iRallyLZOrWZ, false, 0, 0, false, iAirSubteam))) end
                                            if DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateau, iStartLZOrWZ, iRallyPlateau, iRallyLZOrWZ, false, 0, 0, false, iAirSubteam) then
                                                if bDebugMessages == true then LOG(sFunctionRef..'; Zone is not safe so will stop searching') end
                                                break
                                            else
                                                tLastSafeRally = {tPotentialNewRally[1], tPotentialNewRally[2], tPotentialNewRally[3]}
                                                if bDebugMessages == true then LOG(sFunctionRef..': Zone is safe so updating last safe rally to '..repru(tLastSafeRally)) end
                                            end
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Updating support zone location, last safe location after moving towards enemy base='..repru(tLastSafeRally)) end
                                if tLastSafeRally then
                                    iStartPlateau, iStartLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tSupportRallyPoint)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will update the support location to be the midpoint of plateau '..iStartPlateau..'; iStartLZOrWZ='..(iStartLZOrWZ or 'nil')) end
                                    if (iStartLZOrWZ or 0) > 0 then --redundancy
                                        if (iStartPlateau or 0) == 0 then
                                            --water zone
                                            tSupportRallyPoint = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLZOrWZ]][AiBotMap.subrefPondWaterZones][iStartLZOrWZ][AiBotMap.subrefMidpoint]
                                            tStartLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLZOrWZ]][AiBotMap.subrefPondWaterZones][iStartLZOrWZ]
                                            tStartLZOrWZTeamData = tStartLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                        else
                                            --land zone
                                            tSupportRallyPoint = AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iStartLZOrWZ][AiBotMap.subrefMidpoint]
                                            tStartLZOrWZData = AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iStartLZOrWZ]
                                            tStartLZOrWZTeamData = tStartLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                        end
                                        if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefMidpoint]) == false then
                                            tStartMidpoint = {tStartLZOrWZData[AiBotMap.subrefMidpoint][1], tStartLZOrWZData[AiBotMap.subrefMidpoint][2], tStartLZOrWZData[AiBotMap.subrefMidpoint][3]}
                                        else
                                            AiBotUtilities.ErrorHandler('No midpoint for P'..iStartPlateau..'; LZOrWZ '..iStartLZOrWZ)
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            else
                --Redundancy - go to rally point if lack air control, but if have air control then closely shadow the priority unit
                if bDebugMessages == true then LOG(sFunctionRef..': tStartPoint isnt on a valid plateau or LZ, so will just move from priority unit towards base') end
                if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] and oPriorityUnitBeingSupported and EntityCategoryContains(categories.AIR, oPriorityUnitBeingSupported.UnitId) then
                    local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oPriorityUnitBeingSupported:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
                    local iDistToRally = AiBotUtilities.GetDistanceBetweenPositions(  oPriorityUnitBeingSupported:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
                    if bDebugMessages == true then LOG(sFunctionRef..': iAngleToRally='..iAngleToRally..'; iDistToRally='..iDistToRally) end
                    for iCurDist = 40, math.min(iDistToRally, 160), 10 do
                        local tAltLocation = AiBotUtilities.MoveInDirection(oPriorityUnitBeingSupported:GetPosition(), iAngleToRally, iCurDist)
                        if bDebugMessages == true then LOG(sFunctionRef..': iCurDist='..iCurDist..'; tAltLocation='..repru(tAltLocation)..'; Hover label='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tAltLocation) or 'nil')) end
                        if tAltLocation and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tAltLocation) then
                            local iCurSegX, iCurSegZ = AiBotMap.GetPathingSegmentFromPosition(tAltLocation)
                            if bDebugMessages == true then LOG(sFunctionRef..': Water zone for these segments='..(AiBotMap.tWaterZoneBySegment[iCurSegX][iCurSegZ] or 'nil')..'; Land zone for these segments='..(AiBotMap.tLandZoneBySegment[iCurSegX][iCurSegZ] or 'nil')) end
                            if AiBotMap.tWaterZoneBySegment[iCurSegX][iCurSegZ] or AiBotMap.tLandZoneBySegment[iCurSegX][iCurSegZ] then
                                if bDebugMessages == true then LOG(sFunctionRef..'; Have a pahtable location so will pick here, iCurDist='..iCurDist) end
                                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = {tAltLocation[1], tAltLocation[2], tAltLocation[3]}
                                tStartLZOrWZData, tStartLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(tAltLocation, true, iTeam)
                                break
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': About to record the land and water zones by order of distance to tStartLZOrWZData, is tStartLZOrWZData nil='..tostring(tStartLZOrWZData == nil)) end
            if not(tStartLZOrWZData) then
                --Update sub rally point to the actual rally point
                if bDebugMessages == true then LOG(sFunctionRef..'; Dont have valid LZ or WZ for the sub rally point, so will make it the actual rally point') end
                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = {AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][1], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][2], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][3]}
                if tStartMidpoint then
                    iStartPlateau, iStartLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tStartMidpoint)
                    if iStartPlateau == 0 and (iStartLZOrWZ or 0) > 0 then
                        tStartLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLZOrWZ]][AiBotMap.subrefPondWaterZones][iStartLZOrWZ]
                    elseif (iStartLZOrWZ or 0) > 0 then
                        tStartLZOrWZData = AiBotMap.tAllPlateaus[iStartPlateau][AiBotMap.subrefPlateauLandZones][iStartLZOrWZ]
                    else
                        AiBotUtilities.ErrorHandler('Couldnt find LZ or WZ close to tStartMidpoint')
                        LOG(sFunctionRef..': tStartMidpoint='..repru(tStartMidpoint))
                    end
                else
                    AiBotUtilities.ErrorHandler('No tStartMidpoint set')
                end
            end
            if tStartLZOrWZData then
                RecordOtherLandAndWaterZonesByDistance(tStartLZOrWZData)
            end


            --If have air control then move the rally point to be closer to the support point (will already ignore if enemy has LR air due to earlier check that sets bDontMoveCloserToEnemyBase to true)

            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to move rally point closer to support point, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] or false)) end

            if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] and not(bDontMoveCloserToEnemyBase) then
                local iDistBetweenSupportAndRally = AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
                if iDistBetweenSupportAndRally >= 100 then
                    local iIntervalSize = 50
                    local iAngleToSupport = AiBotUtilities.GetAngleFromAToB(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])
                    local iRallyPlateau, iRallyLZOrWZ
                    local tLastSafeRally
                    local iStartPlateauOrZero, iStartLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
                    if bDebugMessages == true then LOG(sFunctionRef..': iAngleToSupport='..iAngleToSupport..'; iDistBetweenSupportAndRally='..iDistBetweenSupportAndRally) end
                    for iCurDist = iIntervalSize, math.floor((iDistBetweenSupportAndRally - iIntervalSize) / iIntervalSize) * iIntervalSize, iIntervalSize do
                        local tPotentialNewRally = AiBotUtilities.MoveInDirection(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint], iAngleToSupport, iCurDist, true, false, true)
                        if tPotentialNewRally then
                            iRallyPlateau, iRallyLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tPotentialNewRally)
                            if (iRallyLZOrWZ or 0) > 0 then
                                --Is this safe?
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering iRallyPlateau='..iRallyPlateau..'; iRallyLZOrWZ='..iRallyLZOrWZ..'; Does enemy have AA threat along path to here='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iRallyPlateau, iRallyLZOrWZ, false, 0, 0, false, iAirSubteam))) end
                                if DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iRallyPlateau, iRallyLZOrWZ, false, 0, 0, false, iAirSubteam) then
                                    if bDebugMessages == true then LOG(sFunctionRef..'; Zone is not safe so will stop searching') end
                                    break
                                else
                                    tLastSafeRally = {tPotentialNewRally[1], tPotentialNewRally[2], tPotentialNewRally[3]}
                                    if bDebugMessages == true then LOG(sFunctionRef..': Zone is safe so updating last safe rally to '..repru(tLastSafeRally)) end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': tLastSafeRally='..repru(tLastSafeRally)) end
                    if tLastSafeRally then
                        AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint] = {tLastSafeRally[1], tLastSafeRally[2], tLastSafeRally[3]}
                    end
                end
            end

            --Search for if enemy has significant AirAA within 200 of support point, and if so if the mod distance is <= ours, in which case rework the support and rally points (to avoid us deciding not to attack the AirAA threat, and instead suiciding air units on their way to the rally point)
            local tSupportRallyLZData, tSupportRallyLZTeamData = AiBotMap.GetLandOrWaterZoneData(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint], true, iTeam)
            if bDebugMessages == true then LOG(sFunctionRef..': Considering moving support point back again if nearby enemy airaa threat, tSupportRallyLZTeamData[AiBotMap.refiModDistancePercent]='..tSupportRallyLZTeamData[AiBotMap.refiModDistancePercent]) end
            if AiBotUtilities.IsTableEmpty(tSupportRallyLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false and tSupportRallyLZTeamData[AiBotMap.refiModDistancePercent] >= 0.15 then
                local iAirAAThreshold = math.max(150, (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] or 0) * 0.2)
                local iLowestAirAAModDist = 100
                for iEntry, tSubtable in tSupportRallyLZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                    if tSubtable[AiBotMap.subrefiDistance] >= 200 then break end
                    local tCurLZOrWZData, tCurLZOrWZTeamData
                    if tSubtable[AiBotMap.subrefbIsWaterZone] then
                        tCurLZOrWZData = AiBotMap.tPondDetails[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                        tCurLZOrWZTeamData = tCurLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                    else
                        tCurLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                        tCurLZOrWZTeamData = tCurLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                    end
                    if (tCurLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) > iAirAAThreshold then
                        iLowestAirAAModDist = math.min(iLowestAirAAModDist, tCurLZOrWZTeamData[AiBotMap.refiModDistancePercent])
                    elseif tLongRangeEnemyAirAAUnits then
                        local tLRAlmostInRange = {}
                        local iLRThreatInRange = 0
                        for iLRAA, oLRAA in tLongRangeEnemyAirAAUnits do
                            if AiBotUtilities.GetDistanceBetweenPositions(oLRAA:GetPosition(), tCurLZOrWZData[AiBotMap.subrefMidpoint]) <= oLRAA[AiBotUnitInfo.refiAARange] + 16 then --Reduced range since we might be protecting air exp per earlier logic
                                table.insert(tLRAlmostInRange, oLRAA)
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(tLRAlmostInRange) == false then
                            if AiBotUtilities.bCPUPerformanceMode then
                                iLRThreatInRange = AiBotUnitInfo.GetMassCostOfUnits(tLRAlmostInRange)
                            else
                                iLRThreatInRange = AiBotUnitInfo.GetAirThreatLevel(tLRAlmostInRange, true, true, false, false, false, false)
                            end
                        end
                        if iLRThreatInRange > 0.5 * iAirAAThreshold then
                            iLowestAirAAModDist = math.min(iLowestAirAAModDist, tCurLZOrWZTeamData[AiBotMap.refiModDistancePercent])
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Searched nearby zones iwthin a distance of 200, iLowestAirAAModDist='..iLowestAirAAModDist..'; tSupportRallyLZTeamData[AiBotMap.refiModDistancePercent]='..tSupportRallyLZTeamData[AiBotMap.refiModDistancePercent]) end
                if iLowestAirAAModDist <= tSupportRallyLZTeamData[AiBotMap.refiModDistancePercent] then
                    local tRallyLZData, tRallyLZTeamData = AiBotMap.GetLandOrWaterZoneData(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint], true, iTeam)
                    if bDebugMessages == true then LOG(sFunctionRef..': Rally point mod dist%='..tRallyLZTeamData[AiBotMap.refiModDistancePercent]) end
                    if tRallyLZTeamData[AiBotMap.refiModDistancePercent] < tSupportRallyLZTeamData[AiBotMap.refiModDistancePercent] then
                        --Make teh support point the rally point instead
                        if bDebugMessages == true then LOG(sFunctionRef..': Will make the support point the rally point') end
                        AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = {AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][1], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][2], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][3]}
                    end
                end
            end

            --Campaign - if not in playable area then change
            if AiBotMap.bIsCampaignMap then
                if not(AiBotConditions.IsLocationInPlayableArea(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])) then
                    --Update the rally point
                    local tLocation = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
                    if tLocation[1] < AiBotMap.rMapPlayableArea[1] then
                        tLocation[1] = AiBotMap.rMapPlayableArea[1]
                    elseif tLocation[1] > AiBotMap.rMapPlayableArea[3] then
                        tLocation[1] = AiBotMap.rMapPlayableArea[3]
                    end
                    if tLocation[3] < AiBotMap.rMapPlayableArea[2] then
                        tLocation[3] = AiBotMap.rMapPlayableArea[2]
                    elseif tLocation[3] > AiBotMap.rMapPlayableArea[4] then
                        tLocation[3] = AiBotMap.rMapPlayableArea[4]
                    end
                    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint] = {tLocation[1], tLocation[2], tLocation[3]}
                end
                if not(AiBotConditions.IsLocationInPlayableArea(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])) then
                    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = {AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][1], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][2], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][3]}
                end
            end

            --Final adjustment - if have any recent nuke launch locations that are near either the rally point or support point,  then move away from here
            if bDebugMessages == true then LOG(sFunctionRef..': Considering moving rally point for nuke, is subrefNukeLaunchLocations empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations]))) end
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations]) == false then
                local iTimeThreshold = math.max(10, 60 * AiBotMap.iMapSize / 1000) + 10
                local iReassessCount = 0
                local iAngleToBase
                local iDistThreshold = 60
                local bRallyIsntNear = true
                local bSupportIsntNear = true
                if bDebugMessages == true then LOG(sFunctionRef..': Checking if air rally or support points are near a recent nuke launch location, Rally='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])..' is near nuke='..tostring(AiBotConditions.IsTargetNearActiveNukeTarget(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint], iTeam, iDistThreshold, iTimeThreshold))..'; Support='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])..'; is near nuke='..tostring(AiBotConditions.IsTargetNearActiveNukeTarget(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint], iTeam, iDistThreshold, iTimeThreshold))) end
                while AiBotConditions.IsTargetNearActiveNukeTarget(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint], iTeam, iDistThreshold, iTimeThreshold) do
                    iReassessCount = iReassessCount + 1
                    if not(iAngleToBase) then iAngleToBase = AiBotUtilities.GetAngleFromAToB(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint], tStartMidpoint) end
                    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint] = AiBotUtilities.MoveInDirection(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint], iAngleToBase, iDistThreshold * iReassessCount, true, false, not(AiBotMap.bIsCampaignMap))
                    if bDebugMessages == true then LOG(sFunctionRef..': Moving rally point due to nuke, iReassessCount='..iReassessCount..'; revised rally='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])..'; iANgleToBase='..iAngleToBase..'; Distance='.. iDistThreshold * iReassessCount) end
                    if iReassessCount >= 5 then
                        bRallyIsntNear = false
                        break
                    end
                end
                iAngleToBase = nil
                while AiBotConditions.IsTargetNearActiveNukeTarget(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint], iTeam, iDistThreshold, iTimeThreshold) do
                    iReassessCount = iReassessCount + 1
                    if not(iAngleToBase) then iAngleToBase = AiBotUtilities.GetAngleFromAToB(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint], tStartMidpoint) end
                    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = AiBotUtilities.MoveInDirection(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint], iAngleToBase, iDistThreshold * iReassessCount, true, false, not(AiBotMap.bIsCampaignMap))
                    if bDebugMessages == true then LOG(sFunctionRef..': Moving support point due to nuke, iReassessCount='..iReassessCount..'; revised support location='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])..'; dist='..iDistThreshold * iReassessCount) end
                    if iReassessCount >= 5 then
                        if bRallyIsntNear then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will use rally point instead of support point as support point still in range of nuke') end
                            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] = {AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][1], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][2], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][3]}
                        else
                            bSupportIsntNear = false
                        end
                        break
                    end
                end
                if bRallyIsntNear and not(bSupportIsntNear)
                        --Redundancy to be sure
                        and not(AiBotConditions.IsTargetNearActiveNukeTarget(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint], iTeam, iDistThreshold, iTimeThreshold))
                then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will make the rally point the air support point instead to avoid a nuke') end
                    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint] = {AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][1], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][2], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][3]}
                end
            end
            if bDebugMessages == true then
                LOG(sFunctionRef..'; Will draw air sub rally point in blue at '..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])) AiBotUtilities.DrawLocation(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint], nil, 10, 10)
                LOG(sFunctionRef..': SupportPoint='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])..'; Will draw in gold') AiBotUtilities.DrawLocation(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint], 4, 10, 10)

            end
        else
            AiBotUtilities.ErrorHandler('No air support point for air subteam '..iAirSubteam)
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetUnitAirStagingSize(oUnit)
    --Manually confirmed - ambassador takes up 4 spaces, janus, inties and asf take up 1, broadswords and solace take up 2 spaces
    if EntityCategoryContains(categories.TECH3 * AiBotUnitInfo.refCategoryBomber, oUnit.UnitId) then
        return 4
    elseif EntityCategoryContains(categories.TECH3 - AiBotUnitInfo.refCategoryAirAA, oUnit.UnitId) then
        return 2
    else return 1
    end
end

function SendUnitsForRefueling(tUnitsForRefueling, iTeam, iAirSubteam, bDontReleaseHealedUnits)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'OrderUnitsToRefuel'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    --Sends low fuel units to air staging
    --if AiBotUtilities.IsTableEmpty(tUnitsForRefueling) == false then
    --Get available air staging units - Only consider actual air staging buildings for these purposes, or else risk interfering with other logic
    local tAirStagingUnitsAndCapacity = {}
    local subrefoUnit = 1
    local subrefiCapacity = 2
    local iMaxCapacity, iCapacityInUse



    for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
        local tCurBrainStaging = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAirStaging, false, true)
        if AiBotUtilities.IsTableEmpty(tCurBrainStaging) == false then
            local bDontCheckPlayableArea = not(AiBotMap.bIsCampaignMap)
            for iUnit, oAirStaging in tCurBrainStaging do
                if AiBotUnitInfo.IsUnitValid(oAirStaging) and oAirStaging:GetFractionComplete() == 1 and (bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(oAirStaging:GetPosition())) then
                    --Does this have capacity?
                    iMaxCapacity = 4
                    if EntityCategoryContains(categories.MOBILE, oAirStaging.UnitId) then
                        if EntityCategoryContains(categories.EXPERIMENTAL, oAirStaging.UnitId) then iMaxCapacity = 40
                        else iMaxCapacity = 1
                        end
                    end

                    iCapacityInUse = 0
                    --First check for air staging cargo and release if they are all at full health
                    local bCargoReadyToRelease = false
                    local tCargo = oAirStaging:GetCargo()
                    if AiBotUtilities.IsTableEmpty(tCargo) == false then

                        for iCargo, oCargo in tCargo do
                            if oCargo.GetFuelRatio and EntityCategoryContains(categories.MOBILE, oCargo.UnitId) then --some mods add units as part of the cargo
                                bCargoReadyToRelease = true
                                if oCargo:GetFuelRatio() < 1 or AiBotUnitInfo.GetUnitHealthPercent(oCargo) < 1 then
                                    bCargoReadyToRelease = false
                                    break
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering air staging unit '..oAirStaging.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAirStaging)..'; Is tCargo empty='..tostring(AiBotUtilities.IsTableEmpty(tCargo))..'; bCargoReadyToRelease='..tostring(bCargoReadyToRelease)..'; Is oAirStaging[reftAssignedRefuelingUnits] empty='..tostring(AiBotUtilities.IsTableEmpty(oAirStaging[reftAssignedRefuelingUnits]))) end
                    if bCargoReadyToRelease then
                        if not(bDontReleaseHealedUnits) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will try and release all units in air staging '..oAirStaging.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAirStaging)) end
                            AiBotOrders.ReleaseStoredUnits(oAirStaging, false, 'ASUnl', false)
                            --Dont clear unit status as should happen automatically in next cycle; dont consider sending units to it this cycle
                        end
                    else
                        if AiBotUtilities.IsTableEmpty(oAirStaging[reftAssignedRefuelingUnits]) == false then
                            --Remove any invalid units or units whose order isn't to refuel
                            local iUnitCount = table.getn(oAirStaging[reftAssignedRefuelingUnits])
                            for iCurUnit = iUnitCount, 1, -1 do
                                local oRefuelingUnit = oAirStaging[reftAssignedRefuelingUnits][iCurUnit]
                                if AiBotUnitInfo.IsUnitValid(oRefuelingUnit) then
                                    local tLastOrder = oRefuelingUnit[AiBotOrders.reftiLastOrders][oRefuelingUnit[AiBotOrders.refiOrderCount]]
                                    if oRefuelingUnit:IsUnitState('Attached') then
                                        iCapacityInUse = iCapacityInUse + GetUnitAirStagingSize(oRefuelingUnit)
                                        if bDebugMessages == true then LOG(sFunctionRef..': oRefuelingUnit='..oRefuelingUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRefuelingUnit)..', is assigned to air staging '..oAirStaging.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAirStaging)..' and is attached, Size of this unit='..GetUnitAirStagingSize(oRefuelingUnit)..'; Capacity in use='..iCapacityInUse) end
                                    elseif (tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderRefuel and tLastOrder[AiBotOrders.subrefoOrderUnitTarget] == oAirStaging) then
                                        --Unit is still assigned here and has orders to get here
                                        iCapacityInUse = iCapacityInUse + GetUnitAirStagingSize(oRefuelingUnit)
                                        --Refresh orders due to issue where a unit can sometimes be told to refuel but doesn't (seems particularly likely in LOUD)
                                        AiBotOrders.UpdateRecordedOrders(oRefuelingUnit)
                                        if bDebugMessages == true then LOG(sFunctionRef..' Staging has been assigned to oRefuelingUnit='..oRefuelingUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRefuelingUnit)..'; Size of this unit='..GetUnitAirStagingSize(oRefuelingUnit)..'; Capacity in use='..iCapacityInUse..'; Order count post refresh for refueling unit='..(oRefuelingUnit[AiBotOrders.refiOrderCount] or 'nil')..'; Unit state='..AiBotUnitInfo.GetUnitState(oRefuelingUnit)) end
                                    else
                                        --Unit has other orders so remove from here
                                        table.remove(oAirStaging[reftAssignedRefuelingUnits], iCurUnit)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Removing unit '..oRefuelingUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRefuelingUnit)..' as it has other orders now; Unit state='..AiBotUnitInfo.GetUnitState(oRefuelingUnit)..'; tLastOrder[AiBotOrders.subrefoOrderUnitTarget]='..(tLastOrder[AiBotOrders.subrefoOrderUnitTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) or 'nil')..'; air staging it is recorded against='..oAirStaging.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAirStaging)) end
                                    end
                                else
                                    --Unit is dead so remove from this list
                                    table.remove(oAirStaging[reftAssignedRefuelingUnits], iCurUnit)
                                end
                            end
                        end
                        if iMaxCapacity > iCapacityInUse then
                            table.insert(tAirStagingUnitsAndCapacity, {[subrefoUnit] = oAirStaging, [subrefiCapacity] = iMaxCapacity - iCapacityInUse})
                        end
                    end
                end
            end
        end
    end

    local tUnitsUnableToRefuel = {}
    local tPriorityUnitsForRefueling = {}
    local tLowerPriorityUnitsForRefueling = {}
    if bDebugMessages == true then LOG(sFunctionRef..': Is table of tAirStagingUnitsAndCapacity empty='..tostring(AiBotUtilities.IsTableEmpty(tAirStagingUnitsAndCapacity))) end
    if AiBotUtilities.IsTableEmpty(tAirStagingUnitsAndCapacity) then
        tUnitsUnableToRefuel = tUnitsForRefueling
    else
        --Have air staging available for units to refuel, cycle through each air unit and find the closest air staging to it that has sufficient capacity to take it
        local iClosestAirStagingDist, iCurDist, iClosestAirStagingRef
        local iCurSize
        if tUnitsForRefueling then
            --Sort between higher and lower priority units for refueling
            for iUnit, oAirUnit in tUnitsForRefueling do
                if AiBotUnitInfo.GetUnitHealthPercent(oAirUnit) <= 0.8 or (oAirUnit.GetFuelRatio and oAirUnit:GetFuelRatio() <= 0.1) then
                    table.insert(tPriorityUnitsForRefueling, oAirUnit)
                else
                    table.insert(tLowerPriorityUnitsForRefueling, oAirUnit)
                end
            end
        end

        function SendUnitsToRefuelAtClosestAvailableAirStaging(tUnitsToSendForRefueling)
            if AiBotUtilities.IsTableEmpty(tUnitsToSendForRefueling) == false then
                for iUnit, oAirUnit in tUnitsToSendForRefueling do
                    if AiBotUnitInfo.IsUnitValid(oAirUnit) and not(oAirUnit:IsUnitState('Attached')) then
                        if EntityCategoryContains(categories.CANNOTUSEAIRSTAGING + categories.EXPERIMENTAL, oAirUnit.UnitId) then
                            table.insert(tUnitsUnableToRefuel, oAirUnit)
                        else
                            iClosestAirStagingDist = 100000
                            iClosestAirStagingRef = nil
                            iCurSize = GetUnitAirStagingSize(oAirUnit)
                            if AiBotUtilities.IsTableEmpty(tAirStagingUnitsAndCapacity) == false then
                                for iAirStagingRef, tSubtable in tAirStagingUnitsAndCapacity do
                                    if bDebugMessages == true then LOG(sFunctionRef..': Looking for closest air staging '..(tSubtable[subrefoUnit].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tSubtable[subrefoUnit]) or 'nil')..', iAirStagingRef='..(iAirStagingRef or 'nil')..'; tSubtable[subrefiCapacity]='..(tSubtable[subrefiCapacity] or 'nil')..'; Unit that is trying to refuel size='..(iCurSize or 'nil')) end
                                    if tSubtable[subrefiCapacity] >= iCurSize then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tSubtable[subrefoUnit]:GetPosition(), oAirUnit:GetPosition())
                                        if bDebugMessages == true then LOG(sFunctionRef..': iCurDist='..iCurDist..'; iClosestAirStagingDist='..(iClosestAirStagingDist or 'nil')) end
                                        if iCurDist < iClosestAirStagingDist then
                                            --Further adjustment - air staging that isn't in a decent direction vs nearest enemy base should have a distance increase
                                            local tAirStagingLZOrWZData, tAirStagingLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(tSubtable[subrefoUnit]:GetPosition(), true, iTeam)
                                            if tAirStagingLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] then
                                                iClosestAirStagingRef = iCurDist
                                                iClosestAirStagingRef = iAirStagingRef
                                                if bDebugMessages == true then LOG(sFunctionRef..': Air staging is in a core zone, updating closest dist to this') end
                                            else
                                                iCurDist = iCurDist + 10
                                                local iAngleFromAirUnitToStaging = AiBotUtilities.GetAngleFromAToB(oAirUnit:GetPosition(), tSubtable[subrefoUnit]:GetPosition())
                                                local iAngleFromAirUnitToNearestEnemy = AiBotUtilities.GetAngleFromAToB(oAirUnit:GetPosition(), tAirStagingLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])
                                                local iAngleDif = AiBotUtilities.GetAngleDifference(iAngleFromAirUnitToStaging, iAngleFromAirUnitToNearestEnemy)
                                                if iAngleDif <= 155 then
                                                    if iAngleDif <= 100 then
                                                        iCurDist = iCurDist + 250
                                                    else
                                                        iCurDist = iCurDist + 150
                                                    end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Have air staging that is in a minor LZ, iCurDist after adjustments='..iCurDist..'; iAngleDif='..iAngleDif) end
                                                if iCurDist < iClosestAirStagingDist then
                                                    iClosestAirStagingRef = iCurDist
                                                    iClosestAirStagingRef = iAirStagingRef
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering unit wanting refueling='..oAirUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAirUnit)..'; iCurSize='..iCurSize..'; iClosestAirStagingRef='..(iClosestAirStagingRef or 'nil')..'; iClosestAirStagingDist='..iClosestAirStagingDist) end
                            if iClosestAirStagingRef then
                                local oClosestAirStaging = tAirStagingUnitsAndCapacity[iClosestAirStagingRef][subrefoUnit]
                                AiBotOrders.IssueTrackedRefuel(oAirUnit, oClosestAirStaging, false, 'Refuel', false)
                                local bRecordRefuelingUnit = true
                                if not(oClosestAirStaging[reftAssignedRefuelingUnits]) then oClosestAirStaging[reftAssignedRefuelingUnits] = {}
                                else
                                    for iRecordedUnit, oRecordedUnit in oClosestAirStaging[reftAssignedRefuelingUnits] do
                                        if oRecordedUnit == oAirUnit then
                                            bRecordRefuelingUnit = false
                                            break
                                        end
                                    end
                                end
                                if bRecordRefuelingUnit then
                                    table.insert(oClosestAirStaging[reftAssignedRefuelingUnits], oAirUnit)
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Just told unit '..oAirUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAirUnit)..' to refuel at '..oClosestAirStaging.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestAirStaging)..'; size of oClosestAirStaging[reftAssignedRefuelingUnits]='..table.getn(oClosestAirStaging[reftAssignedRefuelingUnits])..'; Available capacity pre this order='..tAirStagingUnitsAndCapacity[iClosestAirStagingRef][subrefiCapacity]..'; iCurSize='..iCurSize) end
                                if tAirStagingUnitsAndCapacity[iClosestAirStagingRef][subrefiCapacity] <= iCurSize then
                                    table.remove(tAirStagingUnitsAndCapacity, iClosestAirStagingRef)
                                else
                                    tAirStagingUnitsAndCapacity[iClosestAirStagingRef][subrefiCapacity] = tAirStagingUnitsAndCapacity[iClosestAirStagingRef][subrefiCapacity] - iCurSize
                                end
                            else
                                table.insert(tUnitsUnableToRefuel, oAirUnit)
                            end
                        end
                    end
                end
            end
        end

        if AiBotUtilities.IsTableEmpty(tPriorityUnitsForRefueling) == false then
            SendUnitsToRefuelAtClosestAvailableAirStaging(tPriorityUnitsForRefueling)
        end
        if AiBotUtilities.IsTableEmpty(tLowerPriorityUnitsForRefueling) == false then
            if AiBotUtilities.IsTableEmpty(tAirStagingUnitsAndCapacity) then
                for iAirUnit, oAirUnit in tLowerPriorityUnitsForRefueling do
                    table.insert(tUnitsUnableToRefuel, oAirUnit)
                end
            else
                SendUnitsToRefuelAtClosestAvailableAirStaging(tLowerPriorityUnitsForRefueling)
            end
        end
    end
    --Send any units that couldnt be refueld to the closest friendly base air rally point
    if AiBotUtilities.IsTableEmpty(tUnitsUnableToRefuel) == false then
        local bWantMoreAirStaging = false
        for iUnit, oUnit in tUnitsUnableToRefuel do
            if not(EntityCategoryContains(categories.EXPERIMENTAL + categories.CANNOTUSEAIRSTAGING + AiBotUnitInfo.refCategoryTransport, oUnit.UnitId)) then
                if bDebugMessages == true then LOG(sFunctionRef..': Have unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' that wants to refuel but has no air staging, unit owned by player '..oUnit:GetAIBrain().Nickname) end
                bWantMoreAirStaging = true
                break
            end
        end

        if bWantMoreAirStaging then AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastAirStagingShortage] = GetGameTimeSeconds() end
        local tRallyPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
        local tRallyLZData, tRallyLZTeamData = AiBotMap.GetLandOrWaterZoneData(tRallyPoint, true, iTeam)
        if bDebugMessages == true then LOG(sFunctionRef..': Flagged that we want air staging for units on team '..iTeam..' at time '..GetGameTimeSeconds()..' unless we only have low health exp, bWantMoreAirStaging='..tostring(bWantMoreAirStaging)..'; tRallyPoint='..repru(tRallyPoint)..'; Plateau label='..(NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tRallyPoint) or 'nil')..'; LandZone='..(AiBotMap.GetLandZoneFromPosition(tRallyPoint) or 'nil')..'; reftClosestFriendlyBase to rally point='..repru(tRallyLZTeamData[AiBotMap.reftClosestFriendlyBase])) end
        local tRefuelBase
        if tRallyLZTeamData[AiBotMap.reftClosestFriendlyBase] and (not(AiBotMap.bIsCampaignMap) or AiBotConditions.IsLocationInPlayableArea(tRallyLZTeamData[AiBotMap.reftClosestFriendlyBase])) then tRefuelBase = tRallyLZTeamData[AiBotMap.reftClosestFriendlyBase] else tRefuelBase = tRallyPoint end
        local iDistToReissueOrder = 10 --If the target location is safe then this is increased so that air units idle on hte ground to save fuel
        if ((AiBotUtilities.IsTableEmpty(tAirStagingUnitsAndCapacity) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLowestFriendlyAirFactoryTech] == 1 or (AiBotOverseer.bUnitRestrictionsArePresent and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryAirStaging) == 0))) or table.getn(tUnitsUnableToRefuel) >= 10)
                and AiBotConditions.IsAirMoveLocationSafeToIdle(tRefuelBase, iTeam, false) then iDistToReissueOrder = 60 end
        --If close to unit cap consider ctrl-King unit if it is close to the rally point
        if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= 0 and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap] or -100) <= 10 then
            --Ctrlk units if close to rally point and aibrain owner is close to unit cap
            local iCtrlKCount = 0
            for iUnit, oUnit in tUnitsUnableToRefuel do
                if not(EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId)) and oUnit:GetAIBrain()[AiBotOverseer.refbCloseToUnitCap] and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint) <= 10 and iCtrlKCount < 3 and (not(oUnit[AiBotUnitInfo.refbCampaignTriggerAdded]) or not(AiBotMap.bIsCampaignMap))
                        and (oUnit:GetFuelRatio() <= 0.4 or AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= 0.5) then
                    iCtrlKCount = iCtrlKCount + 1
                    ForkThread(AiBotMicro.MoveAndKillAirUnit,oUnit)
                    --AiBotOrders.IssueTrackedKillUnit(oUnit)
                elseif AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRefuelBase) <= iDistToReissueOrder then
                    --Do nothing, want air unit to idle on ground
                else
                    AiBotOrders.IssueTrackedMove(oUnit, tRefuelBase, iDistToReissueOrder, false, 'UCWntStgn', false)
                end
            end
        else
            --Send units to rally point, unless lots of low fuel in which case consider ctrlking 1 unit (assuming we are past the first 10m)
            local bConsiderKillingUnits = false
            if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 100) <= -1 then bConsiderKillingUnits = true
            else
                local iLowFuelUnits = table.getn(tUnitsUnableToRefuel)
                if iLowFuelUnits >= 10 and GetGameTimeSeconds() >= math.max(150, 600 / AiBotTeam.tTeamData[iTeam][AiBotTeam.refiHighestBrainBuildMultiplier]) then
                    local iTotalCurAirStaging = 0
                    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                        iTotalCurAirStaging = iTotalCurAirStaging + oBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryAirStaging)
                    end
                    if iTotalCurAirStaging == 0 or iLowFuelUnits / iTotalCurAirStaging >= 10 then
                        bConsiderKillingUnits = true
                    end
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': bConsiderKillingUnits='..tostring(bConsiderKillingUnits)) end
            for iUnit, oUnit in tUnitsUnableToRefuel do
                if bDebugMessages == true then LOG(sFunctionRef..': Telling unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to move to refuel location, special micro active='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Cur dist to tRefuelBase='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRefuelBase)) end
                if bConsiderKillingUnits and ((AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLowestUnitCapAdjustmentLevel] or 0) < 0 or oUnit:GetFuelRatio() <= 0.1 and oUnit:GetFuelRatio() >= 0 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint) <= 10 and (not(oUnit[AiBotUnitInfo.refbCampaignTriggerAdded]) or not(AiBotMap.bIsCampaignMap))) and (not(EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId) or AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= 0.2)) then --(experimental condition is a redundancy)
                    if bDebugMessages == true then LOG(sFunctionRef..': Will kill unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' with fuel %='..oUnit:GetFuelRatio()..' and health='..AiBotUnitInfo.GetUnitHealthPercent(oUnit)..' that is distance='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint)..' to the rally point') end
                    ForkThread(AiBotMicro.MoveAndKillAirUnit,oUnit)
                    --AiBotOrders.IssueTrackedKillUnit(oUnit)
                    bConsiderKillingUnits = false --max one per second
                elseif AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRefuelBase) <= iDistToReissueOrder then
                    --Do nothing, want air unit to idle on ground
                else
                    AiBotOrders.IssueTrackedMove(oUnit, tRefuelBase, iDistToReissueOrder, false, 'WntStgn', false)
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef .. ': Finished giving orders for refueling, was tUnitsUnableToRefuel empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsUnableToRefuel))) end
    --end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function TargetUnitWithAirAA(oAirAA, oEnemyUnit, iOptionalClosestDist)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'TargetUnitWithAirAA'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotConditions.IsLocationInPlayableArea(oEnemyUnit:GetPosition()) then
        local iClosestUnitDist = iOptionalClosestDist or AiBotUtilities.GetDistanceBetweenPositions(oAirAA:GetPosition(), oEnemyUnit:GetPosition())
        --Suicide asf into enemy czar or experimental bomber once relatively close; alternativley issua manual attack order when getting close as wehn doing move ended up losing 60 asfs and not even breaking the shield; also manual attack order on exp bomber
        if bDebugMessages == true then LOG(sFunctionRef..': oAirAA='..(oAirAA.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oAirAA) or 'nil')..'; .Dead='..tostring(oAirAA.Dead or false)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oAirAA))..'; oEnemyUnit='..(oEnemyUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEnemyUnit) or 'nil')..'; Is oEnemyUnit valid='..tostring(AiBotUnitInfo.IsUnitValid(oEnemyUnit))..'; iClosestUnitDist='..iClosestUnitDist..'; oAirAA[AiBotUnitInfo.refiAARange]='..(oAirAA[AiBotUnitInfo.refiAARange] or 'nil')) end
        if iClosestUnitDist <= 70 and EntityCategoryContains(AiBotUnitInfo.refCategoryCzar + AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL, oEnemyUnit.UnitId) then
            ForkThread(SuicideASFIntoStrat, oEnemyUnit, oAirAA, true) --Must call via fork thread due to waitticks)
            --If enemy on ground then issue attack
        elseif oEnemyUnit:GetCurrentLayer() == 'Land' or oEnemyUnit:GetPosition()[2] - GetSurfaceHeight(oEnemyUnit:GetPosition()[1], oEnemyUnit:GetPosition()[3]) <= 5 then
            AiBotOrders.IssueTrackedAttack(oAirAA, oEnemyUnit, false, 'AAGrnd', false)
            if bDebugMessages == true then LOG(sFunctionRef..': issued attack on grounded unit') end
            --Penetration fighters
            --[[elseif oAirAA[refbDisableAirAAAttackMicro] then
                AiBotOrders.IssueTrackedAggressiveMove(oAirAA, oEnemyUnit:GetPosition(), 10, false, 'AAAtM', false)--]]
        else
            local bInterceptingDestination = false
            local iOurSpeed = (oAirAA:GetBlueprint().Air.MaxAirspeed or 0)
            local iEnemySpeed = (oEnemyUnit:GetBlueprint().Air.MaxAirspeed or 0)
            if not(oAirAA[AiBotUnitInfo.refiAARange]) then AiBotUtilities.ErrorHandler('Have AirAA unit with no AARange, will proceed on assumption it still has an AA attack, UnitId='..oAirAA.UnitId) end
            if iClosestUnitDist >= 50 and iClosestUnitDist >= 15 + (oAirAA[AiBotUnitInfo.refiAARange] or 5) and not(EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA, oEnemyUnit.UnitId)) then
                if bDebugMessages == true then LOG(sFunctionRef..': iOurSpeed='..iOurSpeed..'; iEnemySpeed='..iEnemySpeed) end
                if iOurSpeed < 8 + iEnemySpeed then
                    --If enemy has better speed than us then dont consider intercepting unless angles are signif dif
                    local iAngleFromEnemyToUs = AiBotUtilities.GetAngleFromAToB(oEnemyUnit:GetPosition(), oAirAA:GetPosition())
                    local iEnemyDirection = AiBotUnitInfo.GetUnitFacingAngle(oEnemyUnit)
                    if bDebugMessages == true then LOG(sFunctionRef..': iAngleFromEnemyToUs='..iAngleFromEnemyToUs..'; iEnemyDirection='..iEnemyDirection..'; Dif='..AiBotUtilities.GetAngleDifference(iAngleFromEnemyToUs, iEnemyDirection)) end
                    if iOurSpeed > iEnemySpeed or AiBotUtilities.GetAngleDifference(iAngleFromEnemyToUs, iEnemyDirection) < 170 then --If 180 then it means we are in the opposite direction to the way the enemy air unit is facing
                        --Consider predicting where air unit will move to, and aim for this location
                        local iDistToTravel
                        if iOurSpeed < iEnemySpeed then iDistToTravel = iClosestUnitDist - (oAirAA[AiBotUnitInfo.refiAARange] or 5)
                        else
                            iDistToTravel = (iClosestUnitDist - (oAirAA[AiBotUnitInfo.refiAARange] or 5)) * iEnemySpeed / iOurSpeed
                        end
                        --This isnt precise, but hopefully will be close enough that I dont have to figure out the complicated maths:
                        local tInterceptTarget = AiBotUtilities.MoveInDirection(oEnemyUnit:GetPosition(), iEnemyDirection, iDistToTravel, true, false, AiBotMap.bIsCampaignMap)
                        AiBotOrders.IssueTrackedMove(oAirAA, tInterceptTarget, 3, false, 'InterC', false)
                        if bDebugMessages == true then LOG(sFunctionRef..': Will try and intercept target nearer to its destination') end
                        bInterceptingDestination = true
                    end
                end
            end
            if not(bInterceptingDestination) then
                if iClosestUnitDist and ((iClosestUnitDist >= 120 or EntityCategoryContains(AiBotUnitInfo.refCategoryCzar, oEnemyUnit.UnitId) or (iClosestUnitDist <= math.max((oAirAA[AiBotUnitInfo.refiAARange] or 5) + iOurSpeed or 40) and EntityCategoryContains(AiBotUnitInfo.refCategoryBomber * categories.TECH3 + AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryTransport, oEnemyUnit.UnitId))) or (iClosestUnitDist <= 5 and EntityCategoryContains(AiBotUnitInfo.refCategoryGunship, oEnemyUnit.UnitId))
                        and ((AiBotUnitInfo.CanSeeUnit(oAirAA:GetAIBrain(), oEnemyUnit)) or oAirAA[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget] == oEnemyUnit)) then
                    --Note - sometimes get lua error from above re the logic for existing airaa orders; however we are checking oEnemyUnit is a valid unit before calling, and also are checking oAirAA is valid
                    AiBotOrders.IssueTrackedAttack(oAirAA, oEnemyUnit, false, 'AAAA', false)
                    if bDebugMessages == true then LOG(sFunctionRef..': issued tracked attack') end
                else
                    AiBotOrders.IssueTrackedMove(oAirAA, oEnemyUnit:GetPosition(), 3, false, 'AAAM', false)
                    if oAirAA[AiBotOrders.reftiLastOrders][oAirAA[AiBotOrders.refiOrderCount]] then --if human player with AiBot not enabled on the unit this will cause an error otherwise
                        oAirAA[AiBotOrders.reftiLastOrders][oAirAA[AiBotOrders.refiOrderCount]][AiBotOrders.subrefoOrderUnitTarget] = oEnemyUnit
                    end
                end
            end
        end
        oAirAA[refoAirAACurTarget] = oEnemyUnit

    else
        --If the air unit has a target that is in the playable area then target that
        --local bInterceptTargetFound = false
        --GetNavigator is too unreliable in campaign, so will just ignore and target enemy air unit (moving towards it if it is off-map) - if want the old code using this, refer to v79 and earlier which had it commented out
        if bDebugMessages == true then LOG(sFunctionRef..': Wanted to target unit at position '..repru(oEnemyUnit:GetPosition())) end
        local iAngleToTarget = AiBotUtilities.GetAngleFromAToB(oAirAA:GetPosition(), oEnemyUnit:GetPosition())
        local tViaPoint = AiBotUtilities.MoveInDirection(oAirAA:GetPosition(), iAngleToTarget, 40, true, false, true)
        if AiBotConditions.IsLocationInPlayableArea(tViaPoint) then
            AiBotOrders.IssueTrackedMove(oAirAA, tViaPoint, 10, false, 'AAPAV', false)
            if bDebugMessages == true then LOG(sFunctionRef..': Found a via point that is in the playable area='..repru(tViaPoint)) end
            oAirAA[refoAirAACurTarget] = oEnemyUnit
        end
        --end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': FInished targeting code for oAirAA='..oAirAA.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAirAA)) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateOrdersForExistingAirAATargets(tInCombatUnits, bReturnTableOfAssignedThreat, iAirSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateOrdersForExistingAirAATargets'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local sUnitRef
    local tExistingThreatAssignedByUnitRef = {}
    if bDebugMessages == true then LOG(sFunctionRef..': updating orders for all InCombatUnits, bReturnTableOfAssignedThreat='..tostring(bReturnTableOfAssignedThreat or false)..'; Is table of tInCombatUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tInCombatUnits))..'; Brain of first in combat unit='..tInCombatUnits[1]:GetAIBrain().Nickname..'; Time='..GetGameTimeSeconds()) end
    for iAAUnit, oAirAA in tInCombatUnits do
        if bDebugMessages == true then LOG(sFunctionRef..': Updating orders for oAirAA unit='..oAirAA.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAirAA)..'; Is cur target valid='..tostring(AiBotUnitInfo.IsUnitValid(oAirAA[refoAirAACurTarget]))) end
        --Update move orders
        if AiBotUnitInfo.IsUnitValid(oAirAA[refoAirAACurTarget]) then
            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiAirAAInCombat] = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiAirAAInCombat] + 1
            if bDebugMessages == true then LOG(sFunctionRef..': Will call logic to target enemy unit '..oAirAA[refoAirAACurTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAirAA[refoAirAACurTarget])..' with oAirAA='..oAirAA.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAirAA)..' at time='..GetGameTimeSeconds()) end
            TargetUnitWithAirAA(oAirAA, oAirAA[refoAirAACurTarget])

            if bReturnTableOfAssignedThreat then
                --Update assigned threat values
                sUnitRef = oAirAA[refoAirAACurTarget].EntityId
                if sUnitRef then
                    tExistingThreatAssignedByUnitRef[sUnitRef] = (tExistingThreatAssignedByUnitRef[sUnitRef] or 0) + AiBotUnitInfo.GetAirThreatLevel({ oAirAA }, false, true, false, true, true, true)
                end
            end
        else
            oAirAA[refoAirAACurTarget] = nil
            if bDebugMessages == true then LOG(sFunctionRef..': Dont have a valid target so will clear refoAirAACurTarget') end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished targeting AirAA existing targets') end
    if bReturnTableOfAssignedThreat then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return tExistingThreatAssignedByUnitRef
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AssignAirAATargets(tAvailableAirAA, tEnemyTargets, iTeam, iAirSubteam, tExistingThreatAssignedByUnitRef, bLastEnemiesToTarget, bSendAllAirAA)
    --bLastEnemiesToTarget - if this is true, then will assign more air units than normal to deal with the threat
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AssignAirAATargets'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tStartPoint = {AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][1], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][2], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][3]}

    --Copy of AiBotUtiliteis function (for speed)
    function GetRoughDistanceBetweenPositions(tPosition1, tPosition2)
        --If want a rough indication of proximity but it isnt as important as speed
        return math.max(math.abs(tPosition1[1] - tPosition2[1]), math.abs(tPosition1[3] - tPosition2[3]))
    end
    --local bDontCheckPlayableArea = not(AiBotMap.bIsCampaignMap) --Can have issues with air units not receiving orders which might be caused by air units going outside the playable area

    --local iAvailableAirSize = table.getn(tAvailableAirAA)
    local iEnemyTargetSize = table.getn(tEnemyTargets)
    local iClosestUnitDist, oClosestUnit, iCurDist, iCurValueAssigned, iThreatWanted, iClosestAARef
    local iCurLoopCount
    local iMaxLoopCount = 200 --Wont assign more than this number of AA units to a particular target, partly as an infinite loop check, and partly to avoid too much on a single unit (e.g. czar or ahwassa)
    local tEnemyAirAAAndCargoUnits = {}

    local tPriorityEnemyTargets
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 10000 then
        local tCzarsAndExpBombers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryCzar + categories.BOMBER * categories.EXPERIMENTAL, tEnemyTargets)
        if AiBotUtilities.IsTableEmpty(tCzarsAndExpBombers) == false then
            tPriorityEnemyTargets = tCzarsAndExpBombers
        end
    end

    function ConsiderAttackingUnit(oEnemyUnit, iThreatToAssign)
        iCurLoopCount = 0
        iCurValueAssigned = (tExistingThreatAssignedByUnitRef[oEnemyUnit.EntityId] or 0)
        if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy unit '..oEnemyUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyUnit)..'; iThreatToAssign='..iThreatToAssign) end
        local tBasePosition = oEnemyUnit:GetPosition()
        while iCurValueAssigned < iThreatToAssign do
            iCurLoopCount = iCurLoopCount + 1
            if iCurLoopCount > iMaxLoopCount then break end
            iClosestUnitDist = 100000
            for iAAUnit, oAAUnit in tAvailableAirAA do
                iCurDist = GetRoughDistanceBetweenPositions(tBasePosition, oAAUnit:GetPosition())
                if iCurDist < iClosestUnitDist then
                    iClosestUnitDist = iCurDist
                    oClosestUnit = oAAUnit
                    iClosestAARef = iAAUnit
                end
            end
            if bDebugMessages == true then
                local iEnemyPlateauOrZero, iEnemyLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oClosestUnit:GetPosition())
                LOG(sFunctionRef..': iClosestUnitDist='..iClosestUnitDist..'; oClosestUnit='..oClosestUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnit)..'; will issue attack order if far away and have visibility; iEnemyPlateauOrZero='..iEnemyPlateauOrZero..'; iEnemyLandOrWaterZone='..iEnemyLandOrWaterZone..' tBasePosition='..repru(tBasePosition)..'; In playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tBasePosition))..'; Can see enemy='..tostring(AiBotUnitInfo.CanSeeUnit(oClosestUnit:GetAIBrain(), oEnemyUnit))..'; enemy unit pos='..repru(oEnemyUnit:GetPosition())..'; terrain height='..GetTerrainHeight(oEnemyUnit:GetPosition()[1],oEnemyUnit:GetPosition()[3])..'; currentlayer='..oEnemyUnit:GetCurrentLayer())
            end
            if not(oClosestUnit.Dead) then --redundancy
                TargetUnitWithAirAA(oClosestUnit, oEnemyUnit, iClosestUnitDist)
            end
            iCurValueAssigned = iCurValueAssigned + AiBotUnitInfo.GetAirThreatLevel({ oClosestUnit }, false, true, false, true, true, true)
            table.remove(tAvailableAirAA, iClosestAARef)
            if AiBotUtilities.IsTableEmpty(tAvailableAirAA) then break end
        end
    end

    if tPriorityEnemyTargets then
        for iEnemyUnit, oEnemyUnit in tPriorityEnemyTargets do
            if AiBotUnitInfo.IsUnitValid(oEnemyUnit) then --redundancy due to lua message that saw once
                iThreatWanted = AiBotUnitInfo.GetAirThreatLevel({ oEnemyUnit }, true, true, false, true, true, true)
                if bLastEnemiesToTarget then iThreatWanted = iThreatWanted * 3 end
                ConsiderAttackingUnit(oEnemyUnit, iThreatWanted)
            end
        end
    end

    if AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false then
        if bDebugMessages == true then LOG(sFunctionRef..': About to cycle through each enemy target, iEnemyTargetSize='..iEnemyTargetSize) end

        local tiDistPerTarget = {}
        for iCurEnemyUnit = 1, iEnemyTargetSize do
            tiDistPerTarget[iCurEnemyUnit] = AiBotUtilities.GetDistanceBetweenPositions(tEnemyTargets[iCurEnemyUnit]:GetPosition(), tStartPoint)
        end
        for iEntry, iDist in AiBotUtilities.SortTableByValue(tiDistPerTarget, false) do
            local oEnemyUnit = tEnemyTargets[iEntry]
            iThreatWanted = AiBotUnitInfo.GetAirThreatLevel({ oEnemyUnit }, true, true, false, true, true, true)
            --Increase threat to assign to AA units
            if EntityCategoryContains(AiBotUnitInfo.refCategoryAntiAir + categories.EXPERIMENTAL, oEnemyUnit.UnitId) then
                iThreatWanted = iThreatWanted * 3
                table.insert(tEnemyAirAAAndCargoUnits, oEnemyUnit) --Will want to assign more if have spare AirAA
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryTransport, oEnemyUnit.UnitId) and oEnemyUnit.GetCargo and AiBotUtilities.IsTableEmpty(oEnemyUnit:GetCargo()) == false then
                iThreatWanted = iThreatWanted * 4
                table.insert(tEnemyAirAAAndCargoUnits, oEnemyUnit) --Will want to assign more if have spare AirAA
            end
            if bLastEnemiesToTarget then
                iThreatWanted = math.max(iThreatWanted, oEnemyUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oEnemyUnit))
                iThreatWanted = iThreatWanted * 3
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Dist based approach, iEntry='..iEntry..'; iDist='..iDist..'; enemy unit='..tEnemyTargets[iEntry].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEnemyTargets[iEntry])..'; iThreatWanted='..iThreatWanted) end

            ConsiderAttackingUnit(oEnemyUnit, iThreatWanted)
            if AiBotUtilities.IsTableEmpty(tAvailableAirAA) then break end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished initial cycling through enemy targets, is tAvailableAirAA empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableAirAA))..'; is tEnemyAirAAAndCargoUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyAirAAAndCargoUnits))..'; bLastEnemiesToTarget='..tostring(bLastEnemiesToTarget or false)..'; bSendAllAirAA='..tostring(bSendAllAirAA or false)) end
        if AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false and AiBotUtilities.IsTableEmpty(tEnemyAirAAAndCargoUnits) == false then
            --Assign more threat to enemy AirAA units since where there's 1 more are likely to follow, and want to overwhelm; dont bother sorting for performacne reasons (as this means we have already assigned air units to every enemy air unit)
            for iUnit, oUnit in tEnemyAirAAAndCargoUnits do
                iThreatWanted = AiBotUnitInfo.GetAirThreatLevel({ oUnit }, true, true, false, true, true, true) * 7 --Will reset the cur assigned threat to 0 when calling below funciton, ehnce doing *3 here is in addition to what assigned before
                ConsiderAttackingUnit(oUnit, iThreatWanted)
            end
            if AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false and (bSendAllAirAA or table.getn(tEnemyAirAAAndCargoUnits) >= 5) then
                for iUnit, oUnit in tEnemyAirAAAndCargoUnits do
                    iThreatWanted = AiBotUnitInfo.GetAirThreatLevel({ oUnit }, true, true, false, true, true, true) * 16 --Will reset the cur assigned threat to 0 when calling below funciton, ehnce doing *3 here is in addition to what assigned before
                    ConsiderAttackingUnit(oUnit, iThreatWanted)
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished sending at higher threat factors, is tAvailableAirAA empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableAirAA))) end
            if bSendAllAirAA and AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': Will now send at massive threat factor') end
                for iUnit, oUnit in tEnemyAirAAAndCargoUnits do
                    iThreatWanted = AiBotUnitInfo.GetAirThreatLevel({ oUnit }, true, true, false, true, true, true) * 100 --Will reset the cur assigned threat to 0 when calling below funciton, ehnce doing *3 here is in addition to what assigned before
                    ConsiderAttackingUnit(oUnit, iThreatWanted)
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, is table of available airaa empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableAirAA))) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck, bReturnGroundAAUnitsAlongsideAAThreat, tOptionalEndMidpointAdjustForDetailedCheck, bOptionalIgnoreOppositeDirectionZones, bIncludeEnemyGroundAAInAirAAThreat, bAssumeWontTargetInterimAAForDetailedCheck, bIgnoreUnderwaterAA)
    --Returns true if enemy has AA threat along the path from start to end (or in an adjacent land/water zone that is close enough to the path)

    --iStartPlateauOrZero: 0 if water zone
    --iEndPlateauOrZero: 0 if water zone
    --bIgnoreAirAAThreat - if this is true will only consider if groundAA threat, not airAA threat
    --iGroundAAThreatThreshold - if set, then will only avoid if has MAA above this levle (e.g. intended for gunships)
    --bUsingTorpBombers - if this is true, and we want to avoid somewhere due to too much ground AA threat, then flag that we have a torp bomber shortfall

    --bDoDetailedCheckForAA - if this is true then will calculate how close to the midpoint AA units are
    --bReturnGroundAAThreatInstead - if this is true will return the groundAA threat
    --tOptionalStartMidpointAdjustForDetailedCheck - ended up removing the code that was making use of this, but in theory this allows a different position to be used than the midpoint for the detailed check
    --bReturnGroundAAUnitsAlongsideAAThreat - only set to true if bReturnGroundAAThreatInstead is true; will also return a table of those groundAA units; recommended that use with bDoDetailedCheckForAA since minimal extra overhead then (so expect the detailed check isn't as expensive vs the normal check which has to do entitycateogyrfilterdown if this is falgged
    --bOptionalIgnoreOppositeDirectionZones - if this is true, and the end plateau+zone has a mod dist that is lower than the start, then will ignore zones whose midpoint is in a significantly different angle to the angle from the start to the end
    --bAssumeWontTargetInterimAAForDetailedCheck - normally if doing a detailed check if we come across any groundAA in the zone that is in our range, and the zone AA as a whole is too much, then we will abort; if this is set to true then instead we will only include the threat of the in-range enemy units

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DoesEnemyHaveAAThreatAlongPath'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    --Calculate air travel path
    CalculateAirTravelPath(iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone)
    local iGroundAAThreat = 0
    local toGroundAAUnits
    if bReturnGroundAAUnitsAlongsideAAThreat then toGroundAAUnits = {} end

    --Cycle through every relevant land and water zone along this path and calculate the threat
    --First do land zones
    local tBasePathingTable = tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone][iEndPlateauOrZero][iEndLandOrWaterZone]
    if bDebugMessages == true then LOG(sFunctionRef..': Near start at time '..GetGameTimeSeconds()..', iStartPlateauOrZero='..iStartPlateauOrZero..'; iStartLandOrWaterZone='..iStartLandOrWaterZone..'; iEndPlateauOrZero='..iEndPlateauOrZero..'; iEndLandOrWaterZone='..iEndLandOrWaterZone..'; bIgnoreAirAAThreat='..tostring(bIgnoreAirAAThreat or false)..'; iGroundAAThreatThreshold='..(iGroundAAThreatThreshold or 'nil')..'; Is table of land azones in path empty='..tostring(AiBotUtilities.IsTableEmpty(tBasePathingTable[subreftPlateauAndLandZonesInPath]) or false)..'; Is table of water zones in path empty='..tostring(AiBotUtilities.IsTableEmpty(tBasePathingTable[subreftWaterZonesInPath]) or false)..'; iAirAAThreatThreshold='..(iAirAAThreatThreshold or 'nil')..'; tOptionalStartMidpointAdjustForDetailedCheck='..repru(tOptionalStartMidpointAdjustForDetailedCheck)..'; tOptionalEndMidpointAdjustForDetailedCheck='..repru(tOptionalEndMidpointAdjustForDetailedCheck)) end
    local iAngleToDestination, iDistanceToDestination, iAngleToInterim, iDistanceToInterim, iInterimBestRange, tStartZoneMidpoint
    local tDestinationMidpoint, iDistanceFromInterimToDestination, iAngleDifToInterimVsToDestination

    if tOptionalEndMidpointAdjustForDetailedCheck then
        tDestinationMidpoint = tOptionalEndMidpointAdjustForDetailedCheck
    elseif iEndPlateauOrZero == 0 then
        tDestinationMidpoint = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iEndLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iEndLandOrWaterZone][AiBotMap.subrefMidpoint]
    else
        tDestinationMidpoint = AiBotMap.tAllPlateaus[iEndPlateauOrZero][AiBotMap.subrefPlateauLandZones][iEndLandOrWaterZone][AiBotMap.subrefMidpoint]
    end

    function UpdateAngleAndDistanceToDestinationZone(tOptionalLZOrWZData)
        local tMidpoint
        if bDoDetailedCheckForAA and tOptionalStartMidpointAdjustForDetailedCheck then tMidpoint = tOptionalStartMidpointAdjustForDetailedCheck
        elseif tOptionalLZOrWZData then tMidpoint = tOptionalLZOrWZData[AiBotMap.subrefMidpoint]
        elseif iStartPlateauOrZero == 0 then tMidpoint = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iStartLandOrWaterZone][AiBotMap.subrefMidpoint]
        else tMidpoint = AiBotMap.tAllPlateaus[iStartPlateauOrZero][AiBotMap.subrefPlateauLandZones][iStartLandOrWaterZone][AiBotMap.subrefMidpoint]
        end
        tStartZoneMidpoint = {tMidpoint[1], tMidpoint[2], tMidpoint[3]}

        iAngleToDestination = AiBotUtilities.GetAngleFromAToB(tStartZoneMidpoint, tDestinationMidpoint)
        iDistanceToDestination = AiBotUtilities.GetDistanceBetweenPositions(tStartZoneMidpoint, tDestinationMidpoint)
    end

    function IsZoneInSimilarDirection(tLZOrWZData)
        if not(tStartZoneMidpoint) then UpdateAngleAndDistanceToDestinationZone(tLZOrWZData) end
        iAngleToInterim = AiBotUtilities.GetAngleFromAToB(tStartZoneMidpoint, tLZOrWZData[AiBotMap.subrefMidpoint])
        iDistanceToInterim = AiBotUtilities.GetDistanceBetweenPositions(tStartZoneMidpoint, tLZOrWZData[AiBotMap.subrefMidpoint])
        iDistanceFromInterimToDestination = AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], tDestinationMidpoint)
        iAngleDifToInterimVsToDestination = AiBotUtilities.GetAngleDifference(iAngleToInterim, iAngleToDestination)
        --v285 - changed as these results returned not in similar direction, but enemy was able to hit the target zone with cruiser fire: iAngleToInterim=300.96374511719; iDistanceToInterim=119.53451538086; iDistanceFromInterimToDestination=119.53451538086; AngleDif=59.036254882813; iDistanceToDestination=0
        if bDebugMessages == true then LOG(sFunctionRef..': iAngleToInterim='..iAngleToInterim..'; iDistanceToInterim='..iDistanceToInterim..'; iDistanceFromInterimToDestination='..iDistanceFromInterimToDestination..'; AngleDif='..AiBotUtilities.GetAngleDifference(iAngleToInterim, iAngleToDestination)..'; iDistanceToDestination='..iDistanceToDestination..'; GetMaxZoneRadiusSize='..AiBotMap.GetMaxZoneRadiusSize(tLZOrWZData)..'; Is dist from interim to dest less than radius+90='..tostring(iDistanceFromInterimToDestination <= AiBotMap.GetMaxZoneRadiusSize(tLZOrWZData) + 90)) end
        if (iDistanceToInterim + 70 <= iDistanceToDestination and (iAngleDifToInterimVsToDestination <= 15 or iDistanceToInterim *0.5 + 30 <= iDistanceToDestination)) or iDistanceFromInterimToDestination <= 110 or (iDistanceFromInterimToDestination <= 160 and iDistanceFromInterimToDestination <= AiBotMap.GetMaxZoneRadiusSize(tLZOrWZData) + 90) then
            return true
        end
        return false
    end

    if bOptionalIgnoreOppositeDirectionZones then UpdateAngleAndDistanceToDestinationZone() end --Ideally would try and use UpdateAngleAndDistanceToDestinationZone instead of some of below code, but for now held off in case of unforseen issue

    local iDistFromOptionalStartToEnd, iCurUnitThreat
    if tOptionalStartMidpointAdjustForDetailedCheck then iDistFromOptionalStartToEnd = AiBotUtilities.GetDistanceBetweenPositions(tOptionalStartMidpointAdjustForDetailedCheck, tDestinationMidpoint) end
    function DetailedCheckIfTooMuchAAInInterimZone(tInterimLZOrWZData, tInterimLZOrWZTeamData, iInterimPlateauOrZero, iInterimZone, bUseMidpointAdjustPosition)
        local bTooMuchAA = false
        if iInterimZone == iEndLandOrWaterZone and iInterimPlateauOrZero == iEndPlateauOrZero and not(tOptionalEndMidpointAdjustForDetailedCheck) then --Redundancy
            bTooMuchAA = true
            if bDebugMessages == true then LOG(sFunctionRef..'; Interim zone same as end zone so returning true for too much AA as redundancy') end
        else
            --First record base values if we havent alreayd
            if not(iAngleToDestination) then
                --Start zone midpoint
                local tMidpoint
                if bUseMidpointAdjustPosition then tMidpoint = tOptionalStartMidpointAdjustForDetailedCheck
                elseif iStartPlateauOrZero == 0 then
                    tMidpoint = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iStartLandOrWaterZone][AiBotMap.subrefMidpoint]
                else
                    tMidpoint = AiBotMap.tAllPlateaus[iStartPlateauOrZero][AiBotMap.subrefPlateauLandZones][iStartLandOrWaterZone][AiBotMap.subrefMidpoint]
                end
                tStartZoneMidpoint = {tMidpoint[1], tMidpoint[2], tMidpoint[3]}

                iAngleToDestination = AiBotUtilities.GetAngleFromAToB(tStartZoneMidpoint, tDestinationMidpoint)
                iDistanceToDestination = AiBotUtilities.GetDistanceBetweenPositions(tStartZoneMidpoint, tDestinationMidpoint)
                --If this zone midpoint isn't reasonably closer than the start position then dont use it
                if tOptionalStartMidpointAdjustForDetailedCheck and iDistanceToDestination + 10 >= iDistFromOptionalStartToEnd then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will update the start position to be used for the line to the optional start='..repru(tOptionalStartMidpointAdjustForDetailedCheck)..'; as iDistanceToDestination='..iDistanceToDestination..'; while iDistFromOptionalStartToEnd='..iDistFromOptionalStartToEnd) end
                    tStartZoneMidpoint = {tOptionalStartMidpointAdjustForDetailedCheck[1], tOptionalStartMidpointAdjustForDetailedCheck[2], tOptionalStartMidpointAdjustForDetailedCheck[3]}
                    iDistanceToDestination = iDistFromOptionalStartToEnd
                end
            end
            --Work ont values specific to this interim zone
            --[[iAngleToInterim = AiBotUtilities.GetAngleFromAToB(tStartZoneMidpoint, tInterimLZOrWZData[AiBotMap.subrefMidpoint])
            iDistanceToInterim = AiBotUtilities.GetDistanceBetweenPositions(tStartZoneMidpoint, tInterimLZOrWZData[AiBotMap.subrefMidpoint])
            iDistanceFromInterimToDestination = AiBotUtilities.GetDistanceBetweenPositions(tInterimLZOrWZData[AiBotMap.subrefMidpoint], tDestinationMidpoint)--]]
            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to analyse interim zone P'..iInterimPlateauOrZero..'Z'..iInterimZone..' further, IsZoneInSimilarDirection='..tostring(IsZoneInSimilarDirection(tInterimLZOrWZData, tInterimLZOrWZTeamData) or false)..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tInterimLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]))) end
            if IsZoneInSimilarDirection(tInterimLZOrWZData) then
                iInterimBestRange = 0
                local tEnemyAAUnits
                if AiBotUtilities.IsTableEmpty(tInterimLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                    tEnemyAAUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGroundAA, tInterimLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])
                    if AiBotUtilities.IsTableEmpty(tEnemyAAUnits) == false then
                        for iUnit, oUnit in tEnemyAAUnits do
                            if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() >= 0.8 then
                                iInterimBestRange = math.max(iInterimBestRange, (oUnit[AiBotUnitInfo.refiAARange] or 0))
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy AA units empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyAAUnits))..'; iInterimBestRange='..iInterimBestRange..'; iDistanceToInterim='..iDistanceToInterim..'; iDistanceToDestination='..iDistanceToDestination) end
                    if iInterimBestRange > 0 and (iDistanceToInterim + iInterimBestRange + 5 <= iDistanceToDestination or iDistanceFromInterimToDestination - iInterimBestRange <= 50) then
                        --More detailed check; dont know what part in the zone we are targeting so want a margin of error
                        local iDistToUnit, iAngleToUnit, iDistFromUnitToTarget
                        local iMobileAdjustment = 23
                        local iCurRangeInclAdjustment
                        for iUnit, oUnit in tEnemyAAUnits do
                            if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() >= 0.8 and (oUnit[AiBotUnitInfo.refiAARange] or 0) > 0 and (not(bIgnoreUnderwaterAA) or not(EntityCategoryContains(categories.SUBMERSIBLE, oUnit.UnitId)) or not(AiBotUnitInfo.IsUnitUnderwater(oUnit))) then
                                --IsLineFromAToBInRangeOfCircleAtC(iDistFromAToB, iDistFromAToC, iDistFromBToC, iAngleFromAToB, iAngleFromAToC, iCircleRadius)
                                --C is oUnit, B is destination zone midpoint, A is start zone midpoint
                                iDistToUnit = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tStartZoneMidpoint)
                                iAngleToUnit = AiBotUtilities.GetAngleFromAToB(tStartZoneMidpoint, oUnit:GetPosition())
                                iDistFromUnitToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tDestinationMidpoint)
                                if bDebugMessages == true then LOG(sFunctionRef..'; Considering if will be in range of enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Is in range='..tostring(AiBotUtilities.IsLineFromAToBInRangeOfCircleAtC(iDistanceToDestination, iDistToUnit, iDistFromUnitToTarget, iAngleToDestination, iAngleToUnit, oUnit[AiBotUnitInfo.refiAARange] + 35))..'; Unit position='..repru(oUnit:GetPosition())..'; tDestinationMidpoint='..repru(tDestinationMidpoint)..'; tStartZoneMidpoint='..repru(tStartZoneMidpoint)..'; iDistToUnit from start zone midpoint='..iDistToUnit..'; iDistFromUnitToTarget, being destination midpoint='..iDistFromUnitToTarget..'; iAngleToUnit='..iAngleToUnit) end
                                iCurRangeInclAdjustment = oUnit[AiBotUnitInfo.refiAARange] + 26
                                if EntityCategoryContains(categories.MOBILE, oUnit.UnitId) then iCurRangeInclAdjustment = iCurRangeInclAdjustment + iMobileAdjustment end
                                if AiBotUtilities.IsLineFromAToBInRangeOfCircleAtC(iDistanceToDestination, iDistToUnit, iDistFromUnitToTarget, iAngleToDestination, iAngleToUnit, iCurRangeInclAdjustment) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have groundAA unit in range from this interim zone, iGroundAAThreat before increase='..iGroundAAThreat)
                                        --Draw line
                                        --ForkThread(AiBotUtilities.ForkedDrawLine, tStartZoneMidpoint, tDestinationMidpoint, math.random(1, 8))
                                    end

                                    if bReturnGroundAAThreatInstead or bAssumeWontTargetInterimAAForDetailedCheck then
                                        iCurUnitThreat = AiBotUnitInfo.GetAirThreatLevel({ oUnit }, true, false, true)
                                        --If interim AA that would normally cause us to abort, instead we should treat it as being worth double normal value since we will be ignoring it instead of attacking it
                                        if AiBotUtilities.IsTableEmpty(oUnit[AiBotBuilding.reftoShieldsProvidingCoverage]) == false or bAssumeWontTargetInterimAAForDetailedCheck then iCurUnitThreat = iCurUnitThreat * 2 end
                                        iGroundAAThreat = iGroundAAThreat + iCurUnitThreat
                                        --Normally we assume that as the interim zone has too much AA in it then if any of the AA in that zone is in range of us we will treat the enemy as having too much threat
                                        --however, if this flag is true then we will just treat it the same as a groundAA threat in the target zone
                                        if not(bAssumeWontTargetInterimAAForDetailedCheck) or iGroundAAThreat > (iGroundAAThreatThreshold or 0) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': iGroundAAThreat after increase='..iGroundAAThreat..'; This is more than iGroundAAThreatThreshold='..(iGroundAAThreatThreshold or 'nil')) end
                                            bTooMuchAA = true
                                            if not(bReturnGroundAAThreatInstead) then break end
                                        end
                                        if bReturnGroundAAUnitsAlongsideAAThreat then
                                            table.insert(toGroundAAUnits, oUnit)
                                        end

                                    else
                                        bTooMuchAA = true
                                        break
                                    end
                                end
                            end
                        end
                    end
                end
            elseif bDebugMessages == true then LOG(sFunctionRef..': Too far awya by distance or by angle so treating it as not having too much AA')
            end
        end

        return bTooMuchAA
    end
    local bZoneHasTooMuchAA
    local iOverridePositionPlateau, iOverridePositionZone, bSameZoneAsPositionOverride
    if tOptionalStartMidpointAdjustForDetailedCheck then
        if bDebugMessages == true then LOG(sFunctionRef..': Getting override plateau and zone for tOptionalStartMidpointAdjustForDetailedCheck='..repru(tOptionalStartMidpointAdjustForDetailedCheck)) end
        iOverridePositionPlateau, iOverridePositionZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tOptionalStartMidpointAdjustForDetailedCheck)
    end
    if AiBotUtilities.IsTableEmpty(tBasePathingTable[subreftPlateauAndLandZonesInPath]) == false then


        for iEntry, tPlateauAndLandZone in tBasePathingTable[subreftPlateauAndLandZonesInPath] do
            local tLZData = AiBotMap.tAllPlateaus[tPlateauAndLandZone[1]][AiBotMap.subrefPlateauLandZones][tPlateauAndLandZone[2]]
            local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
            bSameZoneAsPositionOverride = false
            if iOverridePositionPlateau and iOverridePositionPlateau == tPlateauAndLandZone[1] and iOverridePositionZone == tPlateauAndLandZone[2] then bSameZoneAsPositionOverride = true end
            if bDebugMessages == true then
                if tLZData and tLZTeamData then
                    LOG(sFunctionRef..': Considering entry '..iEntry..'; iPlateau='..tPlateauAndLandZone[1]..'; iLandZone='..tPlateauAndLandZone[2]..'; Is there AA in land zone='..tostring(IsThereAAInZone(tLZTeamData, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat))..'; LZ groundAA threat='..tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]..'; tLZTeamData[AiBotMap.refiEnemyAirAAThreat]='..tLZTeamData[AiBotMap.refiEnemyAirAAThreat]..'; iAirAAThreatThreshold='..(iAirAAThreatThreshold or 0)..'; bOptionalIgnoreOppositeDirectionZones='..tostring(bOptionalIgnoreOppositeDirectionZones or false)..'; IsZoneInSimilarDirection(tLZData)='..tostring(IsZoneInSimilarDirection(tLZData) or false))
                else
                    LOG(sFunctionRef..': Dont have valid LZData or teamdata for iEntry='..iEntry..'P'..(tPlateauAndLandZone[1] or 'nil')..'Z'..(tPlateauAndLandZone[2] or 'nil'))
                end
            end

            if tLZData and (not(bOptionalIgnoreOppositeDirectionZones) or IsZoneInSimilarDirection(tLZData)) then
                if bReturnGroundAAThreatInstead then
                    if bDoDetailedCheckForAA then
                        DetailedCheckIfTooMuchAAInInterimZone(tLZData, tLZTeamData, tPlateauAndLandZone[1], tPlateauAndLandZone[2], bSameZoneAsPositionOverride)
                        if bDebugMessages == true then LOG(sFunctionRef..': Doing detailed check, iGroundAAThreat after checking for this zone='..iGroundAAThreat) end
                    else
                        if (tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) > 0 then
                            iGroundAAThreat = iGroundAAThreat + tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]
                            if bReturnGroundAAUnitsAlongsideAAThreat then --redundancy - not currently planning on using for this, only for detailed check
                                local tGroundAAInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGroundAA, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                                if AiBotUtilities.IsTableEmpty(tGroundAAInZone) == false then
                                    for iUnit, oUnit in tGroundAAInZone do
                                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                                            table.insert(toGroundAAUnits, oUnit)
                                        end
                                    end
                                end
                            end
                        end
                    end
                else
                    bZoneHasTooMuchAA = IsThereAAInZone(tLZTeamData, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat)
                    if bZoneHasTooMuchAA then
                        if bDebugMessages == true then LOG(sFunctionRef..': There is too much AA in this land zone, tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]='..(tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)..'; tLZTeamData[AiBotMap.refiEnemyAirAAThreat]='..(tLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)..'; tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]='..(tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0)..'; bDoDetailedCheckForAA='..tostring(bDoDetailedCheckForAA or false)..'; Is there too much AirAA threat to bother with a detailed check='..tostring(IsThereAAInZone(tLZTeamData, false, -1, iAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat))) end
                        if bDoDetailedCheckForAA and (bIgnoreAirAAThreat or not(IsThereAAInZone(tLZTeamData, false, -1, iAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat))) then
                            --There is too much groundAA (rather than AirAA) so want to do more detailed check to see if groundAA is in range
                            if bDebugMessages == true then LOG(sFunctionRef..': Too much groundAA rather than airaa, so will do more detailed check') end
                            if DetailedCheckIfTooMuchAAInInterimZone(tLZData, tLZTeamData, tPlateauAndLandZone[1], tPlateauAndLandZone[2], bSameZoneAsPositionOverride) then
                                if bDebugMessages == true then LOG(sFunctionRef..': After doing detailed check it is still not safe') end
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return true
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': After doing detailed check it is safe, i.e. groundAA is too far away') end
                            end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Not doing detailed check or is AirAA threat so returning true') end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        end
                    end
                end
            end
        end
    end
    if AiBotUtilities.IsTableEmpty(tBasePathingTable[subreftWaterZonesInPath]) == false then
        for iEntry, iWaterZone in tBasePathingTable[subreftWaterZonesInPath] do
            local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone]
            local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
            bSameZoneAsPositionOverride = false
            if iOverridePositionPlateau and iOverridePositionPlateau == 0 and iOverridePositionZone == iWaterZone then bSameZoneAsPositionOverride = true end

            if bDebugMessages == true then
                LOG(sFunctionRef..': Checking along water zone path, iEntry='..iEntry..'; iWaterZone='..iWaterZone..'; IsThereAAInZone='..tostring(IsThereAAInZone(tWZTeamData, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat))..'; tWZTeamData groundAA='..tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]..'; AirAA threat in WZ='..tWZTeamData[AiBotMap.refiEnemyAirAAThreat]..'; Is WZ in similar direction='..tostring( IsZoneInSimilarDirection(tWZData) or false))
                --AiBotMap.DrawSpecificWaterZone(iWaterZone)
            end
            if tWZData and (not(bOptionalIgnoreOppositeDirectionZones) or IsZoneInSimilarDirection(tWZData)) then
                if bReturnGroundAAThreatInstead then
                    if bDoDetailedCheckForAA then
                        DetailedCheckIfTooMuchAAInInterimZone(tWZData, tWZTeamData, 0, iWaterZone, bSameZoneAsPositionOverride)
                    else
                        if (tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) > 0 then
                            iGroundAAThreat = iGroundAAThreat + tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]
                            if bReturnGroundAAUnitsAlongsideAAThreat then --redundancy - not currently planning on using for this, only for detailed check
                                local tGroundAAInZone = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGroundAA, tWZTeamData[AiBotMap.subrefTEnemyUnits])
                                if AiBotUtilities.IsTableEmpty(tGroundAAInZone) == false then
                                    for iUnit, oUnit in tGroundAAInZone do
                                        if AiBotUnitInfo.IsUnitValid(oUnit) then
                                            table.insert(toGroundAAUnits, oUnit)
                                        end
                                    end
                                end
                            end
                        end
                    end
                else
                    bZoneHasTooMuchAA = IsThereAAInZone(tWZTeamData, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat)
                    if bZoneHasTooMuchAA then
                        --If using torp bombers check if reason for failure is due to enemy groundAA threat
                        if bDebugMessages == true then LOG(sFunctionRef..': TOo much AA in water zone, bDoDetailedCheckForAA='..tostring(bDoDetailedCheckForAA or false)..'; bUsingTorpBombers='..tostring(bUsingTorpBombers or false)..'; bIgnoreAirAAThreat='..tostring(bIgnoreAirAAThreat or false)..'; Is there too much AirAA in the zone='..tostring(IsThereAAInZone(tWZTeamData, false, -1, iAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat))) end
                        if bUsingTorpBombers and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbTooMuchGroundNavalAAForTorpBombers]) and not(tWZTeamData[AiBotMap.subrefbWZOnlyHoverEnemies]) and not(IsThereAAInZone(tWZTeamData, true, 100000000, iAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat)) then
                            --We are only ignoring this target because there is too much groundAA in the water zone
                            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbTooMuchGroundNavalAAForTorpBombers] = true
                        end

                        if bDoDetailedCheckForAA and (bIgnoreAirAAThreat or IsThereAAInZone(tWZTeamData, false, -1, iAirAAThreatThreshold, bIncludeEnemyGroundAAInAirAAThreat)) then
                            --There is too much groundAA (rather than AirAA) so want to do more detailed check to see if groundAA is in range
                            if DetailedCheckIfTooMuchAAInInterimZone(tWZData, tWZTeamData, 0, iWaterZone, bSameZoneAsPositionOverride) then
                                if bDebugMessages == true then LOG(sFunctionRef..': After doing detailed check it is still not safe') end
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                return true
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': After doing detailed check it is safe, i.e. groundAA is too far away') end
                            end
                        else

                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if bReturnGroundAAThreatInstead then
        if bReturnGroundAAUnitsAlongsideAAThreat then return iGroundAAThreat, toGroundAAUnits
        else
            return iGroundAAThreat
        end
    else
        return false
    end
end

function AddEnemyAirUnitsAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, tbAlongPathPlateauAndZonesAlreadyAdded, tEnemyAirTargets, iAirAAThreshold, iGroundAAThreshold, iMaxModDistPercent, iMinDistToEnemyBase)
    --Should only call if we have added enemy air units in the target zone; will also add any air units in a direct line (ignoring adjacent zones) to get from the start zone to the target
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AddEnemyAirUnitsAlongPath'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    --First record that we have added enemies from this zone
    if not(tbAlongPathPlateauAndZonesAlreadyAdded[iEndPlateauOrZero]) then tbAlongPathPlateauAndZonesAlreadyAdded[iEndPlateauOrZero] = {} end
    tbAlongPathPlateauAndZonesAlreadyAdded[iEndPlateauOrZero][iEndLandOrWaterZone] = true

    --Next get the zones that will travel along to get to the target
    CalculateAirTravelPath(iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone)
    local tBasePathingTable = tAirZonePathingFromZoneToZone[iStartPlateauOrZero][iStartLandOrWaterZone][iEndPlateauOrZero][iEndLandOrWaterZone]

    if bDebugMessages == true then LOG(sFunctionRef..': Near start at time '..GetGameTimeSeconds()..', iStartPlateauOrZero='..iStartPlateauOrZero..'; iStartLandOrWaterZone='..iStartLandOrWaterZone..'; iEndPlateauOrZero='..iEndPlateauOrZero..'; iEndLandOrWaterZone='..iEndLandOrWaterZone..'; iAirAAThreshold='..(iAirAAThreshold or 'nil')..'; iGroundAAThreshold='..(iGroundAAThreshold or 'nil')..'; Is table of land azones in path empty='..tostring(AiBotUtilities.IsTableEmpty(tBasePathingTable[subreftPlateauAndLandZonesInPath]) or false)..'; Is table of water zones in path empty='..tostring(AiBotUtilities.IsTableEmpty(tBasePathingTable[subreftWaterZonesInPath]) or false)) end
    local tDestinationMidpoint, bCurUnitInRangeOfAdjacentAA
    local iMaxDestinationZoneSize
    if iEndPlateauOrZero == 0 then
        local tDestinationLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iEndLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iEndLandOrWaterZone]
        tDestinationMidpoint = tDestinationLZOrWZData[AiBotMap.subrefMidpoint]
        iMaxDestinationZoneSize = math.max(tDestinationLZOrWZData[AiBotMap.subrefWZMaxSegX] - tDestinationLZOrWZData[AiBotMap.subrefWZMinSegX], tDestinationLZOrWZData[AiBotMap.subrefWZMaxSegZ] - tDestinationLZOrWZData[AiBotMap.subrefWZMinSegZ]) * AiBotMap.iLandZoneSegmentSize
    else
        local tDestinationLZOrWZData = AiBotMap.tAllPlateaus[iEndPlateauOrZero][AiBotMap.subrefPlateauLandZones][iEndLandOrWaterZone]
        tDestinationMidpoint = tDestinationLZOrWZData[AiBotMap.subrefMidpoint]
        iMaxDestinationZoneSize = math.max(tDestinationLZOrWZData[AiBotMap.subrefLZMaxSegX] - tDestinationLZOrWZData[AiBotMap.subrefLZMinSegX], tDestinationLZOrWZData[AiBotMap.subrefLZMaxSegZ] - tDestinationLZOrWZData[AiBotMap.subrefLZMinSegZ]) * AiBotMap.iLandZoneSegmentSize
    end

    local tStartMidpoint
    local tStartLZOrWZData
    if iStartPlateauOrZero == 0 then
        tStartLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iStartLandOrWaterZone]
    else
        tStartLZOrWZData = AiBotMap.tAllPlateaus[iStartPlateauOrZero][AiBotMap.subrefPlateauLandZones][iStartLandOrWaterZone]
    end
    tStartMidpoint = tStartLZOrWZData[AiBotMap.subrefMidpoint]
    local iMaxDistFromStartToConsider = AiBotUtilities.GetDistanceBetweenPositions(tStartMidpoint, tDestinationMidpoint) + 40 + iMaxDestinationZoneSize * 0.5

    local iCurPlateau, iCurZone
    if AiBotUtilities.IsTableEmpty(tBasePathingTable[subreftPlateauAndLandZonesInPath]) == false then
        for iEntry, tPlateauAndLandZone in tBasePathingTable[subreftPlateauAndLandZonesInPath] do
            if not(tbAlongPathPlateauAndZonesAlreadyAdded[tPlateauAndLandZone[1]][tPlateauAndLandZone[2]]) then
                iCurPlateau = tPlateauAndLandZone[1]
                iCurZone = tPlateauAndLandZone[2]
                if not(tbAlongPathPlateauAndZonesAlreadyAdded[iCurPlateau]) then tbAlongPathPlateauAndZonesAlreadyAdded[iCurPlateau] = {} end
                tbAlongPathPlateauAndZonesAlreadyAdded[iCurPlateau][iCurZone] = true

                local tLZData = AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iCurZone]
                local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]

                if bDebugMessages == true then LOG(sFunctionRef..': Considering entry '..iEntry..'; iCurPlateau='..iCurPlateau..'; iCurZone='..iCurZone..'; tLZTeamData mod dist='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; enemy groundAA='..(tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')..'; AirAA threat='..(tLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 'nil')..'; iGroundAAThreshold='..iGroundAAThreshold..'; iAirAAThreshold='..iAirAAThreshold..'; LZData midpoint='..repru(tLZData[AiBotMap.subrefMidpoint])..'; iMaxModDistPercent='..iMaxModDistPercent) end
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]) == false and (tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) <= iGroundAAThreshold and (tLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) <= iAirAAThreshold and tLZTeamData[AiBotMap.refiModDistancePercent] <= iMaxModDistPercent then
                    local toGroundAAInOtherZones = {}
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                            if (tAdjLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) >= iGroundAAThreshold and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                local tAdjacentAAUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGroundAA, tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                                if AiBotUtilities.IsTableEmpty(tAdjacentAAUnits) == false then
                                    for iAA, oAA in tAdjacentAAUnits do
                                        if (oAA[AiBotUnitInfo.refiAARange] or 0) >= 45 and not(oAA.Dead) then
                                            table.insert(toGroundAAInOtherZones, oAA)
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                        for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                            local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[tSubtable[AiBotMap.subrefAWZRef]]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefAWZRef]][AiBotMap.subrefWZTeamData][iTeam]
                            if (tAdjWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) >= iGroundAAThreshold and AiBotUtilities.IsTableEmpty(tAdjWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                local tAdjacentAAUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGroundAA, tAdjWZTeamData[AiBotMap.subrefTEnemyUnits])
                                if AiBotUtilities.IsTableEmpty(tAdjacentAAUnits) == false then
                                    for iAA, oAA in tAdjacentAAUnits do
                                        if (oAA[AiBotUnitInfo.refiAARange] or 0) >= 45 and not(oAA.Dead) then
                                            table.insert(toGroundAAInOtherZones, oAA)
                                        end
                                    end
                                end
                            end
                        end
                    end

                    if AiBotUtilities.IsTableEmpty(toGroundAAInOtherZones) then toGroundAAInOtherZones = nil end

                    local bIncludeEvenIfOnGround = true
                    --If in LOUD and unit on ground dont add as a target unless enemy has no groundAA here as airaa cant target landed air units in LOUD
                    if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and (tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) > 0 then bIncludeEvenIfOnGround = false end
                    for iUnit, oUnit in tLZTeamData[AiBotMap.reftLZEnemyAirUnits] do
                        if AiBotUnitInfo.IsUnitValid(oUnit) and not(oUnit:IsUnitState('Attached')) and (bIncludeEvenIfOnGround or oUnit:IsUnitState('Moving') or oUnit:IsUnitState('Attacking') or oUnit:GetPosition()[2] - GetSurfaceHeight(oUnit:GetPosition()[1], oUnit:GetPosition()[3]) > 1) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Adding enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' as an enemy air target, dist to LZMidpoint='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], oUnit:GetPosition())..'; Unit position='..repru(oUnit:GetPosition())..'; iMinDistToEnemyBase='..(iMinDistToEnemyBase or 'nil')..'; Dist to closest enemy base='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase])..'; Dist to tStartMidpoint='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tStartMidpoint)..'; iMaxDistFromStartToConsider='..iMaxDistFromStartToConsider) end
                            if (not(iMinDistToEnemyBase) or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase]) >= iMinDistToEnemyBase)
                            and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tStartMidpoint) <= iMaxDistFromStartToConsider then
                                if not(toGroundAAInOtherZones) then
                                    table.insert(tEnemyAirTargets, oUnit)
                                else
                                    bCurUnitInRangeOfAdjacentAA = false
                                    for iAA, oAA in toGroundAAInOtherZones do
                                        if AiBotUtilities.GetDistanceBetweenPositions(oAA:GetPosition(), oUnit:GetPosition()) - 30 <= oAA[AiBotUnitInfo.refiAARange] then
                                            bCurUnitInRangeOfAdjacentAA = true
                                            break
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': LZ bCurUnitInRangeOfAdjacentAA='..tostring(bCurUnitInRangeOfAdjacentAA)) end
                                    if not(bCurUnitInRangeOfAdjacentAA) then
                                        table.insert(tEnemyAirTargets, oUnit)
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    if AiBotUtilities.IsTableEmpty(tBasePathingTable[subreftWaterZonesInPath]) == false then
        for iEntry, iWaterZone in tBasePathingTable[subreftWaterZonesInPath] do
            if not(tbAlongPathPlateauAndZonesAlreadyAdded[0][iWaterZone]) then
                if not(tbAlongPathPlateauAndZonesAlreadyAdded[0]) then tbAlongPathPlateauAndZonesAlreadyAdded[0] = {} end
                tbAlongPathPlateauAndZonesAlreadyAdded[0][iWaterZone] = true

                local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone]
                local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]

                if bDebugMessages == true then LOG(sFunctionRef..': Considering entry '..iEntry..'; iWaterZone='..iWaterZone..'; subrefiThreatEnemyGroundAA='..(tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)) end
                if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.reftLZEnemyAirUnits]) == false and (tWZTeamData[AiBotMap.refiEnemyAirAAThreat] >= 20 and (tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) <= iGroundAAThreshold) then
                    --Get nearby enemy groundAA units in adjacent land and water zones with a high AA threshold
                    local toGroundAAInOtherZones = {}
                    if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                        for _, iAdjWZ in tWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                            local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if iAdjWZ='..iAdjWZ..' has enough groundAA that we should check how close its units are, subrefiThreatEnemyGroundAA='..(tAdjWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')..'; iGroundAAThreshold='..iGroundAAThreshold) end
                            if (tAdjWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) >= iGroundAAThreshold and AiBotUtilities.IsTableEmpty(tAdjWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                local tAdjacentAAUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGroundAA, tAdjWZTeamData[AiBotMap.subrefTEnemyUnits])
                                if AiBotUtilities.IsTableEmpty(tAdjacentAAUnits) == false then
                                    for iAA, oAA in tAdjacentAAUnits do
                                        if (oAA[AiBotUnitInfo.refiAARange] or 0) >= 45 and not(oAA.Dead) then
                                            table.insert(toGroundAAInOtherZones, oAA)
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefAdjacentLandZones]) == false then
                        for iEntry, tSubtable in tWZData[AiBotMap.subrefAdjacentLandZones] do
                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]][AiBotMap.subrefLZTeamData][iTeam]
                            if (tAdjLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) >= iGroundAAThreshold and AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                local tAdjacentAAUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGroundAA, tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                                if AiBotUtilities.IsTableEmpty(tAdjacentAAUnits) == false then
                                    for iAA, oAA in tAdjacentAAUnits do
                                        if (oAA[AiBotUnitInfo.refiAARange] or 0) >= 45 and not(oAA.Dead) then
                                            table.insert(toGroundAAInOtherZones, oAA)
                                        end
                                    end
                                end
                            end
                        end
                    end

                    if AiBotUtilities.IsTableEmpty(toGroundAAInOtherZones) then toGroundAAInOtherZones = nil end
                    local bIncludeEvenIfOnGround = true
                    --If in LOUD and unit on ground dont add as a target unless enemy has no groundAA here as airaa cant target landed air units in LOUD
                    if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and (tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) > 0 then bIncludeEvenIfOnGround = false end
                    for iUnit, oUnit in tWZTeamData[AiBotMap.reftLZEnemyAirUnits] do
                        if AiBotUnitInfo.IsUnitValid(oUnit) and not(oUnit:IsUnitState('Attached')) and oUnit[AiBotUnitInfo.refiAARange] and (bIncludeEvenIfOnGround or oUnit:IsUnitState('Moving') or oUnit:IsUnitState('Attacking') or oUnit:GetPosition()[2] - GetSurfaceHeight(oUnit:GetPosition()[1], oUnit:GetPosition()[3]) > 1) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Adding enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' as an enemy air target, iMinDistToEnemyBase='..(iMinDistToEnemyBase or 'nil')..'; Dist to enemy base='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tWZTeamData[AiBotMap.reftClosestEnemyBase])..'; Dist to tStartMidpoint='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tStartMidpoint)..'; iMaxDistFromStartToConsider='..iMaxDistFromStartToConsider) end
                            if (not(iMinDistToEnemyBase) or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tWZTeamData[AiBotMap.reftClosestEnemyBase]) >= iMinDistToEnemyBase)
                                    and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tStartMidpoint) <= iMaxDistFromStartToConsider then
                                if not(toGroundAAInOtherZones) then
                                    table.insert(tEnemyAirTargets, oUnit)
                                else
                                    bCurUnitInRangeOfAdjacentAA = false
                                    for iAA, oAA in toGroundAAInOtherZones do
                                        if AiBotUtilities.GetDistanceBetweenPositions(oAA:GetPosition(), oUnit:GetPosition()) - 30 <= oAA[AiBotUnitInfo.refiAARange] then
                                            bCurUnitInRangeOfAdjacentAA = true
                                            break
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': bCurUnitInRangeOfAdjacentAA='..tostring(bCurUnitInRangeOfAdjacentAA)) end
                                    if not(bCurUnitInRangeOfAdjacentAA) then
                                        table.insert(tEnemyAirTargets, oUnit)
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageAirAAUnits(iTeam, iAirSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageAirAAUnits'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --Get available airAA units (owned by AiBot brains in our subteam):
    local tAvailableAirAA, tAirForRefueling, tUnavailableUnits, tInCombatUnits = GetAvailableLowFuelAndInUseAirUnits(iTeam, iAirSubteam, AiBotUnitInfo.refCategoryAirAA)
    if bDebugMessages == true then
        LOG(sFunctionRef..': Near start of code, time='..GetGameTimeSeconds()..'; Is tAvailableAirAA empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableAirAA))..'; is tAirForRefueling empty='..tostring(AiBotUtilities.IsTableEmpty(tAirForRefueling))..'; is tUnavailableUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tUnavailableUnits))..'; is tInCombatUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tInCombatUnits))..'; iTeam='..iTeam..'; iAirSubteam='..iAirSubteam..'; AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]))
        --List out every brain in airsubteam
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains]) == false then
            for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                LOG(sFunctionRef..': oBrain in subteam='..oBrain.Nickname)
            end
        else
            LOG('No AiBot brains in air subteam')
        end
    end
    --Update threat level
    local iAvailableAndInCombatAirAAThreat = AiBotUnitInfo.GetAirThreatLevel(tAvailableAirAA, false, true) + AiBotUnitInfo.GetAirThreatLevel(tInCombatUnits, false, true)
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] = iAvailableAndInCombatAirAAThreat + AiBotUnitInfo.GetAirThreatLevel(tAirForRefueling, false, true) + AiBotUnitInfo.GetAirThreatLevel(tUnavailableUnits, false, true)
    --Include human air player if we have gifted them asfs
    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoLastHumanGiftedASFs] then
        local oHumanToInclude = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoLastHumanGiftedASFs]
        local iHumanAirAAToInclude = 0
        if not(oHumanToInclude) or oHumanToInclude.AiBotIsDefeated or oHumanToInclude:IsDefeated() then
            oHumanToInclude = nil
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) == false then
                local iCurAirAAThreat = 0
                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
                    if not(oBrain.AiBotAI) and (oBrain.Human or (not(oBrain.BrainType == 'AI') and not(AiBotConditions.IsCivilianBrain(oBrain)))) then
                        iCurAirAAThreat = AiBotUnitInfo.GetMassCostOfUnits(oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAirAA * categories.TECH3, false, true), true)
                        if iCurAirAAThreat > iHumanAirAAToInclude then
                            oHumanToInclude = oBrain
                            iHumanAirAAToInclude = iCurAirAAThreat
                        end
                    end
                end
            end
            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoLastHumanGiftedASFs] = oHumanToInclude
        else
            iHumanAirAAToInclude = AiBotUnitInfo.GetMassCostOfUnits(oHumanToInclude:GetListOfUnits(AiBotUnitInfo.refCategoryAirAA * categories.TECH3, false, true))
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Will increase AirAA threat for the air subteam '..iAirSubteam..' based on human player '..(oHumanToInclude.Nickname or 'nil')..'; iHumanAirAAToInclude='..iHumanAirAAToInclude) end
        if iHumanAirAAToInclude > 0 then
            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] + iHumanAirAAToInclude
        end
    end

    local iAdjacentGroundAAMax = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] * 0.15 --Even if we want to consider attacking adjacent zones, thsi is the max groundAA to permit

    --Update if we have air control and/or are far behind on air
    local iFarBehindFactor = 0.75
    local iAirControlFactor = 1.25 --having too many cases where we think we have superior force and we still lose the air fight - limits to what micro can achieve due to performance concerns, so try and get around by requiring significantly greater force
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] >= 25000 then
        local iEnemyThreatOverThreshold = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] - 25000
        iFarBehindFactor = math.min(0.9, 0.75 + iEnemyThreatOverThreshold / 1000)
        iAirControlFactor = math.max(iAirControlFactor, math.min(1.45, iEnemyThreatOverThreshold / 1000))
    end
    local iAirAAHeavyLossesReduceAirAAThresholdFactor = 1 --e.g. if normally would run from 1k enemy threat and this is 0.9 then will run from 900 threat
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiAirAAKills] < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiAirAALossesToAir] and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiAirAALossesToAir] >= 1000 then
        local iAdjustValue = 0.1 * math.min(1.7, (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiAirAALossesToAir] - AiBotTeam.tTeamData[iTeam][AiBotTeam.refiAirAAKills]) / 20000)
        iFarBehindFactor = math.min(0.99, iFarBehindFactor + iAdjustValue)
        iAirControlFactor = math.max(iAirControlFactor + 0.1, math.min(1.55, iAirControlFactor + iAdjustValue))
        if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then
            iAirAAHeavyLossesReduceAirAAThresholdFactor = iAirAAHeavyLossesReduceAirAAThresholdFactor - math.min(0.2, iAdjustValue)
            if bDebugMessages == true then LOG(sFunctionRef..': iAirAAHeavyLossesReduceAirAAThresholdFactor='..iAirAAHeavyLossesReduceAirAAThresholdFactor) end
        end
    end

    if not(AiBotUtilities.bFAFActive) then iAirControlFactor = iAirControlFactor + 0.03 end
    --Larger maps - increase control factor slightly more as we are less likely to have intel of enemy air force
    if AiBotMap.iMapSize >= 700 then
        if AiBotMap.iMapSize > 1024 then
            iAirControlFactor = iAirControlFactor + 0.1
            iFarBehindFactor = math.min(0.99, iFarBehindFactor + 0.06)
        elseif AiBotMap.iMapSize >= 1000 then
            iAirControlFactor = iAirControlFactor + 0.06
            iFarBehindFactor = math.min(0.99, iFarBehindFactor + 0.03)
        else
            iAirControlFactor = iAirControlFactor + 0.03
            iFarBehindFactor = math.min(0.99, iFarBehindFactor + 0.01)
        end
    end
    if GetGameTimeSeconds() >= 2700 then --After 45m, increase the factor wanted by below % over the next 30m (due to risk as enemies' production expands they can surprise us with more asf at once)
        iAirControlFactor = math.min(0.08, 0.08 * (GetGameTimeSeconds() - 2700) / 1800) + iAirControlFactor
    end
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiFarBehindFactor] = iFarBehindFactor
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiAirControlFactor] = iAirControlFactor

    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] >= 200 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * iFarBehindFactor then
        AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] = true
    else AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] = false
    end
    --Intiies and small numbers of asfs - require a higher factor (we also add a further absolute check below)
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] <= 1500 then iAirControlFactor = iAirControlFactor + 0.1 end

    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * iAirControlFactor < AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] then
        --With low numbers of inties there is more of a risk we think we have air control when we dont
        if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] > 1000 or AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] + math.max(200, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]) then
            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] = true
        else
            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] = false
        end
    else AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] = false
    end
    if bDebugMessages == true then LOG(sFunctionRef..': AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl])..'; AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir])..'; refiEnemyAirAAThreat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]..'; subrefiHighestFriendlyFactoryTech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]..'; OurAAThreat='..AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat]..'; iAirControlFactor='..iAirControlFactor) end

    --Update orders for any in combat airaa units, and track the assigned damage to them
    local tExistingThreatAssignedByUnitRef = {}
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiAirAAInCombat] = 0
    if AiBotUtilities.IsTableEmpty(tInCombatUnits) == false then
        tExistingThreatAssignedByUnitRef = UpdateOrdersForExistingAirAATargets(tInCombatUnits, not(AiBotUtilities.IsTableEmpty(tAvailableAirAA)), iAirSubteam)
        if bDebugMessages == true then LOG(sFunctionRef..': Just updated orders for all incombat units, iTeam='..iTeam..'; iAirSubteam='..iAirSubteam..'; refiAirAAInCombat='..(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiAirAAInCombat] or 'nil')..'; Time='..GetGameTimeSeconds()) end
    end
    --If have lots of airaa in combat then send any refueling airaa to be available (i.e. want to suicide)
    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiAirAAInCombat] >= 8 and AiBotUtilities.IsTableEmpty(tAirForRefueling) == false and (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiAirAAInCombat] >= 16 or AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] <= AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiAirAAInCombat] * 450 * 5) then
        if not(tAvailableAirAA) then tAvailableAirAA = {} end
        if bDebugMessages == true then LOG(sFunctionRef..': Will have all refueling air remain and fight') end
        for iUnit, oUnit in tAirForRefueling do
            table.insert(tAvailableAirAA, oUnit)
        end
        tAirForRefueling = { }
    end
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoAirAAForCoreEnemies] = true
    if AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false then
        local tEnemyAirTargets = {}
        local toEnemyAirAATargetsConsidered = {}
        local tbPlateauAndLandZonesConsidered = {} --[x] = plateau, [y] = land zone, returns true if considered
        local tbAdjacentPlateauAndLandZonesConsidered = {} --as above, but only set to true if we have considered all adjacent locations
        local tbAlongPathPlateauAndZonesAlreadyAdded = {} --as above, but only set to true if we have considered when getting enemy units along a path
        local tbWaterZonesConsidered = {} --[x] = water zone, returns true if considered
        local tbAdjacentWaterZonesConsidered = {} --as above but only set to true if we have considered all adjacent locations
        local refiAvoidAllAA = 0
        local refiAvoidOnlyGroundAA = 1
        local refiIgnoreAllAA = 2

        local iStartPlateauOrZero, iStartLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])
        if (iStartPlateauOrZero or 0) > 0 then
            if (iStartLandOrWaterZone or 0) == 0 then
                iStartLandOrWaterZone = AiBotMap.GetWaterZoneFromPosition(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])
                iStartPlateauOrZero = 0
            end
        end
        if not(iStartPlateauOrZero) or not(iStartLandOrWaterZone) then
            AiBotUtilities.ErrorHandler('Dont have valid start zone for iAirSubteam='..iAirSubteam..', air support point=X'..(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][1] or 'nil')..'Z'..(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][3] or 'nil'))
        end

        local bDontCheckPacifistArea = not(AiBotOverseer.bPacifistModeActive)
        local iLowerPriorityEnemyAirAADefaultThreshold
        local iHigherPriorityEnemyAirAADefaultThreshold
        if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
            iLowerPriorityEnemyAirAADefaultThreshold = math.max(40000, iAvailableAndInCombatAirAAThreat)
            iHigherPriorityEnemyAirAADefaultThreshold = iLowerPriorityEnemyAirAADefaultThreshold
        else
            --Dont want to engage as we lack air control
            iLowerPriorityEnemyAirAADefaultThreshold = iAvailableAndInCombatAirAAThreat * 0.25
            if not(AiBotUtilities.bFAFActive) then iHigherPriorityEnemyAirAADefaultThreshold = iAvailableAndInCombatAirAAThreat * 0.65
            else iHigherPriorityEnemyAirAADefaultThreshold = iAvailableAndInCombatAirAAThreat * 0.8
            end
            if not(iAirAAHeavyLossesReduceAirAAThresholdFactor == 1) then
                iHigherPriorityEnemyAirAADefaultThreshold = iHigherPriorityEnemyAirAADefaultThreshold * iAirAAHeavyLossesReduceAirAAThresholdFactor
                iLowerPriorityEnemyAirAADefaultThreshold = iLowerPriorityEnemyAirAADefaultThreshold * iAirAAHeavyLossesReduceAirAAThresholdFactor
            end

        end

        local bOnlyConsiderThreatInZonesInSameDirection = true --true in all cases, but as variable incase ever want to change
        bOnlyConsiderThreatInZonesInSameDirection = false
        local iMaxModDist
        function AddEnemyAirInLandZoneIfNoAA(iPlateau, iLandZone, bAddAdjacentZones, refiAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, toOptionalUnitOverride, iOptionalAdjacentZoneSearchType, iOptionalMinDistToClosestEnemyBaseIfGroundThreat, bIgnoreIfLargeGroundAARelativeToAir)
            --See above for refiAASearchTypes, i.e. refiAvoidAllAA, refiAvoidOnlyGroundAA, refiIgnoreAllAA

            if bDebugMessages == true then LOG(sFunctionRef..': refiAASearchType='..(refiAASearchType or 'nil')..'; iPlateau='..(iPlateau or 'nil')..'; iLandZone='..(iLandZone or 'nil')..'; tbAdjacentPlateauAndLandZonesConsidered[refiAASearchType][iPlateau][iLandZone]='..tostring(tbAdjacentPlateauAndLandZonesConsidered[refiAASearchType][iPlateau][iLandZone] or false)..'; bAddAdjacentZones='..tostring(bAddAdjacentZones or false)..'; tbPlateauAndLandZonesConsidered[refiAASearchType][iPlateau][iLandZone]='..tostring(tbPlateauAndLandZonesConsidered[refiAASearchType][iPlateau][iLandZone] or false)..'; iLowerPriorityEnemyAirAADefaultThreshold='..iLowerPriorityEnemyAirAADefaultThreshold..'; iHigherPriorityEnemyAirAADefaultThreshold='..iHigherPriorityEnemyAirAADefaultThreshold..'; iAvailableAndInCombatAirAAThreat='..iAvailableAndInCombatAirAAThreat) end
            if not(tbAdjacentPlateauAndLandZonesConsidered[refiAASearchType][iPlateau][iLandZone]) and (bAddAdjacentZones or not(tbPlateauAndLandZonesConsidered[refiAASearchType][iPlateau][iLandZone])) then
                if not(tbPlateauAndLandZonesConsidered[refiAASearchType][iPlateau]) then
                    if not(tbPlateauAndLandZonesConsidered[refiAASearchType]) then tbPlateauAndLandZonesConsidered[refiAASearchType] = {} end
                    tbPlateauAndLandZonesConsidered[refiAASearchType][iPlateau] = {}
                end
                tbPlateauAndLandZonesConsidered[refiAASearchType][iPlateau][iLandZone] = true
                local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                if bDebugMessages == true then LOG(sFunctionRef..': LZ midpoint='..repru(tLZData[AiBotMap.subrefMidpoint])..'; Is in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]))..'; Playable area='..repru(AiBotMap.rMapPlayableArea)..'; Is zone table of enemy air unit sempty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.reftLZEnemyAirUnits]))..'; If we consider enemy AirAA threat in this and adj zones is there too much?='..tostring(IsThereAANearLandOrWaterZone(iTeam, iPlateau, iLandZone, false, -1, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat], iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone))) end
                if bDontCheckPacifistArea or not(AiBotConditions.AdjacentToPacifistZone(iPlateau, iLandZone)) then
                    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                    local iAlongPathAAThreshold = iOptionalAirThreatThresholdOverride
                    if bDebugMessages == true then LOG(sFunctionRef..': Will adjust AA threshold if radar coverage is poor and we lack air control, iAlongPathAAThreshold='..(iAlongPathAAThreshold or 'nil')..'; refiRadarCoverage='..(tLZTeamData[AiBotMap.refiRadarCoverage] or 'nil')) end
                    if iAlongPathAAThreshold and tLZTeamData[AiBotMap.refiRadarCoverage] <= 100 and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then --tried with 60 radar coverage and was too low
                        iAlongPathAAThreshold = iAlongPathAAThreshold * 0.75
                        if bDebugMessages == true then LOG(sFunctionRef..': Reduced iAlongPathAAThreshold as we lack good intel of this land zone, iAlongPathAAThreshold='..iAlongPathAAThreshold..'; refiRadarCoverage='..(tLZTeamData[AiBotMap.refiRadarCoverage] or 'nil')) end
                    end
                    if iAlongPathAAThreshold and not(iAirAAHeavyLossesReduceAirAAThresholdFactor == 1) then
                        iAlongPathAAThreshold = iAlongPathAAThreshold * iAirAAHeavyLossesReduceAirAAThresholdFactor
                        if bDebugMessages == true then LOG(sFunctionRef..': Further reduced threshold due to heavy losses, iAlongPathAAThreshold after reduction='..iAlongPathAAThreshold..'; iAirAAHeavyLossesReduceAirAAThresholdFactor='..iAirAAHeavyLossesReduceAirAAThresholdFactor) end
                    end

                    if not(iAlongPathAAThreshold) or refiAASearchType == refiAvoidOnlyGroundAA then
                        if tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.25 or tLZTeamData[AiBotMap.subrefLZSValue] >= 2000 or ( tLZTeamData[AiBotMap.subrefLZSValue] >= 10 and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.4) then
                            --If we have multiple AiBot then dont throw away air trying to defend a base
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] > iAvailableAndInCombatAirAAThreat then
                                iAlongPathAAThreshold = iLowerPriorityEnemyAirAADefaultThreshold + (iHigherPriorityEnemyAirAADefaultThreshold - iLowerPriorityEnemyAirAADefaultThreshold) * 0.5
                            else
                                iAlongPathAAThreshold = iHigherPriorityEnemyAirAADefaultThreshold
                            end
                        else
                            iAlongPathAAThreshold = iLowerPriorityEnemyAirAADefaultThreshold
                        end
                    end
                    --if not(AiBotMap.bIsCampaignMap) or AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]) then --will handle via individual targeting as e.g. for transports we could try intercepting the destination
                    local iGroundAAThreshold = iOptionalGroundThreatThresholdOverride
                    if (tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0 and (tLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) == 0 and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryTransport, tLZTeamData[AiBotMap.reftLZEnemyAirUnits])) then
                        --Are presumably only targeting scouts so avoid AA
                        iGroundAAThreshold = 0
                    elseif bIgnoreIfLargeGroundAARelativeToAir and iGroundAAThreshold then
                        if tLZTeamData[AiBotMap.refiModDistancePercent] > 0.5 then
                            iGroundAAThreshold = math.min(iGroundAAThreshold, (tLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) * 0.06 + (tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) * 0.1)
                        else
                            iGroundAAThreshold = math.min(iGroundAAThreshold, (tLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) * 0.1 + (tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) * 0.15)
                        end
                    end
                    local bEnemyHasTooMuchAA = false
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy air units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]))..'; iAlongPathAAThreshold='..iAlongPathAAThreshold..'; Mod dist%='..(tLZTeamData[AiBotMap.refiModDistancePercent] or 'nil')..'; SValue='..tLZTeamData[AiBotMap.subrefLZSValue]..'; iMaxModDist='..(iMaxModDist or 'nil')..'; ModDist%='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; iGroundAAThreshold='..(iGroundAAThreshold or 'nil')..'; subrefLZOrWZThreatAllyGroundAA='..tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]) end
                    if AiBotUtilities.IsTableEmpty(toOptionalUnitOverride or tLZTeamData[AiBotMap.reftLZEnemyAirUnits]) == false and (not(iMaxModDist) or tLZTeamData[AiBotMap.refiModDistancePercent] <= iMaxModDist or (tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] >= 4000 and (tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > tLZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or (tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 and tLZTeamData[AiBotMap.subrefLZbCoreBase])))) then
                        --Add units from here unless there is too much AA
                        local bUseDetailedCheck = false
                        if tLZTeamData[AiBotMap.subrefLZSValue] > 10 and (tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) > 0 then bUseDetailedCheck = true end --More precise check if we have friendly structures in the zone
                        --If it has been a while since we last updated enemy unit positions then refresh to reduce the risk we try and target untis that are far away; for performance reasons only do this if doing a detailed check
                        local iTimeSinceUpdated = GetGameTimeSeconds() - (tLZTeamData[AiBotMap.refiTimeOfLastAirUpdate] or 0)
                        if iTimeSinceUpdated > 1 and (bUseDetailedCheck or iTimeSinceUpdated >= 1.1 + iExtraTicksToWaitBetweenAirCycles * 0.1) then
                            tLZTeamData[AiBotMap.refiTimeOfLastAirUpdate] = GetGameTimeSeconds()
                            AiBotLand.UpdateUnitPositionsAndLandZone(AiBotTeam.GetFirstActiveAiBotBrain(iTeam), tLZTeamData[AiBotMap.reftLZEnemyAirUnits], iTeam, iPlateau, iLandZone, false, true, tLZTeamData, false,                               true)
                            if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftLZEnemyAirUnits]) then
                                if bDebugMessages == true then LOG(sFunctionRef..': No air units after doing a refresh') end
                                return
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to add enemy air units in land zone '..iLandZone..'; refiAASearchType='..refiAASearchType..'; DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iPlateau, iLandZone, refiAASearchType == refiAvoidOnlyGroundAA, nil, nil)='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iPlateau, iLandZone, refiAASearchType == refiAvoidOnlyGroundAA, iGroundAAThreshold, iOptionalAirThreatThresholdOverride, nil, nil, bUseDetailedCheck, nil, nil, nil, nil, bOnlyConsiderThreatInZonesInSameDirection, true))..'; iGroundAAThreshold='..(iGroundAAThreshold or 'nil')) end
                        local iMinDistToEnemyBase
                        --DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck, bReturnGroundAAUnitsAlongsideAAThreat, tOptionalEndMidpointAdjustForDetailedCheck, bOptionalIgnoreOppositeDirectionZones, bIncludeEnemyGroundAAInAirAAThreat)
                        if refiAASearchType == refiIgnoreAllAA and iOptionalMinDistToClosestEnemyBaseIfGroundThreat and DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iPlateau, iLandZone, refiAASearchType == refiAvoidOnlyGroundAA, iGroundAAThreshold, iAlongPathAAThreshold, nil,                   nil,            bUseDetailedCheck, nil,                          nil,                                           nil,                                    nil,                                        bOnlyConsiderThreatInZonesInSameDirection, true) then iMinDistToEnemyBase = iOptionalMinDistToClosestEnemyBaseIfGroundThreat end
                        if not(refiAASearchType == refiIgnoreAllAA) then
                            if not(AiBotUtilities.bCPUPerformanceMode) and iAvailableAndInCombatAirAAThreat < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] and IsThereAANearLandOrWaterZone(iTeam, iPlateau, iLandZone, false, -1, iAlongPathAAThreshold, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, true, nil, nil) then
                                bEnemyHasTooMuchAA = true
                            end
                            if not(bEnemyHasTooMuchAA) and DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iPlateau, iLandZone, refiAASearchType == refiAvoidOnlyGroundAA, iGroundAAThreshold, iAlongPathAAThreshold, nil, nil, bUseDetailedCheck, nil, nil, nil, nil, bOnlyConsiderThreatInZonesInSameDirection) then
                                bEnemyHasTooMuchAA = true
                            end
                        end
                        if bEnemyHasTooMuchAA then
                            if bDebugMessages == true then LOG(sFunctionRef..': enemy has too much AA so wont attack this or adjacent zones') end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Will add all enemy air as potential targets, iAlongPathAAThreshold='..(iAlongPathAAThreshold or 'nil')) end
                            local bIgnoreScouts = false
                            if tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.4 and tLZTeamData[AiBotMap.subrefMexCountByTech][2] == 0 and tLZTeamData[AiBotMap.subrefMexCountByTech][3] == 0 and ((tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) > 0 or tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.6 or tLZTeamData[AiBotMap.subrefLZSValue] == 0) then
                                bIgnoreScouts = true
                            end
                            for iUnit, oUnit in (toOptionalUnitOverride or tLZTeamData[AiBotMap.reftLZEnemyAirUnits]) do
                                if AiBotUnitInfo.IsUnitValid(oUnit) and not(oUnit:IsUnitState('Attached')) then
                                    if bDebugMessages == true then
                                        local iTargetEnemyPlateau, iTargetEnemyZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                                        LOG(sFunctionRef..': Adding enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' as an enemy air target unless air scout that we are ignoring, enemy air unit position='..repru(oUnit:GetPosition())..'; Dist to LZ midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])..'; will chekc min dist as well, iMinDistToEnemyBase='..(iMinDistToEnemyBase or 'nil')..'; Dist to closest enemy base='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase])..'; iTargetEnemyPlateau='..(iTargetEnemyPlateau or 'nil')..'; iTargetEnemyZone='..(iTargetEnemyZone or 'nil')..'; bIgnoreScouts='..tostring(bIgnoreScouts or false))
                                    end
                                    if bIgnoreScouts or not(EntityCategoryContains(AiBotUnitInfo.refCategoryAirScout, oUnit.UnitId)) then
                                        if not(iMinDistToEnemyBase) or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZTeamData[AiBotMap.reftClosestEnemyBase]) >= iMinDistToEnemyBase then
                                            table.insert(tEnemyAirTargets, oUnit)
                                        end
                                    end
                                end
                            end
                            --AddEnemyAirUnitsAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, tbAlongPathPlateauAndZonesAlreadyAdded, tEnemyAirTargets, iAirAAThreshold, iGroundAAThreshold, iMaxModDistPercent)
                            if bDebugMessages == true then LOG(sFunctionRef..': Adding enemy air units along path to get to iLandZone='..iLandZone..' from iStartPlateauOrZero='..iStartPlateauOrZero..'; iStartLandOrWaterZone='..iStartLandOrWaterZone) end
                            AddEnemyAirUnitsAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iPlateau, iLandZone, tbAlongPathPlateauAndZonesAlreadyAdded, tEnemyAirTargets, iAlongPathAAThreshold, (iGroundAAThreshold or 0), tLZTeamData[AiBotMap.refiModDistancePercent] + 0.025, iMinDistToEnemyBase)
                        end
                    end
                    if not(bEnemyHasTooMuchAA) and bAddAdjacentZones then
                        local iAdjacentAASearchType = iOptionalAdjacentZoneSearchType or refiAASearchType
                        if not(iAdjacentAASearchType == refiAvoidAllAA) and tLZTeamData[AiBotMap.refiEnemyAirAAThreat] <= 50 and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then
                            iAdjacentAASearchType = refiAvoidAllAA
                        elseif iAdjacentAASearchType == refiIgnoreAllAA then
                            iAdjacentAASearchType = refiAvoidOnlyGroundAA
                        end

                        local bIncludeCurZone
                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                            for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                if bDebugMessages == true then LOG(sFunctionRef..': About to consider for iAdjLZ='..iAdjLZ..'; Dist between midpoints='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefMidpoint])) end
                                if not(iOptionalMaxDistToEdgeOfAdjacentZone) then bIncludeCurZone = true
                                else
                                    bIncludeCurZone = AiBotConditions.IsPositionCloseToZoneEdge(iPlateau, iAdjLZ, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone)
                                end
                                if bIncludeCurZone then
                                    AddEnemyAirInLandZoneIfNoAA(iPlateau, iAdjLZ, false, iAdjacentAASearchType, iAdjacentGroundAAMax, iOptionalAirThreatThresholdOverride)
                                end
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefAdjacentWaterZones]) == false then
                            for iEntry, tSubtable in tLZData[AiBotMap.subrefAdjacentWaterZones] do
                                if not(iOptionalMaxDistToEdgeOfAdjacentZone) then bIncludeCurZone = true
                                else
                                    bIncludeCurZone = AiBotConditions.IsPositionCloseToZoneEdge(0, tSubtable[AiBotMap.subrefAWZRef], iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone)
                                end
                                if bIncludeCurZone then
                                    AddEnemyAirInWaterZoneIfNoAA(tSubtable[AiBotMap.subrefAWZRef], false, iAdjacentAASearchType, iAdjacentGroundAAMax, iOptionalAirThreatThresholdOverride)
                                end
                            end
                        end
                        if not(tbAdjacentPlateauAndLandZonesConsidered[iAdjacentAASearchType][iPlateau]) then
                            if not(tbAdjacentPlateauAndLandZonesConsidered[iAdjacentAASearchType]) then tbAdjacentPlateauAndLandZonesConsidered[iAdjacentAASearchType] = {} end
                            tbAdjacentPlateauAndLandZonesConsidered[iAdjacentAASearchType][iPlateau] = {}
                        end
                        tbAdjacentPlateauAndLandZonesConsidered[iAdjacentAASearchType][iPlateau][iLandZone] = true
                    end
                    --end
                end
            end
        end
        function AddEnemyAirInWaterZoneIfNoAA(iWaterZone, bAddAdjacentZones, refiAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, toOptionalUnitOverride, iOptionalAdjacentZoneSearchType, iOptionalMinDistToClosestEnemyBaseIfGroundThreat, bIgnoreIfLargeGroundAARelativeToAir)
            --See above for refiAASearchTypes, i.e. refiAvoidAllAA, refiAvoidOnlyGroundAA, refiIgnoreAllAA
            if bDebugMessages == true then LOG(sFunctionRef..': AddEnemyAirInWaterZoneIfNoAA: iWaterZone='..iWaterZone..'; refiAASearchType='..refiAASearchType..'; Adjacent WZ considered='..tostring(tbAdjacentWaterZonesConsidered[refiAASearchType][iWaterZone] or false)..'; This zone considered='..tostring(tbWaterZonesConsidered[refiAASearchType][iWaterZone] or false)..'; bAddAdjacentZones='..tostring(bAddAdjacentZones or false)..'; iOptionalAirThreatThresholdOverride='..(iOptionalAirThreatThresholdOverride or 'nil')) end
            if not(tbAdjacentWaterZonesConsidered[refiAASearchType][iWaterZone]) and (bAddAdjacentZones or not(tbWaterZonesConsidered[refiAASearchType][iWaterZone])) then
                if not(tbWaterZonesConsidered[refiAASearchType]) then tbWaterZonesConsidered[refiAASearchType] = {} end
                tbWaterZonesConsidered[refiAASearchType][iWaterZone] = true
                local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone]
                if bDontCheckPacifistArea or not(AiBotConditions.AdjacentToPacifistZone(0, iWaterZone)) then
                    --if not(AiBotMap.bIsCampaignMap) or AiBotConditions.IsLocationInPlayableArea(tWZData[AiBotMap.subrefMidpoint]) then --will handle via individual targeting as e.g. for transports we could try intercepting the destination
                    local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]

                    local iGroundAAThreshold = iOptionalGroundThreatThresholdOverride
                    if (tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0 and (tWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) == 0 and AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.reftLZEnemyAirUnits]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryTransport, tWZTeamData[AiBotMap.reftLZEnemyAirUnits])) then
                        --Are presumably only targeting scouts so avoid AA
                        iGroundAAThreshold = 0
                    elseif bIgnoreIfLargeGroundAARelativeToAir and iGroundAAThreshold then
                        iGroundAAThreshold = math.min(iGroundAAThreshold, (tWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) * 0.1 + (tWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) * 0.15)
                    end
                    local bEnemyHasTooMuchAA = false
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy air units empty for this WZ='..tostring(AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.reftWZEnemyAirUnits]))) end

                    if AiBotUtilities.IsTableEmpty(toOptionalUnitOverride or tWZTeamData[AiBotMap.reftWZEnemyAirUnits]) == false and (not(iMaxModDist) or tWZTeamData[AiBotMap.refiModDistancePercent] <= iMaxModDist or tWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] >= 4000) then
                        local iAlongPathAAThreshold = iOptionalAirThreatThresholdOverride
                        if iAlongPathAAThreshold and tWZTeamData[AiBotMap.refiRadarCoverage] <= 100 and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then
                            iAlongPathAAThreshold = iAlongPathAAThreshold * 0.75
                            if bDebugMessages == true then LOG(sFunctionRef..': Reduced iAlongPathAAThreshold as we lack good intel of this zone, iAlongPathAAThreshold='..iAlongPathAAThreshold..'; refiRadarCoverage='..(tWZTeamData[AiBotMap.refiRadarCoverage] or 'nil')) end
                        end
                        if not(iAlongPathAAThreshold) or refiAASearchType == refiAvoidOnlyGroundAA then
                            if tWZTeamData[AiBotMap.refiModDistancePercent] <= 0.25 or tWZTeamData[AiBotMap.subrefLZSValue] >= 2000 or ( tWZTeamData[AiBotMap.subrefLZSValue] >= 10 and tWZTeamData[AiBotMap.refiModDistancePercent] <= 0.4) then
                                iAlongPathAAThreshold = iHigherPriorityEnemyAirAADefaultThreshold
                            else
                                iAlongPathAAThreshold = iLowerPriorityEnemyAirAADefaultThreshold
                            end
                        end

                        --Add air units unless too much enemy AA
                        local bUseDetailedCheck = false
                        if tWZTeamData[AiBotMap.subrefWZbCoreBase] or tWZTeamData[AiBotMap.refiModDistancePercent] <= 0.35 then bUseDetailedCheck = true end --More precise check if we have friendly structures in the zone or mod dist is low
                        if bDebugMessages == true then
                            LOG(sFunctionRef..': About to check for air units in a zone, iTeam='..iTeam..'; iStartPlateauOrZero='..iStartPlateauOrZero..'; iStartLandOrWaterZone='..(iStartLandOrWaterZone or 'nil')..'; iWaterZone='..(iWaterZone or 'nil'))
                            LOG(sFunctionRef..': Considering whether to add enemy air units in water zone '..iWaterZone..'; refiAASearchType='..refiAASearchType..'; DoesEnemyHaveAAThreatAlongPath='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, 0, iWaterZone, refiAASearchType == refiAvoidOnlyGroundAA, nil, nil, nil, nil, bUseDetailedCheck, nil, nil, nil, nil, bOnlyConsiderThreatInZonesInSameDirection, true))..'; iOptionalGroundThreatThresholdOverride='..(iOptionalGroundThreatThresholdOverride or 'nil')..'; iOptionalAirThreatThresholdOverride='..(iOptionalAirThreatThresholdOverride or 'nil')..'; iGroundAAThreshold='..(iGroundAAThreshold or 'nil')..'; Mod dist='..(tWZTeamData[AiBotMap.refiModDistancePercent] or 0)..'; bUseDetailedCheck='..tostring(bUseDetailedCheck or false))
                        end

                        --If it has been a while since we last updated enemy unit positions then refresh to reduce the risk we try and target untis that are far away; for performance reasons only do this if doing a detailed check
                        local iTimeSinceUpdated = GetGameTimeSeconds() - (tWZTeamData[AiBotMap.refiTimeOfLastAirUpdate] or 0)
                        if iTimeSinceUpdated > 1 and (bUseDetailedCheck or iTimeSinceUpdated >= 1.1 + iExtraTicksToWaitBetweenAirCycles * 0.1) then
                            tWZTeamData[AiBotMap.refiTimeOfLastAirUpdate] = GetGameTimeSeconds()
                            AiBotNavy.UpdateUnitPositionsAndWaterZone(AiBotTeam.GetFirstActiveAiBotBrain(iTeam), tWZTeamData[AiBotMap.reftWZEnemyAirUnits], iTeam, iWaterZone, false, true, tWZTeamData, false,                           true)
                            if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.reftLZEnemyAirUnits]) then
                                if bDebugMessages == true then LOG(sFunctionRef..': No air units after doing a WZ refresh') end
                                return
                            end
                        end

                        local iMinDistToEnemyBase
                        if refiAASearchType == refiIgnoreAllAA and iOptionalMinDistToClosestEnemyBaseIfGroundThreat and DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, 0, iWaterZone, refiAASearchType == refiAvoidOnlyGroundAA, iGroundAAThreshold, iAlongPathAAThreshold, nil, nil, bUseDetailedCheck, nil, nil, nil, nil, bOnlyConsiderThreatInZonesInSameDirection, true) then iMinDistToEnemyBase = iOptionalMinDistToClosestEnemyBaseIfGroundThreat end
                        if not(refiAASearchType == refiIgnoreAllAA) then
                            if not(AiBotUtilities.bCPUPerformanceMode) and iAvailableAndInCombatAirAAThreat < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] and IsThereAANearLandOrWaterZone(iTeam, 0, iWaterZone, false, -1, iAlongPathAAThreshold, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, true, nil, nil) then
                                bEnemyHasTooMuchAA = true
                            end
                            if not(bEnemyHasTooMuchAA) and DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, 0, iWaterZone, refiAASearchType == refiAvoidOnlyGroundAA, iGroundAAThreshold, iAlongPathAAThreshold, nil, nil, bUseDetailedCheck, nil, nil, nil, nil, bOnlyConsiderThreatInZonesInSameDirection, true) then
                                bEnemyHasTooMuchAA = true
                            end
                        end
                        if bEnemyHasTooMuchAA then
                            if bDebugMessages == true then LOG(sFunctionRef..': enemy has too much AA in WZ so wont attack this or adjacent zones') end
                        else
                            for iUnit, oUnit in (toOptionalUnitOverride or tWZTeamData[AiBotMap.reftWZEnemyAirUnits]) do
                                if AiBotUnitInfo.IsUnitValid(oUnit) and not(oUnit:IsUnitState('Attached')) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding enemy air unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to tEnemyAirTargets unless it is too far away, iMinDistToEnemyBase='..(iMinDistToEnemyBase or 'nil')..'; Dist to closest enemy base='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tWZTeamData[AiBotMap.reftClosestEnemyBase])) end
                                    if not(iMinDistToEnemyBase) or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tWZTeamData[AiBotMap.reftClosestEnemyBase]) >= iMinDistToEnemyBase then
                                        table.insert(tEnemyAirTargets, oUnit)
                                    end
                                end
                            end
                            --AddEnemyAirUnitsAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, tbAlongPathPlateauAndZonesAlreadyAdded, tEnemyAirTargets, iAirAAThreshold, iGroundAAThreshold, iMaxModDistPercent)
                            if bDebugMessages == true then LOG(sFunctionRef..': Adding enemy air units along path to get to iWaterZone='..iWaterZone..' from iStartPlateauOrZero='..iStartPlateauOrZero..'; iStartLandOrWaterZone='..iStartLandOrWaterZone) end
                            AddEnemyAirUnitsAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, 0, iWaterZone, tbAlongPathPlateauAndZonesAlreadyAdded, tEnemyAirTargets, iAlongPathAAThreshold, (iGroundAAThreshold or 0), tWZTeamData[AiBotMap.refiModDistancePercent] + 0.025, iMinDistToEnemyBase)
                        end
                    end
                    if not(bEnemyHasTooMuchAA) and bAddAdjacentZones then
                        local iAdjacentAASearchType = iOptionalAdjacentZoneSearchType or refiAASearchType

                        if not(iAdjacentAASearchType == refiAvoidAllAA) and tWZTeamData[AiBotMap.refiEnemyAirAAThreat] <= 50 and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then
                            iAdjacentAASearchType = refiAvoidAllAA
                        elseif iAdjacentAASearchType == refiIgnoreAllAA then
                            iAdjacentAASearchType = refiAvoidOnlyGroundAA
                        end

                        local bIncludeCurZone
                        if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                            for _, iAdjWZ in tWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                                if not(iOptionalMaxDistToEdgeOfAdjacentZone) then bIncludeCurZone = true
                                else
                                    bIncludeCurZone = AiBotConditions.IsPositionCloseToZoneEdge(0, iAdjWZ, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone)
                                end
                                if bIncludeCurZone then
                                    AddEnemyAirInWaterZoneIfNoAA(iAdjWZ, false, iAdjacentAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride)
                                end
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefAdjacentLandZones]) == false then
                            for iEntry, tSubtable in tWZData[AiBotMap.subrefAdjacentLandZones] do
                                if not(iOptionalMaxDistToEdgeOfAdjacentZone) then bIncludeCurZone = true
                                else
                                    bIncludeCurZone = AiBotConditions.IsPositionCloseToZoneEdge(tSubtable[AiBotMap.subrefWPlatAndLZNumber][1], tSubtable[AiBotMap.subrefWPlatAndLZNumber][2], iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone)
                                end
                                if bIncludeCurZone then
                                    if bDebugMessages == true then LOG(sFunctionRef..': About to add enemy air in land zone if no AA, iEntry='..iEntry..'; tSubtable='..repru(tSubtable)..'; tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]='..(tSubtable[AiBotMap.subrefWPlatAndLZNumber][1] or 'nil')..'; tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]='..(tSubtable[AiBotMap.subrefWPlatAndLZNumber][2] or 'nil')) end
                                    AddEnemyAirInLandZoneIfNoAA(tSubtable[AiBotMap.subrefWPlatAndLZNumber][1], tSubtable[AiBotMap.subrefWPlatAndLZNumber][2], false, iAdjacentAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride)
                                end
                            end
                        end
                        if not(tbAdjacentWaterZonesConsidered[iAdjacentAASearchType]) then tbAdjacentWaterZonesConsidered[iAdjacentAASearchType] = {} end
                        tbAdjacentWaterZonesConsidered[iAdjacentAASearchType][iWaterZone] = true
                    end
                    --end
                end
            end
        end
        --Determine targets and issue orders to attack them

        --Suicide into enemy strats
        if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSuicideTargets]) then
            AssignASFsToEnemyStrats(tAvailableAirAA, iTeam, iAirSubteam)
        end
        if AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false then
            function RecordEnemyAirAATargets(tEnemyAirTargets)
                local toAirAA = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirAA, tEnemyAirTargets)
                if AiBotUtilities.IsTableEmpty(toAirAA) == false then
                    for iEnemyAirAA, oEnemyAirAA in toAirAA do
                        table.insert(toEnemyAirAATargetsConsidered, oEnemyAirAA)
                    end
                end
            end


            --First search for air near priority defence targets - look for enemies near priority defensive targets and core bases
            local iAASearchType
            if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then --and (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] or (iAvailableAndInCombatAirAAThreat < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] and (iAvailableAndInCombatAirAAThreat <= 700 or iAvailableAndInCombatAirAAThreat < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 0.9))) then
                iAASearchType = refiAvoidOnlyGroundAA
            else
                iAASearchType = refiIgnoreAllAA
            end


            local iPlateauOrZero, iLandOrWaterZone
            local iDistanceToZoneEdgeToConsider = 60 --i.e. when deciding whether to consider adjacent zones, will only consdier an adjacent zone if the unit is within this distance of the edge of that zone
            --Cybran M6 specific - suicide into czar if it is close to control centre
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if want to suicide into czar for campaign, AiBotUtilities.IsTableEmpty(tAvailableAirAA)='..tostring(AiBotUtilities.IsTableEmpty(tAvailableAirAA))..'; Is experimental air objectives table still valid='..tostring(AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyExperimentalAirObjectives]))..'; Is czar valid='..tostring(AiBotUnitInfo.IsUnitValid(ScenarioInfo.Czar))..'; Is control centre still valid='..tostring(AiBotUnitInfo.IsUnitValid(ScenarioInfo.ControlCenter))) end
            if AiBotMap.bIsCampaignMap and AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false and AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyExperimentalAirObjectives]) then
                --Is the czar close?
                if AiBotUnitInfo.IsUnitValid(ScenarioInfo.ControlCenter) and ScenarioInfo.Czar and AiBotUnitInfo.IsUnitValid(ScenarioInfo.Czar) then
                    local oClosestCzar, iCurCzarDist
                    local iClosestCzar = 100000
                    local tControlCentre = ScenarioInfo.ControlCenter:GetPosition()
                    for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyExperimentalAirObjectives] do
                        iCurCzarDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tControlCentre)
                        if iCurCzarDist < iClosestCzar then
                            iClosestCzar = iCurCzarDist
                            oClosestCzar = oUnit
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iClosestCzar='..iClosestCzar) end
                    if iClosestCzar <= 220 then --tried with 120 and control centre dies before asfs even get in range; at 180 we get 1 pass
                        table.insert(tEnemyAirTargets, oClosestCzar)
                    end
                end
                if AiBotUtilities.IsTableEmpty(tEnemyAirTargets) == false then
                    --SendMessage(aiBrain, sMessageType, sMessage, iOptionalDelayBeforeSending, iOptionalTimeBetweenMessageType, bOnlySendToTeam, bWaitUntilHaveACU)
                    local aiBrain
                    for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                        if oBrain.AiBotAI then aiBrain = oBrain break end
                    end
                    if aiBrain then
                        --SendMessage(aiBrain, sMessageType,    sMessage,                                   iOptionalDelayBeforeSending, iOptionalTimeBetweenMessageType, bOnlySendToTeam, bWaitUntilHaveACU)
                        AiBotChat.SendMessage(aiBrain, 'M6Czar', 'Time to pull out the goalies, every air unit attack!', 0,                           10000000,                                false,          AiBotMap.bIsCampaignMap)
                    end
                    RecordEnemyAirAATargets(tEnemyAirTargets)
                    AssignAirAATargets(tAvailableAirAA, tEnemyAirTargets, iTeam, iAirSubteam, tExistingThreatAssignedByUnitRef)
                end
            end

            --Determine what threats to avoid for priority units
            local bAvoidLargeEnemyAirAA = false
            local iAirAAAvoidThreshold
            if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then
                bAvoidLargeEnemyAirAA = true
                iAirAAAvoidThreshold = iAvailableAndInCombatAirAAThreat * 0.5
            else
                --We risk not having good intel if either large map size or we lack omni
                iAirAAAvoidThreshold = iAvailableAndInCombatAirAAThreat
            end
            local bAlwaysProtectACU = false
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar] then
                bAlwaysProtectACU = true
            end
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDontHaveBuildingsOrACUInPlayableArea] then
                bAvoidLargeEnemyAirAA = false
                bAlwaysProtectACU = true
            end
            if bDebugMessages == true then LOG(sFunctionRef..': bAvoidLargeEnemyAirAA='..tostring(bAvoidLargeEnemyAirAA)..'; bAlwaysProtectACU='..tostring(bAlwaysProtectACU)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar]='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.refbAssassinationOrSimilar])) end

            function GetAASearchTypeForPriorityUnit(oUnit, iPlateauOrZero, tUnitLZOrWZData, tUnitLZOrWZTeamData)
                --Only consider avoiding AA if no enemy air to ground threat in this zone or adjacent zone
                local bAvoidGroundAA
                if EntityCategoryContains(categories.LAND + categories.NAVAL, oUnit.UnitId) and (tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) < (tUnitLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) * 3 then
                    bAvoidGroundAA = true
                elseif tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 and EntityCategoryContains(categories.LAND + categories.NAVAL, oUnit.UnitId) then
                    bAvoidGroundAA = false
                elseif AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then
                    bAvoidGroundAA = true
                elseif (tUnitLZOrWZTeamData[AiBotMap.refiModDistancePercent] or 0) >= 0.7 and not(EntityCategoryContains(categories.COMMAND, oUnit.UnitId)) then
                    if not(tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] >= 3000 and EntityCategoryContains(categories.AIR, oUnit.UnitId)) then
                        bAvoidGroundAA = true
                    end
                end
                if not(bAvoidGroundAA) and tUnitLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] >= 8000 and (tUnitLZOrWZTeamData[AiBotMap.refiModDistancePercent] or 0) >= 0.4 then bAvoidGroundAA = true end
                if not(bAvoidGroundAA) and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then
                    if EntityCategoryContains(categories.AIR * categories.MOBILE, oUnit.UnitId) then
                        if tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] <= 200 then bAvoidGroundAA = true end
                    else
                        if tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] < 50 then bAvoidGroundAA = true end
                    end
                end

                local bAvoidAAThreat = false
                if bAvoidLargeEnemyAirAA and (not(bAlwaysProtectACU) or not(EntityCategoryContains(categories.COMMAND, oUnit.UnitId))) and not(EntityCategoryContains(AiBotUnitInfo.refCategoryRestorer + AiBotUnitInfo.refCategoryCzar, oUnit.UnitId)) then
                    --Is this in a core zone?
                    if not(tUnitLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or tUnitLZOrWZTeamData[AiBotMap.subrefWZbCoreBase]) then
                        --Is this a land zone adjacent to a core land zone?
                        local bAdjacentToCoreZone = false
                        if iPlateauOrZero > 0 and AiBotUtilities.IsTableEmpty(tUnitLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                            for iEntry, iAdjLZ in tUnitLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                                if AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZbCoreBase] then
                                    bAdjacentToCoreZone = true
                                    break
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Will avoid enemy airaa unless adjacent to core zone with large groundAA threat, bAdjacentToCoreZone='..tostring(bAdjacentToCoreZone)..'; Airtoground threat='..tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat]..'; SValue='..tUnitLZOrWZTeamData[AiBotMap.subrefLZSValue]..'; Mex by tech='..repru(tUnitLZOrWZTeamData[AiBotMap.subrefMexCountByTech])) end
                        if (not(bAdjacentToCoreZone) and (tUnitLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) + (tUnitLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) <= 5500) --if have equiv of 7 t3 maa (just under 4 sams) then still engage
                        --Dont ignore all enemy airaa if large enemy airaa threat unless high value zone
                        or not(((tUnitLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] > 0 or tUnitLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] >= 2 or tUnitLZOrWZTeamData[AiBotMap.subrefLZSValue] >= 6000) and ((tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) > (tUnitLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0))))
                         then
                                bAvoidAAThreat = true
                        end

                    end
                end

                local iPriorityAASearchType
                if bAvoidAAThreat then
                    --Avoid ground even if normally wouldnt
                    iPriorityAASearchType = refiAvoidAllAA
                elseif bAvoidGroundAA then
                    iPriorityAASearchType = refiAvoidOnlyGroundAA
                else
                    iPriorityAASearchType = refiIgnoreAllAA
                end
                return iPriorityAASearchType
            end
            local iCurUnitAASearchType
            if bDebugMessages == true then LOG(sFunctionRef..': Will consider priority units for defence if have available AirAA, is table of available AirAA empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableAirAA))..'; Is table of priority defence units empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam]))) end
            if AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false then
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam]) == false then
                    local iGroundAAAdjacentThreshold = math.max(500, math.min(3000, iAvailableAndInCombatAirAAThreat * 0.01))
                    --if far behind on air then only want to defend ACUs (in assassination) or experimentals that are adjacent to a core zone, or units that have significant groundAA threat near them (but do this by adjusting the AirAA threshold for the groundAA nearby)
                    local toPriorityUnitsByPlateauAndZone = {}
                    for iUnit, oUnit in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam] do
                        iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering priority unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; P='..(iPlateauOrZero or 'nil')..'Z'..(iLandOrWaterZone or 'nil')) end
                        if iPlateauOrZero and iLandOrWaterZone then
                            if not(toPriorityUnitsByPlateauAndZone[iPlateauOrZero]) then toPriorityUnitsByPlateauAndZone[iPlateauOrZero] = {} end
                            if not(toPriorityUnitsByPlateauAndZone[iPlateauOrZero][iLandOrWaterZone]) then toPriorityUnitsByPlateauAndZone[iPlateauOrZero][iLandOrWaterZone] = {} end
                            table.insert(toPriorityUnitsByPlateauAndZone[iPlateauOrZero][iLandOrWaterZone], oUnit)
                            if bDebugMessages == true then LOG(sFunctionRef..': Added unit to toPriorityUnitsByPlateauAndZone, is toPriorityUnitsByPlateauAndZone empty='..tostring(AiBotUtilities.IsTableEmpty(toPriorityUnitsByPlateauAndZone))..'; Is toPriorityUnitsByPlateauAndZone[iPlateauOrZero] empty='..tostring(AiBotUtilities.IsTableEmpty(toPriorityUnitsByPlateauAndZone[iPlateauOrZero]))..'; Is toPriorityUnitsByPlateauAndZone nil='..tostring(toPriorityUnitsByPlateauAndZone == nil)) end
                        end
                    end
                    if AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber]) then
                        local oUnit = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber]
                        iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering Front T3 bomber unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; P='..(iPlateauOrZero or 'nil')..'Z'..(iLandOrWaterZone or 'nil')) end
                        if iPlateauOrZero and iLandOrWaterZone then
                            if not(toPriorityUnitsByPlateauAndZone[iPlateauOrZero]) then toPriorityUnitsByPlateauAndZone[iPlateauOrZero] = {} end
                            if not(toPriorityUnitsByPlateauAndZone[iPlateauOrZero][iLandOrWaterZone]) then toPriorityUnitsByPlateauAndZone[iPlateauOrZero][iLandOrWaterZone] = {} end
                            table.insert(toPriorityUnitsByPlateauAndZone[iPlateauOrZero][iLandOrWaterZone], oUnit)
                            if bDebugMessages == true then LOG(sFunctionRef..': Added fromt bomber unit to toPriorityUnitsByPlateauAndZone, is toPriorityUnitsByPlateauAndZone empty='..tostring(AiBotUtilities.IsTableEmpty(toPriorityUnitsByPlateauAndZone))..'; Is toPriorityUnitsByPlateauAndZone[iPlateauOrZero] empty='..tostring(AiBotUtilities.IsTableEmpty(toPriorityUnitsByPlateauAndZone[iPlateauOrZero]))..'; Is toPriorityUnitsByPlateauAndZone nil='..tostring(toPriorityUnitsByPlateauAndZone == nil)) end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]='..(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]) or 'nil')..'; refbHaveAirControl='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl])) end
                    if AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]) and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]) and (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] or ((AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurTorpBomberThreat] >= 20000 or (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurTorpBomberThreat] >= 3000 and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurTorpBomberThreat] >= 0.75 * AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat])) and (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] > 1.1 * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] or (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurTorpBomberThreat] >= 40000 and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurTorpBomberThreat] >= 0.75 * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat])))) then
                        local oUnit = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]
                        iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering Front torp bomber unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; P='..(iPlateauOrZero or 'nil')..'Z'..(iLandOrWaterZone or 'nil')) end
                        if iPlateauOrZero and iLandOrWaterZone then
                            if not(toPriorityUnitsByPlateauAndZone[iPlateauOrZero]) then toPriorityUnitsByPlateauAndZone[iPlateauOrZero] = {} end
                            if not(toPriorityUnitsByPlateauAndZone[iPlateauOrZero][iLandOrWaterZone]) then toPriorityUnitsByPlateauAndZone[iPlateauOrZero][iLandOrWaterZone] = {} end
                            table.insert(toPriorityUnitsByPlateauAndZone[iPlateauOrZero][iLandOrWaterZone], oUnit)
                            if bDebugMessages == true then LOG(sFunctionRef..': Added fromt torp bomber unit to toPriorityUnitsByPlateauAndZone, is toPriorityUnitsByPlateauAndZone empty='..tostring(AiBotUtilities.IsTableEmpty(toPriorityUnitsByPlateauAndZone))..'; Is toPriorityUnitsByPlateauAndZone[iPlateauOrZero] empty='..tostring(AiBotUtilities.IsTableEmpty(toPriorityUnitsByPlateauAndZone[iPlateauOrZero]))..'; Is toPriorityUnitsByPlateauAndZone nil='..tostring(toPriorityUnitsByPlateauAndZone == nil)) end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is toPriorityUnitsByPlateauAndZone empty='..tostring(AiBotUtilities.IsTableEmpty(toPriorityUnitsByPlateauAndZone))) end
                    if AiBotUtilities.IsTableEmpty(toPriorityUnitsByPlateauAndZone) == false then
                        local iPrioirtyDistToEnemyBaseAdj = 70 --i.e. we will get closest friendly priority unit in zone to enemy base; and then ignore targets with signif groundAA threat if they are closer to the enemy base by more than this
                        local iGroundAAModifier = 0
                        local iAirAAModifier = 0
                        for iPlateauOrZero, tPriorityUnitsInZones in toPriorityUnitsByPlateauAndZone do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iPlateauOrZero='..(iPlateauOrZero or 'nil')..' will cycle through every zone and its priority units') end
                            for iLandOrWaterZone, tUnits in tPriorityUnitsInZones do
                                local oClosestUnitToEnemyBase

                                local tUnitLZOrWZData
                                local tUnitLZOrWZTeamData
                                if bDebugMessages == true then LOG(sFunctionRef..': About to consider adding enemy air in land or water zone near priority units, first unit in table='..(tUnits[1].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tUnits[1]) or 'nil')..' to protect, iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')) end
                                if iPlateauOrZero == 0 then
                                    if (iLandOrWaterZone or 0) > 0 then
                                        tUnitLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                                        tUnitLZOrWZTeamData = tUnitLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                        if not(tbWaterZonesConsidered[iLandOrWaterZone]) then
                                            local iClosestDistToEnemyBase = 100000
                                            local iCurDist
                                            local bHaveAirUnit = false
                                            local bHaveGroundUnit = false
                                            for iUnit, oUnit in tUnits do
                                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tUnitLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])
                                                if iCurDist < iClosestDistToEnemyBase then iClosestDistToEnemyBase = iCurDist oClosestUnitToEnemyBase = oUnit end
                                                if not(bHaveAirUnit) and EntityCategoryContains(AiBotUnitInfo.refCategoryAirNonScout, oUnit.UnitId) then bHaveAirUnit = true end
                                                if not(bHaveGroundUnit) and not(EntityCategoryContains(AiBotUnitInfo.refCategoryAirNonScout, oUnit.UnitId)) then bHaveGroundUnit = true end
                                            end
                                            if bHaveAirUnit and EntityCategoryContains(AiBotUnitInfo.refCategoryGunship + AiBotUnitInfo.refCategoryCzar, oClosestUnitToEnemyBase.UnitId) and (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiOurGunshipAAThreat] or 0) >= 1000 then
                                                if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then
                                                    iGroundAAModifier = math.max(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat], AiBotUnitInfo.GetMassCostOfUnits(tUnits)) * 0.1
                                                else
                                                    iGroundAAModifier = math.max(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat], AiBotUnitInfo.GetMassCostOfUnits(tUnits)) * 0.2
                                                end
                                                iAirAAModifier = math.max(0, iAirAAAvoidThreshold - iAvailableAndInCombatAirAAThreat) + (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiOurGunshipAAThreat] or 0)
                                            elseif not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]) and EntityCategoryContains(AiBotUnitInfo.refCategoryBomber - categories.EXPERIMENTAL, oClosestUnitToEnemyBase.UnitId) then
                                                if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                                                    iGroundAAModifier = math.max(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurT1ToT3BomberThreat], AiBotUnitInfo.GetMassCostOfUnits(tUnits)) * 0.2
                                                else
                                                    iGroundAAModifier = math.max(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurT1ToT3BomberThreat], AiBotUnitInfo.GetMassCostOfUnits(tUnits)) * 0.1
                                                end
                                            elseif not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]) and EntityCategoryContains(AiBotUnitInfo.refCategoryTorpBomber, oClosestUnitToEnemyBase.UnitId) then
                                                if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                                                    iGroundAAModifier = math.max(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurTorpBomberThreat], AiBotUnitInfo.GetMassCostOfUnits(tUnits)) * 0.2
                                                else
                                                    iGroundAAModifier = math.max(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurTorpBomberThreat], AiBotUnitInfo.GetMassCostOfUnits(tUnits)) * 0.1
                                                end
                                            else
                                                iGroundAAModifier = 0
                                                iAirAAModifier = 0
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': oClosestUnitToEnemyBase='..oClosestUnitToEnemyBase.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnitToEnemyBase)..'; iGroundAAModifier='..iGroundAAModifier..'; iAirAAModifier='..iAirAAModifier..'; iGroundAAAdjacentThreshold='..iGroundAAAdjacentThreshold..'; iAirAAAvoidThreshold='..iAirAAAvoidThreshold..'; Gunship air to ground='..(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat] or 'nil')) end

                                            iCurUnitAASearchType = GetAASearchTypeForPriorityUnit(oClosestUnitToEnemyBase, iPlateauOrZero, tUnitLZOrWZData, tUnitLZOrWZTeamData)
                                            --AddEnemyAirInWaterZoneIfNoAA(iWaterZone, bAddAdjacentZones, refiAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, toOptionalUnitOverride, iOptionalAdjacentZoneSearchType, iOptionalMinDistToClosestEnemyBaseIfGroundThreat)
                                            AddEnemyAirInWaterZoneIfNoAA(iLandOrWaterZone, false, iCurUnitAASearchType,     iGroundAAAdjacentThreshold + iGroundAAModifier,iAirAAAvoidThreshold + iAirAAModifier,       nil,     nil,   nil,    refiAvoidOnlyGroundAA, iClosestDistToEnemyBase - iPrioirtyDistToEnemyBaseAdj)
                                            --Also include adjacent zones subject to air threat
                                            if iCurUnitAASearchType == refiIgnoreAllAA and ((bHaveAirUnit and ((tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) >= 100 or AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl])) or (bHaveGroundUnit and (tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) > 100))  then
                                                AddEnemyAirInWaterZoneIfNoAA(iLandOrWaterZone, true, refiAvoidOnlyGroundAA,     iGroundAAAdjacentThreshold + iGroundAAModifier,iAirAAAvoidThreshold + iAirAAModifier,       nil,     nil,   nil,    refiAvoidOnlyGroundAA)
                                            end
                                        end
                                    end
                                else
                                    if (iLandOrWaterZone or 0) > 0 then
                                        tUnitLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                                        tUnitLZOrWZTeamData = tUnitLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]

                                        local iClosestDistToEnemyBase = 100000
                                        local iCurDist
                                        local bHaveAirUnit = false
                                        local bHaveGroundUnit = false
                                        for iUnit, oUnit in tUnits do
                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tUnitLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])
                                            if iCurDist < iClosestDistToEnemyBase then iClosestDistToEnemyBase = iCurDist oClosestUnitToEnemyBase = oUnit end
                                            if not(bHaveAirUnit) and EntityCategoryContains(AiBotUnitInfo.refCategoryAirNonScout, oUnit.UnitId) then bHaveAirUnit = true end
                                            if not(bHaveGroundUnit) and not(EntityCategoryContains(AiBotUnitInfo.refCategoryAirNonScout, oUnit.UnitId)) then bHaveGroundUnit = true end
                                        end

                                        if EntityCategoryContains(AiBotUnitInfo.refCategoryGunship + AiBotUnitInfo.refCategoryCzar, oClosestUnitToEnemyBase.UnitId) and (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiOurGunshipAAThreat] or 0) >= 1000 then
                                            if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then
                                                iGroundAAModifier = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat] * 0.05
                                            else
                                                iGroundAAModifier = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat] * 0.1
                                            end
                                            iAirAAModifier = math.max(0, iAirAAAvoidThreshold - iAvailableAndInCombatAirAAThreat) + (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiOurGunshipAAThreat] or 0)
                                        else
                                            iGroundAAModifier = 0
                                            iAirAAModifier = 0
                                        end

                                        iCurUnitAASearchType = GetAASearchTypeForPriorityUnit(oClosestUnitToEnemyBase, iPlateauOrZero, tUnitLZOrWZData, tUnitLZOrWZTeamData)
                                        --AddEnemyAirInLandZoneIfNoAA(iPlateau, iLandZone, bAddAdjacentZones, refiAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, toOptionalUnitOverride, iOptionalAdjacentZoneSearchType, iOptionalMinDistToClosestEnemyBaseIfGroundThreat)
                                        AddEnemyAirInLandZoneIfNoAA(iPlateauOrZero, iLandOrWaterZone, false, iCurUnitAASearchType, iGroundAAAdjacentThreshold + iGroundAAModifier, iAirAAAvoidThreshold + iAirAAModifier, nil,           nil,                                        nil,                    nil,            iClosestDistToEnemyBase - iPrioirtyDistToEnemyBaseAdj)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Just finished considering adding enemy air in land zone near priority unit oClosestUnitToEnemyBase '..(oClosestUnitToEnemyBase.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnitToEnemyBase) or 'nil')..' to protect, iAASearchType='..iAASearchType..'; iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat]='..(tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 'nil')..'; iCurUnitAASearchType='..iCurUnitAASearchType..'; AirAA threat of enemy units='..AiBotUnitInfo.GetAirThreatLevel(tEnemyAirTargets, true, true, false, false, false, false)) end

                                        --Also include adjacent zones subject to air threat
                                        --AddEnemyAirInLandZoneIfNoAA(iPlateau, iLandZone, bAddAdjacentZones, refiAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride)
                                        if iCurUnitAASearchType == refiIgnoreAllAA and ((bHaveAirUnit and ((tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) >= 100 or AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl])) or (bHaveGroundUnit and (tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) > 100))  then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will consider adjacent zones to zone '..iLandOrWaterZone..' but factoring in any groundAA threat, iGroundAAAdjacentThreshold='..iGroundAAAdjacentThreshold) end
                                            --AddEnemyAirInLandZoneIfNoAA(iPlateau, iLandZone,          bAddAdjacentZones, refiAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, toOptionalUnitOverride, iOptionalAdjacentZoneSearchType)
                                            AddEnemyAirInLandZoneIfNoAA(iPlateauOrZero, iLandOrWaterZone, true, refiAvoidOnlyGroundAA, iGroundAAAdjacentThreshold + iGroundAAModifier, iAirAAAvoidThreshold + iAirAAModifier, iDistanceToZoneEdgeToConsider, oClosestUnitToEnemyBase:GetPosition(), nil,    refiAvoidOnlyGroundAA)
                                        end

                                    end
                                end
                            end
                        end
                    end

                end
                --Also protect gunships
                local iGunshipGroundAAThreshold
                if AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]) then
                    iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition())
                    if bDebugMessages == true then LOG(sFunctionRef..': About to get the closest plateau or zone to the front gunship, front gunship='..(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]) or 'nil')..' at position '..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition())..'; iPlateauOrZero for gunship='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')..'; Playable area='..repru(AiBotMap.rMapPlayableArea)..'; iAASearchType='..(iAASearchType or 'nil')..'; AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat]='..(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat] or 'nil')) end
                    iGunshipGroundAAThreshold = math.min(3200,AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat] * 0.15)
                    iGunshipGroundAAThreshold = math.min(3200,AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat] * 0.15)
                    if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then
                        if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then iGunshipGroundAAThreshold = iGunshipGroundAAThreshold * 0.3
                        else iGunshipGroundAAThreshold = iGunshipGroundAAThreshold * 0.6
                        end
                    end
                    local iGunshipAirAAThreshold = iAirAAAvoidThreshold
                    if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]) or (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiOurGunshipAAThreat] >= 1000 and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiOurGunshipAAThreat] + iAvailableAndInCombatAirAAThreat > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 0.9) then
                        iGunshipAirAAThreshold = iGunshipAirAAThreshold + AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiOurGunshipAAThreat]
                    end

                    if bDebugMessages == true then LOG(sFunctionRef..': iGunshipGroundAAThreshold='..(iGunshipGroundAAThreshold or 'nil')..'; iGunshipAirAAThreshold='..iGunshipAirAAThreshold..'; refiOurGunshipAAThreat='..(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiOurGunshipAAThreat] or 'nil')) end
                    local tUnitLZOrWZData
                    local tUnitLZOrWZTeamData

                    if iPlateauOrZero == 0 then
                        if (iLandOrWaterZone or 0) > 0 then
                            tUnitLZOrWZData = AiBotMap.tPondDetails[iLandOrWaterZone][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                            tUnitLZOrWZTeamData = tUnitLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                            iCurUnitAASearchType = GetAASearchTypeForPriorityUnit(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship], iPlateauOrZero, tUnitLZOrWZData, tUnitLZOrWZTeamData)

                            if iCurUnitAASearchType == refiIgnoreAllAA and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]) then
                                --AddEnemyAirInWaterZoneIfNoAA(iWaterZone,         bAddAdjacentZones, refiAASearchType,        iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride,                    iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone,                              toOptionalUnitOverride, iOptionalAdjacentZoneSearchType)
                                AddEnemyAirInWaterZoneIfNoAA(iLandOrWaterZone, false, iCurUnitAASearchType,        iGunshipGroundAAThreshold               , iGunshipAirAAThreshold                            , iDistanceToZoneEdgeToConsider, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition(), nil            , refiAvoidOnlyGroundAA)
                                AddEnemyAirInWaterZoneIfNoAA(iLandOrWaterZone, true, refiAvoidOnlyGroundAA,        iGunshipGroundAAThreshold * 0.25               , iGunshipAirAAThreshold                            , iDistanceToZoneEdgeToConsider, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition(), nil            , refiAvoidOnlyGroundAA)
                            else
                                AddEnemyAirInWaterZoneIfNoAA(iLandOrWaterZone, false, iCurUnitAASearchType,        iGunshipGroundAAThreshold               , iGunshipAirAAThreshold                            , iDistanceToZoneEdgeToConsider, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition())
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Gunship defence - FInished checking for enemy air in water zone and adjacent zones, is table of enemy targets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyAirTargets))..'; iCurUnitAASearchType='..iCurUnitAASearchType) end
                        end
                    else
                        if (iLandOrWaterZone or 0) > 0 then
                            tUnitLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                            tUnitLZOrWZTeamData = tUnitLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                            iCurUnitAASearchType = GetAASearchTypeForPriorityUnit(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship], iPlateauOrZero, tUnitLZOrWZData, tUnitLZOrWZTeamData)

                            if bDebugMessages == true then LOG(sFunctionRef..': About to search for enemy air targets in land zone that gunship is in to defend gunship, iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'#; will search adjacent zones if not far behind on air, far behind='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir])..'; iCurUnitAASearchType='..iCurUnitAASearchType) end
                            if iCurUnitAASearchType == refiIgnoreAllAA and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]) then
                                AddEnemyAirInLandZoneIfNoAA(iPlateauOrZero, iLandOrWaterZone, false, iCurUnitAASearchType, iGunshipGroundAAThreshold, iGunshipAirAAThreshold, iDistanceToZoneEdgeToConsider, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition(), nil,  refiAvoidOnlyGroundAA)
                                AddEnemyAirInLandZoneIfNoAA(iPlateauOrZero, iLandOrWaterZone, true, refiAvoidOnlyGroundAA, iGunshipGroundAAThreshold * 0.25, iGunshipAirAAThreshold, iDistanceToZoneEdgeToConsider, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition(), nil,  refiAvoidOnlyGroundAA)
                            else
                                AddEnemyAirInLandZoneIfNoAA(iPlateauOrZero, iLandOrWaterZone, not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]), iCurUnitAASearchType, iGunshipGroundAAThreshold, iGunshipAirAAThreshold, iDistanceToZoneEdgeToConsider, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition())
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Gunship defence - FInished checking for enemy air in land zone and adjacent zones, is table of enemy targets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyAirTargets))..'; far behind on air='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir])..'; iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone) end
                        end
                    end
                end
                --Now search around start positions
                local iStartPositionGroundAAThreshold
                if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                    iStartPositionGroundAAThreshold = math.min(4800,iAvailableAndInCombatAirAAThreat * 0.2)
                else
                    iStartPositionGroundAAThreshold = math.min(3200,iAvailableAndInCombatAirAAThreat * 0.2)
                end

                local bConsiderAdjacentZones = not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir])
                if bConsiderAdjacentZones and iAvailableAndInCombatAirAAThreat < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 0.8 then bConsiderAdjacentZones = false end

                for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                    local tStartPoint = AiBotMap.GetPlayerStartPosition(oBrain)
                    iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tStartPoint)
                    if (iPlateauOrZero or 0) == 0 then
                        if (iLandOrWaterZone or 0) > 0 then
                            AddEnemyAirInWaterZoneIfNoAA(iLandOrWaterZone, bConsiderAdjacentZones, iAASearchType, iStartPositionGroundAAThreshold)
                        end
                    else
                        if (iLandOrWaterZone or 0) > 0 then
                            --Have a land zone - check for groundAA
                            if bDebugMessages == true then LOG(sFunctionRef..': About to consider adding enemy air in land or water zone near start position, iAASearchType='..iAASearchType..'; iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; Brain start position='..oBrain.Nickname..'; Start pos='..repru(AiBotMap.GetPlayerStartPosition(oBrain))) end
                            AddEnemyAirInLandZoneIfNoAA(iPlateauOrZero, iLandOrWaterZone, bConsiderAdjacentZones, iAASearchType, iStartPositionGroundAAThreshold)
                        end
                    end
                end

                --Early game - protect expansions we have recently dropped from air to ground attack similarly to if it was a core base (stop checking for htis once we have reached T3 or 10m into the game)
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to defend recently dropped locations, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone]='..repru(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone])..'; Highest friendly tech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]) end
                if GetGameTimeSeconds() <= 600 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone]) == false and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech] < 3 then
                    for iDropPlateauOrZero, tSubtable in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone] do
                        --Only consider land zones
                        if iDropPlateauOrZero > 0 then
                            --Have we dropped here in the last 3 minutes?
                            for iDropLandOrWaterZone, iTimeOfDrop in tSubtable do
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering drop plateau='..iDropPlateauOrZero..'; iDropLandOrWaterZone='..iDropLandOrWaterZone..'; Time since last drop='..GetGameTimeSeconds() - iTimeOfDrop) end
                                if GetGameTimeSeconds() - iTimeOfDrop <= 240 then
                                    --Do we have friendly engineers or factories in this zone?
                                    local tDropLZData = AiBotMap.tAllPlateaus[iDropPlateauOrZero][AiBotMap.subrefPlateauLandZones][iDropLandOrWaterZone]
                                    local tLZTeamData = tDropLZData[AiBotMap.subrefLZTeamData][iTeam]
                                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of friendly units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))..'; Enemy air to ground threat='..(tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 'nil')) end
                                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                        local tFriendlyFactoriesAndEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryEngineer, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                        if bDebugMessages == true then LOG(sFunctionRef..': is table of friendly facs and engis empty='..tostring(AiBotUtilities.IsTableEmpty( tFriendlyFactoriesAndEngineers))) end
                                        if AiBotUtilities.IsTableEmpty( tFriendlyFactoriesAndEngineers) == false then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will add enemy air units in this zone as a high priority, bConsiderAdjacentZones='..tostring(bConsiderAdjacentZones or false)..'; iStartPositionGroundAAThreshold='..iStartPositionGroundAAThreshold) end
                                            if iAASearchType == refiIgnoreAllAA and bConsiderAdjacentZones then
                                                AddEnemyAirInLandZoneIfNoAA(iDropPlateauOrZero, iDropLandOrWaterZone, false, iAASearchType, iStartPositionGroundAAThreshold)
                                                AddEnemyAirInLandZoneIfNoAA(iDropPlateauOrZero, iDropLandOrWaterZone, true, refiAvoidOnlyGroundAA, iStartPositionGroundAAThreshold)
                                            else
                                                AddEnemyAirInLandZoneIfNoAA(iDropPlateauOrZero, iDropLandOrWaterZone, bConsiderAdjacentZones, iAASearchType, iStartPositionGroundAAThreshold)
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end

                --Assign available air units to targets
                if bDebugMessages == true then LOG(sFunctionRef..': FInished checking for neemies around all start positions, is tEnemyAirTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyAirTargets))) end
                if AiBotUtilities.IsTableEmpty(tEnemyAirTargets) == false then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will assign AirAA targets') end
                    RecordEnemyAirAATargets(tEnemyAirTargets)
                    AssignAirAATargets(tAvailableAirAA, tEnemyAirTargets, iTeam, iAirSubteam, tExistingThreatAssignedByUnitRef)
                end
                --Consider bomber targets if we have t3 bombers (partly for simplicity so we can reference the front bomber as the unit we are protecting, even though it might not be)
                if AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false then
                    if bDebugMessages == true then LOG(sFunctionRef..': Is active bomber targets table empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoActiveBomberTargets]))..'; Are we far behind on air='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir])) end
                    if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoActiveBomberTargets]) and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]) then
                        local oFriendlyBomber = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber] --simplification
                        if not(AiBotUnitInfo.IsUnitValid(oFriendlyBomber)) then
                            --Just treat our first asf as the unit we are 'protecting' so we have something to refer to
                            oFriendlyBomber = tAvailableAirAA[1]
                        end
                        local iGroundAAAdjacentThreshold = math.max(500, math.min(3000, iAvailableAndInCombatAirAAThreat * 0.01))
                        iAirAAAvoidThreshold = math.min(iAirAAAvoidThreshold, iAvailableAndInCombatAirAAThreat * 0.95)
                        local iMaxDistFromZoneMidpointToFrontBomber = 125
                        local iMaxDistFromAirSupportPoint = 80
                        local iMaxDistFromFrontBomberToTarget = math.min(400, math.max(150, AiBotMap.iMapSize*0.3))
                        if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurT1ToT3BomberThreat] >= 20000 then
                            if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurT1ToT3BomberThreat] >= 50000 then
                                iMaxDistFromZoneMidpointToFrontBomber = 200
                                iMaxDistFromAirSupportPoint = 140
                                iMaxDistFromFrontBomberToTarget = iMaxDistFromFrontBomberToTarget * 1.1
                            else
                                iMaxDistFromZoneMidpointToFrontBomber = 175
                                iMaxDistFromAirSupportPoint = 110
                            end
                        end

                        --[[local tFrontBomberOrAirSupportPointPosition
                        if AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber]) then
                            tFrontBomberOrAirSupportPointPosition = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber]:GetPosition()
                        else
                            tFrontBomberOrAirSupportPointPosition = {AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][1], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][2], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][3]}
                        end --]]
                        local iCurDistFromBomberToTarget
                        if AiBotUnitInfo.IsUnitValid(oFriendlyBomber) then
                            for iBomberTarget, oBomberTarget in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoActiveBomberTargets] do
                                iCurDistFromBomberToTarget = AiBotUtilities.GetDistanceBetweenPositions(oFriendlyBomber:GetPosition(), oBomberTarget:GetPosition())
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering bomber target '..oBomberTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomberTarget)..'; iCurDistFromBomberToTarget Dist from front bomber to this='..AiBotUtilities.GetDistanceBetweenPositions(oBomberTarget:GetPosition(), oFriendlyBomber:GetPosition())..'; iMaxDistFromFrontBomberToTarget='..iMaxDistFromFrontBomberToTarget) end
                                if AiBotUtilities.GetDistanceBetweenPositions(oBomberTarget:GetPosition(), oFriendlyBomber:GetPosition()) <= iMaxDistFromFrontBomberToTarget then
                                    if oBomberTarget[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] then
                                        --Dealing with water zone bomber target
                                        iLandOrWaterZone = oBomberTarget[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam]
                                        local tUnitLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                                        if AiBotUtilities.GetDistanceBetweenPositions(tUnitLZOrWZData[AiBotMap.subrefMidpoint], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]) <= iMaxDistFromAirSupportPoint or (AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber]) and AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber]:GetPosition(), tUnitLZOrWZData[AiBotMap.subrefMidpoint]) <= iMaxDistFromZoneMidpointToFrontBomber) then
                                            local tUnitLZOrWZTeamData = tUnitLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                            if tUnitLZOrWZTeamData then
                                                iCurUnitAASearchType = GetAASearchTypeForPriorityUnit(oFriendlyBomber, iPlateauOrZero, tUnitLZOrWZData, tUnitLZOrWZTeamData)
                                                --AddEnemyAirInWaterZoneIfNoAA(iWaterZone, bAddAdjacentZones, refiAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, toOptionalUnitOverride, iOptionalAdjacentZoneSearchType, iOptionalMinDistToClosestEnemyBaseIfGroundThreat)
                                                AddEnemyAirInWaterZoneIfNoAA(iLandOrWaterZone, false,       iCurUnitAASearchType,     iGroundAAAdjacentThreshold,       iAirAAAvoidThreshold,                   nil,                                 nil,                                    nil,                   refiAvoidOnlyGroundAA,              nil)
                                                --Also include adjacent zones subject to air threat
                                                if iCurUnitAASearchType == refiIgnoreAllAA then
                                                    AddEnemyAirInWaterZoneIfNoAA(iLandOrWaterZone, true, refiAvoidOnlyGroundAA,     iGroundAAAdjacentThreshold,iAirAAAvoidThreshold,       nil,     nil,   nil,    refiAvoidOnlyGroundAA)
                                                end
                                            end
                                        end

                                    else
                                        iLandOrWaterZone = oBomberTarget[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                                        iPlateauOrZero = oBomberTarget[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]
                                        local tUnitLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                                        if not(tUnitLZOrWZData[AiBotMap.subrefMidpoint]) then
                                            iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oBomberTarget:GetPosition())
                                            if bDebugMessages == true then LOG(sFunctionRef..': Dont have valid assigned plateau and zone for bomber target, just based on its position iPlateauOrZero='..(iPlateauOrZero or 'nil')..'; iLandOrWaterZone='..(iLandOrWaterZone or 'nil')) end
                                            if (iPlateauOrZero or 0) > 0 then
                                                tUnitLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                                            end
                                        end
                                        if bDebugMessages == true then
                                            LOG(sFunctionRef..': tUnitLZOrWZData[AiBotMap.subrefMidpoint]='..repru(tUnitLZOrWZData[AiBotMap.subrefMidpoint])..'; SubSupportPoint='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]))
                                            LOG(sFunctionRef..': LZ oBomberTarget='..oBomberTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomberTarget)..'; LZ iLandOrWaterZone='..iLandOrWaterZone..'; bomber targ to air support point dist='..AiBotUtilities.GetDistanceBetweenPositions(tUnitLZOrWZData[AiBotMap.subrefMidpoint], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])..'; iMaxDistFromZoneMidpointToFrontBomber='..iMaxDistFromZoneMidpointToFrontBomber..'; iMaxDistFromAirSupportPoint='..iMaxDistFromAirSupportPoint)
                                            if AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber]) then LOG(sFunctionRef..': Dist from front bomber to target='..AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber]:GetPosition(), tUnitLZOrWZData[AiBotMap.subrefMidpoint])) end
                                        end
                                        if tUnitLZOrWZData[AiBotMap.subrefMidpoint] and ((AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint] and AiBotUtilities.GetDistanceBetweenPositions(tUnitLZOrWZData[AiBotMap.subrefMidpoint], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]) <= iMaxDistFromAirSupportPoint) or (AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber]) and AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber]:GetPosition(), tUnitLZOrWZData[AiBotMap.subrefMidpoint]) <= iMaxDistFromZoneMidpointToFrontBomber)) then
                                            local tUnitLZOrWZTeamData = tUnitLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                            if tUnitLZOrWZTeamData then
                                                iCurUnitAASearchType = GetAASearchTypeForPriorityUnit(oFriendlyBomber, iPlateauOrZero, tUnitLZOrWZData, tUnitLZOrWZTeamData)
                                                --AddEnemyAirInLandZoneIfNoAA(iPlateau, iLandZone, bAddAdjacentZones, refiAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, toOptionalUnitOverride, iOptionalAdjacentZoneSearchType, iOptionalMinDistToClosestEnemyBaseIfGroundThreat)
                                                AddEnemyAirInLandZoneIfNoAA(iPlateauOrZero, iLandOrWaterZone, false, iCurUnitAASearchType, iGroundAAAdjacentThreshold, iAirAAAvoidThreshold, nil,           nil,                                        nil,                    nil,            nil)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Just finished considering adding enemy air in land zone near bomber target, iAASearchType='..iAASearchType..'; iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat]='..(tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 'nil')..'; iCurUnitAASearchType='..iCurUnitAASearchType..'; AirAA threat of enemy units='..AiBotUnitInfo.GetAirThreatLevel(tEnemyAirTargets, true, true, false, false, false, false)) end

                                                --Also include adjacent zones subject to air threat
                                                --AddEnemyAirInLandZoneIfNoAA(iPlateau, iLandZone, bAddAdjacentZones, refiAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride)
                                                if iCurUnitAASearchType == refiIgnoreAllAA then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will consider adjacent zones to bomber target zone '..iLandOrWaterZone..' but factoring in any groundAA threat, iGroundAAAdjacentThreshold='..iGroundAAAdjacentThreshold) end
                                                    --AddEnemyAirInLandZoneIfNoAA(iPlateau, iLandZone,          bAddAdjacentZones, refiAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, toOptionalUnitOverride, iOptionalAdjacentZoneSearchType)
                                                    AddEnemyAirInLandZoneIfNoAA(iPlateauOrZero, iLandOrWaterZone, true, refiAvoidOnlyGroundAA, iGroundAAAdjacentThreshold, iAirAAAvoidThreshold, iDistanceToZoneEdgeToConsider, oBomberTarget:GetPosition(), nil,    refiAvoidOnlyGroundAA)
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Finished considering enemy air units around bomber target, is tEnemyAirTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyAirTargets))) end
                        if AiBotUtilities.IsTableEmpty(tEnemyAirTargets) == false then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will get availableAirAA to target these units') end
                            RecordEnemyAirAATargets(tEnemyAirTargets)
                            AssignAirAATargets(tAvailableAirAA, tEnemyAirTargets, iTeam, iAirSubteam, tExistingThreatAssignedByUnitRef)
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Do we have available AirAA after considering bomber targets? Is table empty='..tostring( AiBotUtilities.IsTableEmpty(tAvailableAirAA))) end
                    if AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false then
                        local tStartLZOrWZData
                        if iStartPlateauOrZero == 0 then
                            tStartLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iStartLandOrWaterZone]
                        else
                            tStartLZOrWZData = AiBotMap.tAllPlateaus[iStartPlateauOrZero][AiBotMap.subrefPlateauLandZones][iStartLandOrWaterZone]
                        end
                        --Cycle through other land and water zones using the table sorting them by distance
                        if bDebugMessages == true then LOG(sFunctionRef..': We still have available airaa left, Is table of other land/water zones empty='..tostring(AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]))..'; iStartPlateauOrZero='..(iStartPlateauOrZero or 'nil')..'; iStartLandOrWaterZone='..(iStartLandOrWaterZone or 'nil')..'; AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])) end
                        if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                            local iAASearchType
                            local iTorpGroundAAThreshold = 2100
                            local iTorpAirAAThreshold = iAvailableAndInCombatAirAAThreat * 0.5
                            if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) and (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiAirAAKills] < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiAirAALossesToAir] or iAvailableAndInCombatAirAAThreat < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]) then
                                iAASearchType = refiAvoidAllAA
                            else
                                iAASearchType = refiAvoidOnlyGroundAA
                                iTorpAirAAThreshold = iTorpAirAAThreshold * 2
                                iTorpGroundAAThreshold = math.max(iTorpGroundAAThreshold * 1.5, iTorpAirAAThreshold * 0.1)
                            end
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDontHaveBuildingsOrACUInPlayableArea] then iAASearchType = refiIgnoreAllAA end
                            if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then
                                if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then iMaxModDist = 0.45
                                else
                                    iMaxModDist = 0.6
                                end
                            end
                            local iOtherLandZoneGroundAAThreshold
                            if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                                iOtherLandZoneGroundAAThreshold = math.min(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] * 0.15, iStartPositionGroundAAThreshold, iTorpGroundAAThreshold)
                                if iGunshipGroundAAThreshold and iGunshipGroundAAThreshold < iOtherLandZoneGroundAAThreshold then iOtherLandZoneGroundAAThreshold = iGunshipGroundAAThreshold end
                                iOtherLandZoneGroundAAThreshold = iOtherLandZoneGroundAAThreshold * 0.9
                                if bDebugMessages == true then LOG(sFunctionRef..': Set iOtherLandZoneGroundAAThreshold to be '..iOtherLandZoneGroundAAThreshold..' (subject to individual zone air threat') end
                            end


                            for iEntry, tSubtable in tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                                tEnemyAirTargets = {}
                                if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Lower priority enemy air targeter for water zone '..(tSubtable[AiBotMap.subrefiLandOrWaterZoneRef] or 'nil')..'; Zone has friendly torps='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftWaterZonesHasFriendlyTorps][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]] or false)) end
                                    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftWaterZonesHasFriendlyTorps][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]] then
                                        if bDebugMessages == true then LOG(sFunctionRef..': This water zone has friendly torpedo bombers in it so will increase thresholds for AA to ignore. Far behind on air='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir])..'; iTorpGroundAAThreshold='..iTorpGroundAAThreshold..'; iTorpAirAAThreshold='..iTorpAirAAThreshold) end
                                        --AddEnemyAirInWaterZoneIfNoAA(iWaterZone,                                      bAddAdjacentZones, refiAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, toOptionalUnitOverride)
                                        AddEnemyAirInWaterZoneIfNoAA(tSubtable[AiBotMap.subrefiLandOrWaterZoneRef], false, iAASearchType, iTorpGroundAAThreshold, iTorpAirAAThreshold)
                                    else
                                        --AddEnemyAirInWaterZoneIfNoAA(iWaterZone, bAddAdjacentZones, refiAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, toOptionalUnitOverride, iOptionalAdjacentZoneSearchType, iOptionalMinDistToClosestEnemyBaseIfGroundThreat, bIgnoreIfLargeGroundAARelativeToAir)
                                        AddEnemyAirInWaterZoneIfNoAA(tSubtable[AiBotMap.subrefiLandOrWaterZoneRef], false, iAASearchType, iOtherLandZoneGroundAAThreshold, nil,                           nil,                                    nil,                                    nil,                    nil,                            nil,                                            true)
                                    end
                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': Searching through other potential AirAA targets now, considering land zone '..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..', iAASearchType='..iAASearchType) end
                                    --AddEnemyAirInLandZoneIfNoAA(iPlateau,                                 iLandZone,                      bAddAdjacentZones, refiAASearchType, iOptionalGroundThreatThresholdOverride, iOptionalAirThreatThresholdOverride, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, toOptionalUnitOverride, iOptionalAdjacentZoneSearchType, iOptionalMinDistToClosestEnemyBaseIfGroundThreat, bIgnoreIfLargeGroundAARelativeToAir)
                                    AddEnemyAirInLandZoneIfNoAA(tSubtable[AiBotMap.subrefiPlateauOrPond], tSubtable[AiBotMap.subrefiLandOrWaterZoneRef], false, iAASearchType, iOtherLandZoneGroundAAThreshold,                 nil,                                nil,                                    nil,                                    nil,                    nil,                            nil,                                                true)
                                end
                                if AiBotUtilities.IsTableEmpty(tEnemyAirTargets) == false then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will assign available AirAA against enemy air target as tEnemyAirTargets isnt empty, size of tEnemyAirTargets='..table.getn(tEnemyAirTargets)) end
                                    RecordEnemyAirAATargets(tEnemyAirTargets)
                                    AssignAirAATargets(tAvailableAirAA, tEnemyAirTargets, iTeam, iAirSubteam, tExistingThreatAssignedByUnitRef)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Finished assigning, is tAvailableAirAA empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableAirAA))..'; is tEnemyAirTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyAirTargets))) end
                                    if AiBotUtilities.IsTableEmpty(tAvailableAirAA) then break end
                                end
                            end

                            --Campaign specific - check for air experimental targets and attack if we have equivalent of at least 20 asfs
                            if bDebugMessages == true then LOG(sFunctionRef..': Campaign specific - checking for experimental air targets; Is table of available aira empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableAirAA))..'; Is table of enemy experimentals still valid='..tostring(AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyExperimentalAirObjectives]))..'; Our AA threat='..AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat]..'; iAvailableAndInCombatAirAAThreat='..iAvailableAndInCombatAirAAThreat) end
                            if AiBotMap.bIsCampaignMap and AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false and table.getn(tAvailableAirAA) >= 15 and AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyExperimentalAirObjectives]) and iAvailableAndInCombatAirAAThreat >= 8000 then
                                --Consider attacking based on a lower threshold
                                local iGroundThreatOverride = math.max(iAvailableAndInCombatAirAAThreat * 0.33, 3000)
                                local iAirThreatOverride = math.max(3000, iAvailableAndInCombatAirAAThreat * 0.95)
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy exp air objectives, iGroundThreatOverride='..iGroundThreatOverride..'; iAirThreatOverride='..iAirThreatOverride) end
                                for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyExperimentalAirObjectives] do

                                    local iUnitPlateau, iUnitLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                                    if iUnitLandOrWaterZone and iUnitPlateau then

                                        if iUnitPlateau == 0 then
                                            --Reset considered flags so we reconsider but with much higher thresholds
                                            local bResetFlag = false
                                            if tbWaterZonesConsidered[refiAvoidOnlyGroundAA][iUnitLandOrWaterZone] then
                                                tbWaterZonesConsidered[refiAvoidOnlyGroundAA][iUnitLandOrWaterZone] = nil
                                                bResetFlag = true
                                            end
                                            if tbAdjacentWaterZonesConsidered[refiAvoidOnlyGroundAA][iUnitLandOrWaterZone] then
                                                tbAdjacentWaterZonesConsidered[refiAvoidOnlyGroundAA][iUnitLandOrWaterZone] = nil
                                                bResetFlag = true
                                            end
                                            --Add just for the experimental (as sometimes it doesnt show up in the zone list of units)
                                            AddEnemyAirInWaterZoneIfNoAA(iUnitLandOrWaterZone, false, refiAvoidOnlyGroundAA, iGroundThreatOverride, iAirThreatOverride, 10, oUnit:GetPosition(), {oUnit})
                                            --Also consider adding other enemy air in the zone
                                            if bResetFlag then
                                                AddEnemyAirInWaterZoneIfNoAA(iUnitLandOrWaterZone, false, refiAvoidOnlyGroundAA, iGroundThreatOverride, iAirThreatOverride, 10, oUnit:GetPosition())
                                            end
                                        else
                                            local bResetFlag = false
                                            if tbAdjacentPlateauAndLandZonesConsidered[refiAvoidOnlyGroundAA][iUnitPlateau][iUnitLandOrWaterZone] then
                                                tbAdjacentPlateauAndLandZonesConsidered[refiAvoidOnlyGroundAA][iUnitPlateau][iUnitLandOrWaterZone] = nil
                                                bResetFlag = true
                                            end
                                            if tbPlateauAndLandZonesConsidered[refiAvoidOnlyGroundAA][iUnitPlateau][iUnitLandOrWaterZone] then
                                                tbPlateauAndLandZonesConsidered[refiAvoidOnlyGroundAA][iUnitPlateau][iUnitLandOrWaterZone] = nil
                                                bResetFlag = true
                                            end
                                            --Add just for the experimental
                                            AddEnemyAirInLandZoneIfNoAA(iUnitPlateau, iUnitLandOrWaterZone, false, refiAvoidOnlyGroundAA, iGroundThreatOverride, iAirThreatOverride, 10, oUnit:GetPosition(), {oUnit})
                                            --Also consider adding other enemy air in the zone
                                            if bResetFlag then
                                                AddEnemyAirInLandZoneIfNoAA(iUnitPlateau, iUnitLandOrWaterZone, false, refiAvoidOnlyGroundAA, iGroundThreatOverride, iAirThreatOverride, 10, oUnit:GetPosition())
                                            end
                                        end
                                        if bDebugMessages == true then
                                            local tUnitLZOrWZData, tUniTmtLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                                            LOG(sFunctionRef..': Do we have enemy targets after checking for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'? table is empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyAirTargets))..'; iUnitPlateau='..iUnitPlateau..'; iUnitLandOrWaterZone='..iUnitLandOrWaterZone..'; Enemy LZ groundAA='..(tUnitLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')..'; ENemy WZ AA='..(tUnitLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')..'; Enemy AirAA='..(tUnitLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 'nil'))
                                        end
                                        if AiBotUtilities.IsTableEmpty(tEnemyAirTargets) == false then
                                            RecordEnemyAirAATargets(tEnemyAirTargets)
                                            AssignAirAATargets(tAvailableAirAA, tEnemyAirTargets, iTeam, iAirSubteam, tExistingThreatAssignedByUnitRef)
                                            if AiBotUtilities.IsTableEmpty(tAvailableAirAA) then break end
                                        end
                                    end
                                end
                            end
                            --Available AirAA and are in a large air fight (so we dont retreat with some of them just because we arent sure we will win the air fight)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will add existing targets for all airaa units if in large air fight with available airaa, is tAvailableAirAA empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableAirAA))..'; Is tInCombatUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tInCombatUnits))..'; is tEnemyAirTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyAirTargets))) end
                            if AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false and AiBotUtilities.IsTableEmpty(tInCombatUnits) == false then
                                if bDebugMessages == true then LOG(sFunctionRef..': Number of incombat airaa='..table.getn(tInCombatUnits)) end
                                local iCurInCombatUnits = table.getn(tInCombatUnits)
                                if iCurInCombatUnits >= 10 or (iCurInCombatUnits >= 5 and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] <= 45000 and table.getn(tAvailableAirAA) < iCurInCombatUnits * 5) then
                                    local tbEntityIDIncluded = {}
                                    if AiBotUtilities.IsTableEmpty(tEnemyAirTargets) == false then
                                        for iExistingTarget, oExistingTarget in tEnemyAirTargets do
                                            tbEntityIDIncluded[oExistingTarget.EntityId] = true
                                        end
                                    end
                                    local oClosestInCombatEnemyAirAA, iCurDist
                                    local iClosestInCombatEnemyAirAA = 10000
                                    local tStartPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]
                                    for iUnit, oUnit in tInCombatUnits do
                                        if bDebugMessages == true then LOG(sFunctionRef..': oUnit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is targeting refoAirAACurTarget='..oUnit[refoAirAACurTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit[refoAirAACurTarget])..' with refiAARange='..(oUnit[refoAirAACurTarget][AiBotUnitInfo.refiAARange] or 'nil')) end
                                        if oUnit[refoAirAACurTarget].EntityId and not(tbEntityIDIncluded[oUnit[refoAirAACurTarget].EntityId]) and not(oUnit[refoAirAACurTarget].Dead) and (oUnit[refoAirAACurTarget][AiBotUnitInfo.refiAARange] or 0) > 0 then
                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit[refoAirAACurTarget]:GetPosition(), tStartPoint)
                                            if iCurDist < iClosestInCombatEnemyAirAA then
                                                iClosestInCombatEnemyAirAA = iCurDist
                                                oClosestInCombatEnemyAirAA = oUnit[refoAirAACurTarget]
                                            end
                                            tbEntityIDIncluded[oUnit[refoAirAACurTarget].EntityId] = true
                                            table.insert(tEnemyAirTargets,  oUnit[refoAirAACurTarget])
                                            if bDebugMessages == true then LOG(sFunctionRef..': Added existing AirAA target') end
                                        end
                                    end
                                    if oClosestInCombatEnemyAirAA then
                                        --Attack any airaa units in the area around the nearest enemy AirAA (will use enemy brain since human player would be able to attack without needing visual of the units and saves AiBot performance with having to use AiBot memory)
                                        local toNearbyAirAA = oClosestInCombatEnemyAirAA:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryAirAA, oClosestInCombatEnemyAirAA:GetPosition(), 60, 'Ally')
                                        if AiBotUtilities.IsTableEmpty(toNearbyAirAA) == false then
                                            for iEnemyUnit, oEnemyUnit in toNearbyAirAA do
                                                if oEnemyUnit.EntityId and not(tbEntityIDIncluded[oEnemyUnit.EntityId]) and (oEnemyUnit[AiBotUnitInfo.refiAARange] or 0) > 0 then
                                                    tbEntityIDIncluded[oEnemyUnit.EntityId] = true
                                                    table.insert(tEnemyAirTargets,  oEnemyUnit)
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Added oEnemyUnit='..oEnemyUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyUnit)..' to AirAA target') end
                                                end
                                            end
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': is tEnemyAirTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyAirTargets))) end
                                if AiBotUtilities.IsTableEmpty(tEnemyAirTargets) == false then
                                    RecordEnemyAirAATargets(tEnemyAirTargets)
                                    AssignAirAATargets(tAvailableAirAA, tEnemyAirTargets, iTeam, iAirSubteam, tExistingThreatAssignedByUnitRef, false)
                                end
                            end

                            --If have enemy air t argets, and available AirAA, then send more asfs to engage
                            if bDebugMessages == true then LOG(sFunctionRef..': Finished considering targets, will assign even more airaa if have available AirAA left, is tEnemyAirTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyAirTargets))..'; Is tAvailableAirAA empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableAirAA))) end
                            if AiBotUtilities.IsTableEmpty(tEnemyAirTargets) == false and AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false then
                                RecordEnemyAirAATargets(tEnemyAirTargets)
                                AssignAirAATargets(tAvailableAirAA, tEnemyAirTargets, iTeam, iAirSubteam, tExistingThreatAssignedByUnitRef, true)
                            end
                        end

                        --Send any remaining available airAA to engage enemy AirAA units
                        if bDebugMessages == true then LOG(sFunctionRef..': Is toEnemyAirAATargetsConsidered empty='..tostring(AiBotUtilities.IsTableEmpty(toEnemyAirAATargetsConsidered))) end
                        if AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false and AiBotUtilities.IsTableEmpty(toEnemyAirAATargetsConsidered) == false then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will send remaining asfs to target existing asf targets if we think this might be an air fight and we dont have a heavy airaa advantage, size of toEnemyAirAATargetsConsidered='..table.getn(toEnemyAirAATargetsConsidered)) end
                            local iCurTargetSize = table.getn(toEnemyAirAATargetsConsidered)
                            if iCurTargetSize >= 2 and (not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] > 0.35 * AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat])  then
                                --Go through enemy airaa and check how many are close
                                local bLikelyAirFight = false
                                if iCurTargetSize >= 10 then iCurTargetSize = true
                                elseif AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirAA]) == false then
                                    local oFurthestEnemyAirAA
                                    local iFurthestDist = 0
                                    local iCurDist
                                    local iNearbyEnemyAir = 0
                                    local tSupportPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]
                                    local toNearbyAirAA = {}
                                    for iUnit, oUnit in toEnemyAirAATargetsConsidered do
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tSupportPoint)
                                        if iCurDist >  iFurthestDist then
                                            iFurthestDist = iCurDist
                                            oFurthestEnemyAirAA = oUnit
                                        end
                                    end
                                    if oFurthestEnemyAirAA then
                                        local tNearestEnemyAirAA = oFurthestEnemyAirAA:GetPosition()
                                        for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirAA] do
                                            if not(oUnit.Dead) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tNearestEnemyAirAA) <= 160 then
                                                table.insert(toNearbyAirAA, oUnit)
                                                iNearbyEnemyAir = iNearbyEnemyAir + 1
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': iNearbyEnemyAir='..iNearbyEnemyAir..'; Mass cost='..AiBotUnitInfo.GetMassCostOfUnits(toNearbyAirAA, true)..'; our AirAA threat='..AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat]) end
                                    if iNearbyEnemyAir >= 10 and (iNearbyEnemyAir >= 15 or AiBotUnitInfo.GetMassCostOfUnits(toNearbyAirAA, true) >= 0.2 * AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat]) then
                                        bLikelyAirFight = true
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': bLikelyAirFight='..tostring(bLikelyAirFight)) end
                                if bLikelyAirFight then
                                    AssignAirAATargets(tAvailableAirAA, toEnemyAirAATargetsConsidered, iTeam, iAirSubteam, tExistingThreatAssignedByUnitRef, true, true)
                                end
                            end
                        end


                        --If still have available air send them to the support location (unless they could do with a fuel or health top-up); if theyre already there and have low mass consider ctrl-king inties
                        if bDebugMessages == true then LOG(sFunctionRef..': Finished considering AirAA targets for all land and water zones, is tAvailableAirAA empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableAirAA))..'; Is air rally outside playable area='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbOrigRallyOutsidePlayableArea])) end
                        if AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false then
                            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoAirAAForCoreEnemies] = false
                            if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbOrigRallyOutsidePlayableArea] then
                                --First check for enemy units near the revised rally point instead
                                local aiBrain
                                for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                                    if oBrain.AiBotAI then aiBrain = oBrain break end
                                end
                                local tEnemiesNearRally = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryAllAir, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint], 150, 'Enemy')
                                if bDebugMessages == true then LOG(sFunctionRef..': Is tEnemiesNearRally empty for backup given outside playable area='..tostring( AiBotUtilities.IsTableEmpty(tEnemiesNearRally))) end
                                if AiBotUtilities.IsTableEmpty(tEnemiesNearRally) == false then
                                    AssignAirAATargets(tAvailableAirAA, tEnemiesNearRally, iTeam, iAirSubteam, tExistingThreatAssignedByUnitRef)
                                end

                            end
                            if AiBotUtilities.IsTableEmpty(tAvailableAirAA) == false then
                                --Alternate where on the move point we will gather at, to try and make it more likely asfs will be facing the same direction when idling
                                local iAngleAdjust = (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiLastAirAASupportPointAngleAdjust] or 0) + 15
                                if iAngleAdjust >= 360 then iAngleAdjust = iAngleAdjust - 360 end
                                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiLastAirAASupportPointAngleAdjust] = iAngleAdjust
                                local iDistToMove = 20 --asf max speed is 22
                                local tMovePoint = AiBotUtilities.MoveInDirection(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint], iAngleAdjust, iDistToMove, true, false, AiBotMap.bIsCampaignMap)
                                if bDebugMessages == true and tMovePoint[1] > 10000 then LOG(sFunctionRef..': tMovePoint='..repru(tMovePoint)..'; reftAirAsfSupportPoint='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])..'; iAngleAdjust='..iAngleAdjust..'; iDistToMove='..iDistToMove..'; Time='..GetGameTimeSeconds()) end
                                if AiBotUtilities.IsTableEmpty(tMovePoint) then
                                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint]) == false then tMovePoint = {AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][1],AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][2],AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint][3]} end
                                    if AiBotUtilities.IsTableEmpty(tMovePoint) then
                                        AiBotUtilities.ErrorHandler('Have invalid move point due to no air support point, will try startp osition instead')
                                        tMovePoint = AiBotMap.GetPlayerStartPosition(AiBotTeam.GetFirstActiveAiBotBrain(iTeam), false)
                                    end
                                end

                                local bConsiderCtrlKOfInties = false
                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 3 and iAvailableAndInCombatAirAAThreat >= 1750 and AiBotConditions.TeamHasLowMass(iTeam) and AiBotUtilities.IsTableEmpty(tMovePoint) == false and (not(AiBotMap.bIsCampaignMap) or AiBotConditions.IsLocationInPlayableArea(tMovePoint)) then
                                    local tInties = EntityCategoryFilterDown(categories.TECH1, tAvailableAirAA)
                                    if AiBotUtilities.IsTableEmpty(tInties) == false then
                                        local tASFs = EntityCategoryFilterDown(categories.TECH3, tAvailableAirAA)
                                        if AiBotUtilities.IsTableEmpty(tASFs) == false and table.getn(tASFs) >= 6 then
                                            bConsiderCtrlKOfInties = true
                                        end
                                    end
                                end
                                local iIdleAirAACount = 0
                                local iDistToReissueMoveOrder = 10
                                if AiBotConditions.IsAirMoveLocationSafeToIdle(tMovePoint, iTeam, true) then iDistToReissueMoveOrder = 60 end

                                for iUnit, oUnit in tAvailableAirAA do
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering idle airAA order for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' Unit fuel='..oUnit:GetFuelRatio()..'; Unit health%='..AiBotUnitInfo.GetUnitHealthPercent(oUnit)..'; support point='..repru(tMovePoint)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; bConsiderCtrlKOfInties='..tostring(bConsiderCtrlKOfInties)..'; oUnit.Dead='..tostring(oUnit.Dead or false)) end
                                    if not(oUnit.Dead) then --redundancy
                                        if bConsiderCtrlKOfInties and EntityCategoryContains(categories.TECH1, oUnit.UnitId) then
                                            bConsiderCtrlKOfInties = false
                                            local bMoveUnitToRally = false
                                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tMovePoint) >= 10 then
                                                local tUnitZoneData, tUnitTeamZoneData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                                                if not(tUnitTeamZoneData[AiBotMap.subrefLZbCoreBase]) then bMoveUnitToRally = true end
                                            end
                                            if bMoveUnitToRally or oUnit[AiBotUnitInfo.refbCampaignTriggerAdded] then
                                                AiBotOrders.IssueTrackedMove(oUnit, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint], 10, false, 'AACtrlKI', false)
                                            else
                                                ForkThread(AiBotMicro.MoveAndKillAirUnit,oUnit)
                                                --AiBotOrders.IssueTrackedKillUnit(oUnit)
                                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 3 and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbOnlyGetASFs]) and AiBotConditions.GetTeamLifetimeBuildCount(iTeam, AiBotUnitInfo.refCategoryAirAA * categories.TECH3) > 0 then
                                                    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbOnlyGetASFs] = true
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': CtrlKing unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                                            end
                                        elseif ((oUnit:GetFuelRatio() < 0.6 and oUnit:GetFuelRatio() >= 0) or AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= 0.85) and not(EntityCategoryContains(categories.CANNOTUSEAIRSTAGING, oUnit.UnitId)) then
                                            table.insert(tAirForRefueling, oUnit)
                                        else
                                            if AiBotUtilities.IsTableEmpty(tMovePoint) == false then
                                                if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tMovePoint) <= iDistToReissueMoveOrder and oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition] and AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition], tMovePoint) <= iDistToReissueMoveOrder then
                                                    --Do nothing - idle on ground
                                                else
                                                    AiBotOrders.IssueTrackedMove(oUnit, tMovePoint, iDistToReissueMoveOrder, false, 'AAIdle', false)
                                                end
                                                iIdleAirAACount = iIdleAirAACount + 1
                                            end
                                        end
                                    elseif bDebugMessages == true then LOG(sFunctionRef..': Air unit appears to be dead?')
                                    end
                                end
                                if iIdleAirAACount >= 30 and iAvailableAndInCombatAirAAThreat >= 12000 and ScenarioInfo.Options.AiBotTeammate == 1 then
                                    --Consider gifting ASFs to a teammate if we haven't considered recently; only gift if they have more asfs than we do, and we lack air control
                                    if bDebugMessages == true then LOG(sFunctionRef..': Time since we last considered gifting asf to a teammate for airsubteam '..iAirSubteam..'='..(GetGameTimeSeconds() - (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiTimeLastConsideredGiftingASFToAlly] or -100))) end
                                    if GetGameTimeSeconds() - (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiTimeLastConsideredGiftingASFToAlly] or -100) >= 30 then
                                        AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiTimeLastConsideredGiftingASFToAlly] = GetGameTimeSeconds()
                                        if bDebugMessages == true then LOG(sFunctionRef..': Have air control='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl])..'; Table of friendly human and ai brains empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]))..'; AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat]='..AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat]..'; iAvailableAndInCombatAirAAThreat='..iAvailableAndInCombatAirAAThreat) end
                                        if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains]) == false then
                                            local iHumanHighestAirAAThreat = 0
                                            local oHumanHighestAirAAThreat
                                            local iAllTeamAirAAThreat = 0
                                            local iCurAirAAThreat = 0
                                            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
                                                if not(oBrain.AiBotAI) and (oBrain.Human or (not(oBrain.BrainType == 'AI') and not(AiBotConditions.IsCivilianBrain(oBrain)))) then
                                                    iCurAirAAThreat = AiBotUnitInfo.GetMassCostOfUnits(oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryAirAA * categories.TECH3, false, true))
                                                    iAllTeamAirAAThreat = iAllTeamAirAAThreat + iCurAirAAThreat
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering human '..oBrain.Nickname..'; iCurAirAAThreat='..iCurAirAAThreat..'; iAllTeamAirAAThreat='..iAllTeamAirAAThreat) end
                                                    if iCurAirAAThreat > iHumanHighestAirAAThreat then
                                                        iHumanHighestAirAAThreat = iCurAirAAThreat
                                                        oHumanHighestAirAAThreat = oBrain
                                                    end
                                                end
                                            end
                                            if iHumanHighestAirAAThreat >= math.max(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] * 1.3, 15000) then
                                                --Want to gift some of our ASF to teammate
                                                local tOurASFs = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAirAA *  categories.TECH3, tAvailableAirAA)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Is table of our available asfs empty='..tostring(AiBotUtilities.IsTableEmpty(tOurASFs))) end
                                                if AiBotUtilities.IsTableEmpty(tOurASFs) == false then
                                                    local toUnitsToConsiderGifting = {}
                                                    local iASFCount = 0
                                                    for iASF, oASF in tOurASFs do
                                                        if oASF[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueMove and not(oASF[AiBotUnitInfo.refbSpecialMicroActive]) and (AiBotOrders.bDontConsiderCombinedArmy or oASF.AiBotActive) then
                                                            iASFCount = iASFCount + 1
                                                            table.insert(toUnitsToConsiderGifting, oASF)
                                                        end
                                                    end
                                                    if bDebugMessages == true then LOG(sFunctionRef..': iASFCount='..iASFCount) end
                                                    if iASFCount >= 30 then
                                                        local toASFToGive = {}
                                                        local iASFToGive = iASFCount - iMinimumASFCountPostGifting
                                                        for iASF, oASF in toUnitsToConsiderGifting do
                                                            table.insert(toASFToGive, oASF)
                                                            if iASF >= iASFToGive then break end
                                                        end
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Transferring '..iASFToGive..' to player '..oHumanHighestAirAAThreat.Nickname) end
                                                        AiBotChat.SendMessage(toUnitsToConsiderGifting[1]:GetAIBrain(), 'GiveASFs', 'We should combine our air forces to maintain air control, I\'ve just transferred '..iASFToGive..' of my fighters to you '..oHumanHighestAirAAThreat.Nickname..', I trust you\'ll keep the skies clear of hostiles', 0.1, 900, true, true)
                                                        AiBotTeam.TransferUnitsToPlayer(toASFToGive, oHumanHighestAirAAThreat:GetArmyIndex())
                                                        AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoLastHumanGiftedASFs] = oHumanHighestAirAAThreat
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    --Send units for refueling
    if bDebugMessages == true then
        LOG(sFunctionRef..': Finished giving availableAA orders, is table of air for refueling empty='..tostring(AiBotUtilities.IsTableEmpty(tAirForRefueling)))
        if AiBotUtilities.IsTableEmpty(tAirForRefueling) == false then
            for iUnit, oUnit in tAirForRefueling do
                LOG(sFunctionRef..': Entry for refueling='..iUnit..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit))
            end
        end
    end
    --Run the function even if no units wanting refueling so already attached untis can be sent on their way
    SendUnitsForRefueling(tAirForRefueling, iTeam, iAirSubteam)
    if bDebugMessages == true and AiBotUtilities.IsTableEmpty(tAirForRefueling) == false then
        LOG(sFunctionRef..': Will send '..table.getn(tAirForRefueling)..' units to refuel')
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function EnemyBaseEarlyBomber(oBomber)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'EnemyBaseEarlyBomber'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oBomber) then
        local aiBrain = oBomber:GetAIBrain()
        local iTeam = aiBrain.AiBotTeam
        local iAirSubteam = aiBrain.AiBotAirSubteam
        local tEnemyBase

        --Get closest enemy base
        local iStartPlateauOrZero, iStartLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oBomber:GetPosition())
        if not(iStartLandOrWaterZone) or (iStartPlateauOrZero or 0) == 0 then
            iStartPlateauOrZero, iStartLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotMap.GetPlayerStartPosition(oBomber:GetAIBrain()))
        end
        if iStartPlateauOrZero and iStartLandOrWaterZone and iStartPlateauOrZero > 0 then
            local tStartLZTeamData = AiBotMap.tAllPlateaus[iStartPlateauOrZero][AiBotMap.subrefPlateauLandZones][iStartLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
            tEnemyBase = tStartLZTeamData[AiBotMap.reftClosestEnemyBase]
        end
        if bDebugMessages == true then LOG(sFunctionRef..': tEnemyBase='..repru(tEnemyBase)..'; Dist to enemy base='..AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tEnemyBase)) end
        if AiBotUtilities.IsTableEmpty(tEnemyBase) == false then
            local iEnemyBasePlateau, iEnemyBaseZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tEnemyBase)
            if (iEnemyBasePlateau or 0) > 0 and iEnemyBaseZone then
                local tEnemyBaseLZData = AiBotMap.tAllPlateaus[iEnemyBasePlateau][AiBotMap.subrefPlateauLandZones][iEnemyBaseZone]
                local tEnemyBaseLZTeamData = tEnemyBaseLZData[AiBotMap.subrefLZTeamData][iTeam]
                local tEnemyTargets = {}
                local tEnemyInitialDestination
                if AiBotUtilities.IsTableEmpty(tEnemyBaseLZData[AiBotMap.subrefHydroLocations]) == false then
                    local iCurDist
                    local iClosestHydro = 10000
                    for iHydro, tHydro in tEnemyBaseLZData[AiBotMap.subrefHydroLocations] do
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tEnemyBase, tHydro)
                        if iCurDist < iClosestHydro then
                            tEnemyInitialDestination = {tHydro[1], tHydro[2], tHydro[3]}
                        end
                    end
                end
                if not(tEnemyInitialDestination) then tEnemyInitialDestination = {tEnemyBase[1], tEnemyBase[2], tEnemyBase[3]} end

                AiBotMicro.TrackTemporaryUnitMicro(oBomber, 0, nil, true)

                local bReachedInitialLocation = false
                local bReachedEnemyStart = false
                local iTicksToWait
                local bDontConsiderPlayableArea = not(AiBotMap.bIsCampaignMap)
                if bDebugMessages == true then LOG(sFunctionRef..': About to start main loop, iEnemyBasePlateau='..iEnemyBasePlateau..'; iEnemyBaseZone='..iEnemyBaseZone..'; About to start main loop, refbSpecialMicroActive='..tostring(oBomber[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                --Start main loop
                while AiBotUnitInfo.IsUnitValid(oBomber) and oBomber[rebEarlyBomberTargetBase] do
                    --Remove any existing assigned strike damage (will re-add if we retain target)
                    if not(oBomber[AiBotUnitInfo.refbSpecialMicroActive]) then AiBotMicro.TrackTemporaryUnitMicro(oBomber, 0, nil, true) end
                    local tLastOrder = oBomber[AiBotOrders.reftiLastOrders][oBomber[AiBotOrders.refiOrderCount]]
                    local oExistingValidAttackTarget
                    local iCurBomberPlateauOrZero, iCurBomberZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oBomber:GetPosition())
                    local tBomberLastTarget
                    if tLastOrder and tLastOrder[AiBotOrders.subrefoOrderUnitTarget] and (tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack or tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueGroundAttack) and AiBotUnitInfo.IsUnitValid(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) then
                        oExistingValidAttackTarget = tLastOrder[AiBotOrders.subrefoOrderUnitTarget]
                        if AiBotUnitInfo.IsUnitValid(oExistingValidAttackTarget) then tBomberLastTarget = oExistingValidAttackTarget:GetPosition() end
                        RemoveAssignedAttacker(oExistingValidAttackTarget, oBomber)
                    end
                    if not(tBomberLastTarget) and tLastOrder then
                        tBomberLastTarget = tLastOrder[AiBotOrders.subreftOrderPosition]
                        if AiBotUtilities.IsTableEmpty(tBomberLastTarget) then
                            tBomberLastTarget = tEnemyInitialDestination
                        end
                    end

                    iTicksToWait = 10

                    --If enemy base has MAA in it, then abort logic
                    if AiBotConditions.EnemyZoneHasTooMuchAAForBaseBomber(tEnemyBaseLZTeamData, tEnemyBaseLZData, oBomber) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy has MAA to abort logic') end
                        oBomber[rebEarlyBomberTargetBase] = false
                        --Return to base as temporary order (normal engi hunter logic should take over shortly)
                        AiBotOrders.IssueTrackedMove(oBomber, tEnemyBaseLZTeamData[AiBotMap.reftClosestFriendlyBase], 5, false, '1stBombAb', true)
                        break
                    elseif iCurBomberPlateauOrZero and iCurBomberZone and (not(iCurBomberZone == iEnemyBaseZone) or not(iCurBomberPlateauOrZero == iEnemyBasePlateau)) and DoesEnemyHaveAAThreatAlongPath(iTeam, iCurBomberPlateauOrZero, iCurBomberZone, iEnemyBasePlateau, iEnemyBaseZone, false, 45, 50, false, iAirSubteam, true, false, oBomber:GetPosition(), false, tBomberLastTarget, true, false) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Too much AA threat along path to enemy base so will abort') end
                        oBomber[rebEarlyBomberTargetBase] = false
                        --Return to base as temporary order (normal engi hunter logic should take over shortly)
                        AiBotOrders.IssueTrackedMove(oBomber, tEnemyBaseLZTeamData[AiBotMap.reftClosestFriendlyBase], 5, false, '1stBombAb', true)
                        break
                        --If we arent in enemy base yet, then travel to enemy base
                    elseif not((iStartLandOrWaterZone == iEnemyBaseZone and iStartPlateauOrZero == iEnemyBasePlateau) or AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tEnemyInitialDestination) <= 90) then
                        --If we are targeting an enemy engineer that isn't too far from us then still attack it
                        local bAttackExistingTarget = false
                        if AiBotUnitInfo.IsUnitValid(oExistingValidAttackTarget) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Dist to existing target='..AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), oExistingValidAttackTarget:GetPosition())..'; Bomber range='..(oBomber[AiBotUnitInfo.refiBomberRange] or 'nil')..'; Bomb missed count='..(oExistingValidAttackTarget[AiBotUnitInfo.refiBombMissedCount] or 'nil')) end
                            if AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), oExistingValidAttackTarget:GetPosition()) <= 20 + (oBomber[AiBotUnitInfo.refiBomberRange] or 30) and (oExistingValidAttackTarget[AiBotUnitInfo.refiBombMissedCount] or 0) <= 1 then
                                bAttackExistingTarget = true
                                AssignTorpOrBomberTargets({ oBomber}, { oExistingValidAttackTarget }, iAirSubteam, false, false, true)
                                if bDebugMessages == true then LOG(sFunctionRef..': will keep attacking existing target') end
                            end
                        end
                        if not(bAttackExistingTarget) then
                            --Travel to enemy base/hydro
                            AiBotOrders.IssueTrackedMove(oBomber, tEnemyInitialDestination, 5, false, '1stBombBM', true)
                            if bDebugMessages == true then LOG(sFunctionRef..': Will send bomber to enemy base, oExistingValidAttackTarget='..(oExistingValidAttackTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oExistingValidAttackTarget) or 'nil')) end
                        end
                    else
                        iTicksToWait = 1
                        --We are at or near enemy base/hydro, so search for engineers and pgens to attack; if are none, but we have located enemy units, then switch to engi hunter mode
                        if not(bReachedInitialLocation) and AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tEnemyInitialDestination) <= 20 then
                            bReachedInitialLocation = true
                        elseif not(bReachedEnemyStart) and AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tEnemyBase) <= 20 then
                            bReachedEnemyStart = true
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Searching for enemy engineers and pgens to attack, bReachedInitialLocation='..tostring(bReachedInitialLocation)..'; bReachedEnemyStart='..tostring(bReachedEnemyStart)..'; Is table of enemy units in the LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyBaseLZTeamData[AiBotMap.subrefTEnemyUnits]))) end

                        tEnemyTargets = {}
                        local tEnemyPgensAndLowHealthTanks
                        local iAOE, iStrikeDamage = AiBotUnitInfo.GetBomberAOEAndStrikeDamage(oBomber)

                        --For some reason doing FilterToAvailableTargets doesnt work, so having to manually reproduce here
                        if AiBotUtilities.IsTableEmpty(tEnemyBaseLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                            for iUnit, oUnit in tEnemyBaseLZTeamData[AiBotMap.subrefTEnemyUnits] do
                                if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
                                if AiBotUnitInfo.IsUnitValid(oUnit) and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) and (bDontConsiderPlayableArea or AiBotConditions.IsLocationInPlayableArea(oUnit:GetPosition())) and oUnit:GetFractionComplete() >= 0.9 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering potential target='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) or (EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oUnit.UnitId) and oUnit:GetHealth() <= iStrikeDamage and oUnit:GetFractionComplete() == 1) then
                                        table.insert(tEnemyTargets, oUnit)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Adding unit to enemy targets table') end
                                    elseif EntityCategoryContains(AiBotUnitInfo.refCategoryT1Power - AiBotUnitInfo.refCategoryHydro, oUnit.UnitId) then
                                        if not(tEnemyPgensAndLowHealthTanks) then tEnemyPgensAndLowHealthTanks = {} end
                                        table.insert(tEnemyPgensAndLowHealthTanks, oUnit)
                                        --Clumped up tanks that can one-shot at least 1 of - also consider
                                    elseif oUnit:GetHealth() <= iStrikeDamage and AiBotUnitInfo.GetUnitMassCost(oUnit) >= 50 and oUnit:GetFractionComplete() == 1 and EntityCategoryContains(AiBotUnitInfo.refCategoryMobileLand, oUnit.UnitId) then
                                        if not(tEnemyPgensAndLowHealthTanks) then tEnemyPgensAndLowHealthTanks = {} end
                                        table.insert(tEnemyPgensAndLowHealthTanks, oUnit)
                                    end
                                end
                            end
                            if AiBotUtilities.IsTableEmpty(tEnemyTargets) and tEnemyPgensAndLowHealthTanks then
                                if bDebugMessages == true then LOG(sFunctionRef..': No enemy engineers so will include pgens and low health tanks as potential targets') end
                                tEnemyTargets = tEnemyPgensAndLowHealthTanks
                            end
                        end

                        if bDebugMessages == true then LOG(sFunctionRef..': Finished searching for enemy targets, is table empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyTargets))..'; Time='..GetGameTimeSeconds()) end
                        if AiBotUtilities.IsTableEmpty(tEnemyTargets) then
                            --If reached enemy base and hydro then abort this logic and switch to normal engi hunter logic
                            if not(bReachedInitialLocation) then
                                if bDebugMessages == true then LOG(sFunctionRef..'; No enemy targets, will go to the initial destination') end
                                AiBotOrders.IssueTrackedMove(oBomber, tEnemyInitialDestination, 5, false, '1stBombCM', true)
                            elseif not(bReachedEnemyStart) then
                                if bDebugMessages == true then LOG(sFunctionRef..'; No enemy targets, will go to the enemy base') end
                                AiBotOrders.IssueTrackedMove(oBomber, tEnemyBase, 5, false, '1stBombDM', true)
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': No enemy engis or t1 pgens so will switch to default engi hunter logic') end
                                oBomber[rebEarlyBomberTargetBase] = false
                                --Return to base as temporary order (normal engi hunter logic should take over shortly)
                                AiBotOrders.IssueTrackedMove(oBomber, tEnemyBaseLZTeamData[AiBotMap.reftClosestFriendlyBase], 5, false, '1stBombXb', true)
                                break
                            end
                        else
                            --Target enemies, hover-bombing if the target is close
                            local oNearestEnemy
                            local oSecondNearestEnemy
                            local iClosestDist = 10000
                            local iSecondClosestDist = 10000
                            local iModDist, iCurDamage
                            local iSingleEngiValue = 52
                            iStrikeDamage = math.max(150, iStrikeDamage) --assume we can 1-shot all engineers in case it gives strange results if we cant

                            for iUnit, oUnit in tEnemyTargets do
                                iModDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oBomber:GetPosition())
                                if iModDist < iSecondClosestDist and oUnit:GetHealth() > oBomber[AiBotUnitInfo.refiStrikeDamage] then
                                    if oUnit:GetHealth() > oBomber[AiBotUnitInfo.refiStrikeDamage] * 2 then
                                        iModDist = iModDist + 22
                                    else
                                        iModDist = iModDist + 15
                                    end
                                end --Prioritise targets we think we can kill in 1-2 hits
                                if oUnit[AiBotUnitInfo.refiBombMissedCount] then iModDist = iModDist + 40 * oUnit[AiBotUnitInfo.refiBombMissedCount] end
                                --Reduce mod dist if there are other engineers nearby
                                if iModDist - 40 < iClosestDist then
                                    iCurDamage = AiBotLogic.GetDamageFromBomb(aiBrain, oUnit:GetPosition(), iAOE, iStrikeDamage, nil, nil, nil, nil, nil, 0.8, nil, nil, true, nil, nil, nil, nil, nil)
                                    if iCurDamage > iSingleEngiValue then
                                        --Prioritise bombs that might hit multiple engineers
                                        iModDist = iModDist - math.min(70, 40 * iCurDamage / iSingleEngiValue)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Adjusting mod dist to factor aoe') end
                                    end
                                end
                                if iModDist < iClosestDist then
                                    oSecondNearestEnemy = oNearestEnemy
                                    iSecondClosestDist = iClosestDist
                                    oNearestEnemy = oUnit
                                    iClosestDist = iModDist
                                elseif iModDist < iSecondClosestDist then
                                    oSecondNearestEnemy = oUnit
                                    iSecondClosestDist = iModDist
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Targeting enemy units, will consider if want to hover bomb, iClosestDist='..iClosestDist..'; Time since last fired a bomb='..GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastBombFired] or 0)..'; iSecondClosestDist='..iSecondClosestDist..'; oNearestEnemy='..(oNearestEnemy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemy) or 'nil'))
                                if oNearestEnemy then LOG(sFunctionRef..': Health of oNearestEnemy='..oNearestEnemy:GetHealth()..'; Bomber strike damage='..oBomber[AiBotUnitInfo.refiStrikeDamage]) end
                            end
                            --Hover-bomb if we have fired relatively recently
                            if not(AiBotUtilities.bLoudModActive) and oNearestEnemy and iClosestDist <= 70 and ((oBomber[AiBotUnitInfo.refiLastBombFired] and GetGameTimeSeconds() - oBomber[AiBotUnitInfo.refiLastBombFired] <= 10) or (not(oBomber[AiBotUnitInfo.refiLastBombFired]) and iClosestDist <= 0 and not(AiBotUnitInfo.IsUnitValid(oExistingValidAttackTarget)) and oNearestEnemy:GetHealth() <= oBomber[AiBotUnitInfo.refiStrikeDamage])) and
                                    (oNearestEnemy:GetHealth() > oBomber[AiBotUnitInfo.refiStrikeDamage] or (iClosestDist < 50 and iSecondClosestDist < 50) or
                                            --If fired recently but not really recently then presumably our bomb missed so we want to fire at this target again
                                            (oBomber[AiBotUnitInfo.refiLastBombFired] and GetGameTimeSeconds() - oBomber[AiBotUnitInfo.refiLastBombFired] >= 3)) then
                                --AiBotMicro.HoverBombTarget(oBomber, oNearestEnemy)
                                if bDebugMessages == true then LOG(sFunctionRef..': Will call hoverbomb logic to target '..oNearestEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemy)) end
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                --NOTE: Dont call via fork thread, as otherwise we end up calling the same logic multiple times and it overriding orders
                                AiBotMicro.T1OrT3HoverBombTarget(oBomber, oNearestEnemy, true, (EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oNearestEnemy.UnitId) or oNearestEnemy:GetFractionComplete() < 1), true) --Dont do via fork thread, as want this logic to be dleayed so we dont rerun it
                                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                                if bDebugMessages == true then LOG(sFunctionRef..': Finished hoverbomb attempt') end
                                iTicksToWait = 1 --Just to avoid infinite loop risk
                            else
                                if AiBotUnitInfo.IsUnitValid(oNearestEnemy) then
                                    AiBotOrders.IssueTrackedAttack(oBomber, oNearestEnemy, false, 'BaseBmAt'..oNearestEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestEnemy), oBomber[AiBotUnitInfo.refbLowerPriorityMicroActive])
                                else --redundancy
                                    if bDebugMessages == true then LOG(sFunctionRef..': WIll use normal bomber attack logic') end
                                    AssignTorpOrBomberTargets({ oBomber}, tEnemyTargets, iAirSubteam, false, false, true)
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': End of loop, will wait '..iTicksToWait..' ticks, refbSpecialMicroActive='..tostring(oBomber[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitTicks(iTicksToWait)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    if bDebugMessages == true then LOG(sFunctionRef..': Finished waiting iTicksToWait, refbSpecialMicroActive='..tostring(oBomber[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                end
            end
        end
    end
    if oBomber[AiBotUnitInfo.refbSpecialMicroActive] then
        oBomber[AiBotUnitInfo.refbSpecialMicroActive] = false
        oBomber[AiBotUnitInfo.refbLowerPriorityMicroActive] = false
        ForkThread(AiBotMicro.ForkedResetMicroFlag, oBomber, 0) --redundancy
    end
    oBomber[rebEarlyBomberTargetBase] = false
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ApplyEngiHuntingBomberLogic(oBomber, iAirSubteam, iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ApplyEngiHuntingBomberLogic'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oBomber='..(oBomber.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oBomber) or 'nil')..' owned by '..oBomber:GetAIBrain().Nickname..'; AirSubteam='..iAirSubteam..'; iTeam='..iTeam..'; Time='..GetGameTimeSeconds()..'; Brain owner='..oBomber:GetAIBrain().Nickname) end
    local bContinue = true
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftiTimeOfLastEngiHunterBomberOrder] = GetGameTimeSeconds()
    if oBomber[rebEarlyBomberTargetBase] == nil and (GetGameTimeSeconds() <= 120 or oBomber:GetAIBrain()[AiBotOverseer.refbFirstBomber]) and AiBotUnitInfo.GetUnitLifetimeCount(oBomber) == 1 then
        if GetGameTimeSeconds() > 120 then
            oBomber[rebEarlyBomberTargetBase] = false
        else
            oBomber[rebEarlyBomberTargetBase] = true
            ForkThread(EnemyBaseEarlyBomber, oBomber)
            if bDebugMessages == true then LOG(sFunctionRef..': Starting early base bomber logic') end
            bContinue = false
        end
    elseif oBomber[refiBomberTargetNavalEngiWZ] == nil and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis]) == false then
        local iClosestWZDist = 10000
        local iClosestWZRef, iCurDist
        for iCurWZ, iBombersWanted in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis] do
            if iBombersWanted > 0 then
                local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurWZ]][AiBotMap.subrefPondWaterZones][iCurWZ]
                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tWZData[AiBotMap.subrefMidpoint])
                if iCurDist < iClosestWZDist then
                    iClosestWZDist = iCurDist
                    iClosestWZRef = iCurWZ
                end
            end
        end
        if iClosestWZRef then
            oBomber[refiBomberTargetNavalEngiWZ] = iClosestWZRef
            AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis][iClosestWZRef] = AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis][iClosestWZRef] - 1
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis][iClosestWZRef] <= 0 then
                AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis][iClosestWZRef] = nil
            end
            ForkThread(EnemyNavalEngineerBomber, oBomber)
        end
    elseif bDebugMessages == true then LOG(sFunctionRef..': Will consider normal bomber logic')
    end
    if bContinue then
        local tBomberTable = {oBomber}
        local tEnemyTargets = {}
        --Engi hunter logic - search outwards from the bomber for the closest engineer that doesnt have groundAA protecting it
        local iStartPlateauOrZero, iStartLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oBomber:GetPosition())
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code for unit '..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; Position='..repru(oBomber:GetPosition())..'; iStartPlateauOrZero='..(iStartPlateauOrZero or 'nil')..'; iStartLandOrWaterZone='..(iStartLandOrWaterZone or 'nil')..'; Special micro='..tostring(oBomber[AiBotUnitInfo.refbSpecialMicroActive])..'; GameTime='..GetGameTimeSeconds()) end
        if (iStartLandOrWaterZone or 0) > 0 and not(oBomber[AiBotUnitInfo.refbSpecialMicroActive]) then
            local tStartLZOrWZData, tStartLZOrWZTeamData
            if iStartPlateauOrZero == 0 then
                tStartLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iStartLandOrWaterZone]
                tStartLZOrWZTeamData = tStartLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
            else
                tStartLZOrWZData = AiBotMap.tAllPlateaus[iStartPlateauOrZero][AiBotMap.subrefPlateauLandZones][iStartLandOrWaterZone]
                tStartLZOrWZTeamData = tStartLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
            end

            if tStartLZOrWZData then
                function FilterToAvailableTargets(tPotentialTargets, iOptionalCategory) --COPY OF BELOW from managebombers, but with adj to ignore part-complete units
                    if AiBotUtilities.IsTableEmpty(tPotentialTargets) == false then
                        local bDontConsiderPlayableArea = not(AiBotMap.bIsCampaignMap)
                        for iUnit, oUnit in tPotentialTargets do
                            if bDebugMessages == true then
                                if AiBotUnitInfo.IsUnitValid(oUnit) then LOG(sFunctionRef..': Considering if potential target is valid, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; IsUnitUnderwater='..tostring(AiBotUnitInfo.IsUnitUnderwater(oUnit))..'; IsLocationInPlayableArea='..tostring(AiBotConditions.IsLocationInPlayableArea(oUnit:GetPosition()))..'; has desired category='..tostring(not(iOptionalCategory) or EntityCategoryContains(iOptionalCategory, oUnit.UnitId)))
                                else LOG(sFunctionRef..': Unit invalid, oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil'))
                                end
                            end
                            if AiBotUnitInfo.IsUnitValid(oUnit) and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) and (bDontConsiderPlayableArea or AiBotConditions.IsLocationInPlayableArea(oUnit:GetPosition())) and (oUnit:GetFractionComplete() >= 0.9 or EntityCategoryContains(AiBotUnitInfo.refCategoryGroundAA, oUnit.UnitId)) then
                                if not(iOptionalCategory) or EntityCategoryContains(iOptionalCategory, oUnit.UnitId) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding to tEnemyTargets') end
                                    table.insert(tEnemyTargets, oUnit)
                                end
                            end
                        end
                    end
                end


                local bDontCheckForPacifism = not(AiBotOverseer.bPacifistModeActive)
                local iEngiHunterCategories = AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryRadar
                if bDontCheckForPacifism or not(tStartLZOrWZData[AiBotMap.subrefbPacifistArea]) then FilterToAvailableTargets(tStartLZOrWZTeamData[AiBotMap.subrefTEnemyUnits], iEngiHunterCategories) end
                local bDontCheckForEnemyThreats = false
                local bAbort = false
                --Run to base if zone has AA and we arent targeting an engineer already
                local tLastOrder = oBomber[AiBotOrders.reftiLastOrders][oBomber[AiBotOrders.refiOrderCount]]
                if not(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) or not(EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryRadar, tLastOrder[AiBotOrders.subrefoOrderUnitTarget].UnitId)) then
                    --Arent targeting an engineer currently, so abort if there is AA in the same zone as the bomber (e.g. this might be relevant if have switched from base hunter logic)
                    if AiBotConditions.EnemyZoneHasTooMuchAAForBaseBomber(tStartLZOrWZTeamData, tStartLZOrWZData, oBomber) then
                        --Return to base
                        AiBotOrders.IssueTrackedMove(oBomber, tStartLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], 5, false, 'AbortEHb', true)
                        bAbort = true
                    end
                elseif (tStartLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) > 0 then bDontCheckForEnemyThreats = true
                end
                if bDebugMessages == true then LOG(sFunctionRef..': bAbort after checking for groundAA in cur zone (if bomber not targeting engineer)='..tostring(bAbort)) end
                if not(bAbort) then
                    RecordOtherLandAndWaterZonesByDistance(tStartLZOrWZData, tStartLZOrWZData[AiBotMap.subrefMidpoint])

                    if bDebugMessages == true then LOG(sFunctionRef..': Finished checking for targets in starting zone, is table of enemy targets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyTargets))) end
                    local iSearchSize = 500
                    if AiBotUtilities.IsTableEmpty( tEnemyTargets) == false then
                        iSearchSize = 100 --we also test if it is 100 lower down
                        --[[if bDebugMessages == true then LOG(sFunctionRef..': Assigning bomber targets for Engi hunter for units in bomber cur zone') end
                        AssignTorpOrBomberTargets(tBomberTable, tEnemyTargets, iAirSubteam, false, true)
                        tEnemyTargets = {}--]]
                    end

                    if AiBotUtilities.IsTableEmpty(tBomberTable) == false and AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                        for iEntry, tPathingDetails in tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                            local iOtherPlateauOrZero = tPathingDetails[AiBotMap.subrefiPlateauOrPond]
                            local iOtherLZOrWZ = tPathingDetails[AiBotMap.subrefiLandOrWaterZoneRef]
                            if tPathingDetails[AiBotMap.subrefbIsWaterZone] then iOtherPlateauOrZero = 0 end
                            if iOtherLZOrWZ then
                                local tOtherLZOrWZData
                                local tOtherLZOrWZTeamData
                                if iOtherPlateauOrZero == 0 then
                                    tOtherLZOrWZData = AiBotMap.tPondDetails[tPathingDetails[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][iOtherLZOrWZ]
                                    tOtherLZOrWZTeamData = tOtherLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                else
                                    tOtherLZOrWZData = AiBotMap.tAllPlateaus[iOtherPlateauOrZero][AiBotMap.subrefPlateauLandZones][iOtherLZOrWZ]
                                    tOtherLZOrWZTeamData = tOtherLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                end
                                if (tOtherLZOrWZData[AiBotMap.subrefLZTravelDist] or 0) > iSearchSize then break end
                                if bDontCheckForPacifism or not(tOtherLZOrWZData[AiBotMap.subrefbPacifistArea]) then
                                    --Ignore targets with shielding or AA
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering enemies in iOtherPlateauOrZero='..(iOtherPlateauOrZero or 'nil')..'; iOtherLZOrWZ='..(iOtherLZOrWZ or 'nil')..'; Enemy shield threat='..(tOtherLZOrWZTeamData[AiBotMap.subrefThreatEnemyShield] or 0)..'; GroundAA='.. (tOtherLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)..'; Enemy AirAA='..(tOtherLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)) end
                                    if bDontCheckForEnemyThreats or ((tOtherLZOrWZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) == 0 and (tOtherLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) == 0 and (tOtherLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) == 0) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Does enemy have AA threat along the path to this zone='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iOtherPlateauOrZero, iOtherLZOrWZ, true, 1, 400, false, iAirSubteam, true, false, oBomber:GetPosition(),                      false,                                  nil,                                        false,                              false))) end
                                        --DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck, bReturnGroundAAUnitsAlongsideAAThreat, tOptionalEndMidpointAdjustForDetailedCheck, bOptionalIgnoreOppositeDirectionZones, bIncludeEnemyGroundAAInAirAAThreat)
                                        if bDontCheckForEnemyThreats or not(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iOtherPlateauOrZero, iOtherLZOrWZ,            true,               1,                      400,                    false,          iAirSubteam, true,                      false,                          oBomber:GetPosition(),                      false,                                  nil,                                        false,                              false)) then
                                            FilterToAvailableTargets(tOtherLZOrWZTeamData[AiBotMap.subrefTEnemyUnits], iEngiHunterCategories)
                                            if bDebugMessages == true then
                                                LOG(sFunctionRef..': Considering iOtherPlateauOrZero='..(iOtherPlateauOrZero or 'nil')..'; iOtherLZOrWZ='..(iOtherLZOrWZ or 'nil')..'; dist='..(tPathingDetails[AiBotMap.subrefiDistance] or 'nil')..'; iSearchSize='..(iSearchSize or 'nil')..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tOtherLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]))..'; Is table of targets empty='..tostring(AiBotUtilities.IsTableEmpty( tEnemyTargets)))
                                            end
                                            if AiBotUtilities.IsTableEmpty( tEnemyTargets) == false then
                                                if iSearchSize > 100 then iSearchSize = 100 end --we also set it to 100 further up
                                                --[[if bDebugMessages == true then LOG(sFunctionRef..': Assigning bomber targets for Engi hunter, iOtherLZOrWZ='..iOtherLZOrWZ) end
                                                AssignTorpOrBomberTargets(tBomberTable, tEnemyTargets, iAirSubteam, false, true)
                                                tEnemyTargets = {}
                                                if AiBotUtilities.IsTableEmpty(tBomberTable) then break end--]]
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Finished searching for targets in other zones, is tEnemyTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyTargets))) end
                    if AiBotUtilities.IsTableEmpty(tEnemyTargets) == false then
                        --Pick the best target, based on distance, aoe damage, and angle to us
                        local iAOE, iStrikeDamage = AiBotUnitInfo.GetBomberAOEAndStrikeDamage(oBomber)
                        iStrikeDamage = math.max(150, iStrikeDamage) --assume we can 1-shot all engineers in case it gives strange results if we cant
                        local tAltEnemyTargets = {}
                        local oBestEnemyTarget
                        if table.getn(tEnemyTargets) == 1 then
                            oBestEnemyTarget = tEnemyTargets[1]
                            if bDebugMessages == true then LOG(sFunctionRef..': Only have 1 potnetial target so will just target this, target='..tEnemyTargets[1].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEnemyTargets[1])) end
                        else
                            local iClosestEnemy = 100000
                            local iCurDist
                            for iUnit, oUnit in tEnemyTargets do
                                if (oUnit[refiStrikeDamageAssigned] or 0) == 0 then
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oBomber:GetPosition())
                                    if iCurDist < iClosestEnemy then
                                        iClosestEnemy = iCurDist
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iClosestEnemy='..iClosestEnemy) end
                            local iCurDamage
                            local iBestDamage = 0
                            local aiBrain = oBomber:GetAIBrain()
                            local iMaxDist = iClosestEnemy + 75
                            for iUnit, oUnit in tEnemyTargets do
                                --Check not already trying to kill the target
                                if (oUnit[refiStrikeDamageAssigned] or 0) == 0 then
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oBomber:GetPosition())
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to target enemy oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Damage from bomb='..AiBotLogic.GetDamageFromBomb(aiBrain, oUnit:GetPosition(), iAOE, iStrikeDamage, nil, nil, nil, nil, nil, 0.8, nil, nil, true, nil, nil, nil, nil, nil)..'; Best damage so far='..iBestDamage..'; Dist to unit='..iCurDist..'; iMaxDist='..iMaxDist) end
                                    if iCurDist <= iMaxDist then

                                        iCurDamage = AiBotLogic.GetDamageFromBomb(aiBrain, oUnit:GetPosition(), iAOE, iStrikeDamage, nil, nil, nil, nil, nil, 0.8, nil, nil, true, nil, nil, nil, nil, nil)
                                        if oUnit[AiBotUnitInfo.refiBombMissedCount] then iCurDamage = iCurDamage / (oUnit[AiBotUnitInfo.refiBombMissedCount] + 1) end
                                        if iCurDamage > iBestDamage and (iCurDist <= iClosestEnemy + 40 or iCurDamage > iBestDamage * 1.4) then
                                            iBestDamage = iCurDamage
                                            oBestEnemyTarget = oUnit
                                            if bDebugMessages == true then LOG(sFunctionRef..': Updating oBestEnemyTarget to be oUnit') end
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Multiple potential targets to pick from, after considering these oBestEnemyTarget='..(oBestEnemyTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oBestEnemyTarget) or 'nil')) end
                        end
                        if oBestEnemyTarget then
                            tAltEnemyTargets = {oBestEnemyTarget}
                            local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oBestEnemyTarget:GetPosition(), oBomber:GetPosition())
                            local iAngleToTarget = AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), oBestEnemyTarget:GetPosition())
                            local iBomberFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oBomber)
                            local iAngleDifToTarget = AiBotUtilities.GetAngleDifference(iBomberFacingAngle, iAngleToTarget)
                            local iTimeUntilReadyToFire = AiBotUnitInfo.GetTimeUntilReadyToFireBomb(oBomber)
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to micro turn to target, Dist to target='..AiBotUtilities.GetDistanceBetweenPositions(oBestEnemyTarget:GetPosition(), oBomber:GetPosition())..'; Unit facing angle='..AiBotUnitInfo.GetUnitFacingAngle(oBomber)..'; Angle to target='..AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), oBestEnemyTarget:GetPosition())..'; oBomber[refiTimeBetweenBombs]='..(oBomber[AiBotUnitInfo.refiTimeBetweenBombs] or 'nil')..'; Bomber range='..oBomber[AiBotUnitInfo.refiBomberRange]..'; Bomber speed='..AiBotUnitInfo.GetUnitSpeed(oBomber)..'; iTimeUntilReadyToFire='..iTimeUntilReadyToFire..'; oBomber[refbSpecialMicroActive]='..tostring(oBomber[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; refbLowerPriorityMicroActive='..tostring(oBomber[AiBotUnitInfo.refbLowerPriorityMicroActive] or false)) end

                            --If we have recently fired and enemy is close then hover-bomb
                            if not(oBomber[AiBotUnitInfo.refbSpecialMicroActive]) or oBomber[AiBotUnitInfo.refbLowerPriorityMicroActive] then
                                if iDistToTarget <= (oBomber[AiBotUnitInfo.refiBomberRange] or 30) + 10 and iTimeUntilReadyToFire >= 2 and oBestEnemyTarget:GetHealth() <= 250 and not(oBomber[AiBotUnitInfo.refbEasyBrain]) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Bomber recently fired and isnt able to fire again for a few seconds so will hoverbomb to attack '..oBestEnemyTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBestEnemyTarget)) end
                                    ForkThread(AiBotMicro.T1OrT3HoverBombTarget, oBomber, oBestEnemyTarget, false, (EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oBestEnemyTarget.UnitId) or oBestEnemyTarget:GetFractionComplete() < 1), false)
                                    tEnemyTargets = nil
                                    tAltEnemyTargets = nil
                                    tBomberTable = nil
                                    --If bomber is facing the wrong direction and isnt that far from the target, and is ready to fire, then consider using micro to turn around and fire at it
                                elseif iDistToTarget <= 85 and iAngleDifToTarget > 15 and (iTimeUntilReadyToFire <= 0 or (iDistToTarget <= 60 and iTimeUntilReadyToFire <= 5 and (iDistToTarget <= 40 or iTimeUntilReadyToFire <= 3))) and not(oBomber[AiBotUnitInfo.refbEasyBrain])
                                        and (iAngleDifToTarget > 30 or (iDistToTarget < (oBomber[AiBotUnitInfo.refiBomberRange] or 30) - 5 and iTimeUntilReadyToFire <= 0))
                                then
                                    --Want to turn to face the target and shoot it
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will use micro to turn where we are to fire a bomb at oBestEnemyTarget='..oBestEnemyTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBestEnemyTarget)) end
                                    local iAcceptableAngleDif = 23 --prev 30 (pre-v285) in all cases
                                    if iAngleDifToTarget <= 30 then iAcceptableAngleDif = 15 end --had scenario where bomber got intel of engineer from its own radar range, with angle dif just below 30 - too big an angle to fire its bomb
                                    --TurnAirUnitAndAttackTarget(oBomber, oTarget, bDontAdjustMicroFlag, bContinueAttackingUntilTargetDead, bContinueAttackUntilFiredBomb, iAcceptableAngleDifOverride)
                                    ForkThread(AiBotMicro.TurnAirUnitAndAttackTarget, oBomber, oBestEnemyTarget, nil,             false,                              false,                           iAcceptableAngleDif)
                                    tEnemyTargets = nil
                                    tAltEnemyTargets = nil
                                    tBomberTable = nil
                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will target oBestEnemyTarget='..oBestEnemyTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBestEnemyTarget)) end
                                    tAltEnemyTargets = {oBestEnemyTarget}
                                end
                            else
                                tAltEnemyTargets = tEnemyTargets
                            end
                        else tAltEnemyTargets = tEnemyTargets
                        end

                        if tAltEnemyTargets then
                            AssignTorpOrBomberTargets(tBomberTable, tAltEnemyTargets, iAirSubteam, false, true)
                            tEnemyTargets = {}
                            if bDebugMessages == true then LOG(sFunctionRef..': Will target the enemy with the bomber, is tBomberTable after assigning targets='..tostring(AiBotUtilities.IsTableEmpty(tBomberTable))) end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tBomberTable) == false then
                        --Find a zone for the bomber to scout to look for engineers
                        UpdateScoutingShortlist(iTeam)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering locations to scout with bomber, is table of scouting shortlist empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftLandAndWaterZoneScoutingShortlist]))) end
                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftLandAndWaterZoneScoutingShortlist]) == false then
                            local iClosestDist = 100000
                            local iClosestOnEnemySide = 100000
                            local iCurDist, tClosestMidpoint, iClosestPlateauOrZero, iClosestLZOrWZRef, iClosestEnemyPlateauOrZero, iClosestEnemyLZOrWZRef, tClosestEnemySideMidpoint, iModDist, iCurGroundAAThreat
                            for iEntry, tPlateauAndZoneRef in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftLandAndWaterZoneScoutingShortlist] do
                                --local tScoutingLZOrWZData, tScoutingLZOrWZTeamData
                                if tPlateauAndZoneRef[1] > 0 then
                                    --Waterzone - for now only want to target land zone
                                    --tScoutingLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[tPlateauAndZoneRef[2]]][AiBotMap.subrefPondWaterZones][tPlateauAndZoneRef[2]]
                                    --tScoutingLZOrWZTeamData = tScoutingLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]

                                    --Land zone
                                    local tScoutingLZData = AiBotMap.tAllPlateaus[tPlateauAndZoneRef[1]][AiBotMap.subrefPlateauLandZones][tPlateauAndZoneRef[2]]
                                    local tScoutingLZTeamData = tScoutingLZData[AiBotMap.subrefLZTeamData][iTeam]
                                    --Dont consider if has enemy AA; also require there to be at least 1 unbuilt mex
                                    if (tScoutingLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) == 0 and (tScoutingLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) == 0 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to scout the zone P'..tPlateauAndZoneRef[1]..'Z'..tPlateauAndZoneRef[2]..'; Dist to us='..AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tScoutingLZData[AiBotMap.subrefMidpoint])..'; Is table of unbuilt mexes empty='..tostring(AiBotUtilities.IsTableEmpty(tScoutingLZData[AiBotMap.subrefMexUnbuiltLocations]))..'; Mod dist%='..(tScoutingLZTeamData[AiBotMap.refiModDistancePercent] or 'nil')) end
                                        if AiBotUtilities.IsTableEmpty(tScoutingLZData[AiBotMap.subrefMexUnbuiltLocations]) == false then
                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tScoutingLZData[AiBotMap.subrefMidpoint])
                                            --Modify the distance if enemy has groundAA threat here, or lots of mexes
                                            if iCurDist <= iClosestOnEnemySide then
                                                iModDist = iCurDist
                                                --DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck, bReturnGroundAAUnitsAlongsideAAThreat, tOptionalEndMidpointAdjustForDetailedCheck, bOptionalIgnoreOppositeDirectionZones)
                                                iCurGroundAAThreat = DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, tPlateauAndZoneRef[1], tPlateauAndZoneRef[2], true,              1,                      400,                false,              iAirSubteam, true,                  true,                           oBomber:GetPosition())
                                                if iCurGroundAAThreat >= 1 then
                                                    if iCurGroundAAThreat >= 100 then iModDist = math.max(iModDist * 3, iModDist + 150)
                                                    else iModDist = math.max(iModDist * 2, iModDist + 100)
                                                    end
                                                end
                                                if table.getn(tScoutingLZData[AiBotMap.subrefMexUnbuiltLocations]) >= 2 then
                                                    if table.getn(tScoutingLZData[AiBotMap.subrefMexUnbuiltLocations]) >= 4 or table.getn(tScoutingLZData[AiBotMap.subrefMexUnbuiltLocations]) < (tScoutingLZData[AiBotMap.subrefLZOrWZMexCount] or 0) then
                                                        iModDist = iModDist * 0.75
                                                    end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': iModDist='..iModDist..'; iCurGroundAAThreat='..iCurGroundAAThreat..'; Total unbuilt locations='..table.getn(tScoutingLZData[AiBotMap.subrefMexUnbuiltLocations])..'; Mex count='.. (tScoutingLZData[AiBotMap.subrefLZOrWZMexCount] or 'nil')) end
                                                if iModDist < iClosestDist then
                                                    iClosestDist = iModDist
                                                    iClosestPlateauOrZero = tPlateauAndZoneRef[1]
                                                    iClosestLZOrWZRef = tPlateauAndZoneRef[2]
                                                    tClosestMidpoint = {tScoutingLZData[AiBotMap.subrefMidpoint][1], tScoutingLZData[AiBotMap.subrefMidpoint][2], tScoutingLZData[AiBotMap.subrefMidpoint][3]}
                                                end
                                                if iModDist < iClosestOnEnemySide and (tScoutingLZTeamData[AiBotMap.refiModDistancePercent] or 0) >= 0.5 then
                                                    iClosestOnEnemySide = iModDist
                                                    iClosestEnemyPlateauOrZero =  tPlateauAndZoneRef[1]
                                                    iClosestEnemyLZOrWZRef = tPlateauAndZoneRef[2]
                                                    tClosestEnemySideMidpoint = {tScoutingLZData[AiBotMap.subrefMidpoint][1], tScoutingLZData[AiBotMap.subrefMidpoint][2], tScoutingLZData[AiBotMap.subrefMidpoint][3]}
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Updating the closest midpoint on the enemy side of the map') end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': tClosestMidpoint to scout='..repru(tClosestMidpoint)) end
                            if tClosestEnemySideMidpoint then
                                AiBotOrders.IssueTrackedMove(oBomber, tClosestEnemySideMidpoint, 10, false, 'BScEP'..iClosestEnemyPlateauOrZero..'Z'..iClosestEnemyLZOrWZRef, false)
                                tBomberTable = nil
                            elseif tClosestMidpoint then
                                AiBotOrders.IssueTrackedMove(oBomber, tClosestMidpoint, 10, false, 'BScAP'..iClosestPlateauOrZero..'Z'..iClosestLZOrWZRef, false)
                                tBomberTable = nil
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Redundancy - will just attack move to enemy base at position '..repru(tStartLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])) end
                                --aggressive move to the closest enemy base
                                AiBotOrders.IssueTrackedAggressiveMove(oBomber, tStartLZOrWZTeamData[AiBotMap.reftClosestEnemyBase], 10, false, 'BAtBs', false)
                                tBomberTable = nil
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageBombers(iTeam, iAirSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageBombers'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local tAvailableBombers, tBombersForRefueling, tUnavailableUnits, tSpecialLogicAvailableBombers = GetAvailableLowFuelAndInUseAirUnits(iTeam, iAirSubteam, AiBotUnitInfo.refCategoryBomber - categories.EXPERIMENTAL)
    --DualGap air/eco: a refuelled strat must immediately return to work. Feed
    --each available T3 bomber an enemy mex through the normal bomber target
    --assignment path, then remove it from this cycle so generic logic cannot
    --replace the order with an idle/rally order.
    local oDualGapBrain
    for _, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
        if oBrain.AiBotDualGapRole == 'top_air' or oBrain.AiBotDualGapRole == 'bottom_air' or oBrain.AiBotDualGapRole == 'eco' then
            oDualGapBrain = oBrain
            break
        end
    end
    if oDualGapBrain and AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
        local iMapWidth = (ScenarioInfo and ScenarioInfo.size and ScenarioInfo.size[1]) or 1024
        local iMapHeight = (ScenarioInfo and ScenarioInfo.size and ScenarioInfo.size[2]) or iMapWidth
        local tEnemyMexes = oDualGapBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMex,
                {iMapWidth * 0.5, 0, iMapHeight * 0.5}, math.max(iMapWidth, iMapHeight), 'Enemy') or {}
        if AiBotUtilities.IsTableEmpty(tEnemyMexes) == false then
            for iBomber = table.getn(tAvailableBombers), 1, -1 do
                local oBomber = tAvailableBombers[iBomber]
                if AiBotUnitInfo.IsUnitValid(oBomber)
                        and EntityCategoryContains(AiBotUnitInfo.refCategoryBomber * categories.TECH3, oBomber.UnitId) then
                    local oTarget = tEnemyMexes[math.mod(iBomber - 1, table.getn(tEnemyMexes)) + 1]
                    if AiBotUnitInfo.IsUnitValid(oTarget) then
                        AssignTorpOrBomberTargets({oBomber}, {oTarget}, iAirSubteam, false, false, true)
                        LOG('AiBot Dual Gap strat relaunched: army='..oDualGapBrain:GetArmyIndex()
                                ..'; bomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)
                                ..'; target='..oTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTarget)
                                ..'; time='..GetGameTimeSeconds())
                        table.remove(tAvailableBombers, iBomber)
                    end
                end
            end
        end
    end
    local iOurBomberThreat = 0
    local tEnemyTargets = {}
    local bHaveT3Bombers = false
    local iMassThreshold = 0
    local iAAMassThreshold = 0
    local iAACategory = AiBotUnitInfo.refCategoryGroundAA + AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryMobileLandShield + AiBotUnitInfo.refCategoryShieldBoat + categories.COMMAND
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoActiveBomberTargets] = {} --Reset

    function FilterToAvailableTargets(tPotentialTargets, iOptionalCategory, bOptionalCheckNotAlreadyInEnemyTargets) --UPDATE USAGE IN SPECIAL BOMBER LOGIC IF CHANGING (and changes are relevant to engi hunter)
        if AiBotUtilities.IsTableEmpty(tPotentialTargets) == false then
            local bDontConsiderPlayableArea = not(AiBotMap.bIsCampaignMap)
            local iOriginalEnemyTargetSize
            if bOptionalCheckNotAlreadyInEnemyTargets then
                if AiBotUtilities.IsTableEmpty(tEnemyTargets) then bOptionalCheckNotAlreadyInEnemyTargets = false
                else iOriginalEnemyTargetSize = table.getn(tEnemyTargets)
                end
            end
            local bAlreadyRecorded
            iAAMassThreshold = iMassThreshold * 3

            for iUnit, oUnit in tPotentialTargets do
                if bDebugMessages == true then
                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                        LOG(sFunctionRef..': Considering whether to treat unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' as a potential target, is unit valid=true, Is unit attached='..tostring(oUnit:IsUnitState('Attached'))..'; Is unit underwater='..tostring(AiBotUnitInfo.IsUnitUnderwater(oUnit))..'; Is unit in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(oUnit:GetPosition()))..'; Is unit optional category (if is one)='..tostring(not(iOptionalCategory) or EntityCategoryContains(iOptionalCategory, oUnit.UnitId))..'; bOptionalCheckNotAlreadyInEnemyTargets='..tostring(bOptionalCheckNotAlreadyInEnemyTargets or false)..'; Is unit GroundAA='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryGroundAA, oUnit.UnitId))..'; iMassThreshold='..iMassThreshold..'; Unit mass cost='..(oUnit[AiBotUnitInfo.refiUnitMassCost] or 'nil')..'; Time='..GetGameTimeSeconds())
                    else
                        LOG(sFunctionRef..': Considering whether to treat unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' as a potential target, is unit valid=false')
                    end
                end
                if AiBotUnitInfo.IsUnitValid(oUnit) and not(oUnit:IsUnitState('Attached')) and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) and (bDontConsiderPlayableArea or AiBotConditions.IsLocationInPlayableArea(oUnit:GetPosition())) then
                    if ((oUnit[AiBotUnitInfo.refiUnitMassCost] or GetUnitMassCost(oUnit)) >= iMassThreshold or (oUnit[AiBotUnitInfo.refiUnitMassCost] >= iAAMassThreshold and EntityCategoryContains(iAACategory, oUnit.UnitId))) and (not(iOptionalCategory) or (iOptionalCategory and EntityCategoryContains(iOptionalCategory, oUnit.UnitId))) then
                        if not(bOptionalCheckNotAlreadyInEnemyTargets) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Adding unit to enemy targets') end
                            table.insert(tEnemyTargets, oUnit)
                        else
                            bAlreadyRecorded = false
                            for iRecordedUnit, oRecordedUnit in tEnemyTargets do
                                if oRecordedUnit == oUnit then
                                    bAlreadyRecorded = true
                                    break
                                elseif iRecordedUnit > iOriginalEnemyTargetSize then
                                    break
                                end
                            end
                            if not(bAlreadyRecorded) then
                                table.insert(tEnemyTargets, oUnit)
                            end
                        end
                    end
                end
            end
        end
    end

    --Consider nearby defence
    local tRallyPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
    local iRallyPlateauOrZero, iRallyLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tRallyPoint)
    local tRallyLZOrWZData
    local tRallyLZOrWZTeamData
    if iRallyPlateauOrZero == 0 then
        tRallyLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iRallyLZOrWZ]][AiBotMap.subrefPondWaterZones][iRallyLZOrWZ]
        tRallyLZOrWZTeamData = tRallyLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
    else
        tRallyLZOrWZData = AiBotMap.tAllPlateaus[iRallyPlateauOrZero][AiBotMap.subrefPlateauLandZones][iRallyLZOrWZ]
        tRallyLZOrWZTeamData = tRallyLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
    end

    --Record T3 bombers that are getting far from our air rally point and are either available or unavailable so our asfs can consider protecting them as a priority
    local oFrontBomber
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] >= 2000 then
        local iCurDistToRally
        local iFurthestFromRally = 0
        local tRally = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
        local bAlreadyRecorded
        function ConsiderFrontBomberFromTable(tT3Bombers, bAlsoConsiderAddingToTargetTable)
            if AiBotUtilities.IsTableEmpty(tT3Bombers) == false then
                for iBomber, oBomber in tT3Bombers do
                    iCurDistToRally = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tRally)
                    if iCurDistToRally > iFurthestFromRally then
                        --Want to ignore bombers we have recently built since they may be far from the rally point (assume if bomber started being built 3m+ ago then it will have been constructed for a while)
                        if iFurthestFromRally <= 60 or oBomber[AiBotUnitInfo.refiLastBombFired] or GetGameTimeSeconds() - oBomber[AiBotUnitInfo.refiTimeCreated] >= 180 or AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tRallyLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) >= 150 then
                            oFrontBomber = oBomber
                            iFurthestFromRally = iCurDistToRally
                            if AiBotUnitInfo.IsUnitValid(oFrontBomber[refoStrikeDamageAssigned]) then
                                bAlreadyRecorded = false
                                if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoActiveBomberTargets]) == false then
                                    for iRecorded, oRecorded in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoActiveBomberTargets] do
                                        if oRecorded == oFrontBomber[refoStrikeDamageAssigned] then bAlreadyRecorded = true break end
                                    end
                                end
                                if not(bAlreadyRecorded) then table.insert(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoActiveBomberTargets], oFrontBomber[refoStrikeDamageAssigned]) end
                            end
                        end
                    end
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
            local tT3Bombers = EntityCategoryFilterDown(categories.TECH3 * AiBotUnitInfo.refCategoryBomber, tAvailableBombers)
            ConsiderFrontBomberFromTable(tT3Bombers)
        end
        if AiBotUtilities.IsTableEmpty(tUnavailableUnits) == false then
            local tT3Bombers = EntityCategoryFilterDown(categories.TECH3 * AiBotUnitInfo.refCategoryBomber, tUnavailableUnits)
            ConsiderFrontBomberFromTable(tT3Bombers, true)
        end
    end
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber] = oFrontBomber
    if AiBotUnitInfo.IsUnitValid(oFrontBomber) then bHaveT3Bombers = true end

    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code, is table of available bombers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableBombers))..'; iTeam='..iTeam..'; iAirSubteam='..iAirSubteam..'; oFrontBomber (T3 bomber only)='..(oFrontBomber.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFrontBomber) or 'nil')) end
    if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
        local iStartPlateauToUse, iStartZoneToUse
        if AiBotUnitInfo.IsUnitValid(oFrontBomber) then
            local iDistFromBomberToRally = AiBotUtilities.GetDistanceBetweenPositions(oFrontBomber:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
            if bDebugMessages == true then LOG(sFunctionRef..': FrontBomber iDistFromBomberToRally='..iDistFromBomberToRally) end
            if iDistFromBomberToRally > 60 and (AiBotUnitInfo.IsUnitValid(oFrontBomber[refoStrikeDamageAssigned]) or (oFrontBomber[AiBotUnitInfo.refiLastBombFired] and GetGameTimeSeconds() - oFrontBomber[AiBotUnitInfo.refiLastBombFired] <= 30)) then
                if oFrontBomber[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] then
                    iStartPlateauToUse = 0
                    iStartZoneToUse = oFrontBomber[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam]
                elseif oFrontBomber[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam] then
                    iStartPlateauToUse = oFrontBomber[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]
                    iStartZoneToUse = oFrontBomber[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
                else
                    iStartPlateauToUse, iStartZoneToUse = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oFrontBomber:GetPosition())
                end
            end
        end
        if not(iStartPlateauToUse) or not(iStartZoneToUse) then
            iStartPlateauToUse = iRallyPlateauOrZero
            iStartZoneToUse = iRallyLZOrWZ
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Finished determining start plateau and zone to use, either based on front bomber or rally, iStartPlateauToUse='..iStartPlateauToUse..'; iStartZoneToUse='..iStartZoneToUse..'; iRallyPlateauOrZero='..iRallyPlateauOrZero..'; iRallyLZOrWZ='..iRallyLZOrWZ..'; oFrontBomber='..(oFrontBomber.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFrontBomber) or 'nil')..'; Last time bomb fired='..GetGameTimeSeconds() - (oFrontBomber[AiBotUnitInfo.refiLastBombFired] or 0)..'; Strike damage assignment='..(oFrontBomber[refoStrikeDamageAssigned].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFrontBomber[refoStrikeDamageAssigned]) or 'nil')) end
        local aiBrain
        for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
            aiBrain = oBrain
            break
        end
        local iTeam = aiBrain.AiBotTeam
        --GetAirThreatLevel(tUnits,      bEnemyUnits, bIncludeAirToAir, bIncludeGroundToAir, bIncludeAirToGround, bIncludeNonCombatAir, bIncludeAirTorpedo, bBlueprintThreat)
        iOurBomberThreat = AiBotUnitInfo.GetAirThreatLevel(tAvailableBombers, false,      false,          false,              true,                   false,              false)
        local iAvailableAndInCombatBombers = table.getn(tAvailableBombers)
        --If we have incombat bombers then increase our threat and available bombers for these
        if iAvailableAndInCombatBombers > 0 and AiBotUtilities.IsTableEmpty(tUnavailableUnits) == false then
            local tInCombatBombers = {}
            local iDistThreshold = 100
            for iBomber, oBomber in tUnavailableUnits do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering if oBomber '..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..' has recently fired or is attackign something nearby, refbSpecialMicroActive='..tostring(oBomber[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                if (oBomber[AiBotUnitInfo.refiLastBombFired] and GetGameTimeSeconds() - oBomber[AiBotUnitInfo.refiLastBombFired] <= 12)
                        or oBomber[AiBotUnitInfo.refbSpecialMicroActive]  then
                    table.insert(tInCombatBombers, oBomber)
                    if bDebugMessages == true then LOG(sFunctionRef..': Have recently fired a bomb or have special micro active') end
                else
                    local tLastOrder = oBomber[AiBotOrders.reftiLastOrders][1]
                    if (tLastOrder[AiBotOrders.subrefoOrderUnitTarget].UnitId and not(tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderRefuel) and ((not(tLastOrder[AiBotOrders.subrefoOrderUnitTarget].Dead) and AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tLastOrder[AiBotOrders.subrefoOrderUnitTarget]:GetPosition()) <= iDistThreshold) or (tLastOrder[AiBotOrders.subrefoOrderUnitTarget].Dead and tLastOrder[AiBotOrders.subrefoOrderUnitTarget][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam] and AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tLastOrder[AiBotOrders.subrefoOrderUnitTarget][AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) <= iDistThreshold)))
                            or ((tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAggressiveMove or tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueGroundAttack) and tLastOrder[AiBotOrders.subreftOrderPosition] and AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tLastOrder[AiBotOrders.subreftOrderPosition]) <= iDistThreshold) then
                        table.insert(tInCombatBombers, oBomber)
                        if bDebugMessages == true then LOG(sFunctionRef..': Are attacking a target that is close to it') end
                    end
                end
                if AiBotUtilities.IsTableEmpty(tInCombatBombers) == false then
                    if bDebugMessages == true then LOG(sFunctionRef..': iAvailableAndInCombatBombers before adding in combat='..iAvailableAndInCombatBombers..'; size of tInCombatBombers='..table.getn(tInCombatBombers)..'; iOurBomberThreat before in combat='..iOurBomberThreat..'; threat of in combat='..AiBotUnitInfo.GetAirThreatLevel(tInCombatBombers, false,      false,          false,              true,                   false,              false)) end
                    iAvailableAndInCombatBombers = iAvailableAndInCombatBombers + table.getn(tInCombatBombers)
                    iOurBomberThreat = iOurBomberThreat + AiBotUnitInfo.GetAirThreatLevel(tInCombatBombers, false,      false,          false,              true,                   false,              false)
                end
            end
        end

        local iSearchSize = 300
        if AiBotMap.iMapSize > 512 then
            if AiBotUtilities.bQuietModActive then
                iSearchSize = 365 --Az preference
            else
                iSearchSize = 450
            end
        end

        if iAvailableAndInCombatBombers >= 8 then iSearchSize = iSearchSize * 1.5 end
        if AiBotMap.bIsCampaignMap then
            iSearchSize = math.max(AiBotMap.iMapSize, iSearchSize * 1.5)
        end
        if iAvailableAndInCombatBombers >= 20 and (iAvailableAndInCombatBombers >= 50 or (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] and (AiBotMap.bIsCampaignMap or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] < 3))) then
            iSearchSize = iSearchSize * 2
        elseif AiBotMap.bIsCampaignMap and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then iSearchSize = iSearchSize * 1.5
        end
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiBomberLosses] > 0 then
            iSearchSize = iSearchSize * math.min(2, math.max(0.5, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiT1ToT3BomberKills] / AiBotTeam.tTeamData[iTeam][AiBotTeam.refiBomberLosses]))
        end

        --Consider snipe targets
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of active snipe targets empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]))..'; Is table of bomber snipe targets empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets]))..'; iSearchSize='..iSearchSize) end
        local tEnemySnipeTargets
        if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]) then
            tEnemySnipeTargets = {}
            for iSnipeTarget, oSnipeTarget in AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets] do
                table.insert(tEnemySnipeTargets, oSnipeTarget)
            end
        end
        if not(tEnemySnipeTargets) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets]) == false then
            for iSnipeTarget, oSnipeTarget in AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets] do
                if AiBotUnitInfo.IsUnitValid(oSnipeTarget) then
                    if not(tEnemySnipeTargets) then tEnemySnipeTargets = {} end
                    table.insert(tEnemySnipeTargets, oSnipeTarget)
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': is tEnemySnipeTargets nil='..tostring(tEnemySnipeTargets == nil)) end
        if tEnemySnipeTargets then
            --Get closest snipe target to our air rally point
            local iClosestSnipeTarget = 100000
            local iCurDist
            local oClosestSnipeTarget
            for iSnipeTarget, oSnipeTarget in tEnemySnipeTargets do
                if (oSnipeTarget[AiBotUnitInfo.refiRecentBomberSnipeAttempts] or 0) == 0 then
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oSnipeTarget:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
                    if iCurDist < iClosestSnipeTarget then
                        oClosestSnipeTarget = oSnipeTarget
                        iClosestSnipeTarget = iCurDist
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': oClosestSnipeTarget='..(oClosestSnipeTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestSnipeTarget) or 'nil')) end
            if oClosestSnipeTarget then
                ForkThread(PlanBomberSnipe, tAvailableBombers,  oClosestSnipeTarget, iTeam)
                tAvailableBombers = nil
            end
        end
        if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
            local iHighestTechLevel = 1
            local iCurTechLevel
            for iUnit, oUnit in tAvailableBombers do
                iCurTechLevel = AiBotUnitInfo.GetUnitTechLevel(oUnit)
                if iCurTechLevel > iHighestTechLevel then
                    iHighestTechLevel = iCurTechLevel
                    if iHighestTechLevel >= 3 then break end
                end
            end
            if iHighestTechLevel >= 3 then
                iMassThreshold = 160
            elseif iHighestTechLevel == 2 then
                iMassThreshold = 43 --i.e. ignore LABs and scouts
            end
            --Consider nearby defence
            local iAAPriorityThresholdFactor = 1.5 --e.g. for rally zones - decrease this if mod dist is high

            if AiBotMap.iMapSize <= 256 then
                iAAPriorityThresholdFactor = 1
            elseif AiBotMap.iMapSize <=512 then
                if tRallyLZOrWZTeamData[AiBotMap.refiModDistancePercent] > 0.05 then
                    if tRallyLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.25 then
                        iAAPriorityThresholdFactor = 1
                    else
                        iAAPriorityThresholdFactor = 1.25
                    end
                end
            elseif tRallyLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.2 then
                if tRallyLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.35 then
                    iAAPriorityThresholdFactor = 1
                else
                    iAAPriorityThresholdFactor = 1.25
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iAAPriorityThresholdFactor for zones adjacent to rally or high priority enemy targets='..iAAPriorityThresholdFactor..'; Is table of enemies in rally zone empty='..tostring(AiBotUtilities.IsTableEmpty(tRallyLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]))..'; Have air control='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl])) end
            FilterToAvailableTargets(tRallyLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])
            if AiBotUtilities.IsTableEmpty( tEnemyTargets) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': Attacking enemy units in the rally zone') end
                AssignTorpOrBomberTargets(tAvailableBombers, tEnemyTargets, iAirSubteam, false, true)
                tEnemyTargets = {}
            end
            if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
                local bCheckForObjectiveTargets = false
                if AiBotMap.bIsCampaignMap and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                    bCheckForObjectiveTargets = true
                end
                local toObjectiveTargets = {}
                function AddObjectiveTargetsFromLZTeamData(tLZTeamData)
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of ground fire friendly targets empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoGroundFireFriendlyTarget]))) end
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoGroundFireFriendlyTarget]) == false then
                        if AiBotConditions.IsTableOfUnitsStillValid(tLZTeamData[AiBotMap.reftoGroundFireFriendlyTarget], false) then
                            for iUnit, oUnit in tLZTeamData[AiBotMap.reftoGroundFireFriendlyTarget] do
                                table.insert(toObjectiveTargets, oUnit)
                            end
                        end
                    end
                end
                --Consider adjacent zones if are on a land zone, and the rally point is closer to our base than the enemy
                local tbZonesConsideredByPlateau = {}
                tbZonesConsideredByPlateau[iRallyPlateauOrZero] = {}
                local iMaxEnemyGroundAAThreat
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap] then
                    iMaxEnemyGroundAAThreat = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] * 0.2
                    if bDebugMessages == true then LOG(sFunctionRef..': Base GroundAA threat - are near unit cap so increasing to 20% of our bomber threat, iMaxEnemyGroundAAThreat='..iMaxEnemyGroundAAThreat) end
                else
                    iMaxEnemyGroundAAThreat = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] * 0.15
                    if bDebugMessages == true then LOG(sFunctionRef..': Base GroundAA threat - iMaxEnemyGroundAAThreat='..iMaxEnemyGroundAAThreat) end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': About to adjust bomber GroundAA threat for kills and losses, bomber losses='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiBomberLosses] or 0)..'; Bomber kills='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiT1ToT3BomberKills] or 0)) end
                if (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiBomberLosses] or 0) == 0 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiT1ToT3BomberKills] or 0) >= 1000 then
                    iMaxEnemyGroundAAThreat = iMaxEnemyGroundAAThreat * 1.2
                    if bDebugMessages == true then LOG(sFunctionRef..': No losses and lots of kills, will increase threshold, iMaxEnemyGroundAAThreat='..iMaxEnemyGroundAAThreat) end
                elseif (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiBomberLosses] or 0) == 0 then
                    --No change
                    if bDebugMessages == true then LOG(sFunctionRef..': No losses so no change, iMaxEnemyGroundAAThreat='..iMaxEnemyGroundAAThreat) end

                elseif (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiT1ToT3BomberKills] or 0) > (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiBomberLosses] or 0) then
                    iMaxEnemyGroundAAThreat = iMaxEnemyGroundAAThreat * math.min(1.2, (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiT1ToT3BomberKills] / (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiBomberLosses] or 0) - 1)*0.35 + 1)
                    if bDebugMessages == true then LOG(sFunctionRef..': Killed more than we have lossed to increasing threshold, iMaxEnemyGroundAAThreat='..iMaxEnemyGroundAAThreat) end
                else
                    iMaxEnemyGroundAAThreat = iMaxEnemyGroundAAThreat * math.max(0.25, (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiT1ToT3BomberKills] or 0) /  (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiBomberLosses] or 0))
                    if bDebugMessages == true then LOG(sFunctionRef..': Not killed more than we have lost so reducing AA threshold based on % of kills to losses='.. (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiT1ToT3BomberKills] or 0) /  (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiBomberLosses] or 0)..'; iMaxEnemyGroundAAThreat='..iMaxEnemyGroundAAThreat) end
                end
                --If have strat bombers then have a higher minimum ground AA threshold
                if bHaveT3Bombers then
                    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                        iMaxEnemyGroundAAThreat = math.max(1200, iMaxEnemyGroundAAThreat + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] * 0.1) --T2 flak is 160, T3 MAA is 600
                    else
                        iMaxEnemyGroundAAThreat = math.max(1000, iMaxEnemyGroundAAThreat + AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurT1ToT3BomberThreat] * 0.07) --T2 flak is 160, T3 MAA is 600
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': We have t3 bombers so increasing iMaxEnemyGroundAAThreat by 7-10% based onif have air control, iMaxEnemyGroundAAThreat='..iMaxEnemyGroundAAThreat) end
                end
                --If have large number of available bombers then increase
                if iAvailableAndInCombatBombers >= 20 then
                    iMaxEnemyGroundAAThreat = iMaxEnemyGroundAAThreat * (1.1 + math.min(0.6, 0.4 * iAvailableAndInCombatBombers / 50))
                    if bDebugMessages == true then LOG(sFunctionRef..': Lots of available bombers so increasing threat further, iAvailableAndInCombatBombers='..iAvailableAndInCombatBombers..'; iMaxEnemyGroundAAThreat post increase='..iMaxEnemyGroundAAThreat) end
                end

                local bConsiderHigherTechUnitsFirst = false
                if (iOurBomberThreat >= 2000 or (not(AiBotUtilities.bQuietModActive) and iOurBomberThreat >= 1500)) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 3 and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.TECH3 + categories.EXPERIMENTAL, tAvailableBombers)) == false then
                    bConsiderHigherTechUnitsFirst = true
                end

                if bDebugMessages == true then LOG(sFunctionRef..': bConsiderHigherTechUnitsFirst='..tostring(bConsiderHigherTechUnitsFirst or false)..'; bHaveT3Bombers='..tostring(bHaveT3Bombers)..'; iMaxEnemyGroundAAThreat='..iMaxEnemyGroundAAThreat) end
                local tbZoneByPlateauHasTooMuchAA = {}
                if bConsiderHigherTechUnitsFirst then
                    --Consider higher priority relatively nearby targets:
                    local iHighPriorityCategories = AiBotUnitInfo.refCategoryMobileLand * (categories.TECH3 + categories.EXPERIMENTAL) + AiBotUnitInfo.refCategoryStructure * (categories.TECH3 + categories.TECH2) + AiBotUnitInfo.refCategoryNavalSurface - categories.TECH1

                    FilterToAvailableTargets(aiBrain:GetUnitsAroundPoint(iHighPriorityCategories, tRallyPoint, math.max(100, math.min(AiBotMap.iMapSize * 0.3, 200)), 'Enemy'))
                    if AiBotUtilities.IsTableEmpty(tEnemyTargets) == false then
                        local iCurPlateauOrZero, iCurZone
                        local toPriorityEnemiesToTarget = {}
                        for iUnit, oUnit in tEnemyTargets do
                            iCurPlateauOrZero, iCurZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                            if iCurPlateauOrZero and iCurZone then
                                if tbZoneByPlateauHasTooMuchAA[iCurPlateauOrZero][iCurZone] == nil then
                                    if tbZoneByPlateauHasTooMuchAA[iCurPlateauOrZero] == nil then tbZoneByPlateauHasTooMuchAA[iCurPlateauOrZero] = {} end
                                    --DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck, bReturnGroundAAUnitsAlongsideAAThreat, tOptionalEndMidpointAdjustForDetailedCheck, bOptionalIgnoreOppositeDirectionZones, bIncludeEnemyGroundAAInAirAAThreat, bAssumeWontTargetInterimAAForDetailedCheck)
                                    tbZoneByPlateauHasTooMuchAA[iCurPlateauOrZero][iCurZone] = DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauToUse, iStartZoneToUse, iCurPlateauOrZero, iCurZone, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl], iMaxEnemyGroundAAThreat * iAAPriorityThresholdFactor, nil, false, iAirSubteam, true, false, nil, false)
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering priority enemy target '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' in P'..iCurPlateauOrZero..'Z'..iCurZone..'; Too much AA in this zone='..tostring(tbZoneByPlateauHasTooMuchAA[iCurPlateauOrZero][iCurZone])..'; iMaxEnemyGroundAAThreat='..iMaxEnemyGroundAAThreat..'; iAAPriorityThresholdFactor='..iAAPriorityThresholdFactor) end
                                if not(tbZoneByPlateauHasTooMuchAA[iCurPlateauOrZero][iCurZone]) then
                                    table.insert(toPriorityEnemiesToTarget, oUnit)
                                end
                            end
                        end
                        if AiBotUtilities.IsTableEmpty(toPriorityEnemiesToTarget) == false then
                            AssignTorpOrBomberTargets(tAvailableBombers, toPriorityEnemiesToTarget, iAirSubteam, false, true)
                        end
                    end
                    tEnemyTargets = {} --reset targets
                end
                if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering enemies around rally, iRallyPlateauOrZero='..(iRallyPlateauOrZero or 'nil')) end
                    if iRallyPlateauOrZero > 0 then --if water zone then wont prioritise enemies around rally area
                        if (tRallyLZOrWZData[AiBotMap.refiModDistancePercent] or 0) <= 0.4 then
                            if AiBotUtilities.IsTableEmpty(tRallyLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                for _, iAdjLZ in tRallyLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                                    tbZonesConsideredByPlateau[iRallyPlateauOrZero][iAdjLZ] = true
                                    local tAdjLZTeamData
                                    if not(tbZoneByPlateauHasTooMuchAA[iRallyPlateauOrZero][iAdjLZ]) then
                                        tAdjLZTeamData = AiBotMap.tAllPlateaus[iRallyPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                        FilterToAvailableTargets(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                                        if AiBotUtilities.IsTableEmpty( tEnemyTargets) == false then
                                            if tbZoneByPlateauHasTooMuchAA[iRallyPlateauOrZero][iAdjLZ] == nil then
                                                if tbZoneByPlateauHasTooMuchAA[iRallyPlateauOrZero] == nil then tbZoneByPlateauHasTooMuchAA[iRallyPlateauOrZero] = {} end
                                                tbZoneByPlateauHasTooMuchAA[iRallyPlateauOrZero][iAdjLZ] = DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauToUse, iStartZoneToUse, iRallyPlateauOrZero, iAdjLZ, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl], iMaxEnemyGroundAAThreat * iAAPriorityThresholdFactor, nil, false, iAirSubteam, true, false, nil, false)
                                            end
                                            if not(tbZoneByPlateauHasTooMuchAA[iRallyPlateauOrZero][iAdjLZ]) then
                                                AssignTorpOrBomberTargets(tAvailableBombers, tEnemyTargets, iAirSubteam, false, true)
                                            end
                                            tEnemyTargets = {}
                                            if AiBotUtilities.IsTableEmpty(tAvailableBombers) then break end
                                        end
                                    end
                                    if bCheckForObjectiveTargets then
                                        if not(tAdjLZTeamData) then tAdjLZTeamData = AiBotMap.tAllPlateaus[iRallyPlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam] end
                                        AddObjectiveTargetsFromLZTeamData(tAdjLZTeamData)
                                    end
                                end
                            end

                            --Consider adjacent water zones
                            if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
                                if AiBotUtilities.IsTableEmpty(tRallyLZOrWZData[AiBotMap.subrefAdjacentWaterZones]) == false then

                                    for iEntry, tSubtable in tRallyLZOrWZData[AiBotMap.subrefAdjacentWaterZones] do
                                        local iAdjWZ = tSubtable[AiBotMap.subrefAWZRef]
                                        if not(tbZoneByPlateauHasTooMuchAA[iRallyPlateauOrZero][iAdjWZ]) then
                                            local tAdjWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iAdjWZ]][AiBotMap.subrefPondWaterZones][iAdjWZ][AiBotMap.subrefWZTeamData][iTeam]
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjWZ='..iAdjWZ..'; is table of enemy units empty for this zone='..tostring(AiBotUtilities.IsTableEmpty(tAdjWZTeamData[AiBotMap.subrefTEnemyUnits]))) end
                                            FilterToAvailableTargets(tAdjWZTeamData[AiBotMap.subrefTEnemyUnits])
                                            if AiBotUtilities.IsTableEmpty( tEnemyTargets) == false then
                                                if tbZoneByPlateauHasTooMuchAA[iRallyPlateauOrZero][iRallyLZOrWZ] == nil then
                                                    if tbZoneByPlateauHasTooMuchAA[iRallyPlateauOrZero] == nil then tbZoneByPlateauHasTooMuchAA[iRallyPlateauOrZero] = {} end
                                                    tbZoneByPlateauHasTooMuchAA[iRallyPlateauOrZero][iRallyLZOrWZ] = DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauToUse, iStartZoneToUse, 0, iAdjWZ, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl], iMaxEnemyGroundAAThreat * iAAPriorityThresholdFactor, nil, false, iAirSubteam, true, false, nil, false)
                                                end

                                                if not(tbZoneByPlateauHasTooMuchAA[iRallyPlateauOrZero][iAdjWZ]) then
                                                    AssignTorpOrBomberTargets(tAvailableBombers, tEnemyTargets, iAirSubteam, false, true)
                                                end
                                                tEnemyTargets = {}
                                                if AiBotUtilities.IsTableEmpty(tAvailableBombers) then break end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
                        --If have air control and lots of bombers available consider further away targets; also consider if rally point is outside the playable area
                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of available bombers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableBombers))..'; Do we have air control='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl])..'; iAvailableAndInCombatBombers='..(iAvailableAndInCombatBombers or 'nil')..'; iOurBomberThreat='..(iOurBomberThreat or 'nil')..'; iMaxEnemyGroundAAThreat before adjusting if dont have lots of bombers='..iMaxEnemyGroundAAThreat..'; iSearchSize='..iSearchSize..'; Time='..GetGameTimeSeconds()) end
                        if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbOrigRallyOutsidePlayableArea] or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDontHaveBuildingsOrACUInPlayableArea] or (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] and iAvailableAndInCombatBombers >= 8 and (iAvailableAndInCombatBombers >= 60 or iOurBomberThreat >= 25000 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] < 3 or (AiBotMap.bIsCampaignMap and iAvailableAndInCombatBombers >= 12 and (iAvailableAndInCombatBombers >= 12 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeLastNearUnitCap])))) then
                            if bDebugMessages == true then LOG(sFunctionRef..': We have lots of available bombers and air control, or want to be suicidal due to campaign map') end
                        else
                            iMaxEnemyGroundAAThreat = iMaxEnemyGroundAAThreat / 1.5
                            if bDebugMessages == true then LOG(sFunctionRef..': We dont have lots of available bombers so be more cautious about searching for far away targets') end
                        end
                        --Check for approaching enemy air threat if we lack air control
                        local bAbortDueToAirAAThreat = false
                        if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then
                            --Check both rally point and front bomber approaching asf threats
                            local iBomberPlateauOrZero, iBomberLandOrWaterZone
                            local tFrontBomberPosition
                            if AiBotUnitInfo.IsUnitValid(oFrontBomber) then
                                iBomberPlateauOrZero, iBomberLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oFrontBomber:GetPosition())
                                tFrontBomberPosition = oFrontBomber:GetPosition()
                            end
                            if not(tFrontBomberPosition) then
                                iBomberPlateauOrZero = iRallyPlateauOrZero
                                iBomberLandOrWaterZone = iRallyLZOrWZ
                                tFrontBomberPosition = {AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][1], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][2], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint][3]}
                            end
                            local iMaxEnemyAirAA
                            if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then
                                iMaxEnemyAirAA = math.min(200, iOurBomberThreat * 0.05)
                            else
                                iMaxEnemyAirAA = math.min(600, iOurBomberThreat * 0.05)
                            end
                            if IsThereAANearLandOrWaterZone(iTeam, iBomberPlateauOrZero, iBomberLandOrWaterZone, (iBomberPlateauOrZero == 0), -1, iMaxEnemyAirAA) or IsThereNearbyAirAA(iTeam, iBomberPlateauOrZero, iBomberLandOrWaterZone, (iBomberPlateauOrZero == 0), 200, iMaxEnemyAirAA, tFrontBomberPosition) then
                                bAbortDueToAirAAThreat = true
                                --Exception if have t3 bombers and nearest airaa unit is further away than target of fromt bomber who has fired recently or is close to that target
                                if bHaveT3Bombers and AiBotUnitInfo.IsUnitValid(oFrontBomber) and ((AiBotUnitInfo.IsUnitValid(oFrontBomber[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]) and AiBotUtilities.GetDistanceBetweenPositions(oFrontBomber:GetPosition(), oFrontBomber[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]:GetPosition()) <= 120) or (oFrontBomber[AiBotUnitInfo.refiLastBombFired] and GetGameTimeSeconds() - oFrontBomber[AiBotUnitInfo.refiLastBombFired]) <= 6) then
                                    --First check if enemy airaa in same zone as fromt bomber
                                    local tFrontBomberLZOrWZData, tFrontBomberLZOrWZTeamData
                                    if iBomberPlateauOrZero == 0 then
                                        tFrontBomberLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iBomberLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iBomberLandOrWaterZone]
                                        tFrontBomberLZOrWZTeamData = tFrontBomberLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                    else
                                        tFrontBomberLZOrWZData = AiBotMap.tAllPlateaus[iBomberPlateauOrZero][AiBotMap.subrefPlateauLandZones][iBomberLandOrWaterZone]
                                        tFrontBomberLZOrWZTeamData = tFrontBomberLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if can ignore airaa threat around front bomber, iBomberPlateauOrZero='..(iBomberPlateauOrZero or 'nil')..'; iBomberLandOrWaterZone='..(iBomberLandOrWaterZone or 'nil')) end
                                    if (tFrontBomberLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) == 0 then
                                        local oNearestBomberWithAttackOrder
                                        local iCurDist
                                        local iClosestDistToFrontBomber = 60 --Only consider bombers close to the front bomber
                                        if AiBotUnitInfo.IsUnitValid(oFrontBomber[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]) then
                                            oNearestBomberWithAttackOrder = oFrontBomber
                                        else
                                            if not(oFrontBomber.GetPosition) then AiBotUtilities.ErrorHandler('Front bomber is valid but doesnt have get poition')
                                            else
                                                for iBomber, oBomber in tAvailableBombers do
                                                    if EntityCategoryContains(categories.TECH3, oBomber.UnitId) then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Checking dist between oBomber='..(oBomber.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oBomber) or 'nil')..' and oFrontBomber='..(oFrontBomber.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFrontBomber) or 'nil')) end
                                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), oFrontBomber:GetPosition())
                                                        if iCurDist < iClosestDistToFrontBomber then
                                                            if AiBotUnitInfo.IsUnitValid(oBomber[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]) then
                                                                iClosestDistToFrontBomber = iCurDist
                                                                oNearestBomberWithAttackOrder = oBomber
                                                            end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                        if oNearestBomberWithAttackOrder then
                                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirAA]) then
                                                bAbortDueToAirAAThreat = false
                                                if bDebugMessages == true then LOG(sFunctionRef..': No AirAA units so will ignore airaa afterall') end
                                            else
                                                iClosestDistToFrontBomber = 10000
                                                local oClosestAirAA
                                                for iAirAA, oAirAA in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirAA] do
                                                    if not(oAirAA.Dead) then
                                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oFrontBomber:GetPosition(), oAirAA:GetPosition())
                                                        if iCurDist <  iClosestDistToFrontBomber then
                                                            if oAirAA:GetFractionComplete() == 1 and not(oAirAA:IsUnitState('Attached')) then
                                                                iClosestDistToFrontBomber = iCurDist
                                                                oClosestAirAA = oAirAA
                                                            end
                                                        end
                                                    end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': oClosestAirAA='..(oClosestAirAA.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestAirAA) or 'nil')) end
                                                if oClosestAirAA then
                                                    if iClosestDistToFrontBomber < 100 then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy AirAA unit is too close to bomber so will abort due to airaa threat still') end
                                                    elseif AiBotUnitInfo.GetUnitSpeed(oClosestAirAA) <= 1 then
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy AirAA unit is stationery or almost stationery so will ignore for now') end
                                                        bAbortDueToAirAAThreat = false
                                                    else
                                                        local tBomberTarget = oNearestBomberWithAttackOrder[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget]:GetPosition()
                                                        local iAirAADistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oClosestAirAA:GetPosition(), tBomberTarget)

                                                        if  iAirAADistToTarget <= 50 then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': AirAA is close to target so will still avoid AirAA') end
                                                        else
                                                            local iAirAAFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oClosestAirAA)
                                                            local iAirAAAngleToTarget = AiBotUtilities.GetAngleFromAToB(oClosestAirAA:GetPosition(), tBomberTarget)
                                                            if AiBotUtilities.GetAngleDifference(iAirAAFacingAngle, iAirAAAngleToTarget) <= 45 then
                                                                if bDebugMessages == true then LOG(sFunctionRef..': AirAA is heading towards target so still avoid airaa') end
                                                            else
                                                                local iAirAAAngleToBomber = AiBotUtilities.GetAngleFromAToB(oClosestAirAA:GetPosition(), oNearestBomberWithAttackOrder:GetPosition())
                                                                if AiBotUtilities.GetAngleDifference(iAirAAFacingAngle, iAirAAAngleToBomber) <= 45 then
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': AirAA is heading towards bomber so still avoid airaa') end
                                                                else
                                                                    --Check airaa isn't between us and the target
                                                                    local iBomberDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oNearestBomberWithAttackOrder:GetPosition(), tBomberTarget)
                                                                    local iAirAADistToBomber = AiBotUtilities.GetDistanceBetweenPositions(oNearestBomberWithAttackOrder:GetPosition(), oClosestAirAA:GetPosition())
                                                                    local iBomberAngleToTarget = AiBotUtilities.GetAngleFromAToB(oNearestBomberWithAttackOrder:GetPosition(), tBomberTarget)
                                                                    local iBomberAngleToAsf = iAirAAAngleToBomber - 180
                                                                    if iBomberAngleToAsf < 0 then iBomberAngleToAsf = iBomberAngleToAsf + 360 end

                                                                    if AiBotUtilities.IsLineFromAToBInRangeOfCircleAtC(iBomberDistToTarget, iAirAADistToBomber, iAirAADistToTarget, iBomberAngleToTarget, iBomberAngleToAsf, 50) then
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Bomber will get too close to the airaa if it carries on towards target, so will continue to avoid airaa') end
                                                                    else
                                                                        bAbortDueToAirAAThreat = false
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy not responding with airaa yet, and we think we can get away with dropping bomb on target, so wont run from airaa just yet') end
                                                                    end
                                                                end
                                                            end
                                                        end
                                                    end
                                                else
                                                    bAbortDueToAirAAThreat = false
                                                    if bDebugMessages == true then LOG(sFunctionRef..': No oClosestAirAA unit so will ignore airaa afterall') end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of pathing to other zones empty='..tostring(AiBotUtilities.IsTableEmpty(tRallyLZOrWZData[AiBotMap.subrefLZPathingToOtherLandZones]))..'; bAbortDueToAirAAThreat='..tostring(bAbortDueToAirAAThreat or false)) end
                        if AiBotUtilities.IsTableEmpty(tRallyLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false and not(bAbortDueToAirAAThreat) then
                            local bDontCheckForPacifism = not(AiBotOverseer.bPacifistModeActive)
                            local iCurGroundAAThreat
                            local iMaxModDist --In addition to searchsize which limits by distance, will also avoid attacking enemy base if we lack air control
                            if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                                if iOurBomberThreat <= 3000 and not(bHaveT3Bombers) and not(AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontT3Bomber])) then
                                    iMaxModDist = 0.75 --Dont want to be too aggressive early on with bombers even if we have air control
                                else
                                    iMaxModDist = 10 --Can go over 1 mod dist for zones behind enemy base, so doing 10 to be safe
                                end
                            elseif AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then
                                if AiBotMap.iMapSize >= 1000 then
                                    iMaxModDist = 0.3
                                elseif AiBotMap.iMapSize <= 256 then
                                    iMaxModDist = 0.55
                                else
                                    iMaxModDist = 0.4
                                end
                            else
                                if AiBotMap.iMapSize >= 1000 then iMaxModDist = 0.45
                                elseif AiBotMap.iMapSize <= 256 then iMaxModDist = 0.7
                                else iMaxModDist = 0.55
                                end
                            end
                            local iZoneDistFromFrontBomberToIgnoreModDist
                            if bHaveT3Bombers then
                                if AiBotMap.iMapSize > 512 then
                                    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                                        iZoneDistFromFrontBomberToIgnoreModDist = 250
                                    elseif not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]) then
                                        iZoneDistFromFrontBomberToIgnoreModDist = 180
                                    else iZoneDistFromFrontBomberToIgnoreModDist = 140
                                    end
                                elseif AiBotMap.iMapSize > 256 then
                                    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                                        iZoneDistFromFrontBomberToIgnoreModDist = 200
                                    elseif not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]) then
                                        iZoneDistFromFrontBomberToIgnoreModDist = 150
                                    else iZoneDistFromFrontBomberToIgnoreModDist = 120
                                    end
                                else
                                    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                                        iZoneDistFromFrontBomberToIgnoreModDist = 160
                                    elseif not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]) then
                                        iZoneDistFromFrontBomberToIgnoreModDist = 120
                                    else iZoneDistFromFrontBomberToIgnoreModDist = 100
                                    end
                                end
                            end

                            if bDebugMessages == true then LOG(sFunctionRef..': About to cycle through other zones by distance, iMaxModDist='..iMaxModDist) end
                            for iEntry, tPathingDetails in tRallyLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                                local iOtherPlateauOrZero = tPathingDetails[AiBotMap.subrefiPlateauOrPond]
                                local iOtherLZOrWZ = tPathingDetails[AiBotMap.subrefiLandOrWaterZoneRef]
                                if tPathingDetails[AiBotMap.subrefbIsWaterZone] then iOtherPlateauOrZero = 0 end
                                local iCurGroundAAThreatAlongPath = 0
                                local tAAUnitsAlongPath
                                local bProceedWithAttack
                                if not(tbZonesConsideredByPlateau[iRallyPlateauOrZero][iOtherLZOrWZ]) and iOtherLZOrWZ and not(tbZoneByPlateauHasTooMuchAA[iOtherPlateauOrZero][iOtherLZOrWZ]) then
                                    local tOtherLZOrWZData
                                    local tOtherLZOrWZTeamData
                                    if iOtherPlateauOrZero == 0 then
                                        tOtherLZOrWZData = AiBotMap.tPondDetails[tPathingDetails[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][iOtherLZOrWZ]
                                        tOtherLZOrWZTeamData = tOtherLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                        iCurGroundAAThreat = (tOtherLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)
                                    else
                                        tOtherLZOrWZData = AiBotMap.tAllPlateaus[iOtherPlateauOrZero][AiBotMap.subrefPlateauLandZones][iOtherLZOrWZ]
                                        tOtherLZOrWZTeamData = tOtherLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                        iCurGroundAAThreat = (tOtherLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)
                                    end
                                    if (tOtherLZOrWZData[AiBotMap.subrefLZTravelDist] or 0) > iSearchSize and ((tOtherLZOrWZTeamData[AiBotMap.subrefLZSValue] or 0) == 0 or (tOtherLZOrWZData[AiBotMap.subrefLZTravelDist] or 0) > iSearchSize + 25) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Stopping loop as P'..iOtherPlateauOrZero..'Z'..iOtherLZOrWZ..';  is outside search size') end
                                        break
                                    elseif tOtherLZOrWZTeamData[AiBotMap.refiModDistancePercent] > iMaxModDist then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Mod dist of P'..iOtherPlateauOrZero..'Z'..iOtherLZOrWZ..' is too high so wont consider this zone') end
                                    end
                                    if bDontCheckForPacifism or not(AiBotConditions.AdjacentToPacifistZone(iOtherPlateauOrZero, iOtherLZOrWZ)) then
                                        --If enemy GroundAA threat is too big then stop looking/dont consider targets that are more than a bit further from here iSearchSize

                                        if bDebugMessages == true then LOG(sFunctionRef..': Dealing with P'..iOtherPlateauOrZero..'Z'..iOtherLZOrWZ..'; iCurGroundAAThreat='..iCurGroundAAThreat..'; Enemy shield='..(tOtherLZOrWZData[AiBotMap.subrefThreatEnemyShield] or 0)..'; iMaxEnemyGroundAAThreat='..iMaxEnemyGroundAAThreat..'; SValue='..(tOtherLZOrWZTeamData[AiBotMap.subrefLZSValue] or 0)..'; Mod dist='..tOtherLZOrWZTeamData[AiBotMap.refiModDistancePercent]..'; iMaxModDist='..iMaxModDist..'; Target zone radar coverage='..(tOtherLZOrWZTeamData[AiBotMap.refiRadarCoverage] or 'nil')) end
                                        if iCurGroundAAThreat + math.min(iCurGroundAAThreat * 3, (tOtherLZOrWZData[AiBotMap.subrefThreatEnemyShield] or 0)) > iMaxEnemyGroundAAThreat and (tOtherLZOrWZTeamData[AiBotMap.subrefLZSValue] or 0) == 0 then
                                            iSearchSize = math.min(iSearchSize, (tOtherLZOrWZData[AiBotMap.subrefLZTravelDist] or 0) + 25) --i.e. consider a couple more zones in case htey are in another direction
                                            if bDebugMessages == true then LOG(sFunctionRef..': Zone has too much AA threat so wont target and will stop searching soon') end
                                            --If mod dist relatively high then only consider if we have intel coverage
                                        elseif (tOtherLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= iMaxModDist or (iZoneDistFromFrontBomberToIgnoreModDist and oFrontBomber and AiBotUtilities.GetDistanceBetweenPositions(oFrontBomber:GetPosition(), tOtherLZOrWZData[AiBotMap.subrefMidpoint]) <= iZoneDistFromFrontBomberToIgnoreModDist)) and (tOtherLZOrWZTeamData[AiBotMap.refiModDistancePercent] < 0.45 or tOtherLZOrWZTeamData[AiBotMap.refiRadarCoverage] >= 50 or GetGameTimeSeconds() - (tOtherLZOrWZTeamData[AiBotMap.refiTimeLastHadVisual] or 0) <= 120) then
                                            --Update mass thresholds based on mod dist if we have T3 bombers (default earlier is 160 mass for t3)
                                            if iHighestTechLevel >= 3 then
                                                if tOtherLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.25 then iMassThreshold = 160
                                                elseif tOtherLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.5 then iMassThreshold = math.min(800, 160 * math.max(1, tPathingDetails[AiBotMap.subrefiDistance] / 100))
                                                else iMassThreshold = 800 --e.g. T3 MAA is 600, stationery flak is 400 - dont want to ignore; we will treat MAA as being worth 4 times the normal value though to reduce risk we ignore
                                                end
                                            end
                                            FilterToAvailableTargets(tOtherLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iOtherPlateauOrZero='..(iOtherPlateauOrZero or 'nil')..'; iOtherLZOrWZ='..(iOtherLZOrWZ or 'nil')..', based on iRallyPlateauOrZero='..iRallyPlateauOrZero..'Z'..iRallyLZOrWZ..'; dist='..(tPathingDetails[AiBotMap.subrefiDistance] or 'nil')..'; iSearchSize='..(iSearchSize or 'nil')..'; Does it have enemy units='..tostring(AiBotUtilities.IsTableEmpty(tOtherLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]))..'; Is table of targets empty='..tostring(AiBotUtilities.IsTableEmpty( tEnemyTargets))) end
                                            if AiBotUtilities.IsTableEmpty( tEnemyTargets) == false then
                                                --DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat,                                          iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck, bReturnGroundAAUnitsAlongsideAAThreat, tOptionalEndMidpointAdjustForDetailedCheck)
                                                iCurGroundAAThreatAlongPath, tAAUnitsAlongPath = DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauToUse, iStartZoneToUse,           iOtherPlateauOrZero, iOtherLZOrWZ, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl], iMaxEnemyGroundAAThreat, nil,                      false,           iAirSubteam, true,                     true,                       nil,                                            true)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Assigning bomber targets for iOtherLZOrWZ='..iOtherLZOrWZ..'; iCurGroundAAThreatAlongPath='..iCurGroundAAThreatAlongPath..'; iMaxEnemyGroundAAThreat='..iMaxEnemyGroundAAThreat) end
                                                bProceedWithAttack = false
                                                if iCurGroundAAThreatAlongPath < iMaxEnemyGroundAAThreat then
                                                    bProceedWithAttack = true
                                                    local oClosestEnemyToRally = AiBotUtilities.GetNearestUnit(tEnemyTargets, tRallyPoint)
                                                    if oClosestEnemyToRally then
                                                        local tNearbyEnemyGroundAA = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryGroundAA, oClosestEnemyToRally:GetPosition(), 80, 'Enemy')
                                                        if AiBotUtilities.IsTableEmpty(tNearbyEnemyGroundAA) == false then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy GroundAA threat using getunitsaroundpoint='..AiBotUnitInfo.GetAirThreatLevel(tNearbyEnemyGroundAA, true, false, true, false, false, false)..'; iMaxEnemyGroundAAThreat='..iMaxEnemyGroundAAThreat) end
                                                            if AiBotUnitInfo.GetAirThreatLevel(tNearbyEnemyGroundAA, true, false, true, false, false, false) >= iMaxEnemyGroundAAThreat then
                                                                bProceedWithAttack = false
                                                            else
                                                                if bDebugMessages == true then LOG(sFunctionRef..': will add nearby enemy groundAA to targets') end
                                                                FilterToAvailableTargets(tNearbyEnemyGroundAA, nil, true)
                                                            end
                                                        end
                                                    end
                                                    if bProceedWithAttack then
                                                        if AiBotUtilities.IsTableEmpty(tAAUnitsAlongPath) == false then
                                                            if bDebugMessages == true then LOG(sFunctionRef..': will add AA units along path to available targets') end
                                                            FilterToAvailableTargets(tAAUnitsAlongPath, nil, true)
                                                        end
                                                        --Further redundancy for nearby AA - get the closest potential enemy target, and search for nearby groundAA units using getunitsaroundpoint

                                                        AssignTorpOrBomberTargets(tAvailableBombers, tEnemyTargets, iAirSubteam, false, true)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Have added all enemy units and AA units along the path, are available bombers table empty now='..tostring(AiBotUtilities.IsTableEmpty(tAvailableBombers))) end
                                                        if AiBotUtilities.IsTableEmpty(tAvailableBombers) then break end
                                                    end
                                                end
                                                if not(bProceedWithAttack) then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Too great an enemy threat so wont add these targets after all') end
                                                    iSearchSize = math.min(iSearchSize, (tOtherLZOrWZData[AiBotMap.subrefLZTravelDist] or 0) + 25) --i.e. consider a couple more zones in case htey are in another direction
                                                end
                                                tEnemyTargets = {}
                                            end
                                            if bCheckForObjectiveTargets then AddObjectiveTargetsFromLZTeamData(tOtherLZOrWZTeamData) end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end


                if bDebugMessages == true then LOG(sFunctionRef..': Finished sending out bombers at targets, is table of available bombers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableBombers))..'; Is table of objective targets empty='..tostring(AiBotUtilities.IsTableEmpty(toObjectiveTargets))) end
                if bCheckForObjectiveTargets and AiBotUtilities.IsTableEmpty(toObjectiveTargets) == false and AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
                    AssignTorpOrBomberTargets(tAvailableBombers, toObjectiveTargets, iAirSubteam, true, true)
                end

                --Send any remaining bombers to rally point (or for refueling if they are damaged)
                local iIdleDistanceToReissueOrder = 20
                if AiBotConditions.IsAirMoveLocationSafeToIdle(tRallyPoint, iTeam, false) then iIdleDistanceToReissueOrder = 60 end
                if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
                    for iUnit, oUnit in tAvailableBombers do
                        if ((oUnit:GetFuelRatio() < 0.6 and oUnit:GetFuelRatio() >= 0) or (AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= 0.85 and (AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= 0.7 or EntityCategoryContains(categories.TECH1, oUnit.UnitId) or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint) <= 200))) and not(EntityCategoryContains(categories.CANNOTUSEAIRSTAGING, oUnit.UnitId)) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Have injured bomber so will send it for refueling as it is idle otherwise, Bomber oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                            table.insert(tBombersForRefueling, oUnit)
                        elseif AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint) <= iIdleDistanceToReissueOrder and oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition] and AiBotUtilities.GetDistanceBetweenPositions(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition], tRallyPoint) <= iIdleDistanceToReissueOrder then
                            --Idle air unit on ground
                        else
                            AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, iIdleDistanceToReissueOrder, false, 'BombIdl', false)
                        end
                    end
                end
            end
        end
    end

    if AiBotUtilities.IsTableEmpty(tSpecialLogicAvailableBombers) == false then
        for iUnit, oUnit in tSpecialLogicAvailableBombers do
            if EntityCategoryContains(categories.TECH1, oUnit.UnitId) then
                ApplyEngiHuntingBomberLogic(oUnit, iAirSubteam, iTeam)
            else
                AiBotUtilities.ErrorHandler('Special bomber logic not implemented other htan for t1 bombers')
            end
        end
    end

    --Send units for refueling
    if bDebugMessages == true then LOG(sFunctionRef..': Finished giving bomber orders, is table of air for refueling empty='..tostring(AiBotUtilities.IsTableEmpty(tBombersForRefueling))) end
    --Run the function even if no units wanting refueling so already attached untis can be sent on their way
    SendUnitsForRefueling(tBombersForRefueling, iTeam, iAirSubteam)
    if bDebugMessages == true and AiBotUtilities.IsTableEmpty(tBombersForRefueling) == false then
        LOG(sFunctionRef..': Will send '..table.getn(tBombersForRefueling)..' units to refuel')
    end
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurT1ToT3BomberThreat] = iOurBomberThreat
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageTorpedoBombers(iTeam, iAirSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageTorpedoBombers'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftWaterZonesHasFriendlyTorps] = {}
    local tAvailableBombers, tBombersForRefueling, tUnavailableUnits = GetAvailableLowFuelAndInUseAirUnits(iTeam, iAirSubteam, AiBotUnitInfo.refCategoryTorpBomber - AiBotUnitInfo.refCategoryGunship, true)
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurTorpBomberThreat] = AiBotUnitInfo.GetAirThreatLevel(tAvailableBombers, false, false, false, false, false, true) + AiBotUnitInfo.GetAirThreatLevel(tBombersForRefueling, false, false, false, false, false, true) + AiBotUnitInfo.GetAirThreatLevel(tUnavailableUnits, false, false, false, false, false, true)

    if bDebugMessages == true then
        LOG(sFunctionRef..': Start of code at time='..GetGameTimeSeconds()..'; Is table of available bombers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableBombers))..'; iTeam='..iTeam..'; iAirSubteam='..iAirSubteam)
        --List out every brain in airsubteam
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains]) == false then
            for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                LOG(sFunctionRef..': oBrain in subteam='..oBrain.Nickname)
            end
        end
    end
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbTooMuchGroundNavalAAForTorpBombers] = false
    local oRecentlyAttackingTorpBomber = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber] = nil
    if AiBotUnitInfo.IsUnitValid(oRecentlyAttackingTorpBomber) and ((oRecentlyAttackingTorpBomber[AiBotUnitInfo.refiLastWeaponEvent] and GetGameTimeSeconds() - oRecentlyAttackingTorpBomber[AiBotUnitInfo.refiLastWeaponEvent] <= 20) or oRecentlyAttackingTorpBomber[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack) then
        if bDebugMessages == true then LOG(sFunctionRef..': We had an attacking torp bomber from last cycle so will maintain it (but might replace it later on in code if we give new attack orders)') end
    else
        oRecentlyAttackingTorpBomber = nil
    end
    --Check unavailableunits in case any of them has an attack order
    if AiBotUtilities.IsTableEmpty(tUnavailableUnits) == false then
        local tRallyPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
        local iFurthestDistFromRally = 0
        local iCurDistFromRally
        if AiBotUnitInfo.IsUnitValid(oRecentlyAttackingTorpBomber) then iFurthestDistFromRally = AiBotUtilities.GetDistanceBetweenPositions(oRecentlyAttackingTorpBomber:GetPosition(), tRallyPoint) end
        for iUnit, oUnit in tUnavailableUnits do
            if (oUnit[AiBotUnitInfo.refiLastWeaponEvent] and GetGameTimeSeconds() - oUnit[AiBotUnitInfo.refiLastWeaponEvent] <= 20) or oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack then
                iCurDistFromRally = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint)
                if iCurDistFromRally > iFurthestDistFromRally then
                    iFurthestDistFromRally = iCurDistFromRally
                    oRecentlyAttackingTorpBomber = oUnit
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': oRecentlyAttackingTorpBomber after checking last recorded and unavailable torps='..(oRecentlyAttackingTorpBomber.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oRecentlyAttackingTorpBomber) or 'nil')) end
    local iTorpBomberThreat = 0
    local tiWZWithTooMuchAA = {}
    local tiAnglesFromRallyOfWZWithTooMuchAA = {}
    if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
        local tRallyPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
        local tEnemyTargets = {}
        local tbAdjacentWaterZonesConsidered = {}
        local tbWaterZonesConsidered = {}
        function AddEnemyTargetsInWaterZone(iWaterZone, bIsPrimaryZoneToAttack, iMaxDistFromAirRallyPointForAdjacentZones)
            --See above for refiAASearchTypes, i.e. refiAvoidAllAA, refiAvoidOnlyGroundAA, refiIgnoreAllAA
            if bDebugMessages == true then LOG(sFunctionRef..': Adding enemytargetsi n water zone '..iWaterZone..'; bIsPrimaryZoneToAttack='..tostring(bIsPrimaryZoneToAttack or false)..'; tbAdjacentWaterZonesConsidered[iWaterZone]='..tostring(tbAdjacentWaterZonesConsidered[iWaterZone] or false)..'; tbWaterZonesConsidered[iWaterZone]='..tostring(tbWaterZonesConsidered[iWaterZone] or false)) end
            if not(tbAdjacentWaterZonesConsidered[iWaterZone]) and (bIsPrimaryZoneToAttack or not(tbWaterZonesConsidered[iWaterZone])) then
                local iFurthestUnitFromRallyForZone = 0
                local bContinue = true
                tbWaterZonesConsidered[iWaterZone] = true
                local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone]
                local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]))) end
                if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                    local tEnemyUnitsOfInterest
                    if bIsPrimaryZoneToAttack then tEnemyUnitsOfInterest = tWZTeamData[AiBotMap.subrefTEnemyUnits]
                    else
                        tEnemyUnitsOfInterest = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGroundAA, tWZTeamData[AiBotMap.subrefTEnemyUnits])
                        if AiBotUtilities.IsTableEmpty(tEnemyUnitsOfInterest) then
                            if bDebugMessages == true then LOG(sFunctionRef..': enemy has no AA units of interest so returning nil') end
                            bContinue = false
                        end
                    end
                    if bContinue then
                        --Add enemy units if not hover
                        --local iCurDistToRally
                        --local iClosestOutOfRangeUnit = 10000
                        --local toDistanceAndUnitOutOfInitialRangeByDistance
                        local bCloseToBeingInRange
                        if not(bIsPrimaryZoneToAttack) then toDistanceAndUnitOutOfInitialRangeByDistance = {} end
                        for iUnit, oUnit in tEnemyUnitsOfInterest do
                            if AiBotUnitInfo.IsUnitValid(oUnit) and not(EntityCategoryContains(categories.HOVER, oUnit.UnitId)) then
                                --if land layer then unable to target
                                if not(oUnit:GetCurrentLayer() == 'Land') then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to table of enemy targets unless in an adjacent zone and too far away, target assigned WZ='..(oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] or 'nil')..'; AA threat='..AiBotUnitInfo.GetAirThreatLevel({ oUnit}, true, false, true, false, false, false)..'; position='..repru(oUnit:GetPosition())..'; Map water height='..AiBotMap.iMapWaterHeight..'; Is this location underwater='..tostring(AiBotMap.IsUnderwater(oUnit:GetPosition(), false, nil))..'; Dist to rally='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint)..'; iMaxDistFromAirRallyPointForAdjacentZones='..(iMaxDistFromAirRallyPointForAdjacentZones or 'nil')..'; Unit AA threat='..AiBotUnitInfo.GetAirThreatLevel({ oUnit }, true, false, true, false, false, false)) end
                                    --iCurDistToRally = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint)
                                    if bIsPrimaryZoneToAttack then --or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint) <= iMaxDistFromAirRallyPointForAdjacentZones then
                                        table.insert(tEnemyTargets, oUnit)
                                        --[[if bIsPrimaryZoneToAttack then
                                            if iCurDistToRally > iFurthestUnitFromRallyForZone then
                                                iFurthestUnitFromRallyForZone = iCurDistToRally
                                            end
                                        else
                                            if iCurDistToRally > iFurthestUnitFromRallyForZone then iFurthestUnitFromRallyForZone = iCurDistToRally end
                                        end--]]
                                        if bDebugMessages == true then LOG(sFunctionRef..': Added unit to enemy units table as it is in primary zone') end
                                    else
                                        --Check unit has an anti-air attack and is close to being in range of an enemy
                                        if (oUnit[AiBotUnitInfo.refiAARange] or 0) > 0 then
                                            bCloseToBeingInRange = false
                                            if AiBotUtilities.IsTableEmpty(tEnemyTargets) == false then
                                                for iEnemy, oEnemy in tEnemyTargets do
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Dist until in range of oEnemy '..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..': dist-Range='..AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition()) - oUnit[AiBotUnitInfo.refiAARange]..'; Angle dif vs rally='..AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oEnemy:GetPosition()), AiBotUtilities.GetAngleFromAToB(tRallyPoint, oEnemy:GetPosition()))) end
                                                    if AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition()) - oUnit[AiBotUnitInfo.refiAARange] <= 15
                                                            or (AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oEnemy:GetPosition()), AiBotUtilities.GetAngleFromAToB(tRallyPoint, oEnemy:GetPosition())) <= 25) then
                                                        table.insert(tEnemyTargets, oEnemy)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Unit is close to being able to give AA coverage to the enemy unit '..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; Unit AA range='..oUnit[AiBotUnitInfo.refiAARange]..'; Dist to existing enemy='..AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition())) end
                                                        break
                                                    end
                                                end
                                            end
                                        end
                                        --[[else
                                            table.insert(toDistanceAndUnitOutOfInitialRangeByDistance, math.floor(iCurDistToRally), oUnit)
                                        if iCurDistToRally < iClosestOutOfRangeUnit then iClosestOutOfRangeUnit = iCurDistToRally end--]]
                                    end
                                end
                            end
                        end
                        --Add any initially out of range units if we have just added other units close to this (i.e. want to avoid the scenario where we say target a frigate at the front of a naval force, but ignore the cruisers just behind it)
                        --[[local iNewDistanceThreshold = iFurthestUnitFromRallyForZone + 15
                        local bRemovedEntries
                        while iClosestOutOfRangeUnit < iFurthestUnitFromRallyForZone and AiBotUtilities.IsTableEmpty(toDistanceAndUnitOutOfInitialRangeByDistance) == false and not(bRemovedEntries) do
                            iClosestOutOfRangeUnit = 100000
                            bRemovedEntries = false
                            for iCurEntry = table.getn(toDistanceAndUnitOutOfInitialRangeByDistance), 1, -1 do
                                if toDistanceAndUnitOutOfInitialRangeByDistance[iCurEntry][1] <= iNewDistanceThreshold then
                                    table.insert(tEnemyTargets, toDistanceAndUnitOutOfInitialRangeByDistance[iCurEntry][2])
                                    table.remove(toDistanceAndUnitOutOfInitialRangeByDistance, iCurEntry)
                                    iFurthestUnitFromRallyForZone = math.max(iFurthestUnitFromRallyForZone, toDistanceAndUnitOutOfInitialRangeByDistance[iCurEntry][1])
                                    bRemovedEntries = true
                                else
                                    if toDistanceAndUnitOutOfInitialRangeByDistance[iCurEntry][1] < iClosestOutOfRangeUnit then iClosestOutOfRangeUnit = toDistanceAndUnitOutOfInitialRangeByDistance[iCurEntry][1] end
                                end
                            end
                            if not(bRemovedEntries) then break end --infinite loop redundancy
                        end--]]
                    end

                end
                if bIsPrimaryZoneToAttack and bContinue then
                    if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will add units in adjacent water zones if they arent too far away, iFurthestUnitFromRallyForZone='..(iFurthestUnitFromRallyForZone or 'nil')) end
                        for _, iAdjWZ in tWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                            AddEnemyTargetsInWaterZone(iAdjWZ, false, iFurthestUnitFromRallyForZone + 50)
                        end
                    end
                    tbAdjacentWaterZonesConsidered[iWaterZone] = true
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of defence water zones empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftiTorpedoDefenceWaterZones]))..'; Is reftoPriorityTorpedoUnitTargets empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoPriorityTorpedoUnitTargets]))) end
        local tiWaterZoneByDistance = {}
        local tStartLZOrWZData
        local iStartPlateauOrZero, iStartLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tRallyPoint)
        if iStartPlateauOrZero == 0 then
            tStartLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iStartLandOrWaterZone]
        else
            tStartLZOrWZData = AiBotMap.tAllPlateaus[iStartPlateauOrZero][AiBotMap.subrefPlateauLandZones][iStartLandOrWaterZone]
        end

        if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftiTorpedoDefenceWaterZones]) == false then
            for iEntry, iWaterZone in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftiTorpedoDefenceWaterZones] do
                local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone]
                tiWaterZoneByDistance[iWaterZone] = AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, tWZData[AiBotMap.subrefMidpoint])
            end
        else
            --Defend all water as presumably enemy has nearby naval units
            if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                for iEntry, tSubtable in tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                    if tSubtable[AiBotMap.subrefbIsWaterZone] then
                        tiWaterZoneByDistance[tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]] = tSubtable[AiBotMap.subrefiDistance]
                    end
                end
            else
                AiBotUtilities.ErrorHandler('Have torpedo bombers but no priority areas to defend with them', true)
            end
        end

        if AiBotUtilities.IsTableEmpty(tiWaterZoneByDistance) == false or (AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoPriorityTorpedoUnitTargets]) == false and AiBotUtilities.IsTableEmpty(tAvailableBombers) == false) then
            --Cycle through in order of distance
            iTorpBomberThreat = AiBotUnitInfo.GetAirThreatLevel(tAvailableBombers, false, false, false, true, false, true, false) + AiBotUnitInfo.GetAirThreatLevel(tUnavailableUnits, false, false, false, true, false, true, false)

            local iAAThreatThreshold

            local iAirAAThreatThreshold = 0
            if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then iAirAAThreatThreshold = iTorpBomberThreat * 0.25
            elseif not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]) then
                iAirAAThreatThreshold = math.min(iTorpBomberThreat * 0.15, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] * 0.25)
            end

            --Consider targeting any priority units first
            if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoPriorityTorpedoUnitTargets]) then
                local iCurSegmentX, iCurSegmentZ, iTargetWZ, bTooMuchAA, bHaveSeenTargetRecently
                local toPriorityTargets = {}
                local aiBrain
                for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                    aiBrain = oBrain
                    break
                end
                for iPriority, oPriority in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoPriorityTorpedoUnitTargets] do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering priority unit target='..oPriority.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oPriority)..' owned by '..oPriority:GetAIBrain().Nickname..'; Current height='..oPriority:GetPosition()[2]..'; Map water height='..AiBotMap.iMapWaterHeight..'; Water zone at position='..(AiBotMap.GetWaterZoneFromPosition(oPriority:GetPosition()) or 'nil')) end
                    if oPriority:GetPosition()[2] <= AiBotMap.iMapWaterHeight and (AiBotMap.GetWaterZoneFromPosition(oPriority:GetPosition()) or AiBotUnitInfo.IsUnitUnderwater(oPriority))  then
                        iAAThreatThreshold = iTorpBomberThreat * 2
                        iTargetWZ = oPriority[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam]
                        if not(iTargetWZ) then
                            iCurSegmentX, iCurSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oPriority:GetPosition())
                            iTargetWZ = AiBotMap.tWaterZoneBySegment[iCurSegmentX][iCurSegmentZ]
                        end
                        if iTargetWZ then bTooMuchAA = DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, 0, iTargetWZ, false,      iAAThreatThreshold,     iAirAAThreatThreshold * 3, true, iAirSubteam)
                        else
                            bTooMuchAA = false
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': bTooMuchAA='..tostring(bTooMuchAA)..'; iTargetWZ='..(iTargetWZ or 'nil')) end
                        if not(bTooMuchAA) then
                            --Can we either see the unit, or have torpedo bombers already attacking it?
                            bHaveSeenTargetRecently = AiBotUnitInfo.CanSeeUnit(aiBrain, oPriority)
                            if not(bHaveSeenTargetRecently) then
                                if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
                                    for iTorp, oTorp in tAvailableBombers do
                                        if oTorp[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefoOrderUnitTarget] == oPriority then
                                            bHaveSeenTargetRecently = true
                                            break
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': bHaveSeenTargetRecently='..tostring(bHaveSeenTargetRecently or false)) end
                            if bHaveSeenTargetRecently then
                                table.insert(toPriorityTargets, oPriority)
                            end
                        else
                            if iTargetWZ then
                                local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iTargetWZ]][AiBotMap.subrefPondWaterZones][iTargetWZ]
                                tiWZWithTooMuchAA[iTargetWZ] = true
                                table.insert(tiAnglesFromRallyOfWZWithTooMuchAA, AiBotUtilities.GetAngleFromAToB(tRallyPoint, tWZData[AiBotMap.subrefMidpoint]))
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of priority targets empty='..tostring(AiBotUtilities.IsTableEmpty(toPriorityTargets))) end
                if AiBotUtilities.IsTableEmpty(toPriorityTargets) == false then
                    AssignTorpOrBomberTargets(tAvailableBombers, toPriorityTargets, iAirSubteam)
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': About to cycle through water zones, iTorpBomberThreat='..iTorpBomberThreat..'; iAirAAThreatThreshold='..iAirAAThreatThreshold..'; tiWaterZoneByDistance='..repru(tiWaterZoneByDistance)..'; Is table of available torp bombers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableBombers))) end
            if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false and AiBotUtilities.IsTableEmpty(tiWaterZoneByDistance) == false then
                local bIgnoreDueToSimilarAngleAAThreat, iCurZoneAngleToRally
                local bDoDetailedCheck = true
                function ConsiderRecordingFrontTorpedoBomber()
                    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]) and AiBotUnitInfo.GetMassCostOfUnits(tEnemyTargets, true) >= 1500 then
                        local iCurDistToRally
                        local iFurthestDistToRally = 50 --no point recording torp bomber that is still close to our rally
                        local tCurRally = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
                        local oFurthestTorpFromRally
                        for iTorp, oTorp in tAvailableBombers do
                            iCurDistToRally = AiBotUtilities.GetDistanceBetweenPositions(oTorp:GetPosition(), tCurRally)
                            if iCurDistToRally > iFurthestDistToRally then
                                iFurthestDistToRally = iCurDistToRally
                                oFurthestTorpFromRally = oTorp
                            end
                        end

                        if oFurthestTorpFromRally then
                            --Check we havent got a recently fired torp bomber who is even further away (unless it is only a bit further awawy)
                            if AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]) and AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]:GetPosition(), tCurRally) > 10 + iFurthestDistToRally then
                                if bDebugMessages == true then LOG(sFunctionRef..': Wont update toFrontAttackingTorpBomber as we have a recently fired one that is further away, iFurthestDistToRally='..iFurthestDistToRally..'; Dist from rally for previously recorded attacking torp bomber='..AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]:GetPosition(), tCurRally)) end
                            else
                                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber] = oFurthestTorpFromRally
                            end
                        end
                    end
                end
                for iWaterZone, iDistance in AiBotUtilities.SortTableByValue(tiWaterZoneByDistance, false) do
                    local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone]
                    local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                    local iMassValueOfEnemyUnits = 0
                    if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                        iMassValueOfEnemyUnits = AiBotUnitInfo.GetMassCostOfUnits(tWZTeamData[AiBotMap.subrefTEnemyUnits], true)
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iWaterZone='..iWaterZone..'; iDistance='..iDistance..'; iMassValueOfEnemyUnits='..iMassValueOfEnemyUnits..'; refiModDistancePercent='..tWZTeamData[AiBotMap.refiModDistancePercent]) end
                    if iMassValueOfEnemyUnits > 0 then
                        if iTorpBomberThreat >= 6000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] or (iTorpBomberThreat >= 4000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] and GetGameTimeSeconds() - (tWZTeamData[AiBotMap.refiTimeOfLastTorpAttack] or -100) >= 3) then --Have so many torp bombers that dont want to worry about enemy groundAA threat quite as much
                            if tWZTeamData[AiBotMap.refiModDistancePercent] <= 0.2 or (tWZTeamData[AiBotMap.refiModDistancePercent] <= 0.4 and AiBotMap.iMapSize <= 512 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] == 0) then iAAThreatThreshold = iTorpBomberThreat * 0.8
                            elseif tWZTeamData[AiBotMap.refiModDistancePercent] <= 0.5 or (AiBotMap.iMapSize <= 256 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] == 0) then iAAThreatThreshold = iTorpBomberThreat * 0.45
                            elseif tWZTeamData[AiBotMap.refiModDistancePercent]  <= 0.75 then iAAThreatThreshold = iTorpBomberThreat * 0.25
                            else iAAThreatThreshold = iTorpBomberThreat * 0.2
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': We have a large torp bomber threat so setting a higher enemy AA threshold as even if we will lose the torps we may want to suicide them') end
                        elseif GetGameTimeSeconds() - (tWZTeamData[AiBotMap.refiTimeOfLastTorpAttack] or -100) >= 5 then
                            --Havnet attacked for a while, so want more threat than enemy
                            iAAThreatThreshold = iTorpBomberThreat * 0.4
                            if iDistance >= 200 then
                                if tWZTeamData[AiBotMap.subrefWZbCoreBase] then iAAThreatThreshold = iAAThreatThreshold * 0.75
                                else
                                    iAAThreatThreshold = iAAThreatThreshold * 0.5
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Havent attacked for a while, so want to delay an attack until we think we have enough threat, i.e. want more mass in torps than enemy has in AA') end
                        else
                            if tWZTeamData[AiBotMap.refiModDistancePercent] <= 0.2 then iAAThreatThreshold = iTorpBomberThreat * 0.8
                            elseif tWZTeamData[AiBotMap.refiModDistancePercent] <= 0.5 then iAAThreatThreshold = iTorpBomberThreat * 0.45
                            elseif tWZTeamData[AiBotMap.refiModDistancePercent]  <= 0.75 then iAAThreatThreshold = iTorpBomberThreat * 0.25
                            else iAAThreatThreshold = iTorpBomberThreat * 0.2
                            end
                            --Recently chose to attack here
                            if tWZTeamData[AiBotMap.refiModDistancePercent] <= 0.2 and tWZTeamData[AiBotMap.subrefWZbCoreBase] then
                                iAAThreatThreshold = math.min(iTorpBomberThreat * 1.2, math.max(iTorpBomberThreat * 0.8, iAAThreatThreshold * 1.25))
                            else
                                iAAThreatThreshold = math.min(iTorpBomberThreat, math.max(iTorpBomberThreat * 0.5, iAAThreatThreshold * 1.2))
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': We recently chose to attack this zone, so will be much more likely to attack with torps') end
                        end
                        if iDistance >= 300 then
                            iAAThreatThreshold = iAAThreatThreshold * (1 + (iDistance - 300) / 300)
                        end
                        --Be less liekly to send torp bombers if enemy has significantly more AA covering the target than the damage we would do attacking the target
                        if iAAThreatThreshold >= 500 and tWZTeamData[AiBotMap.refiModDistancePercent] >= 0.3 then
                            if tWZTeamData[AiBotMap.refiModDistancePercent] >= 0.75 then
                                iAAThreatThreshold = math.min(iAAThreatThreshold, iMassValueOfEnemyUnits)
                            elseif tWZTeamData[AiBotMap.refiModDistancePercent] >= 0.5 then
                                iAAThreatThreshold = math.min(iAAThreatThreshold, iMassValueOfEnemyUnits * 1.3)
                            else
                                iAAThreatThreshold = math.min(iAAThreatThreshold, iMassValueOfEnemyUnits * 1.75)
                            end
                        end
                        if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) then iAAThreatThreshold = iAAThreatThreshold * 0.6 end
                        --Be much more cautious of enemy AA if they ahve torp defence in the zone
                        if (tWZTeamData[AiBotMap.refiEnemyTorpDefenceCount] or 0) > 0 then
                            if iAAThreatThreshold <= 1000 or (iTorpBomberThreat >= 2000 and iAAThreatThreshold <= 1500 and iTorpBomberThreat >= iAAThreatThreshold * 2) then --i.e. up against frigates or similar
                                if bDebugMessages == true then LOG(sFunctionRef..': Reducing AA Threat threshold due to enemy torpedo defence but only slightly as a low threshold, iAAThreatThreshold before reduction='..iAAThreatThreshold) end
                                iAAThreatThreshold = math.max(100, iAAThreatThreshold * iAAThreatThreshold / (iAAThreatThreshold + math.min(iAAThreatThreshold * 1.75, math.min(30, tWZTeamData[AiBotMap.refiEnemyTorpDefenceCount]) * 100)))
                                if bDebugMessages == true then LOG(sFunctionRef..': iAAThreatThreshold after low value reduction='..iAAThreatThreshold) end
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Reducing AA Threat threshold due to enemy torpedo defence, iAAThreatThreshold before reduction='..iAAThreatThreshold) end
                                iAAThreatThreshold = iAAThreatThreshold * iAAThreatThreshold / (iAAThreatThreshold + math.min(iAAThreatThreshold * 4, math.min(30, tWZTeamData[AiBotMap.refiEnemyTorpDefenceCount]) * 500))
                                if iAAThreatThreshold < 1000 then iAAThreatThreshold = math.max(800, (1000 - iAAThreatThreshold)*0.5+iAAThreatThreshold) end
                                if bDebugMessages == true then LOG(sFunctionRef..': iAAThreatThreshold after reduction='..iAAThreatThreshold) end
                            end
                        end
                        --Increase the threshold for high numbers of torpedo bombers (30+) where mod dist relatively low and distance also relatively low
                        if iTorpBomberThreat >= 8000 and tWZTeamData[AiBotMap.refiModDistancePercent] <= 0.35 and (iDistance <= 200 or tWZTeamData[AiBotMap.refiModDistancePercent] <= 0.25) and iAAThreatThreshold < iTorpBomberThreat * 0.9 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Have very large torpedo bomber threat so will increase AA threshold a bit, iAAThreatThreshold before increase='..iAAThreatThreshold..'; iTorpBomberThreat='..iTorpBomberThreat..'; iMassValueOfEnemyUnits='..iMassValueOfEnemyUnits) end
                            iAAThreatThreshold = math.min(iTorpBomberThreat * 0.9, iAAThreatThreshold + (0.5 * math.max(0, iTorpBomberThreat - 15000)) + 0.3 * (math.min(15000, iTorpBomberThreat) - 8000), math.max(iMassValueOfEnemyUnits * 0.6, iAAThreatThreshold * 1.2))
                        end

                        --Min AA threat for nearby WZs as we can probably attrition enemy destroyers with a single torp bomber that then reheals itself at staging
                        if tWZTeamData[AiBotMap.refiModDistancePercent] <= 0.35 and iAAThreatThreshold < 200 and tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] > tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] then iAAThreatThreshold = 200 end

                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if enemies in iWaterZone='..iWaterZone..'; iStartPlateauOrZero='..iStartPlateauOrZero..'; iStartLandOrWaterZone='..iStartLandOrWaterZone..';  iDistance='..iDistance..'; Is table of enemy units in this WZ empty='..tostring(AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]))..'; tWZTeamData[AiBotMap.subrefWZbCoreBase]='..tostring(tWZTeamData[AiBotMap.subrefWZbCoreBase] or false)..'; iTorpBomberThreat='..iTorpBomberThreat..'; tWZTeamData[AiBotMap.refiModDistancePercent]='..tWZTeamData[AiBotMap.refiModDistancePercent]..'; iMassValueOfEnemyUnits='..iMassValueOfEnemyUnits..'; tWZTeamData[AiBotMap.refiEnemyTorpDefenceCount]='..(tWZTeamData[AiBotMap.refiEnemyTorpDefenceCount] or 'nil')..'; Enemy groundAA just in this water zone='..tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]..'; iAAThreatThreshold after adjustments='..iAAThreatThreshold) end
                        if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                            --If enemy has too much AA in a WZ in a similar angle then ignore
                            bIgnoreDueToSimilarAngleAAThreat = false
                            if AiBotUtilities.IsTableEmpty(tiAnglesFromRallyOfWZWithTooMuchAA) == false then
                                iCurZoneAngleToRally = AiBotUtilities.GetAngleFromAToB(tRallyPoint, tWZData[AiBotMap.subrefMidpoint])
                                for _, iDangerousAngleToRally in tiAnglesFromRallyOfWZWithTooMuchAA do
                                    if AiBotUtilities.GetAngleDifference(iCurZoneAngleToRally, iDangerousAngleToRally) <= 25 then
                                        bIgnoreDueToSimilarAngleAAThreat = true
                                        break
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Want to attack, enemy AA threat threshold='..iAAThreatThreshold..'; DoesEnemyHaveAAThreatAlongPath='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, 0, iWaterZone, false, iAAThreatThreshold, 0))..'; bIgnoreDueToSimilarAngleAAThreat='..tostring(bIgnoreDueToSimilarAngleAAThreat)..'; bDoDetailedCheck='..tostring(bDoDetailedCheck)) end
                            --DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA)
                            if bIgnoreDueToSimilarAngleAAThreat then
                                if bDebugMessages == true then LOG(sFunctionRef..': Ignoring due to nearby angle zone that does have significant threat') end
                                tiWZWithTooMuchAA[iWaterZone] = true
                                --                                                                                                                                                                                                                 DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck, bReturnGroundAAUnitsAlongsideAAThreat, tOptionalEndMidpointAdjustForDetailedCheck, bOptionalIgnoreOppositeDirectionZones, bIncludeEnemyGroundAAInAirAAThreat, bAssumeWontTargetInterimAAForDetailedCheck, bIgnoreUnderwaterAA)
                            elseif not(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, 0, iWaterZone, false,      iAAThreatThreshold,     iAirAAThreatThreshold, true, iAirSubteam) or (bDoDetailedCheck and not(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone,        0,              iWaterZone,         false,              iAAThreatThreshold,      iAirAAThreatThreshold,     true,           iAirSubteam,        true,               false,                      nil,                                        false,                                      nil,                                        true,                               false,                              true,                                       true)))) then
                                --Add enemies in this water zone and any adjacent water zone
                                AddEnemyTargetsInWaterZone(iWaterZone, true)
                                tWZTeamData[AiBotMap.refiTimeOfLastTorpAttack] = GetGameTimeSeconds()
                                if bDebugMessages == true then LOG(sFunctionRef..': will attack enemies in this water zone if any valid targets, is tEnemyTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyTargets))) end
                                if AiBotUtilities.IsTableEmpty(tEnemyTargets) == false then
                                    --Double check the AA threat of assigned enemies isnt too much (redundancy for if our 'include adjacent zone' logic has added some units - will only abort if is significantly higher than what we wanted)
                                    local iEnemyGroundAAThreat = AiBotUnitInfo.GetAirThreatLevel(tEnemyTargets, true, false, true, false, false, false)
                                    if bDebugMessages == true then LOG(sFunctionRef..': AA threat of all targets='..iEnemyGroundAAThreat..'; will abort if it is too high, iAAThreatThreshold='..iAAThreatThreshold) end
                                    if iEnemyGroundAAThreat > iAAThreatThreshold * 1.1 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will abort the attack as totla enemy AA threat is more than we wanted') end
                                        break
                                    end

                                    --Assign targets by type
                                    local iPriorityCat1 = AiBotUnitInfo.refCategoryGroundAA + AiBotUnitInfo.refCategoryShieldBoat
                                    local iPriorityCat2 = AiBotUnitInfo.refCategoryFrigate - iPriorityCat1
                                    local iOtherCat = categories.ALLUNITS - iPriorityCat1 - iPriorityCat2
                                    local tEnemyPriority1 = EntityCategoryFilterDown(iPriorityCat1, tEnemyTargets)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of priority1 units empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyPriority1))) end
                                    --Record front torpedo bomber out of those available, if enemy has significant threat and we have air control
                                    ConsiderRecordingFrontTorpedoBomber()

                                    if AiBotUtilities.IsTableEmpty(tEnemyPriority1) == false then
                                        AssignTorpOrBomberTargets(tAvailableBombers, tEnemyPriority1, iAirSubteam)
                                        if AiBotUtilities.IsTableEmpty(tAvailableBombers) then
                                            break
                                        else
                                            AssignTorpOrBomberTargets(tAvailableBombers, tEnemyPriority1, iAirSubteam,  nil,                nil,                    nil,            2)
                                        end
                                    end
                                    local tEnemyPriority2 = EntityCategoryFilterDown(iPriorityCat2, tEnemyTargets)
                                    if AiBotUtilities.IsTableEmpty(tEnemyPriority2) == false then
                                        AssignTorpOrBomberTargets(tAvailableBombers, tEnemyPriority2, iAirSubteam)
                                        if AiBotUtilities.IsTableEmpty(tAvailableBombers) then
                                            break
                                        end
                                    end
                                    local tEnemyOther = EntityCategoryFilterDown(iOtherCat, tEnemyTargets)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Is table tEnemyOther empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyOther))) end
                                    if AiBotUtilities.IsTableEmpty(tEnemyOther) == false then
                                        AssignTorpOrBomberTargets(tAvailableBombers, tEnemyOther, iAirSubteam)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Is table of available bombers empty after assigning torp targets='..tostring(AiBotUtilities.IsTableEmpty(tAvailableBombers))) end
                                        if AiBotUtilities.IsTableEmpty(tAvailableBombers) then
                                            break
                                        end
                                    end
                                    --Send extra torps (i.e. overkill) for AA
                                    if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
                                        --We have already done priority1 units above
                                        if AiBotUtilities.IsTableEmpty(tEnemyPriority2) == false then
                                            AssignTorpOrBomberTargets(tAvailableBombers, tEnemyPriority2, iAirSubteam,  nil,                nil,                    nil,            2)
                                            if AiBotUtilities.IsTableEmpty(tAvailableBombers) then
                                                break
                                            end
                                        end
                                        if AiBotUtilities.IsTableEmpty(tEnemyOther) == false then
                                            AssignTorpOrBomberTargets(tAvailableBombers, tEnemyOther, iAirSubteam,  nil,                nil,                    nil,            2)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Is table of available bombers empty after assigning torp targets with double threat factor='..tostring(AiBotUtilities.IsTableEmpty(tAvailableBombers))) end
                                            if AiBotUtilities.IsTableEmpty(tAvailableBombers) then
                                                break
                                            end
                                        end
                                    end
                                end
                                --Clear enemy targets (incase e.g. we have decided not to attack some of them because we have enough threat assigned already or outside playable area)
                                tEnemyTargets = {}
                                --Consider attacking the nearest enemy AA unit in the zone if it is exposed, or if there is no nearby AA unit the nearest non-hover unit
                            elseif bDoDetailedCheck and tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] <= 10000 and tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] + (tWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) < iAAThreatThreshold * 0.8 and ((tWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) == 0 or AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then
                                local oClosestAAUnit, iCurDist
                                local oClosestNonAAUnit
                                local iClosestAAUnit = 10000
                                local iClosestNonAAUnit = 10000
                                for iUnit, oUnit in tWZTeamData[AiBotMap.subrefTEnemyUnits] do
                                    if not(oUnit.Dead) and not(EntityCategoryContains(categories.HOVER, oUnit.UnitId)) then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tStartLZOrWZData[AiBotMap.subrefMidpoint])
                                        if oUnit[AiBotUnitInfo.refiAARange] and EntityCategoryContains(AiBotUnitInfo.refCategoryGroundAA, oUnit.UnitId) then
                                            if iCurDist - oUnit[AiBotUnitInfo.refiAARange] < iClosestAAUnit then
                                                iClosestAAUnit = iCurDist - oUnit[AiBotUnitInfo.refiAARange]
                                                oClosestAAUnit = oUnit
                                            end
                                        elseif iCurDist < iClosestNonAAUnit then
                                            iClosestNonAAUnit = iCurDist
                                            oClosestNonAAUnit = oUnit
                                        end
                                    end
                                end
                                local oUnitToConsiderTargeting = (oClosestAAUnit or oClosestNonAAUnit)
                                if bDebugMessages == true then LOG(sFunctionRef..': Detailed check for vulnerable unit, oClosestAAUnit='..(oClosestAAUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestAAUnit) or 'nil')..'; oClosestNonAAUnit='..(oClosestNonAAUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestNonAAUnit) or 'nil'))
                                    if oClosestAAUnit and oClosestNonAAUnit then LOG(sFunctionRef..': Dist between oClosestAAUnit and oClosestNonAAUnit='..AiBotUtilities.GetDistanceBetweenPositions(oClosestAAUnit:GetPosition(), oClosestNonAAUnit:GetPosition())..'; oClosestAAUnit range='..(oClosestAAUnit[AiBotUnitInfo.refiAARange] or 'nil')..'; iClosestNonAAUnit='..iClosestNonAAUnit..'; iClosestAAUnit less range='..iClosestAAUnit) end
                                end
                                if oUnitToConsiderTargeting and (tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] <= 400 or not(oClosestAAUnit) or (oClosestAAUnit and AiBotUnitInfo.GetAirThreatLevel({ oClosestAAUnit }, true, false, true, false, false, false) >= 0.5 * tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]))  then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if oUnitToConsiderTargeting='..oUnitToConsiderTargeting.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitToConsiderTargeting)..' is vulnerable to torpedo bomber attack') end
                                    --DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck, bReturnGroundAAUnitsAlongsideAAThreat, tOptionalEndMidpointAdjustForDetailedCheck, bOptionalIgnoreOppositeDirectionZones, bIncludeEnemyGroundAAInAirAAThreat, bAssumeWontTargetInterimAAForDetailedCheck, bIgnoreUnderwaterAA)
                                    if not(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone,        0,              iWaterZone,         false,              iAAThreatThreshold,      iAirAAThreatThreshold,     true,           iAirSubteam,        true,               false,                      nil,                                        false,                                      oUnitToConsiderTargeting:GetPosition(),         true,                               false,                              true,                           true)) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will target just this unit and nearby ones') end
                                        ConsiderRecordingFrontTorpedoBomber()
                                        local toUnitsToTarget = {oUnitToConsiderTargeting}
                                        if not(oUnitToConsiderTargeting == oClosestAAUnit) and oClosestAAUnit and (iClosestNonAAUnit > iClosestAAUnit or AiBotUtilities.GetDistanceBetweenPositions(oClosestAAUnit:GetPosition(), oUnitToConsiderTargeting:GetPosition()) - (oClosestAAUnit[AiBotUnitInfo.refiAARange] or 0) <= 20) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Including closest enemy AA unit in table of units to target') end
                                            table.insert(toUnitsToTarget, oClosestAAUnit)
                                        end
                                        for iUnit, oUnit in tWZTeamData[AiBotMap.subrefTEnemyUnits] do
                                            if not(oUnit == oUnitToConsiderTargeting) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnitToConsiderTargeting:GetPosition()) <= 15 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Adding nearby enemy naval unit oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to targets') end
                                                table.insert(toUnitsToTarget, oUnit)
                                            end
                                        end
                                        AssignTorpOrBomberTargets(tAvailableBombers, toUnitsToTarget, iAirSubteam,  nil,                nil,                    nil,            1.5)
                                    else tiWZWithTooMuchAA[iWaterZone] = true
                                    end
                                elseif oUnitToConsiderTargeting and not(oUnitToConsiderTargeting == oClosestAAUnit) and iClosestNonAAUnit < iClosestAAUnit and AiBotUtilities.GetDistanceBetweenPositions(oClosestAAUnit:GetPosition(), oClosestNonAAUnit:GetPosition()) - (oClosestAAUnit[AiBotUnitInfo.refiAARange] or 0) >= 40 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Nearest enemy too far from enemy AA so will try targeting it provided not significant AA along path') end
                                    --      DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck, bReturnGroundAAUnitsAlongsideAAThreat, tOptionalEndMidpointAdjustForDetailedCheck, bOptionalIgnoreOppositeDirectionZones, bIncludeEnemyGroundAAInAirAAThreat, bAssumeWontTargetInterimAAForDetailedCheck, bIgnoreUnderwaterAA)
                                    if not(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone,        0,              iWaterZone,         false,              iAAThreatThreshold,      iAirAAThreatThreshold,     true,           iAirSubteam,        true,               false,                      nil,                                        false,                                      oUnitToConsiderTargeting:GetPosition(),         true,                               false,                              true,                                       true)) then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy doesnt have enough AA threat along path doing detailed check') end
                                        local toUnitsToTarget = {}
                                        for iUnit, oUnit in tWZTeamData[AiBotMap.subrefTEnemyUnits] do
                                            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnitToConsiderTargeting:GetPosition()) <= 20 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Including unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' in units to target') end
                                                table.insert(toUnitsToTarget)
                                            end
                                        end
                                        if toUnitsToTarget[1] then
                                            ConsiderRecordingFrontTorpedoBomber()
                                            AssignTorpOrBomberTargets(tAvailableBombers, toUnitsToTarget, iAirSubteam,  nil,                nil,                    nil,            1.5)
                                        end
                                    else tiWZWithTooMuchAA[iWaterZone] = true
                                    end
                                else tiWZWithTooMuchAA[iWaterZone] = true
                                end
                            else
                                tiWZWithTooMuchAA[iWaterZone] = true
                                table.insert(tiAnglesFromRallyOfWZWithTooMuchAA, AiBotUtilities.GetAngleFromAToB(tRallyPoint, tWZData[AiBotMap.subrefMidpoint]))
                                if bDebugMessages == true then LOG(sFunctionRef..': Recording that WZ has too much AA') end
                            end
                        end
                        --Only do detailed check for the first water zone with potential enemy targets
                        bDoDetailedCheck = false
                    end
                end
            end
        else
            AiBotUtilities.ErrorHandler('Have torpedo bombers but no areas to defend with them')
        end
        --Send remaining units to rally point (or refuel if could do with refuel)
        if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
            for iUnit, oUnit in tAvailableBombers do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering idle torp bomber order for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' Unit fuel='..oUnit:GetFuelRatio()..'; Unit health%='..AiBotUnitInfo.GetUnitHealthPercent(oUnit)..'; rally point='..repru(tRallyPoint)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
                if ((oUnit:GetFuelRatio() < 0.6 and oUnit:GetFuelRatio() >= 0) or AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= 0.85) and not(EntityCategoryContains(categories.CANNOTUSEAIRSTAGING, oUnit.UnitId)) then
                    table.insert(tBombersForRefueling, oUnit)
                else
                    AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 10, false, 'TpIdle', false)
                end
            end
        end
    end

    --Flag if we lack torpedo bombers
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] = false
    if bDebugMessages == true then LOG(sFunctionRef..': is tiWZWithTooMuchAA empty='..tostring(AiBotUtilities.IsTableEmpty(tiWZWithTooMuchAA))..'; is tAvailableBombers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableBombers))) end
    if AiBotUtilities.IsTableEmpty(tAvailableBombers) or AiBotUtilities.IsTableEmpty(tiWZWithTooMuchAA) == false then
        if bDebugMessages == true then LOG(sFunctionRef..': Is reftoPriorityTorpedoUnitTargets empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoPriorityTorpedoUnitTargets]))..'; is reftiTorpedoDefenceWaterZones empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftiTorpedoDefenceWaterZones]))) end
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoPriorityTorpedoUnitTargets]) == false then
            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] = true
            if bDebugMessages == true then LOG(sFunctionRef..': Want more torp bombers to deal with priority enemy targets') end
        elseif AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftiTorpedoDefenceWaterZones]) == false then
            local bConsiderEvenIfTooMuchAA = AiBotUtilities.IsTableEmpty(tAvailableBombers)
            for iEntry, iWaterZone in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftiTorpedoDefenceWaterZones] do
                if bConsiderEvenIfTooMuchAA or tiWZWithTooMuchAA[iWaterZone] then
                    local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone]
                    local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if want torp bombers - considering iWaterZone='..iWaterZone..'; is table of enemy units mpety='..tostring(AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]))..'; does this WZ have only hover enemies='..tostring(tWZTeamData[AiBotMap.subrefbWZOnlyHoverEnemies])..'; iTorpBomberThreat='..iTorpBomberThreat..'; subrefTThreatEnemyCombatTotal='..(tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; subrefWZThreatEnemyVsSurface='..(tWZTeamData[AiBotMap.subrefWZThreatEnemyVsSurface] or 'nil')..'; subrefiHighestFriendlyNavalFactoryTech='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech]) end
                    if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subrefTEnemyUnits]) == false and not(tWZTeamData[AiBotMap.subrefbWZOnlyHoverEnemies]) and (tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 100 or (tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]  >= 25 and iTorpBomberThreat == 0) or ((tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) > 1500 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] == 0 or AiBotMap.iMapSize <= 256))) then
                        --Check enemy doesnt have a naval fac in this zone if we have a significant torp bomber threat already and have naval fac
                        if iTorpBomberThreat < 2500 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] == 0 or AiBotMap.iMapSize <= 256 or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tWZTeamData[AiBotMap.subrefTEnemyUnits])) then
                            --Check enemy AA t hreat, as we might not have targeted htis zone due to enemy airaa
                            if bDebugMessages == true then LOG(sFunctionRef..': Want more torp bombers to deal with enemy unless enemy AirAA threat is the reason, iTorpBomberThreat='..iTorpBomberThreat..'; tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; subrefiThreatEnemyGroundAA='..tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]) end
                            if iTorpBomberThreat < (tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) or (iTorpBomberThreat < (tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 3 and (tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) > 0.1 * iTorpBomberThreat) or
                                    --If are naval locked then even if enemy has mostly cruisers in this zone still want to consider killing with torp bombers
                                    (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] < 2 and (iTorpBomberThreat <= 6000 or iTorpBomberThreat < ((tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) * 2 + (tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)) * 5) and (iTorpBomberThreat < 4000 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyNavalFactoryTech] == 0))then
                                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies] = true
                                if bDebugMessages == true then LOG(sFunctionRef..': We want more torp bombers as we lack available torp bombers, iTorpBomberThreat='..iTorpBomberThreat..'; iWaterZone='..iWaterZone..'; Enemy combat total='..(tWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; subrefiThreatEnemyGroundAA='.. (tWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)) end
                                break
                            end
                        end
                    end
                end
            end
        end
    end

    --Update lastattackingtorp bomber if unavailable or previous entry is further from rally to current entry
    if AiBotUnitInfo.IsUnitValid(oRecentlyAttackingTorpBomber) then
        if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]) then
            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber] = oRecentlyAttackingTorpBomber
        else
            local tRallyPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
            local iFurthestDistFromRally = AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]:GetPosition(), tRallyPoint)
            if AiBotUtilities.GetDistanceBetweenPositions(oRecentlyAttackingTorpBomber:GetPosition(), tRallyPoint) > iFurthestDistFromRally + 10 then
                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber] = oRecentlyAttackingTorpBomber
            end
        end
    end

    --Send units for refueling
    if bDebugMessages == true then LOG(sFunctionRef..': Finished giving torp bomber orders, is table of air for refueling empty='..tostring(AiBotUtilities.IsTableEmpty(tBombersForRefueling))..'; AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies]='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoAvailableTorpsForEnemies])..'; toFrontAttackingTorpBomber at end of code='..(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.toFrontAttackingTorpBomber]) or 'nil')) end
    --Run the function even if no units wanting refueling so already attached untis can be sent on their way
    SendUnitsForRefueling(tBombersForRefueling, iTeam, iAirSubteam)
    if bDebugMessages == true and AiBotUtilities.IsTableEmpty(tBombersForRefueling) == false then
        LOG(sFunctionRef..': Will send '..table.getn(tBombersForRefueling)..' units to refuel')
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AssignTorpOrBomberTargets(tAvailableBombers, tEnemyTargets, iAirSubteam, bForceGroundFire, bTargetAAAndShieldsFirst, bIgnoreMicro, iOptionalOverkillFactor)
    --NOTE: If want to prioritise by category then do by changing tEnemyTargets and calling this function multiple times
    --iOptionalOverkillFactor - e.g. if 2 then will send twice as many units as normal (intended where we still have available torp bombers after considering targets)

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AssignTorpOrBomberTargets'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time='..GetGameTimeSeconds()..'; bIgnoreMicro='..tostring(bIgnoreMicro or false)..'; Likely team='..(tAvailableBombers[1]:GetAIBrain().AiBotTeam or 'nil')) end

    if bTargetAAAndShieldsFirst then
        if bDebugMessages == true then LOG(sFunctionRef..': Will split up targets between those iwth AA category and those without; also priority enemy ACUs ahead of all this, mass cost of available bombers='..AiBotUnitInfo.GetMassCostOfUnits(tAvailableBombers)) end
        if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurT1ToT3BomberThreat] >= 2000 and EntityCategoryContains(AiBotUnitInfo.refCategoryBomber, tAvailableBombers[1].UnitId) then
            local tEnemyACU = EntityCategoryFilterDown(categories.COMMAND, tEnemyTargets)
            if bDebugMessages == true then LOG(sFunctionRef..': is table of enemy ACU empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyACU))) end
            if AiBotUtilities.IsTableEmpty(tEnemyACU) == false then
                if AiBotUnitInfo.GetMassCostOfUnits(tAvailableBombers) >= 15000 then
                    AssignTorpOrBomberTargets(tAvailableBombers, tEnemyACU, iAirSubteam, bForceGroundFire, false, bIgnoreMicro)
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
            local iSearchCategory = AiBotUnitInfo.refCategoryGroundAA + AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryMobileLandShield + AiBotUnitInfo.refCategoryShieldBoat
            local tEnemyAAAndShields = EntityCategoryFilterDown(iSearchCategory, tEnemyTargets)
            if AiBotUtilities.IsTableEmpty(tEnemyAAAndShields) then
                if bDebugMessages == true then LOG(sFunctionRef..': Have no enemy AA so will call this again and assign targets to all enemy units, without order to target AA first') end
                AssignTorpOrBomberTargets(tAvailableBombers, tEnemyTargets, iAirSubteam, bForceGroundFire, false, bIgnoreMicro)
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Will call this function again targeting just the enemy AA units') end
                AssignTorpOrBomberTargets(tAvailableBombers, tEnemyAAAndShields, iAirSubteam, bForceGroundFire, false, bIgnoreMicro)
                if bDebugMessages == true then LOG(sFunctionRef..': Have finished targeting the enemy AA units, is available bombers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableBombers))) end
                if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
                    if bDebugMessages == true then LOG(sFunctionRef..': Still have available bombers so will target all units') end
                    local tOtherTargets = EntityCategoryFilterDown(categories.ALLUNITS - iSearchCategory, tEnemyTargets)
                    if AiBotUtilities.IsTableEmpty(tOtherTargets) == false then
                        AssignTorpOrBomberTargets(tAvailableBombers, tOtherTargets, iAirSubteam, bForceGroundFire, false, bIgnoreMicro)
                    end
                end
            end
        end
    else

        --Copy of AiBotUtiliteis function (for speed)
        function GetRoughDistanceBetweenPositions(tPosition1, tPosition2)
            --If want a rough indication of proximity but it isnt as important as speed
            return math.max(math.abs(tPosition1[1] - tPosition2[1]), math.abs(tPosition1[3] - tPosition2[3]))
        end



        --local iAvailableAirSize = table.getn(tAvailableBombers)
        local iEnemyTargetSize = table.getn(tEnemyTargets)
        local iClosestUnitDist, oClosestUnit, iCurDist, iClosestTorpRef
        local iCurLoopCount
        local iMaxLoopCount = 200 --Wont assign more than this number of AA units to a particular target, partly as an infinite loop check, and partly to avoid too much on a single unit (e.g. czar or ahwassa)
        local iTotalStrikeDamageWanted
        if bDebugMessages == true then LOG(sFunctionRef..': About to cycle through torp bomber targets, iEnemyTargetSize='..iEnemyTargetSize..'; Time='..GetGameTimeSeconds()) end

        --First order enemy units by distance
        local tRallyPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
        local toEnemyUnitsByDistance = {}
        for iUnit, oUnit in tEnemyTargets do
            toEnemyUnitsByDistance[iUnit] = GetRoughDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint)
        end

        local aiBrain
        local bTorpBombers = false
        local iUnitTorpDefenceCount
        if tAvailableBombers[1] then
            aiBrain = tAvailableBombers[1]:GetAIBrain()
            if EntityCategoryContains(AiBotUnitInfo.refCategoryTorpBomber, tAvailableBombers[1].UnitId) then
                bTorpBombers = true
                iUnitTorpDefenceCount = 0
                for iUnit, oUnit in toEnemyUnitsByDistance do
                    if oUnit[AiBotUnitInfo.refiTorpedoDefenceCount] then iUnitTorpDefenceCount = iUnitTorpDefenceCount + oUnit[AiBotUnitInfo.refiTorpedoDefenceCount] end
                end
            end
        else
            for iUnit, oUnit in tAvailableBombers do
                aiBrain = oUnit:GetAIBrain()
                break
            end
        end
        local bIssueAttackUnitOrder
        --Go through enemy units by distance to rally point (so target the nearest ones first)
        local bDontCheckPlayableArea = not(AiBotMap.bIsCampaignMap)
        local iEnemyTorpDefenceCount, bAlreadyRecorded
        local bBlockingShoreline, iAngleToRally

        for iCurEnemyUnit, iDistance in AiBotUtilities.SortTableByValue(toEnemyUnitsByDistance, false) do
            --for iCurEnemyUnit = iEnemyTargetSize, 1, -1 do
            iClosestUnitDist = 100000
            local oEnemyUnit = tEnemyTargets[iCurEnemyUnit]

            if (bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(oEnemyUnit:GetPosition())) and (oEnemyUnit and not(oEnemyUnit.Dead)) then
                iTotalStrikeDamageWanted = oEnemyUnit:GetMaxHealth()
                if oEnemyUnit.MyShield.GetMaxHealth then iTotalStrikeDamageWanted = iTotalStrikeDamageWanted + oEnemyUnit.MyShield:GetMaxHealth() end
                if bTorpBombers then
                    if not(iEnemyTorpDefenceCount) then
                        local tCurWZData, tCurWZTeamData = AiBotMap.GetLandOrWaterZoneData(oEnemyUnit:GetPosition(), true, aiBrain.AiBotTeam)
                        iEnemyTorpDefenceCount = math.max((iUnitTorpDefenceCount or 0), (tCurWZTeamData[AiBotMap.refiEnemyTorpDefenceCount] or 0))
                    end
                    if iEnemyTorpDefenceCount > 0 then
                        --Torp bombers seem weakiner in LOUD (and to lesser extent QUIET) so will be even more prudent re how many bombers we need
                        if AiBotUtilities.bLoudModActive then iTotalStrikeDamageWanted = math.max(math.min(iTotalStrikeDamageWanted * 4, iEnemyTorpDefenceCount * 400), iTotalStrikeDamageWanted * 1.8)
                        elseif AiBotUtilities.bQuietModActive then iTotalStrikeDamageWanted = math.max(math.min(iTotalStrikeDamageWanted * 3.5, iEnemyTorpDefenceCount * 325), iTotalStrikeDamageWanted * 1.5)
                        else iTotalStrikeDamageWanted = math.max(math.min(iTotalStrikeDamageWanted * 3, iEnemyTorpDefenceCount * 250), iTotalStrikeDamageWanted * 1.25)
                        end
                    else
                        if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then iTotalStrikeDamageWanted = iTotalStrikeDamageWanted * 1.25 end
                    end
                end

                local tBasePosition = oEnemyUnit:GetPosition()
                iCurLoopCount = 0
                --If dealing with an anti-air unit then increase strike damage wanted by 50% to allow for some of the torps dying
                if EntityCategoryContains(AiBotUnitInfo.refCategoryCruiserCarrier, oEnemyUnit.UnitId) then
                    iTotalStrikeDamageWanted = iTotalStrikeDamageWanted * 1.5
                elseif EntityCategoryContains(AiBotUnitInfo.refCategoryStructureAA + categories.COMMAND + AiBotUnitInfo.refCategoryGroundAA * categories.TECH3, oEnemyUnit.UnitId) then
                    iTotalStrikeDamageWanted = iTotalStrikeDamageWanted * 1.2
                    if EntityCategoryContains(categories.COMMAND, oEnemyUnit.UnitId) and aiBrain then
                        --Check if under a fixed shield
                        local iShieldHealth = AiBotLogic.IsTargetUnderShield(aiBrain, oEnemyUnit, 0, true, false, true, true)
                        iTotalStrikeDamageWanted = iTotalStrikeDamageWanted + (iShieldHealth or 0)
                    end
                end
                if iOptionalOverkillFactor then iTotalStrikeDamageWanted = iTotalStrikeDamageWanted * iOptionalOverkillFactor end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering targeting oEnemyUnit='..(oEnemyUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyUnit)..'; oEnemyUnit[refiStrikeDamageAssigned]='..(oEnemyUnit[refiStrikeDamageAssigned] or 'nil')..'; iTotalStrikeDamageWanted='..iTotalStrikeDamageWanted)..'; Can see unit='..tostring(AiBotUnitInfo.CanSeeUnit(aiBrain, oEnemyUnit))) end
                bAlreadyRecorded = false
                if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoActiveBomberTargets]) == false then
                    for iRecorded, oRecorded in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoActiveBomberTargets] do
                        if oRecorded == oEnemyUnit then bAlreadyRecorded = true break end
                    end
                end
                bBlockingShoreline = false
                if bTorpBombers and (oEnemyUnit[refiStrikeDamageAssigned] or 0) < iTotalStrikeDamageWanted * 1.5 then
                    --Based on basic sandbox test torps looked like most of them dropped their bombs around 12 short of the cruiser (a few were less than 12, and a very small % were a bit more than 12)
                    iAngleToRally = AiBotUtilities.GetAngleFromAToB(oEnemyUnit:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
                    local tLikelyDropPoint = AiBotUtilities.MoveInDirection(oEnemyUnit:GetPosition(), iAngleToRally, 12)
                    if tLikelyDropPoint and GetTerrainHeight(tLikelyDropPoint[1], tLikelyDropPoint[3]) >= AiBotMap.iMapWaterHeight then
                        bBlockingShoreline = true
                        iTotalStrikeDamageWanted = iTotalStrikeDamageWanted * 1.5 --some shots may hit shore
                    end
                    if bDebugMessages == true then AiBotUtilities.DrawLocation(tLikelyDropPoint) end
                end
                if not(bAlreadyRecorded) then table.insert(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftoActiveBomberTargets], oEnemyUnit) end
                while (oEnemyUnit[refiStrikeDamageAssigned] or 0) < iTotalStrikeDamageWanted do
                    iCurLoopCount = iCurLoopCount + 1
                    if iCurLoopCount > iMaxLoopCount then AiBotUtilities.ErrorHandler('Potential infinite loop unless have '..iMaxLoopCount..' plus torp bombers') break end
                    iClosestUnitDist = 100000
                    for iTorp, oTorp in tAvailableBombers do
                        iCurDist = GetRoughDistanceBetweenPositions(tBasePosition, oTorp:GetPosition())
                        if iCurDist < iClosestUnitDist then
                            iClosestUnitDist = iCurDist
                            oClosestUnit = oTorp
                            iClosestTorpRef = iTorp
                        end
                    end
                    if oClosestUnit and not(oClosestUnit.Dead) then

                        if bBlockingShoreline then
                            --Move until very close (assuming we are coming from the rally point or similar angle)
                            --Tried with >=20 dist and some of the shots would hit the shore; with 18 they seemed ok, same for 17, so will do 17
                            if iClosestUnitDist >= 17 and AiBotUtilities.GetAngleDifference(iAngleToRally, AiBotUtilities.GetAngleFromAToB(oClosestUnit:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])) <= 80 then
                                AiBotOrders.IssueTrackedMove(oClosestUnit, oEnemyUnit:GetPosition(), 2, false, 'TrpBchBl', false)
                            else
                                AiBotOrders.IssueTrackedAttack(oClosestUnit, oEnemyUnit, false, 'ATrp', bIgnoreMicro)
                            end
                        else
                            --Attack if we already have an attack order on this unit, or we ahve visibility of it - decided ot comment out as had added  to try and avoid a bug with units not targeting but it was caused by somethign else, left commented out in case want to reintroduce at a later point
                            bIssueAttackUnitOrder = not(bForceGroundFire)
                            --if bIssueAttackUnitOrder then bIssueAttackUnitOrder = AiBotUnitInfo.CanSeeUnit(aiBrain, oEnemyUnit) end

                            if bIssueAttackUnitOrder then
                                AiBotOrders.IssueTrackedAttack(oClosestUnit, oEnemyUnit, false, 'ATrp', bIgnoreMicro)
                            else
                                --Bomber - use attackground; torp bomber - use attackmove
                                if EntityCategoryContains(AiBotUnitInfo.refCategoryTorpBomber, oClosestUnit.UnitId) then
                                    AiBotOrders.IssueTrackedAggressiveMove(oClosestUnit, oEnemyUnit:GetPosition(), 6, false, 'AMTrp', bIgnoreMicro)
                                else
                                    --Bomber - ground fire
                                    --IssueTrackedGroundAttack(oUnit,      tOrderPosition,         iDistanceToReissueOrder, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder, oOptionalLinkedUnitTarget)
                                    AiBotOrders.IssueTrackedGroundAttack(oClosestUnit, oEnemyUnit:GetPosition(), 1,                       false,              'ABGrn',            bIgnoreMicro,                   oEnemyUnit)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Issued ground attack for oEnemyUnit='..oEnemyUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyUnit)..' at position '..repru(oEnemyUnit:GetPosition())) end
                                end
                            end
                        end
                        AddAssignedAttacker(oEnemyUnit, oClosestUnit) --Must do this after sending the order or else will be cleared
                        if bDebugMessages == true then LOG(sFunctionRef..': Will tell oClosestUnit='..oClosestUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestUnit)..' with distance '..iClosestUnitDist..' to attack enemy oEnemyUnit='..oEnemyUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyUnit)..', strike damage of torp bomber='..oClosestUnit[AiBotUnitInfo.refiStrikeDamage]..'; assigned strike damage after including this='..oEnemyUnit[refiStrikeDamageAssigned]..'; bIssueAttackUnitOrder='..tostring(bIssueAttackUnitOrder or false)..'; oClosestUnit last order reprs='..reprs(oClosestUnit[AiBotOrders.reftiLastOrders])..'; target cur layer='..reprs(oEnemyUnit:GetCurrentLayer())..'; Will also remove unit from table of available bombers, iClosestTorpRef='..iClosestTorpRef) end
                    end
                    if iClosestTorpRef then
                        table.remove(tAvailableBombers, iClosestTorpRef)
                    else
                        if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
                            AiBotUtilities.ErrorHandler('Failed to get a valid friendly unit despite table not being empty')
                            if bDebugMessages == true then
                                for iTorp, oTorp in tAvailableBombers do
                                    iCurDist = GetRoughDistanceBetweenPositions(tBasePosition, oTorp:GetPosition())
                                    LOG(sFunctionRef..': oTorp='..oTorp.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTorp)..'; iCurDist='..iCurDist..'; iClosestUnitDist='..iClosestUnitDist)
                                    if iCurDist < iClosestUnitDist then
                                        iClosestUnitDist = iCurDist
                                        oClosestUnit = oTorp
                                        iClosestTorpRef = iTorp
                                    end
                                end
                            end
                            break
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is tAvailableBombers empty after removal of the last entry='..tostring(AiBotUtilities.IsTableEmpty(tAvailableBombers))) end
                    if AiBotUtilities.IsTableEmpty(tAvailableBombers) then break end
                end
            end
            if AiBotUtilities.IsTableEmpty(tAvailableBombers) then break end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': end of code, is table of available bomers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableBombers))) end
end

function GetUnitNearestEnemyBase(tUnitsToConsider, iTeam, tOptionalEnemyBaseOverride)
    --e.g. used to get the front gunship - will use straight line distance so best used for air units
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetUnitNearestEnemyBase'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iCurPlateauOrZero, iCurLZOrWZ
    local iClosestDist = 100000
    local oClosestUnit
    local iCurDist
    for iUnit, oUnit in tUnitsToConsider do
        if not(oClosestUnit) then oClosestUnit = oUnit end --backup incase fail to find a unit with below approach
        if tOptionalEnemyBaseOverride then
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tOptionalEnemyBaseOverride)
            if iCurDist < iClosestDist then
                iClosestDist = iCurDist
                oClosestUnit = oUnit
            end
        else

            --Get land/water zone, and get nearest enemy base from this
            iCurPlateauOrZero, iCurLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
            --[[if (iCurPlateauOrZero or 0) > 0 then
        if (iCurLZOrWZ or 0) == 0 then
            iCurLZOrWZ = AiBotMap.GetWaterZoneFromPosition(oUnit:GetPosition())
            if (iCurLZOrWZ or 0) > 0 then
                iCurPlateauOrZero = 0
            end
        end
    end--]]
            if (iCurLZOrWZ or 0) > 0 then
                local tLZOrWZTeamData
                if (iCurPlateauOrZero or 0) == 0 then
                    tLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurLZOrWZ]][AiBotMap.subrefPondWaterZones][iCurLZOrWZ][AiBotMap.subrefWZTeamData][iTeam]
                else
                    tLZOrWZTeamData = AiBotMap.tAllPlateaus[iCurPlateauOrZero][AiBotMap.subrefPlateauLandZones][iCurLZOrWZ][AiBotMap.subrefLZTeamData][iTeam]
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Checking unit distance, iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurLZOrWZ='..(iCurLZOrWZ or 'nil')..' for oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; iCurLZOrWZ='..(iCurLZOrWZ or 'nil')..'; iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase]='..repru(tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])) end

                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(),  tLZOrWZTeamData[AiBotMap.reftClosestEnemyBase])
                if iCurDist < iClosestDist then
                    iClosestDist = iCurDist
                    oClosestUnit = oUnit
                end
            end
        end
    end
    return oClosestUnit
end

function GetGunshipsToMoveToTarget(tAvailableGunships, tTarget, oOptionalTarget)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetGunshipsToMoveToTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iGunshipMoveTolerance = 3 --If last move target was within 2.5 of current move target then wont move
    --Dist adjust - note this is a square, so e.g. if typical gunship range is 20+, then if are at +15x +15z from this, means will be 21 away, i.e. dont want to go further than +/- 15
    --[[local tDistanceAdjustXZ = {{0,0},{-5,-5},{5,5},{-5,5},{5,-5},{0,-5},{0,5},{-5,0},{5,0},
{-10,-10},{10,10},{-10,10},{10,-10},{0,-10},{0,10},{-10,0},{10,0},
{-15,-15},{15,15},{-15,15},{15,-15},{0,-15},{0,15},{-15,0},{15,0},
{-20,-20},{20,20},{-20,20},{20,-20},{0,-20},{0,20},{-20,0},{20,0}}--]]
    if AiBotUtilities.IsTableEmpty(tDistanceAdjustXZ) then
        table.insert(tDistanceAdjustXZ, {0,0})
        local iAdjustInterval = 6 --At 6.5 sometimes gunships on the outer edges dont have targets
        local iMinGunshipRange = 20
        local iMaxCycles = math.max(math.floor(iMinGunshipRange / iAdjustInterval), 1)
        local iAdjustBase
        local iCornerAdjust
        for iCurCycle = 1, iMaxCycles, 1 do
            --Want to record as ever expanding hollow boxes
            iAdjustBase = iCurCycle * iAdjustInterval
            --First go along the top and bottom of the box; exclude corners if at the last entry
            if iCurCycle < iMaxCycles then iCornerAdjust = 0 else iCornerAdjust = iAdjustInterval end
            for iCurX = - iAdjustBase + iCornerAdjust, iAdjustBase - iCornerAdjust, iAdjustInterval do
                for iCurZ = - iAdjustBase, iAdjustBase, iAdjustBase * 2 do
                    table.insert(tDistanceAdjustXZ, {iCurX, iCurZ})
                end
            end
            --Then do the left and right columns/sides of the box (excl corners which ahve already done per the above)
            for iCurX = - iAdjustBase, iAdjustBase, iAdjustBase * 2 do
                for iCurZ = -iAdjustBase + iAdjustInterval, iAdjustBase - iAdjustInterval, iAdjustInterval do
                    table.insert(tDistanceAdjustXZ, {iCurX, iCurZ})
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': tDistanceAdjustXZ after update has '..table.getn(tDistanceAdjustXZ)..' entries, repru='..repru(tDistanceAdjustXZ)) end
        end
    end
    --Find the first placement that we dont have assigned
    local tiValidPlacements = {}
    local iTotalUnits = table.getn(tAvailableGunships)
    for iUnit, oUnit in tAvailableGunships do
        if bDebugMessages == true then LOG(sFunctionRef..': Working out what gunships already have placements, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Placement='..(oUnit[refiGunshipPlacement] or 'nil')..'; Is easy brain='..tostring(oUnit[AiBotUnitInfo.refbEasyBrain] or false)) end
        if oUnit[refiGunshipPlacement] then
            if tiValidPlacements[oUnit[refiGunshipPlacement]] then
                --Duplicate entry so need to clear this unit
                oUnit[refiGunshipPlacement] = 10000
            else
                tiValidPlacements[oUnit[refiGunshipPlacement]] = true
            end
        end
    end
    local iFirstMissingPlacement
    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code at time '..GetGameTimeSeconds()..'; iTotalUnits='..iTotalUnits) end
    for iCurPlacement = 1, iTotalUnits do
        if not(tiValidPlacements[iCurPlacement]) then
            iFirstMissingPlacement = iCurPlacement
            if bDebugMessages == true then LOG(sFunctionRef..': First missing placement='..iCurPlacement) end
            break
        end
    end

    local tAdjustedMovePosition
    local iCurPlacement
    local iPlacementSize = table.getn(tDistanceAdjustXZ)
    local iEasyGunships = 0
    if iFirstMissingPlacement then
        local toUnitsToPlace = {}
        for iUnit, oUnit in tAvailableGunships do
            if bDebugMessages == true then LOG(sFunctionRef..': Considering gunship'..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; its placement is '..(oUnit[refiGunshipPlacement] or 'nil')..'; Is easy='..tostring(oUnit[AiBotUnitInfo.refbEasyBrain] or false)..'; iFirstMissingPlacement='..iFirstMissingPlacement) end
            if (oUnit[refiGunshipPlacement] or 10000) >= iFirstMissingPlacement then
                if oUnit[AiBotUnitInfo.refbEasyBrain] then
                    --Just attackmove to the target
                    AiBotOrders.IssueTrackedAggressiveMove(oUnit, tTarget, 4, false, 'GSEsyA', false)
                    iEasyGunships = iEasyGunships + 1
                else
                    if bDebugMessages == true then LOG(sFunctionRef..': Gunship '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' has placement '..(oUnit[refiGunshipPlacement] or 'nil')..' so will add to table of units needing new placements') end
                    table.insert(toUnitsToPlace, oUnit)
                end
            end
        end

        local iClosestDist
        local iCurDist
        local iClosestUnitRef
        if iEasyGunships == 0 or iFirstMissingPlacement <= iTotalUnits - iEasyGunships then
            for iBasePlacement = iFirstMissingPlacement, iTotalUnits - iEasyGunships do
                --Adjust placement value to reflect we have only defined a limited number of options
                if AiBotUtilities.IsTableEmpty(toUnitsToPlace) then break end --redundancy
                iCurPlacement = iBasePlacement
                if bDebugMessages == true then LOG(sFunctionRef..': iCurPlacement='..iCurPlacement..'; iPlacementSize='..iPlacementSize..'; will reduce cur placement if it exceeds the size') end
                while iCurPlacement  > iPlacementSize do
                    iCurPlacement = iCurPlacement - iPlacementSize
                end
                --Identify which gunship is closest to each placement point
                tAdjustedMovePosition = {tTarget[1] + tDistanceAdjustXZ[iCurPlacement][1], tTarget[2], tTarget[3] + tDistanceAdjustXZ[iCurPlacement][2]}
                iClosestDist = 10000
                iClosestUnitRef = nil
                for iUnit, oUnit in toUnitsToPlace do
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tAdjustedMovePosition)
                    if iCurDist < iClosestDist then
                        iClosestDist = iCurDist
                        iClosestUnitRef = iUnit
                    end
                end
                --Assign this position to this gunship
                toUnitsToPlace[iClosestUnitRef][refiGunshipPlacement] = iBasePlacement
                if bDebugMessages == true then LOG(sFunctionRef..': Assigning gunship '..toUnitsToPlace[iClosestUnitRef].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(toUnitsToPlace[iClosestUnitRef])..' to base placement '..iBasePlacement) end
                table.remove(toUnitsToPlace, iClosestUnitRef)
            end
        end
    end

    --Issue move orders
    local toUnitsByBasePlacementRef = {}
    for iUnit, oUnit in tAvailableGunships do
        oUnit[reftGunshipSpecialRallyPathing] = nil
        if oUnit[refiGunshipPlacement] then
            toUnitsByBasePlacementRef[oUnit[refiGunshipPlacement]] = oUnit
            if bDebugMessages == true then LOG(sFunctionRef..': Recording unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' with gunship placement '..(oUnit[refiGunshipPlacement] or 'nil')..' in table toUnitsByBasePlacementRef') end
        end
    end

    local bConsiderAttackIfCloseToTarget
    if oOptionalTarget and (AiBotUtilities.bLoudModActive or AiBotUtilities.bSteamActive) then --(QUIET meant to have fixed LOUD's issues with gunships not being able to fire at nearby units); Steam has issues similar to loud where gunsihps may not fire if not facing target
        bConsiderAttackIfCloseToTarget = true
    end

    function MoveIndividualGunship(oClosestUnit, tUnitDestination)
        --Experimental gunship doesnt attack properly when just given a move order
        if bDebugMessages == true then LOG(sFunctionRef..': Are we dealing with an experimental='..tostring( EntityCategoryContains(categories.EXPERIMENTAL, oClosestUnit.UnitId))..'; Dist to unit destination='..AiBotUtilities.GetDistanceBetweenPositions(oClosestUnit:GetPosition(), tUnitDestination)..'; Is oOptionalTarget valid='..tostring(AiBotUnitInfo.IsUnitValid(oOptionalTarget))..'; oOptionalTarget='..(oOptionalTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oOptionalTarget) or 'nil')..'; Is this a czar='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryCzar, oClosestUnit.UnitId))) end
        if EntityCategoryContains(categories.EXPERIMENTAL, oClosestUnit.UnitId) and AiBotUtilities.GetDistanceBetweenPositions(oClosestUnit:GetPosition(), tUnitDestination) <= 20 then
            if oOptionalTarget and (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) then --Had issue where czar stops attacking despite being on attackmove') end
                --Do manual attack to be safe due to risk czar doesnt fire at all (had mixed results)
                AiBotOrders.IssueTrackedAttack(oClosestUnit, oOptionalTarget, false, 'LoudExA', false)
            else
                if bDebugMessages == true then LOG(sFunctionRef..'; Will just do attackmove to the traget instead') end
                AiBotOrders.IssueTrackedAggressiveMove(oClosestUnit, tUnitDestination, math.max(15, iGunshipMoveTolerance), false, 'GSExA', false)
            end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': bConsiderAttackIfCloseToTarget='..tostring(bConsiderAttackIfCloseToTarget)..'; Time since last f ired='..GetGameTimeSeconds() - (oClosestUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0)..'; oClosestUnit[AiBotUnitInfo.refiTimeBetweenDFShots]='..(oClosestUnit[AiBotUnitInfo.refiTimeBetweenDFShots] or 'nil')) end
            if bConsiderAttackIfCloseToTarget and (oClosestUnit[refoGunshipAttackOrderTarget] == oOptionalTarget or AiBotUtilities.GetDistanceBetweenPositions(oClosestUnit:GetPosition(), oOptionalTarget:GetPosition()) < (oClosestUnit[AiBotUnitInfo.refiDFRange] or 0)) then
                AiBotOrders.IssueTrackedAggressiveMove(oClosestUnit, tUnitDestination, iGunshipMoveTolerance, false, 'GSLdAtc', false)
                oClosestUnit[refoGunshipAttackOrderTarget] = oOptionalTarget
            else
                AiBotOrders.IssueTrackedMove(oClosestUnit, tUnitDestination, iGunshipMoveTolerance, false, 'GSAtc', false)
                if bConsiderAttackIfCloseToTarget then oClosestUnit[refoGunshipAttackOrderTarget] = nil end
            end
        end
    end

    if iEasyGunships== 0 or iTotalUnits > iEasyGunships then
        for iBasePlacement = 1, iTotalUnits - iEasyGunships do
            iCurPlacement = iBasePlacement
            while iCurPlacement  > iPlacementSize do
                iCurPlacement = iCurPlacement - iPlacementSize
            end

            tAdjustedMovePosition = {tTarget[1] + tDistanceAdjustXZ[iCurPlacement][1], tTarget[2], tTarget[3] + tDistanceAdjustXZ[iCurPlacement][2]}
            tAdjustedMovePosition[2] = GetSurfaceHeight(tAdjustedMovePosition[1], tAdjustedMovePosition[3])
            if bDebugMessages == true then LOG(sFunctionRef..': iBasePlacement='..iBasePlacement..'; Is the entry in UnitsByPlacementRef nil for this='..tostring(not(toUnitsByBasePlacementRef[iBasePlacement]))) end
            if not(toUnitsByBasePlacementRef[iBasePlacement]) then
                AiBotUtilities.ErrorHandler('Missing gunship for iBasePlacement='..iBasePlacement..'; iEasyGunships='..(iEasyGunships or 'nil')..'; iTotalUnits='..iTotalUnits)
            else
                MoveIndividualGunship(toUnitsByBasePlacementRef[iBasePlacement], tAdjustedMovePosition)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageGunships(iTeam, iAirSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageGunships'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tAvailableGunships, tGunshipsForRefueling, tUnavailableUnits = GetAvailableLowFuelAndInUseAirUnits(iTeam, iAirSubteam, AiBotUnitInfo.refCategoryGunship + AiBotUnitInfo.refCategoryCzar + AiBotUnitInfo.refCategoryTransport * categories.EXPERIMENTAL + AiBotUnitInfo.refCategoryAAGunship, nil, not(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets])))
    local tGunshipsToRetreatNotRefuel --If want to retreat a gunship but we dont want to send it for refueling, include here
    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code, time='..GetGameTimeSeconds()..'; Is tAvailableGunships empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableGunships))..'; Is table of active snipe targets empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]))) end
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat] = AiBotUnitInfo.GetAirThreatLevel(tAvailableGunships, false, false, false, true, false, false) + AiBotUnitInfo.GetAirThreatLevel(tGunshipsForRefueling, false, false, false, true, false, false) + AiBotUnitInfo.GetAirThreatLevel(tUnavailableUnits, false, false, false, true, false, false)

    local iCloseToFrontThreshold = 50
    local iEnemyAirAAThreatNearGunship
    local bHaveClearAirControl = false
    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
        --For factories we use a higher threshold than gunships; i.e. gunships we just want to reduce the risk we are aggressive, they attack with air, and we realise we lack air control and run and lose everything
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiAirControlFactor] + 0.15) < AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] then
            bHaveClearAirControl = true
        end
    end

    --Set a default value as a basic backup
    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then iEnemyAirAAThreatNearGunship = 0 else iEnemyAirAAThreatNearGunship = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] end
    local iEnemyGroundAAThreatByGunship = 0
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiOurGunshipAAThreat] = 0
    local tTeleportTargetToMoveTo --used if we want to preemptively move to an enemy teleport target location
    if bDebugMessages == true then LOG(sFunctionRef..': Is front gunship valid='..tostring(AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]))) end
    local tGunshipLandOrWaterZoneData, tGunshipLandOrWaterZoneTeamData, iGunshipPlateauOrZero, iGunshipLandOrWaterZone
    if AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]) then
        --If we go from the rally point to the last front gunship, do we come across any zones with a large ground threat? if so then want to try an alt rally point
        iGunshipPlateauOrZero, iGunshipLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition())
        if iGunshipPlateauOrZero and (iGunshipLandOrWaterZone or 0) > 0 then
            --Ignore this logic if significant AA threat in the gunship current zone

            if iGunshipPlateauOrZero == 0 then
                --iGunshipLandOrWaterZone = AiBotMap.GetWaterZoneFromPosition(oFrontGunship:GetPosition())
                tGunshipLandOrWaterZoneData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iGunshipLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iGunshipLandOrWaterZone]
                tGunshipLandOrWaterZoneTeamData = tGunshipLandOrWaterZoneData[AiBotMap.subrefWZTeamData][iTeam]
                iEnemyGroundAAThreatByGunship = (tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)
                iEnemyAirAAThreatNearGunship = (tGunshipLandOrWaterZoneTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)
            else
                tGunshipLandOrWaterZoneData = AiBotMap.tAllPlateaus[iGunshipPlateauOrZero][AiBotMap.subrefPlateauLandZones][iGunshipLandOrWaterZone]
                tGunshipLandOrWaterZoneTeamData = tGunshipLandOrWaterZoneData[AiBotMap.subrefLZTeamData][iTeam]
                iEnemyGroundAAThreatByGunship = (tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)
                iEnemyAirAAThreatNearGunship = (tGunshipLandOrWaterZoneTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)
            end
            --NOTE: This is used for deciding whether we do the calculations of via points, and for some of the higher priority gunship logic before the main code (where a more precise check is done) - for the more detailed check, look for the log with the text "About to check if shoudl run due to high AA near where gunships are"
            --Also include adjacent zones
            RecordOtherLandAndWaterZonesByDistance(tGunshipLandOrWaterZoneData)
            if AiBotUtilities.IsTableEmpty(tGunshipLandOrWaterZoneData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                local iSearchDistance = 100
                if bHaveClearAirControl then iSearchDistance = 80
                elseif AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then iSearchDistance = 90 end
                if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat] >= 25000 then
                    iSearchDistance = iSearchDistance + math.min(80, (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat] - 25000) / 1000)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iEnemyAirAAThreatNearGunship before considering nearby zones and getunitsaroundpoint='..iEnemyAirAAThreatNearGunship..'; iSearchDistance='..iSearchDistance) end
                for iEntry, tSubtable in tGunshipLandOrWaterZoneData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                    if tSubtable[AiBotMap.subrefiDistance] <= iSearchDistance then
                        local tOtherZoneData, tOtherTeamData
                        if tSubtable[AiBotMap.subrefbIsWaterZone] then
                            tOtherZoneData = AiBotMap.tPondDetails[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                            tOtherTeamData = tOtherZoneData[AiBotMap.subrefWZTeamData][iTeam]
                        else
                            tOtherZoneData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                            tOtherTeamData = tOtherZoneData[AiBotMap.subrefLZTeamData][iTeam]
                        end
                        if (tOtherTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) > 0 then
                            iEnemyAirAAThreatNearGunship = iEnemyAirAAThreatNearGunship + 0.5 * tOtherTeamData[AiBotMap.refiEnemyAirAAThreat]
                        end
                    else
                        break
                    end
                end
            end
            local tNearbyEnemyAirAA
            if AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] or 0) > 0 then
                local oFirstAiBotBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                if oFirstAiBotBrain then
                    tNearbyEnemyAirAA = AiBotTeam.GetFirstActiveAiBotBrain(iTeam):GetUnitsAroundPoint(AiBotUnitInfo.refCategoryAirAA + AiBotUnitInfo.refCategoryCzar + AiBotUnitInfo.refCategoryRestorer, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship]:GetPosition(), 70, 'Enemy')

                    if AiBotUtilities.IsTableEmpty(tNearbyEnemyAirAA) == false then
                        if bDebugMessages == true then LOG(sFunctionRef..': iEnemyAirAAThreatNearGunship before getunitsaroundpoint='..iEnemyAirAAThreatNearGunship..'; Threat from getunitsaroundpoint='..AiBotUnitInfo.GetAirThreatLevel(tNearbyEnemyAirAA, true, true, false, false, false, false)) end
                        iEnemyAirAAThreatNearGunship = math.max(iEnemyAirAAThreatNearGunship, AiBotUnitInfo.GetAirThreatLevel(tNearbyEnemyAirAA, true, true, false, false, false, false))
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': iEnemyGroundAAThreatByGunship='..iEnemyGroundAAThreatByGunship..'; Gunship threat='..AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat]..'; iEnemyAirAAThreatNearGunship='..iEnemyAirAAThreatNearGunship) end

        end
    end

    local oFrontGunship
    local bGunshipWantsAirScout = false
    if bDebugMessages == true then LOG(sFunctionRef..': About to move onto main gunship logic if have any available, is table of available gunships empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableGunships))) end
    if AiBotUtilities.IsTableEmpty(tAvailableGunships) == false then
        local tiPlateauAndZoneForEnemiesToBeIn = {} --if dont have priority targets, then will use this to focus on higher value targets (e.g. to try and reduce cases where 100 t3 gunships will move halfway across the map for 1 MAA)
        --Prioroity targets to attack - search for enemies around start positions (ignore AA):
        local tEnemyGroundOrGunshipTargets = {}
        --Get the gunship nearest to an enemy base and record this as the front gunship
        local tOptionalEnemyBaseOverride
        if AiBotMap.bIsCampaignMap and AiBotTeam.GetFirstActiveAiBotBrain(iTeam).CampaignAI then
            --Get the nearest zone with significant enemy structure threat inside the playable area, if there is such a zone
            tOptionalEnemyBaseOverride = AiBotTeam.GetEnemyMainCampaignBase(iTeam)
        end
        oFrontGunship = GetUnitNearestEnemyBase(tAvailableGunships, iTeam, tOptionalEnemyBaseOverride)
        --Adjustment - consider changing front gunship if previous front gunship is valid and is far away but with significantly more gunships near it (unless its an experimental)
        local iAvailableGunshipCount = table.getn(tAvailableGunships)
        if iAvailableGunshipCount >= 5 and AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftFrontGunshipPosition]) == false and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship] == oFrontGunship) and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurGunshipThreat] >= 2500 and not(EntityCategoryContains(categories.EXPERIMENTAL, oFrontGunship.UnitId)) and AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftFrontGunshipPosition], oFrontGunship:GetPosition()) >= 60 then
            local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
            local tGunshipsNearNewFrontGunship = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryGunship, oFrontGunship:GetPosition(), 50, 'Ally')
            local tGunshipNearOldFrontGunship = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryGunship, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftFrontGunshipPosition], 50, 'Ally')
            if bDebugMessages == true then LOG(sFunctionRef..': Considering if should change front gunship, front gunship before='..oFrontGunship.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFrontGunship)..'; Size of gunships near old front gunship='..table.getn(tGunshipNearOldFrontGunship)..'; Size of gunships near new front gunship='..table.getn(tGunshipsNearNewFrontGunship)..'; Front gunship position='..repru(oFrontGunship:GetPosition())..'; Old position='..repru(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftFrontGunshipPosition])..'; Distance between them='..AiBotUtilities.GetDistanceBetweenPositions(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftFrontGunshipPosition], oFrontGunship:GetPosition())) end
            if tGunshipNearOldFrontGunship and table.getn(tGunshipNearOldFrontGunship) > 2.5 * table.getn(tGunshipsNearNewFrontGunship) then
                --Get closest gunship to the old front gunship
                local iCurDist
                local iClosestToFrontDist = 10000
                local tOldGunshipPosition = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftFrontGunshipPosition]
                for iUnit, oUnit in tGunshipNearOldFrontGunship do
                    if oUnit:GetAIBrain().AiBotAirSubteam == iAirSubteam and oUnit[refiGunshipPlacement] < 10000 then
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tOldGunshipPosition)
                        if bDebugMessages == true then LOG(sFunctionRef..': Searching for closest unit to old gunship position, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurDist='..iCurDist..'; iClosestToFrontDist='..iClosestToFrontDist..'; Gunship placement number='..(oUnit[refiGunshipPlacement] or 'nil')) end
                        if iCurDist < iClosestToFrontDist then
                            oFrontGunship = oUnit
                            iClosestToFrontDist = iCurDist
                            if iClosestToFrontDist < 1 then break end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': oFrontGunship after check='..oFrontGunship.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFrontGunship)) end
            end
        end
        AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftFrontGunshipPosition] = {oFrontGunship:GetPosition()[1], oFrontGunship:GetPosition()[2], oFrontGunship:GetPosition()[3]}


        --Cloaked nearby enemy ACU - want gunship to be a priority
        if AiBotUnitInfo.IsUnitValid(oFrontGunship) and AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCloakedEnemyUnits]) then

            local iCloakedUnits = table.getn(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCloakedEnemyUnits])

            for iCurEntry = iCloakedUnits, 1, -1 do
                if not(bGunshipWantsAirScout) and AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), AiBotTeam.tTeamData[iTeam][AiBotTeam.reftCloakedEnemyUnits][iCurEntry]:GetPosition()) <= 200 then
                    bGunshipWantsAirScout = true
                    break
                end
            end
        end


        local tGunshipsNearFront = {}
        local tGunshipsNotNearFront = {}
        local bHaveGunshipsVeryFarFromFront = false
        local iCurDist

        for iUnit, oUnit in tAvailableGunships do
            if bDebugMessages == true then LOG(sFunctionRef..': Considering how close unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is to front gunship '..oFrontGunship.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFrontGunship)..'; Dist='..AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), oUnit:GetPosition())..'; Threat of unit='..AiBotUnitInfo.GetAirThreatLevel({ oUnit}, false, false, false, true, false, false)) end
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), oUnit:GetPosition())
            if iCurDist <= iCloseToFrontThreshold then
                table.insert(tGunshipsNearFront, oUnit)
            else
                table.insert(tGunshipsNotNearFront, oUnit)
                if iCurDist >= 120 then bHaveGunshipsVeryFarFromFront = true end
            end
            --Track available gunship health
            if EntityCategoryContains(categories.TECH3, oUnit.UnitId) then
                oUnit[AiBotUnitInfo.refiHealthSecondLastCheck] = oUnit[AiBotUnitInfo.refiHealthWhenLastChecked]
                oUnit[AiBotUnitInfo.refiHealthWhenLastChecked] = oUnit:GetHealth()
            end
        end
        local iOurGunshipThreat = AiBotUnitInfo.GetAirThreatLevel(tGunshipsNearFront, false, false, false, true, false, false)

        --GetAirThreatLevel(tUnits, bEnemyUnits, bIncludeAirToAir, bIncludeGroundToAir, bIncludeAirToGround, bIncludeNonCombatAir, bIncludeAirTorpedo, bBlueprintThreat)
        AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiOurGunshipAAThreat] = AiBotUnitInfo.GetAirThreatLevel(tAvailableGunships, false,  true,               false,              false, false, false)
        local iOurGunshipAA = math.max(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refiOurGunshipAAThreat] * 0.25, AiBotUnitInfo.GetAirThreatLevel(tGunshipsNearFront, false, true, false, false, false, false))
        --Reduce AA for larger values, as e.g. czars and restorers with threat of 130k per above got wiped out by asf force with threat of 120k
        if iOurGunshipAA >= 25000 then
            iOurGunshipAA = 20000 + (iOurGunshipAA - 25000) * 0.6
        end

        local bHaveT3Gunships = false
        if iOurGunshipThreat >= 2000 then
            if EntityCategoryContains(categories.TECH3 + categories.EXPERIMENTAL, tAvailableGunships[1].UnitId) then bHaveT3Gunships = true
            elseif AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.TECH3 + categories.EXPERIMENTAL, tAvailableGunships)) == false then
                bHaveT3Gunships = true
            end
        end

        if not(tGunshipLandOrWaterZoneData) then
            iGunshipPlateauOrZero, iGunshipLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oFrontGunship:GetPosition())
            if iGunshipPlateauOrZero == 0 then
                --iGunshipLandOrWaterZone = AiBotMap.GetWaterZoneFromPosition(oFrontGunship:GetPosition())
                tGunshipLandOrWaterZoneData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iGunshipLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iGunshipLandOrWaterZone]
                tGunshipLandOrWaterZoneTeamData = tGunshipLandOrWaterZoneData[AiBotMap.subrefWZTeamData][iTeam]
                if bDebugMessages == true then LOG(sFunctionRef..': Have a water zone, iGunshipLandOrWaterZone='..(iGunshipLandOrWaterZone or 'nil')) end
            else
                tGunshipLandOrWaterZoneData = AiBotMap.tAllPlateaus[iGunshipPlateauOrZero][AiBotMap.subrefPlateauLandZones][iGunshipLandOrWaterZone]
                tGunshipLandOrWaterZoneTeamData = tGunshipLandOrWaterZoneData[AiBotMap.subrefLZTeamData][iTeam]
            end
        end
        if bDebugMessages == true then
            LOG(sFunctionRef..': oFrontGunship='..oFrontGunship.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFrontGunship)..'; Position='..repru(oFrontGunship:GetPosition())..'; iGunshipPlateauOrZero='..(iGunshipPlateauOrZero or 'nil')..'; iGunshipLandOrWaterZone='..(iGunshipLandOrWaterZone or 'nil')..'; WZ from position='..(AiBotMap.GetWaterZoneFromPosition(oFrontGunship:GetPosition()) or 'nil')..'; Is table of enemy experimentals empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals])))
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false then
                local iExperimentalPlateau, iExperimentalZone
                for iExperimental, oExperimental in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals] do
                    iExperimentalPlateau, iExperimentalZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oExperimental:GetPosition())
                    LOG(sFunctionRef..': Considering oExperimental '..oExperimental.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oExperimental)..' at position '..repru(oExperimental:GetPosition())..' and last recorded position '..repru(oExperimental[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])..'; iExperimentalPlateau='..(iExperimentalPlateau or 'nil')..'; iExperimentalZone='..(iExperimentalZone or 'nil'))

                end
            end
            local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
            tGunshipsNearFront = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryGunship, oFrontGunship:GetPosition(), 50, 'Ally')
            LOG(sFunctionRef..': Threat of gunships within 50 of front gunship='..AiBotUnitInfo.GetAirThreatLevel(tGunshipsNearFront, false, false, false, true, false, false)..'; iOurGunshipThreat='..iOurGunshipThreat)
        end

        local iMaxEnemyAirAA --Amount of enemy airaa threat required to make gunships to target enemies nearby
        local iDistToSupport = AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])
        local iOptionalHigherAirAAThresholdForHighValueZones
        if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]) and iDistToSupport <= 160 and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] then iOptionalHigherAirAAThresholdForHighValueZones = AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] end
        local bOnlyRunFromAirAAIfInRange = false
        --If our gunshipAA exceeds enemy total AirAA force
        if iOurGunshipAA > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] and iOurGunshipAA > 200 then
            bOnlyRunFromAirAAIfInRange = true
            if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then
                iMaxEnemyAirAA = math.max(iOurGunshipAA * 0.75, iOurGunshipThreat * 0.05)
                if bDebugMessages == true then LOG(sFunctionRef..': Far behind on air but our gunship AA threat is more than enemy AirAA threat, iMaxEnemyAirAA before adjustment='..iMaxEnemyAirAA) end
            else
                iMaxEnemyAirAA = math.max(iOurGunshipAA, iOurGunshipThreat * 0.05)
                if bDebugMessages == true then LOG(sFunctionRef..': Relying on gunship AA as it is greater than enemy AA, iMaxEnemyAirAA before adjustment='..iMaxEnemyAirAA) end
            end
        elseif AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then
            iMaxEnemyAirAA = math.min(2000, math.max(iOurGunshipAA * 0.2, iOurGunshipThreat * 0.03))
            if bDebugMessages == true then LOG(sFunctionRef..': Far behind on air, iMaxEnemyAirAA='..iMaxEnemyAirAA) end
        elseif iOurGunshipAA > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 0.75 and iOurGunshipAA + AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 0.9 then
            iMaxEnemyAirAA = math.max(iOurGunshipAA * 0.75, iOurGunshipThreat * 0.05)
            if bDebugMessages == true then LOG(sFunctionRef..': Not far behind on air and our gunship AA isnt that different from enemy AirAA threat, iMaxEnemyAirAA='..iMaxEnemyAirAA) end
        else
            --Is the air support location nearby?
            if bDebugMessages == true then LOG(sFunctionRef..': We arent far behind on air, but our gunship AA isnt enough to ignore enemy AA, iDistToSupport='..iDistToSupport) end
            if iDistToSupport <= 160 then
                if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                    bOnlyRunFromAirAAIfInRange = true
                    if bHaveClearAirControl then
                        iMaxEnemyAirAA = math.min(math.max(10000, iOurGunshipAA * 0.5), math.max(iOurGunshipThreat * 0.2, iOurGunshipAA * 0.7))
                    else
                        iMaxEnemyAirAA = math.min(math.max(9000, iOurGunshipAA * 0.45), math.max(iOurGunshipThreat * 0.175, iOurGunshipAA * 0.65))
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Close to air support and have air control, iMaxEnemyAirAA='..iMaxEnemyAirAA) end
                else
                    iMaxEnemyAirAA = math.min(math.max(8000, iOurGunshipAA * 0.4),  math.max(iOurGunshipThreat * 0.075, iOurGunshipAA * 0.6))
                    if iOurGunshipAA + AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] > 1.5 * AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] then
                        bOnlyRunFromAirAAIfInRange = true
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Close to air support but dont have air control, iMaxEnemyAirAA='..iMaxEnemyAirAA) end
                end
            else
                if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                    if bHaveClearAirControl then
                        iMaxEnemyAirAA = math.min(math.max(8000, iOurGunshipAA * 0.4),  math.max(iOurGunshipThreat * 0.075, iOurGunshipAA * 0.6))
                        if iOurGunshipAA * 0.7 > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] then
                            bOnlyRunFromAirAAIfInRange = true
                        end
                    else
                        iMaxEnemyAirAA = math.min(math.max(7000, iOurGunshipAA * 0.35),  math.max(iOurGunshipThreat * 0.065, iOurGunshipAA * 0.5))
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Far from air support but have air control, iMaxEnemyAirAA='..iMaxEnemyAirAA) end
                else
                    iMaxEnemyAirAA = math.min(math.max(5000, iOurGunshipAA * 0.2),  math.max(iOurGunshipThreat * 0.04, iOurGunshipAA * 0.4))
                    if bDebugMessages == true then LOG(sFunctionRef..': Far from air support and dont have air control, iMaxEnemyAirAA='..iMaxEnemyAirAA) end
                end
            end
        end
        if iOptionalHigherAirAAThresholdForHighValueZones and iOptionalHigherAirAAThresholdForHighValueZones < iMaxEnemyAirAA then iOptionalHigherAirAAThresholdForHighValueZones = iMaxEnemyAirAA end
        if AiBotMap.bIsCampaignMap then
            iMaxEnemyAirAA = math.max(iMaxEnemyAirAA, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] * 0.5, iOurGunshipAA * 0.8)
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDontHaveBuildingsOrACUInPlayableArea] then iMaxEnemyAirAA = 100000 end
        end

        --If are buildings in the gunship zone then increase threshold to run from enemy AA
        if (tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) > 0 then iMaxEnemyAirAA = math.max(iMaxEnemyAirAA, iOurGunshipThreat * 0.08) end

        local bDontLookForMoreTargets = false
        local bDontCheckForPacifism = not(AiBotOverseer.bPacifistModeActive)
        local tNewlyAddedEnemies

        local bConsiderAttackingEnemyGunships = false
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] >= 100 and iOurGunshipThreat >= 400 then
            --Consider if enemy has experimental gunships or we have a greater gunship threat than their air to ground threat
            if iOurGunshipThreat > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat] then
                bConsiderAttackingEnemyGunships = true
            elseif AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround]) == false and AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGunship * categories.CYBRAN * categories.EXPERIMENTAL, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround])) == false then
                bConsiderAttackingEnemyGunships = true
            end
        end


        if bDebugMessages == true then
            LOG(sFunctionRef..': About to look for targets for g unships, iMaxEnemyAirAA='..iMaxEnemyAirAA..'; iDistToSupport='..AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])..'; iOurGunshipThreat='..iOurGunshipThreat..'; HaveAirControl='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl])..'; Far behind on air='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir])..'; bConsiderAttackingEnemyGunships='..tostring(bConsiderAttackingEnemyGunships)..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirToGroundThreat]..'; Is table of enemy air to ground empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround]))..'; iOurGunshipAA='..iOurGunshipAA..'; subrefiOurAirAAThreat='..AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat]..'; Enemy team refiEnemyAirAAThreat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat])
            --List out any soulrippers
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround]) == false then
                local tEnemySoulrippers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGunship * categories.CYBRAN * categories.EXPERIMENTAL, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirToGround])
                if AiBotUtilities.IsTableEmpty(tEnemySoulrippers) == false then
                    for iUnit, oUnit in tEnemySoulrippers do
                        local iCurExpPlat, iCurExpZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                        LOG(sFunctionRef..': Enemy soulripper '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' reftAssignedPlateauAndLandZoneByTeam='..repru(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam])..'; WZ='..repru(oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam])..'; iCurExpPlat='..(iCurExpPlat or 'nil')..'; iCurExpZone='..(iCurExpZone or 'nil')..'; Soulripper airaa threat='..AiBotUnitInfo.GetAirThreatLevel({ oUnit }, true, true, true, false, false, false))
                    end
                end
            end
        end
        function AddUnitToTargetsTable(oUnit, bNotCheckedValid)
            if not(bNotCheckedValid) or (AiBotUnitInfo.IsUnitValid(oUnit) and not(oUnit:IsUnitState('Attached')) and not(AiBotUnitInfo.IsUnitUnderwater(oUnit))) then
                table.insert(tEnemyGroundOrGunshipTargets, oUnit)
                table.insert(tNewlyAddedEnemies, oUnit)
            end
        end
        local iZonesWithPotentialTargetsCount = 0
        local bHaveEnemyInCoreBase = false
        local bUseDefensively = false
        local iMinDistFromAAWantedIfAvoidingForMostUnits = 30 --we increase this later on for the AA range to avoid needing to keep adding the AA r ange; this is if we decide to not attakc everything in a zone, but just nearest enemies that lack groundAA coverage
        local bAreJustTargetingUnitsOutOfAARange = false --set to true if when choosing zone targets we decide to attack units that are vulnerable rather than focusing down AA
        function AddEnemyGroundUnitsToTargetsSubjectToAA(iPlateauOrZero, iLandOrWaterZone, iGunshipThreatFactorWanted, bCheckForAirAA, bOnlyIncludeIfMexToProtect, iGroundAAThresholdAdjust, bIgnoreMidpointPlayableCheck, bDetailedAACheckOverride)
            --Campaign specific-  check this is within the playable area first
            tNewlyAddedEnemies = {}
            local iSpecificAirAAThreatLimit
            if not(bCheckForAirAA) then iSpecificAirAAThreatLimit = -1
            else iSpecificAirAAThreatLimit = iMaxEnemyAirAA
            end
            local tLZOrWZData
            local tLZOrWZTeamData
            if iPlateauOrZero > 0 then
                --Land zone
                tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]

            else
                --Water zone
                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
            end

            --Think we already take into account gorundAA in the main function, so this is effectively doubling up, hence why modifiers arent too high
            if tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.25 then
                iSpecificAirAAThreatLimit = math.max(0, iSpecificAirAAThreatLimit - (tLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) * 3.5)
            elseif tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.4 then
                iSpecificAirAAThreatLimit = math.max(0, iSpecificAirAAThreatLimit - (tLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) * 1.5)
            elseif tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.55 then
                iSpecificAirAAThreatLimit = math.max(0, iSpecificAirAAThreatLimit - (tLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) * 0.5)
            end

            if bDebugMessages == true then LOG(sFunctionRef..': Is midpoint in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tLZOrWZData[AiBotMap.subrefMidpoint]))..'; bIgnoreMidpointPlayableCheck='..tostring(bIgnoreMidpointPlayableCheck or false)..'; tLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA]='..(tLZOrWZTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 'nil')..'; Adjacent to pacifist zone='..tostring((bDontCheckForPacifism or not(AiBotConditions.AdjacentToPacifistZone(iPlateauOrZero, iLandOrWaterZone))))..'; Dist from front gunship to midpoint='..AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], oFrontGunship:GetPosition())) end
            if not(AiBotMap.bIsCampaignMap) or ((bIgnoreMidpointPlayableCheck or (AiBotConditions.IsLocationInPlayableArea(tLZOrWZData[AiBotMap.subrefMidpoint]))) and (bDontCheckForPacifism or not(AiBotConditions.AdjacentToPacifistZone(iPlateauOrZero, iLandOrWaterZone)) or (not(AiBotConditions.IsZoneAPacifistZone(iPlateauOrZero, iLandOrWaterZone)) and AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], AiBotOverseer.tAveragePacifistLocation) >= math.max(175, AiBotUtilities.GetDistanceBetweenPositions(tLZOrWZData[AiBotMap.subrefMidpoint], oFrontGunship:GetPosition()) - 25)))) then
                function IsHighValueZoneToProtect()
                    if (tLZOrWZTeamData[AiBotMap.subrefLZSValue] or 0) >= 2000 or (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] or 0) > 0 or (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] or 0) > 0 then
                        return true
                    else
                        return false
                    end
                end
                if bDebugMessages == true then LOG('AddEnemyGroundUnitsToTargetsSubjectToAA: Deciding whether to add units for land zone '..iLandOrWaterZone..' plateau '..iPlateauOrZero..'; bOnlyIncludeIfMexToProtect='..tostring(bOnlyIncludeIfMexToProtect)..'; IsHighValueZoneToProtect='..tostring(IsHighValueZoneToProtect())..'; Enemy combat threat in zone if LZ='..(tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)..'; Mobile DF total if LZ='..(tLZOrWZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)..'; Enemy AA total if LZ='..(tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)..'; tLZOrWZTeamData[AiBotMap.refiModDistancePercent]='..tLZOrWZTeamData[AiBotMap.refiModDistancePercent]..'; bConsiderAttackingEnemyGunships='..tostring(bConsiderAttackingEnemyGunships)..'; tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat]='..(tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0)..'; Is table of enemy units in the zone empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]))..'; bUseDefensively='..tostring(bUseDefensively)) end
                if (not(bOnlyIncludeIfMexToProtect) or IsHighValueZoneToProtect()) and (not(bUseDefensively) or tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.35 or IsHighValueZoneToProtect()) and (AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false or (bConsiderAttackingEnemyGunships and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftLZEnemyAirUnits]) == false)) then
                    local bDoDetailedGroundAACheck = bDetailedAACheckOverride
                    if IsHighValueZoneToProtect() then
                        if (tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) <= 200 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] then iGunshipThreatFactorWanted = math.min(iGunshipThreatFactorWanted, math.max(iGunshipThreatFactorWanted * 0.5, 1.5))
                        else iGunshipThreatFactorWanted = math.min(iGunshipThreatFactorWanted, math.max(iGunshipThreatFactorWanted * 0.8, 1.8))
                        end
                        bDoDetailedGroundAACheck = true
                        if iSpecificAirAAThreatLimit >= 0 and iOptionalHigherAirAAThresholdForHighValueZones then iSpecificAirAAThreatLimit = math.max(iSpecificAirAAThreatLimit, iOptionalHigherAirAAThresholdForHighValueZones) end
                    elseif tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.35 and bConsiderAttackingEnemyGunships and (tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) >= 500 then
                        bDoDetailedGroundAACheck = true
                    elseif iZonesWithPotentialTargetsCount < 4 then
                        bDoDetailedGroundAACheck = true
                    end

                    local iMaxEnemyGroundAA
                    if iGunshipThreatFactorWanted == 0 then
                        iMaxEnemyGroundAA = -1 --   -1 is used to denote infinite in this case
                    else
                        iMaxEnemyGroundAA = iOurGunshipThreat / iGunshipThreatFactorWanted
                        if bDebugMessages == true then LOG(sFunctionRef..': iMaxEnemyGroundAA based on threat factor only='..iMaxEnemyGroundAA..'; will now adjust for shields, tLZOrWZTeamData[AiBotMap.subrefThreatEnemyShield]='..(tLZOrWZTeamData[AiBotMap.subrefThreatEnemyShield] or 'nil')) end
                        --Further adjust for enemy shield value
                        if (tLZOrWZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) > 0 then
                            if AiBotUtilities.bFAFActive then
                                --Shields dont stack very well so limit the threat from them to 1:1
                                iMaxEnemyGroundAA = math.max(iMaxEnemyGroundAA * 0.5, iMaxEnemyGroundAA - math.min(5500, tLZOrWZTeamData[AiBotMap.subrefThreatEnemyShield]))
                            else
                                --Shields stack, so allow a 3:1 threat ratio
                                iMaxEnemyGroundAA = math.max(iMaxEnemyGroundAA * 0.25, iMaxEnemyGroundAA - math.min(12000, tLZOrWZTeamData[AiBotMap.subrefThreatEnemyShield]))
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iMaxEnemyGroundAA after shield adjustment='..iMaxEnemyGroundAA) end
                        end
                    end
                    --Adjust ground AA if we have T2 or T3 mexes or high structure value here (subject to an overall cap)
                    if iGunshipThreatFactorWanted > 2.5 and (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][2] or 0) > 0 or (tLZOrWZTeamData[AiBotMap.subrefMexCountByTech][3] or 0) > 0 or (tLZOrWZTeamData[AiBotMap.subrefLZSValue] or 0) >= 1000 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Have T2 or T3 mexes we want to defend, so will increase the groundAA threat we think we can handle by 50% (subjcet to overall limit), iMaxEnemyGroundAA before adjustment='..iMaxEnemyGroundAA..'; iGunshipThreatFactorWanted='..iGunshipThreatFactorWanted..'; Expected threshold after adjustment='..math.max(iMaxEnemyGroundAA, math.min(iMaxEnemyGroundAA * 1.5, iOurGunshipThreat / 2.5), iOurGunshipThreat / 4.5)) end
                        iMaxEnemyGroundAA = math.max(iMaxEnemyGroundAA, math.min(iMaxEnemyGroundAA * 1.5, iOurGunshipThreat / 2.5), iOurGunshipThreat / 4.5)

                    end
                    if iGroundAAThresholdAdjust and iMaxEnemyGroundAA >= 0 then
                        iMaxEnemyGroundAA = math.max(0, iMaxEnemyGroundAA + iGroundAAThresholdAdjust)
                        if bDebugMessages == true then LOG(sFunctionRef..': Finished increasing for iGroundAAThresholdAdjust='..iGroundAAThresholdAdjust) end
                    end
                    --decrease max groundAA for higher values (since the more MAA/SAMs in one place, the harder it will be for low health gunships to heal, instead they just die
                    if iOurGunshipThreat >= 10000 then
                        if (AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and (not(AiBotUtilities.bQuietModActive) or AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] >= math.max(10000, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills])) then
                            iMaxEnemyGroundAA = math.max(iMaxEnemyGroundAA * 0.1, iMaxEnemyGroundAA - math.max(0, (iMaxEnemyGroundAA - 5000)) / (iGunshipThreatFactorWanted * 0.5))
                            if iOurGunshipThreat >= 20000 then
                                iMaxEnemyGroundAA = math.max(iMaxEnemyGroundAA * 0.5, iMaxEnemyGroundAA - math.max(0, (iMaxEnemyGroundAA - 10000)) / (iGunshipThreatFactorWanted * 0.25))
                            end
                        elseif iOurGunshipThreat >= 12000 then
                            iMaxEnemyGroundAA = math.max(iMaxEnemyGroundAA * 0.6, iMaxEnemyGroundAA - math.max(0, (iMaxEnemyGroundAA - 6000)) / (iGunshipThreatFactorWanted * 0.2))
                            local iLossToKillRatioToUse = 1
                            if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] >= math.max(10000,  AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills])  then
                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills] == 0 then
                                    iLossToKillRatioToUse = 2.5
                                else
                                    iLossToKillRatioToUse = math.min(2.5, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] / AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills])
                                end
                                iMaxEnemyGroundAA = iMaxEnemyGroundAA * math.min(1, (1 - 0.1 * (iLossToKillRatioToUse - 1)))
                                if bDebugMessages == true then LOG(sFunctionRef..': Reduced groundAA threshold due to heavy losses for gunships, iMaxEnemyGroundAA='..iMaxEnemyGroundAA) end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Reducing the enemy groundAA threshold due to high threat levels, iMaxEnemyGroundAA after reduction='..iMaxEnemyGroundAA) end
                        end
                    end

                    --Check if enemy has enough AA nearby
                    local bTooMuchAA
                    local bDontAvoidNearestAA = true
                    local oClosestEnemyUnit
                    local oClosestEnemyAAUnit
                    local iMinDistFromAAWantedFrontUnit = iMinDistFromAAWantedIfAvoidingForMostUnits + 10 --(we manually adjust this for the AA range when referring to it, i.e. this is dif to iMinDistFromAAWantedIfAvoidingForMostUnits which is modified below)

                    if not (bCheckForAirAA) and iMaxEnemyGroundAA <= 0 then
                        bTooMuchAA = false
                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy doesnt have any groundAA and we arent checking for AirAA') end
                    else
                        local tMidpointForDetailedAACheck

                        if bDoDetailedGroundAACheck and AiBotConditions.IsTableOfUnitsStillValid(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) then
                            local tEnemyAAUnits = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGroundAA, tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])

                            local iClosestAADist = 10000
                            local iClosestDist = 10000
                            if AiBotUtilities.IsTableEmpty(tEnemyAAUnits) == false then
                                for iUnit, oUnit in tEnemyAAUnits do
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oFrontGunship:GetPosition())
                                    if iCurDist < iClosestDist and (iPlateauOrZero > 0 or not(AiBotUnitInfo.IsUnitUnderwater(oUnit))) then
                                        oClosestEnemyUnit = oUnit
                                        iClosestDist = iCurDist
                                    end
                                end
                            end

                            for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits] do
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oFrontGunship:GetPosition())
                                if (iCurDist < iClosestDist or iCurDist < iClosestAADist) then
                                    if (iPlateauOrZero > 0 or not(AiBotUnitInfo.IsUnitUnderwater(oUnit))) then
                                        if iCurDist < iClosestDist then
                                            oClosestEnemyUnit = oUnit
                                            iClosestDist = iCurDist
                                        end
                                        if iCurDist < iClosestAADist and (oUnit[AiBotUnitInfo.refiAARange] or 0) > 0 and EntityCategoryContains(AiBotUnitInfo.refCategoryGroundAA, oUnit.UnitId) then
                                            oClosestEnemyAAUnit = oUnit
                                            iClosestAADist = iCurDist
                                        end
                                    end
                                end
                            end
                            --Gusnhips will target AA over other units, so we want to consider using the closest AA unit for detailed checks; however also want to handle times when vulnerable enemies are close to the edge of the zone and we can attack them without getting into range of main AA threat in the wider zone
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if should target closest enemy unit, or closest enemy AA unit, oClosestEnemyAAUnit='..(oClosestEnemyAAUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemyAAUnit) or 'nil')..'; oClosestEnemyUnit='..(oClosestEnemyUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemyUnit) or 'nil'))
                                if oClosestEnemyAAUnit then LOG(sFunctionRef..': oClosestEnemyAAUnit AA range='..(oClosestEnemyAAUnit[AiBotUnitInfo.refiAARange] or 'nil')..'; Dist between this and closest enemy='..AiBotUtilities.GetDistanceBetweenPositions(oClosestEnemyAAUnit:GetPosition(), oClosestEnemyUnit:GetPosition())) end
                            end
                            if bDoDetailedGroundAACheck and oClosestEnemyAAUnit and not(oClosestEnemyAAUnit == oClosestEnemyUnit) and AiBotUtilities.GetDistanceBetweenPositions(oClosestEnemyAAUnit:GetPosition(), oClosestEnemyUnit:GetPosition()) <= oClosestEnemyAAUnit[AiBotUnitInfo.refiAARange] + iMinDistFromAAWantedFrontUnit then
                                oClosestEnemyUnit = oClosestEnemyAAUnit
                                if bDebugMessages == true then LOG(sFunctionRef..': Will switch so closest enemy is the closest AA unit') end
                            end
                            if oClosestEnemyUnit then tMidpointForDetailedAACheck = oClosestEnemyUnit:GetPosition() end
                            if bDebugMessages == true then LOG(sFunctionRef..': oClosestEnemyUnit (or closest AA if enemy has nearby groudnAA)='..(oClosestEnemyUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemyUnit) or 'nil')..'; will set this as the position to use for detailed AA check, tMidpointForDetailedAACheck='..repru(tMidpointForDetailedAACheck)) end
                        end
                        local tStartToUse
                        if bDoDetailedGroundAACheck then tStartToUse = oFrontGunship:GetPosition() end
                        --DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck, bReturnGroundAAUnitsAlongsideAAThreat, tOptionalEndMidpointAdjustForDetailedCheck)
                        bTooMuchAA = DoesEnemyHaveAAThreatAlongPath(iTeam, iGunshipPlateauOrZero, iGunshipLandOrWaterZone, iPlateauOrZero, iLandOrWaterZone, not(bCheckForAirAA), iMaxEnemyGroundAA, iSpecificAirAAThreatLimit,     false,              iAirSubteam, bDoDetailedGroundAACheck, nil,                         tStartToUse,                                        nil,                                    tMidpointForDetailedAACheck)
                        if not(bTooMuchAA) and oClosestEnemyAAUnit and not(oClosestEnemyAAUnit == oClosestEnemyUnit) and DoesEnemyHaveAAThreatAlongPath(iTeam, iGunshipPlateauOrZero, iGunshipLandOrWaterZone, iPlateauOrZero, iLandOrWaterZone, not(bCheckForAirAA), iMaxEnemyGroundAA, iSpecificAirAAThreatLimit,     false,              iAirSubteam, bDoDetailedGroundAACheck, nil,                         tStartToUse,                                        nil,                                    oClosestEnemyAAUnit:GetPosition()) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy has too much AA if we target the nearest AA unit, so we want to only target units near the closest enemy unit that arent in range of the nearest AA') end
                            bDontAvoidNearestAA = false
                            iMinDistFromAAWantedIfAvoidingForMostUnits = iMinDistFromAAWantedIfAvoidingForMostUnits + oClosestEnemyAAUnit[AiBotUnitInfo.refiAARange]
                            bAreJustTargetingUnitsOutOfAARange = true
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering zone '..iLandOrWaterZone..'; iPlateauOrZero='..iPlateauOrZero..'; bTooMuchAA='..tostring(bTooMuchAA)..'; bCheckForAirAA='..tostring(bCheckForAirAA or false)..'; iMaxEnemyGroundAA='..(iMaxEnemyGroundAA or 'nil')..'; iSpecificAirAAThreatLimit='..iSpecificAirAAThreatLimit..'; iOptionalHigherAirAAThresholdForHighValueZones='..(iOptionalHigherAirAAThresholdForHighValueZones or 'nil')..'; iOurGunshipThreat='..iOurGunshipThreat..'; iGunshipThreatFactorWanted='..iGunshipThreatFactorWanted..'; bDoDetailedGroundAACheck='..tostring(bDoDetailedGroundAACheck)..'; bDontAvoidNearestAA='..tostring(bDontAvoidNearestAA)) end

                    if not (bTooMuchAA) then
                        --Add enemy units in the plateau/land zone to list of enemy unit targets
                        if bDebugMessages == true then LOG(sFunctionRef..': We want to target this zone if it has enemy units in it, Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]))..'; Is table of enemy air units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftLZEnemyAirUnits]))) end
                        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                            if not(bHaveEnemyInCoreBase) then bHaveEnemyInCoreBase = tLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] end
                            local bDontCheckPlayableArea = not(AiBotMap.bIsCampaignMap)
                            local bReplaceOnFirstValidUnit = bOnlyIncludeIfMexToProtect

                            for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits] do
                                --Ignore land scouts - both because they are low threat, and also because in the case of selens they might be cloaked
                                if AiBotUnitInfo.IsUnitValid(oUnit) and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryNavalSurface + AiBotUnitInfo.refCategoryMobileLand - AiBotUnitInfo.refCategoryLandScout, oUnit.UnitId) and not (AiBotUnitInfo.IsUnitUnderwater(oUnit)) and (bDontCheckPlayableArea or AiBotConditions.IsLocationInPlayableArea(oUnit:GetPosition())) and not(oUnit:IsUnitState('Attached')) then
                                    if bDontAvoidNearestAA or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestEnemyAAUnit:GetPosition()) >= iMinDistFromAAWantedIfAvoidingForMostUnits then
                                        if bReplaceOnFirstValidUnit then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want to replace first valid unit as bOnlyIncludeIfMexToProtect is true, PlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; SValue='..tLZOrWZTeamData[AiBotMap.subrefLZSValue]..'; Is high value zone='..tostring(IsHighValueZoneToProtect())) end
                                            tEnemyGroundOrGunshipTargets = {}
                                            bReplaceOnFirstValidUnit = false
                                            bDontLookForMoreTargets = true
                                        end
                                        AddUnitToTargetsTable(oUnit)
                                    end
                                end
                            end
                        end
                        --Consider adding enemy cybran experimentals or gunships
                        if bConsiderAttackingEnemyGunships and tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] > 0 then
                            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftLZEnemyAirUnits]) == false then
                                local tEnemyGunships = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGunship, tLZOrWZTeamData[AiBotMap.reftLZEnemyAirUnits])
                                if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy gunships empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyGunships))) end
                                if AiBotUtilities.IsTableEmpty(tEnemyGunships) == false then
                                    if tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] * 1.25 < iOurGunshipThreat or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(categories.EXPERIMENTAL * categories.CYBRAN, tEnemyGunships)) == false then
                                        for iUnit, oUnit in  tEnemyGunships do
                                            if AiBotUnitInfo.IsUnitValid(oUnit) and not(oUnit:IsUnitState('Attached')) then
                                                if bDontAvoidNearestAA or AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestEnemyAAUnit:GetPosition()) >= iMinDistFromAAWantedIfAvoidingForMostUnits then
                                                    AddUnitToTargetsTable(oUnit)
                                                end
                                            end
                                        end
                                    elseif bDebugMessages == true then LOG(sFunctionRef..': we dont have significantly more gunship threat so dont want to attack gunships with our own')
                                    end
                                end
                            end
                        end

                    elseif bDebugMessages == true then LOG(sFunctionRef..': Too much AA so wont try and target this zone')
                    end
                    if not(bOnlyIncludeIfMexToProtect) and AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets) == false and IsHighValueZoneToProtect() then
                        bDontLookForMoreTargets = true
                    end
                end
            end
        end

        local iCurPlateauOrZero, iCurLZOrWZ

        --Retreat if ahwassa bomb exploded near front gunship
        local bRetreatFromAhwassa = false
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to retreat from Ahwassa targets, tiRecentExpBomberTargets='..repru(tiRecentExpBomberTargets)) end
        if oFrontGunship and AiBotUtilities.IsTableEmpty(tiRecentExpBomberTargets) == false then
            local iDistanceThreshold = 55 + math.min(20, table.getn(tAvailableGunships) * 0.25)
            for iTarget, tTarget in tiRecentExpBomberTargets do
                if bDebugMessages == true then LOG(sFunctionRef..': Dist between front gunship and ahwassa target='..AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), tTarget)..'; iDistanceThreshold='..iDistanceThreshold) end
                if AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), tTarget) <= iDistanceThreshold then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to retreat from ahwassa target, tTarget='..repru(tTarget)..'; Dist to front gunship='..AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), tTarget)) end
                    bRetreatFromAhwassa = true
                    break
                end
            end
        end
        --Snipe target
        local bUsingSnipePriority = false
        local iClosestSnipeTarget = 100000
        if not(bRetreatFromAhwassa) and AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]) and iOurGunshipThreat > 0 then
            local iAvailableGunshipThreat = AiBotUnitInfo.GetAirThreatLevel(tAvailableGunships, false, false, false, true)
            local iTargetHealthPercent
            if not(tNewlyAddedEnemies) then tNewlyAddedEnemies = {} end
            for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets] do
                local iTargetPlateauOrZero, iTargetLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                local tbPlateauAndZoneAdded = {}
                local iOrigMaxEnemyAirAA = iMaxEnemyAirAA
                if (iTargetPlateauOrZero or 0) > 0 and (iTargetLZOrWZ or 0) > 0 then
                    if not(tbPlateauAndZoneAdded[iTargetPlateauOrZero]) then tbPlateauAndZoneAdded[iTargetPlateauOrZero] = {} end
                    if not(tbPlateauAndZoneAdded[iTargetPlateauOrZero][iTargetLZOrWZ]) then
                        local tTargetLZTeamData = AiBotMap.tAllPlateaus[iTargetPlateauOrZero][AiBotMap.subrefPlateauLandZones][iTargetLZOrWZ][AiBotMap.subrefLZTeamData][iTeam]
                        iTargetHealthPercent = AiBotUnitInfo.GetUnitHealthAndShieldPercent(oUnit)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy snipe target '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Will add all enemy ground units in P'..iTargetPlateauOrZero..'Z'..iTargetLZOrWZ..'; Unit health='..oUnit:GetHealth()..'; iAvailableGunshipThreat='..iAvailableGunshipThreat..'; iAvailableGunshipThreat='..iAvailableGunshipThreat..'; Enemy AA threat in this zone='..(tTargetLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')..'; second line condition='..tostring(iAvailableGunshipThreat < 1000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] or AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] or tTargetLZTeamData[AiBotMap.refiModDistancePercent] < 0.25 or (tTargetLZTeamData[AiBotMap.refiModDistancePercent] < 0.5 and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir])) or AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refbAssassinationOrSimilar])) end
                        if oUnit:GetHealth() < iAvailableGunshipThreat and ((iTargetHealthPercent <= 0.2 and iAvailableGunshipThreat >= math.min(5000, oUnit:GetHealth() * 2)) or (tTargetLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] < iAvailableGunshipThreat and iTargetHealthPercent < 0.3))
                                --Avoid suciiding into a snipe target if it is full share with players still on enemy team, and we are far behind on air and have enough fo a gunship threat taht would hurt to lose them
                                and (iAvailableGunshipThreat < 1000 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] or AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] or tTargetLZTeamData[AiBotMap.refiModDistancePercent] < 0.25 or (tTargetLZTeamData[AiBotMap.refiModDistancePercent] < 0.5 and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir])) or AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refbAssassinationOrSimilar]) then
                            --Just add the ACU as a target
                            if bDebugMessages == true then LOG(sFunctionRef..': Will just add the enemy ACU as a snipe target as it is so low health') end
                            AddUnitToTargetsTable(oUnit, true)
                            --Make sure gunships will prioritise enemy ACU
                            bUsingSnipePriority = true
                        elseif AiBotMap.bIsCampaignMap and oUnit[AiBotUnitInfo.refiCampaignSnipeAttempts] then
                            if bDebugMessages == true then LOG(sFunctionRef..': Campaign ACU snipe attempt') end
                            AddUnitToTargetsTable(oUnit, true)
                        elseif tTargetLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] < iAvailableGunshipThreat then
                            tbPlateauAndZoneAdded[iTargetPlateauOrZero][iTargetLZOrWZ] = true
                            iMaxEnemyAirAA = math.min(iOrigMaxEnemyAirAA * (0.25 + 0.25 * iTargetHealthPercent), iOrigMaxEnemyAirAA)
                            AddEnemyGroundUnitsToTargetsSubjectToAA(iTargetPlateauOrZero, iTargetLZOrWZ, 0.75, true, nil,nil,true)
                        end

                        iClosestSnipeTarget = math.min(iClosestSnipeTarget, AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oFrontGunship:GetPosition()))
                    end
                end
                iMaxEnemyAirAA = iOrigMaxEnemyAirAA
            end
        end

        --Emergency response - first include any ground threats in a core zone and (if none) adjacent to a core zone (v92 and earlier - used start positions instead)
        if not(iClosestSnipeTarget) or iClosestSnipeTarget >= 200 then
            local tiFriendlyStartPositionPlateauAndZones = {}
            local iStartPositionGunshipThreatFactorWanted = 0.5
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 then
                iStartPositionGunshipThreatFactorWanted = math.min(1.2, 0.3 + 0.3 * AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount])
            end
            --Dont want ot consider non-air subteam incase we cross half the map and lose our gunships to air (which happend in RC on v204)
            for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                local iBasePlateau, iBaseZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotMap.GetPlayerStartPosition(oBrain))
                if (iBasePlateau or 0) > 0 then
                    if (iBaseZone or 0) == 0 then
                        iBaseZone = AiBotMap.GetWaterZoneFromPosition(AiBotMap.GetPlayerStartPosition(oBrain))
                        if (iBaseZone or 0) > 0 then
                            iBasePlateau = 0
                        end
                    end
                end
                table.insert(tiFriendlyStartPositionPlateauAndZones, {iBasePlateau, iBaseZone})
            end

            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiFortifyZonesByPlateau]) == false then
                for iPlateau, tZones in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiFortifyZonesByPlateau] do
                    for iZone, bZone in tZones do
                        --Only include if we have friendly SValue in the zone
                        local tLZOrWZData
                        local tLZOrWZTeamData
                        if iPlateau > 0 then
                            tLZOrWZData  = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iZone]
                            tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                        else
                            --Water zone
                            tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iPlateau]][AiBotMap.subrefPondWaterZones][iZone]
                            tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                        end
                        if tLZOrWZTeamData[AiBotMap.subrefLZSValue] > 0 then
                            table.insert(tiFriendlyStartPositionPlateauAndZones, {iPlateau, iZone})
                        end
                    end
                end
            end

            local bAlwaysInclAdjToStart = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]
            if not(bAlwaysInclAdjToStart) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] or 0) < iOurGunshipThreat * 0.1 then bAlwaysInclAdjToStart = true end
            --Campaign - temporary escort missions - treat a priority defence unit similar to a start position
            if AiBotMap.bIsCampaignMap and AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam]) == false then
                local tOtherDefenceUnits = EntityCategoryFilterDown(categories.ALLUNITS - categories.COMMAND - AiBotUnitInfo.refCategoryExperimentalLevel, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam])
                if AiBotUtilities.IsTableEmpty(tOtherDefenceUnits) == false then
                    local tbPlateauAndZone = {}
                    if AiBotUtilities.IsTableEmpty(tiFriendlyStartPositionPlateauAndZones) == false then
                        for _, tiPlateauAndZone in tiFriendlyStartPositionPlateauAndZones do
                            if not(tbPlateauAndZone[tiPlateauAndZone[1]]) then tbPlateauAndZone[tiPlateauAndZone[1]] = {} end
                            tbPlateauAndZone[tiPlateauAndZone[1]][tiPlateauAndZone[2]] = true
                        end
                    end
                    local iCurUnitPlateau, iCurUnitZone
                    for iUnit, oUnit in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftACUExpAndPriorityDefenceOnSubteam] do
                        if not(oUnit.Dead) then
                            iCurUnitPlateau = (oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] or -1)
                            if iCurUnitPlateau > 0 then
                                iCurUnitZone = (oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] or -1)
                                if iCurUnitZone > 0 then
                                    if not(tbPlateauAndZone[iCurUnitPlateau]) then tbPlateauAndZone[iCurUnitPlateau] = true end
                                    if not(tbPlateauAndZone[iCurUnitPlateau][iCurUnitZone]) then
                                        tbPlateauAndZone[iCurUnitPlateau][iCurUnitZone] = true
                                        if not(tiFriendlyStartPositionPlateauAndZones) then tiFriendlyStartPositionPlateauAndZones = {} end
                                        table.insert(tiFriendlyStartPositionPlateauAndZones, {iCurUnitPlateau, iCurUnitZone})
                                    end
                                end
                            end
                        end
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(tiFriendlyStartPositionPlateauAndZones) == false and (not(iClosestSnipeTarget) or iClosestSnipeTarget >= 400) then
                if bDebugMessages == true then LOG(sFunctionRef..': Will look for enemies in tiFriendlyStartPositionPlateauAndZones, tiFriendlyStartPositionPlateauAndZones='..repru(tiFriendlyStartPositionPlateauAndZones)) end
                for iEntry, tiPlateauAndZone in tiFriendlyStartPositionPlateauAndZones do
                    --AddEnemyGroundUnitsToTargetsSubjectToAA(iPlateauOrZero, iLandOrWaterZone, iGunshipThreatFactorWanted, bCheckForAirAA, bOnlyIncludeIfMexToProtect, iGroundAAThresholdAdjust, bIgnoreMidpointPlayableCheck)
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to add enemies around core base P'..(tiPlateauAndZone[1] or 'nil')..'; Z'..(tiPlateauAndZone[2] or 'nil')) end
                    AddEnemyGroundUnitsToTargetsSubjectToAA(tiPlateauAndZone[1], tiPlateauAndZone[2], iStartPositionGunshipThreatFactorWanted, false, nil, nil, true)
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of targets empty after checking core zones='..tostring(AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets))) end
                if AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets) then
                    --Consider land zones adjacent to a land start position provided the zone midpoint is within 25% of the closest base (since we aren't doing an AirAA check), and the enemy doesnt have a large airaa force near us
                    for iEntry, tiPlateauAndZone in tiFriendlyStartPositionPlateauAndZones do
                        if tiPlateauAndZone[1] > 0 then
                            local tLZData = AiBotMap.tAllPlateaus[tiPlateauAndZone[1]][AiBotMap.subrefPlateauLandZones][tiPlateauAndZone[2]]
                            if bDebugMessages == true then LOG(sFunctionRef..': About to consider adjacent land zones to the core zone P'..tiPlateauAndZone[1]..'Z'..tiPlateauAndZone[2]..'; bRetreatFromAhwassa='..tostring(bRetreatFromAhwassa)..'; Is table of adj zones empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]))..'; iEnemyAirAAThreatNearGunship='..iEnemyAirAAThreatNearGunship..'; 25% of gunship threat='..iOurGunshipThreat * 0.25..'; iMaxEnemyAirAA='..iMaxEnemyAirAA) end
                            if not(bRetreatFromAhwassa) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false and iEnemyAirAAThreatNearGunship < math.min(iOurGunshipThreat * 0.25, iMaxEnemyAirAA) then
                                local iCurDistToBase
                                local iGunshipAdjacentToCoreBaseThreatFactorWanted = 3
                                if AiBotMap.bIsCampaignMap and tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZFortify] then iGunshipAdjacentToCoreBaseThreatFactorWanted = 2 end
                                for iEntry, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do

                                    --Land zone
                                    local tAdjLZData = AiBotMap.tAllPlateaus[tiPlateauAndZone[1]][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                    local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iAdjLZ='..iAdjLZ..'; Mod dist%='..tAdjLZTeamData[AiBotMap.refiModDistancePercent]..'; Is campaign map='..tostring(AiBotMap.bIsCampaignMap)..'; LZ fortify='..tostring(tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZFortify] or false)..'; AdjLZ Fortify='..tostring(tAdjLZTeamData[AiBotMap.subrefLZFortify] or false)..'; bAlwaysInclAdjToStart='..tostring(bAlwaysInclAdjToStart)) end
                                    if tAdjLZTeamData[AiBotMap.refiModDistancePercent] <= 0.5 or (AiBotMap.bIsCampaignMap and (tLZData[AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefLZFortify] or tAdjLZTeamData[AiBotMap.subrefLZFortify])) then
                                        iCurDistToBase = AiBotUtilities.GetDistanceBetweenPositions(tAdjLZTeamData[AiBotMap.reftClosestFriendlyBase], tAdjLZData[AiBotMap.subrefMidpoint])
                                        if bAlwaysInclAdjToStart or tAdjLZTeamData[AiBotMap.refiModDistancePercent] <= 0.1 or iCurDistToBase <= 220 then
                                            --Check actual % dist to base
                                            if bAlwaysInclAdjToStart or tAdjLZTeamData[AiBotMap.refiModDistancePercent] <= 0.1 or iCurDistToBase <= 100 or iCurDistToBase / AiBotUtilities.GetDistanceBetweenPositions(tAdjLZTeamData[AiBotMap.reftClosestFriendlyBase], tAdjLZTeamData[AiBotMap.reftClosestEnemyBase]) <= 0.275 then
                                                AddEnemyGroundUnitsToTargetsSubjectToAA(tiPlateauAndZone[1], iAdjLZ, 3, false)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Is table of enem ytargets empty after checking iAdjLZ='..iAdjLZ..'='..tostring(AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets))..'; iCurDistToBase='..iCurDistToBase..'; % of dist from friendl yto enemy='..iCurDistToBase / AiBotUtilities.GetDistanceBetweenPositions(tAdjLZTeamData[AiBotMap.reftClosestFriendlyBase], tAdjLZTeamData[AiBotMap.reftClosestEnemyBase])..'; Mod dist%='..tAdjLZTeamData[AiBotMap.refiModDistancePercent]..'; bAlwaysInclAdjToStart='..tostring(bAlwaysInclAdjToStart or false)) end
                                            elseif bDebugMessages == true then LOG(sFunctionRef..': Actual % is too far, iCurDistToBase='..iCurDistToBase..'; tAdjLZTeamData[AiBotMap.refiModDistancePercent]='..tAdjLZTeamData[AiBotMap.refiModDistancePercent]..'; Actual %='..iCurDistToBase / AiBotUtilities.GetDistanceBetweenPositions(tAdjLZTeamData[AiBotMap.reftClosestFriendlyBase], tAdjLZTeamData[AiBotMap.reftClosestEnemyBase]))
                                            end
                                        elseif bDebugMessages == true then LOG(sFunctionRef..': Midpoint is too far away, iCurDistToBase='..iCurDistToBase)
                                        end
                                    elseif bDebugMessages == true then LOG(sFunctionRef..': Wont consider iAdjLZ='..iAdjLZ..' as a high priority since tAdjLZTeamData[AiBotMap.refiModDistancePercent]='..tAdjLZTeamData[AiBotMap.refiModDistancePercent])
                                    end
                                end
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished checking for enemies in LZ adjacent to core zone, is table of enemy targets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets))..'; if empty then will move on to Checking if too great an enemy threat in zone ghunships are in now (or adjacent to it), IsThereAANearLandOrWaterZone='..tostring(IsThereAANearLandOrWaterZone(iTeam, iGunshipPlateauOrZero, iGunshipLandOrWaterZone, (iGunshipPlateauOrZero == 0), iOurGunshipThreat / 3, iMaxEnemyAirAA))) end
            end
        end

        local bConsiderIgnoringEnemiesInLowValueZones = false --if set to true then will look for more zones in case there is a high value wone we can target
        if not(bRetreatFromAhwassa) and (not(iClosestSnipeTarget) or iClosestSnipeTarget >= 400) then
            --if AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets) then
            --Consider enemy experimental near start position
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false then

                local tNearestBase = tGunshipLandOrWaterZoneTeamData[AiBotMap.reftClosestFriendlyBase]
                local oNearestExperimental
                local iCurDist
                local iClosestDist = 100000
                if AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets) == false then iClosestDist = 100 end
                for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals] do
                    if AiBotUnitInfo.IsUnitValid(oUnit) and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) then
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tNearestBase, oUnit:GetPosition())
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy Exp '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurDist='..iCurDist..'; iClosestDist='..iClosestDist) end
                        if iCurDist < iClosestDist then
                            iClosestDist = iCurDist
                            oNearestExperimental = oUnit
                        end
                    end
                end
                if oNearestExperimental and iClosestDist <= 190 then
                    --If lack air control then consider nearby air threat using normal logic
                    local bAttackExperimental = true
                    if iClosestDist > 100 and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then
                        if iClosestDist > 170 and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then
                            bAttackExperimental = false
                        elseif AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] or iClosestDist > 130 then
                            local bNearbyAirToGunship = IsThereAANearLandOrWaterZone(iTeam, iGunshipPlateauOrZero, iGunshipLandOrWaterZone, (iGunshipPlateauOrZero == 0), iOurGunshipThreat / 1.8, iMaxEnemyAirAA, 60, oFrontGunship:GetPosition())
                            if bNearbyAirToGunship then
                                bAttackExperimental = false
                            end
                        end
                    end
                    if bAttackExperimental then
                        local bCheckForAirAA = true
                        local iThreatFactor = 3.5
                        if iClosestDist <= 130 then
                            bCheckForAirAA = false
                            iThreatFactor = 2
                        end
                        local iTargetPlateau, iTargetZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oNearestExperimental:GetPosition())
                        if (iTargetZone or 0) > 0 then
                            local iGroundAAThreatAdjust = 0
                            if iOurGunshipThreat >= 600 then
                                --Reduce by AA of experimental, i.e. dont want to avoid engaging a ythotha just because of the ythotha AA
                                iGroundAAThreatAdjust = AiBotUnitInfo.GetAirThreatLevel({ oNearestExperimental }, true, false, true, false, false, false, false) * 0.75
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Will consider adding zone containing the closest experimental, oNearestExperimental='..oNearestExperimental.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestExperimental)..'; iGroundAAThreatAdjust='..iGroundAAThreatAdjust..'; iTargetPlateau='..iTargetPlateau..'; iTargetZone='..iTargetZone) end
                            --AddEnemyGroundUnitsToTargetsSubjectToAA(iPlateauOrZero, iLandOrWaterZone, iGunshipThreatFactorWanted, bCheckForAirAA, bOnlyIncludeIfMexToProtect, iGroundAAThresholdAdjust, bIgnoreMidpointPlayableCheck, bDetailedAACheckOverride)
                            AddEnemyGroundUnitsToTargetsSubjectToAA(iTargetPlateau, iTargetZone, iThreatFactor, bCheckForAirAA, nil, iGroundAAThreatAdjust, nil, true)
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finished considering if have appraoching land experimental, oNearestExperimental='..(oNearestExperimental.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNearestExperimental) or 'nil')..'; iClosestDist='..iClosestDist..'; Is table of enemy targets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets))) end
            end
            local bConsiderEnemiesInGunshipZone = AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets)
            if not(bConsiderEnemiesInGunshipZone) and iOurGunshipThreat >= 5000 and not(bHaveEnemyInCoreBase) and AiBotUtilities.GetDistanceBetweenPositions(tEnemyGroundOrGunshipTargets[1]:GetPosition(), oFrontGunship:GetPosition()) >= 200 and iEnemyGroundAAThreatByGunship < 0.2 * iOurGunshipThreat and iEnemyAirAAThreatNearGunship < 0.05 * iOurGunshipThreat and (tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefThreatEnemyShield] or 0) < math.min(iOurGunshipThreat * 0.5, 7500) and AiBotUtilities.IsTableEmpty(tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                --Want to avoid the scenario where we are about ot kill a high value unit or enemy base, but we decide to run across to the other side of the map because a couple of tanks got adjacent to a core base
                if (tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) - (tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefThreatEnemyShield] or 0) * 4 >= 6000 then
                    bConsiderEnemiesInGunshipZone = true
                else
                    local tEnemiesOfSignificanceInZone = EntityCategoryFilterDown(categories.COMMAND + AiBotUnitInfo.refCategoryFatboy + AiBotUnitInfo.refCategoryExperimentalLevel, tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefTEnemyUnits])
                    if AiBotUtilities.IsTableEmpty( tEnemiesOfSignificanceInZone) == false then
                        --Check enemy health low enough we can kill it relatively fast
                        local iCurHealthAndShield
                        for iUnit, oUnit in tEnemiesOfSignificanceInZone do
                            if not(oUnit.Dead) then
                                iCurHealthAndShield = AiBotUnitInfo.GetUnitCurHealthAndShield(oUnit)
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering unit of interest in gunship zone, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurHealthAndShield='..iCurHealthAndShield..'; Unit health%='..AiBotUnitInfo.GetUnitHealthAndShieldPercent(oUnit)) end
                                if iCurHealthAndShield <= 16000 and (iCurHealthAndShield < iOurGunshipThreat or AiBotUnitInfo.GetUnitHealthAndShieldPercent(oUnit) <= 0.6) then
                                    bConsiderEnemiesInGunshipZone = true
                                    break
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true and AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets) == false then LOG(sFunctionRef..': We have targets but want to consider still attacking nearby enemies first; bConsiderEnemiesInGunshipZone='..tostring(bConsiderEnemiesInGunshipZone)..'; Dist to first enemy in table of enemies='..AiBotUtilities.GetDistanceBetweenPositions(tEnemyGroundOrGunshipTargets[1]:GetPosition(), oFrontGunship:GetPosition())..'; bHaveEnemyInCoreBase='..tostring(bHaveEnemyInCoreBase)..'; iEnemyGroundAAThreatByGunship='..iEnemyGroundAAThreatByGunship..'; iEnemyAirAAThreatNearGunship='..iEnemyAirAAThreatNearGunship..'; Is table of enemy units in gunship zone empty='..tostring(AiBotUtilities.IsTableEmpty(tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefTEnemyUnits]))..'; Enemy structure mass in zone='..(tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 'nil')..'; Enemy shield threat='..(tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefThreatEnemyShield] or 'nil')) end
            if bConsiderEnemiesInGunshipZone then
                --Protect ACU if down to last ACU on the team and ACU may be in trouble
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] == 1 then
                    local aiBrain = AiBotTeam.GetFirstActiveAiBotBrain(iTeam)
                    local tACUs = aiBrain:GetListOfUnits(categories.COMMAND, false, true)
                    if AiBotUtilities.IsTableEmpty(tACUs) == false then
                        for iACU, oACU in tACUs do
                            local iCurACUHealthPercent = AiBotUnitInfo.GetUnitHealthPercent(oACU)
                            if iCurACUHealthPercent < 0.95 then
                                local iCurACUPlateauOrZero, iCurACUZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oACU:GetPosition())
                                if (iCurACUPlateauOrZero or 0) > 0 then
                                    local tACULZData = AiBotMap.tAllPlateaus[iCurACUPlateauOrZero][AiBotMap.subrefPlateauLandZones][iCurACUZone]
                                    local tACULZTeamData = tACULZData[AiBotMap.subrefLZTeamData][iTeam]
                                    if not(tACULZTeamData[AiBotMap.subrefLZbCoreBase]) and tACULZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 300 then
                                        if (iCurACUHealthPercent <= 0.7 or tACULZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 1000) and (iCurACUHealthPercent <= 0.5 or tACULZTeamData[AiBotMap.subrefLZThreatAllyMobileDFTotal] < tACULZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]) then
                                            --Wnat to defend ACU
                                            --AddEnemyGroundUnitsToTargetsSubjectToAA(iPlateauOrZero, iLandOrWaterZone, iGunshipThreatFactorWanted, bCheckForAirAA, bOnlyIncludeIfMexToProtect, iGroundAAThresholdAdjust, bIgnoreMidpointPlayableCheck)
                                            AddEnemyGroundUnitsToTargetsSubjectToAA(iCurACUPlateauOrZero, iCurACUZone, 0.5 + iCurACUHealthPercent, false, false, nil, true)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Want to defend ACU from enemy units') end

                                        end
                                    end
                                end
                            end
                        end
                    end
                end

                --Check if want gunships to run to rally point if nearby enemy airAA (if give no targets for gunships then they will go to rally point or air staging), or if we have very weak AirAA
                local iGunshipThreatFactorForSameZone = 1.725 --This is referenced by the later zones threat factor wanted to ensure always higher
                if AiBotMap.bIsCampaignMap then
                    iGunshipThreatFactorForSameZone = 1.6
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDontHaveBuildingsOrACUInPlayableArea] then iGunshipThreatFactorForSameZone = 0.01 end
                elseif AiBotUtilities.bQuietModActive then iGunshipThreatFactorForSameZone = 1.9 --Gunships no longer get slowed down/lose fuel when taking damage, so won't be quite as bad in QUIET; Az also mentioned their damage should be similar to FAF levels, although concern from replays seen so far is effective DPS is significantly lower due to targeting
                elseif AiBotUtilities.bLoudModActive then iGunshipThreatFactorForSameZone = 3 --gunships are much weaker in LOUD; we will also increase the % threshold later as well by a further %
                end
                --If we have suffered significant gunship losses vs kills the nfurther increase the base factor
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] >= 10000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills] then
                    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbGunshipsHadAttackOrderLastCycle] then
                        --i.e. want to try and reduce the risk we decide to engage pre-10k losses; suffer a couple of losses when attacking, and that causes us to retreat from a fight we could've won
                        iGunshipThreatFactorForSameZone = iGunshipThreatFactorForSameZone * (1 + math.min(1.35, 0.9 * (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] - 10000) / AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills]))
                    else
                        iGunshipThreatFactorForSameZone = iGunshipThreatFactorForSameZone * (1 + math.min(1.5, 1 * (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] - 10000) / AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills]))
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Adjusted gunship threat base factor for high gunship losses, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills]..'; iGunshipThreatFactorForSameZone post update='..iGunshipThreatFactorForSameZone..'; AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbGunshipsHadAttackOrderLastCycle]='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbGunshipsHadAttackOrderLastCycle])) end
                end

                local bCheckForAirAA = true
                local iDistToStartCheckingForAirAA = 0
                if bHaveClearAirControl and (AiBotMap.bIsCampaignMap or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat] >= 10000) then
                    bCheckForAirAA = false
                    if not(AiBotMap.bIsCampaignMap) then
                        iDistToStartCheckingForAirAA = 225
                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDontHaveBuildingsOrACUInPlayableArea] then iDistToStartCheckingForAirAA = 1000 end
                    else iDistToStartCheckingForAirAA = 500
                    end
                end

                local bMidpointPlayableOverride = AiBotMap.bIsCampaignMap

                --Is there a vulnerable fatboy nearby?
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoVulnerableFatboys] and AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoVulnerableFatboys]) then
                    local iClosestFatboy = 300
                    local iCurFatboyDist
                    local oClosestFatboy
                    for iFatboy, oFatboy in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoVulnerableFatboys] do
                        if not(AiBotUnitInfo.IsUnitUnderwater(oFatboy)) then
                            iCurFatboyDist = AiBotUtilities.GetDistanceBetweenPositions(oFatboy:GetPosition(), oFrontGunship:GetPosition())
                            if iCurFatboyDist < iClosestFatboy then
                                oClosestFatboy = oFatboy
                                iClosestFatboy = iCurFatboyDist
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering priority enemy fatboy as gunship target. oClosestFatboy='..(oClosestFatboy.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestFatboy) or 'nil')..'; iClosestFatboy='..iClosestFatboy) end
                    if oClosestFatboy then
                        local iCurFatboyPlateau, iCurFatboyZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oClosestFatboy:GetPosition())
                        if iCurFatboyPlateau and iCurFatboyZone then
                            --AddEnemyGroundUnitsToTargetsSubjectToAA(iPlateauOrZero, iLandOrWaterZone, iGunshipThreatFactorWanted, bCheckForAirAA, bOnlyIncludeIfMexToProtect, iGroundAAThresholdAdjust, bIgnoreMidpointPlayableCheck)
                            AddEnemyGroundUnitsToTargetsSubjectToAA(iCurFatboyPlateau, iCurFatboyZone, iGunshipThreatFactorForSameZone * (1 + 0.3 * iClosestFatboy / 300), bCheckForAirAA, false, nil, bMidpointPlayableOverride)
                            if bDebugMessages == true then LOG(sFunctionRef..': Finished considering whether to add units in the zone with the fatboy as targets, gunship factor expected to be the threshold='..iGunshipThreatFactorForSameZone * (1 + 0.3 * iClosestFatboy / 300)) end
                        end
                    end
                end

                --Telesnipe defence - if no targets yet and enemy has queued up a snipe attempt, then have gunships move there
                if AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftRecentEnemyTeleportDetails]) == false and oFrontGunship then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want gunships to prevent a snipe attempt if it isnt too far away') end
                    local iClosestTeleportDist = 500 --If assume a teleport allows about 45s for the unit to teleport there then teleport away (will vary following FAF update), and gunships move at 10 per sec, then if we only consider telesnipe locations within 500 it should cover cases where the gunships are close enough to feasibly help
                    local iCurTeleportDist
                    for iTeleportEntry, tTeleportDetails in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftRecentEnemyTeleportDetails] do
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering teleport entry for the location '..repru(tTeleportDetails[AiBotTeam.subreftTeleportTarget])..'; Dist to front gunship='..AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), tTeleportDetails[AiBotTeam.subreftTeleportTarget])) end
                        if tTeleportDetails[AiBotTeam.subreftTeleportTarget][2] >= AiBotMap.iMapWaterHeight - 1 then --dont want to try and target ACUs significantly underwater
                            iCurTeleportDist = AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), tTeleportDetails[AiBotTeam.subreftTeleportTarget])
                            local tTeleportLZData, tTeleportLZTeamData = AiBotMap.GetLandOrWaterZoneData(tTeleportDetails[AiBotTeam.subreftTeleportTarget], true, iTeam)
                            if iCurTeleportDist < iClosestTeleportDist or (not(tTeleportTargetToMoveTo) and tTeleportLZTeamData[AiBotMap.refiModDistancePercent] <= 0.25 and iCurTeleportDist <= 800 and (ScenarioInfo.Options.Victory == 'demoralization' or ScenarioInfo.Options.Victory == 'decapitation')) then
                                --Is the target locatin one we want to preemptively defend?
                                if bDebugMessages == true then LOG(sFunctionRef..': Deciding if we want to defend the location, SValue='..tTeleportLZTeamData[AiBotMap.subrefLZSValue]..'; Core base='..tostring(tTeleportLZTeamData[AiBotMap.subrefLZbCoreBase])..'; Table of allied acus empty?='..tostring(AiBotUtilities.IsTableEmpty(tTeleportLZTeamData[AiBotMap.subrefAlliedACU]))..'; Mod dist%='..tTeleportLZTeamData[AiBotMap.refiModDistancePercent]..'; Enemy groundAA='..tTeleportLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]) end
                                if tTeleportLZTeamData[AiBotMap.subrefLZSValue] >= 3000 or tTeleportLZTeamData[AiBotMap.subrefLZbCoreBase] or AiBotUtilities.IsTableEmpty(tTeleportLZTeamData[AiBotMap.subrefAlliedACU]) == false or (tTeleportLZTeamData[AiBotMap.refiModDistancePercent] < 0.4 and tTeleportLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] == 0 and (tTeleportLZTeamData[AiBotMap.refiModDistancePercent] < 0.15 or (tTeleportLZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) > 1000)) then
                                    iClosestTeleportDist = iCurTeleportDist
                                    tTeleportTargetToMoveTo = {tTeleportDetails[AiBotTeam.subreftTeleportTarget][1], tTeleportDetails[AiBotTeam.subreftTeleportTarget][2], tTeleportDetails[AiBotTeam.subreftTeleportTarget][3]}
                                    if bDebugMessages == true then LOG(sFunctionRef..': recording as a preemptive teleport location target') end
                                end
                            end
                        end
                    end
                end
                if not(tTeleportTargetToMoveTo) then
                    local iSearchDistance = 60
                    if bDebugMessages == true then LOG(sFunctionRef..': About to check if shoudl run due to high AA near where gunships are, Is there AA near gunship P'..iGunshipPlateauOrZero..'; Z'..iGunshipLandOrWaterZone..'; iMaxEnemyAirAA='..iMaxEnemyAirAA..'; iOurGunshipThreat='..iOurGunshipThreat..'; Is there too much AA='..tostring(IsThereAANearLandOrWaterZone(iTeam, iGunshipPlateauOrZero, iGunshipLandOrWaterZone, (iGunshipPlateauOrZero == 0), iOurGunshipThreat / iGunshipThreatFactorForSameZone, iMaxEnemyAirAA                  , iSearchDistance,                               oFrontGunship:GetPosition(),false,                   oFrontGunship:GetPosition(),            math.min(30, 10+iAvailableGunshipCount)))..'; bOnlyRunFromAirAAIfInRange='..tostring(bOnlyRunFromAirAAIfInRange or false)) end
                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] < 3 or (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] and ((bHaveClearAirControl and iDistToSupport <= 100) or iDistToSupport <= 90)) then iSearchDistance = 40 end
                    if bOnlyRunFromAirAAIfInRange then bOnlyRunFromAirAAIfInRange = false end
                    local oFrontAAGunship = oFrontGunship
                    if bOnlyRunFromAirAAIfInRange then
                        local iFrontGunshipDistLessRangeValue = - math.max(30, (oFrontAAGunship[AiBotUnitInfo.refiAARange] or 0))
                        local iCurDistLessRangeValue
                        for iUnit, oUnit in tGunshipsNearFront do
                            if (oUnit[AiBotUnitInfo.refiAARange] or 0) > 30 then
                                iCurDistLessRangeValue = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oFrontAAGunship:GetPosition()) - oUnit[AiBotUnitInfo.refiAARange]
                                if iCurDistLessRangeValue < iFrontGunshipDistLessRangeValue then
                                    iFrontGunshipDistLessRangeValue = iCurDistLessRangeValue
                                    oFrontAAGunship = oUnit
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': oFrontAAGunship='..oFrontAAGunship.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFrontAAGunship)..' with AARange='..(oFrontAAGunship[AiBotUnitInfo.refiAARange] or 0)) end
                    end
                    --                                     IsThereAANearLandOrWaterZone(iTeam, iPlateau,             iLandOrWaterZone,       bIsWaterZone,                               iOptionalGroundThreatThreshold, iOptionalAirAAThreatThreshold, iOptionalMaxDistToEdgeOfAdjacentZone, tOptionalStartPointForEdgeOfAdacentZone, bIncludeEnemyGroundAAInAirAAThreat, tOptionalDetailedGroundAAPositionCheck, iIncludeForDetailedIfWithinThisDistOfBeingInRange))
                    if (bOnlyRunFromAirAAIfInRange and not(IsThereAANearLandOrWaterZone(iTeam, iGunshipPlateauOrZero, iGunshipLandOrWaterZone, (iGunshipPlateauOrZero == 0), iOurGunshipThreat / iGunshipThreatFactorForSameZone, -1                  , iSearchDistance,                               oFrontGunship:GetPosition(),     false,                   oFrontGunship:GetPosition(),            math.min(30, 10+iAvailableGunshipCount))) and (not(InRangeOfEnemyAirAA(oFrontAAGunship)) or not(IsThereAANearLandOrWaterZone(iTeam, iGunshipPlateauOrZero, iGunshipLandOrWaterZone, (iGunshipPlateauOrZero == 0), iOurGunshipThreat / iGunshipThreatFactorForSameZone, iMaxEnemyAirAA                  , iSearchDistance,                               oFrontGunship:GetPosition(),false,                   oFrontGunship:GetPosition(),            math.min(30, 10+iAvailableGunshipCount)))))
                            or (not( bOnlyRunFromAirAAIfInRange) and not(IsThereAANearLandOrWaterZone(iTeam, iGunshipPlateauOrZero, iGunshipLandOrWaterZone, (iGunshipPlateauOrZero == 0), iOurGunshipThreat / iGunshipThreatFactorForSameZone, iMaxEnemyAirAA                  , iSearchDistance,                               oFrontGunship:GetPosition(),false,                   oFrontGunship:GetPosition(),            math.min(30, 10+iAvailableGunshipCount)))) then

                        --no nearby enemy air threat so can just evaluate each land zone or water zone on its own merits - cycle through each in order of distance, but first consider adjacent locations

                        --First consider the land/water zone the gunship is in at the moment
                        --AddEnemyGroundUnitsToTargetsSubjectToAA(iPlateauOrZero, iLandOrWaterZone, iGunshipThreatFactorWanted, bCheckForAirAA, bOnlyIncludeIfMexToProtect, iGroundAAThresholdAdjust, bIgnoreMidpointPlayableCheck)
                        AddEnemyGroundUnitsToTargetsSubjectToAA(iGunshipPlateauOrZero, iGunshipLandOrWaterZone, iGunshipThreatFactorForSameZone, false, nil, nil, true) --dont check for airaa since we already checked above
                        if bDebugMessages == true then LOG(sFunctionRef..': Is tEnemyGroundOrGunshipTargets empty after considering enemies in the same LZ/WZ as gunship='..tostring(AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets))) end
                        if AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets) then
                            --Is there groundAA in the current plateau/water zone (i.e. there are enemies but we have chosen not to attack due to the threat)?
                            if (tGunshipLandOrWaterZoneData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) > 0 or (tGunshipLandOrWaterZoneData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) > 0 then
                                --Enemy has AA in the same LZ as our gunships and we dont want to attack enemies, so retreat
                                if bDebugMessages == true then LOG(sFunctionRef..': Enemy GroundAA threat exists in same zone as gunships and we have no targets so want to retreat') end
                            else
                                --If lack AirAA then only consider adjacent zones to the gunship, provided one of them has ground to air threat of at least 200
                                local iMaxDefensiveRange = 50
                                if bDebugMessages == true then LOG(sFunctionRef..': COnsidering if we want to use gunships defnesively, our AA threat='..AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat]..'; iOurGunshipAA='..iOurGunshipAA..'; Enemy AirAA threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]) end
                                if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] + iOurGunshipAA < math.max(100, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 0.7) and (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] > 0 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] > 0) then
                                    local iNearbyGroundToAirThreat = (tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) + (tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0)
                                    if AiBotUtilities.IsTableEmpty(tGunshipLandOrWaterZoneData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                                        for iEntry, tSubtable in tGunshipLandOrWaterZoneData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                                            if tSubtable[AiBotMap.subrefiDistance] <= 110 then
                                                iNearbyGroundToAirThreat = iNearbyGroundToAirThreat + 0.5 * (tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) + (tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0)
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': iNearbyGroundToAirThreat='..iNearbyGroundToAirThreat) end
                                    if iNearbyGroundToAirThreat < 200 then
                                        bUseDefensively = true
                                        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] < 3 then
                                            iMaxDefensiveRange = 150
                                        end
                                        if AiBotUtilities.GetDistanceBetweenPositions(tGunshipLandOrWaterZoneData[AiBotMap.subrefMidpoint], tGunshipLandOrWaterZoneTeamData[AiBotMap.reftClosestFriendlyBase]) >= 150 then iMaxDefensiveRange = math.min(50, iMaxDefensiveRange * 0.5) end
                                    end
                                end
                                if not(bUseDefensively) and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] and iOurGunshipAA < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] then
                                    bUseDefensively = true
                                    --If enemy appears to be attacking us be more likely to retreat
                                elseif iEnemyAirAAThreatNearGunship >= 10000 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] > iOurGunshipAA then
                                    if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then
                                        bUseDefensively = true
                                    else
                                        --Check for nearby friendly AirAA threat
                                        local tNearbyAirAA = oFrontGunship:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryAirAA - AiBotUnitInfo.refCategoryGunship, oFrontGunship:GetPosition(), 100, 'Ally')
                                        local iOurNearbyAirAA = AiBotUnitInfo.GetAirThreatLevel(tNearbyAirAA, false, true, false, false, false, false)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy has strong nearby airaa threat, iOurNearbyAirAA excl gunships='..iOurNearbyAirAA..'; iOurGunshipAA='..iOurGunshipAA..'; iEnemyAirAAThreatNearGunship='..iEnemyAirAAThreatNearGunship..'; Total enemy AirAA threat='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]..'; bHaveClearAirControl='..tostring(bHaveClearAirControl)) end
                                        if iOurGunshipAA + iOurNearbyAirAA < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] and iOurGunshipAA < 2 * iEnemyAirAAThreatNearGunship then
                                            bUseDefensively = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will use gunships defensively due to enemy AirAA threat') end
                                        elseif not(bHaveClearAirControl) and iOurGunshipAA + iOurNearbyAirAA < AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 1.5 and iOurGunshipAA < 2.5 * iEnemyAirAAThreatNearGunship then
                                            bUseDefensively = true
                                            if bDebugMessages == true then LOG(sFunctionRef..': Dont have clear air control so will use gunships defensively due to nearby enemy AirAA threat') end
                                        end
                                    end
                                end
                                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDontHaveBuildingsOrACUInPlayableArea] then iMaxDefensiveRange = math.max(iMaxDefensiveRange, 1000) end

                                if bDebugMessages == true then LOG(sFunctionRef..': oFrontGunship='..oFrontGunship.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFrontGunship)..'; iGunshipPlateauOrZero='..(iGunshipPlateauOrZero or 'nil')..'; iGunshipLandOrWaterZone='..(iGunshipLandOrWaterZone or 'nil')..'; bUseDefensively='..tostring(bUseDefensively)..'; position='..repru(oFrontGunship:GetPosition())) end

                                RecordOtherLandAndWaterZonesByDistance(tGunshipLandOrWaterZoneData)
                                if AiBotUtilities.IsTableEmpty(tGunshipLandOrWaterZoneData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                                    local iGunshipThreatFactorWanted
                                    local iPostFirstTargetCount = 0 --used so once we have a target we will still consider a few extra zones in case they are more important
                                    local iDistanceOfFirstTarget
                                    local iPostTargetMaxDistance = 80
                                    local iPostTargetMaxZoneCheck = 4
                                    local iLowValueZoneThreshold = math.min(4000, 0.1 * iOurGunshipThreat)
                                    local iHighestEnemyValueZone = 0
                                    local iDistFromFrontGunshipToMidpoint = AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), tGunshipLandOrWaterZoneData[AiBotMap.subrefMidpoint])
                                    local iGunshipZoneRadius

                                    if iGunshipPlateauOrZero == 0 then
                                        iGunshipZoneRadius = ((tGunshipLandOrWaterZoneData[AiBotMap.subrefWZMaxSegX] - tGunshipLandOrWaterZoneData[AiBotMap.subrefWZMinSegX]) + (tGunshipLandOrWaterZoneData[AiBotMap.subrefWZMaxSegZ] - tGunshipLandOrWaterZoneData[AiBotMap.subrefWZMinSegZ])) * AiBotMap.iLandZoneSegmentSize * 0.5
                                    else
                                        iGunshipZoneRadius = ((tGunshipLandOrWaterZoneData[AiBotMap.subrefLZMaxSegX] - tGunshipLandOrWaterZoneData[AiBotMap.subrefLZMinSegX]) + (tGunshipLandOrWaterZoneData[AiBotMap.subrefLZMaxSegZ] - tGunshipLandOrWaterZoneData[AiBotMap.subrefLZMinSegZ])) * AiBotMap.iLandZoneSegmentSize * 0.5
                                    end

                                    local iMinThreatFactor = iGunshipThreatFactorForSameZone * 1.15
                                    if bDebugMessages == true then LOG(sFunctionRef..': iDistFromFrontGunshipToMidpoint='..iDistFromFrontGunshipToMidpoint..'; iPostTargetMaxDistance='..iPostTargetMaxDistance..'; iGunshipZoneRadius='..iGunshipZoneRadius) end
                                    for iEntry, tSubtable in tGunshipLandOrWaterZoneData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                                        --Once found a zone with targets, use that unless we have another zone where mex is under threat that we want to consider instaed
                                        if bUseDefensively and tSubtable[AiBotMap.subrefiDistance] > iMaxDefensiveRange then break end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if P'..tSubtable[AiBotMap.subrefiPlateauOrPond]..'Z'..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..' is in range, subrefiDistance='..tSubtable[AiBotMap.subrefiDistance]..'; iDistanceOfFirstTarget='..(iDistanceOfFirstTarget or 'nil')..'; Dist from front gunship to midpoint of target zone (if it is a land zone)='..AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), (AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]][AiBotMap.subrefMidpoint] or {0,0,0}))..'; subrefbIsWaterZone='..tostring(tSubtable[AiBotMap.subrefbIsWaterZone] or false)) end
                                        if iPostFirstTargetCount == 0 or (tSubtable[AiBotMap.subrefiDistance] <= iDistanceOfFirstTarget + iPostTargetMaxDistance) or (not(tSubtable[AiBotMap.subrefbIsWaterZone]) and tSubtable[AiBotMap.subrefiDistance] <= iDistanceOfFirstTarget + iPostTargetMaxDistance + iDistFromFrontGunshipToMidpoint and AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]][AiBotMap.subrefMidpoint]) <= tSubtable[AiBotMap.subrefiDistance]) then
                                            if bMidpointPlayableOverride and tSubtable[AiBotMap.subrefiDistance] >= 120 then bMidpointPlayableOverride = false end
                                            if not(bCheckForAirAA) and tSubtable[AiBotMap.subrefiDistance] > iDistToStartCheckingForAirAA then bCheckForAirAA = true end
                                            if tSubtable[AiBotMap.subrefiDistance] <= 110 or AiBotMap.bIsCampaignMap then
                                                if tSubtable[AiBotMap.subrefiDistance] <= 70 then iGunshipThreatFactorWanted = iGunshipThreatFactorForSameZone + 1.25 --3
                                                else
                                                    iGunshipThreatFactorWanted = iGunshipThreatFactorForSameZone + 1.75 --3.5
                                                end
                                                if AiBotMap.bIsCampaignMap then --lower threshold for gunships to attack
                                                    if tSubtable[AiBotMap.subrefiDistance] <= 350 then iGunshipThreatFactorWanted = iGunshipThreatFactorWanted * 0.75
                                                    else iGunshipThreatFactorWanted = iGunshipThreatFactorWanted * 0.85
                                                    end

                                                    --Large numbers of T2 gunships in campaign - lower threshold to attack
                                                    if iOurGunshipThreat >= 10000 and (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] < 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.refbActiveDefenseObjective]) then
                                                        iGunshipThreatFactorWanted = math.max(iMinThreatFactor, iGunshipThreatFactorWanted * 0.8)
                                                    else
                                                        iGunshipThreatFactorWanted = math.max(2.05, iGunshipThreatFactorWanted)
                                                    end
                                                    if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDontHaveBuildingsOrACUInPlayableArea] then iGunshipThreatFactorWanted = 0.01 end
                                                elseif AiBotUtilities.bLoudModActive then
                                                    --iGunshipThreatFactorWanted = iGunshipThreatFactorWanted * 1.1 --Prev used for LCE

                                                    iGunshipThreatFactorWanted = iGunshipThreatFactorWanted * 1.3 --We already have a higher base factor in LOUD, so this is essentially multiplying any further mods above
                                                end
                                            else
                                                if tSubtable[AiBotMap.subrefiDistance] <= 200 then
                                                    iGunshipThreatFactorWanted = 4
                                                else
                                                    iGunshipThreatFactorWanted = 4.5
                                                end
                                                if AiBotUtilities.bQuietModActive then --make gunships less likely to attack
                                                    iGunshipThreatFactorWanted = iGunshipThreatFactorWanted * 1.1
                                                elseif AiBotUtilities.bLoudModActive then
                                                    iGunshipThreatFactorWanted = iGunshipThreatFactorWanted * 1.3 --We already have a higher base factor in LOUD, so this is essentially multiplying any further mods above
                                                end
                                            end
                                            --Reduce threat factor if we have air control
                                            if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                                                if bHaveClearAirControl then
                                                    iGunshipThreatFactorWanted = math.max(math.min(2.7, iGunshipThreatFactorWanted), iGunshipThreatFactorWanted * 0.8)
                                                else
                                                    iGunshipThreatFactorWanted = math.max(math.min(3.3, iGunshipThreatFactorWanted), iGunshipThreatFactorWanted * 0.9)
                                                end
                                            end
                                            --Non-LOUD - Reduce gunship threat factor if we have T3 gunships and our overall threat factor means enemy wouldnt have more than 3 SAMs (even 4 SAMs shouldnt do enough damage to 1-shot a gunship)
                                            if (not(AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) or (AiBotUtilities.bQuietModActive and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipLosses] < math.max(10000, AiBotTeam.tTeamData[iTeam][AiBotTeam.refiGunshipKills]))) and bHaveT3Gunships and iGunshipThreatFactorWanted > 2.05 and (iOurGunshipThreat / iGunshipThreatFactorWanted <= 5000 or tSubtable[AiBotMap.subrefiDistance] <= 60) then --3 sams is 4800
                                                if AiBotMap.bIsCampaignMap then
                                                    iGunshipThreatFactorWanted = math.max(2.05, iGunshipThreatFactorWanted * 0.6)
                                                else
                                                    iGunshipThreatFactorWanted = math.max(2.05, iGunshipThreatFactorWanted * 0.8)
                                                end
                                            end

                                            if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbGunshipsHadAttackOrderLastCycle] then iGunshipThreatFactorWanted = iGunshipThreatFactorWanted * 0.85 end
                                            --Make sure our threat factor is always higher than the base
                                            if iGunshipThreatFactorWanted < iMinThreatFactor then iGunshipThreatFactorWanted = iMinThreatFactor end
                                            if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                                --AddEnemyGroundUnitsToTargetsSubjectToAA(iPlateauOrZero, iLandOrWaterZone, iGunshipThreatFactorWanted, bCheckForAirAA, bOnlyIncludeIfMexToProtect, iGroundAAThresholdAdjust, bIgnoreMidpointPlayableCheck)
                                                AddEnemyGroundUnitsToTargetsSubjectToAA(0, tSubtable[AiBotMap.subrefiLandOrWaterZoneRef], iGunshipThreatFactorWanted, bCheckForAirAA, (iPostFirstTargetCount > 0 and (tSubtable[AiBotMap.subrefiDistance] <= 100)), nil, bMidpointPlayableOverride)
                                            else
                                                AddEnemyGroundUnitsToTargetsSubjectToAA(tSubtable[AiBotMap.subrefiPlateauOrPond], tSubtable[AiBotMap.subrefiLandOrWaterZoneRef], iGunshipThreatFactorWanted, bCheckForAirAA, (iPostFirstTargetCount > 0 and (tSubtable[AiBotMap.subrefiDistance] <= 100)), nil, bMidpointPlayableOverride)
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Have just finished calling AddEnemyGroundUnitsToTargetsSubjectToAA for zone '..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..', PlateauOrPond='..tSubtable[AiBotMap.subrefiPlateauOrPond]..'; Is table of enemy targets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets))..'; Is tNewlyAddedEnemies empty='..tostring(AiBotUtilities.IsTableEmpty(tNewlyAddedEnemies))..'; tSubtable='..repru(tSubtable)..'; iGunshipThreatFactorWanted='..iGunshipThreatFactorWanted..'; iMinThreatFactor (i.e. gunship threat factor cant be below this, which is a % of the same zone threat factor)='..iMinThreatFactor..'; AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbGunshipsHadAttackOrderLastCycle]='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbGunshipsHadAttackOrderLastCycle] or false)..'; subrefiDistance='..tSubtable[AiBotMap.subrefiDistance]) end
                                            if AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets) == false then
                                                --We have enemies to potentially target - however if tthey are of very low value relative to gunships want to search for other more high value zones that wea re interested in targeting
                                                local iCurEnemyPlateauOrZero
                                                if tSubtable[AiBotMap.subrefbIsWaterZone] then iCurEnemyPlateauOrZero = 0
                                                else iCurEnemyPlateauOrZero = tSubtable[AiBotMap.subrefiPlateauOrPond]
                                                end
                                                local iCurEnemyZone = tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]

                                                local iMassValueOfTargets = AiBotUnitInfo.GetMassCostOfUnits(tNewlyAddedEnemies, true)
                                                local tCurEnemyZoneData, tCurEnemyTeamData
                                                if iCurEnemyPlateauOrZero > 0 then
                                                    --Land zone
                                                    tCurEnemyZoneData = AiBotMap.tAllPlateaus[iCurEnemyPlateauOrZero][AiBotMap.subrefPlateauLandZones][iCurEnemyZone]
                                                    tCurEnemyTeamData = tCurEnemyZoneData[AiBotMap.subrefLZTeamData][iTeam]

                                                else
                                                    --Water zone
                                                    tCurEnemyZoneData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurEnemyZone]][AiBotMap.subrefPondWaterZones][iCurEnemyZone]
                                                    tCurEnemyTeamData = tCurEnemyZoneData[AiBotMap.subrefWZTeamData][iTeam]
                                                end

                                                if bDebugMessages == true then LOG(sFunctionRef..': Have targets for this zone, p'..iCurEnemyPlateauOrZero..'Z'.. iCurEnemyZone..' iPostFirstTargetCount='..iPostFirstTargetCount..'; bDontLookForMoreTargets='..tostring(bDontLookForMoreTargets)..'; iMassValueOfTargets='..iMassValueOfTargets..'; iLowValueZoneThreshold='..iLowValueZoneThreshold) end
                                                if iPostFirstTargetCount == 0 then
                                                    iDistanceOfFirstTarget = tSubtable[AiBotMap.subrefiDistance]
                                                    --Get mass value of targets

                                                    if iMassValueOfTargets < iLowValueZoneThreshold and ((tCurEnemyTeamData[AiBotMap.subrefLZSValue] or 0) < 100 or iMassValueOfTargets * 5 < (tCurEnemyTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)) then
                                                        iPostTargetMaxDistance = math.min(750, math.max(250, AiBotMap.iMapSize * 0.5))
                                                        iPostTargetMaxZoneCheck = 100
                                                        bConsiderIgnoringEnemiesInLowValueZones = true
                                                    else
                                                        iPostTargetMaxDistance = 80
                                                        iPostTargetMaxZoneCheck = 4
                                                    end
                                                    --If we are close to gunship zone then increase maxzonecheck to reduce issues where e.g. gunship is near edge of this zone in other direction to the first zone we have picked
                                                    if tSubtable[AiBotMap.subrefiDistance] <= 80 and ( tSubtable[AiBotMap.subrefiDistance] <= 40 or iDistFromFrontGunshipToMidpoint >= 30) then iPostTargetMaxZoneCheck = iPostTargetMaxZoneCheck + 2 end

                                                    if bDebugMessages == true then LOG(sFunctionRef..': iMassValueOfTargets='..iMassValueOfTargets..'; iOurGunshipThreat='..iOurGunshipThreat..'; iPostTargetMaxDistance='..iPostTargetMaxDistance..'; iPostTargetMaxZoneCheck='..iPostTargetMaxZoneCheck..'; SValue='..(tCurEnemyTeamData[AiBotMap.subrefLZSValue] or 'nil')) end
                                                end
                                                iPostFirstTargetCount = iPostFirstTargetCount + 1
                                                if (bConsiderIgnoringEnemiesInLowValueZones and (iMassValueOfTargets > math.max(iLowValueZoneThreshold, iHighestEnemyValueZone * 2) or (tCurEnemyTeamData[AiBotMap.subrefLZSValue] or 0) > 100 and iMassValueOfTargets * 5 > (tCurEnemyTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0))) or (not(bConsiderIgnoringEnemiesInLowValueZones) and iMassValueOfTargets > iLowValueZoneThreshold and iOurGunshipThreat > 12000) then
                                                    --require units to be in this zone
                                                    bConsiderIgnoringEnemiesInLowValueZones = true
                                                    table.insert(tiPlateauAndZoneForEnemiesToBeIn, {iCurEnemyPlateauOrZero, iCurEnemyPlateauOrZero})
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding zone as one for enemies to be in to be selected, iCurEnemyPlateauOrZero='..iCurEnemyPlateauOrZero..'; iCurEnemyPlateauOrZero='..iCurEnemyPlateauOrZero..'; iMassValueOfTargets='..iMassValueOfTargets..'; SIze of enemy units='..table.getn(tEnemyGroundOrGunshipTargets)..'; SValue='..(tCurEnemyTeamData[AiBotMap.subrefLZSValue] or 'nil')) end
                                                end

                                                iHighestEnemyValueZone = math.max(iHighestEnemyValueZone, iMassValueOfTargets)
                                                if bDebugMessages == true then LOG(sFunctionRef..': ihighestEnemyValueZone='..iHighestEnemyValueZone..'; iMassValueOfTargets (for the most recently considered zone)='..iMassValueOfTargets) end
                                                if iPostFirstTargetCount >= iPostTargetMaxZoneCheck or bDontLookForMoreTargets then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Been through the maximum number of zones to check, will abort, bDontLookForMoreTargets='..tostring(bDontLookForMoreTargets)..'; iPostTargetMaxZoneCheck='..iPostTargetMaxZoneCheck) end
                                                    break
                                                elseif iPostTargetMaxZoneCheck > 4 then
                                                    local iMassValueOfTargets = AiBotUnitInfo.GetMassCostOfUnits(tEnemyGroundOrGunshipTargets, true)
                                                    if iMassValueOfTargets > iLowValueZoneThreshold or ((tCurEnemyTeamData[AiBotMap.subrefLZSValue] or 0) > 100 and iMassValueOfTargets * 5 > (tCurEnemyTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)) then
                                                        iPostTargetMaxZoneCheck = math.min(6, iPostTargetMaxZoneCheck) --Incase we increased from 4 to 6 above due to first zone being very close to gunship
                                                        iPostTargetMaxDistance = 80
                                                        if iPostFirstTargetCount < iPostTargetMaxZoneCheck then
                                                            bConsiderIgnoringEnemiesInLowValueZones = false
                                                        else
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Ending loop as have passed iPostTargetMaxZoneCheck, iMassValueOfTargets='..iMassValueOfTargets) end
                                                            break
                                                        end
                                                    end
                                                end
                                            end
                                        elseif bDontLookForMoreTargets or (iPostFirstTargetCount > 0 and tSubtable[AiBotMap.subrefiDistance] > iDistanceOfFirstTarget + iPostTargetMaxDistance + iGunshipZoneRadius) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Ending loop, bDontLookForMoreTargets='..tostring(bDontLookForMoreTargets)..'; iPostFirstTargetCount='..iPostFirstTargetCount) end
                                            break
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end

        --Further away gunships - consider whether we want to move closer to the front gunship, if it is in the playable area
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want further away gunships to move towards front, is table of gunships not near front empty='..tostring(AiBotUtilities.IsTableEmpty(tGunshipsNotNearFront))..'; Is front gunship in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(oFrontGunship:GetPosition()))..'; tGunshipLandOrWaterZoneTeamData[AiBotMap.refiEnemyAirAAThreat]='..tGunshipLandOrWaterZoneTeamData[AiBotMap.refiEnemyAirAAThreat]..'; iOurGunshipAA='..iOurGunshipAA..'; Front gunship groundAA='..(tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 'nil')..'; bHaveGunshipsVeryFarFromFront='..tostring(bHaveGunshipsVeryFarFromFront)) end
        local bGivenOrdersToFarFromFrontGunships = false
        local tMovePoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
        if AiBotUtilities.IsTableEmpty(tGunshipsNotNearFront) == false and (bHaveGunshipsVeryFarFromFront or AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets)) and (not(AiBotMap.bIsCampaignMap) or AiBotConditions.IsLocationInPlayableArea(oFrontGunship:GetPosition())) then
            bGivenOrdersToFarFromFrontGunships = true
            local tiPlateauAndZonesConsidered = {}
            local tiPlateauAndZonesForHighHealthConsidered
            local bCurEntrySafe
            local bAlwaysConsolidateHighHealthGunships = false
            local iGroundAAHighHealthThreatThreshold
            if ((tGunshipLandOrWaterZoneTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) <= math.max(100, iOurGunshipThreat * 0.1, iOurGunshipAA) or (tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or tGunshipLandOrWaterZoneTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) > 0) then
                bAlwaysConsolidateHighHealthGunships = true
                tiPlateauAndZonesForHighHealthConsidered = {}
                if iOurGunshipThreat >= 8000 then --Assume we have t3 gunships
                    iGroundAAHighHealthThreatThreshold = 500
                else
                    iGroundAAHighHealthThreatThreshold = 180
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': bAlwaysConsolidateHighHealthGunships='..tostring(bAlwaysConsolidateHighHealthGunships)) end
            local iDistToProceedToFront = 120
            if bAlwaysConsolidateHighHealthGunships then
                local iNearbyGunshipThreatToSecondGunship = 0
                local oClosestGunshipNotNearFront
                local iClosestGunshipNotNearFront = 100000
                local toGunshipsToConsiderThreatGrouping = {}
                for iUnit, oUnit in tGunshipsNotNearFront do
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oFrontGunship:GetPosition())
                    if iCurDist <= iDistToProceedToFront then
                        --This gunship will be proceeding anyway so dont need to consider its threat
                    else
                        if iCurDist < iClosestGunshipNotNearFront then
                            oClosestGunshipNotNearFront = oUnit
                            iClosestGunshipNotNearFront = iCurDist
                            table.insert(toGunshipsToConsiderThreatGrouping, oUnit)
                        end
                    end
                end
                if oClosestGunshipNotNearFront and AiBotUtilities.IsTableEmpty(toGunshipsToConsiderThreatGrouping) == false then
                    for iUnit, oUnit in toGunshipsToConsiderThreatGrouping do
                        if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oClosestGunshipNotNearFront:GetPosition()) <= 40 then
                            iNearbyGunshipThreatToSecondGunship = iNearbyGunshipThreatToSecondGunship + (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit))
                        end
                    end
                end
                iGroundAAHighHealthThreatThreshold = math.max(iGroundAAHighHealthThreatThreshold, iNearbyGunshipThreatToSecondGunship * 0.15)
                if bDebugMessages == true then LOG(sFunctionRef..': iNearbyGunshipThreatToSecondGunship='..iNearbyGunshipThreatToSecondGunship..'; iGroundAAHighHealthThreatThreshold='..iGroundAAHighHealthThreatThreshold) end
            end

            for iUnit, oUnit in tGunshipsNotNearFront do
                if ((oUnit:GetFuelRatio() < 0.6 and oUnit:GetFuelRatio() >= 0) or AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= 0.85) and not(EntityCategoryContains(categories.CANNOTUSEAIRSTAGING, oUnit.UnitId)) then
                    table.insert(tGunshipsForRefueling, oUnit)
                    if bDebugMessages == true then LOG(sFunctionRef..': Will send gunship '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' for refueling') end
                    --If we almost at full health and enemy has no AirAA in the front gunship zone, then move closer
                elseif bAlwaysConsolidateHighHealthGunships and AiBotUnitInfo.GetUnitHealthPercent(oUnit) >= 0.95 then
                    if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oFrontGunship:GetPosition()) <= math.max(iDistToProceedToFront, iCloseToFrontThreshold) then
                        bCurEntrySafe = true
                    else
                        local iCurPlateauOrZero, iCurZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                        if tiPlateauAndZonesConsidered[iCurPlateauOrZero][iCurZone] then
                            bCurEntrySafe = true
                        elseif tiPlateauAndZonesForHighHealthConsidered[iCurPlateauOrZero][iCurZone] == nil then
                            bCurEntrySafe = false
                            local tPositionTowardsFront = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oFrontGunship:GetPosition()), iCloseToFrontThreshold, true, false, false)
                            if tPositionTowardsFront then
                                local iFrontPlateauOrZero, iFrontZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tPositionTowardsFront)
                                --                  DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck, bReturnGroundAAUnitsAlongsideAAThreat, tOptionalEndMidpointAdjustForDetailedCheck, bOptionalIgnoreOppositeDirectionZones, bIncludeEnemyGroundAAInAirAAThreat, bAssumeWontTargetInterimAAForDetailedCheck)
                                bCurEntrySafe = not(DoesEnemyHaveAAThreatAlongPath(iTeam, iCurPlateauOrZero, iCurZone,           iFrontPlateauOrZero, iFrontZone,                     true,          iGroundAAHighHealthThreatThreshold, -1,       false,             iAirSubteam, true,                 false,                           oUnit:GetPosition(),                          false,                                  oFrontGunship:GetPosition(),                    true))
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if it is safe for high health gunship not near the front to move towards front gunship, iFrontPlateauOrZero='..(iFrontPlateauOrZero or 'nil')..'; iFrontZone='..(iFrontZone or 'nil')..'; iCurPlateauOrZero='..iCurPlateauOrZero..'; iCurZone='..iCurZone..'; bCurEntrySafe='..tostring(bCurEntrySafe)..'; this will be applied to oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                                if not(tiPlateauAndZonesForHighHealthConsidered[iCurPlateauOrZero]) then tiPlateauAndZonesForHighHealthConsidered[iCurPlateauOrZero] = {} end
                                tiPlateauAndZonesForHighHealthConsidered[iCurPlateauOrZero][iCurZone] = bCurEntrySafe
                            end
                        else
                            bCurEntrySafe = tiPlateauAndZonesForHighHealthConsidered[iCurPlateauOrZero][iCurZone]
                        end
                    end
                    if bCurEntrySafe then
                        if bDebugMessages == true then LOG(sFunctionRef..': Moving unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to be closer to front gunship despite the general retreat order') end
                        AiBotOrders.IssueTrackedMove(oUnit, oFrontGunship:GetPosition(), 10, false, 'FACons2', false)
                    else
                        if not(tGunshipsToRetreatNotRefuel) then tGunshipsToRetreatNotRefuel = {} end
                        table.insert(tGunshipsToRetreatNotRefuel, oUnit)
                        if bDebugMessages == true then LOG(sFunctionRef..': Cur entry isnt safe so will include in table of gunships to retreat') end
                    end
                else
                    local iCurPlateauOrZero, iCurZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                    if tiPlateauAndZonesConsidered[iCurPlateauOrZero][iCurZone] == nil then --will approximate by assuming every gunship in the same zone will give the same result, even if the positiontowardsfront may be slightly different
                        bCurEntrySafe = false
                        local tPositionTowardsFront = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oFrontGunship:GetPosition()), iCloseToFrontThreshold * 0.5, true, false, false)
                        if tPositionTowardsFront then
                            local iFrontPlateauOrZero, iFrontZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tPositionTowardsFront)
                            --                  DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck, bReturnGroundAAUnitsAlongsideAAThreat, tOptionalEndMidpointAdjustForDetailedCheck, bOptionalIgnoreOppositeDirectionZones, bIncludeEnemyGroundAAInAirAAThreat, bAssumeWontTargetInterimAAForDetailedCheck)
                            bCurEntrySafe = not(DoesEnemyHaveAAThreatAlongPath(iTeam, iCurPlateauOrZero, iCurZone,                  iFrontPlateauOrZero, iFrontZone,        false,              140,                     0,                     false,              iAirSubteam, true,              false,                                  oUnit:GetPosition(),                    false,                                  oFrontGunship:GetPosition()))
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if it is safe for gunship not near the front to move towards front gunship, iFrontPlateauOrZero='..(iFrontPlateauOrZero or 'nil')..'; iFrontZone='..(iFrontZone or 'nil')..'; iCurPlateauOrZero='..iCurPlateauOrZero..'; iCurZone='..iCurZone..'; bCurEntrySafe='..tostring(bCurEntrySafe)..'; this will be applied to oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                            if not(tiPlateauAndZonesConsidered[iCurPlateauOrZero]) then tiPlateauAndZonesConsidered[iCurPlateauOrZero] = {} end
                            tiPlateauAndZonesConsidered[iCurPlateauOrZero][iCurZone] = bCurEntrySafe
                        end
                    else
                        bCurEntrySafe = tiPlateauAndZonesConsidered[iCurPlateauOrZero][iCurZone]
                    end
                    if bCurEntrySafe then
                        if bDebugMessages == true then LOG(sFunctionRef..': Moving unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to be closer to front gunship despite the general retreat order') end
                        AiBotOrders.IssueTrackedMove(oUnit, oFrontGunship:GetPosition(), 10, false, 'FACons1', false)
                    else
                        if not(tGunshipsToRetreatNotRefuel) then tGunshipsToRetreatNotRefuel = {} end
                        table.insert(tGunshipsToRetreatNotRefuel, oUnit)
                        if bDebugMessages == true then LOG(sFunctionRef..': Cur entry isnt safe so will include this unit in table of gunships to retreat') end
                    end
                end
            end
        end

        if AiBotUtilities.IsTableEmpty(tEnemyGroundOrGunshipTargets) then
            if oFrontGunship and tTeleportTargetToMoveTo then
                if bDebugMessages == true then LOG(sFunctionRef..': Will move gunships to teleport target location, tTeleportTargetToMoveTo='..repru(tTeleportTargetToMoveTo)) end
                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbGunshipsHadAttackOrderLastCycle] = true
                GetGunshipsToMoveToTarget(tAvailableGunships, tTeleportTargetToMoveTo)
            else
                AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbGunshipsHadAttackOrderLastCycle] = false
                --Return available gunships to rally point
                if bDebugMessages == true then LOG(sFunctionRef..': Finished considering gunships targets for all land and water zones, will send any remaining gunships to refuel or go to rally (or support point if we have air control). AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl])) end
                if AiBotUtilities.IsTableEmpty(tAvailableGunships) == false then --redundancy
                    local tMovePoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
                    --DOnt wnat to move to support point, as support point is based in part on front gunship, so end up with a circular logic
                    if AiBotUtilities.IsTableEmpty(tGunshipsNearFront) == false then
                        for iUnit, oUnit in tGunshipsNearFront do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering idle gunship order for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' Unit fuel='..oUnit:GetFuelRatio()..'; Unit health%='..AiBotUnitInfo.GetUnitHealthPercent(oUnit)..'; support point='..repru(tMovePoint)..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
                            if ((oUnit:GetFuelRatio() < 0.6 and oUnit:GetFuelRatio() >= 0) or AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= 0.85) and not(EntityCategoryContains(categories.CANNOTUSEAIRSTAGING, oUnit.UnitId)) then
                                table.insert(tGunshipsForRefueling, oUnit)
                            else
                                if not(tGunshipsToRetreatNotRefuel) then tGunshipsToRetreatNotRefuel = {} end
                                table.insert(tGunshipsToRetreatNotRefuel, oUnit)
                                if bDebugMessages == true then LOG(sFunctionRef..': No targets so will return to rally - adding gunship to table of gunships to retreat') end
                            end
                        end
                    end
                end
            end
        else
            --Revise list of enemy targets if we only want to consider those in higher value zones
            local tRevisedEnemyGroundTargets
            if AiBotUtilities.IsTableEmpty(tiPlateauAndZoneForEnemiesToBeIn) then
                tRevisedEnemyGroundTargets = tEnemyGroundOrGunshipTargets
            else
                tRevisedEnemyGroundTargets = {}
                for iUnit, oUnit in tEnemyGroundOrGunshipTargets do
                    for iEntry, tPlateauAndZone in tiPlateauAndZoneForEnemiesToBeIn do
                        if (oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] == tPlateauAndZone[2] and oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] == tPlateauAndZone[1]) then
                            table.insert(tRevisedEnemyGroundTargets, oUnit)
                        elseif tPlateauAndZone[1] == 0 and oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] == tPlateauAndZone[2] then
                            table.insert(tRevisedEnemyGroundTargets, oUnit)
                        end
                    end
                end
                if AiBotUtilities.IsTableEmpty(tRevisedEnemyGroundTargets) then tRevisedEnemyGroundTargets = tEnemyGroundOrGunshipTargets end
                if bDebugMessages == true then LOG(sFunctionRef..': Limiting to only units in high value zones, size of tEnemyGroundOrGunshipTargets='..table.getn(tEnemyGroundOrGunshipTargets)..'; Size of tRevisedEnemyGroundTargets='..table.getn(tRevisedEnemyGroundTargets)..'; tiPlateauAndZoneForEnemiesToBeIn='..repru(tiPlateauAndZoneForEnemiesToBeIn)) end
            end
            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbGunshipsHadAttackOrderLastCycle] = true
            --Have targets for gunships, and have available gunships - send orders for targeting
            local oClosestEnemy
            --Get the closest enemy unit to the front gunship; first filter to only consider AA, then (if no AA) consider experimentals and mexes; then (if none of these consider other units
            local tiCategoryPriorities = {AiBotUnitInfo.refCategoryGroundAA, AiBotUnitInfo.refCategoryExperimentalLevel + AiBotUnitInfo.refCategoryMex - categories.TECH1 + AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryMobileLandShield + AiBotUnitInfo.refCategoryShieldBoat, categories.ALLUNITS}
            local iCurDist
            local iClosestDist = 100000
            for iCurCategoryEntry, iCategoryPriority in tiCategoryPriorities do
                local tPotentialTargets = EntityCategoryFilterDown(iCategoryPriority, tRevisedEnemyGroundTargets)
                if AiBotUtilities.IsTableEmpty(tPotentialTargets) == false then
                    for iUnit, oUnit in tPotentialTargets do
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), oUnit:GetPosition())
                        if iCurDist < iClosestDist then
                            iClosestDist = iCurDist
                            oClosestEnemy = oUnit
                        end
                    end
                end
                if oClosestEnemy then
                    --Dont avoid attacking exp just because there are some AA near another base
                    if iCurCategoryEntry == 1 and iClosestDist >= 70 then
                        local tExperimentalsInTargets = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryExperimentalLevel, tRevisedEnemyGroundTargets)
                        if AiBotUtilities.IsTableEmpty(tExperimentalsInTargets) == false then
                            local iSearchThreshold = iClosestDist - 65
                            for iUnit, oUnit in tExperimentalsInTargets do
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), oUnit:GetPosition())
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to prioritise enemy experimental instead of MAA, iCurDist='..iCurDist..'; iSearchThreshold='..iSearchThreshold..'; iClosestDist='..iClosestDist) end
                                if iCurDist < iSearchThreshold then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will target nearby enemy experimental in priority to near but further away MAA') end
                                    iClosestDist = iCurDist
                                    iSearchThreshold = iCurDist
                                    oClosestEnemy = oUnit
                                end
                            end
                        end
                    end
                    break
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Closest priority enemy='..oClosestEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestEnemy)..'; Is closest enemy near an active nuke='..tostring( AiBotConditions.IsTargetNearActiveNukeTarget(oClosestEnemy:GetPosition(), iTeam, 60))..'; AiBotUtilities.bLoudModActive='..tostring(AiBotUtilities.bLoudModActive or false)) end
            --Consider searching a bit further away for enemy AA if this isn't a high value target or a unit with AA
            if AiBotUtilities.IsTableEmpty(tiPlateauAndZoneForEnemiesToBeIn) and (oClosestEnemy[AiBotUnitInfo.refiAARange] or 0) == 0 and not(EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel + AiBotUnitInfo.refCategoryAllShieldUnits + categories.COMMAND + AiBotUnitInfo.refCategoryGroundAA, oClosestEnemy.UnitId)) then
                local toNearbyAAUnits = oFrontGunship:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryGroundAA, oClosestEnemy:GetPosition(), 80, 'Enemy')
                if bDebugMessages == true then LOG(sFunctionRef..': Is toNearbyAAUnits empty='..tostring(AiBotUtilities.IsTableEmpty(toNearbyAAUnits))) end
                if AiBotUtilities.IsTableEmpty(toNearbyAAUnits) == false then
                    local iClosestAALessRange = 10
                    local iCurAALessRange
                    for iEnemyAA, oEnemyAA in toNearbyAAUnits do
                        if oEnemyAA:GetFractionComplete() >= 0.6 then
                            iCurAALessRange = AiBotUtilities.GetDistanceBetweenPositions(oFrontGunship:GetPosition(), oEnemyAA:GetPosition()) - (oEnemyAA[AiBotUnitInfo.refiAARange] or 0)
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering alternate enemy AA to target, oEnemyAA='..oEnemyAA.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyAA)..'; iCurAALessRange='..iCurAALessRange) end
                            if iCurAALessRange < iClosestAALessRange and (not(bAreJustTargetingUnitsOutOfAARange) or iCurAALessRange < iMinDistFromAAWantedIfAvoidingForMostUnits) then
                                iClosestAALessRange = iCurAALessRange
                                oClosestEnemy = oEnemyAA
                                if bDebugMessages == true then LOG(sFunctionRef..': Changing oClosestEnemy to be this unit') end
                            end
                        end
                    end
                end
            end

            --Check we arent near a nuke
            if AiBotConditions.IsTargetNearActiveNukeTarget(oClosestEnemy:GetPosition(), iTeam, 60) then
                if bDebugMessages == true then LOG(sFunctionRef..': We are near an active nuke target so will change gunship position to go to rally point') end
                --Return to rally instead
                if bGivenOrdersToFarFromFrontGunships then
                    GetGunshipsToMoveToTarget(tGunshipsNearFront, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
                else
                    GetGunshipsToMoveToTarget(tAvailableGunships, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
                end

            else
                if bDebugMessages == true then LOG(sFunctionRef..': Will try and get gunships to move to oClosestEnemy at position '..repru(oClosestEnemy:GetPosition())..'; is in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(oClosestEnemy:GetPosition()))) end
                --If closest enemy is covered by a fixed shield then make sure all gunships will prioritise fixed shields over AA
                if bUsingSnipePriority then
                    for iGunship, oGunship in tAvailableGunships do
                        if oGunship[AiBotUnitInfo.refbUsingDefaultWeaponPriority] then
                            AiBotUnitInfo.SetUnitWeaponTargetPriorities(oGunship, AiBotUnitInfo.refWeaponPriorityGunshipSnipe, true)
                            oGunship[AiBotUnitInfo.refbUsingDefaultWeaponPriority] = false
                        end
                    end
                elseif AiBotUtilities.IsTableEmpty(oClosestEnemy[AiBotBuilding.reftoUnitsCoveredByShield]) == false then
                    for iGunship, oGunship in tAvailableGunships do
                        if oGunship[AiBotUnitInfo.refbUsingDefaultWeaponPriority] then
                            AiBotUnitInfo.SetUnitWeaponTargetPriorities(oGunship, AiBotUnitInfo.refWeaponPriorityGunshipShield, true)
                            oGunship[AiBotUnitInfo.refbUsingDefaultWeaponPriority] = false
                        end
                    end
                else
                    for iGunship, oGunship in tAvailableGunships do
                        if not(oGunship[AiBotUnitInfo.refbUsingDefaultWeaponPriority]) then
                            AiBotUnitInfo.SetUnitWeaponTargetPriorities(oGunship, AiBotUnitInfo.refWeaponPriorityGunship, true)
                            oGunship[AiBotUnitInfo.refbUsingDefaultWeaponPriority] = true
                        end

                    end
                end
                if bGivenOrdersToFarFromFrontGunships then
                    GetGunshipsToMoveToTarget(tGunshipsNearFront, oClosestEnemy:GetPosition(), oClosestEnemy)
                else
                    --if AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive then --LOUD has significantly lowered gunship firing tolerance so they have to face enemy to fire
                    GetGunshipsToMoveToTarget(tAvailableGunships, oClosestEnemy:GetPosition(), oClosestEnemy)
                    --else
                    --GetGunshipsToMoveToTarget(tAvailableGunships, oClosestEnemy:GetPosition())
                    --end
                end

            end
        end
    else
        AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbGunshipsHadAttackOrderLastCycle] = false
    end

    --Clear assignment flags for any refueling gunships
    if AiBotUtilities.IsTableEmpty(tGunshipsForRefueling) == false then
        for iUnit, oUnit in tGunshipsForRefueling do
            oUnit[refiGunshipPlacement] = 10000
        end
    end

    --Send units for refueling
    if bDebugMessages == true then LOG(sFunctionRef..': Finished giving gunship orders, is table of gunships for refueling empty='..tostring(AiBotUtilities.IsTableEmpty(tGunshipsForRefueling))..'; is tGunshipsToRetreatNotRefuel empty='..tostring(AiBotUtilities.IsTableEmpty(tGunshipsToRetreatNotRefuel))..'; will first consider avoiding enemy ground AA') end
    if (AiBotUtilities.IsTableEmpty(tGunshipsForRefueling) == false or AiBotUtilities.IsTableEmpty(tGunshipsToRetreatNotRefuel) == false) then
        --if AA near gunship look for if there's a safer route to get back to rally point
        local iUnitDistToRally
        local tRallyPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
        local iCurPlateauOrZero, iCurZone
        local tGunshipZoneDetailsByPlateauAndZone = {} --[x] = plateau or zero, [y] = zone, returns below subref tables
        local subrefClosestGunshipRef = 1 --location in tGunshipsForRefueling of the closest gunship to rally point
        local subrefClosestDistToRally = 2 --Distance of subrefClosestGunshipRef to the rally point
        local subrefStraightLineAAThreatToRally = 3 --Enemy groundAA threat from subrefClosestGunshipRef to the rally

        local tiAllGunshipRefsInZone = 4 --table of the tGunshipsForRefueling index for every gunship in this zone
        local iGroundAAIgnoreThresholdHealthFactor = 0.25 --E.g. a full health retreating gunship (6k health) will look for alternative paths vs 1500 AA threat, so wont try and avoid an enemy T2 flak, but will from a SAM

        --First record closest gunship to rally point for each zone
        local iRallyPlateauOrZero, iRallyLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
        local toGunshipsToRetreatOrRefuel = {}
        if AiBotUtilities.IsTableEmpty(tGunshipsForRefueling) then
            toGunshipsToRetreatOrRefuel = tGunshipsToRetreatNotRefuel
            for iGunship, oGunship in toGunshipsToRetreatOrRefuel do
                oGunship[refbGunshipWantsToRefuel] = nil
            end
        else
            for iGunship, oGunship in tGunshipsForRefueling do
                oGunship[refbGunshipWantsToRefuel] = true
                table.insert(toGunshipsToRetreatOrRefuel, oGunship)
            end
            if AiBotUtilities.IsTableEmpty(tGunshipsToRetreatNotRefuel) == false then
                for iGunship, oGunship in tGunshipsToRetreatNotRefuel do
                    oGunship[refbGunshipWantsToRefuel] = nil
                    table.insert(toGunshipsToRetreatOrRefuel, oGunship)
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Will record the closest gunship in each zone to the rally, size of toGunshipsToRetreatOrRefuel='..table.getn(toGunshipsToRetreatOrRefuel)) end
        for iCurEntry = table.getn(toGunshipsToRetreatOrRefuel), 1, -1 do
            local oUnit =  toGunshipsToRetreatOrRefuel[iCurEntry]
            iCurPlateauOrZero, iCurZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
            if bDebugMessages == true then LOG(sFunctionRef..': Checking if oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..' is closest gunship to rally for this zone, iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurZone='..(iCurZone or 'nil')) end
            if iCurPlateauOrZero and iCurZone then
                iUnitDistToRally = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint)
                if bDebugMessages == true then LOG(sFunctionRef..': iUnitDistToRally='..iUnitDistToRally..'; tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefClosestDistToRally]='..(tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefClosestDistToRally] or 'nil')..'; iRallyLandOrWaterZone='..iRallyLandOrWaterZone..'; iRallyPlateauOrZero='..iRallyPlateauOrZero) end
                if iUnitDistToRally > 120 and not(iRallyLandOrWaterZone == iCurZone and iCurPlateauOrZero ==  iRallyPlateauOrZero) then
                    --Far enoguh from rally, and in a dif zone, so want to record gunship
                    if not(tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone]) then
                        if not(tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero]) then
                            if not(tGunshipZoneDetailsByPlateauAndZone) then tGunshipZoneDetailsByPlateauAndZone = {} end
                            tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero] = {}
                        end
                        tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone] = {[tiAllGunshipRefsInZone] = {}}
                    end
                    if iUnitDistToRally < (tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefClosestDistToRally] or 100000) then
                        if bDebugMessages == true then LOG(sFunctionRef..': Updating closest gunship ref for P'..iCurPlateauOrZero..'Z'..iCurZone..' to be '..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; based on iCurEntry='..iCurEntry) end
                        tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefClosestDistToRally] = iUnitDistToRally
                        tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefClosestGunshipRef] = iCurEntry
                    end
                    table.insert(tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][tiAllGunshipRefsInZone], iCurEntry)
                else
                    oUnit[reftGunshipSpecialRallyPathing] = nil
                    if bDebugMessages == true then LOG(sFunctionRef..': Unit is either in rally or close to rally so wont give it special retreat pathing') end
                end
            end
        end
        if tGunshipZoneDetailsByPlateauAndZone then --we have recorded at least one gunship for whom we want to look for alternative retreat logic
            local iCurEntry, oUnit, iMaxAAThreatWanted, iBaseZoneMaxAAThreatBeforeConsideringOtherZones, iPreviousBestPathingCurrentAAThreat, bStickWithPreviousPathing
            local tiPathingToUse --table listing the points along the path (e.g. zone midpoints) to pass through to get to the rally point
            local iCurZoneCount, iCurZoneSize, iOtherPlateau, iOtherZone, iThreatToOtherZone, iCurBestDetourPlateauOrZero, iCurBestDetourZone
            local iBestAAPathThreat = 100000
            local iDistThreshold = 250
            local tOtherZoneStartPointToUse
            local tBestPathingMidpoint
            if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then iDistThreshold = 350 end
            local iMaxZonesToConsider = 25
            if  AiBotUtilities.bCPUPerformanceMode then
                iMaxZonesToConsider = 8
                iDistThreshold = iDistThreshold * 0.5
            end

            for iCurPlateauOrZero, tZoneAndDetails in tGunshipZoneDetailsByPlateauAndZone do
                for iCurZone, tGunshipPathingSubtable in tZoneAndDetails do
                    if tGunshipPathingSubtable[subrefClosestGunshipRef] then --for some reason we consider zones with no values that havent been considered in the above
                        tiPathingToUse = nil
                        iCurEntry = tGunshipPathingSubtable[subrefClosestGunshipRef]
                        oUnit = toGunshipsToRetreatOrRefuel[iCurEntry]
                        bStickWithPreviousPathing = false

                        if bDebugMessages == true then LOG(sFunctionRef..': Cycling through retreat zones, iCurPlateauOrZero='..iCurPlateauOrZero..'; iCurZone='..iCurZone..'; gunship closest to rally oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; is oUnit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; oUnit[reftGunshipSpecialRallyPathing]='..repru(oUnit[reftGunshipSpecialRallyPathing])..'; iCurEntry='..(iCurEntry or 'nil')) end
                        --Do we want to stick with previously decided pathing?
                        if oUnit[reftGunshipSpecialRallyPathing][subrefLastRecordedZone] and oUnit[reftGunshipSpecialRallyPathing][subrefLastRecordedPlateauOrZero]
                                and oUnit[reftGunshipSpecialRallyPathing][subrefGunshipPlateauAndZoneWhenRecorded][1] == iCurPlateauOrZero
                                and oUnit[reftGunshipSpecialRallyPathing][subrefGunshipPlateauAndZoneWhenRecorded][2] == iCurZone then
                            --When the gunship was in this plateau and zone it had a recorded rally point, so will stick with that unless enemy AA threat has increased significantly
                            iOtherPlateau = oUnit[reftGunshipSpecialRallyPathing][subrefLastRecordedPlateauOrZero]
                            iOtherZone = oUnit[reftGunshipSpecialRallyPathing][subrefLastRecordedZone]
                            if not(tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone][subrefStraightLineAAThreatToRally]) then
                                if not(tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone]) then
                                    if not(tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau]) then tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau] = {} end
                                    tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone] = {}
                                end
                                tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone][subrefStraightLineAAThreatToRally] = DoesEnemyHaveAAThreatAlongPath(iTeam, iOtherPlateau, iOtherZone, iRallyPlateauOrZero, iRallyLandOrWaterZone, true, nil, nil, false, iAirSubteam, true, true, oUnit:GetPosition(), false, tRallyPoint, true, nil, nil, true) --If changing here then also change below
                            end
                            local tAltLZOrWZData
                            if iOtherPlateau == 0 then
                                tAltLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iOtherZone]][AiBotMap.subrefPondWaterZones][iOtherZone]
                            else
                                tAltLZOrWZData = AiBotMap.tAllPlateaus[iOtherPlateau][AiBotMap.subrefPlateauLandZones][iOtherZone]
                            end
                            iPreviousBestPathingCurrentAAThreat = tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone][subrefStraightLineAAThreatToRally]
                                    + DoesEnemyHaveAAThreatAlongPath(iTeam, iCurPlateauOrZero, iCurZone, iOtherPlateau, iOtherZone, true, nil, nil, false, iAirSubteam, true, true, oUnit:GetPosition(), false, tAltLZOrWZData[AiBotMap.subrefMidpoint], true, nil, nil, true)
                            if bDebugMessages == true then LOG(sFunctionRef..': iPreviousBestPathingCurrentAAThreat='..iPreviousBestPathingCurrentAAThreat) end
                            if iPreviousBestPathingCurrentAAThreat <= 1.2 * (oUnit[reftGunshipSpecialRallyPathing][subrefLastRecordedAAThreat] or 0) then
                                --Stick with previous unless going back from current zone is better
                                if not(tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone]) then
                                    if not(tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero]) then tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero] = {} end
                                    tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone] = {}
                                end
                                if not(tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefStraightLineAAThreatToRally]) then
                                    tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefStraightLineAAThreatToRally] = DoesEnemyHaveAAThreatAlongPath(iTeam, iCurPlateauOrZero, iCurZone, iRallyPlateauOrZero, iRallyLandOrWaterZone, true, nil, nil, false, iAirSubteam, true, true, oUnit:GetPosition(), false, tRallyPoint, true, nil, nil, true) --If changing here then also change below
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Threat if just go to rally from here='..tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefStraightLineAAThreatToRally]) end
                                if tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefStraightLineAAThreatToRally] > 1.2 * tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefStraightLineAAThreatToRally] then
                                    bStickWithPreviousPathing = true
                                    iCurBestDetourZone = iOtherZone
                                    iCurBestDetourPlateauOrZero = iOtherPlateau
                                    iBestAAPathThreat = (oUnit[reftGunshipSpecialRallyPathing][subrefLastRecordedAAThreat] or 0)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will stick with previous pathing') end
                                end
                            end
                        end
                        if not(bStickWithPreviousPathing) then

                            iBaseZoneMaxAAThreatBeforeConsideringOtherZones = oUnit:GetHealth() * iGroundAAIgnoreThresholdHealthFactor

                            iCurBestDetourPlateauOrZero = nil
                            iCurBestDetourZone = nil
                            --Calc straight line AA threat
                            if not(tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefStraightLineAAThreatToRally]) then tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefStraightLineAAThreatToRally] = DoesEnemyHaveAAThreatAlongPath(iTeam, iCurPlateauOrZero, iCurZone, iRallyPlateauOrZero, iRallyLandOrWaterZone, true, nil, nil, false, iAirSubteam, true, true, oUnit:GetPosition(), false, tRallyPoint, true, nil, nil, true) end --If changing here then also change below
                            if bDebugMessages == true then LOG(sFunctionRef..': Threat if go from straight line from here back to rally='..tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefStraightLineAAThreatToRally]..'; iBaseZoneMaxAAThreatBeforeConsideringOtherZones='..iBaseZoneMaxAAThreatBeforeConsideringOtherZones) end
                            if tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefStraightLineAAThreatToRally] > iBaseZoneMaxAAThreatBeforeConsideringOtherZones then
                                --Require zones that arent in a straight line to be significanlty safer, as will also be greater airaa risk with a detour, and the longer we are traveling the more we might take damage from ground AA; also helps from cpu optimisation perspective
                                --first record base:
                                iBestAAPathThreat = tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefStraightLineAAThreatToRally]
                                iCurBestDetourPlateauOrZero = iCurPlateauOrZero
                                iCurBestDetourZone = iCurZone
                                --look for if are better alternatives:
                                local tCurLZOrWZData, tCurLZOrWZTeamData
                                if iCurPlateauOrZero == 0 then
                                    tCurLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurZone]][AiBotMap.subrefPondWaterZones][iCurZone]
                                    tCurLZOrWZTeamData = tCurLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                else
                                    tCurLZOrWZData = AiBotMap.tAllPlateaus[iCurPlateauOrZero][AiBotMap.subrefPlateauLandZones][iCurZone]
                                    tCurLZOrWZTeamData = tCurLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                end
                                --No point running via dif rally point if enemy has air here and we lack air control; also require greater decrease in groundAA threat due to risk enemy air catches up with us if taking detour
                                if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) then
                                    iMaxAAThreatWanted = math.min(tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefStraightLineAAThreatToRally] * 0.6, tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefStraightLineAAThreatToRally] - (tCurLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) * 6)
                                else
                                    iMaxAAThreatWanted = tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][subrefStraightLineAAThreatToRally] * 0.7
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': iMaxAAThreatWanted before considering other zones='..iMaxAAThreatWanted..'; Enemy AirAA threat in cur plateau and zone='..(tCurLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)) end
                                if iMaxAAThreatWanted > 50 then
                                    if AiBotUtilities.IsTableEmpty(tCurLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) then
                                        RecordOtherLandAndWaterZonesByDistance(tCurLZOrWZData)
                                    end
                                    if tCurLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] then
                                        iCurZoneCount = 0
                                        for iEntry, tSubtable in tCurLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                                            if tSubtable[AiBotMap.subrefiDistance] > iDistThreshold then break end
                                            local tAltLZOrWZData
                                            if tSubtable[AiBotMap.subrefbIsWaterZone] then iOtherPlateau = 0 else iOtherPlateau = tSubtable[AiBotMap.subrefiPlateauOrPond] end
                                            iOtherZone = tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]
                                            if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                                tAltLZOrWZData = AiBotMap.tPondDetails[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][iOtherZone]
                                                iCurZoneSize = math.max(tAltLZOrWZData[AiBotMap.subrefWZMaxSegX] - tAltLZOrWZData[AiBotMap.subrefWZMinSegX], tAltLZOrWZData[AiBotMap.subrefWZMaxSegZ] - tAltLZOrWZData[AiBotMap.subrefWZMinSegZ])
                                            else
                                                tAltLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][iOtherZone]
                                                iCurZoneSize = math.max(tAltLZOrWZData[AiBotMap.subrefLZMaxSegX] - tAltLZOrWZData[AiBotMap.subrefLZMinSegX], tAltLZOrWZData[AiBotMap.subrefLZMaxSegZ] - tAltLZOrWZData[AiBotMap.subrefLZMinSegZ])
                                            end
                                            iCurZoneSize = iCurZoneSize * AiBotMap.iLandZoneSegmentSize
                                            if iCurZoneSize >= 35 then --Dont want to consider tiny zones on cliffs
                                                --Ignore zone if the primary gunship was in it previously (as means we are doubling back on ourselves)
                                                if not(iOtherZone == oUnit[reftGunshipSpecialRallyPathing][subrefGunshipPlateauAndZoneWhenRecorded][2]) or not(iOtherPlateau == oUnit[reftGunshipSpecialRallyPathing][subrefGunshipPlateauAndZoneWhenRecorded][1]) then

                                                    iCurZoneCount = iCurZoneCount + 1
                                                    if iCurZoneCount > iMaxZonesToConsider then break end
                                                    if not(tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone][subrefStraightLineAAThreatToRally]) then
                                                        if not(tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone]) then
                                                            if not(tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau]) then tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau] = {} end
                                                            tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone] = {}
                                                            tOtherZoneStartPointToUse = {tAltLZOrWZData[AiBotMap.subrefMidpoint][1], tAltLZOrWZData[AiBotMap.subrefMidpoint][2], tAltLZOrWZData[AiBotMap.subrefMidpoint][3]}
                                                        elseif not(tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone][subrefClosestGunshipRef]) then
                                                            tOtherZoneStartPointToUse = {tAltLZOrWZData[AiBotMap.subrefMidpoint][1], tAltLZOrWZData[AiBotMap.subrefMidpoint][2], tAltLZOrWZData[AiBotMap.subrefMidpoint][3]}
                                                        else
                                                            tOtherZoneStartPointToUse = toGunshipsToRetreatOrRefuel[tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone][subrefClosestGunshipRef]]:GetPosition()
                                                        end
                                                        tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone][subrefStraightLineAAThreatToRally] = DoesEnemyHaveAAThreatAlongPath(iTeam, iOtherPlateau, iOtherZone, iRallyPlateauOrZero, iRallyLandOrWaterZone, true, nil, nil, false, iAirSubteam, true, true, tOtherZoneStartPointToUse, false, tRallyPoint, true, nil, nil, true) --If changing here then also change above
                                                    end
                                                    --If we could get to the other zone, would it be significantly safer to retreat from there?
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if would be better to travel from iOtherPlateau='..iOtherPlateau..'; iOtherZone='..iOtherZone..'; AA threat from that zone to rally='..(tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone][subrefStraightLineAAThreatToRally] or 0)..'; iMaxAAThreatWanted='..iMaxAAThreatWanted) end
                                                    if (tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone][subrefStraightLineAAThreatToRally] or 0) < iMaxAAThreatWanted then
                                                        --What is the threat if we travel here directly?
                                                        iThreatToOtherZone = DoesEnemyHaveAAThreatAlongPath(iTeam, iCurPlateauOrZero, iCurZone, iOtherPlateau, iOtherZone, true, nil, nil, false, iAirSubteam, true, true, oUnit:GetPosition(), false, tAltLZOrWZData[AiBotMap.subrefMidpoint], true, nil, nil, true)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Threat if go from here to other zone, iThreatToOtherZone='..iThreatToOtherZone..'; Combined threat='..iThreatToOtherZone + tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone][subrefStraightLineAAThreatToRally]) end
                                                        if iThreatToOtherZone + tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone][subrefStraightLineAAThreatToRally] < iMaxAAThreatWanted then
                                                            --Have a new best path to take, via detour
                                                            iBestAAPathThreat = iThreatToOtherZone + tGunshipZoneDetailsByPlateauAndZone[iOtherPlateau][iOtherZone][subrefStraightLineAAThreatToRally]
                                                            iMaxAAThreatWanted = iBestAAPathThreat
                                                            iCurBestDetourPlateauOrZero = iOtherPlateau
                                                            iCurBestDetourZone = iOtherZone
                                                            tBestPathingMidpoint = {tOtherZoneStartPointToUse[1], tOtherZoneStartPointToUse[2], tOtherZoneStartPointToUse[3]}
                                                            if bDebugMessages == true then LOG(sFunctionRef..': Recording this other zone as the best via point zone to go to') end
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        if iCurBestDetourPlateauOrZero and iCurBestDetourZone then --want to use special pathing
                            local tBestLZMidpoint
                            if iCurBestDetourPlateauOrZero == iCurPlateauOrZero and iCurBestDetourZone == iCurZone then
                                tBestLZMidpoint = tRallyPoint
                            elseif iCurBestDetourPlateauOrZero == 0 then
                                tBestLZMidpoint = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurBestDetourZone]][AiBotMap.subrefPondWaterZones][iCurBestDetourZone][AiBotMap.subrefMidpoint]
                            else
                                tBestLZMidpoint = AiBotMap.tAllPlateaus[iCurBestDetourPlateauOrZero][AiBotMap.subrefPlateauLandZones][iCurBestDetourZone][AiBotMap.subrefMidpoint]
                            end
                            for _, iRecordedGunshipRef in tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][tiAllGunshipRefsInZone] do
                                local oRecordedUnit = toGunshipsToRetreatOrRefuel[iRecordedGunshipRef]
                                if not(oRecordedUnit[reftGunshipSpecialRallyPathing]) then oRecordedUnit[reftGunshipSpecialRallyPathing] = {} end
                                oRecordedUnit[reftGunshipSpecialRallyPathing][subrefLastRecordedZone] = iCurBestDetourZone
                                oRecordedUnit[reftGunshipSpecialRallyPathing][subrefLastRecordedPlateauOrZero] = iCurBestDetourPlateauOrZero
                                oRecordedUnit[reftGunshipSpecialRallyPathing][subrefLastRecordedAAThreat] = iBestAAPathThreat
                                oRecordedUnit[reftGunshipSpecialRallyPathing][subrefGunshipPlateauAndZoneWhenRecorded] = {iCurPlateauOrZero, iCurZone}
                                AiBotOrders.IssueTrackedMove(oRecordedUnit, tBestLZMidpoint, 10, false, 'GSRtrViaP'..iCurBestDetourPlateauOrZero..'Z'..iCurBestDetourZone, false)
                                if bDebugMessages == true then LOG(sFunctionRef..': Told retreating gunship '..oRecordedUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oRecordedUnit)..' to go to iCurBestDetourPlateauOrZero='..iCurBestDetourPlateauOrZero..'; iCurBestDetourZone='..iCurBestDetourZone) end
                            end
                        else
                            --Just use default pathing
                            for _, iRecordedGunshipRef in tGunshipZoneDetailsByPlateauAndZone[iCurPlateauOrZero][iCurZone][tiAllGunshipRefsInZone] do
                                local oRecordedUnit = toGunshipsToRetreatOrRefuel[iRecordedGunshipRef]
                                oRecordedUnit[reftGunshipSpecialRallyPathing] = nil
                            end
                        end
                    end
                end
            end
        end
        --Remove any gunships given special order from those to be given normal refueling order
        if AiBotUtilities.IsTableEmpty(tGunshipsForRefueling) == false then
            for iCurEntry = table.getn(tGunshipsForRefueling), 1, -1 do
                local oUnit =  tGunshipsForRefueling[iCurEntry]
                if oUnit[reftGunshipSpecialRallyPathing][subrefLastRecordedZone] then
                    table.remove(tGunshipsForRefueling, iCurEntry)
                end
            end
        end
        if AiBotUtilities.IsTableEmpty(tGunshipsToRetreatNotRefuel) == false then
            local tRallyPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
            for iCurEntry = table.getn(tGunshipsToRetreatNotRefuel), 1, -1 do
                local oUnit = tGunshipsToRetreatNotRefuel[iCurEntry]
                if oUnit[reftGunshipSpecialRallyPathing][subrefLastRecordedZone] then
                    table.remove(tGunshipsToRetreatNotRefuel, iCurEntry)
                else
                    --Send to rally point
                    if bDebugMessages == true then LOG(sFunctionRef..': Ordering oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to retreat to air rally point insead of using refuel logic') end
                    AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 10, false, 'GSRtrRal', false)
                end
            end
        end
    end
    --Run the function even if no units wanting refueling so already attached untis can be sent on their way
    SendUnitsForRefueling(tGunshipsForRefueling, iTeam, iAirSubteam)
    if bDebugMessages == true and AiBotUtilities.IsTableEmpty(tGunshipsForRefueling) == false then
        LOG(sFunctionRef..': Will send '..table.getn(tGunshipsForRefueling)..' units to refuel')
    end

    --Update front gunship (or set to nilif none available)
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refoFrontGunship] = oFrontGunship

    --Update if gunship wants scout (for cloaked neemies)
    --First remove any existing assignment
    if AiBotUtilities.IsTableEmpty( AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout]) == false then
        local iExistingEntries = table.getn(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout])
        for iCurEntry = iExistingEntries, 1, -1 do
            if not(AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout][iCurEntry])) or EntityCategoryContains(AiBotUnitInfo.refCategoryGunship, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout].UnitId) then
                table.remove(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout], iCurEntry)
            end
        end
    end
    if bGunshipWantsAirScout and oFrontGunship then
        if not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout]) then AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout] = {} end
        AddUnitWantingPriorityScout(oFrontGunship)
    end

    --Disable gunship weapons over pacifist areas
    if AiBotOverseer.bPacifistModeActive or AiBotOverseer.bHaveDisabledGunshipWeaponsForPacifism then
        AiBotOverseer.bHaveDisabledGunshipWeaponsForPacifism = AiBotOverseer.bPacifistModeActive
        for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
            local tAllGunships = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryGunship, false, true)
            if AiBotUtilities.IsTableEmpty(tAllGunships) == false then
                local iCurSegmentX, iCurSegmentZ
                local sPathing = AiBotMap.refPathingTypeHover
                local bDisableWeapon
                for iGunship, oGunship in tAllGunships do
                    bDisableWeapon = false
                    if oGunship:GetFractionComplete() == 1 then
                        if NavUtils.GetLabel(sPathing, oGunship:GetPosition()) then
                            local tGunshipLZOrWZData = AiBotMap.GetLandOrWaterZoneData(oGunship:GetPosition())
                            if tGunshipLZOrWZData[AiBotMap.subrefbPacifistArea] then
                                bDisableWeapon = true
                            end
                        end
                        if bDisableWeapon then
                            AiBotUnitInfo.DisableUnitWeapon(oGunship)
                        else
                            AiBotUnitInfo.EnableUnitWeapon(oGunship)
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateScoutingShortlist(iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateScoutingShortlist'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)


    if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTimeOfScoutingShortlistUpdate] or 0) >= 0.89 then

        --Decide how often we want to scout
        local tiTimeByPriority = {[AiBotMap.subrefiScoutingHighPriority] = 60, [AiBotMap.subrefiScoutingMediumPriority] = 120, [AiBotMap.subrefiScoutingLowPriority] = 360}
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] < 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTeamGrossMass] < 12 then
            for iEntry, iInterval in tiTimeByPriority do
                iInterval = iInterval * 2
            end
        end
        local iRadarFactor = 4 --If have radar coverage then dont want to scout as often
        local iLongestOverdueScoutingTarget = 0
        --Create shortlist
        AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiTimeOfScoutingShortlistUpdate] = GetGameTimeSeconds()
        AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftLandAndWaterZoneScoutingShortlist] = {}
        local tShortlist = AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftLandAndWaterZoneScoutingShortlist]

        local iIntervalWanted
        local iLongestOverdueRequirement = 0
        local bConsiderOverdueLimit = false
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLongestOverdueScoutingTarget] >= 360 then --we have some locations we haven't scouted for at least 6 minutes after we wanted to
            iLongestOverdueRequirement = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLongestOverdueScoutingTarget] * 0.25
            bConsiderOverdueLimit = true
        end
        local tiEntriesBelowOverdueRequirement = {}
        local iEntriesAboveOverdueRequirement = 0
        local iMinSegmentsWantedForMexFreeZones = 400 / AiBotMap.iLandZoneSegmentSize
        local iAmountOverIntervalWanted
        local iShortlistEntry = 0
        local iLowPriorityShortlistEntryCount = 0

        if bDebugMessages == true then LOG(sFunctionRef..': About to cycle through each plateau and land zone, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLongestOverdueScoutingTarget]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLongestOverdueScoutingTarget]..'; iLongestOverdueRequirement='..iLongestOverdueRequirement) end
        for iPlateau, tPlateauSubtable in AiBotMap.tAllPlateaus do
            for iLandZone, tLZData in tPlateauSubtable[AiBotMap.subrefPlateauLandZones] do
                if tLZData[AiBotMap.subrefLZOrWZMexCount] > 0 or tLZData[AiBotMap.subrefLZTotalSegmentCount] >= iMinSegmentsWantedForMexFreeZones then
                    local tLZOrWZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                    iIntervalWanted =  tiTimeByPriority[tLZOrWZTeamData[AiBotMap.refiScoutingPriority]] + tLZOrWZTeamData[AiBotMap.refiRecentlyFailedScoutAttempts] ^ 3
                    if tLZOrWZTeamData[AiBotMap.refiRadarCoverage] >= 40 then iIntervalWanted = iIntervalWanted * iRadarFactor end
                    iAmountOverIntervalWanted = GetGameTimeSeconds() - (tLZOrWZTeamData[AiBotMap.refiTimeLastHadVisual] or 0) - iIntervalWanted
                    iLongestOverdueScoutingTarget = math.max(iLongestOverdueScoutingTarget, iAmountOverIntervalWanted)
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; tiTimeByPriority[tLZOrWZTeamData[AiBotMap.refiScoutingPriority]]='..tiTimeByPriority[tLZOrWZTeamData[AiBotMap.refiScoutingPriority]]..'; tLZOrWZTeamData[AiBotMap.refiRecentlyFailedScoutAttempts]='..tLZOrWZTeamData[AiBotMap.refiRecentlyFailedScoutAttempts]..'; Time last had visual='..(tLZOrWZTeamData[AiBotMap.refiTimeLastHadVisual] or 0)..'; Cur time='..GetGameTimeSeconds()..'; Do we expect to be adding this to shortlist='..tostring(GetGameTimeSeconds() - (tLZOrWZTeamData[AiBotMap.refiTimeLastHadVisual] or 0) > iIntervalWanted)..'; iAmountOverIntervalWanted='..iAmountOverIntervalWanted) end
                    if iAmountOverIntervalWanted > 0 then
                        table.insert(tShortlist, {iPlateau, iLandZone})
                        if bConsiderOverdueLimit then
                            iShortlistEntry = iShortlistEntry + 1
                            if iAmountOverIntervalWanted >= iLongestOverdueRequirement then
                                iEntriesAboveOverdueRequirement = iEntriesAboveOverdueRequirement + 1
                            else
                                table.insert(tiEntriesBelowOverdueRequirement, iShortlistEntry)
                                iLowPriorityShortlistEntryCount = iLowPriorityShortlistEntryCount + 1
                            end
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iEntriesAboveOverdueRequirement='..(iEntriesAboveOverdueRequirement or 'nil')..'; iLowPriorityShortlistEntryCount='..(iLowPriorityShortlistEntryCount or 'nil')..'; bConsiderOverdueLimit='..tostring(bConsiderOverdueLimit)) end

        --Same for water zones with mexes
        for iPond, tPondSubtable in AiBotMap.tPondDetails do
            for iWaterZone, tWZData in tPondSubtable[AiBotMap.subrefPondWaterZones] do
                local tLZOrWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                iIntervalWanted =  tiTimeByPriority[tLZOrWZTeamData[AiBotMap.refiScoutingPriority]] + tLZOrWZTeamData[AiBotMap.refiRecentlyFailedScoutAttempts] ^ 3
                if tLZOrWZTeamData[AiBotMap.refiRadarCoverage] >= 50 then iIntervalWanted = iIntervalWanted * iRadarFactor end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering iWaterZone='..iWaterZone..'; tLZOrWZTeamData[AiBotMap.refiTimeLastHadVisual]='..(tLZOrWZTeamData[AiBotMap.refiTimeLastHadVisual] or 'nil')..'; Time since last had visula='..GetGameTimeSeconds() - (tLZOrWZTeamData[AiBotMap.refiTimeLastHadVisual] or 0)..'; iIntervalWanted='..iIntervalWanted) end
                if GetGameTimeSeconds() - (tLZOrWZTeamData[AiBotMap.refiTimeLastHadVisual] or 0) > iIntervalWanted then
                    iLongestOverdueScoutingTarget = math.max(GetGameTimeSeconds() - (tLZOrWZTeamData[AiBotMap.refiTimeLastHadVisual] or 0) - iIntervalWanted, iLongestOverdueScoutingTarget)
                    if iLongestOverdueScoutingTarget >= iLongestOverdueRequirement then
                        if bDebugMessages == true then LOG(sFunctionRef..': Adding water zone '..iWaterZone..' to shortlist') end
                        table.insert(tShortlist, {0, iWaterZone})
                        if bConsiderOverdueLimit then
                            iShortlistEntry = iShortlistEntry + 1
                            if iAmountOverIntervalWanted >= iLongestOverdueRequirement then
                                iEntriesAboveOverdueRequirement = iEntriesAboveOverdueRequirement + 1
                            else
                                table.insert(tiEntriesBelowOverdueRequirement, iShortlistEntry)
                                iLowPriorityShortlistEntryCount = iLowPriorityShortlistEntryCount + 1
                            end
                        end
                    end
                end
            end
        end

        if bConsiderOverdueLimit and AiBotUtilities.IsTableEmpty(tiEntriesBelowOverdueRequirement) == false and iEntriesAboveOverdueRequirement >= 5 and iLowPriorityShortlistEntryCount >= 5 then
            --Consider removing the entries we have scouted most recently based on how many spyp planes we have
            local iAirScouts = AiBotConditions.GetCurrentAiBotUnitsOfCategoryInTeam(AiBotUnitInfo.refCategoryAirScout, iTeam)
            if iAirScouts < iEntriesAboveOverdueRequirement then
                for iEntryToRemove = iLowPriorityShortlistEntryCount, 1 do
                    if bDebugMessages == true then LOG(sFunctionRef..': Are removing a shortlist entry as we have so many') end
                    table.remove(tShortlist, tiEntriesBelowOverdueRequirement[iEntryToRemove])
                end
            end
        end

        AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiLongestOverdueScoutingTarget] = iLongestOverdueScoutingTarget

        if bDebugMessages == true then
            if AiBotUtilities.IsTableEmpty(tShortlist) == false then
                LOG(sFunctionRef..': end of code, size of tShortlist='..table.getn(tShortlist)..'; tShortlist='..repru(tShortlist)..'; iLongestOverdueScoutingTarget='..iLongestOverdueScoutingTarget..'; iEntriesAboveOverdueRequirement='..iEntriesAboveOverdueRequirement..'; iLowPriorityShortlistEntryCount='..iLowPriorityShortlistEntryCount)
            else
                LOG(sFunctionRef..': End of code, tShortlist is empty,shortlist='..repru(tShortlist)..'; iLongestOverdueScoutingTarget='..iLongestOverdueScoutingTarget)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageAirScouts(iTeam, iAirSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageAirScouts'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tAvailableScouts, tScoutsForRefueling, tUnavailableUnits = GetAvailableLowFuelAndInUseAirUnits(iTeam, iAirSubteam, AiBotUnitInfo.refCategoryAirScout)

    --First record as having visual of every land/water zone that an air scout is in
    local tBombersForVision = {}
    for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
        if oBrain.AiBotAI then
            local tCurUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategoryBomber - categories.EXPERIMENTAL, false, true)
            if AiBotUtilities.IsTableEmpty(tCurUnits) == false then
                for iUnit, oUnit in tCurUnits do
                    if oUnit:GetFractionComplete() == 1 and not(oUnit:IsUnitState('Attached')) then
                        table.insert(tBombersForVision, oUnit)
                    end
                end
            end
        end
    end
    local tUnitsGivingVisual = {tAvailableScouts, tScoutsForRefueling, tUnavailableUnits, tBombersForVision}
    for iEntry, tScoutTable in tUnitsGivingVisual do
        if AiBotUtilities.IsTableEmpty(tScoutTable) == false then
            local iCurPlateauOrZero, iCurLZOrWZ
            for iUnit, oUnit in tScoutTable do
                iCurPlateauOrZero, iCurLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                if bDebugMessages == true then LOG(sFunctionRef..'; Considering Scout giving visual of a zone, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurLZOrWZ='..(iCurLZOrWZ or 'nil')) end
                if (iCurPlateauOrZero or -1) >= 0 then
                    if (iCurLZOrWZ or 0) == 0 then
                        iCurLZOrWZ = AiBotMap.GetWaterZoneFromPosition(oUnit:GetPosition())
                        if (iCurLZOrWZ or 0) > 0 then
                            iCurPlateauOrZero = -1
                        end
                    end
                    if (iCurLZOrWZ or 0) > 0 then
                        if iCurPlateauOrZero == 0 then
                            --Water zone
                            AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurLZOrWZ]][AiBotMap.subrefPondWaterZones][iCurLZOrWZ][AiBotMap.subrefWZTeamData][iTeam][AiBotMap.refiTimeLastHadVisual] = GetGameTimeSeconds()
                        else
                            --Land zone
                            local tScoutLZTeamData = AiBotMap.tAllPlateaus[iCurPlateauOrZero][AiBotMap.subrefPlateauLandZones][iCurLZOrWZ][AiBotMap.subrefLZTeamData][iTeam]

                            if not(tScoutLZTeamData) then
                                local iAltPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition())
                                if (iAltPlateau or 0) > 0 and not(iAltPlateau == iCurPlateauOrZero) then
                                    iCurPlateauOrZero = iAltPlateau
                                    tScoutLZTeamData = AiBotMap.tAllPlateaus[iCurPlateauOrZero][AiBotMap.subrefPlateauLandZones][iCurLZOrWZ][AiBotMap.subrefLZTeamData][iTeam]
                                end
                                if not(tScoutLZTeamData) then
                                    iCurPlateauOrZero, iCurLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                                    tScoutLZTeamData = AiBotMap.tAllPlateaus[iCurPlateauOrZero][AiBotMap.subrefPlateauLandZones][iCurLZOrWZ][AiBotMap.subrefLZTeamData][iTeam]
                                end
                            end
                            if tScoutLZTeamData then
                                tScoutLZTeamData[AiBotMap.refiTimeLastHadVisual] = GetGameTimeSeconds()
                            end
                        end
                    end
                end
            end
        end
    end

    --Shortlist of locations to scout if haven't recently
    UpdateScoutingShortlist(iTeam)
    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Is table of available scouts empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableScouts))..'; iAirSubteam='..iAirSubteam..'; iTeam='..iTeam) end
    if AiBotUtilities.IsTableEmpty(tAvailableScouts) == false then
        local tScoutsWithNoDestination = {}
        local tRallyPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
        --First assign any priority scouts
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout]) == false then
            --Refresh the list
            local iPriorityUnitsToScout = table.getn(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout])
            for iEntry = iPriorityUnitsToScout, 1, -1 do
                if not(AiBotUnitInfo.IsUnitValid(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout][iEntry])) or GetGameTimeSeconds() - (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout][iEntry][refiTimeLastWantedPriorityAirScout] or GetGameTimeSeconds()) >= 20 then
                    table.remove(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout], iEntry)
                end
            end
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout]) == false then
                local iCurDist, iClosestDist
                --Get priority unit to scout - prioritise non-TMD
                local oUnitToScout, iCurTimeSinceScouted
                local iLongestTimeSinceScouted = -1
                local iCurCount = 0
                while AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout]) == false do
                    iCurCount = iCurCount + 1
                    if iCurCount >= 100 then AiBotUtilities.ErrorHandler('Infinite loop protection') break end
                    for iPossibleUnitToScout, oPossibleUnitToScout in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout] do
                        iCurTimeSinceScouted = GetGameTimeSeconds() - (AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftPriorityUnitsWantingAirScout][iPossibleUnitToScout][refiTimeLastWantedPriorityAirScout] or GetGameTimeSeconds())
                        if EntityCategoryContains(AiBotUnitInfo.refCategoryTMD, oPossibleUnitToScout.UnitId) then iCurTimeSinceScouted = iCurTimeSinceScouted - math.min(90, iCurTimeSinceScouted - 1)  end --prioritise non-TMD
                        if iCurTimeSinceScouted > iLongestTimeSinceScouted then
                            iLongestTimeSinceScouted = iCurTimeSinceScouted
                            oUnitToScout = oPossibleUnitToScout
                        end
                    end
                    --Find the nearest spy plane
                    iClosestDist = 100000
                    local iClosestRef
                    for iUnit, oUnit in tAvailableScouts do
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnitToScout:GetPosition())
                        if iCurDist < iClosestDist then
                            iClosestRef = iUnit
                            iClosestDist = iCurDist
                        end
                    end
                    if iClosestRef then
                        AiBotOrders.IssueTrackedMove(tAvailableScouts[iClosestRef], oUnitToScout:GetPosition(), 10, false, 'PrASc', false)
                        table.remove(tAvailableScouts, iClosestRef)
                    end
                    if AiBotUtilities.IsTableEmpty(tAvailableScouts) then
                        break
                    end
                end
            end
        end

        if AiBotUtilities.IsTableEmpty(tAvailableScouts) == false then
            --Do we have locations available for scouting?
            if bDebugMessages == true then LOG(sFunctionRef..': Do we have locations available for scouting - is table empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftLandAndWaterZoneScoutingShortlist]))) end
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftLandAndWaterZoneScoutingShortlist]) == false then
                local tiScoutRefByDistance = {}
                for iUnit, oUnit in tAvailableScouts do
                    tiScoutRefByDistance[iUnit] = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint)
                end
                --Sort through scouts by distance and find the nearest location overdue for scouting
                local iCurDist, iClosestDist, iClosestPlateauOrZero, iClosestLZOrWZRef, tClosestMidpoint, iClosestShortlistRef
                for iUnit, iDistance in AiBotUtilities.SortTableByValue(tiScoutRefByDistance, false) do
                    if bDebugMessages == true then LOG(sFunctionRef..'; Considering air scout with iUnit ref='..iUnit..'; Air scout='..tAvailableScouts[iUnit].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tAvailableScouts[iUnit])..'; Dist to air rally point='..tiScoutRefByDistance[iUnit]) end
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftLandAndWaterZoneScoutingShortlist]) == false then


                        iClosestDist = 100000
                        for iEntry, tPlateauAndZoneRef in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftLandAndWaterZoneScoutingShortlist] do
                            local tMidpoint
                            if tPlateauAndZoneRef[1] == 0 then
                                --Waterzone
                                tMidpoint = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[tPlateauAndZoneRef[2]]][AiBotMap.subrefPondWaterZones][tPlateauAndZoneRef[2]][AiBotMap.subrefMidpoint]
                            else
                                tMidpoint = AiBotMap.tAllPlateaus[tPlateauAndZoneRef[1]][AiBotMap.subrefPlateauLandZones][tPlateauAndZoneRef[2]][AiBotMap.subrefMidpoint]
                            end
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tMidpoint, tAvailableScouts[iUnit]:GetPosition())
                            if iCurDist < iClosestDist then
                                iClosestDist = iCurDist
                                iClosestPlateauOrZero = tPlateauAndZoneRef[1]
                                iClosestLZOrWZRef = tPlateauAndZoneRef[2]
                                tClosestMidpoint = {tMidpoint[1], tMidpoint[2], tMidpoint[3]}
                                iClosestShortlistRef = iEntry
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if P'..tPlateauAndZoneRef[1]..'Z'..tPlateauAndZoneRef[2]..' is closest to the scout from the scouting shortlist, iCurDist='..iCurDist..'; iClosestDist='..iClosestDist) end
                        end
                        AiBotOrders.IssueTrackedMove(tAvailableScouts[iUnit], tClosestMidpoint, 10, false, 'ASP'..iClosestPlateauOrZero..'Z'..iClosestLZOrWZRef, false)
                        if bDebugMessages == true then LOG(sFunctionRef..': Telling scout to go to P'..iClosestPlateauOrZero..'Z'..iClosestLZOrWZRef..'; iClosestDist='..iClosestDist) end
                        --Update tracking
                        tAvailableScouts[iUnit][reftScoutAssignedPlateauAndZoneRef] = {[1] = iClosestPlateauOrZero, [2] = iClosestLZOrWZRef}
                        table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftLandAndWaterZoneScoutingShortlist], iClosestShortlistRef)
                    else
                        table.insert(tScoutsWithNoDestination, tAvailableScouts[iUnit])
                    end
                end
            else
                tScoutsWithNoDestination = tAvailableScouts
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Is tScoutsWithNoDestination empty='..tostring(AiBotUtilities.IsTableEmpty(tScoutsWithNoDestination))) end
            if AiBotUtilities.IsTableEmpty(tScoutsWithNoDestination) == false then
                for iUnit, oUnit in tScoutsWithNoDestination do
                    --If still have remaining available scouts send for refueling with lower threshold
                    if ((oUnit:GetFuelRatio() < 0.6 and oUnit:GetFuelRatio() >= 0) or AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= 0.7) and not(EntityCategoryContains(categories.CANNOTUSEAIRSTAGING, oUnit.UnitId)) then
                        table.insert(tScoutsForRefueling, oUnit)
                    else
                        AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 10, false, 'ASIdle', false)
                    end
                end
            end
        end
    end
    SendUnitsForRefueling(tScoutsForRefueling, iTeam, iAirSubteam)
    if bDebugMessages == true and AiBotUtilities.IsTableEmpty(tScoutsForRefueling) == false then
        LOG(sFunctionRef..': Will send '..table.getn(tScoutsForRefueling)..' units to refuel')
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function OnAirScoutDeath(oUnit)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'OnAirScoutDeath'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iTargetPlateauOrZero = oUnit[reftScoutAssignedPlateauAndZoneRef][1]
    local iTargetLZOrWZ = oUnit[reftScoutAssignedPlateauAndZoneRef][2]
    local tLZOrWZTeamData
    local iTeam = oUnit:GetAIBrain().AiBotTeam
    if iTargetPlateauOrZero == 0 then
        --Water zone
        tLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iTargetLZOrWZ]][AiBotMap.subrefPondWaterZones][iTargetLZOrWZ][AiBotMap.subrefWZTeamData][iTeam]
    else
        tLZOrWZTeamData = AiBotMap.tAllPlateaus[iTargetPlateauOrZero][AiBotMap.subrefPlateauLandZones][iTargetLZOrWZ][AiBotMap.subrefLZTeamData][iTeam]
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..'; Unit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; oUnit[reftScoutAssignedPlateauAndZoneRef]='..repru(oUnit[reftScoutAssignedPlateauAndZoneRef])..'; iTargetPlateauOrZero='..(iTargetPlateauOrZero or 'nil')..'; iTargetLZOrWZ='..(iTargetLZOrWZ or 'nil')..'; tLZOrWZTeamData[AiBotMap.refiRecentlyFailedScoutAttempts]='..(tLZOrWZTeamData[AiBotMap.refiRecentlyFailedScoutAttempts] or 'nil')..'; iTeam='..(iTeam or 'nil')) end
    tLZOrWZTeamData[AiBotMap.refiRecentlyFailedScoutAttempts] = tLZOrWZTeamData[AiBotMap.refiRecentlyFailedScoutAttempts] + 1
    ForkThread(DelayAirScoutVariableChange, tLZOrWZTeamData)
    oUnit[reftScoutAssignedPlateauAndZoneRef] = nil
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end
function DelayAirScoutVariableChange(tLZOrWZTeamData)
    WaitSeconds(300)
    tLZOrWZTeamData[AiBotMap.refiRecentlyFailedScoutAttempts] = math.max(0, tLZOrWZTeamData[AiBotMap.refiRecentlyFailedScoutAttempts] - 1)
end

function AddZoneToPotentialDropZonesSameIslandOrDifPond(iTeam, iPlateauOrZero, iLandOrWaterZone)
    if iPlateauOrZero == 0 then
        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialPondDropZones]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialPondDropZones] = {} end --redundancy
        table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialPondDropZones], iLandOrWaterZone)
    else
        if not( AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau]) then
            AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau] = {}
        end
        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau][iPlateauOrZero]) then
            if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau] = {} end
            AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau][iPlateauOrZero] = {}
        end
        table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau][iPlateauOrZero], iLandOrWaterZone)
    end
end

function UpdateTransportShortlistForFarAwayLandZoneDrops(iTeam)
    --Once per game generate list of land zones that are on the same island as a base but far away, or are on an island with lots of zones but far away from the existing island, so we can consider dropping these as well
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateTransportShortlistForFarAwayLandZoneDrops'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    --Dont even consider for small maps
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code at time '..GetGameTimeSeconds()..' for team '..iTeam..'; iMapSize='..AiBotMap.iMapSize) end
    if AiBotMap.iMapSize > 256 then
        if not( AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau]) then --redundancy (this function should only be called once per team each game)

            AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau] = {}
            --Generate shortlist of islands that have a friendly AiBotAI base on them
            local tiPlayerStartByPlateauAndIsland = {}
            local iCurPlateau, iCurLZ, iCurIsland

            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                local tStartPoint = AiBotMap.GetPlayerStartPosition(oBrain)
                iCurPlateau, iCurLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tStartPoint)
                iCurIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tStartPoint)
                if (iCurIsland or 0) > 0 and (iCurLZ or 0) > 0 then
                    if not(tiPlayerStartByPlateauAndIsland[iCurPlateau]) then tiPlayerStartByPlateauAndIsland[iCurPlateau] = {} end
                    tiPlayerStartByPlateauAndIsland[iCurPlateau][iCurIsland] = true
                end
            end

            --Add in large land zone count islands
            local tiOtherFarAwayIslandsByPlateau = {}
            for iPlateau, tPlateauSubtable in AiBotMap.tAllPlateaus do
                if AiBotUtilities.IsTableEmpty(tPlateauSubtable[AiBotMap.subrefPlateauIslandLandZones]) == false then
                    for iIsland, iLZCount in tPlateauSubtable[AiBotMap.subrefPlateauIslandLandZones] do
                        if iLZCount >= 10 and  (tPlateauSubtable[AiBotMap.subrefPlateauIslandMexCount][iIsland] or 0) >= 14 then
                            if not(tiOtherFarAwayIslandsByPlateau[iPlateau]) then tiOtherFarAwayIslandsByPlateau[iPlateau] = {} end
                            tiOtherFarAwayIslandsByPlateau[iPlateau][iIsland] = true
                        end
                    end
                end
            end

            local iTravelDistance, iClosestBasePlateau, iClosestBaseLandZone
            local iTravelThreshold = 200
            if AiBotMap.iMapSize >= 1000 then iTravelThreshold = 260 end

            function ConsiderAddingZoneInIsland(iPlateau, iIsland, iLandZone, bCheckDistFromExistingDropLocations, iMexThresholdOverride, bIncludeAdjacentZoneMexCount)
                local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                local iMexesAvailable = (tLZData[AiBotMap.subrefLZOrWZMexCount] or 0)
                if bIncludeAdjacentZoneMexCount and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                    for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                        local tAdjLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                        iMexesAvailable = iMexesAvailable + (tAdjLZData[AiBotMap.subrefLZOrWZMexCount] or 0)
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Considering iLandZone='..iLandZone..'; with mexcount='..(tLZData[AiBotMap.subrefLZOrWZMexCount] or 0)..'; iMexesAvailable='..iMexesAvailable..'; bIncludeAdjacentZoneMexCount='..tostring(bIncludeAdjacentZoneMexCount or false)..'; iMexThresholdOverride='..(iMexThresholdOverride or 'nil')..'; iTeam='..iTeam) end
                if iMexesAvailable >= (iMexThresholdOverride or 1) then
                    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                    --Is it on our side of the map (or almost on our side of the map)?
                    if bDebugMessages == true then LOG(sFunctionRef..': refiModDistancePercent='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; subrefTotalSignificantMassReclaim='..(tLZTeamData[AiBotMap.subrefTotalSignificantMassReclaim] or 'nil')) end
                    if tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.55 and not(tLZTeamData[AiBotMap.subrefLZbCoreBase]) and ((iMexesAvailable >= (iMexThresholdOverride or 3) or (tLZData[AiBotMap.subrefTotalSignificantMassReclaim] >= 300 and iMexesAvailable + tLZData[AiBotMap.subrefTotalSignificantMassReclaim] / 300 >= 3))) and (tLZTeamData[AiBotMap.refiNonAiBotTeammateFactoryCount] or 0) == 0  then --core base check is a redundancy, not even sure if it gets set before this code runs anyway
                        --Get travel distance to closest friendly base
                        iClosestBasePlateau, iClosestBaseLandZone = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                        if bDebugMessages == true then LOG(sFunctionRef..': iClosestBasePlateau='..(iClosestBasePlateau or 'nil')..'; iClosestBaseLandZone='..(iClosestBaseLandZone or 'nil')) end
                        if (iClosestBaseLandZone or 0) > 0 and iClosestBasePlateau == iPlateau then
                            iTravelDistance = (AiBotMap.GetTravelDistanceBetweenLandZones(iPlateau, iClosestBaseLandZone, iLandZone) or 10000)
                            if bDebugMessages == true then LOG(sFunctionRef..': iClosestBaseLandZone='..(iClosestBaseLandZone or 'nil')..'; iTravelDistance='..(iTravelDistance or 'nil')) end
                            if iTravelDistance >= 275 then
                                local bDropLocation = true
                                if  bCheckDistFromExistingDropLocations then
                                    if iPlateau > 0 and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau][iPlateau]) == false then
                                        for iExistingEntry, iExistingLandZone in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau][iPlateau] do
                                            local tExistingLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iExistingLandZone]
                                            if bDebugMessages == true then LOG(sFunctionRef..': Already have a drop location for this plateau for zone '..iExistingLandZone..'; Travel dist to here='..(AiBotMap.GetTravelDistanceBetweenLandZones(iPlateau, iLandZone, iExistingLandZone) or 'nil')) end
                                            if (AiBotMap.GetTravelDistanceBetweenLandZones(iPlateau, iLandZone, iExistingLandZone) or 10000) <= iTravelThreshold then
                                                bDropLocation = false
                                                break
                                            end
                                        end
                                    end
                                end
                                --Want to consider dropping this location during the game
                                if bDropLocation then
                                    AddZoneToPotentialDropZonesSameIslandOrDifPond(iTeam, iPlateau, iLandZone)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Added plateau and zone to potential drop zones, iPlateau='..iPlateau..'; iLandZone='..iLandZone) end
                                end
                            end
                        end
                    end
                end
            end

            function ConsiderAdditionalDropZoneForIsland(iPlateau, iIsland, bCheckDistFromExistingDropLocations)
                if bDebugMessages == true then LOG(sFunctionRef..': Considering iIsland '..iIsland..' in iPlateau='..iPlateau) end
                if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandLandZones][iIsland]) == false then
                    for iEntry, iLandZone in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandLandZones][iIsland] do
                        ConsiderAddingZoneInIsland(iPlateau, iIsland, iLandZone, bCheckDistFromExistingDropLocations, nil, false)
                    end
                    --20km+ maps - go again, this time without the mex threshold
                    for iEntry, iLandZone in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandLandZones][iIsland] do
                        ConsiderAddingZoneInIsland(iPlateau, iIsland, iLandZone, true, 3, true)
                    end
                end
            end

            --Cycle through each of these islands, and find land zones iwth lots of mexes (3+) that we want to consider expanding to
            if AiBotUtilities.IsTableEmpty(tiPlayerStartByPlateauAndIsland) == false then
                for iPlateau, tSubtable in tiPlayerStartByPlateauAndIsland do
                    for iIsland, bConsider in tSubtable do
                        ConsiderAdditionalDropZoneForIsland(iPlateau, iIsland, false)
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(tiOtherFarAwayIslandsByPlateau) == false then
                for iPlateau, tSubtable in tiOtherFarAwayIslandsByPlateau do
                    for iIsland, bConsider in tSubtable do
                        ConsiderAdditionalDropZoneForIsland(iPlateau, iIsland, true)
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau]='..repru(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau])) end
    --Active check - i.e. factoring in current conditions, do we still want to drop the zone?
    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportFarAwaySameIslandPlateauLandZoneDropShortlist] = {}
    local tShortlist = AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportFarAwaySameIslandPlateauLandZoneDropShortlist]
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau]) == false then
        local tiPlateauAndZoneWithAdjacentEngineers = {}
        local bCampaignMap = AiBotMap.bIsCampaignMap
        --Dont drop if we have engineers in this zone or adjacent, or there are dangerous enemy units
        for iPlateau, tLandZones in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau] do
            for iEntry, iLandZone in tLandZones do
                local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                if bDebugMessages == true then LOG(sFunctionRef..': Considering the land zone '..iLandZone..' in iPlateau='..iPlateau..'; tLZTeamData[AiBotMap.subrefLZSValue]='..tLZTeamData[AiBotMap.subrefLZSValue]..'; subrefLZOrWZMexCount='..(tLZData[AiBotMap.subrefLZOrWZMexCount] or 'nil')) end
                if tLZTeamData[AiBotMap.subrefLZSValue] <= 200 and (tLZTeamData[AiBotMap.refiNonAiBotTeammateFactoryCount] or 0) == 0 and (tLZTeamData[AiBotMap.refiTransportRecentUnloadCount] or 0) < 3 then --i.e. dont have a land factory or better in the zone, or if we have dropped at least twice recently here
                    --Check we havent already got mexes on any of the positions
                    if bDebugMessages == true then LOG(sFunctionRef..': tLZTeamData[AiBotMap.subrefMexCountByTech]='..repru(tLZTeamData[AiBotMap.subrefMexCountByTech])) end
                    if tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3] == 0 then
                        if bDebugMessages == true then
                            LOG(sFunctionRef..': tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]='..tostring(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ])..'; tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]='..(tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')..'; Is table of units to repair empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToRepair]))..'; Is midpoint in playable area='..tostring(AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]))..'; bCampaignMap='..tostring(bCampaignMap)..'; First unit to repair='..(tLZData[AiBotMap.subreftoUnitsToRepair][1].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(tLZData[AiBotMap.subreftoUnitsToRepair][1]) or 'nil'))
                            if tLZData[AiBotMap.subreftoUnitsToRepair][1] then LOG(sFunctionRef..': Health percent of first unit to repair='..AiBotUnitInfo.GetUnitHealthPercent(tLZData[AiBotMap.subreftoUnitsToRepair][1])) end
                        end

                        if (not(tLZTeamData[AiBotMap.subrefbDangerousEnemiesInThisLZ]) and (tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) == 0) or (bCampaignMap and AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint]) and AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToRepair]) == false and AiBotUnitInfo.GetUnitHealthPercent(tLZData[AiBotMap.subreftoUnitsToRepair][1]) <= 0.15) then
                            --Do we want BP for this zone?
                            if bDebugMessages == true then LOG(sFunctionRef..': tLZTeamData[AiBotMap.subrefTbWantBP]='..tostring(tLZTeamData[AiBotMap.subrefTbWantBP] or false)..'; tLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted]='..repru(tLZTeamData[AiBotMap.subrefTBuildPowerByTechWanted])) end
                            local bBPWanted = tLZTeamData[AiBotMap.subrefTbWantBP]
                            if not(bBPWanted) then
                                --Do we not want BP because we have engineers trying to travel here?
                                if bDebugMessages == true then LOG(sFunctionRef..': Is subrefTEngineersTravelingHere empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEngineersTravelingHere]))) end
                                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false then
                                    if AiBotMap.bIsCampaignMap then bBPWanted = true
                                    else
                                        local iClosestEngineer = 100000
                                        local iCurDist
                                        for iEngineer, oEngineer in tLZTeamData[AiBotMap.subrefTEngineersTravelingHere] do
                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                            if iCurDist < iClosestEngineer then
                                                iClosestEngineer = iCurDist
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': iClosestEngineer='..iClosestEngineer) end
                                        if iClosestEngineer >= 120 then
                                            bBPWanted = true
                                        end
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': bBPWanted='..tostring(bBPWanted)) end
                            if bBPWanted then
                                --Do we have any engineers or factories in this zone?
                                if bDebugMessages == true then LOG(sFunctionRef..': Is table of allied units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))) end
                                local bHaveUnattachedEngineersOrFactories = false
                                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) then
                                    --Do nothing - no allied units there so no engineers or factories will be there
                                else
                                    local tFactoriesAndEngineers = AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryEngineer + categories.COMMAND + categories.SUBCOMMANDER, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))
                                    if AiBotUtilities.IsTableEmpty(tFactoriesAndEngineers) == false then
                                        --This will include transport if it is about to land
                                        for iUnit, oUnit in tFactoriesAndEngineers do
                                            if not(oUnit:IsUnitState('Attached')) and oUnit:GetFractionComplete() == 1 then
                                                bHaveUnattachedEngineersOrFactories = true
                                            end
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Is table of allied units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))..'; bHaveUnattachedEngineersOrFactories='..tostring(bHaveUnattachedEngineersOrFactories)) end
                                if not(bHaveUnattachedEngineersOrFactories) then
                                    --Do we have engineers in an adjacent zone?
                                    local bHaveNearbyFactoriesOrLargeThreat = false
                                    local bAlreadyHaveTransportTravelingHere = false
                                    if tLZTeamData[AiBotMap.refiTransportRecentUnloadCount] == 1 and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime][tLZData[AiBotMap.subrefLZIslandRef]][iLandZone]) then bAlreadyHaveTransportTravelingHere = true end

                                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                        for _, iAdjLZ in tLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                                            if bDebugMessages == true then LOG(sFunctionRef..': iAdjLZ='..iAdjLZ..'; tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..(tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; Is table of allied units empty='..tostring(AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))..'; tAdjLZTeamData[AiBotMap.refiTransportRecentUnloadCount]='..(tAdjLZTeamData[AiBotMap.refiTransportRecentUnloadCount] or 'nil')..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime][tLZData[AiBotMap.subrefLZIslandRef][iLandZone]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime][tLZData[AiBotMap.subrefLZIslandRef]][iLandZone] or 'nil')) end
                                            if tAdjLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] > 100 and not(bCampaignMap) then
                                                --Check how close the enemy unit is if we already have a transport heading to the base location
                                                if not(bAlreadyHaveTransportTravelingHere) then
                                                    bHaveNearbyFactoriesOrLargeThreat = true
                                                    break
                                                else
                                                    local iDistThreshold = 160
                                                    local iCurDist
                                                    if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                                        local tEnemyCombat = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandCombat, tAdjLZTeamData[AiBotMap.subrefTEnemyUnits])
                                                        if AiBotUtilities.IsTableEmpty(tEnemyCombat) == false then
                                                            for iUnit, oUnit in tEnemyCombat do
                                                                if AiBotUnitInfo.IsUnitValid(oUnit) then
                                                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                                                                    if bDebugMessages == true then LOG(sFunctionRef..': Dist of enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to midpoint='..iCurDist) end
                                                                    if iCurDist < iDistThreshold then
                                                                        if bDebugMessages == true then LOG(sFunctionRef..': Enemy is too close, no longer include as potential drop zone') end
                                                                        bHaveNearbyFactoriesOrLargeThreat = true
                                                                        break
                                                                    end
                                                                end
                                                            end
                                                            if bHaveNearbyFactoriesOrLargeThreat then break end
                                                        end
                                                    end
                                                end
                                            end
                                            if not(bHaveNearbyFactoriesOrLargeThreat) then
                                                if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                                    local tFactoriesAndEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory + AiBotUnitInfo.refCategoryEngineer + categories.COMMAND + categories.SUBCOMMANDER, tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                                    if AiBotUtilities.IsTableEmpty(tFactoriesAndEngineers) == false then
                                                        for iUnit, oUnit in tFactoriesAndEngineers do
                                                            if not(oUnit:IsUnitState('Attached')) and oUnit:GetFractionComplete() == 1 then
                                                                bHaveUnattachedEngineersOrFactories = true

                                                                if EntityCategoryContains(AiBotUnitInfo.refCategoryFactory, oUnit.UnitId) then
                                                                    bHaveNearbyFactoriesOrLargeThreat = true
                                                                    break
                                                                end
                                                            end
                                                        end
                                                        if bDebugMessages == true then LOG(sFunctionRef..': bHaveUnattachedEngineersOrFactories='..tostring(bHaveUnattachedEngineersOrFactories)..'; Either we have engineers/factory or enemy has combat threat in this adj LZ') end
                                                        if bHaveNearbyFactoriesOrLargeThreat then break end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                    if not(bHaveNearbyFactoriesOrLargeThreat) then
                                        --Check the zone itself as well
                                        if bDebugMessages == true then LOG(sFunctionRef..': No major adjacent enemy threats, considering zone itself, enemy combat='..(tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)..'; Enemy ground AA='..tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]))) end
                                        if not(bCampaignMap) and ((tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) >= 100 or tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] >= 175) then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Drop zone itself has too great an enemy threat') end
                                            bHaveNearbyFactoriesOrLargeThreat = true
                                        end
                                    end
                                    if not(bHaveNearbyFactoriesOrLargeThreat) then
                                        if not(bHaveUnattachedEngineersOrFactories) then
                                            --Want to add to shortlist to consider dropping
                                            if bDebugMessages == true then LOG(sFunctionRef..': Adding plateau '..iPlateau..'; land zone '..iLandZone..'; to shortlist of locations to consider dropping') end
                                            table.insert(tShortlist, {iPlateau, iLandZone})
                                        else
                                            --Add to lower priority shortlist
                                            table.insert(tiPlateauAndZoneWithAdjacentEngineers, {iPlateau, iLandZone})
                                            if bDebugMessages == true then LOG(sFunctionRef..': Have adjacent zone with engineers but no factory or significant enemy threat so will still consider dropping') end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(tShortlist) and AiBotUtilities.IsTableEmpty(tiPlateauAndZoneWithAdjacentEngineers) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': Dont have high priority transport drop location but do have a lower priority one with adjacent engineers') end
                for iEntry, tSubtable in tiPlateauAndZoneWithAdjacentEngineers do
                    table.insert(tShortlist, {tSubtable[1], tSubtable[2]})
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, tShortlist='..repru(tShortlist)) end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RecordPotentialCombatDropShortlist(iTeam)
    --Should only be called once per game - determines plateaus and zones where we should consider dropping with t1 arti if enemy has vulnerable mexes
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordPotentialCombatDropShortlist'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --First record start positions for all players as dont want to drop these regardless
    local toBrainsToConsider = {}
    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains] do
        table.insert(toBrainsToConsider, oBrain)
    end
    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
        table.insert(toBrainsToConsider, oBrain)
    end
    local iCurPlateau, iCurLZ
    local tbPlayerStartByPlateauAndZone = {}
    local tbFriendlyPlateaus = {}
    for iBrain, oBrain in toBrainsToConsider do
        local tEnemyStart = AiBotMap.GetPlayerStartPosition(oBrain)
        iCurPlateau, iCurLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tEnemyStart)
        if iCurPlateau and iCurLZ then
            if not(tbPlayerStartByPlateauAndZone[iCurPlateau]) then tbPlayerStartByPlateauAndZone[iCurPlateau] = {} end
            if bDebugMessages == true then LOG(sFunctionRef..': tEnemyStart='..repru(tEnemyStart)..' for brain '..oBrain.Nickname..'; iCurPlateau='..(iCurPlateau or 'nil')..'; iCurLZ='..(iCurLZ or 'nil')) end
            tbPlayerStartByPlateauAndZone[iCurPlateau][iCurLZ] = true
            if oBrain.AiBotTeam == iTeam then tbFriendlyPlateaus[iCurPlateau] = true end
        end
    end

    --Now cycle through every plateau and identify any zone with 2+ mexes in it
    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialCombatDropZonesByPlateau] = {}
    for iPlateau, tPlateauSubtable in AiBotMap.tAllPlateaus do
        local iTotalMexThreshold = 2
        if table.getn(AiBotMap.tMassPoints) / AiBotTeam.iPlayersAtGameStart <= 15 then iTotalMexThreshold = 1 end
        if (tPlateauSubtable[AiBotMap.subrefPlateauTotalMexCount] or 0) >= iTotalMexThreshold then
            for iLandZone, tLZData in tPlateauSubtable[AiBotMap.subrefPlateauLandZones] do
                if (tLZData[AiBotMap.subrefLZOrWZMexCount] or 0) >= iTotalMexThreshold then
                    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                    --Ignore zones that can path to with land from a friendly base, or which are in a friendly or enemy base
                    if (tbFriendlyPlateaus[iPlateau] and tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.2) or tbPlayerStartByPlateauAndZone[iPlateau][iLandZone] then
                        --Ignore
                    else
                        --Have a land zone, with 2+ mexes (unless iTotalMexThreshold is 1), so shoudl consider dropping it for the main combat drop logic
                        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialCombatDropZonesByPlateau][iPlateau]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialCombatDropZonesByPlateau][iPlateau] = {} end
                        table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialCombatDropZonesByPlateau][iPlateau], iLandZone)
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateTransportShortlistForPondDrops(iTeam, tbPlateausWithPlayerStartOrIslandDrop)
    --See if we have any underwater mexes on a plateau that doesnt have an island drop planned or a player start position
    --This is only called once each game per team; must be called after the 'far away land zone' logic or else far away land zone logic wont run at all due to check if below table is nil
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateTransportShortlistForPondDrops'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not( AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialPondDropZones]) then
        AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialPondDropZones] = {}
        if AiBotUtilities.IsTableEmpty(AiBotMap.tPondDetails) == false then
            local tWZWithUnderwaterMexesByPond = {}
            local iCurMexPlateau, iCurMexPond, iCurSegmentX, iCurSegmentZ, iCurWZ
            local tbWZConsidered = {}
            for iMex, tMex in AiBotMap.tMassPoints do
                if AiBotMap.IsUnderwater(tMex) then
                    iCurMexPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tMex)
                    iCurSegmentX, iCurSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tMex)
                    iCurWZ = AiBotMap.tWaterZoneBySegment[iCurSegmentX][iCurSegmentZ]
                    if iCurWZ and not(tbWZConsidered[iCurWZ]) then
                        tbWZConsidered[iCurWZ] = true
                        local tWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurWZ]][AiBotMap.subrefPondWaterZones][iCurWZ]
                        local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                        if tWZTeamData[AiBotMap.reftClosestFriendlyBase] then
                            if bDebugMessages == true then LOG(sFunctionRef..': Have an underwater mex, tMex='..repru(tMex)..'; iCurMexPlateau='..(iCurMexPlateau or 'nil')..'; tbPlateausWithPlayerStartOrIslandDrop[iCurMexPlateau]='..tostring(tbPlateausWithPlayerStartOrIslandDrop[iCurMexPlateau] or false)..'; Dist from midpoint to closest base='..AiBotUtilities.GetDistanceBetweenPositions(tWZData[AiBotMap.subrefMidpoint], tWZTeamData[AiBotMap.reftClosestFriendlyBase])..'; iCurWZ='..iCurWZ) end
                            if iCurMexPlateau and not(tbPlateausWithPlayerStartOrIslandDrop[iCurMexPlateau]) or (AiBotUtilities.GetDistanceBetweenPositions(tWZData[AiBotMap.subrefMidpoint], tWZTeamData[AiBotMap.reftClosestFriendlyBase]) >= math.max(130, AiBotMap.iMapSize * 0.3) and AiBotUtilities.GetDistanceBetweenPositions(tWZData[AiBotMap.subrefMidpoint], tWZTeamData[AiBotMap.reftClosestEnemyBase]) >= math.max(130, AiBotMap.iMapSize * 0.4)) then


                                iCurMexPond = AiBotMap.tiPondByWaterZone[iCurWZ]
                                if iCurMexPond then
                                    if not(tWZWithUnderwaterMexesByPond[iCurMexPond]) then tWZWithUnderwaterMexesByPond[iCurMexPond] = {} end
                                    table.insert(tWZWithUnderwaterMexesByPond[iCurMexPond], iCurWZ)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding iCurWZ='..iCurWZ..' to list of water zones to consider dropping, iCurMexPond='..iCurMexPond) end
                                end
                            end
                        end
                    end
                end
            end
            local tbPondsInDropList = {}
            if AiBotUtilities.IsTableEmpty(tWZWithUnderwaterMexesByPond) == false then
                for iPond, tWZs in tWZWithUnderwaterMexesByPond do
                    --Get the mex that is closest to a friendly base
                    local iCurDist
                    local iClosestDist = 100000
                    local iClosestWZRef
                    for iEntry, iWaterZone in tWZs do
                        local tWZData = AiBotMap.tPondDetails[iPond][AiBotMap.subrefPondWaterZones][iWaterZone]
                        local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                        if tWZTeamData[AiBotMap.reftClosestFriendlyBase] then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tWZData[AiBotMap.subrefMidpoint], tWZTeamData[AiBotMap.reftClosestFriendlyBase])
                            if iCurDist < iClosestDist then
                                iClosestWZRef = iWaterZone
                                iClosestDist = iCurDist
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iPond='..iPond..'; iClosestWZRef='..(iClosestWZRef or 'nil')..'; iClosestDist='..iClosestDist) end
                    if iClosestWZRef then
                        if bDebugMessages == true then LOG(sFunctionRef..': Adding water zone '..iClosestWZRef..' to potential drop zones') end
                        AddZoneToPotentialDropZonesSameIslandOrDifPond(iTeam, 0, iClosestWZRef)
                        tbPondsInDropList[AiBotMap.tiPondByWaterZone[iClosestWZRef]] = true
                    end
                end
            end
            --Consider dropping pond naval start positions
            local iCurTravelDist
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering priority pond for brain='..oBrain.Nickname..'; refiPriorityPondRef='..(oBrain[AiBotNavy.refiPriorityPondRef] or 'nil')..'; tbPondsInDropList='..repru(tbPondsInDropList)) end
                if oBrain[AiBotNavy.refiPriorityPondRef] and not(tbPondsInDropList[AiBotNavy.refiPriorityPondRef]) then
                    local tNavalBuildLocation = AiBotMap.tPondDetails[oBrain[AiBotNavy.refiPriorityPondRef]][AiBotMap.subrefBuildLocationByStartPosition][oBrain:GetArmyIndex()]
                    if AiBotUtilities.IsTableEmpty(tNavalBuildLocation) == false then
                        --How far away is this naval build location to our start position?
                        local iTargetPlateau, iTargetWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tNavalBuildLocation)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering adding naval build location to transport drop dist, iTargetWZ='..(iTargetWZ or 'nil')..'; Brain='..oBrain.Nickname..'; Dist from naval build location to base='..AiBotUtilities.GetDistanceBetweenPositions(tNavalBuildLocation, AiBotMap.GetPlayerStartPosition(oBrain))) end
                        if iTargetWZ and iTargetPlateau == 0 then
                            iCurTravelDist = (AiBotUtilities.GetTravelDistanceBetweenPositions(AiBotMap.GetPlayerStartPosition(oBrain), tNavalBuildLocation, AiBotMap.refPathingTypeHover) or AiBotUtilities.GetDistanceBetweenPositions(tNavalBuildLocation, AiBotMap.GetPlayerStartPosition(oBrain)) + 150)
                            if bDebugMessages == true then LOG(sFunctionRef..': iCurTravelDist='..iCurTravelDist) end
                            if iCurTravelDist >= 150 then

                                AddZoneToPotentialDropZonesSameIslandOrDifPond(iTeam, 0, iTargetWZ)
                                tbPondsInDropList[AiBotMap.tiPondByWaterZone[iTargetWZ]] = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Adding naval zone to drop location, iTargetWZ='..iTargetWZ) end
                            end
                        end
                    end
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateTransportPlateauDropLocationShortlist(iTeam, bUpdateCombatDropShortlist)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateTransportPlateauDropLocationShortlist'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastTransportShortlistUpdate] = GetGameTimeSeconds()
    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportIslandDropShortlist] = {}
    local tbPlateausWithPlayerStartOrIslandDrop = {}

    --First record (once per game) potential islands to consider dropping for this team
    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropIslandsByPlateau]) and AiBotMap.bRecordedIslands then
        if bDebugMessages == true then LOG(sFunctionRef..': About to do one-off exercise at start of game to identify islands to drop, time='..GetGameTimeSeconds()) end
        AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropIslandsByPlateau] = {}
        --First identify any islands by plateau that have mexes and dont have an enemy or friendly start position
        local tiPlayerStartByPlateauAndIsland = {}
        local iCurPlateau, iCurLZ, iCurIsland
        local toBrainsToConsider = {}

        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains] do
            table.insert(toBrainsToConsider, oBrain)
        end
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyHumanAndAIBrains] do
            table.insert(toBrainsToConsider, oBrain)
        end
        for iBrain, oBrain in toBrainsToConsider do
            local tEnemyStart = AiBotMap.GetPlayerStartPosition(oBrain)
            iCurPlateau, iCurLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tEnemyStart)
            iCurIsland = NavUtils.GetLabel(AiBotMap.refPathingTypeLand, tEnemyStart)
            if (iCurIsland or 0) > 0 then
                if not(tiPlayerStartByPlateauAndIsland[iCurPlateau]) then tiPlayerStartByPlateauAndIsland[iCurPlateau] = {} end
                if bDebugMessages == true then LOG(sFunctionRef..': tEnemyStart='..repru(tEnemyStart)..' for brain '..oBrain.Nickname..'; iCurPlateau='..(iCurPlateau or 'nil')..'; iCurIsland='..(iCurIsland or 'nil')) end
                tiPlayerStartByPlateauAndIsland[iCurPlateau][iCurIsland] = true
            end
        end

        --Cycle through every island, check it's not listed in the above table, and then record as a potential island to consider dropping
        local bAlreadyIncluded = false
        local iClosestLZToBase, iClosestBasePlateau, iClosestBaseLZ, iCurDistToFriendlyBase

        for iPlateau, tPlateauSubtable in AiBotMap.tAllPlateaus do
            if bDebugMessages == true then LOG(sFunctionRef..': Considering iPlateau='..iPlateau..'; Is table of island land zones empty='..tostring(AiBotUtilities.IsTableEmpty(tPlateauSubtable[AiBotMap.subrefPlateauIslandLandZones]))) end
            if AiBotUtilities.IsTableEmpty(tPlateauSubtable[AiBotMap.subrefPlateauIslandLandZones]) == false then
                for iIsland, tLandZonesInIsland in tPlateauSubtable[AiBotMap.subrefPlateauIslandLandZones] do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iIsland='..iIsland..'; tiPlayerStartByPlateauAndIsland[iPlateau][iIsland]='..reprs(tiPlayerStartByPlateauAndIsland[iPlateau][iIsland])..'; Mex count='..(tPlateauSubtable[AiBotMap.subrefPlateauIslandMexCount][iIsland] or 0)) end
                    if not(tiPlayerStartByPlateauAndIsland[iPlateau][iIsland]) then
                        --Does the island have mexes? (v90 - effectively removed this requirement and just require that it has land zones, while later on have a requirement for there to be mexes or reclaim)
                        if (tPlateauSubtable[AiBotMap.subrefPlateauIslandMexCount][iIsland] or 0) > 0 or AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandLandZones][iIsland]) == false or AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandUnitsToCapture][iIsland]) == false then
                            if AiBotUtilities.IsTableEmpty(AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandLandZones][iIsland]) then AiBotUtilities.ErrorHandler('Island has mexes but no land zone')
                            else
                                local iSignificantReclaimValue = 0
                                --Are we close to a friendly base (such that there's no point trying to drop here?)
                                iClosestLZToBase = 100000
                                iClosestBasePlateau = nil
                                iClosestBaseLZ = nil
                                --Cycle through every land zone to check for friendly bases on the same plateau, and for how many mexes we have built on
                                for iEntry, iLandZone in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandLandZones][iIsland] do
                                    local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                                    --if not(tLZData[AiBotMap.subrefLastReclaimRefresh]) then
                                    --AiBotMap.RefreshLandOrWaterZoneReclaimValue(iPlateau, iLandZone, false, true, true) --end --reworked how reclaim zones are updated so this should no longer be necessary
                                    iSignificantReclaimValue = iSignificantReclaimValue + (tLZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0)
                                    local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                                    --Treat capturable units as being worth 70% of their mass cost
                                    if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToCapture]) == false then iSignificantReclaimValue = iSignificantReclaimValue + AiBotUnitInfo.GetMassCostOfUnits(tLZData[AiBotMap.subreftoUnitsToCapture]) * 0.7 end
                                    --Get plateau of the nearest allied base for the first entry, since presumably all land zones have the same plateau, so stop searching if the first one is on a dif plateau
                                    if not(iClosestBasePlateau) then
                                        iClosestBasePlateau, iClosestBaseLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tLZTeamData[AiBotMap.reftClosestFriendlyBase])
                                        if not(iClosestBasePlateau) then break
                                        end
                                    end
                                    iCurDistToFriendlyBase = (AiBotUtilities.GetApproxTravelDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestFriendlyBase], tLZTeamData[AiBotMap.subrefMidpoint]) or 100000)
                                    if iCurDistToFriendlyBase < iClosestLZToBase then
                                        iClosestLZToBase = iCurDistToFriendlyBase
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': P'..iPlateau..'Z'..iLandZone..'; tLZOrWZData[subrefLastReclaimRefresh]='..(tLZData[AiBotMap.subrefLastReclaimRefresh] or 'nil')..'; iCurDistToFriendlyBase='..iCurDistToFriendlyBase..'; Signif reclaim val for just this zone='..(tLZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0)..'; Is table of units to capture empty='..tostring(AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToCapture]))) end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering island '..iIsland..'; iClosestLZToBase='..iClosestLZToBase..'; iClosestBasePlateau='..(iClosestBasePlateau or 'nil')..'; iClosestLZToBase='..(iClosestLZToBase or 'nil')..'; Island mex count='..tPlateauSubtable[AiBotMap.subrefPlateauIslandMexCount][iIsland]..'; iSignificantReclaimValue='..iSignificantReclaimValue) end
                                if iClosestLZToBase >= 190 or (iClosestLZToBase >= 140 and tPlateauSubtable[AiBotMap.subrefPlateauIslandMexCount][iIsland] >= 7) or (not(iClosestBasePlateau == iPlateau) and (tPlateauSubtable[AiBotMap.subrefPlateauIslandMexCount][iIsland] or 0) > 0) then
                                    bAlreadyIncluded = false
                                    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropIslandsByPlateau][iPlateau]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropIslandsByPlateau][iPlateau] = {}
                                    else
                                        for iEntry, iRecordedIsland in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropIslandsByPlateau][iPlateau] do
                                            if iIsland == iRecordedIsland then
                                                bAlreadyIncluded = true
                                                break
                                            end
                                        end
                                    end
                                    if not(bAlreadyIncluded) then
                                        --A transport is 120 mass, an engi is 52 mass, so want >200 mass for it to be worthwhile to consider dropping engi (on assumption will also be some lower value reclaim to give a profit)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Deciding whether to include iIsland='..iIsland..'; iSignificantReclaimValue='..iSignificantReclaimValue..'; iReclaimWantedForTransportDrop='..iReclaimWantedForTransportDrop) end
                                        if (tPlateauSubtable[AiBotMap.subrefPlateauIslandMexCount][iIsland] or 0) > 0 or iSignificantReclaimValue >= iReclaimWantedForTransportDrop then
                                            --this is a 1-off at game start that records locations we might conceivably want to drop during the game - see later loop which factors in things like friendly units
                                            if bDebugMessages == true then
                                                LOG(sFunctionRef..': Including iIsland='..iIsland..' on iPlateau='..iPlateau..' in potential drop locations, mex count='..(tPlateauSubtable[AiBotMap.subrefPlateauIslandMexCount][iIsland] or 0)..'; iSignificantReclaimValue='..iSignificantReclaimValue)
                                                AiBotMap.DrawSpecificLandZone(iPlateau, AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandLandZones][iIsland][1], math.random(1, 8))
                                            end
                                            table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropIslandsByPlateau][iPlateau], iIsland)
                                            tbPlateausWithPlayerStartOrIslandDrop[iPlateau] = true
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end

        --Consider ponds with mexes that cant be reached by land - most of the logic is handled in UpdateTransportShortlistForPondDrops
        --First record all plateaus that have a player start position
        for iBrain, oBrain in toBrainsToConsider do
            local tPlayerStart = AiBotMap.GetPlayerStartPosition(oBrain)
            local iStartPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tPlayerStart)
            if iStartPlateau then tbPlateausWithPlayerStartOrIslandDrop[iStartPlateau] = true end
        end
    end

    local tShortlist = AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportIslandDropShortlist]
    local bDontCheckPlayableArea = not(AiBotMap.bIsCampaignMap)
    local bDontHaveLocationInPlayableArea
    --Now go through potential islands to consider dropping, and decide which of them we want in the shortlist if any
    if bDebugMessages == true then LOG(sFunctionRef..': Time='..GetGameTimeSeconds()..' About to create shortlist of isalnds to drop, is reftiPotentialDropIslandsByPlateau empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropIslandsByPlateau]))..'; repru of this='..repru(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropIslandsByPlateau])) end
    local iRecentDropCount
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropIslandsByPlateau]) == false then
        local bTooMuchThreatOrEngisTraveling
        local iMexesAlreadyBuiltOn = 0
        local iZonesWithSignificantThreat = 0
        local iZonesWithMexesAndNoEnemyThreatOrFriendlyEngis
        local iSignificantReclaimValue

        for iPlateau, tIslands in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropIslandsByPlateau] do
            iZonesWithMexesAndNoEnemyThreatOrFriendlyEngis = 0
            for iEntry, iIsland in tIslands do
                --Have we not had a recent failed drop?
                bDontHaveLocationInPlayableArea = not(bDontCheckPlayableArea)
                if bDebugMessages == true then LOG(sFunctionRef..': Considering the iIsland='..iIsland..' in iPlateau '..iPlateau..'; Time of last failed drop='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandDropTime][iIsland] or 'nil')) end
                if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandDropTime][iIsland] or -600) >= 300 then --at least 5m since we last attempted a drop
                    iRecentDropCount = 0
                    --Cycle through every land zone on island and check if enemy has large threat (>600) indicating an ACU is present or isgnificant army, or we have engineers traveling here or already on the island (and unattached)
                    bTooMuchThreatOrEngisTraveling = false
                    iSignificantReclaimValue = 0
                    for iLZEntry, iLandZone in AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandLandZones][iIsland] do
                        local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                        iSignificantReclaimValue = iSignificantReclaimValue + (tLZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0)
                        local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                        if AiBotUtilities.IsTableEmpty(tLZData[AiBotMap.subreftoUnitsToCapture]) == false then iSignificantReclaimValue = iSignificantReclaimValue + AiBotUnitInfo.GetMassCostOfUnits(tLZData[AiBotMap.subreftoUnitsToCapture]) * 0.7 end
                        if bDontHaveLocationInPlayableArea then bDontHaveLocationInPlayableArea = not(AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint])) end
                        iMexesAlreadyBuiltOn = 0
                        iRecentDropCount = iRecentDropCount + (tLZTeamData[AiBotMap.refiTransportRecentUnloadCount] or 0)
                        iMexesAlreadyBuiltOn = iMexesAlreadyBuiltOn + tLZTeamData[AiBotMap.subrefMexCountByTech][1] + tLZTeamData[AiBotMap.subrefMexCountByTech][2] + tLZTeamData[AiBotMap.subrefMexCountByTech][3]
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iLandZone='..iLandZone..' in the island, enemy threat='..tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; Is table of enemy engineers traveling here empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEngineersTravelingHere]))..'; iMexesAlreadyBuiltOn='..iMexesAlreadyBuiltOn) end
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEngineersTravelingHere]) == false or (tLZTeamData[AiBotMap.refiNonAiBotTeammateFactoryCount] or 0) > 0 then
                            if bDebugMessages == true then LOG(sFunctionRef..': we already have engineers traveling here or a teammate factory so will abort') end
                            bTooMuchThreatOrEngisTraveling = true
                            break
                        elseif tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 175 then
                            if tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] >= 250 or ((tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) + (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileIndirectTotal] or 0) >= 100) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Significant threat in the zone') end
                                iZonesWithSignificantThreat = iZonesWithSignificantThreat + 1
                            end
                        elseif AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                            --(we already checked for factories earlier so this is partially a redundancy, as well as expanding to include engineers
                            local tEngineersAndFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryFactory, tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                            if AiBotUtilities.IsTableEmpty(tEngineersAndFactories) == false then
                                for iUnit, oUnit in tEngineersAndFactories do
                                    if not(oUnit:IsUnitState('Attached')) and oUnit:GetFractionComplete() >= 1 then
                                        if bDebugMessages == true then LOG(sFunctionRef..': we already have engineers or factories here') end
                                        bTooMuchThreatOrEngisTraveling = true
                                        break
                                    end
                                end
                            end
                            if (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) == 0 and ((tLZData[AiBotMap.subrefLZOrWZMexCount] or 0) > 0 or iSignificantReclaimValue >= iReclaimWantedForTransportDrop) then iZonesWithMexesAndNoEnemyThreatOrFriendlyEngis = iZonesWithMexesAndNoEnemyThreatOrFriendlyEngis + 1 end
                        else
                            if (tLZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) == 0 and ((tLZData[AiBotMap.subrefLZOrWZMexCount] or 0) > 0 or iSignificantReclaimValue >= iReclaimWantedForTransportDrop) then iZonesWithMexesAndNoEnemyThreatOrFriendlyEngis = iZonesWithMexesAndNoEnemyThreatOrFriendlyEngis + 1 end
                        end
                        if bTooMuchThreatOrEngisTraveling then break end
                    end
                    if iZonesWithSignificantThreat > 0 then
                        if iZonesWithMexesAndNoEnemyThreatOrFriendlyEngis == 0 then
                            bTooMuchThreatOrEngisTraveling = true
                            if bDebugMessages == true then LOG(sFunctionRef..': All zones have significant enemy threat') end
                        elseif iZonesWithMexesAndNoEnemyThreatOrFriendlyEngis < iZonesWithSignificantThreat * 6 then
                            --If there are lots of zones without significant enemy threat then still consider
                            bTooMuchThreatOrEngisTraveling = true
                            if bDebugMessages == true then LOG(sFunctionRef..': Enoguh zones have threat relative to zones without threat that we dont want to drop, iZonesWithMexesAndNoEnemyThreatOrFriendlyEngis='..iZonesWithMexesAndNoEnemyThreatOrFriendlyEngis..'; iZonesWithSignificantThreat='..iZonesWithSignificantThreat) end
                        end
                    end

                    if not(bTooMuchThreatOrEngisTraveling) and iMexesAlreadyBuiltOn >= (AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][iIsland] or 0) then
                        if iMexesAlreadyBuiltOn > 0 then
                            bTooMuchThreatOrEngisTraveling = true
                        elseif  iSignificantReclaimValue < iReclaimWantedForTransportDrop then
                            bTooMuchThreatOrEngisTraveling = true
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': bTooMuchThreatOrEngisTraveling='..tostring(bTooMuchThreatOrEngisTraveling)) end
                    if not(bTooMuchThreatOrEngisTraveling) and iRecentDropCount < 3 then --note this probably is effectively 1 less than the value noted, since if the transport is given the order to unload then that location is removed from the shortlist it will potentially cancel its unload order
                        if not(bDontHaveLocationInPlayableArea) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Adding iIsland='..iIsland..' in plateau '..iPlateau..' to the transport shortlist') end
                            table.insert(tShortlist, {iPlateau, iIsland})
                        end
                    end
                end
            end
        end
    end

    --Now consider adding land zonesi n same island:
    local bFirstTimeConsidering = false
    if not( AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialDropZonesByPlateau]) and not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialPondDropZones]) then bFirstTimeConsidering = true end
    UpdateTransportShortlistForFarAwayLandZoneDrops(iTeam) --want to run every time, has code in it to make sure one part only runs at start of game
    if bFirstTimeConsidering then
        --Also drop locations for ponds
        UpdateTransportShortlistForPondDrops(iTeam, tbPlateausWithPlayerStartOrIslandDrop)
        RecordPotentialCombatDropShortlist(iTeam)
    end
    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportCombatPlateauLandZoneDropShortlist] = {}
    if bUpdateCombatDropShortlist then UpdateActiveShortlistForCombatDrops(iTeam) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function UpdateActiveShortlistForCombatDrops(iTeam)
    --assumes reftTransportCombatPlateauLandZoneDropShortlist already set to {} prior to calling this, updates this for any potential combat drop zones
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'UpdateActiveShortlistForCombatDrops'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastTransportCombatShortlistUpdate] = GetGameTimeSeconds()
    local iGroundAAThreshold = 160
    if bDebugMessages == true then LOG(sFunctionRef..': Considering active combat drop locations, is table of potential combat drop zones empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialCombatDropZonesByPlateau]))) end
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialCombatDropZonesByPlateau]) == false then
        --Get start plateau and zone based on friendly base nearest rally point
        local iMobileDFThreshold = 60
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] >= 2 then
            iMobileDFThreshold = 200
            iGroundAAThreshold = 400
        end
        local iMexMassInvestment
        local bHaveSafeTarget = false
        local iDangerousGroundAAThreshold = iGroundAAThreshold * 10
        local iDangerousMobileDFThreshold = iMobileDFThreshold * 10
        local iLowestGeneralDangerousZoneThreat = 100000
        local iDangerousPlateau, iCurDangerousZoneThreat
        local iDangerousZone
        local iBestEnemyZoneSafeMexValue = 0
        local tbPlayerBaseOnPlateau = {}
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains] do
            local iCurPlateau = NavUtils.GetLabel(AiBotMap.refPathingTypeHover, AiBotMap.GetPlayerStartPosition(oBrain))
            tbPlayerBaseOnPlateau[iCurPlateau] = true
        end
        for iPlateau, tiLandZones in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialCombatDropZonesByPlateau] do
            for iEntry, iLandZone in tiLandZones do
                local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
                local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                --Check for zones where enemy has mexes, we have no friendly units, enemy lacks significant groundAA or mobile DF threat or T2+ PD, then consider adding to shortlist
                if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to drop in P'..iPlateau..'Z'..iLandZone..'; Is table of allied units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]))..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]))..'; Enemy groundAA='..(tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)..'; Enemy mobile DF total='..(tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0)..'; Best enemy structure DF range='..(tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0)..'; Enemy AirAA threat='..(tLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)) end
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) and AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.subrefTEnemyUnits]) == false and (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0) < 29 then
                    --Does enemy have most of the mexes here?
                    local toEnemyMexCount = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy mexes empty='..tostring( AiBotUtilities.IsTableEmpty(toEnemyMexCount))) end
                    if AiBotUtilities.IsTableEmpty(toEnemyMexCount) == false then
                        iMexMassInvestment = 0
                        for iUnit, oUnit in toEnemyMexCount do
                            if not(oUnit.Dead) then
                                iMexMassInvestment = iMexMassInvestment + (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) * oUnit:GetFractionComplete()
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iMexMassInvestment='..iMexMassInvestment..'; LZ mex count='..(tLZData[AiBotMap.subrefLZOrWZMexCount] or 'nil')..'; Count of enemy mex ignoring % complete='..table.getn(toEnemyMexCount)) end
                        if iMexMassInvestment >= 550 or (iMexMassInvestment >= 50 and not(tbPlayerBaseOnPlateau[iPlateau])) then
                            --Check whether its safe to travel here for each individual transport
                            --Ignore if 1 mex unless enemy has significant building mass value invested here and not dangerous
                            if iMexMassInvestment < 800 and iMexMassInvestment < iBestEnemyZoneSafeMexValue and (AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tLZData[AiBotMap.subrefLZIslandRef]] or 0) <= 1 and (tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) <= 1000 then
                                --Ignore if already have a better target
                                if bDebugMessages == true then LOG(sFunctionRef..': Not enoguh mex value to be worth adding to the shortlist') end
                            elseif (tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) <= iGroundAAThreshold and (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) <= iMobileDFThreshold and (tLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) <= 40 then
                                if bDebugMessages == true then LOG(sFunctionRef..': Adding to combat drop shortlist') end
                                table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportCombatPlateauLandZoneDropShortlist], {iPlateau, iLandZone})
                                bHaveSafeTarget = true
                                iBestEnemyZoneSafeMexValue = math.max(iMexMassInvestment, iBestEnemyZoneSafeMexValue)
                            elseif not(bHaveSafeTarget) and (tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) <= iDangerousGroundAAThreshold and (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) <= iDangerousMobileDFThreshold and (tLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) <= 200 then
                                iCurDangerousZoneThreat = (tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) * 2 + (tLZTeamData[AiBotMap.subrefLZThreatEnemyMobileDFTotal] or 0) + (tLZTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)
                                --Increase threat by 50% if this is a low value location (e.g. 1 mex) so we are less likely to pick it
                                if iMexMassInvestment <= 800 and (AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauIslandMexCount][tLZData[AiBotMap.subrefLZIslandRef]] or 0) <= 1 and (tLZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) <= 1000 then iCurDangerousZoneThreat = iCurDangerousZoneThreat * 1.5 end
                                if iCurDangerousZoneThreat < iLowestGeneralDangerousZoneThreat then
                                    iLowestGeneralDangerousZoneThreat = iCurDangerousZoneThreat
                                    iDangerousPlateau = iPlateau
                                    iDangerousZone = iLandZone
                                end
                            end
                        end
                    end
                end
            end
        end
        if not(bHaveSafeTarget) and iDangerousPlateau and iDangerousZone then
            if bDebugMessages == true then LOG(sFunctionRef..': Will record dangerous zone to drop to instead, iDangerousPlateau='..iDangerousPlateau..'; iDangerousZone='..iDangerousZone..'; iLowestGeneralDangerousZoneThreat='..iLowestGeneralDangerousZoneThreat) end
            table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportCombatPlateauLandZoneDropShortlist], {iDangerousPlateau, iDangerousZone})
        end
    end
    --Consider dropping enemy bases if theyre just ecoing and we arent far behind on air
    AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyBaseInCombatDropShortlist] = false

    if bDebugMessages == true then LOG(sFunctionRef..': If enemy isnt at T3 land yet will consider dropping their base, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech]..'; Is our team far behind on air='..tostring(AiBotConditions.TeamIsFarBehindOnAir(iTeam))..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount]) end
    local bConsiderDroppingBase = false
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyGroundTech] < 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] < 3 and not(AiBotConditions.TeamIsFarBehindOnAir(iTeam)) then
        bConsiderDroppingBase = true
    elseif AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime]) then
        bConsiderDroppingBase = true
    elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.refiConstructedExperimentalCount] == 0 then
        local iLastFailedDrop = 0
        for iTargetIsland, tZoneAndTime in AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime] do
            for iZone, iTime in tZoneAndTime do
                if iTime > iLastFailedDrop then iLastFailedDrop = iTime end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': iLastFailedDrop='..iLastFailedDrop..'; Cur time='..GetGameTimeSeconds()..'; Time since last failed drop='..GetGameTimeSeconds() - iLastFailedDrop) end
        if GetGameTimeSeconds() - iLastFailedDrop >= 300 then
            if bDebugMessages == true then LOG(sFunctionRef..': Havent had a failed drop for at least 5m, will consider deropping enemy base despite them having t3 tech') end
            bConsiderDroppingBase = true
        end
    end

    if bConsiderDroppingBase then
        if bDebugMessages == true then LOG(sFunctionRef..': Will consider enemy start zones to see if there are any vulnerable to a t1 arti drop (i.e. no PD and minimal groundAA, and no major threat), iGroundAAThreshold='..iGroundAAThreshold) end
        local iCurPlateau, iCurLZ
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains] do
            local tEnemyStart = AiBotMap.GetPlayerStartPosition(oBrain)
            iCurPlateau, iCurLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tEnemyStart)
            if iCurPlateau and iCurLZ and iCurPlateau > 0 then
                local tLZData = AiBotMap.tAllPlateaus[iCurPlateau][AiBotMap.subrefPlateauLandZones][iCurLZ]
                local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                if bDebugMessages == true then LOG(sFunctionRef..': Considering the start for enemy '..oBrain.Nickname..' at P'..iCurPlateau..'Z'..iCurLZ..'; Transport unload count='..(tLZTeamData[AiBotMap.refiTransportRecentUnloadCount] or 'nil')..'; tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]='..(tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')..'; Best structure range='..tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange]..'; Best mobile DF range='..tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange]..'; Mex count='..tLZData[AiBotMap.subrefLZOrWZMexCount]..'; Time since last had visual='..(GetGameTimeSeconds() - (tLZTeamData[AiBotMap.refiTimeLastHadVisual] or 0))..'; Air to ground threat='..(tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 'nil')) end
                if (tLZTeamData[AiBotMap.refiTransportRecentUnloadCount] or 0) <= 1 and tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] < iGroundAAThreshold and (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestStructureDFRange] or 0) == 0 and (tLZTeamData[AiBotMap.subrefLZThreatEnemyBestMobileDFRange] or 0) <= 10 and tLZData[AiBotMap.subrefLZOrWZMexCount] >= 3 and GetGameTimeSeconds() - (tLZTeamData[AiBotMap.refiTimeLastHadVisual] or 0) <= 300 and (tLZTeamData[AiBotMap.refiEnemyAirToGroundThreat] or 0) == 0 then
                    local iEnemyLandFactories = 0
                    local tEnemyLandFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryLandFactory, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                    if AiBotUtilities.IsTableEmpty(tEnemyLandFactories) == false then
                        for iFactory, oFactory in tEnemyLandFactories do
                            if AiBotUnitInfo.IsUnitValid(oFactory) and oFactory:GetFractionComplete() == 1 then
                                iEnemyLandFactories = iEnemyLandFactories + 1
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Including enemy base P'..iCurPlateau..'Z'..iCurLZ..' which is the core base for '..oBrain.Nickname..' in the combat drop shortlist unless it has 2+ land factories, iEnemyLandFactories='..iEnemyLandFactories) end
                    if iEnemyLandFactories <= 1 then
                        --has enemy got any t2+ mexes or has started upgrading?
                        local tEnemyMexesAndFabs = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryMassFab + AiBotUnitInfo.refCategoryPower - categories.TECH1, tLZTeamData[AiBotMap.subrefTEnemyUnits])
                        if AiBotUtilities.IsTableEmpty(tEnemyMexesAndFabs) == false then
                            for iUnit, oUnit in tEnemyMexesAndFabs do
                                if not(oUnit.Dead) and oUnit:GetFractionComplete() >= 0.5 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy has T2 or better eco at the base') end
                                    table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportCombatPlateauLandZoneDropShortlist], {iCurPlateau, iCurLZ})
                                    AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyBaseInCombatDropShortlist] = true
                                    break
                                end
                            end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy doesnt have T2 eco at the base yet') end
                        end
                    end
                end
            end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetIslandPlateauAndLandZoneForTransportToTravelTo(iTeam, oUnit)
    --Returns island, plateau and land zone that we want to drop at (or nil if there are none)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetIslandPlateauAndLandZoneForTransportToTravelTo'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iTargetIsland, iTargetPlateau, iTargetLandZone
    if not(oUnit[refbCombatDrop]) or AiBotUtilities.IsTableEmpty(oUnit:GetCargo()) then
        local tShortlist = AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportIslandDropShortlist]
        if bDebugMessages == true then LOG(sFunctionRef..': Is the island shortlist empty='..tostring(AiBotUtilities.IsTableEmpty(tShortlist))..'; repru of tShortlist='..repru(tShortlist)) end
        if AiBotUtilities.IsTableEmpty(tShortlist) == false then
            local iCurDist
            local iClosestLZ
            local iClosestNoMexLZ
            local iClosestDist = 100000
            local iClosestNoMexDist = 100000
            local iClosestIslandDist = 100000
            local iCurIslandDist
            local iAirSubteam = oUnit:GetAIBrain().AiBotAirSubteam

            --Unit cur plateau and land/water zone
            local iCurPlateauOrZero, iCurLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
            if bDebugMessages == true then LOG(sFunctionRef..': Closest plateau and land or water zone to unit position: Unit position='..repru(oUnit:GetPosition())..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurLandOrWaterZone='..(iCurLandOrWaterZone or 'nil')) end
            local iAdjustedMexesInClosestZone = 0
            local iCurAdjustedIslandMexValue
            local iDistToOurStart, iDistToCurBrainStart, iClosestBrainDist
            for iEntry, tiPlateauAndIsland in tShortlist do
                --Get the closest land zone to oUnit for this particular plateau and island; then using that land zone, work out the island distance, and reecord if that island is closest to our transport (with mexless islands being treated as further away)
                iClosestDist = 100000
                iClosestNoMexDist= 100000

                iClosestLZ = nil
                iClosestNoMexLZ = nil
                iCurAdjustedIslandMexValue = 0
                if bDebugMessages == true then LOG(sFunctionRef..': About to consider all zones in plateau '..(tiPlateauAndIsland[1] or 'nil')..' to get the closest land zone adjusted for mexes, repru='..repru(AiBotMap.tAllPlateaus[tiPlateauAndIsland[1]][AiBotMap.subrefPlateauIslandLandZones][tiPlateauAndIsland[2]])) end
                for iLZEntry, iLandZone in AiBotMap.tAllPlateaus[tiPlateauAndIsland[1]][AiBotMap.subrefPlateauIslandLandZones][tiPlateauAndIsland[2]] do
                    local tLZData = AiBotMap.tAllPlateaus[tiPlateauAndIsland[1]][AiBotMap.subrefPlateauLandZones][iLandZone]
                    iCurAdjustedIslandMexValue = iCurAdjustedIslandMexValue + (tLZData[AiBotMap.subrefLZOrWZMexCount] or 0)
                    --Only consider LZs with mexes so we land close to where we likely want to be
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                    if tLZData[AiBotMap.subrefLZOrWZMexCount] > 0 then
                        if iCurDist < iClosestDist then
                            iClosestDist = iCurDist
                            iClosestLZ = iLandZone
                        end
                    elseif not(iClosestLZ)  then
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                        if tLZData[AiBotMap.subrefLZTotalSegmentCount] <= 20 then
                            if tLZData[AiBotMap.subrefLZTotalSegmentCount] <= 5 then iCurDist = iCurDist + 1000
                            else iCurDist = iCurDist + 500
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Few segments in LZ '..iLandZone..' so increasing the distance so are less likely to pick it, tLZData[AiBotMap.subrefLZTotalSegmentCount]='..tLZData[AiBotMap.subrefLZTotalSegmentCount]) end
                        end
                        if iCurDist < iClosestNoMexDist then
                            iClosestNoMexDist = iCurDist
                            iClosestNoMexLZ = iLandZone
                        end
                    end
                end
                if not(iClosestLZ) then
                    iClosestLZ = iClosestNoMexLZ
                    iClosestDist = iClosestNoMexDist + 500
                end
                --Is it safe to travel here?
                if bDebugMessages == true then
                    LOG(sFunctionRef..': Considering iEntry='..iEntry..'; tiPlateauAndIsland='..repru(tiPlateauAndIsland)..'; iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurLandOrWaterZone='..(iCurLandOrWaterZone or 'nil')..'; iClosestLZ='..(iClosestLZ or 'nil')..'; tiPlateauAndIsland[1]='..(tiPlateauAndIsland[1] or 'nil')..'; iCurAdjustedIslandMexValue='..iCurAdjustedIslandMexValue)
                    LOG(sFunctionRef..': Does enemy have aa threat along path='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iCurPlateauOrZero, iCurLandOrWaterZone, tiPlateauAndIsland[1], iClosestLZ, false, 60))..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime][tiPlateauAndIsland[2]][iClosestLZ]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime][tiPlateauAndIsland[2]][iClosestLZ] or 'nil')..'; Does enemy have AA using detailed check='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iCurPlateauOrZero, iCurLandOrWaterZone, tiPlateauAndIsland[1], iClosestLZ, false, 60,          nil,                     false,         iAirSubteam,         true)))
                end
                --Has a transport recently died trying to get here?
                if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime][tiPlateauAndIsland[2]][iClosestLZ] or -300) > 180 then
                    --DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck)
                    if not(DoesEnemyHaveAAThreatAlongPath(iTeam, iCurPlateauOrZero, iCurLandOrWaterZone, tiPlateauAndIsland[1], iClosestLZ, false, 60,          nil,                     false,         iAirSubteam,         true, nil, oUnit:GetPosition())) then
                        iCurIslandDist = iClosestDist
                        if bDebugMessages == true then LOG(sFunctionRef..': iCurIslandDist='..iCurIslandDist..'; iClosestIslandDist='..iClosestIslandDist..'; iCurAdjustedIslandMexValue='..iCurAdjustedIslandMexValue) end
                        --Adjust mexes for mod distance
                        if iCurAdjustedIslandMexValue >= iAdjustedMexesInClosestZone then
                            local tLZData = AiBotMap.tAllPlateaus[tiPlateauAndIsland[1]][AiBotMap.subrefPlateauLandZones][iClosestLZ]
                            local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
                            if tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.65 then
                                iCurAdjustedIslandMexValue = iCurAdjustedIslandMexValue * 0.2
                            elseif tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.5 then iCurAdjustedIslandMexValue = iCurAdjustedIslandMexValue * 0.35
                            elseif tLZTeamData[AiBotMap.refiModDistancePercent] >= 0.4 then iCurAdjustedIslandMexValue = iCurAdjustedIslandMexValue * 0.9
                            elseif tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.2 or iClosestDist <= math.min(150, AiBotMap.iMapSize * 0.25) then iCurAdjustedIslandMexValue = iCurAdjustedIslandMexValue * 0.7
                            else
                                --Do nothing - will multiply by 1
                            end
                            --Make sure if we are on a team we dont have the furthest AiBot from the island choosing to go there
                            if iCurAdjustedIslandMexValue >= iAdjustedMexesInClosestZone and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] > 1 then
                                --Check if there is a friendly base closer to it than the base of the brain owning the transport
                                local oTransportBrain = oUnit:GetAIBrain()
                                iDistToOurStart = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], AiBotMap.GetPlayerStartPosition(oTransportBrain))
                                iClosestBrainDist = 10000
                                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                                    if not(oBrain == oTransportBrain) then
                                        if bDebugMessages == true then LOG(sFunctionRef..'; Dist from brain '..oBrain.Nickname..' to target LZData midpoint='..AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], AiBotMap.GetPlayerStartPosition(oBrain))..'; iDistToOurStart='..iDistToOurStart) end
                                        iDistToCurBrainStart = AiBotUtilities.GetDistanceBetweenPositions(tLZData[AiBotMap.subrefMidpoint], AiBotMap.GetPlayerStartPosition(oBrain))
                                        iClosestBrainDist = math.min(iClosestBrainDist, iDistToCurBrainStart)
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': iDistToOurStart='..iDistToOurStart..'; iClosestBrainDist='..iClosestBrainDist..'; iCurAdjustedIslandMexValue before adjustment for distance='..iCurAdjustedIslandMexValue) end
                                if iDistToOurStart > iClosestBrainDist then
                                    if iDistToOurStart > iClosestBrainDist + 150 then
                                        iCurAdjustedIslandMexValue = iCurAdjustedIslandMexValue * 0.1
                                    elseif iDistToOurStart > iClosestBrainDist + 60 then
                                        iCurAdjustedIslandMexValue = iCurAdjustedIslandMexValue * 0.3
                                    else
                                        iCurAdjustedIslandMexValue = iCurAdjustedIslandMexValue * 0.7
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': iCurAdjustedIslandMexValue after adjustments for mod dist and closer teammates='..iCurAdjustedIslandMexValue..'; Mod dist='..tLZTeamData[AiBotMap.refiModDistancePercent]) end
                        end
                        if iCurAdjustedIslandMexValue >= iAdjustedMexesInClosestZone and (iCurAdjustedIslandMexValue > iAdjustedMexesInClosestZone or iCurIslandDist < iClosestIslandDist) then
                            if bDebugMessages == true then LOG(sFunctionRef..'; Updating preferred rop location based on mexes and distance, iClosestIslandDist='..iClosestIslandDist) end
                            iAdjustedMexesInClosestZone = iCurAdjustedIslandMexValue
                            iClosestIslandDist = iCurIslandDist
                            iTargetIsland = tiPlateauAndIsland[2]
                            iTargetPlateau = tiPlateauAndIsland[1]
                            iTargetLandZone = iClosestLZ
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': end of code, iTargetIsland='..(iTargetIsland or 'nil')..'; iTargetPlateau='..(iTargetPlateau or 'nil')..'; iTargetLandZone='..(iTargetLandZone or 'nil')) end
    return iTargetIsland, iTargetPlateau, iTargetLandZone
end

function GetPlateauAndZoneForEngineerSupport(iTeam, oUnit)
    --Returns island, plateau and land zone that we want to drop at (or nil if there are none)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetPlateauAndZoneForEngineerSupport'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local iTargetIsland, iTargetPlateau, iTargetLandZone
    if not(oUnit[refbCombatDrop]) or AiBotUtilities.IsTableEmpty(oUnit:GetCargo()) then
        local tShortlist = AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiHighTechEngiDropPlateauAndZones]
        if bDebugMessages == true then LOG(sFunctionRef..': Is the engineer support shortlist empty='..tostring(AiBotUtilities.IsTableEmpty(tShortlist))..'; repru of tShortlist='..repru(tShortlist)) end
        if AiBotUtilities.IsTableEmpty(tShortlist) == false then
            local iCurDist
            local iClosestDist = 100000
            local iAirSubteam = oUnit:GetAIBrain().AiBotAirSubteam
            local iTimeSinceLastTransportDeath
            local iCurUnitPlateau, iCurUnitZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
            local bRemoveCurEntry
            for iEntry = table.getn(tShortlist), 1, -1 do
                local tiPlateauZoneAndTech = tShortlist[iEntry]
                bRemoveCurEntry = false
                local tCurLZOrWZData, tCurLZOrWZTeamData
                if tiPlateauZoneAndTech[1] > 0 then
                    tCurLZOrWZData = AiBotMap.tAllPlateaus[tiPlateauZoneAndTech[1]][AiBotMap.subrefPlateauLandZones][tiPlateauZoneAndTech[2]]
                    tCurLZOrWZTeamData = tCurLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                else
                    tCurLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[tiPlateauZoneAndTech[2]]][AiBotMap.subrefPondWaterZones][tiPlateauZoneAndTech[2]]
                    tCurLZOrWZTeamData = tCurLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                end
                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tCurLZOrWZData[AiBotMap.subrefMidpoint], oUnit:GetPosition())
                if iCurDist < iClosestDist then
                    --Do we have any t3 engis or factories in this zone already? If so then clear the flag
                    if AiBotUtilities.IsTableEmpty(tCurLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                        local tEngineersAndFactories = EntityCategoryFilterDown((AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryFactory) * categories.TECH3, tCurLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                        if AiBotUtilities.IsTableEmpty(tEngineersAndFactories) == false then
                            bRemoveCurEntry = true
                        end
                    end
                    --Check adjacent zones
                    if not(bRemoveCurEntry) and AiBotUtilities.IsTableEmpty(tCurLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                        for _, iAdjLZ in tCurLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                            local tAdjLZTeamData = AiBotMap.tAllPlateaus[tiPlateauZoneAndTech[1]][AiBotMap.subrefPlateauLandZones][iAdjLZ][AiBotMap.subrefLZTeamData][iTeam]
                            if AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) == false then
                                local tEngineersAndFactories = EntityCategoryFilterDown((AiBotUnitInfo.refCategoryEngineer + AiBotUnitInfo.refCategoryFactory) * categories.TECH3, tAdjLZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                if AiBotUtilities.IsTableEmpty(tEngineersAndFactories) == false then
                                    bRemoveCurEntry = true
                                    break
                                end
                            end
                        end
                    end
                    --Is it safe to travel here?
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering iEntry='..iEntry..'; iCurDist='..iCurDist..'; P='..tiPlateauZoneAndTech[1]..'Z='..tiPlateauZoneAndTech[2]..'; tCurLZOrWZData[AiBotMap.subrefLZIslandRef]='..(tCurLZOrWZData[AiBotMap.subrefLZIslandRef] or 'nil')..'; bRemoveCurEntry='..tostring(bRemoveCurEntry)) end

                    --Has a transport recently died trying to get here? then ignore
                    if bRemoveCurEntry then
                        table.remove(tShortlist, iEntry)
                    elseif tCurLZOrWZData[AiBotMap.subrefLZIslandRef] then
                        iTimeSinceLastTransportDeath = GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime][tCurLZOrWZData[AiBotMap.subrefLZIslandRef][2]][tiPlateauZoneAndTech[2]] or -1000)
                        if bDebugMessages == true then LOG(sFunctionRef..': iTimeSinceLastTransportDeath='..iTimeSinceLastTransportDeath) end
                        if iTimeSinceLastTransportDeath > 180 and (iTimeSinceLastTransportDeath >= 300 or not(DoesEnemyHaveAAThreatAlongPath(iTeam, tiPlateauZoneAndTech[1], tiPlateauZoneAndTech[2], iCurUnitPlateau, iCurUnitZone, false, 100,          nil,                     false,         iAirSubteam,         true, nil, oUnit:GetPosition()))) then
                            iClosestDist = iCurDist
                            iTargetIsland = tCurLZOrWZData[AiBotMap.subrefLZIslandRef]
                            iTargetPlateau = tiPlateauZoneAndTech[1]
                            iTargetLandZone = tiPlateauZoneAndTech[2]
                            if bDebugMessages == true then LOG(sFunctionRef..': Recording as closest P and Z that wants support, P'..tiPlateauZoneAndTech[1]..'Z'..tiPlateauZoneAndTech[2]) end
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': end of code, iTargetIsland='..(iTargetIsland or 'nil')..'; iTargetPlateau='..(iTargetPlateau or 'nil')..'; iTargetLandZone='..(iTargetLandZone or 'nil')) end
    return iTargetIsland, iTargetPlateau, iTargetLandZone
end

function GetFarAwayLandZoneOnCurrentIslandForTransportToTravelTo(iTeam, oUnit)
    --Returns island, plateau and land zone that we want to drop at (or nil if there are none)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetFarAwayLandZoneOnCurrentIslandForTransportToTravelTo'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iTargetIsland, iTargetPlateau, iTargetLandZone
    if not(oUnit[refbCombatDrop]) or AiBotUtilities.IsTableEmpty(oUnit:GetCargo()) then
        local tShortlist = AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportFarAwaySameIslandPlateauLandZoneDropShortlist] --(UpdateTransportShortlistForFarAwayLandZoneDrops determins the shortlist)
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code for shortlist, time='..GetGameTimeSeconds()..', is shortlist empty='..tostring(AiBotUtilities.IsTableEmpty(tShortlist))) end
        if AiBotUtilities.IsTableEmpty(tShortlist) == false then
            local iCurModDist
            local iClosestModDist = 100000
            local tiClosestPlateauAndZone
            local iAirSubteam = oUnit:GetAIBrain().AiBotAirSubteam

            --Unit cur plateau and land/water zone
            local iCurPlateauOrZero, iCurLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
            if bDebugMessages == true then LOG(sFunctionRef..': Closest plateau and land or water zone to unit position: Unit position='..repru(oUnit:GetPosition())..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurLandOrWaterZone='..(iCurLandOrWaterZone or 'nil')) end

            local bDontCheckPlayableArea = not(AiBotMap.bIsCampaignMap)
            local bDontHaveLocationInPlayableArea

            for iEntry, tiPlateauAndZone in tShortlist do
                bDontHaveLocationInPlayableArea = not(bDontCheckPlayableArea)
                local tLZData = AiBotMap.tAllPlateaus[tiPlateauAndZone[1]][AiBotMap.subrefPlateauLandZones][tiPlateauAndZone[2]]
                if bDontHaveLocationInPlayableArea then bDontHaveLocationInPlayableArea = not(AiBotConditions.IsLocationInPlayableArea(tLZData[AiBotMap.subrefMidpoint])) end
                if not(bDontHaveLocationInPlayableArea) then
                    iCurModDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])
                    if iCurModDist < 100 then iCurModDist = 100 - (100 - iCurModDist) * 0.1 end
                    iCurModDist = iCurModDist / math.max(0.5, tLZData[AiBotMap.subrefLZOrWZMexCount])
                    --If we have already picked a location be more likely to stick with it
                    if tiPlateauAndZone[2] == oUnit[refiTargetZoneForDrop] and tiPlateauAndZone[1] == oUnit[refiTargetPlateauForDrop] then iCurModDist = iCurModDist - math.max(25, iCurModDist * 0.1) end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering P'..tiPlateauAndZone[1]..'Z'..tiPlateauAndZone[2]..' with mod distance of '..iCurModDist..'; Actual dist='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZData[AiBotMap.subrefMidpoint])..'; Mex count='..tLZData[AiBotMap.subrefLZOrWZMexCount]..'; iClosestModDist so far='..iClosestModDist) end
                    if iCurModDist < iClosestModDist then
                        --Is it safe to travel here?
                        if bDebugMessages == true then LOG(sFunctionRef..': Time since last failed drop='..GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime][tLZData[AiBotMap.subrefLZIslandRef]][tiPlateauAndZone[2]] or -300)) end
                        if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedIslandAndZoneDropTime][tLZData[AiBotMap.subrefLZIslandRef]][tiPlateauAndZone[2]] or -300) > 180 then

                            if bDebugMessages == true then LOG(sFunctionRef..': Considering iEntry='..iEntry..'; tiPlateauAndZone='..repru(tiPlateauAndZone)..'; iCurPlateauOrZero='..iCurPlateauOrZero..'; iCurLandOrWaterZone='..iCurLandOrWaterZone..'; Does enemy have aa threat along path='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iCurPlateauOrZero, iCurLandOrWaterZone, tiPlateauAndZone[1], tiPlateauAndZone[2], false, 60,          nil,                     false,         iAirSubteam,         true, nil, oUnit:GetPosition()))) end
                            if not(DoesEnemyHaveAAThreatAlongPath(iTeam, iCurPlateauOrZero, iCurLandOrWaterZone, tiPlateauAndZone[1], tiPlateauAndZone[2], false, 60,          nil,                     false,         iAirSubteam,         true, nil, oUnit:GetPosition())) then
                                iClosestModDist = iCurModDist
                                tiClosestPlateauAndZone = {tiPlateauAndZone[1], tiPlateauAndZone[2]}
                            end
                        end
                    end
                end
            end
            if tiClosestPlateauAndZone then
                iTargetPlateau = tiClosestPlateauAndZone[1]
                iTargetLandZone = tiClosestPlateauAndZone[2]
                local tLZData = AiBotMap.tAllPlateaus[iTargetPlateau][AiBotMap.subrefPlateauLandZones][iTargetLandZone]
                iTargetIsland = tLZData[AiBotMap.subrefLZIslandRef]
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, iTargetIsland='..(iTargetIsland or 'nil')..'; iTargetPlateau='..(iTargetPlateau or 'nil')..'; iTargetLandZone='..(iTargetLandZone or 'nil')) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iTargetIsland, iTargetPlateau, iTargetLandZone
end

function GetCombatDropPlateauAndLandZoneEntryRefForTransport(iTeam, oUnit)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetCombatDropPlateauAndLandZoneEntryRefForTransport'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportCombatPlateauLandZoneDropShortlist]) == false then
        local iGroundAAThreshold = math.max(50, oUnit:GetHealth() * 0.4) --Prev was 150 * AiBotUnitInfo.GetUnitTechLevel(oUnit), *75% if likely targeting base; so this works out as similar for t1 transport (slightly more if it is on full health), but more for T2+ transport
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyBaseInCombatDropShortlist] then iGroundAAThreshold = iGroundAAThreshold * 1.4 end --So we are more likely to drop core bases even if it means passing over some mAA first (as we wont havei ncluded the enemy base in the droplist if it had relatively modest AA)
        local iAirSubteam = oUnit:GetAIBrain().AiBotAirSubteam
        local iClosestDist = 10000
        local iModDist
        local iClosestEntryRef


        local iStartPlateauOrZero, iStartLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
        local tEnemyStartZonesByPlateau
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbEnemyBaseInCombatDropShortlist] then
            tEnemyStartZonesByPlateau = {}
            for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoEnemyBrains] do
                local tEnemyStart = AiBotMap.GetPlayerStartPosition(oBrain)
                local iCurPlateau, iCurLZ = AiBotMap.GetPlateauAndLandZoneReferenceFromPosition(tEnemyStart)
                if iCurPlateau and iCurLZ and iCurPlateau > 0 then
                    if not(tEnemyStartZonesByPlateau[iCurPlateau]) then tEnemyStartZonesByPlateau[iCurPlateau] = {} end
                    tEnemyStartZonesByPlateau[iCurPlateau][iCurLZ] = true
                end
            end
        end
        for iEntry, tiPlateauAndZone in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportCombatPlateauLandZoneDropShortlist] do
            local tCurLZData = AiBotMap.tAllPlateaus[tiPlateauAndZone[1]][AiBotMap.subrefPlateauLandZones][tiPlateauAndZone[2]]
            iModDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tCurLZData[AiBotMap.subrefMidpoint])
            if tCurLZData[AiBotMap.refiTransportRecentUnloadCount] then iModDist = iModDist + 100 * (tCurLZData[AiBotMap.refiTransportRecentUnloadCount] - 1) end
            if tCurLZData[AiBotMap.subrefLZOrWZMexCount] >= 4 then
                iModDist = iModDist - 50
                if tEnemyStartZonesByPlateau and tEnemyStartZonesByPlateau[tiPlateauAndZone[1]][tiPlateauAndZone[2]] and (tCurLZData[AiBotMap.refiTransportRecentUnloadCount] or 0) <= 1 then
                    iModDist = iModDist - 200
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Considering P'..tiPlateauAndZone[1]..'Z'..tiPlateauAndZone[2]..'; Is this an enemy base='..tostring(tEnemyStartZonesByPlateau[tiPlateauAndZone[1]][tiPlateauAndZone[2]] or false)..'; iModDist='..iModDist..'; iClosestDist='..iClosestDist) end
            if iModDist < iClosestDist then
                CalculateAirTravelPath(iStartPlateauOrZero, iStartLandOrWaterZone, tiPlateauAndZone[1], tiPlateauAndZone[2])
                if bDebugMessages == true then
                    local iEnemyAAThreat, toEnemyAAUnits = DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, tiPlateauAndZone[1], tiPlateauAndZone[2], false, iGroundAAThreshold, 0, false, iAirSubteam, true, true, oUnit:GetPosition(), true)
                    LOG(sFunctionRef..': Does enemy ahve AA threat along path='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, tiPlateauAndZone[1], tiPlateauAndZone[2], false, iGroundAAThreshold, 0, false, iAirSubteam, true, false, oUnit:GetPosition(), false))..'; iEnemyAAThreat='..iEnemyAAThreat)
                    if AiBotUtilities.IsTableEmpty(toEnemyAAUnits) == false then
                        for iAA, oAA in toEnemyAAUnits do
                            if AiBotUnitInfo.IsUnitValid(oAA) then
                                LOG(sFunctionRef..': oAA='..oAA.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oAA)..'; AARange='..(oAA[AiBotUnitInfo.refiAARange] or 'nil')..'; owned yb brian'..oAA:GetAIBrain().Nickname..'; Assigned plateau and zone=P'..(oAA[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] or 'nil')..'Z'..(oAA[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2] or 'nil'))
                            end
                        end
                    end
                end
                if not(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, tiPlateauAndZone[1], tiPlateauAndZone[2], false, iGroundAAThreshold, 0, false, iAirSubteam, true, false, oUnit:GetPosition(), false)) then
                    iClosestDist = iModDist
                    iClosestEntryRef = iEntry
                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        return iClosestEntryRef
    end
    --local tLZData = AiBotMap.tAllPlateaus[137][AiBotMap.subrefPlateauLandZones][3]
    --if tLZData then return tLZData[AiBotMap.subrefLZIslandRef], 137, 3 end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetWaterZoneForTransportToTravelTo(iTeam, oUnit)
    --Returns island, plateau and land zone that we want to drop at (or nil if there are none)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetWaterZoneForTransportToTravelTo'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iTargetWaterZone
    if not(oUnit[refbCombatDrop]) or AiBotUtilities.IsTableEmpty(oUnit:GetCargo()) then
        local tShortlist = AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiPotentialPondDropZones]
        if bDebugMessages == true then LOG(sFunctionRef..': Start of code for shortlist, time='..GetGameTimeSeconds()..', is shortlist empty='..tostring(AiBotUtilities.IsTableEmpty(tShortlist))) end
        if AiBotUtilities.IsTableEmpty(tShortlist) == false then
            local iCurDist
            local iClosestDist = 100000

            --Unit cur plateau and land/water zone
            local iCurPlateauOrZero, iCurLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
            if bDebugMessages == true then LOG(sFunctionRef..': Closest plateau and land or water zone to unit position: Unit position='..repru(oUnit:GetPosition())..'; oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurLandOrWaterZone='..(iCurLandOrWaterZone or 'nil')..'; tShortlist='..repru(tShortlist)) end

            local bDontCheckPlayableArea = not(AiBotMap.bIsCampaignMap)
            local bDontHaveLocationInPlayableArea
            local iCurPond
            for iEntry, iWaterZone in tShortlist do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering entry '..iEntry..'; iWaterZone='..iWaterZone..'; Time last failed to drop here='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedWaterZoneDropTime][iWaterZone] or 'nil')..'; Time last dropped='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone][0][iWaterZone] or 'nil')) end
                if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiLastFailedWaterZoneDropTime][iWaterZone] or -300) >= 300 and (not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone][0][iWaterZone]) or GetGameTimeSeconds() - AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone][0][iWaterZone] >= 200) then --we also check the time of last engi drop against the specific zone below
                    bDontHaveLocationInPlayableArea = not(bDontCheckPlayableArea)
                    iCurPond =   AiBotMap.tiPondByWaterZone[iWaterZone]
                    local tWZData = AiBotMap.tPondDetails[iCurPond][AiBotMap.subrefPondWaterZones][iWaterZone]
                    if bDontHaveLocationInPlayableArea then bDontHaveLocationInPlayableArea = not(AiBotConditions.IsLocationInPlayableArea(tWZData[AiBotMap.subrefMidpoint])) end
                    if not(bDontHaveLocationInPlayableArea) then
                        --If there are mexes in this WZ, then only drop if there are unbuilt mexes in this zone (we might be dropping 0 mex WZ to build naval fac though)
                        if bDebugMessages == true then LOG(sFunctionRef..': is table of unbuilt locations empty='..tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefMexUnbuiltLocations]))..'; subrefLZOrWZMexCount='..(tWZData[AiBotMap.subrefLZOrWZMexCount] or 0)..'; Is table of allied units empty='..tostring(AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZTeamData][iTeam][AiBotMap.subreftoLZOrWZAlliedUnits]))) end
                        if AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefMexUnbuiltLocations]) == false or ((tWZData[AiBotMap.subrefLZOrWZMexCount] or 0) == 0 and (AiBotUtilities.IsTableEmpty(tWZData[AiBotMap.subrefWZTeamData][iTeam][AiBotMap.subreftoLZOrWZAlliedUnits]) or AiBotUtilities.IsTableEmpty(EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFactory, tWZData[AiBotMap.subrefWZTeamData][iTeam][AiBotMap.subreftoLZOrWZAlliedUnits])))) then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tWZData[AiBotMap.subrefMidpoint])
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering water zone '..iWaterZone..' with distance of '..iCurDist) end
                            if iCurDist < iClosestDist then
                                local tWZTeamData = tWZData[AiBotMap.subrefWZTeamData][iTeam]
                                if bDebugMessages == true then LOG(sFunctionRef..': Time since last engi drop='..(GetGameTimeSeconds() - (tWZTeamData[AiBotMap.refiTimeLastDroppedEngi] or 0))..'; Want BP='..tostring(tWZTeamData[AiBotMap.subrefTbWantBP])..'; Time since last idle engi by tech='..repru(tWZTeamData[AiBotMap.subrefiTimeLastHadSpareEngiByTech])) end
                                if not(tWZTeamData[AiBotMap.refiTimeLastDroppedEngi]) or GetGameTimeSeconds() - tWZTeamData[AiBotMap.refiTimeLastDroppedEngi] >= 200 then
                                    --Do we have naval fac or multiple engis here already?
                                    if AiBotUtilities.IsTableEmpty(tWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits]) or tWZTeamData[AiBotMap.subrefTbWantBP] or (GetGameTimeSeconds() - math.max((tWZTeamData[AiBotMap.subrefiTimeLastHadSpareEngiByTech][1] or 0), (tWZTeamData[AiBotMap.subrefiTimeLastHadSpareEngiByTech][2] or 0), (tWZTeamData[AiBotMap.subrefiTimeLastHadSpareEngiByTech][3] or 0)) >= 180) then
                                        --Is it safe to travel here?
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering iEntry='..iEntry..'; iWaterZone='..iWaterZone..'; will see if safe to travel here, does enemy have AA threat='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iCurPlateauOrZero, iCurLandOrWaterZone, 0, iWaterZone, false, 60))) end
                                        if not(DoesEnemyHaveAAThreatAlongPath(iTeam, iCurPlateauOrZero, iCurLandOrWaterZone, 0, iWaterZone, false, 60)) then
                                            iClosestDist = iCurDist
                                            iTargetWaterZone = iWaterZone
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, iTargetWaterZone='..(iTargetWaterZone or 'nil')) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iTargetWaterZone
end

function GetTransportEngiCargoAndRemainingCapacity(oUnit, iEngiTechLevel)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetTransportEngiCargoAndRemainingCapacity'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': About to try and get cargo for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; is oUnit.GetCargo nil='..tostring(oUnit.GetCargo == nil)..'; Does unit contain transport category='..tostring(EntityCategoryContains(categories.TRANSPORTATION, oUnit.UnitId))..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
    local tCargo = oUnit:GetCargo()
    local tiClampsByType = AiBotUnitInfo.GetClampsByType(oUnit)
    local iCargoSize = 0
    if AiBotUtilities.IsTableEmpty(tCargo) == false then
        iCargoSize = table.getn(tCargo)
        local iCurCargoTechLevel
        local iCurClampType

        for iCargo, oCargo in tCargo do
            if tiClampsByType[AiBotUnitInfo.refClampStinger] > 0 then
                iCurClampType = AiBotUnitInfo.refClampStinger
            else
                iCurCargoTechLevel = AiBotUnitInfo.GetUnitTechLevel(oCargo)
                if iCurCargoTechLevel == 3 or EntityCategoryContains(categories.COMMAND + categories.SUBCOMMANDER, oCargo.UnitId) then
                    iCurClampType = AiBotUnitInfo.refClampLarge
                elseif iCurCargoTechLevel <= 1 then
                    iCurClampType = AiBotUnitInfo.refClampSmall
                elseif iCurCargoTechLevel <= 2 then
                    iCurClampType = AiBotUnitInfo.refClampMedium
                elseif iCurCargoTechLevel == 4 then
                    iCurClampType = AiBotUnitInfo.refClampExperimental
                else
                    --Redundancy
                    iCurClampType = AiBotUnitInfo.refClampLarge
                end
            end
            if tiClampsByType[iCurClampType] > 0 then
                tiClampsByType[iCurClampType] = tiClampsByType[iCurClampType] - 1
            else
                --Find the next largest clamp and reset
                if bDebugMessages == true then LOG(sFunctionRef..': Dont have enough of the smallest clamp type, iCurClampType='..iCurClampType..'; tiClampsByType='..repru(tiClampsByType)) end
                for iClampType, iClampsAvailable in tiClampsByType do
                    if iClampsAvailable > 0 then
                        tiClampsByType[iClampType] = tiClampsByType[iClampType] - 1
                        if iClampType == AiBotUnitInfo.refClampMedium then
                            --if bDebugMessages == true then LOG(sFunctionRef..': Splitting medium out as it can take 2 small units') end
                            tiClampsByType[AiBotUnitInfo.refClampSmall] = tiClampsByType[AiBotUnitInfo.refClampSmall] + 1
                        elseif iClampType == AiBotUnitInfo.refClampLarge then
                            if iCurClampType == AiBotUnitInfo.refClampSmall then
                                --if bDebugMessages == true then LOG(sFunctionRef..': Splitting large out as it can take 4 small units') end
                                tiClampsByType[AiBotUnitInfo.refClampSmall] = tiClampsByType[AiBotUnitInfo.refClampSmall] + 3
                            else
                                --if bDebugMessages == true then LOG(sFunctionRef..': Splitting large out as it can take 2 medium units') end
                                tiClampsByType[AiBotUnitInfo.refClampMedium] = tiClampsByType[AiBotUnitInfo.refClampMedium] + 1
                            end
                        end
                    end
                end
            end
        end
    end

    --How many of the tech level wanted can we fit in?
    local tiTechLevelCountByClamp = {[AiBotUnitInfo.refClampSmall] = {[1]=1,[2]=0,[3]=0,[4]=0},
                                     [AiBotUnitInfo.refClampMedium] = {[1]=2,[2]=1,[3]=0,[4]=0},
                                     [AiBotUnitInfo.refClampLarge] = {[1]=4,[2]=2,[3]=1,[4]=0},
                                     [AiBotUnitInfo.refClampExperimental] = {[1]=1,[2]=1,[3]=1,[4]=1},
                                     [AiBotUnitInfo.refClampStinger] = {[1]=1,[2]=1,[3]=0,[4]=0}}


    local iCurLevelCapacity = 0
    for iClampType, iClampsAvailable in tiClampsByType do
        if iClampsAvailable > 0 then
            iCurLevelCapacity = iCurLevelCapacity + tiTechLevelCountByClamp[iClampType][iEngiTechLevel] * iClampsAvailable
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, iCurLevelCapacity='..iCurLevelCapacity..'; iCargoSize='..iCargoSize..'; iEngiTechLevel='..iEngiTechLevel..'; tiClampsByType='..repru(tiClampsByType)) end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iCargoSize, iCurLevelCapacity
    --return iCargoSize, iTotalCapacity - iCargoSize
end

function ManageTransports(iTeam, iAirSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageTransports'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    if bDebugMessages == true then LOG(sFunctionRef..': Time of last transport shortlist update='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastTransportShortlistUpdate] or 0)..'; Cur time='..GetGameTimeSeconds()..'; Dif='..GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastTransportShortlistUpdate] or 0)) end
    local tAvailableTransports, tTransportsForRefueling, tUnavailableUnits = GetAvailableLowFuelAndInUseAirUnits(iTeam, iAirSubteam, AiBotUnitInfo.refCategoryTransport - categories.EXPERIMENTAL) --In reality shouldnt have any units for refueling

    local function ManageDualGapReclaimTransport(oTransport)
        local aiBrain = oTransport:GetAIBrain()
        if not aiBrain or not(aiBrain.AiBotDualGapRole == 'top_air'
                or aiBrain.AiBotDualGapRole == 'bottom_air'
                or aiBrain.AiBotDualGapRole == 'eco')
                or GetGameTimeSeconds() < 600
                or aiBrain:GetCurrentUnits(AiBotUnitInfo.refCategoryBomber * categories.TECH3) == 0 then
            return false
        end

        local tCargo = oTransport:GetCargo()
        if AiBotUtilities.IsTableEmpty(tCargo) == false then
            local tBestPosition
            local iBestMass = 0
            local tStart = AiBotMap.GetPlayerStartPosition(aiBrain)
            for _, tReclaimColumn in AiBotMap.tReclaimAreas do
                for _, tReclaimArea in tReclaimColumn do
                    local tPosition = tReclaimArea[AiBotMap.refReclaimSegmentMidpoint]
                    local iMass = tReclaimArea[AiBotMap.refReclaimTotalMass] or 0
                    local bOurHalf = tPosition and ((aiBrain.AiBotDualGapSide == 'left' and tPosition[1] < 512)
                            or (aiBrain.AiBotDualGapSide == 'right' and tPosition[1] > 512))
                    if bOurHalf and iMass > iBestMass
                            and AiBotUtilities.GetDistanceBetweenPositions(tStart, tPosition) >= 100 then
                        iBestMass = iMass
                        tBestPosition = tPosition
                    end
                end
            end
            if tBestPosition and iBestMass >= 25 then
                if not oTransport.AiBotDualGapLastDropOrderTime
                        or GetGameTimeSeconds() - oTransport.AiBotDualGapLastDropOrderTime >= 10 then
                    AiBotOrders.IssueTrackedTransportUnload(oTransport, tBestPosition, 8, false, 'DGRecDrop', true)
                    oTransport.AiBotDualGapReclaimDropped = true
                    oTransport.AiBotDualGapLastDropOrderTime = GetGameTimeSeconds()
                    oTransport.AiBotDualGapReclaimLoadTarget = nil
                    LOG('AiBot Dual Gap reclaim drop dispatched: army='..aiBrain:GetArmyIndex()
                            ..'; mass='..iBestMass..'; target='..tBestPosition[1]..','..tBestPosition[3]
                            ..'; time='..GetGameTimeSeconds())
                end
            end
            return true
        end

        local tStart = AiBotMap.GetPlayerStartPosition(aiBrain)
        if oTransport.AiBotDualGapReclaimDropped
                and AiBotUtilities.GetDistanceBetweenPositions(oTransport:GetPosition(), tStart) > 45 then
            AiBotOrders.IssueTrackedMove(oTransport, tStart, 15, false, 'DGRecHome', true)
            return true
        end

        local oEngineer = oTransport.AiBotDualGapReclaimLoadTarget
        if not AiBotUnitInfo.IsUnitValid(oEngineer) or oEngineer:IsUnitState('Attached') then
            oEngineer = nil
            local iClosestDistance
            local tEngineers = aiBrain:GetListOfUnits(AiBotUnitInfo.refCategoryEngineer * categories.TECH1, false, true)
            if AiBotUtilities.IsTableEmpty(tEngineers) == false then
                for _, oCandidate in tEngineers do
                    if AiBotUnitInfo.IsUnitValid(oCandidate) and oCandidate:GetFractionComplete() == 1
                            and not oCandidate:IsUnitState('Attached') then
                        local iDistance = AiBotUtilities.GetDistanceBetweenPositions(oTransport:GetPosition(), oCandidate:GetPosition())
                        if not iClosestDistance or iDistance < iClosestDistance then
                            oEngineer = oCandidate
                            iClosestDistance = iDistance
                        end
                    end
                end
            end
            oTransport.AiBotDualGapReclaimLoadTarget = oEngineer
        end
        if oEngineer then
            local iDistance = AiBotUtilities.GetDistanceBetweenPositions(oTransport:GetPosition(), oEngineer:GetPosition())
            if iDistance > 10 then
                AiBotOrders.IssueTrackedMove(oTransport, oEngineer:GetPosition(), 6, false, 'DGRecPickup', true)
            elseif not oTransport.AiBotDualGapLastLoadOrderTime
                    or GetGameTimeSeconds() - oTransport.AiBotDualGapLastLoadOrderTime >= 5 then
                AiBotOrders.IssueTrackedTransportLoad(oEngineer, oTransport, false, 'DGRecLoad', true, true)
                oTransport.AiBotDualGapLastLoadOrderTime = GetGameTimeSeconds()
                LOG('AiBot Dual Gap reclaim engineer loading: army='..aiBrain:GetArmyIndex()
                        ..'; engineer='..oEngineer.UnitId..'; distance='..iDistance..'; time='..GetGameTimeSeconds())
            end
        end
        return true
    end

    -- A DualGap air slot does not spend its opening on engineer/combat drops.
    -- Keep an initial ACU transport available to unload the commander, but
    -- remove every other transport from the generic drop planner.
    local function FilterDualGapAirTransports(tUnits)
        if AiBotUtilities.IsTableEmpty(tUnits) == false then
            for iUnit = table.getn(tUnits), 1, -1 do
                if ManageDualGapReclaimTransport(tUnits[iUnit])
                        or not AiBotDualGap.CanUseTransportDrop(tUnits[iUnit]) then
                    table.remove(tUnits, iUnit)
                end
            end
        end
    end
    FilterDualGapAirTransports(tAvailableTransports)
    FilterDualGapAirTransports(tTransportsForRefueling)
    FilterDualGapAirTransports(tUnavailableUnits)
    if GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastTransportShortlistUpdate] or 0) >= 0.8 then
        local bUpdateCombatDropShortlist = false
        --Only consider combat drops if we already have a transport (for now)
        if AiBotUtilities.IsTableEmpty(tAvailableTransports) == false or AiBotUtilities.IsTableEmpty(tUnavailableUnits) == false or (GetGameTimeSeconds() >= 420 and GetGameTimeSeconds() - (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiTimeOfLastTransportCombatShortlistUpdate] or 0) >= 60) then bUpdateCombatDropShortlist = true end
        UpdateTransportPlateauDropLocationShortlist(iTeam, bUpdateCombatDropShortlist)
    end
    local tRallyPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]

    if bDebugMessages == true then LOG(sFunctionRef..': Near start, time='..GetGameTimeSeconds()..'; Is table of available transports empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableTransports))..'; tRallyPoint='..repru(tRallyPoint)..'; Is table of unavailable units empty='..tostring(AiBotUtilities.IsTableEmpty(tUnavailableUnits))) end

    function RemoveDropFromShortlist(iTargetPlateau, iTargetIsland, iTargetZone)
        local bRemovedEntry = false
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiHighTechEngiDropPlateauAndZones]) == false then
            for iEntry, tPlateauZoneAndTech in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiHighTechEngiDropPlateauAndZones] do
                if tPlateauZoneAndTech[1] == iTargetPlateau and tPlateauZoneAndTech[2] == iTargetZone then
                    bRemovedEntry = true
                    break
                end
            end
        end
        if not(bRemovedEntry) then
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportIslandDropShortlist]) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': iTargetPlateau='..(iTargetPlateau or 'nil')..'; iTargetZone='..(iTargetZone or 'nil')..'; iTargetIsland='..(iTargetIsland or 'nil')..'; will check if on island drop hsortlist') end
                if iTargetIsland then
                    for iEntry, tPlateauAndIsland in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportIslandDropShortlist] do
                        if tPlateauAndIsland[1] == iTargetPlateau and tPlateauAndIsland[2] == iTargetIsland then
                            bRemovedEntry = true
                            table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportIslandDropShortlist], iEntry)
                            break
                        end
                    end
                end
            end
            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportFarAwaySameIslandPlateauLandZoneDropShortlist]) == false then
                for iEntry, tPlateauAndLZ in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportFarAwaySameIslandPlateauLandZoneDropShortlist] do
                    if tPlateauAndLZ[1] == iTargetPlateau and tPlateauAndLZ[2] == iTargetZone then
                        bRemovedEntry = true
                        table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportFarAwaySameIslandPlateauLandZoneDropShortlist], iEntry)
                        break
                    end
                end
            end
        end
        return bRemovedEntry
    end

    --First manage 'busy' transports - i.e. consider dropping early
    function ConsiderEmergencyDrops(tUnitsToConsider, bRemoveFromTableIfEmergencyDrop, bRefreshDropOrderIfNoUnitState, bRemoveFromShortlist)
        for iUnit, oUnit in tUnitsToConsider do
            local tCargo = oUnit:GetCargo()
            if AiBotUtilities.IsTableEmpty(tCargo) == false then
                if bRemoveFromShortlist and oUnit[refiTargetPlateauForDrop] then
                    RemoveDropFromShortlist(oUnit[refiTargetPlateauForDrop], (oUnit[refiTargetIslandForDrop] or NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, (oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition] or AiBotMap.GetPlayerStartPosition(oUnit:GetAIBrain())))), (oUnit[refiTargetZoneForDrop] or 0))
                end
                local bDropNow, bAlwaysDropAtTarget, bAbortDrop = ShouldTransportDropEarlyOrAlwaysDropAtTarget(oUnit, iTeam, false)
                if bDebugMessages == true then LOG(sFunctionRef..': Considering transport with a cargo, oUnit='..(oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit))..'; owned by '..oUnit:GetAIBrain().Nickname..'; bDropNow='..tostring(bDropNow)..'; oUnit[refbCombatDrop]='..tostring(oUnit[refbCombatDrop] or false)..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; LastOrder subreftOrderPosition='..repru(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition])..'; Cur unit position='..repru(oUnit:GetPosition())..'; Transport target drop=P'..(oUnit[refiTargetPlateauForDrop] or 'nil')..'Z'..(oUnit[refiTargetZoneForDrop] or 'nil')..'; bRemoveFromShortlist='..tostring(bRemoveFromShortlist or false)) end
                if bDropNow then
                    --Drop early
                    AiBotOrders.IssueTrackedTransportUnload(oUnit, oUnit:GetPosition(), 8, false, 'EmergBDr', false)
                    oUnit[refbEmergencyDropActive] = true
                    if bRemoveFromTableIfEmergencyDrop then table.remove(tUnitsToConsider, iUnit) end
                    --Transports that are about to do a combat drop in range of enemy PD that have just detected - adjust drop location slightly
                elseif bAbortDrop then
                    --Go to the nearest base
                    if bDebugMessages == true then LOG(sFunctionRef..': Will abort and return to base') end
                    local tNewDropLocation
                    local tCurLZData, tCurLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                    if tCurLZTeamData[AiBotMap.reftClosestFriendlyBase] then
                        tNewDropLocation = {tCurLZTeamData[AiBotMap.reftClosestFriendlyBase][1], tCurLZTeamData[AiBotMap.reftClosestFriendlyBase][2], tCurLZTeamData[AiBotMap.reftClosestFriendlyBase][3]}
                    else
                        tNewDropLocation = AiBotMap.GetPlayerStartPosition(oUnit:GetAIBrain())
                    end
                    if AiBotUtilities.IsTableEmpty(tNewDropLocation) == false then
                        --Emergency drop at this new location
                        AiBotOrders.IssueTrackedTransportUnload(oUnit, tNewDropLocation, 2, false, 'EmergPDDr', false)
                        --oUnit[refbEmergencyDropActive] = true --Dont treat as emergency drop because we want the transport to receive new orders, i.e. we are presumably aborting because of the ground threat in the zone we were about to drop
                        if bRemoveFromTableIfEmergencyDrop then table.remove(tUnitsToConsider, iUnit) end
                    end
                elseif oUnit[refbCombatDrop] then
                    local tOrderTarget = oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition]
                    if AiBotUtilities.IsTableEmpty(tOrderTarget) == false then
                        local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tOrderTarget)
                        if iDistToTarget <= 35 and iDistToTarget >= 5 then --if are right ontop then no point aborting
                            --T1 PD have range of 26; do 28 since if have multiple units some of them may get hit
                            local tNearbyT1PD = oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryPD * categories.TECH1, tOrderTarget, 28, 'Enemy')
                            if AiBotUtilities.IsTableEmpty(tNearbyT1PD) == false then
                                local oClosestConstructedPDToRally, iCurDist
                                local iClosestConstructedPDDist = 100000
                                for iPD, oPD in tNearbyT1PD do
                                    if oPD:GetFractionComplete() >= 0.95 then
                                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oPD:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
                                        if iCurDist < iClosestConstructedPDDist then
                                            oClosestConstructedPDToRally = oPD
                                            iClosestConstructedPDDist = iCurDist
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': iClosestConstructedPDDist to our rally point='..iClosestConstructedPDDist..'; oClosestConstructedPDToRally='..(oClosestConstructedPDToRally.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestConstructedPDToRally) or 'nil')) end
                                if oClosestConstructedPDToRally then
                                    local iAngleToMove
                                    local tNewDropLocation
                                    if bDebugMessages == true then LOG(sFunctionRef..': Dist from PD to order target='..AiBotUtilities.GetDistanceBetweenPositions(tOrderTarget, oClosestConstructedPDToRally:GetPosition())) end
                                    if AiBotUtilities.GetDistanceBetweenPositions(tOrderTarget, oClosestConstructedPDToRally:GetPosition()) >= 4 then --far enough away that we presumably aren't already dropping
                                        --If we move a bit further away are we ok?
                                        local iAngleToMove = AiBotUtilities.GetAngleFromAToB(oClosestConstructedPDToRally:GetPosition(), tOrderTarget)
                                        tNewDropLocation = AiBotUtilities.MoveInDirection(oClosestConstructedPDToRally:GetPosition(), iAngleToMove, math.max(oClosestConstructedPDToRally[AiBotUnitInfo.refiCombatRange] or 0) + 5, 35, true, false, true)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Trying to move drop location slightly away from PD, tNewDropLocation='..repru(tNewDropLocation)..'; Island label for this='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tNewDropLocation) or 'nil')..'; Island ref of the orig order target='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tOrderTarget) or 'nil')) end
                                        if AiBotUtilities.IsTableEmpty(tNewDropLocation) == false and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tNewDropLocation) == NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tOrderTarget) then
                                            local tPDAroundNewPotentialDropLocation = oUnit:GetAIBrain():GetUnitsAroundPoint(AiBotUnitInfo.refCategoryPD * categories.TECH1, tNewDropLocation, 28, 'Enemy')
                                            if bDebugMessages == true then LOG(sFunctionRef..': Are there PD if we move a bit further away from the closest one? Is tPDAroundNewPotentialDropLocation empty='..tostring(AiBotUtilities.IsTableEmpty(tPDAroundNewPotentialDropLocation))) end
                                            if AiBotUtilities.IsTableEmpty(tPDAroundNewPotentialDropLocation) == false then
                                                tNewDropLocation = nil
                                            end
                                        else
                                            tNewDropLocation = nil
                                        end
                                    end
                                    if not(tNewDropLocation) then
                                        iAngleToMove = AiBotUtilities.GetAngleFromAToB(oClosestConstructedPDToRally:GetPosition(),AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
                                        tNewDropLocation = AiBotUtilities.MoveInDirection(oClosestConstructedPDToRally:GetPosition(), iAngleToMove, math.max(oClosestConstructedPDToRally[AiBotUnitInfo.refiCombatRange] or 0) + 5, 35, true, false, true)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Adjusting drop location, tNewDropLocation='..repru(tNewDropLocation)..'; Island label for this='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tNewDropLocation) or 'nil')..'; Island ref of the orig order target='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tOrderTarget) or 'nil')) end
                                        if not(AiBotUtilities.IsTableEmpty(tNewDropLocation) == false and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tNewDropLocation) == NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tOrderTarget)) then
                                            tNewDropLocation = nil
                                        end
                                    end

                                    if AiBotUtilities.IsTableEmpty(tNewDropLocation) == false then
                                        --Emergency drop at this new location
                                        AiBotOrders.IssueTrackedTransportUnload(oUnit, tNewDropLocation, 2, false, 'EmergPDDr', false)
                                        oUnit[refbEmergencyDropActive] = true
                                        if bRemoveFromTableIfEmergencyDrop then table.remove(tUnitsToConsider, iUnit) end
                                    end
                                end
                            end
                        end
                    end
                end
                --[[if not(bDropNow) and bRefreshDropOrderIfNoUnitState and oUnit[AiBotOrders.refiOrderCount] <= 1 then
    local tLastOrder = oUnit[AiBotOrders.reftiLastOrders][1]
    if tLastOrder[AiBotOrders.subrefiOrderType]
    AiBotOrders.UpdateRecordedOrders(oUnit)
    if
end--]]
            elseif oUnit[refbEmergencyDropActive] then oUnit[refbEmergencyDropActive] = nil --redundancy (shouldnt ever trigger)
            end
        end
    end
    if AiBotUtilities.IsTableEmpty(tUnavailableUnits) == false then
        ConsiderEmergencyDrops(tUnavailableUnits, false, false, true)
        if bDebugMessages == true then LOG(sFunctionRef..': Finished cycling through unavailable units to decide if we should drop now') end
    end

    --Campaign override - ignore transports in the first minute of the game if this is a campaign AI
    if AiBotMap.bIsCampaignMap and AiBotUtilities.IsTableEmpty(tAvailableTransports) == false and GetGameTimeSeconds() <= 60 then
        for iCurEntry = table.getn(tAvailableTransports), 1, -1 do
            local oTransport = tAvailableTransports[iCurEntry]
            if oTransport:GetAIBrain().CampaignAI then
                if bDebugMessages == true then LOG(sFunctionRef..': Have campaign transport in the first minute so will abort orders') end
                table.remove(tAvailableTransports, iCurEntry)
            end
        end
    end
    if AiBotUtilities.IsTableEmpty(tAvailableTransports) == false then
        ConsiderEmergencyDrops(tAvailableTransports, true, false, false)
        if bDebugMessages == true then LOG(sFunctionRef..': Finsihed cycling through available transports to see if we should drop now, is table empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableTransports))) end
        if AiBotUtilities.IsTableEmpty(tAvailableTransports) == false then
            --Cycle through each transport, and decide the best island to try and drop to - first sort transports by distance so are less likely to have a far away transport go to a aplteau that a closer one can reach

            if table.getn(tAvailableTransports) > 1 then
                --Multiple transports can have issues with being stuck in a loop depending on the location of the drop target; therefore want to exclude any avaialble tranpsorts that have been given an unload order
                local bRemovedEntry
                for iCurTransportEntry = table.getn(tAvailableTransports), 1, -1 do
                    bRemovedEntry = false
                    local oTransport = tAvailableTransports[iCurTransportEntry]
                    AiBotOrders.UpdateRecordedOrders(oTransport)
                    local tLastOrder = oTransport[AiBotOrders.reftiLastOrders][oTransport[AiBotOrders.refiOrderCount]]
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering available oTransport='..oTransport.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTransport)..' owned by brain '..oTransport:GetAIBrain().Nickname..'; last order type='..(tLastOrder[AiBotOrders.subrefiOrderType] or 'nil')..'; refiTargetZoneForDrop='..(oTransport[refiTargetZoneForDrop] or 'nil')) end
                    if tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderUnloadTransport and oTransport[refiTargetZoneForDrop] and AiBotUtilities.IsTableEmpty(tLastOrder[AiBotOrders.subreftOrderPosition]) == false then
                        local iTargetPlateau, iTargetZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tLastOrder[AiBotOrders.subreftOrderPosition])
                        if iTargetZone == oTransport[refiTargetZoneForDrop] then
                            bRemovedEntry = RemoveDropFromShortlist((oTransport[refiTargetPlateauForDrop] or NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tLastOrder[AiBotOrders.subreftOrderPosition])), (oTransport[refiTargetIslandForDrop] or NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tLastOrder[AiBotOrders.subreftOrderPosition])), oTransport[refiTargetZoneForDrop])
                        end
                        local bAbort = false
                        if not(bRemovedEntry) then
                            local tTargetZoneData, tTargetZoneTeamData
                            if iTargetPlateau == 0 then
                                tTargetZoneData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iTargetZone]][AiBotMap.subrefPondWaterZones][iTargetZone]
                                tTargetZoneTeamData = tTargetZoneData[AiBotMap.subrefWZTeamData][iTeam]
                            else
                                tTargetZoneData = AiBotMap.tAllPlateaus[iTargetPlateau][AiBotMap.subrefPlateauLandZones][iTargetZone]
                                tTargetZoneTeamData = tTargetZoneData[AiBotMap.subrefLZTeamData][iTeam]
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': We didnt remove the target from the shortlist which sugests we no longer think the target is suitable - if it has an ACU or there are sufficient enemies around the dropzone then abort the drop, enemy combat threat at zone='..(tTargetZoneTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')) end
                            local iCombatThreshold = 50
                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportFarAwaySameIslandPlateauLandZoneDropShortlist]) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportIslandDropShortlist]) then
                                --Might as well chance a drop, maybe our engineers can reclaim a tank or they move away before we get there
                                iCombatThreshold = 125
                            end
                            if (tTargetZoneTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) >= iCombatThreshold and not(tTargetZoneTeamData[AiBotMap.subrefLZbCoreBase]) then
                                if AiBotConditions.IsTableOfUnitsStillValid(tTargetZoneTeamData[AiBotMap.subrefTEnemyUnits]) then
                                    local tUnitsNearDropZone = {}
                                    for iUnit, oUnit in tTargetZoneTeamData[AiBotMap.subrefTEnemyUnits] do
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Unit combat range='..(oUnit[AiBotUnitInfo.refiCombatRange] or 0)..'; Fraction complete='..oUnit:GetFractionComplete()..'; Dist from unit position to order position='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLastOrder[AiBotOrders.subreftOrderPosition])) end
                                        if (oUnit[AiBotUnitInfo.refiCombatRange] or 0) >= 15 and oUnit:GetFractionComplete() >= 0.9 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLastOrder[AiBotOrders.subreftOrderPosition]) <= oUnit[AiBotUnitInfo.refiCombatRange] + 5 then
                                            table.insert(tUnitsNearDropZone, oUnit)
                                            if bDebugMessages == true then LOG(sFunctionRef..': Adding unit as one of those close to the drop zone') end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Combat threat of units near drop zone='..AiBotUnitInfo.GetCombatThreatRating(tUnitsNearDropZone, true, false)..'; iCombatThreshold='..iCombatThreshold) end
                                    if AiBotUtilities.IsTableEmpty(tUnitsNearDropZone) == false and AiBotUnitInfo.GetCombatThreatRating(tUnitsNearDropZone, true, false) >= iCombatThreshold then
                                        bAbort = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Want to abort transport drop for target zone '..iTargetZone..'; PlateauOrZero='..iTargetPlateau..' and transport '..oTransport.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTransport)..' as enemy has too large a combat threat near the drop point') end
                                    elseif bDebugMessages == true then LOG(sFunctionRef..': Combat threat near drop zone is low enough that will risk dropping')
                                    end
                                end
                            end
                        end
                        if not(bAbort) then
                            if bDebugMessages == true then LOG(sFunctionRef..': bRemovedEntry='..tostring(bRemovedEntry or false)) end
                            --if bRemovedEntry then
                            table.remove(tAvailableTransports, iCurTransportEntry)
                            --end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Will clear the transport orders and make it available') end
                            AiBotOrders.IssueTrackedClearCommands(oTransport)
                        end
                    end
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Do we have available transports after (if we have multiple trans) excluding those given unload order? is tAvailableTransports empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableTransports))) end
        if AiBotUtilities.IsTableEmpty(tAvailableTransports) == false then
            --DoesEnemyHaveAAThreatAlongPath(iTeam, iCurPlateauOrZero, iCurLandOrWaterZone, tiPlateauAndIsland[1], iClosestLZ, false, 60)) then


            local tiTransportDistance = {}
            local iMinUnitTechLevel, bIsEngiSupportDrop
            for iUnit, oUnit in tAvailableTransports do
                tiTransportDistance[iUnit] = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint)
                oUnit[refiEngisWanted] = 0
                oUnit[refiTargetIslandForDrop] = nil --will change later if we are dropping
            end

            local iIslandToTravelTo, iPlateauToTravelTo, iLandZoneToTravelTo, iExtraEngisWanted, iEngisHave, iEngiRemainingCapacity
            local iTechLevel = AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyFactoryTech]
            for iUnitRef, iDistance in AiBotUtilities.SortTableByValue(tiTransportDistance, true) do --sort high to low, with thel ogic that rally is likely close to our base, so high dist is likely closer to enemy/plateau
                local oUnit = tAvailableTransports[iUnitRef]
                local bTravelToSameIsland = false
                local iWaterZoneToTravelTo
                iMinUnitTechLevel = nil
                iIslandToTravelTo, iPlateauToTravelTo, iLandZoneToTravelTo = GetIslandPlateauAndLandZoneForTransportToTravelTo(iTeam, oUnit)
                if bDebugMessages == true then LOG(sFunctionRef..': iUnitRef='..iUnitRef..'; Considering transport '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by brain '..oUnit:GetAIBrain().Nickname..'; iDistance to rally point='..iDistance..'; iIslandToTravelTo='..(iIslandToTravelTo or 'nil')..'; iPlateauToTravelTo='..(iPlateauToTravelTo or 'nil')..'; iLandZoneToTravelTo='..(iLandZoneToTravelTo or 'nil')) end
                if not(iIslandToTravelTo) then

                    iIslandToTravelTo, iPlateauToTravelTo, iLandZoneToTravelTo = GetFarAwayLandZoneOnCurrentIslandForTransportToTravelTo(iTeam, oUnit)
                    if bDebugMessages == true then LOG(sFunctionRef..': Transport doesnt have an island to travel to, will see if have far away land zones we want to travel to instead, iIslandToTravelTo after check='..(iIslandToTravelTo or 'nil')) end
                    if iIslandToTravelTo then bTravelToSameIsland = true
                    else
                        iWaterZoneToTravelTo = GetWaterZoneForTransportToTravelTo(iTeam, oUnit)
                        iLandZoneToTravelTo = nil --redundancy
                        iPlateauToTravelTo = 0 --redundancy
                    end
                else
                    --Consider far away land zones with 3+ mexes in them if the target plateau only has 1 mex and not lots of reclaim
                    local tCurTargetLZData = AiBotMap.tAllPlateaus[iPlateauToTravelTo][AiBotMap.subrefPlateauLandZones][iLandZoneToTravelTo]
                    if bDebugMessages == true then LOG(sFunctionRef..': Mexes in target island='..(AiBotMap.tAllPlateaus[iPlateauToTravelTo][AiBotMap.subrefPlateauIslandMexCount][iIslandToTravelTo] or 'nil')..'; P'..iPlateauToTravelTo..'Z'..iLandZoneToTravelTo..'; subrefTotalSignificantMassReclaim='..(tCurTargetLZData[AiBotMap.subrefTotalSignificantMassReclaim] or 'nil')) end


                    if iPlateauToTravelTo and iLandZoneToTravelTo and (AiBotMap.tAllPlateaus[iPlateauToTravelTo][AiBotMap.subrefPlateauIslandMexCount][iIslandToTravelTo] or 0) <= 1 and (tCurTargetLZData[AiBotMap.subrefTotalSignificantMassReclaim] or 0) < 2000 then
                        local bUseFarAwayZoneInstead = false
                        local iOrigIsland, iOrigPlateau, iOrigLZ
                        iOrigIsland = iIslandToTravelTo
                        iOrigPlateau = iPlateauToTravelTo
                        iOrigLZ = iLandZoneToTravelTo
                        iIslandToTravelTo, iPlateauToTravelTo, iLandZoneToTravelTo = GetFarAwayLandZoneOnCurrentIslandForTransportToTravelTo(iTeam, oUnit)
                        --If the mod dist of this is <= 0.55 and it has 3+ mexes then pick this instead
                        if iPlateauToTravelTo and iLandZoneToTravelTo then
                            local tFarAwayLZData = AiBotMap.tAllPlateaus[iPlateauToTravelTo][AiBotMap.subrefPlateauLandZones][iLandZoneToTravelTo]
                            local tFarAwayLZTeamData = tFarAwayLZData[AiBotMap.subrefLZTeamData][iTeam]
                            if bDebugMessages == true then LOG(sFunctionRef..': Far away zone mod dist='..tFarAwayLZTeamData[AiBotMap.refiModDistancePercent]..'; Mex count='..tFarAwayLZData[AiBotMap.subrefLZOrWZMexCount]) end
                            if tFarAwayLZData[AiBotMap.subrefLZOrWZMexCount] >= 3 and  tFarAwayLZTeamData[AiBotMap.refiModDistancePercent] <= 0.55 then
                                bUseFarAwayZoneInstead = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Will use far away zone instead, P'..iPlateauToTravelTo..'Z'..iLandZoneToTravelTo) end
                            end
                        end
                        if not(bUseFarAwayZoneInstead) then
                            iIslandToTravelTo = iOrigIsland
                            iPlateauToTravelTo = iOrigPlateau
                            iLandZoneToTravelTo = iOrigLZ
                        end
                    end
                end
                if not(iIslandToTravelTo) and not(iWaterZoneToTravelTo) then
                    --Do we have any zones wanting engineer support?
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiHighTechEngiDropPlateauAndZones]) == false then
                        iIslandToTravelTo, iPlateauToTravelTo, iLandZoneToTravelTo = GetPlateauAndZoneForEngineerSupport(iTeam, oUnit)
                        if iIslandToTravelTo or iLandZoneToTravelTo then
                            if bDebugMessages == true then LOG(sFunctionRef..': Setting bIsEngiSupportDrop to true, iIslandToTravelTo='..(iIslandToTravelTo or 'nil')..'; iLandZoneToTravelTo='..(iLandZoneToTravelTo or 'nil')) end
                            bIsEngiSupportDrop = true
                            --Set min engi tech level
                            for iEntry, tPlateauZoneAndTech in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiHighTechEngiDropPlateauAndZones] do
                                if tPlateauZoneAndTech[1] == iPlateauToTravelTo and tPlateauZoneAndTech[2] == iLandZoneToTravelTo then
                                    iMinUnitTechLevel = tPlateauZoneAndTech[3]
                                    break
                                end
                            end
                        end
                    end
                    if not(iIslandToTravelTo) and not(iWaterZoneToTravelTo) then
                        if oUnit[refbCombatDrop] or AiBotUtilities.IsTableEmpty(oUnit:GetCargo()) then
                            local iCombatEntryRef = GetCombatDropPlateauAndLandZoneEntryRefForTransport(iTeam, oUnit)
                            if iCombatEntryRef then
                                iPlateauToTravelTo = AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportCombatPlateauLandZoneDropShortlist][iCombatEntryRef][1]
                                iLandZoneToTravelTo = AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportCombatPlateauLandZoneDropShortlist][iCombatEntryRef][2]
                                iIslandToTravelTo = AiBotMap.tAllPlateaus[iPlateauToTravelTo][AiBotMap.subrefPlateauLandZones][iLandZoneToTravelTo][AiBotMap.subrefLZIslandRef]
                            end
                            if iIslandToTravelTo then
                                if bDebugMessages == true then LOG(sFunctionRef..'; Will try and do a combat drop for transport '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at time='..GetGameTimeSeconds()) end
                                oUnit[refbCombatDrop] = true
                            end
                        end
                    end
                else
                    oUnit[refbCombatDrop] = false
                    if bDebugMessages == true then LOG(sFunctionRef..': Dont want combat drop') end
                end
                oUnit[refiTransMinEngiTechLevel] = iMinUnitTechLevel
                if iIslandToTravelTo or iWaterZoneToTravelTo then
                    local tLZOrWZData
                    if iIslandToTravelTo then tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauToTravelTo][AiBotMap.subrefPlateauLandZones][iLandZoneToTravelTo]
                    else tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZoneToTravelTo]][AiBotMap.subrefPondWaterZones][iWaterZoneToTravelTo]
                    end

                    --Decide how many engineers we want to drop on this LZ
                    iEngisHave, iEngiRemainingCapacity = GetTransportEngiCargoAndRemainingCapacity(oUnit, iTechLevel)
                    if iEngisHave >= 4 or iEngiRemainingCapacity < 0 or (iEngiRemainingCapacity == 1 and iEngisHave >= 3) then
                        iExtraEngisWanted = 0
                    elseif iEngisHave >= 1 and oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderUnloadTransport then
                        --Want transport to drop with what it has
                        iExtraEngisWanted = 0
                    else
                        if oUnit[refbCombatDrop] then
                            iExtraEngisWanted = math.min(iEngiRemainingCapacity, 8 - iEngisHave)
                            if (oUnit[refiTransportTimeSpentWaiting] or 0) >= 30 and iEngisHave >= 3 then iExtraEngisWanted = 0
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': want to do combat drop, iExtraEngisWanted='..iExtraEngisWanted) end
                        elseif bIsEngiSupportDrop then
                            if iEngisHave >= 2 then iExtraEngisWanted = 0
                            else
                                iExtraEngisWanted = 2 - iEngisHave
                                if (oUnit[refiTransportTimeSpentWaiting] or 0) >= 30 and iEngisHave >= 1 then
                                    iExtraEngisWanted = 0
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Transport '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' iExtraEngisWanted='..iExtraEngisWanted..'; iEngisHave='..iEngisHave..'; Time spent waiting='..(oUnit[refiTransportTimeSpentWaiting] or 0)) end
                        else
                            --First calculate how many we want (ignoring ones we already have):
                            local iBuildRate = math.max(1, (oUnit:GetAIBrain()[AiBotEconomy.refiBrainBuildRateMultiplier] or 1))
                            if iWaterZoneToTravelTo then iExtraEngisWanted = 1
                            else
                                iExtraEngisWanted = math.max(1, AiBotMap.tAllPlateaus[iPlateauToTravelTo][AiBotMap.subrefPlateauIslandMexCount][iIslandToTravelTo] / iBuildRate)
                                if AiBotMap.tAllPlateaus[iPlateauToTravelTo][AiBotMap.subrefPlateauIslandMexCount][iIslandToTravelTo] <= 2 then iExtraEngisWanted = 1 end
                            end

                            if iExtraEngisWanted == 2 then iExtraEngisWanted = 1 end --Only want 1 engi for 1-2 mex plateaus (as wont be building land fac)
                            --Cap engis at 4 (fewer if likely T2 or T3 engis), and also reduce for the number of engineers we already have
                            iExtraEngisWanted = math.min(5 - iTechLevel, math.max(1, 4 / iBuildRate) - iEngisHave, math.max(0, iExtraEngisWanted - iEngisHave), iEngiRemainingCapacity)
                            --Reduce extra engis wanted if we have been waiting a while
                            if bDebugMessages == true then LOG(sFunctionRef..': Checking if we have been waiting a while, in which case do we want to reduce engineers wnated, time spent waiting='..(oUnit[refiTransportTimeSpentWaiting] or 'nil')..'; iEngisHave='..iEngisHave..'; iExtraEngisWanted pre adjust='..iExtraEngisWanted..'; Dist to zone midpoint='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZOrWZData[AiBotMap.subrefMidpoint])) end
                            if (oUnit[refiTransportTimeSpentWaiting] or 0) >= 30 and iEngisHave >= 1 and iEngisHave >= iExtraEngisWanted then
                                if bDebugMessages == true then LOG(sFunctionRef..': Time spent waiting >= 30 so dont want more engineers') end
                                iExtraEngisWanted = 0
                            elseif iEngisHave >= 2 then
                                local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLZOrWZData[AiBotMap.subrefMidpoint])
                                if iDistToTarget <= 250 and iEngisHave >= 3 / iBuildRate and ((oUnit[refiTransportTimeSpentWaiting] or 0) >= 2 and not(AiBotUnitInfo.IsUnitValid(oUnit[refoTransportUnitTryingToLoad]))) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Have been waiting for at least 2 seconds and no engineers trying to load so dont want more engineers') end
                                    iExtraEngisWanted = 0
                                elseif (oUnit[refiTransportTimeSpentWaiting] or 0) >= 10 then
                                    if iDistToTarget <= 350 then
                                        if iEngisHave >= 3 / iBuildRate then
                                            iExtraEngisWanted = 0
                                        elseif iDistToTarget <= 240 then
                                            iExtraEngisWanted = 0
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': iExtraEngisWanted after dist check='..iExtraEngisWanted) end
                                end
                            end
                        end
                    end
                    local bGetMoreUnits = false
                    if bDebugMessages == true then LOG(sFunctionRef..': iExtraEngisWanted='..(iExtraEngisWanted or 'nil')..'; iEngisHave='..(iEngisHave or 'nil')..'; iTechLevel='..(iTechLevel or 'nil')..'; Mex count of target island='..(AiBotMap.tAllPlateaus[iPlateauToTravelTo][AiBotMap.subrefPlateauIslandMexCount][iIslandToTravelTo] or 'nil')..'; iEngiRemainingCapacity='..(iEngiRemainingCapacity or 'nil')) end
                    if iExtraEngisWanted == 0 and iEngisHave == 0 then
                        AiBotUtilities.ErrorHandler('Dont have any engis but dont want any, something has gone wrong')
                        oUnit[refiEngisWanted] = iExtraEngisWanted
                        oUnit[refiCombatUnitsWanted] = nil
                    elseif iExtraEngisWanted > 0 then
                        oUnit[refiTransportTimeSpentWaiting] = (oUnit[refiTransportTimeSpentWaiting] or 0) + 1
                        --Want to wait for more engineers unless have some already and arent on a core LZ
                        local iCurPlateauOrZero, iCurLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())

                        local tCurLZOrWZTeamData
                        local tCurLZOrWZData
                        if iCurPlateauOrZero > 0 then
                            --Dealing with a land zone so it might have a land factory
                            tCurLZOrWZData = AiBotMap.tAllPlateaus[iCurPlateauOrZero][AiBotMap.subrefPlateauLandZones][iCurLandOrWaterZone]
                            tCurLZOrWZTeamData = tCurLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                        else
                            tCurLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iCurLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iCurLandOrWaterZone]
                            tCurLZOrWZTeamData = tCurLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurLandOrWaterZone='..(iCurLandOrWaterZone or 'nil')..'; Is this a core base='..tostring(tCurLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or false)) end
                        if tCurLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] or iEngisHave == 0 then

                            bGetMoreUnits = true
                            if oUnit[refbCombatDrop] then
                                oUnit[refiCombatUnitsWanted] = iExtraEngisWanted
                                oUnit[refiEngisWanted] = 0
                            else
                                oUnit[refiEngisWanted] = iExtraEngisWanted
                                oUnit[refiCombatUnitsWanted] = nil
                            end
                            --Get more engis/combat units
                            if tCurLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] then

                                if AiBotUnitInfo.IsUnitValid(oUnit[refoTransportUnitTryingToLoad]) and not(oUnit[refoTransportUnitTryingToLoad]:IsUnitState('Attached')) and oUnit[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionLoadOntoTransport then
                                    --Do nothing re orders if transport already has an engineer assigned to load onto it (as dont want to override transport orders incase engineers are trying to load onto it)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Already have an engineer assigned to load onto this transport='..oUnit[refoTransportUnitTryingToLoad].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit[refoTransportUnitTryingToLoad])..'; Engineer action='..oUnit[AiBotEngineer.refiAssignedAction]) end
                                else
                                    --Find the closest engineer to us that has an order to load onto a transport, if there is one, otherwise move to the midpoint
                                    local tHoldingLocation
                                    local oClosestLoadingEngineer
                                    local iClosestLoadingEngineerDist = 1000
                                    local iCurEngiDist
                                    local iCategoryWanted
                                    if oUnit[refbCombatDrop] then iCategoryWanted = AiBotUnitInfo.refCategoryIndirect * categories.TECH1 else iCategoryWanted = AiBotUnitInfo.refCategoryEngineer end
                                    local tEngineersInZone = EntityCategoryFilterDown(iCategoryWanted, tCurLZOrWZTeamData[AiBotMap.subreftoLZOrWZAlliedUnits])
                                    for iEngineer, oEngineer in tEngineersInZone do
                                        if AiBotUnitInfo.IsUnitValid(oEngineer) and oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionLoadOntoTransport and not(oEngineer:IsUnitState('Attached')) and (not(iMinUnitTechLevel) or AiBotUnitInfo.GetUnitTechLevel(oEngineer) >= iMinUnitTechLevel) and oEngineer:GetFractionComplete() == 1 then
                                            local tEngineerLastOrder = oEngineer[AiBotOrders.reftiLastOrders][oEngineer[AiBotOrders.refiOrderCount]]
                                            if not(AiBotUnitInfo.IsUnitValid(tEngineerLastOrder[AiBotOrders.subrefoOrderUnitTarget])) or tEngineerLastOrder[AiBotOrders.subrefoOrderUnitTarget] == oUnit or not(EntityCategoryContains(AiBotUnitInfo.refCategoryTransport, oUnit)) then
                                                iCurEngiDist = AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), oUnit:GetPosition())
                                                if iCurEngiDist < iClosestLoadingEngineerDist then
                                                    iClosestLoadingEngineerDist = iCurEngiDist
                                                    oClosestLoadingEngineer = oEngineer
                                                end
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': iClosestLoadingEngineerDist='..iClosestLoadingEngineerDist..'; oClosestLoadingEngineer='..(oClosestLoadingEngineer.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestLoadingEngineer) or 'nil')) end
                                    if oClosestLoadingEngineer then
                                        tHoldingLocation = oClosestLoadingEngineer:GetPosition()
                                        --If we are close to the engineer then instead get the engineer to give an order to load onto this transport, if we dont have such an engineer recorded

                                        if iClosestLoadingEngineerDist <= 12 then
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will try and get closest loading engineer to load onto transport, unit state='..AiBotUnitInfo.GetUnitState(oClosestLoadingEngineer)..'; Time='..GetGameTimeSeconds()) end
                                            AiBotOrders.IssueTrackedTransportLoad(oClosestLoadingEngineer, oUnit, false, 'TrLNrEng', false)
                                        else
                                            AiBotOrders.IssueTrackedMove(oUnit, tHoldingLocation, 5,                   false,              'TrLFarE',            false)
                                        end
                                    else
                                        tHoldingLocation = {tCurLZOrWZData[AiBotMap.subrefMidpoint][1], tCurLZOrWZData[AiBotMap.subrefMidpoint][2], tCurLZOrWZData[AiBotMap.subrefMidpoint][3]}
                                        AiBotOrders.IssueTrackedMove(oUnit, tHoldingLocation, 5,                   false,              'TrWtForE',            false)
                                        --Early game - Get the closest engineer in the zone that isn't loaded and isnt building a mex or building something that is nearly done, and clear its orders so it can be used
                                        if AiBotUtilities.IsTableEmpty(tEngineersInZone) == false and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] <= 1 and GetGameTimeSeconds() <= 600 then
                                            local oClosestEngineerInZone
                                            local iClosestEngineerInZoneDist = 10000
                                            local iCurDist
                                            for iEngineer, oEngineer in tEngineersInZone do
                                                if AiBotUnitInfo.IsUnitValid(oEngineer) and oEngineer:GetFractionComplete() == 1 and not(oEngineer:IsUnitState('Attached')) and not(oEngineer:IsUnitState('Capturing')) and not(oEngineer[AiBotUnitInfo.refbSpecialMicroActive]) and (not(iMinUnitTechLevel) or AiBotUnitInfo.GetUnitTechLevel(oEngineer) >= iMinUnitTechLevel) and not(oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionBuildMex) and (not(oEngineer[AiBotEngineer.refbPrimaryBuilder]) or not(oEngineer:GetWorkProgress() >= 0.8)) and not(oEngineer[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionLoadOntoTransport) then
                                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEngineer:GetPosition(), oUnit:GetPosition())
                                                    if iCurDist < iClosestEngineerInZoneDist then
                                                        iClosestEngineerInZoneDist = iCurDist
                                                        oClosestEngineerInZone = oEngineer
                                                    end
                                                end
                                            end
                                            if bDebugMessages == true then
                                                LOG(sFunctionRef..': Will clear an engineer in the zone so it can be made available for the transport, oClosestEngineerInZone='..(oClosestEngineerInZone.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestEngineerInZone) or 'nil')..'; iClosestEngineerInZoneDist='..iClosestEngineerInZoneDist..'; Time='..GetGameTimeSeconds())
                                                if oClosestEngineerInZone then LOG(sFunctionRef..': oClosestEngineerInZone unit state='..AiBotUnitInfo.GetUnitState(oClosestEngineerInZone)..'; refbSpecialMicroActive='..tostring(oClosestEngineerInZone[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                                            end
                                            if oClosestEngineerInZone then
                                                AiBotOrders.IssueTrackedClearCommands(oClosestEngineerInZone)
                                                if bDebugMessages == true then LOG(sFunctionRef..': Is this engineer considered available post-clearing='..tostring(AiBotConditions.IsEngineerAvailable(oClosestEngineerInZone, true))) end
                                            end
                                        end
                                    end
                                end

                                --However, want to record that we are waiting for an engineer if not already recorded
                                local bRecordAgainstLZ = true
                                if AiBotUtilities.IsTableEmpty(tCurLZOrWZTeamData[AiBotMap.reftoTransportsWaitingForUnits]) == false then
                                    for iRecordedTransport, oRecordedTransport in tCurLZOrWZTeamData[AiBotMap.reftoTransportsWaitingForUnits] do
                                        if oRecordedTransport == oUnit then
                                            bRecordAgainstLZ = false
                                        end
                                    end
                                end
                                if bRecordAgainstLZ then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding transport as waiting for units against cur LZ or WZ team data, EngisWnated='..(oUnit[refiEngisWanted] or 'nil')..'; refiCombatUnitsWanted='..(oUnit[refiCombatUnitsWanted] or 'nil')..'; CombatDrop='..tostring(oUnit[refbCombatDrop] or false)) end
                                    table.insert(tCurLZOrWZTeamData[AiBotMap.reftoTransportsWaitingForUnits], oUnit)
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Transport is in core base iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurLandOrWaterZone='..(iCurLandOrWaterZone or 'nil')..'; is table of transports waiting for engineers empty='..tostring(AiBotUtilities.IsTableEmpty(tCurLZOrWZTeamData[AiBotMap.reftoTransportsWaitingForUnits]))) end
                            else
                                --Want engineers, but not on core base, so move to core base
                                if AiBotUtilities.IsTableEmpty(tCurLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]) then AiBotUtilities.ErrorHandler('Dont have a closest friendly base for iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurLandOrWaterZone='..(iCurLandOrWaterZone or 'nil')) end
                                if bDebugMessages == true then LOG(sFunctionRef..': Transport '..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..' wants engineers but not in core base so will move there iCurPlateauOrZero='..(iCurPlateauOrZero or 'nil')..'; iCurLandOrWaterZone='..(iCurLandOrWaterZone or 'nil')..'; Is transport valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; tCurLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase]='..repru(tCurLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])..'; Unit last order position='..repru(oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]][AiBotOrders.subreftOrderPosition])) end
                                --IssueTrackedMove(oUnit, tOrderPosition,                           iDistanceToReissueOrder, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
                                AiBotOrders.IssueTrackedMove(oUnit, tCurLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase], 10,                   false,              'TWntE',            false)

                            end
                        end
                    else
                        oUnit[refiEngisWanted] = 0
                        oUnit[refiCombatUnitsWanted] = nil
                    end
                    if not(bGetMoreUnits) then
                        oUnit[refiTransportTimeSpentWaiting] = 0
                        --Have enough engineers (or arent on core lZ so dont want to delay by going back for more) - unload at the target land zone
                        oUnit[refiTargetPlateauForDrop] = iPlateauToTravelTo
                        oUnit[refiTargetIslandForDrop] = iIslandToTravelTo
                        oUnit[refiTargetZoneForDrop] = iLandZoneToTravelTo or iWaterZoneToTravelTo --must set before calling the transportunload order
                        AiBotOrders.IssueTrackedTransportUnload(oUnit, tLZOrWZData[AiBotMap.subrefMidpoint], 10, false, 'TRLZUnlP'..(iPlateauToTravelTo or 'x')..'I'..(iIslandToTravelTo or 0)..'Z'..(iLandZoneToTravelTo or iWaterZoneToTravelTo), false)
                        --Set this as an expansion zone if it is in same isalnd (as normal logic wont flag it as an expansion)
                        if bDebugMessages == true then
                            LOG(sFunctionRef..': Just tried to send order for transport to go to iIslandToTravelTo='..iIslandToTravelTo..'; iLandZoneToTravelTo='..iLandZoneToTravelTo..'; LZ midpoint='..repru(tLZOrWZData[AiBotMap.subrefMidpoint]))
                        end
                        local tTargetLZData =  AiBotMap.tAllPlateaus[iPlateauToTravelTo][AiBotMap.subrefPlateauLandZones][iLandZoneToTravelTo]
                        local tLZTeamData = tTargetLZData[AiBotMap.subrefLZTeamData][iTeam]
                        if bTravelToSameIsland and tLZTeamData then
                            if not(tLZTeamData[AiBotMap.subrefLZCoreExpansion]) and (tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] >= 3 or (AiBotMap.bIsCampaignMap and (AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subreftoUnitsToRepair]) == false or AiBotUtilities.IsTableEmpty(tLZOrWZData[AiBotMap.subreftoUnitsToCapture]) == false))) then
                                tLZTeamData[AiBotMap.subrefLZExpansionOverride] = true
                            end
                        end

                        --Also set expansion flag for 1-2 mex land zone locations where we are dropping engineers if not many mexes on map and it's not too close to enemy (so not just throwing away mass by trying to fortify more)
                        if tLZTeamData and not(tLZTeamData[AiBotMap.subrefLZExpansionOverride]) and (tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] or 0) >= 1 and tLZOrWZData[AiBotMap.refiModDistancePercent] <= 0.6 then
                            --Decide if we want to treat a low mex location as still valuable - consider for lowish mex maps
                            local iMapMexCount = table.getn(AiBotMap.tMassPoints)
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to also set expansion override for P'..iPlateauToTravelTo..'; iIslandToTravelTo='..iIslandToTravelTo..'; iLandZoneToTravelTo='..(iLandZoneToTravelTo or 'nil')..'; iMapMexCount='..iMapMexCount..'; Players at game tsart='..AiBotTeam.iPlayersAtGameStart..'; Island mex count='..(AiBotMap.tAllPlateaus[iPlateauToTravelTo][AiBotMap.subrefPlateauIslandMexCount][iIslandToTravelTo] or 0)) end
                            if iMapMexCount / AiBotTeam.iPlayersAtGameStart <= 13 then --13 or less mexes per player, so 2 mex islands will be of more value
                                if (tLZOrWZData[AiBotMap.subrefLZOrWZMexCount] >= 2 or AiBotMap.tAllPlateaus[iPlateauToTravelTo][AiBotMap.subrefPlateauIslandMexCount][iIslandToTravelTo] or 0) >= 2 then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Setting expansion override flag to true') end
                                    tLZTeamData[AiBotMap.subrefLZExpansionOverride] = true
                                end
                            end
                        end

                        --Remove this location from the shortlist
                        if oUnit[refbCombatDrop] then
                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportCombatPlateauLandZoneDropShortlist]) == false then --redundancy
                                for iEntry, tiPlateauAndLandZone in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportCombatPlateauLandZoneDropShortlist] do
                                    if tiPlateauAndLandZone[2] == iLandZoneToTravelTo and tiPlateauAndLandZone[1] == iPlateauToTravelTo then
                                        table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportCombatPlateauLandZoneDropShortlist], iEntry)
                                        break
                                    end
                                end
                            end
                        elseif bTravelToSameIsland then
                            for iEntry, tiPlateauAndLandZone in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportFarAwaySameIslandPlateauLandZoneDropShortlist] do
                                if tiPlateauAndLandZone[2] == iLandZoneToTravelTo then
                                    table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportFarAwaySameIslandPlateauLandZoneDropShortlist], iEntry)
                                    break
                                end
                            end
                        elseif bIsEngiSupportDrop then
                            RemoveDropFromShortlist(iPlateauToTravelTo, iIslandToTravelTo, iLandZoneToTravelTo)
                        else
                            for iEntry, tiPlateauAndIsland in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportIslandDropShortlist] do
                                if tiPlateauAndIsland[1] == iPlateauToTravelTo and tiPlateauAndIsland[2] == iIslandToTravelTo then
                                    table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftTransportIslandDropShortlist], iEntry)
                                    break
                                end
                            end
                        end
                    end

                else
                    if bDebugMessages == true then LOG(sFunctionRef..': We dont have island to travel to so unload unless transport already on its way and might be justified') end
                    --Do we have engineers loaded? if so then unload
                    local tCargo = oUnit:GetCargo()
                    if AiBotUtilities.IsTableEmpty(tCargo) == false then
                        --Consider proceeding
                        local tLastOrder = oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]]
                        if bDebugMessages == true then LOG(sFunctionRef..': Last order='..reprs(tLastOrder)..'; Is last order tyep unoad transport='..tostring(tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderUnloadTransport)) end

                        local bDropNow, bAlwaysDropAtTarget, bAbortDrop = ShouldTransportDropEarlyOrAlwaysDropAtTarget(oUnit, iTeam, true)
                        if bDropNow then
                            --For completeness - since adding logic earlier on to consider available transports in all cases for emergency drops where they have a cargo, this shouldn't ever trigger; have also added flag to considering whether to drop early so logic shouldn't even be run
                            AiBotOrders.IssueTrackedTransportUnload(oUnit, oUnit:GetPosition(), 8, false, 'EmergDr', false)
                            AiBotUtilities.ErrorHandler('Unexpected code event, likely overlooked something when changing code, will proceed with dropping early', true)
                        elseif not(bAlwaysDropAtTarget) then
                            --Consider dropping at rally point instead
                            --If far from rally then look for nearest zone to unload at
                            local iTransportPlateauOrZero, iTransportLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                            local tTransportLZOrWZData, tTransportLZOrWZTeamData
                            if iTransportLandOrWaterZone then
                                if iTransportPlateauOrZero == 0 then
                                    tTransportLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iTransportLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iTransportLandOrWaterZone]
                                    tTransportLZOrWZTeamData = tTransportLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                else
                                    tTransportLZOrWZData = AiBotMap.tAllPlateaus[iTransportPlateauOrZero][AiBotMap.subrefPlateauLandZones][iTransportLandOrWaterZone]
                                    tTransportLZOrWZTeamData = tTransportLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                end
                                if tTransportLZOrWZTeamData[AiBotMap.subrefLZbCoreBase] then
                                    AiBotOrders.IssueTrackedTransportUnload(oUnit, oUnit:GetPosition(), 10, false, 'TRUnlBas', false)
                                elseif AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tRallyPoint) <= 50 then
                                    AiBotOrders.IssueTrackedTransportUnload(oUnit, tRallyPoint, 10, false, 'TRUnlR', false)
                                else
                                    --Find the nearest zone wanting engineers (or unload at rally point if cant find any
                                    local tMidpointToUnloadAt
                                    RecordOtherLandAndWaterZonesByDistance(tTransportLZOrWZData)
                                    if AiBotUtilities.IsTableEmpty(tTransportLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                                        local tTargetLZOrWZData, tTargetLZOrWZTeamData
                                        for iEntry, tSubtable in tTransportLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                                            if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                                tTargetLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                                tTargetLZOrWZTeamData = tTargetLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]

                                            else
                                                tTargetLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                                tTargetLZOrWZTeamData = tTargetLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                            end
                                            if tTargetLZOrWZTeamData[AiBotMap.subrefTbWantBP] and (tTargetLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) <= 20 and AiBotUtilities.IsTableEmpty(tTargetLZOrWZTeamData[AiBotMap.reftoNearestCombatEnemies]) then
                                                tMidpointToUnloadAt = {tTargetLZOrWZData[AiBotMap.subrefMidpoint][1], tTargetLZOrWZData[AiBotMap.subrefMidpoint][2], tTargetLZOrWZData[AiBotMap.subrefMidpoint][3]}
                                                break
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': About to unload transport '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; tMidpointToUnloadAt='..repru(tMidpointToUnloadAt)..'; refbSpecialMicroActive='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
                                    if AiBotUtilities.IsTableEmpty(tMidpointToUnloadAt) == false then
                                        AiBotOrders.IssueTrackedTransportUnload(oUnit, tMidpointToUnloadAt, 10, false, 'TRUnlZ', false)
                                    else
                                        --No zones wanting engineers so unload at rally point
                                        AiBotOrders.IssueTrackedTransportUnload(oUnit, tRallyPoint, 10, false, 'TRUnlB1', false)
                                    end
                                end
                            end
                        else
                            if tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderUnloadTransport then
                                AiBotOrders.IssueTrackedTransportUnload(oUnit, tLastOrder[AiBotOrders.subreftOrderPosition], 10, false, 'TRUnlB2', false)
                            else
                                AiBotOrders.IssueTrackedTransportUnload(oUnit, tRallyPoint, 10, false, 'TRUnlB3', false)
                            end
                        end
                    else
                        --Go to rally point as have no cargo and nowhere we want to drop, and flag we no longer want units
                        oUnit[refbCombatDrop] = false
                        oUnit[refiEngisWanted] = 0
                        oUnit[refiCombatUnitsWanted] = 0
                        if bDebugMessages == true then LOG(sFunctionRef..': Sending transport to rally point and clearing units itw ants') end
                        AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 10, false, 'TIdle', false)
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': End of loop for this transport in available transports, refbCombatDrop='..tostring(oUnit[refbCombatDrop] or false)..'; refiEngisWanted='..(oUnit[refiEngisWanted] or 0)..'; refiCombatUnitsWanted='..(oUnit[refiCombatUnitsWanted] or 0)) end
            end
        end
    end
    if AiBotUtilities.IsTableEmpty(tTransportsForRefueling) == false then
        for iUnit, oUnit in tTransportsForRefueling do
            --confirm no cargo
            local tCargo = oUnit:GetCargo()
            if AiBotUtilities.IsTableEmpty(tCargo) == false then
                AiBotOrders.IssueTrackedTransportUnload(oUnit, tRallyPoint, 10, false, 'TRFalUnl', false)
            else
                if AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, oUnit:GetPosition()) <= 30 and (not(oUnit[AiBotUnitInfo.refbCampaignTriggerAdded]) or not(AiBotMap.bIsCampaignMap)) and not(EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId)) then --(exp exclusion is a redundancy, shoudlnt get to this point)
                    ForkThread(AiBotMicro.MoveAndKillAirUnit,oUnit)
                    --AiBotOrders.IssueTrackedKillUnit(oUnit)
                else
                    --Go to rally point
                    AiBotOrders.IssueTrackedMove(oUnit, tRallyPoint, 10, false, 'TIdle', false)
                end
            end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ShouldTransportDropEarlyOrAlwaysDropAtTarget(oUnit, iTeam, bJustConsiderAlwaysDropping)
    --Return bDropNow, bAlwaysDropAtTarget and bAbortDrop values (i.e. true if should drop now; false true if should proceed to target regardless since we are close; and false false if should either proceed with other logic such as retreating to rally (if no where to drop) or proceeding with the drop (if unit alreayd has drop order queued up and is close enough to be busy)
    --bJustConsiderAlwaysDropping - if this is true, then will only consider the distance based check for this - i.e. intended where we have already considered whether to dropnow for the unit

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ShouldTransportDropEarlyOrAlwaysDropAtTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local tLastOrder = oUnit[AiBotOrders.reftiLastOrders][oUnit[AiBotOrders.refiOrderCount]]
    if tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderUnloadTransport then
        --Consider dropping immediately due to enemy AirAA threat
        if not(bJustConsiderAlwaysDropping) then
            local tCurZoneData, tCurZoneTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
            if bDebugMessages == true then LOG(sFunctionRef..': Transport oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Transport health%='..AiBotUnitInfo.GetUnitHealthPercent(oUnit)..'; enemy AirAA threat in this zone='..(tCurZoneTeamData[AiBotMap.refiEnemyAirAAThreat] or 0)) end
            if (tCurZoneTeamData[AiBotMap.refiEnemyAirAAThreat] or 0) > 0 and (NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition()) or 0) > 0 and AiBotUtilities.IsTableEmpty(tCurZoneTeamData[AiBotMap.reftLZEnemyAirUnits]) == false then
                local iAirAAThreshold = math.max(10, ((oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) - 60) * 0.3 * AiBotUnitInfo.GetUnitHealthPercent(oUnit))
                if tCurZoneTeamData[AiBotMap.refiEnemyAirAAThreat] > iAirAAThreshold then

                    --Check for nearby enemy airaa units by distance
                    local iClosestEnemyAirAA = 10000
                    local iDistanceThreshold = 10
                    local iAirAAWithinThresholdMassValue = 0
                    local iCurDist
                    for iEnemy, oEnemy in tCurZoneTeamData[AiBotMap.reftLZEnemyAirUnits] do
                        if AiBotUnitInfo.IsUnitValid(oEnemy) and EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA, oEnemy.UnitId) and oEnemy:GetFractionComplete() == 1 then
                            --Is enemy off the ground?
                            if oEnemy:IsUnitState('Moving') or (not(oEnemy:IsUnitState('Attached')) and oEnemy:GetPosition()[2] - GetTerrainHeight(oEnemy:GetPosition()[1], oEnemy:GetPosition()[3]) >= 2) then
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oEnemy:GetPosition(), oUnit:GetPosition()) - (oEnemy[AiBotUnitInfo.refiAARange] or 20)
                                if iCurDist < iClosestEnemyAirAA then
                                    iClosestEnemyAirAA = iCurDist
                                end
                                if iCurDist <= iDistanceThreshold then
                                    iAirAAWithinThresholdMassValue = iAirAAWithinThresholdMassValue + (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit))
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Will consider dropping transport early, special micro active='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive])..'; Dist to cur unload destination='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLastOrder[AiBotOrders.subreftOrderPosition])..'; Last order detsination pre update='..repru(tLastOrder[AiBotOrders.subreftOrderPosition])..'; iClosestEnemyAirAA='..iClosestEnemyAirAA..'; Unit position='..repru(oUnit:GetPosition())..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))..'; iAirAAWithinThresholdMassValue='..iAirAAWithinThresholdMassValue) end
                    if iClosestEnemyAirAA <= 10 and (iAirAAWithinThresholdMassValue >= 100 or AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= 0.7) then --i.e. air unit is 10 away from being in range of us (or less)
                        --If combat drop then require us to be dropping on land
                        if (NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition()) or 0) > 0 and (not(oUnit[refbCombatDrop]) or not(AiBotMap.IsUnderwater({oUnit:GetPosition()[1], GetTerrainHeight(oUnit:GetPosition()[1], oUnit:GetPosition()[3]), oUnit:GetPosition()[3]}))) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Dropping early as enemy has AirAA') end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return true, false, false
                        end
                    end
                end
            end
        end
        --We arent worried about a nearby AirAA threat; what about groundAA threat?
        local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tLastOrder[AiBotOrders.subreftOrderPosition])
        if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to drop due to target being dangerous, iDistToTarget='..iDistToTarget) end
        if AiBotUnitInfo.GetUnitHealthPercent(oUnit) <= 0.35 and (iDistToTarget <= 50 or oUnit[refbCombatDrop]) and GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeLastDamaged] or 0) <= 8 then
            if bDebugMessages == true then LOG(sFunctionRef..': Transport is low health so want to drop immediately unless it isnt likely to be a valid drop location') end
            if (NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition()) or 0) > 0 and (not(oUnit[refbCombatDrop]) or GetTerrainHeight(oUnit:GetPosition()[1], oUnit:GetPosition()[3]) >= AiBotMap.iMapWaterHeight) then
                if bDebugMessages == true then LOG(sFunctionRef..': Will drop early (i.e. where we are)') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return true, false, false
            elseif iDistToTarget <= 40 then
                if bDebugMessages == true then LOG(sFunctionRef..': Target within 40 so will proceed to drop') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return false, true, false --i.e. carry on to destination
            else
                if bDebugMessages == true then LOG(sFunctionRef..': Returning false') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return false, false, false --i.e. consider retreating or changing targets if called this as part of retreat to rally logic, but dont force an abort
            end

        else
            local tTargetLZOrWZData, tTargetLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(tLastOrder[AiBotOrders.subreftOrderPosition], true, iTeam)
            --Engineer drop where enemies are at the target
            if bDebugMessages == true then LOG(sFunctionRef..': Enemy combat in target LZ='..(tTargetLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)..'; Friendly threat='..(tTargetLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)..'; Is table of nearest DF enemies empty='..tostring(AiBotUtilities.IsTableEmpty(tTargetLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]))) end
            if not(oUnit[refbCombatDrop]) and not(tTargetLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and not(tTargetLZOrWZTeamData[AiBotMap.subrefWZbCoreBase]) and (tTargetLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) > 50 and (tTargetLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) < 50 and AiBotUtilities.IsTableEmpty(tTargetLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies]) == false then
                --Check for enemies near the drop location specifically that have a DF attack
                local iDistUntilInRange
                for iEnemy, oEnemy in tTargetLZOrWZTeamData[AiBotMap.reftoNearestDFEnemies] do
                    if not(oEnemy.Dead) and oEnemy:GetFractionComplete() >= 0.8 then
                        iDistUntilInRange = AiBotUtilities.GetDistanceBetweenPositions(tLastOrder[AiBotOrders.subreftOrderPosition], oEnemy:GetPosition()) - (oEnemy[AiBotUnitInfo.refiDFRange] or 0)
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy '..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)..'; iDistUntilInRange='..iDistUntilInRange) end
                        if iDistUntilInRange <= 18 and (iDistUntilInRange <= 8 or EntityCategoryContains(categories.MOBILE, oEnemy.UnitId)) then
                            if bDebugMessages == true then LOG(sFunctionRef..': If we drop as planned we will probaboy just die to enemy so will abort') end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return false, false, true --i.e. want to abort and pick a different target/retreat
                        end
                    end
                end
            end
            --Further check if we are almost there - no tanks or ACUs doing getunitsaroundpoint (since there might be a delay in updating units)
            if iDistToTarget <= 5 and not(oUnit[refbCombatDrop]) and not(tTargetLZOrWZTeamData[AiBotMap.subrefLZbCoreBase]) and not(tTargetLZOrWZTeamData[AiBotMap.subrefWZbCoreBase]) then
                local tEnemyUnits = oUnit:GetAIBrain():GetUnitsAroundPoint(categories.COMMAND + AiBotUnitInfo.refCategoryPD + AiBotUnitInfo.refCategoryMobileDFLand, tLastOrder[AiBotOrders.subreftOrderPosition], 35, 'Enemy')
                if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyUnits))) end
                if AiBotUtilities.IsTableEmpty(tEnemyUnits) == false then
                    for iEnemy, oEnemy in tEnemyUnits do
                        if oEnemy:GetFractionComplete() >= 0.8 then
                            if bDebugMessages == true then LOG(sFunctionRef..': Detected enemy, oEnemy='..oEnemy.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemy)) end
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            return false, false, true --i.e. want to abort and pick a different target/retreat
                        end
                    end
                end
            end

            if iDistToTarget <= 30 or (iDistToTarget <= 60 and oUnit[refbCombatDrop]) then
                --Might as well proceed to destination and unload - significant risk we just die if we return by this stage anyway, while a combat drop loses its effectiveness if keep changing our mind
                if bDebugMessages == true then LOG(sFunctionRef..': Will proceed to destination as we are close to it now') end
                AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                return false, true, false
            elseif iDistToTarget <= 250 then
                local tCargo = oUnit:GetCargo()
                local iCargoSize = table.getn(tCargo)
                if bDebugMessages == true then LOG(sFunctionRef..': Will cnosider proceeding to destination, tTargetLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]='..(tTargetLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 'nil')..'; oUnit[refbCombatDrop]='..tostring(oUnit[refbCombatDrop] or false)) end
                if (tTargetLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) - (tTargetLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) < iCargoSize * 30 or oUnit[refbCombatDrop] then
                    --Might as well proceed to destination and unload given minimal enemy combat threat
                    if bDebugMessages == true then LOG(sFunctionRef..': Minimal combat threat so will proceed to destination') end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    return false, true, false
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iCargoSize='..iCargoSize..'; Enemy combat threat='..tTargetLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; bUnloadAtRallyOrOtherZone='..tostring(bUnloadAtRallyOrOtherZone)) end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return false, false, false
end

function ManageNovax(iTeam, iAirSubteam)
    --Wont bother with normal air availability since arent interested in fuel or health
    local iPlateauOrZero, iLandOrWaterZone
    for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
        if oBrain.AiBotAI then
            local tCurUnits = oBrain:GetListOfUnits(AiBotUnitInfo.refCategorySatellite, false, true)
            for iUnit, oUnit in tCurUnits do
                if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:GetFractionComplete() >= 1 then
                    --Refresh positions of enemies in the zone the novax is in
                    iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                    local tLZOrWZTeamData
                    if iLandOrWaterZone > 0 then
                        if iPlateauOrZero == 0 then
                            --Water zone
                            tLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][iTeam]
                            if GetGameTimeSeconds() - (tLZOrWZTeamData[AiBotMap.subrefiTimeOfLastEnemyUnitPosUpdate] or -100) >= 2 then
                                --UpdateUnitPositionsAndWaterZone(aiBrain, tUnits,                              iTeam, iRecordedWaterZone, bUseLastKnownPosition, bAreAirUnits, tWZTeamData, bUpdateTimeOfLastEnemyPositionCheck, bAreEnemyUnits)
                                AiBotNavy.UpdateUnitPositionsAndWaterZone(oBrain, tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits], iTeam, iLandOrWaterZone, false,                  false,      tLZOrWZTeamData, true,                              true)
                            end
                        else
                            tLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
                            if GetGameTimeSeconds() - (tLZOrWZTeamData[AiBotMap.subrefiTimeOfLastEnemyUnitPosUpdate] or -100) >= 2 then
                                --UpdateUnitPositionsAndLandZone(aiBrain, tUnits,                                  iTeam, iRecordedPlateau, iRecordedLandZone, bUseLastKnownPosition, bAreAirUnits, tLZTeamData, bUpdateTimeOfLastEnemyPositionCheck, bAreEnemyUnits)
                                AiBotLand.UpdateUnitPositionsAndLandZone(oBrain, tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits], iTeam, iPlateauOrZero, iLandOrWaterZone, false,                   false, tLZOrWZTeamData,     true,                                   true)
                            end
                        end
                    end
                    ForkThread(NovaxCoreTargetLoop, oBrain, oUnit)
                end
            end
        end
    end
end

function NovaxCoreTargetLoop(aiBrain, oNovax, bCalledFromUnitDeath)
    --Used so can do forkthread of this in case come across errors
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'NovaxCoreTargetLoop'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if AiBotUnitInfo.IsUnitValid(oNovax) then

        --If called from a unit dying only get a new target if the novax has an attack order on a unit
        local bGetNewTarget = true
        if bCalledFromUnitDeath and oNovax[AiBotOrders.refiOrderCount] > 0 then
            bGetNewTarget = false
            local tLastOrder = oNovax[AiBotOrders.reftiLastOrders][oNovax[AiBotOrders.refiOrderCount]]
            if tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack then
                bGetNewTarget = true
            end
        end
        if bGetNewTarget then

            local iEffectiveRange = math.max(20, oNovax:GetBlueprint().Weapon[1].MaxRadius) + 10
            local oTarget

            local iOrderType
            local refiLastIssuedOrderType = 'AiBotNovaxLastOrderType'
            local refoLastIssuedOrderUnit = 'AiBotNovaxLastOrderUnit'
            local reftLastIssuedOrderLocation = 'AiBotNovaxLastOrderLocation'
            local refOrderAttack = 1
            local refOrderMove = 2
            oTarget = GetNovaxTarget(aiBrain, oNovax)
            oNovax[refoNovaxLastTarget] = oTarget
            if oTarget then
                if bDebugMessages == true then
                    LOG(sFunctionRef .. ': GameTime='..GetGameTimeSeconds()..'; Have a target ' .. oTarget.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oTarget) .. '; will decide whether to attack or move to it; Distance to target=' .. AiBotUtilities.GetDistanceBetweenPositions(oTarget:GetPosition(), oNovax:GetPosition()))
                end
                if AiBotUtilities.GetDistanceBetweenPositions(oTarget:GetPosition(), oNovax:GetPosition()) > iEffectiveRange then
                    iOrderType = refOrderMove
                else
                    iOrderType = refOrderAttack
                end

                if iOrderType == refOrderMove then
                    AiBotOrders.IssueTrackedMove(oNovax, oTarget:GetPosition(), 8, false, 'NVMv', false)
                else
                    AiBotOrders.IssueTrackedAttack(oNovax, oTarget, false, 'NVAtc', false)
                end
            else
                if bDebugMessages == true then LOG(sFunctionRef .. ': No target so move to enemy base') end

                --No target so move towards enemy base
                AiBotOrders.IssueTrackedMove(oNovax, AiBotMap.GetPrimaryEnemyBaseLocation(aiBrain), 8, false, 'NVBsMv', false)
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetEnemyUnitsInCurrentAndAdjacentZonesOfCategory(iStartPlateauOrZero, tStartLZOrWZData, tStartLZOrWZTeamData, iTeam, iOptionalCategory)
    --iOptionalCategoyr - if nil will just return all units
    local tUnitsOfCategory = {}
    function AddUnitsFromZoneTeamData(tLZOrWZTeamData)
        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
            local tZoneUnitsOfCategory
            if iOptionalCategory then tZoneUnitsOfCategory = EntityCategoryFilterDown(iOptionalCategory, tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])
            else tZoneUnitsOfCategory = tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]
            end
            if AiBotUtilities.IsTableEmpty(tZoneUnitsOfCategory) == false then
                for iUnit, oUnit in tZoneUnitsOfCategory do
                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                        table.insert(tUnitsOfCategory, oUnit)
                    end
                end
            end
        end
    end
    AddUnitsFromZoneTeamData(tStartLZOrWZTeamData)
    if iStartPlateauOrZero == 0 then
        if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefAdjacentLandZones]) == false then
            for iEntry, tSubtable in tStartLZOrWZData[AiBotMap.subrefAdjacentLandZones] do
                AddUnitsFromZoneTeamData(AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefWPlatAndLZNumber][1]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefWPlatAndLZNumber][2]][AiBotMap.subrefLZTeamData][iTeam])
            end
        end
        if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefWZAdjacentWaterZones]) == false then
            for iEntry, iWaterZone in tStartLZOrWZData[AiBotMap.subrefWZAdjacentWaterZones] do
                AddUnitsFromZoneTeamData(AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone][AiBotMap.subrefWZTeamData][iTeam])
            end
        end
    else
        --Dealing with land zone
        if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
            for iEntry, iLandZone in tStartLZOrWZData[AiBotMap.subrefLZAdjacentLandZones] do
                AddUnitsFromZoneTeamData(AiBotMap.tAllPlateaus[iStartPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam])
            end
        end
        if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefAdjacentWaterZones]) == false then
            for iEntry, tSubtable in tStartLZOrWZData[AiBotMap.subrefAdjacentWaterZones] do
                AddUnitsFromZoneTeamData(AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[tSubtable[AiBotMap.subrefAWZRef]]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefAWZRef]][AiBotMap.subrefWZTeamData][iTeam])
            end
        end
    end
    return tUnitsOfCategory
end

function GetNovaxTarget(aiBrain, oNovax)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetNovaxTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local oTarget
    local iTeam = aiBrain.AiBotTeam
    local iStartPlateauOrZero, iStartLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oNovax:GetPosition())
    local tStartLZOrWZData
    local tStartLZOrWZTeamData
    if iStartPlateauOrZero == 0 then
        tStartLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iStartLandOrWaterZone]
        tStartLZOrWZTeamData = tStartLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
    else
        tStartLZOrWZData =  AiBotMap.tAllPlateaus[iStartPlateauOrZero][AiBotMap.subrefPlateauLandZones][iStartLandOrWaterZone]
        tStartLZOrWZTeamData = tStartLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
    end

    --Get list of significant enemy shielding (will ignore targets under these shields)
    local iMediumSearchRange = 53 --Omni range is 60, so getunitsaroundpoint baed on this range should be fine; means we wont pickup all nearby enemy shields, but should still do ok
    local iShortSearchRange = 32 --ragne of novax laser
    local tNearbyEnemyShields = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryShieldBoat + AiBotUnitInfo.refCategoryMobileLandShield * categories.TECH3 - AiBotUnitInfo.refCategoryFatboy, oNovax:GetPosition(), iMediumSearchRange + 60, 'Enemy') --shield boats have a size of 120 so a radius of 60, so want to include max enemy search range (iMediumSearchRange) plus this, to make sure all shields are taken into account
    --tNearbyEnemyShields = GetEnemyUnitsInCurrentAndAdjacentZonesOfCategory(iStartPlateauOrZero, tStartLZOrWZData, tStartLZOrWZTeamData, iTeam, AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryShieldBoat + AiBotUnitInfo.refCategoryMobileLandShield * categories.TECH3)
    local tNotLowHealthNearbyShields = {}
    local tMobileShieldsToCheck = {}
    local tNearbyNovax = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategorySatellite, oNovax:GetPosition(), 30, 'Ally')
    local iNearbyNovax = table.getn(tNearbyNovax)
    local iShieldHealthThreshold = 3000 * iNearbyNovax
    if AiBotUtilities.IsTableEmpty(tNearbyEnemyShields) == false then
        local iCurShield, iMaxShield
        for iUnit, oUnit in tNearbyEnemyShields do
            iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit, false)
            if iCurShield >= iShieldHealthThreshold and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) then
                table.insert(tNotLowHealthNearbyShields, oUnit)
                if EntityCategoryContains(categories.MOBILE, oUnit.UnitId) then
                    table.insert(tMobileShieldsToCheck, oUnit)
                end
            end

        end
    end
    local bHaveShieldsToCheck = not(AiBotUtilities.IsTableEmpty(tNotLowHealthNearbyShields))

    function DoShieldsCoverUnit(oTargetUnit, oOptionalShieldToIgnore, bUseDetailedShieldCheck, iOptionalThresholdOverride)
        local tPosition = oTargetUnit:GetPosition()
        if bUseDetailedShieldCheck or EntityCategoryContains(AiBotUnitInfo.refCategoryStructure - AiBotUnitInfo.refCategoryFixedShield, oTargetUnit.UnitId) then
            local bUnderFixedShield = AiBotLogic.IsTargetUnderShield(aiBrain, oTargetUnit, iOptionalThresholdOverride or iShieldHealthThreshold, false, true, false, true)
            if bDebugMessages == true then LOG(sFunctionRef..': Will use istargetundershield function for this unit, bUnderFixedShield='..tostring(bUnderFixedShield or false)) end
            if bUnderFixedShield then
                return true
            elseif AiBotUtilities.IsTableEmpty(tMobileShieldsToCheck) == false then
                for iUnit, oUnit in tMobileShieldsToCheck do
                    if AiBotUtilities.GetDistanceBetweenPositions(tPosition, oUnit:GetPosition()) <= oUnit:GetBlueprint().Defense.Shield.ShieldSize * 0.5 then
                        return true
                    end
                end
            end
        elseif bHaveShieldsToCheck then
            for iUnit, oUnit in tNotLowHealthNearbyShields do
                if not(oUnit == oOptionalShieldToIgnore) then
                    if AiBotUtilities.GetDistanceBetweenPositions(tPosition, oUnit:GetPosition()) <= oUnit:GetBlueprint().Defense.Shield.ShieldSize * 0.5 then
                        return true
                    end
                end
            end
        end
        return false
    end

    --Check for priority override (but still consider shields and ACU even if have a priority target)
    if bDebugMessages == true then LOG(sFunctionRef .. ': Time='..GetGameTimeSeconds()..'; Is there a valid target override set=' .. tostring(oNovax[refoPriorityTargetOverride]) .. '; Time since last override=' .. GetGameTimeSeconds() - (oNovax[refiTimeOfLastOverride] or -100)) end
    if AiBotUnitInfo.IsUnitValid(oNovax[refoPriorityTargetOverride]) and (GetGameTimeSeconds() - oNovax[refiTimeOfLastOverride]) <= 11 then

        --Are there any near-exposed shields nearby? Then target them instead

        if bDebugMessages == true then LOG(sFunctionRef .. ': is table of nearby shields empty=' .. tostring(AiBotUtilities.IsTableEmpty(tNearbyEnemyShields)) .. '; target subject to this=' .. oNovax[refoPriorityTargetOverride].UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oNovax[refoPriorityTargetOverride])) end
        if AiBotUtilities.IsTableEmpty(tNearbyEnemyShields) == false then
            local iCurShield, iMaxShield
            local iLowestShield = 4000 + 1000 * iNearbyNovax
            local iMaxShieldPercent = (0.3 + math.min(0.4, iNearbyNovax * 0.1))
            for iUnit, oUnit in tNearbyEnemyShields do
                iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit)
                if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to target enemy near-exposed shield, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurShield='..iCurShield..'; iMaxShield='..iMaxShield) end
                if iCurShield <= iLowestShield and iCurShield <= iMaxShield * iMaxShieldPercent then
                    if not (AiBotLogic.IsTargetUnderShield(aiBrain, oUnit, iLowestShield + 1,                     false,                      false,                  false)) then
                        oTarget = oUnit
                        iLowestShield = iCurShield
                        if bDebugMessages == true then LOG(sFunctionRef .. ': Nearby shield with low health, setting oTarget=' .. oTarget.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oTarget)) end
                    end
                end
            end
        end
        if not(oTarget) then
            --Is there an expoesd enemy ACU that we can kill instead?
            if ScenarioInfo.Options.Victory == "demoralization" then
                local iRange = math.max(20, oNovax:GetBlueprint().Weapon[1].MaxRadius)
                local tNearbyACUs = GetEnemyUnitsInCurrentAndAdjacentZonesOfCategory(iStartPlateauOrZero, tStartLZOrWZData, tStartLZOrWZTeamData, iTeam, categories.COMMAND)
                local iDPS = 243

                if AiBotUtilities.IsTableEmpty(tNearbyACUs) == false then
                    local iShortestTimeToKillTarget = 60 --Wont consider ACUs where will take more than this time to kill them
                    local iTimeToKillTarget
                    local iCurDPSMod = 0
                    for iACU, oACU in tNearbyACUs do
                        iTimeToKillTarget = 10000
                        if not(oACU:IsUnitState('Attached')) and not(AiBotMap.IsUnderwater(oACU:GetPosition())) then --Even if ACU slightly above water watn to ignore since it could probably easily get underwater
                            local iACUCurShield, iACUMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oACU)
                            iCurDPSMod = -AiBotUnitInfo.GetACUShieldRegenRate(oACU) - AiBotUnitInfo.GetUnitHealthRegenRate(oACU)
                            local iACUHealth = oACU:GetHealth() + iACUCurShield
                            if -iCurDPSMod < iCurDPSMod then
                                iTimeToKillTarget = iACUHealth / (iDPS + iCurDPSMod)
                                if iTimeToKillTarget > 0 and  iTimeToKillTarget < iShortestTimeToKillTarget then
                                    --Are there nearby shields?
                                    if not(DoShieldsCoverUnit(oACU, nil, true)) then
                                        iShortestTimeToKillTarget = iTimeToKillTarget
                                        oTarget = oACU
                                    end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': iShortestTimeToKillTarget='..iShortestTimeToKillTarget..'; is oTarget valid='..tostring(AiBotUnitInfo.IsUnitValid(oTarget))) end
                end
            end

            if not(oTarget) then
                --Target the priority override
                oTarget = oNovax[refoPriorityTargetOverride]
            end
        end
    end

    if not (oTarget) then
        --Normal targeting logic - see AiBot devlog and xls for logic behind some of this
        local iRange = math.max(20, oNovax:GetBlueprint().Weapon[1].MaxRadius)
        local iSpeed = oNovax:GetBlueprint().Physics.MaxSpeed
        local iTimeToTarget
        local iTimeToKillTarget
        local iDPS = 243
        local iCurDPSMod
        local iBestTargetValue = 105
        local iBestValueWithNoThreshold = 0
        local oBestTargetWithNoThreshold
        local iCurValue
        local iCategoriesToSearch
        local iMassFactor
        local iCurShield, iMaxShield
        local tPositionToSearchFrom = oNovax:GetPosition()
        local iNearestShield, iCurShieldDistance, iNearestWater, tPossiblePosition, tPossibleShields, iACUSpeed, iCurAmphibiousGroup

        local tEnemyUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileLand + AiBotUnitInfo.refCategoryNavalSurface + AiBotUnitInfo.refCategoryStructure, tPositionToSearchFrom, iMediumSearchRange, 'Enemy')
        if not(tEnemyUnits) then tEnemyUnits = {} end
        --GetEnemyUnitsInCurrentAndAdjacentZonesOfCategory(iStartPlateauOrZero, tStartLZOrWZData, tStartLZOrWZTeamData, iTeam, nil)
        local bIncreaseMAAWeighting = false
        if AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subrefiOurGunshipThreat] >= 5000 and not(AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbFarBehindOnAir]) and (AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.refbHaveAirControl] or AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.subrefiOurGunshipThreat] >= 30000) then bIncreaseMAAWeighting = true end
        function GetUnitTypeMassWeighting(oUnit)
            if EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield + AiBotUnitInfo.refCategoryMobileLandShield + AiBotUnitInfo.refCategoryShieldBoat, oUnit.UnitId) then
                return 4
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryT1Mex, oUnit.UnitId) then
                return 5
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryT2Mex, oUnit.UnitId) then
                return 2
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryT3Mex, oUnit.UnitId) then
                return 1.5
            elseif EntityCategoryContains(categories.COMMAND, oUnit.UnitId) and AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refbAssassinationOrSimilar] then
                return 3
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryVolatile * categories.STRUCTURE + AiBotUnitInfo.refCategoryVolatile * categories.LAND, oUnit.UnitId) and oUnit.GetFractionComplete and oUnit:GetFractionComplete() == 1 then
                return 2
                --Adjustments for certain categories to just bring them above iBestTargetValue starting threshold
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer, oUnit.UnitId) then
                return 1.35
            elseif bIncreaseMAAWeighting and EntityCategoryContains(AiBotUnitInfo.refCategoryGroundAA, oUnit.UnitId) then
                return 1.5
            elseif EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oUnit.UnitId) then
                if oUnit.MyShield.GetHealth and oUnit.MyShield:GetHealth() <= 3000 and oUnit:GetFractionComplete() >= 0.5 then
                    return 1.5
                else return 1.25
                end
            else
                return 1
            end
        end
        local oUnitBP
        --Add current target to enemy units to be considered if it's still valid (wont worry about duplication); originally was essential when doing the 'include adjacent zone units' approach, but now is more of a redundancy for if the novax moves just too far away while circling a target
        if bDebugMessages == true then LOG(sFunctionRef..'; Considering if last novax target still valid, oNovax[refoNovaxLastTarget]='..(oNovax[refoNovaxLastTarget].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oNovax[refoNovaxLastTarget]) or 'nil')..'; Is valid='..tostring(AiBotUnitInfo.IsUnitValid(oNovax[refoNovaxLastTarget]))) end
        if AiBotUnitInfo.IsUnitValid(oNovax[refoNovaxLastTarget]) then table.insert(tEnemyUnits, oNovax[refoNovaxLastTarget]) end

        local iFractionComplete
        local toUnshieldedNearbyFixedShields = {}
        for iUnit, oUnit in tEnemyUnits do
            --Ignore units that are mobile and attached, or underwater
            if bDebugMessages == true then LOG(sFunctionRef .. ': Considering enemy unit ' .. oUnit.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oUnit) .. '; Unit state=' .. AiBotUnitInfo.GetUnitState(oUnit) .. '; Does it contain mobile category=' .. tostring(EntityCategoryContains(categories.MOBILE, oUnit.UnitId)) .. '; is it underwater=' .. tostring(AiBotUnitInfo.IsUnitUnderwater(oUnit)) .. '; Is it under shield=' .. tostring(DoShieldsCoverUnit(oUnit, oUnit))..'; Unti AIBrain owner='..oUnit:GetAIBrain().Nickname..' with index '..oUnit:GetAIBrain():GetArmyIndex()..'; Dist to unit='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNovax:GetPosition())..'; Fraction complete='..oUnit:GetFractionComplete()..'; Under construction shield condition='..tostring(iFractionComplete > 0.35 and oUnitBP.Defense.Shield.ShieldMaxHealth and oUnitBP.Defense.Shield.ShieldMaxHealth >= 10000 and oUnit:GetHealth() <= 500 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNovax:GetPosition()) <= iShortSearchRange)) end
            if not (oUnit:IsUnitState('Attached') and EntityCategoryContains(categories.MOBILE, oUnit.UnitId)) and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) then
                --Ignore units that are shielded
                if not (DoShieldsCoverUnit(oUnit, oUnit)) or (EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oUnit.UnitId) and (oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1] or 0) > 0 and (AiBotMap.tAllPlateaus[oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]][AiBotMap.subrefPlateauLandZones][oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]][AiBotMap.subrefLZTeamData][iTeam][AiBotMap.subrefThreatEnemyShield] or 0) == 0 and not(DoShieldsCoverUnit(oUnit, oUnit, true, math.max(iShieldHealthThreshold + 1000, iShieldHealthThreshold * 1.3)))) then
                    iMassFactor = GetUnitTypeMassWeighting(oUnit)
                    oUnitBP = oUnit:GetBlueprint()
                    iCurDPSMod = 0
                    iCurValue = (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) * iMassFactor
                    iFractionComplete = oUnit:GetFractionComplete()
                    if iFractionComplete < 0.9 then
                        if iFractionComplete < 0.15 or not((EntityCategoryContains(AiBotUnitInfo.refCategoryAllShieldUnits, oUnit.UnitId) or (oUnit.MyShield and not(AiBotUtilities.bFAFActive)))) then
                            iCurValue = iCurValue * iFractionComplete
                            if oUnitBP.Defense.Shield.ShieldMaxHealth and oUnitBP.Defense.Shield.ShieldMaxHealth >= 10000 and oUnit:GetHealth() <= 500 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNovax:GetPosition()) <= iShortSearchRange then
                                iCurValue = iCurValue * 3 --still want slight increase in value of part-complete shield even if low completion %
                            end
                            --Under construction shield that is nearing completion and is in range of novax - massively increase value (to avoid e.g. prioritising a different unit such as damaged t3 arti when enemy shield if built will prevent us damaging it as well)
                        elseif iFractionComplete > 0.25 and oUnitBP.Defense.Shield.ShieldMaxHealth and oUnitBP.Defense.Shield.ShieldMaxHealth >= 10000 and oUnit:GetHealth() <= 500 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNovax:GetPosition()) <= iShortSearchRange then
                            if bDebugMessages == true then LOG(sFunctionRef..': Massively increasing value of under construction shield t hat is in our range') end
                            iCurValue = iCurValue * 10
                        end
                    end
                    if oUnitBP.Defense.Shield and AiBotUnitInfo.IsUnitShieldEnabled(oUnit) then
                        if oUnit.MyShield.GetHealth and oUnit.MyShield:GetHealth() > 0 then
                            iCurDPSMod = oUnitBP.Defense.Shield.ShieldRegenRate
                            if not (iCurDPSMod) then
                                if EntityCategoryContains(categories.COMMAND + categories.SUBCOMMANDER, oUnit.UnitId) then
                                    iCurDPSMod = AiBotUnitInfo.GetACUShieldRegenRate(oUnit)
                                    if (iCurDPSMod or 0) == 0 then
                                        AiBotUtilities.ErrorHandler('For some reason the unit has a shield with health but no regen rate; oUnit=' .. oUnit.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oUnit), nil, true)
                                        iCurDPSMod = 0
                                    end
                                else
                                    AiBotUtilities.ErrorHandler('For some reason the unit has a shield with health but no regen rate; oUnit=' .. oUnit.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oUnit), nil, true)
                                    iCurDPSMod = 0
                                end
                            end
                        else
                            iCurDPSMod = 0
                        end
                    else
                        iCurDPSMod = 0
                    end
                    iCurDPSMod = iCurDPSMod + (oUnitBP.Defense.RegenRate or 0)
                    iTimeToTarget = math.max(0, AiBotUtilities.GetDistanceBetweenPositions(oNovax:GetPosition(), oUnit:GetPosition()) - iRange) / iSpeed
                    iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit)

                    if iMaxShield >= 6000 and iCurShield == 0 and oUnit:GetHealth() < 1000 then
                        if not(DoShieldsCoverUnit(oUnit, oUnit, true, 100)) then
                            table.insert(toUnshieldedNearbyFixedShields, oUnit)
                            iCurValue = iCurValue * 2
                        end
                    end

                    iTimeToKillTarget = (oUnit:GetHealth() + iCurShield + math.min(iMaxShield - iCurShield, iTimeToTarget * iCurDPSMod)) / math.max(0.001, iDPS - iCurDPSMod)
                    if iMaxShield == 0 and not (EntityCategoryContains(categories.COMMAND, oUnit.UnitId)) then
                        --If target is already in firing range then prioritise low health units; if its outside firing range then instead prioritise higher health units (that are worth a detour to kill)
                        if iTimeToTarget > 0 then
                            iCurValue = iCurValue * math.max(AiBotUnitInfo.GetUnitHealthPercent(oUnit), 0.25)
                        elseif oUnit:GetMaxHealth() >= 600 then
                            iCurValue = iCurValue * (1 + 0.2 * (1-AiBotUnitInfo.GetUnitHealthPercent(oUnit)))
                        end
                    end
                    iCurValue = iCurValue / math.max(1.5, iTimeToTarget * 0.9 + iTimeToKillTarget)


                    --Massively adjust mass factor if dealing with nearby ACU that can kill before it gets to safety
                    if iCategoriesToSearch == categories.COMMAND and (iTimeToTarget + iTimeToKillTarget) < 60 and (iMaxShield + oUnit:GetMaxHealth()) <= 25000 then
                        iACUSpeed = oUnitBP.Physics.MaxSpeed
                        --Get nearest shield
                        iNearestShield = 10000
                        tPossibleShields = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryFixedShield, oUnit:GetPosition(), 102, 'Enemy')
                        --Dont do mobile shields since risk thinking no mobile shields, then revealing them and aborting attack, then losing intle on the mobile shield and repeating attack; so better to just attack if there's a mobile shield
                        if AiBotUtilities.IsTableEmpty(tPossibleShields) == false then
                            for iShield, oShield in tPossibleShields do
                                iCurShieldDistance = AiBotUtilities.GetDistanceBetweenPositions(oShield:GetPosition(), oUnit:GetPosition()) - oShield:GetBlueprint().Defense.Shield.ShieldSize * 0.5
                                if iCurShieldDistance < iNearestShield then
                                    iNearestShield = iCurShieldDistance
                                end
                            end
                        end
                        --Could the ACU get under a shield before it dies?
                        if bDebugMessages == true then LOG(sFunctionRef .. ': Have a nearby ACU target, will consider if we can kill it before it gets to safety; iNearestShield=' .. iNearestShield .. '; iACUSpeed=' .. iACUSpeed) end
                        if iNearestShield / iACUSpeed > iTimeToKillTarget then

                            iNearestWater = nil
                            if iStartPlateauOrZero > 0 and AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefAdjacentWaterZones]) then
                                iNearestWater = 10000
                            else
                                --Where is the nearest water to the ACU
                                iCurAmphibiousGroup = NavUtils.GetLabel(AiBotMap.refPathingTypeAmphibious, oUnit:GetPosition())
                                for iDistance = 20, 100, 20 do
                                    for iAngle = 0, 315, 45 do
                                        tPossiblePosition = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iAngle, iDistance, true, false, true)
                                        tPossiblePosition[2] = GetTerrainHeight(tPossiblePosition[1], tPossiblePosition[3])
                                        if AiBotMap.IsUnderwater(tPossiblePosition) then
                                            --Can the enemy ACU path here?
                                            if NavUtils.GetLabel(AiBotMap.refPathingTypeAmphibious, tPossiblePosition) == iCurAmphibiousGroup then
                                                iNearestWater = iDistance
                                                break
                                            end
                                        end
                                    end
                                    if iNearestWater then
                                        break
                                    end
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef .. ': iNearestWater=' .. (iNearestWater or 'nil')) end
                            if (iNearestWater or 10000) / iACUSpeed > iTimeToKillTarget then
                                iCurValue = iCurValue * 30
                                if bDebugMessages == true then LOG(sFunctionRef .. ': Think we can kill the ACU so massively increasing the curvalue to ' .. iCurValue) end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef .. ' Unit ' .. oUnit.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oUnit) .. ' iCurValue=' .. iCurValue .. '; iTimeToTarget=' .. iTimeToTarget .. '; iTimeToKillTarget=' .. iTimeToKillTarget .. '; iCurShield=' .. iCurShield .. '; iMaxShield=' .. iMaxShield .. '; iCurDPSMod=' .. iCurDPSMod..'; Cur health='..oUnit:GetHealth()) end
                    if iCurValue > iBestTargetValue then
                        if bDebugMessages == true then LOG(sFunctionRef .. ': Have a new best target, iBestTargetValue=' .. iBestTargetValue .. '; Target=' .. oUnit.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                        iBestTargetValue = iCurValue
                        oTarget = oUnit
                    elseif not(oTarget) and iCurValue > iBestValueWithNoThreshold then
                        iBestValueWithNoThreshold = iCurValue
                        oBestTargetWithNoThreshold = oUnit
                    end
                elseif bDebugMessages == true then
                    LOG(sFunctionRef .. ': Target unit ' .. oUnit.UnitId .. AiBotUnitInfo.GetUnitLifetimeCount(oUnit) .. ' is underwater or under a shield')
                end
            end
        end
        if oTarget and AiBotUtilities.IsTableEmpty(toUnshieldedNearbyFixedShields) == false and not(oTarget.MyShield) then
            if bDebugMessages == true then LOG(sFunctionRef..': Considering switching from actual best target to a vulnerable nearby shield') end
            local iClosestShieldDist = 10000
            local iCurShieldDist
            for iUnit, oUnit in toUnshieldedNearbyFixedShields do
                iCurShieldDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNovax:GetPosition())
                if iCurShieldDist < iClosestShieldDist then
                    iClosestShieldDist = iCurShieldDist
                    oTarget = oUnit
                    if bDebugMessages == true then LOG(sFunctionRef..': Switching target to oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                end
            end
        end

        --If shields have recently dropped to T3 arti and the unit is far enough away that it wont have been considered from the above, then consider targeting (unless we are already targeting a fixed shield or ACU)
        local oNearestRecentlyFailedShield
        local iNearestRecentlyFailedShieldDist = 100000
        if (not(oTarget) or not(EntityCategoryContains(AiBotUnitInfo.refCategoryFixedShield + categories.COMMAND + AiBotUnitInfo.refCategoryGameEnder + AiBotUnitInfo.refCategoryFixedT3Arti, oTarget.UnitId))) then
            local tiUnitsToRemove = {}
            local iCurDist
            local bAdjustValueForDistance = false
            local bAssignedPriorityShield = false

            function ConsiderTableOfPriorityUnits(tTableOfUnits, iPriorityShieldSearchDist)
                for iUnit, oUnit in tTableOfUnits do
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering priority unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Health of shield='..oUnit.MyShield:GetHealth()..'; Dist to novax='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNovax:GetPosition())..'; Do shields cover this shield='..tostring((DoShieldsCoverUnit(oUnit, oUnit)))..'; iBestTargetValue='..iBestTargetValue) end
                    if oUnit.MyShield.GetHealth and oUnit.MyShield:GetHealth() >= 3000 then
                        table.insert(tiUnitsToRemove, iUnit)
                    elseif oUnit:GetFractionComplete() == 1 then
                        --Is the unit outside of the search range from above, but still close enoguh that we want to consider?
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNovax:GetPosition())
                        if iCurDist < iNearestRecentlyFailedShieldDist then--and oUnit.MyShield:GetHealth() == 1 then
                            iNearestRecentlyFailedShieldDist = iCurDist
                            oNearestRecentlyFailedShield = oUnit
                        end
                        if iCurDist > iMediumSearchRange and iCurDist < iPriorityShieldSearchDist then
                            --Is the unit covered by another shield?
                            if not (DoShieldsCoverUnit(oUnit, oUnit)) then
                                iMassFactor = GetUnitTypeMassWeighting(oUnit)
                                iCurValue = (oUnit[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oUnit)) * iMassFactor
                                --Want to get the closest recently dropped sheidl (in case more than one)
                                if bAdjustValueForDistance then iCurValue = iCurValue * (0.5 + (1-iCurDist / iPriorityShieldSearchDist)) end
                                if bDebugMessages == true then LOG(sFunctionRef..': Recently dropped shield iCurValue='..iCurValue) end
                                if iCurValue > iBestTargetValue then
                                    if not(bAdjustValueForDistance) then
                                        bAdjustValueForDistance = true
                                        iCurValue = iCurValue * (0.5 + (1-iCurDist / iPriorityShieldSearchDist))
                                    end
                                    iBestTargetValue = iCurValue
                                    oTarget = oUnit
                                    bAssignedPriorityShield = true
                                end
                            end
                        end
                        -- iMediumSearchRange
                    end
                end
                if AiBotUtilities.IsTableEmpty(tiUnitsToRemove) == false then
                    for iCurEntry = table.getn(tiUnitsToRemove), 1, -1 do
                        table.remove(tTableOfUnits, iCurEntry)
                    end
                end
            end
            if AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyShieldsFailedToArti]) then
                ConsiderTableOfPriorityUnits(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyShieldsFailedToArti], math.max(iMediumSearchRange * 2, 150))
            end
            if not(bAssignedPriorityShield) and (not(oTarget) or not(EntityCategoryContains(AiBotUnitInfo.refCategoryFatboy, oTarget.UnitId))) and AiBotConditions.IsTableOfUnitsStillValid(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoVulnerableFatboys]) then
                ConsiderTableOfPriorityUnits(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoVulnerableFatboys], math.max(iMediumSearchRange * 3, 350))
            end
        end

        --Consider ignoring closest target and focusing on something furhter away if we dont have a high value target
        local bConsiderFurtherAwayMexes = false
        if not(oTarget) then bConsiderFurtherAwayMexes = true
            --NOTE: iBestTargetValue is already set at a threshold to mean really low value targets are ignored
        else
            if GetUnitTypeMassWeighting(oTarget) < 1.5 and iBestTargetValue < 150 then
                --Not a high value category; consider if we will still deal lots of damage relative to the mass cost; e.g. a T2 mex costs 900 mass with 2.5k health, so a dps of 243 would take 10.3s to kill, so 900 / 10.3 = 87.4 (ignoring the x2 weighting).  for a sniperbot, it's c.2s to kill a 880 mass unit so worth targeting (value is c.440); for a blaze it's c.4s to kill a 180 mass unit so c.45 mass/s; for UEF Fixed T2 flak (no modifier) it's 39 mass/s; i.e. if go with a value of 80 then it should exclude a lot of low value targets
                bConsiderFurtherAwayMexes = true --will consider further away mexes, but not much further away
            end
        end

        if bDebugMessages == true then LOG(sFunctionRef..': Finished considering all units at time '..GetGameTimeSeconds()..' in cur and adjacent zones, iStartPlateauOrZero='..(iStartPlateauOrZero)..'; iStartLandOrWaterZone='..iStartLandOrWaterZone..'; oTarget='..(oTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTarget) or 'nil')..'; iBestTargetValue='..iBestTargetValue..'; bConsiderFurtherAwayMexes='..tostring(bConsiderFurtherAwayMexes)) end

        if bConsiderFurtherAwayMexes then
            local iFurtherAwayMexTargetDist
            if oTarget then
                iFurtherAwayMexTargetDist = math.min(150, AiBotMap.iMapSize * 0.4)
            else
                iFurtherAwayMexTargetDist = math.min(750, math.max(200, AiBotMap.iMapSize * 0.6))
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Searching for unshielded T1 and T2 mexes, iFurtherAwayMexTargetDist='..iFurtherAwayMexTargetDist..'; AiBotMap.iMapSize='..AiBotMap.iMapSize) end


            --Get low priority target (i.e. further away target) - for now have done a copy of M27 approach
            tEnemyUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryT2Mex + AiBotUnitInfo.refCategoryT3Mex, oNovax:GetPosition(), iFurtherAwayMexTargetDist, 'Enemy')
            local iClosestTarget = 10000
            local iCurDist
            if AiBotUtilities.IsTableEmpty(tEnemyUnits) == false then
                for iUnit, oUnit in tEnemyUnits do
                    if bDebugMessages == true then LOG(sFunctionRef..': Searching for mexes, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Dist to novax='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNovax:GetPosition())..'; Is underwtaer='..tostring(AiBotUnitInfo.IsUnitUnderwater(oUnit))..'; Is under shield='..tostring(AiBotLogic.IsTargetUnderShield(aiBrain, oUnit, 0, false, false, true, false))) end
                    if oUnit:GetFractionComplete() == 1 and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) and not (AiBotLogic.IsTargetUnderShield(aiBrain, oUnit, 0, false, false, true, false)) then
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNovax:GetPosition())
                        if iCurDist < iClosestTarget then
                            iClosestTarget = iCurDist
                            oTarget = oUnit
                        end
                    end
                end
            end

            if oNearestRecentlyFailedShield and oTarget and iClosestTarget * 2 > iNearestRecentlyFailedShieldDist then
                oTarget = oNearestRecentlyFailedShield
            end

            if bDebugMessages == true then LOG(sFunctionRef..': oTarget after searching for nearby mexes='..(oTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTarget) or 'nil')..'; iClosestTarget='..(iClosestTarget or 'nil')) end

            --If enemy has fatboys then consider targeting one of these if the zone lacks enemy fixed shields
            if iClosestTarget >= 100 and (iClosestTarget >= 350 or not(oTarget) or not(oTarget == oNearestRecentlyFailedShield)) then

                if (not(oTarget) or AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats]) == false) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals]) == false then
                    local tFatboysToConsider
                    if oTarget then tFatboysToConsider = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFatboy, tStartLZOrWZData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats])
                    else tFatboysToConsider = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryFatboy, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyLandExperimentals])
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Is table of enemy LR threats empty='..tostring(tStartLZOrWZData[AiBotMap.subrefoNearbyEnemyLongRangeDFThreats])..'; is tFatboysToConsider empty='..tostring(AiBotUtilities.IsTableEmpty(tFatboysToConsider))) end
                    if AiBotUtilities.IsTableEmpty(tFatboysToConsider) == false then
                        for iUnit, oUnit in tFatboysToConsider do
                            if AiBotUnitInfo.IsUnitValid(oUnit) and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) and oUnit:GetFractionComplete() >= 0.35 then
                                --Check no fixed shields in this LZ
                                local tUnitLZData, tUnitLZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
                                if bDebugMessages == true then LOG(sFunctionRef..': Fatboy oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Dist to fatboy='.. AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNovax:GetPosition())) end
                                if (tUnitLZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) <= 350 then
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oNovax:GetPosition())
                                    if iCurDist < iClosestTarget then
                                        iClosestTarget = iCurDist
                                        oTarget = oUnit
                                    end
                                end
                            end
                        end
                    end
                end

            end
            if not(oTarget) and oNearestRecentlyFailedShield and iNearestRecentlyFailedShieldDist < 500 then
                oTarget = oNearestRecentlyFailedShield
                iClosestTarget = iNearestRecentlyFailedShieldDist
            end

            if not (oTarget) or iClosestTarget >= 500 then
                --Prev target was closer and a mex or surface navy that isn't under shield coverage? (redundancy as shouldve already considered earlier)
                if AiBotUnitInfo.IsUnitValid(oNovax[refoNovaxLastTarget]) and EntityCategoryContains(AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryNavalSurface, oNovax[refoNovaxLastTarget].UnitId) then
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oNovax[refoNovaxLastTarget]:GetPosition(), tPositionToSearchFrom)
                    if iCurDist < iClosestTarget and not(AiBotUnitInfo.IsUnitUnderwater(oNovax[refoNovaxLastTarget])) and not(AiBotLogic.IsTargetUnderShield(aiBrain, oNovax[refoNovaxLastTarget], 2000, false, false, false, nil)) then
                        if bDebugMessages == true then LOG(sFunctionRef..': setting oTarget to the novax last target for now, although will also consider enemy naval surface in a moment, iCurDist='..iCurDist) end
                        oTarget = oNovax[refoNovaxLastTarget]
                        iClosestTarget = iCurDist
                    end
                end

                --Nearest surface naval unit
                tEnemyUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryNavalSurface, tPositionToSearchFrom, 1000, 'Enemy')
                if bDebugMessages == true then LOG(sFunctionRef .. ': No high priority targets, will search for lower priority, first with surface naval units. Is table empty=' .. tostring(AiBotUtilities.IsTableEmpty(tEnemyUnits))) end
                if AiBotUtilities.IsTableEmpty(tEnemyUnits) == false then
                    local iClosestDist = 10000
                    if oTarget then iClosestDist = iClosestTarget end
                    for iUnit, oUnit in tEnemyUnits do
                        if not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tPositionToSearchFrom)
                            if iCurDist < iClosestDist then
                                if not(AiBotLogic.IsTargetUnderShield(aiBrain, oUnit, 2000, false, false, false, nil)) then
                                    iClosestDist = iCurDist
                                    oTarget = oUnit
                                end
                            end
                        end
                    end
                else
                    --Target nearest unshielded T3+ mobile land unit or T2 structure; if are none, then just get the nearest mobile land unit:
                    tEnemyUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryMobileLand + AiBotUnitInfo.refCategoryStructure, tPositionToSearchFrom, 1000, 'Enemy')
                    if AiBotUtilities.IsTableEmpty(tEnemyUnits) == false then
                        local iCurDist
                        local iClosestUnshieldedDist = 10000
                        local iClosestShieldedDist = 10000
                        local oClosestShieldedUnit
                        local oClosestUnshieldedUnit
                        local oClosestHighValueUnit
                        local iClosestHighValueUnit = 10000
                        if oTarget then iClosestHighValueUnit = iClosestTarget oClosestHighValueUnit = oTarget end
                        local tNovaxPosition = oNovax:GetPosition()
                        for iUnit, oUnit in tEnemyUnits do
                            if not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) then
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tNovaxPosition)
                                if iCurDist < math.max(iClosestUnshieldedDist, iClosestShieldedDist, iClosestHighValueUnit) then
                                    if iCurDist < iClosestShieldedDist then
                                        oClosestShieldedUnit = oUnit
                                        iClosestShieldedDist = iCurDist
                                    end
                                    if iCurDist < iClosestUnshieldedDist and iCurDist <= math.max(250, iClosestShieldedDist) then
                                        if not (AiBotLogic.IsTargetUnderShield(aiBrain, oUnit, 10000, false, true, true, false)) then
                                            oClosestUnshieldedUnit = oUnit
                                            iClosestUnshieldedDist = iCurDist
                                        end
                                    end
                                    if iCurDist < iClosestHighValueUnit then
                                        oClosestHighValueUnit = oUnit
                                    end
                                end
                            end
                        end

                        if oClosestUnshieldedUnit and iClosestUnshieldedDist <= math.max(250, iClosestShieldedDist + 60) then
                            oTarget = oClosestUnshieldedUnit
                        elseif oClosestShieldedUnit then
                            oTarget = oClosestShieldedUnit
                        else
                            oTarget = oClosestHighValueUnit --If nil then will just be ttargeting enemy base/start position
                        end
                    end
                end
            end
        end
        if not(oTarget) and iBestValueWithNoThreshold >= iBestTargetValue * 0.5 then --i.e. we didnt find anything with iBestTargetValue, so will now consider units with up to half of it
            oTarget = oBestTargetWithNoThreshold
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return oTarget
end

function ManageExperimentalBomber(iTeam, iAirSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageExperimentalBomber'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



    local tAvailableBombers, tBombersForRetreating, tUnavailableUnits = GetAvailableLowFuelAndInUseAirUnits(iTeam, iAirSubteam, AiBotUnitInfo.refCategoryBomber * categories.EXPERIMENTAL)

    if bDebugMessages == true then LOG(sFunctionRef..': Near start of code, time='..GetGameTimeSeconds()..'; Is tAvailableBombers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableBombers))..'; Is tUnavailableUnits empty='..tostring(AiBotUtilities.IsTableEmpty(tUnavailableUnits))) end
    local iOurExpBomberThreat = 0
    if AiBotUtilities.IsTableEmpty(tBombersForRetreating) == false then iOurExpBomberThreat = iOurExpBomberThreat + AiBotUnitInfo.GetAirThreatLevel(tBombersForRetreating, false, false, false, true, false, false) end
    if AiBotUtilities.IsTableEmpty(tUnavailableUnits) == false then iOurExpBomberThreat = iOurExpBomberThreat + AiBotUnitInfo.GetAirThreatLevel(tUnavailableUnits, false, false, false, true, false, false) end

    --Skip a cycle if no orders last time
    if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoRecentExpBomberAttackOrders] then
        --Do nothing
        if bDebugMessages == true then LOG(sFunctionRef..': Skipping a cycle since bombers not got active targets') end
        AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoRecentExpBomberAttackOrders] = false
    elseif AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
        local bGivenDifOrderToReturnToRally = false
        iOurExpBomberThreat = iOurExpBomberThreat + AiBotUnitInfo.GetAirThreatLevel(tAvailableBombers, false, false, false, true, false, false)
        local iTotalExpBombers = table.getn(tAvailableBombers)

        local iBombersPerTick = math.max(1, math.ceil(iTotalExpBombers / 3)) --Logic can run slowly so want to spread it out over 3 ticks
        local iCurBomberPerTick = 0

        local iFriendlyUnitDamageReductionFactor = 0.8
        local iFriendlyUnitAOEFactor = 1.6
        local iMobileUnitInnerDamageFactor = 0.75
        local iOptionalShieldReductionFactor = 0.15
        local bAvoidRecentLowHealthBomberTargets

        local iHighestLC = 0
        local iLowestLC = 10000
        for iExpBomb, oExpBomb in tAvailableBombers do
            iHighestLC = math.max(AiBotUnitInfo.GetUnitLifetimeCount(oExpBomb), iHighestLC)
            iLowestLC = math.min(AiBotUnitInfo.GetUnitLifetimeCount(oExpBomb), iLowestLC)
        end
        if AiBotUtilities.IsTableEmpty(tBombersForRetreating) == false then
            iTotalExpBombers = iTotalExpBombers + table.getn(tBombersForRetreating)
            for iExpBomb, oExpBomb in tBombersForRetreating do
                iHighestLC = math.max(AiBotUnitInfo.GetUnitLifetimeCount(oExpBomb), iHighestLC)
                iLowestLC = math.min(AiBotUnitInfo.GetUnitLifetimeCount(oExpBomb), iLowestLC)
            end
        end
        if AiBotUtilities.IsTableEmpty(tUnavailableUnits) == false then
            iTotalExpBombers = iTotalExpBombers + table.getn(tUnavailableUnits)
            for iExpBomb, oExpBomb in tUnavailableUnits do
                if oExpBomb:GetFractionComplete() == 1 then
                    iHighestLC = math.max(AiBotUnitInfo.GetUnitLifetimeCount(oExpBomb), iHighestLC)
                    iLowestLC = math.min(AiBotUnitInfo.GetUnitLifetimeCount(oExpBomb), iLowestLC)
                end
            end
        end


        for iBomber, oBomber in tAvailableBombers do
            if bDebugMessages == true and not(oBomber.Dead) then LOG(sFunctionRef..': Considering oBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; Special micro active='..tostring(oBomber[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Time='..GetGameTimeSeconds()) end
            if AiBotUnitInfo.IsUnitValid(oBomber) and not(oBomber[AiBotUnitInfo.refbSpecialMicroActive]) then --needed as will spread out logic over a number of ticks
                if iTotalExpBombers >= 2 and AiBotUtilities.IsTableEmpty(tiRecentExpBomberTargets) == false and (iTotalExpBombers >= 4 or AiBotUnitInfo.GetUnitHealthPercent(oBomber) >= 0.4 or (iTotalExpBombers >= 3 and AiBotUnitInfo.GetUnitHealthPercent(oBomber) >= 0.2)) then bAvoidRecentLowHealthBomberTargets = true end
                if bDebugMessages == true then LOG(sFunctionRef..': bAvoidRecentLowHealthBomberTargets='..tostring(bAvoidRecentLowHealthBomberTargets or false)..'; iTotalExpBombers='..iTotalExpBombers..'; Bomber health%='..AiBotUnitInfo.GetUnitHealthPercent(oBomber)..'; tiRecentExpBomberTargets='..repru(tiRecentExpBomberTargets)) end
                local tiZonesByPlateauConsidered = {}
                local aiBrain = oBomber:GetAIBrain()
                local iAOE, iDamage = AiBotUnitInfo.GetBomberAOEAndStrikeDamage(oBomber)
                local tEnemyGroundTargets = {}
                local iBomberPlateauOrZero, iBomberLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oBomber:GetPosition())
                local tBomberLandOrWaterZoneData, tBomberLandOrWaterZoneTeamData
                local tBomberZoneMidpoint
                if iBomberPlateauOrZero == 0 then
                    tBomberLandOrWaterZoneData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iBomberLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iBomberLandOrWaterZone]
                    tBomberLandOrWaterZoneTeamData = tBomberLandOrWaterZoneData[AiBotMap.subrefWZTeamData][iTeam]
                    tBomberZoneMidpoint =    tBomberLandOrWaterZoneData[AiBotMap.subrefMidpoint]
                    if bDebugMessages == true then LOG(sFunctionRef..': Have a water zone, iBomberLandOrWaterZone='..(iBomberLandOrWaterZone or 'nil')) end
                else
                    tBomberLandOrWaterZoneData = AiBotMap.tAllPlateaus[iBomberPlateauOrZero][AiBotMap.subrefPlateauLandZones][iBomberLandOrWaterZone]
                    tBomberLandOrWaterZoneTeamData = tBomberLandOrWaterZoneData[AiBotMap.subrefLZTeamData][iTeam]
                    tBomberZoneMidpoint =    tBomberLandOrWaterZoneData[AiBotMap.subrefMidpoint]
                end

                if bDebugMessages == true then LOG(sFunctionRef..': oExpBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; owner='..oBomber:GetAIBrain().Nickname..'; Position='..repru(oBomber:GetPosition())..'; iBomberPlateauOrZero='..(iBomberPlateauOrZero or 'nil')..'; iBomberLandOrWaterZone='..(iBomberLandOrWaterZone or 'nil')..'; tGunshipMidpoint='..repru(tBomberZoneMidpoint)..'; WZ from position='..(AiBotMap.GetWaterZoneFromPosition(oBomber:GetPosition()) or 'nil')) end

                local iMaxEnemyAirAA --Amount of enemy airaa threat required to make exp bomber to target enemies nearby
                if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] >= 2000 + 4000 * iTotalExpBombers then
                    iMaxEnemyAirAA = 1000
                else
                    --Is the air support location nearby?
                    local iDistToSupport = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])
                    if iDistToSupport <= 200 then
                        if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                            iMaxEnemyAirAA = 10000
                        else
                            iMaxEnemyAirAA = 6000
                        end
                    else
                        if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                            iMaxEnemyAirAA = 7000
                        else
                            iMaxEnemyAirAA = 3500
                        end
                    end
                end
                if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] then
                    iMaxEnemyAirAA = iMaxEnemyAirAA + (tBomberLandOrWaterZoneTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) + (tBomberLandOrWaterZoneTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0)
                else
                    iMaxEnemyAirAA = iMaxEnemyAirAA + ((tBomberLandOrWaterZoneTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0) + (tBomberLandOrWaterZoneTeamData[AiBotMap.subrefLZOrWZThreatAllyGroundAA] or 0)) * 0.5
                end
                if iTotalExpBombers > 1 then
                    iMaxEnemyAirAA = iMaxEnemyAirAA * (1 + (iTotalExpBombers-1) * 0.5)
                    --If we have 4+ exp bombers then be more aggressive with the bomber with the highest LC
                    if iTotalExpBombers >= 4 and (not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]) or iTotalExpBombers >= 5) and table.getn(tAvailableBombers) >= 4 then
                        if iHighestLC == AiBotUnitInfo.GetUnitLifetimeCount(oBomber) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Increasing iMaxEnemyAirAA as we have lots of exp bombers so want to be aggressive with one of them, iMaxEnemyAirAA before increase='..iMaxEnemyAirAA) end
                            iMaxEnemyAirAA = math.max(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat], iMaxEnemyAirAA * 1.5, 8000)
                        end
                    end
                    --Be aggressive with the lowest LC as well if very dangerous scenario
                    if iTotalExpBombers > 2 and (iTotalExpBombers >= 5 or iLowestLC < iTotalExpBombers * 4) and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir]) and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] > AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] then
                        if (iTotalExpBombers >= 5 or AiBotUnitInfo.GetUnitLifetimeCount(oBomber) == iLowestLC) and AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure]) == false then
                            local iEnemyArtiOrGEMassInvestment = 0
                            local bApplyCustomThreatFactor = AiBotUnitInfo.bCustomThreatFactor
                            if bApplyCustomThreatFactor and AiBotUnitInfo.iThreatFactor == 1 then bApplyCustomThreatFactor = false end
                            local iCurCost

                            for iArti, oArti in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyArtiAndExpStructure] do
                                if not(oArti.Dead) then
                                    iCurCost = oArti[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oArti)
                                    if bApplyCustomThreatFactor then iCurCost = iCurCost * AiBotUnitInfo.iThreatFactor end
                                    if oArti:GetFractionComplete() < 1 then iCurCost = iCurCost * oArti:GetFractionComplete() end
                                    iEnemyArtiOrGEMassInvestment = iEnemyArtiOrGEMassInvestment + iCurCost
                                end

                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if should be more aggressive with all exp bombers and/or our lowest LC bomber, iEnemyArtiOrGEMassInvestment='..iEnemyArtiOrGEMassInvestment) end
                            if iEnemyArtiOrGEMassInvestment >= 140000 or (iEnemyArtiOrGEMassInvestment >= 70000 and AiBotUnitInfo.GetUnitLifetimeCount(oBomber) == iLowestLC) then
                                iMaxEnemyAirAA = math.max(iMaxEnemyAirAA, AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiOurAirAAThreat], 8000)
                            end
                        end
                    end
                end
                if AiBotTeam.tTeamData[iTeam][AiBotTeam.refbDontHaveBuildingsOrACUInPlayableArea] then iMaxEnemyAirAA = 100000 end

                if bDebugMessages == true then LOG(sFunctionRef..': About to look for targets for experimental bomber, iMaxEnemyAirAA='..iMaxEnemyAirAA..'; iDistToSupport='..AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirAsfSupportPoint])..'; HaveAirControl='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl])..'; Far behind on air='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir])..'; Enemy total AirAA='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]..'; OurAirAA='..AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat]) end
                local bHaveTargetWhereShotIsntBlocked = false
                local bHaveTargetWhereShotIsBlocked = false
                function AddEnemyGroundUnitsToTargetsSubjectToAA(iPlateauOrZero, iLandOrWaterZone, bCheckForAirAA)
                    if not(tiZonesByPlateauConsidered[iPlateauOrZero][iLandOrWaterZone]) then
                        if not(tiZonesByPlateauConsidered[iPlateauOrZero]) then tiZonesByPlateauConsidered[iPlateauOrZero] = {} end
                        tiZonesByPlateauConsidered[iPlateauOrZero][iLandOrWaterZone] = true
                        local iMaxEnemyGroundAA = -1
                        --Check if sufficient threat in the LZ/WZ to consider targeting
                        local tLZOrWZTeamData
                        if iPlateauOrZero > 0 then
                            --Land zone
                            tLZOrWZTeamData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone][AiBotMap.subrefLZTeamData][iTeam]
                        else
                            --Water zone
                            tLZOrWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone][AiBotMap.subrefWZTeamData][iTeam]
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Considering targeting untis in iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]))..'; Is table of allied ACUs empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefAlliedACU]))..'; Enemy combat total='..tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal]..'; Enemy structure total mass='..tLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]) end
                        --Only consider zones with enemy units, no friendly ACUs, and sufficient threat to be worth bombing
                        if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefAlliedACU]) and (tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) + (tLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) + ((tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) + (tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)) * 2 >= 1500 then
                            --Only include if enemy threat is high and our threat isnt high (as dont want to nuke our own units); however dont ignore if has high AA threat as otherwise risk targeting something near this and dying to the AA; also dont ignore if very high mass value as could be t3 arti/game ender that we want to kill asap
                            if bDebugMessages == true then LOG(sFunctionRef..': Are potential enemies to target, checking overall threat vs friendly threat, ally combat total='..(tLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0)..'; Enemy combat total='..(tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0)..'; tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]='..(tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')..'; tLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]='..(tLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 'nil')) end
                            if (tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) >= 2000 or ((tLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) >= 100000 and ((tLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) >= (tLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) * 0.25)) or
                                    ((tLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) * 1.75 <= (tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) + ((tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) + (tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)) * 0.6 + (tLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) * 0.05 and
                                            ((tLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) <= 200 or (tLZOrWZTeamData[AiBotMap.subrefTThreatEnemyCombatTotal] or 0) + (tLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) + (tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) + (tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) >= 2500 + (tLZOrWZTeamData[AiBotMap.subrefLZTThreatAllyCombatTotal] or 0) * 3)) then

                                --Check if enemy has enough AA nearby
                                local bTooMuchAA
                                if not (bCheckForAirAA) and iMaxEnemyGroundAA < 0 then
                                    bTooMuchAA = false
                                else
                                    bTooMuchAA = DoesEnemyHaveAAThreatAlongPath(iTeam, iBomberPlateauOrZero, iBomberLandOrWaterZone, iPlateauOrZero, iLandOrWaterZone, not(bCheckForAirAA), iMaxEnemyGroundAA, iMaxEnemyAirAA)
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': bTooMuchAA='..tostring(bTooMuchAA)..'; iBomberPlateauOrZero='..iBomberPlateauOrZero..'; iBomberLandOrWaterZone='..iBomberLandOrWaterZone..'; iMaxEnemyGroundAA='..iMaxEnemyGroundAA..'; iMaxEnemyAirAA='..iMaxEnemyAirAA) end

                                if not (bTooMuchAA) then
                                    --Add enemy ground units in the plateau/land zone to list of enemy unit targets
                                    local tPriorityTargets = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure + AiBotUnitInfo.refCategoryNavalSurface + AiBotUnitInfo.refCategoryMobileLand * categories.TECH2 + AiBotUnitInfo.refCategoryMobileLand * categories.TECH3 + AiBotUnitInfo.refCategoryMobileLand * categories.EXPERIMENTAL + categories.COMMAND, tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will add targets to consider, Is tPriorityTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tPriorityTargets))) end
                                    if AiBotUtilities.IsTableEmpty(tPriorityTargets) == false then
                                        local iCurUnitSegmentX, iCurUnitSegmentZ, bAddUnit
                                        for iUnit, oUnit in tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits] do
                                            if AiBotUnitInfo.IsUnitValid(oUnit) and not(oUnit:IsUnitState('Attached')) and not(AiBotMap.IsUnderwater(oUnit:GetPosition(), false, math.max(0, iAOE - 4))) then
                                                --Is enemy still in this zone if we no longer have intel?
                                                bAddUnit = false
                                                if bDebugMessages == true then LOG(sFunctionRef..': Checking if have a mobile unit that has moved far from the lastk nown position such that we will end up targeting a different zone by mistake, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Can see unit='..tostring(AiBotUnitInfo.CanSeeUnit(aiBrain, oUnit))..'; Dist between position and last known position='..AiBotUtilities.GetRoughDistanceBetweenPositions(oUnit:GetPosition(), oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam])) end
                                                if EntityCategoryContains(categories.STRUCTURE, oUnit.UnitId) or AiBotUnitInfo.CanSeeUnit(aiBrain, oUnit) then
                                                    bAddUnit = true
                                                else
                                                    --dealing with mobile unit, is it still in this zone?
                                                    iCurUnitSegmentX, iCurUnitSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oUnit:GetPosition())
                                                    if iPlateauOrZero == 0 then
                                                        if AiBotMap.tWaterZoneBySegment[iCurUnitSegmentX][iCurUnitSegmentZ] == iLandOrWaterZone then
                                                            bAddUnit = true
                                                        elseif AiBotUtilities.GetRoughDistanceBetweenPositions(oUnit:GetPosition(), oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) <= 15 then
                                                            bAddUnit = true
                                                        end
                                                    else
                                                        --Land zone
                                                        if AiBotMap.tLandZoneBySegment[iCurUnitSegmentX][iCurUnitSegmentZ] == iLandOrWaterZone then
                                                            bAddUnit = true
                                                        elseif AiBotUtilities.GetRoughDistanceBetweenPositions(oUnit:GetPosition(), oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) <= 15 then
                                                            bAddUnit = true
                                                        end
                                                    end
                                                    if not(bAddUnit) then
                                                        --Update last position as unit is in a differnet zone so want to avoid it being treated as invisible
                                                        oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam] = {oUnit:GetPosition()[1], oUnit:GetPosition()[2], oUnit:GetPosition()[3]}
                                                    end
                                                end

                                                if bAddUnit then
                                                    if not(oUnit[AiBotUnitInfo.refbExpBomberShotBlocked]) then bHaveTargetWhereShotIsntBlocked = true
                                                    else bHaveTargetWhereShotIsBlocked = true
                                                    end
                                                    table.insert(tEnemyGroundTargets, oUnit)
                                                end
                                            end
                                        end
                                    end
                                    --Consider adding restorers if enemy has significant airaa threat in the zone - drafted for v168, but decided in the end not to add as didnt trigger on several sandbox scenarios or the replay in question; left code here in case decide want to add it in the future
                                    --[[if tLZOrWZTeamData[AiBotMap.refiEnemyAirAAThreat] >= 9000 and tLZOrWZTeamData[AiBotMap.refiEnemyAirToGroundThreat] >= 4500 and AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.reftLZEnemyAirUnits]) == false then
                        local tEnemyRestorers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryRestorer - categories.EXPERIMENTAL - categories.HIGHALTAIR, tLZOrWZTeamData[AiBotMap.reftLZEnemyAirUnits])
                        if AiBotUtilities.IsTableEmpty(tEnemyRestorers) == false then
                            if bDebugMessages == true then LOG(sFunctionRef..': About to add enemy restorers that are in the target zone, P'..iPlateauOrZero..'Z'..iLandOrWaterZone..'; size of table='..table.getn(tEnemyRestorers)) end
                            local bAddUnit, iCurUnitSegmentX, iCurUnitSegmentZ
                            for iUnit, oUnit in tEnemyRestorers do
                                iCurUnitSegmentX, iCurUnitSegmentZ = AiBotMap.GetPathingSegmentFromPosition(oUnit:GetPosition())
                                if iPlateauOrZero == 0 then
                                    if AiBotMap.tWaterZoneBySegment[iCurUnitSegmentX][iCurUnitSegmentZ] == iLandOrWaterZone then
                                        bAddUnit = true
                                    elseif AiBotUtilities.GetRoughDistanceBetweenPositions(oUnit:GetPosition(), oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) <= 15 then
                                        bAddUnit = true
                                    end
                                else
                                    --Land zone
                                    if AiBotMap.tLandZoneBySegment[iCurUnitSegmentX][iCurUnitSegmentZ] == iLandOrWaterZone then
                                        bAddUnit = true
                                    elseif AiBotUtilities.GetRoughDistanceBetweenPositions(oUnit:GetPosition(), oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam]) <= 15 then
                                        bAddUnit = true
                                    end
                                end
                                if not(bAddUnit) then
                                    --Update last position as unit is in a differnet zone so want to avoid it being treated as invisible
                                    oUnit[AiBotUnitInfo.reftLastKnownPositionByTeam][iTeam] = {oUnit:GetPosition()[1], oUnit:GetPosition()[2], oUnit:GetPosition()[3]}
                                end
                                if bAddUnit then
                                    if not(oUnit[AiBotUnitInfo.refbExpBomberShotBlocked]) then bHaveTargetWhereShotIsntBlocked = true
                                    else bHaveTargetWhereShotIsBlocked = true
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Adding enemy gunship unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to tEnemyGroundTargets, for P'..iPlateauOrZero..'Z'..iLandOrWaterZone) end
                                    table.insert(tEnemyGroundTargets, oUnit)
                                end
                            end
                        end
                    end--]]
                                end
                            end
                        end
                    elseif bDebugMessages == true then LOG(sFunctionRef..': We have already considered P'..iPlateauOrZero..'Z'..iLandOrWaterZone..' for this bomber')
                    end
                end

                local iCurPlateauOrZero, iCurLZOrWZ

                --Emergency response - first include any ground threats in a start position
                for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                    local tStartPoint = AiBotMap.GetPlayerStartPosition(oBrain)
                    iCurPlateauOrZero, iCurLZOrWZ = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tStartPoint)
                    if (iCurPlateauOrZero or 0) > 0 then
                        if (iCurLZOrWZ or 0) == 0 then
                            iCurLZOrWZ = AiBotMap.GetWaterZoneFromPosition(tStartPoint)
                            if (iCurLZOrWZ or 0) > 0 then
                                iCurPlateauOrZero = 0
                            end
                        end
                    end
                    if (iCurLZOrWZ or 0) > 0 then
                        if bDebugMessages == true then LOG(sFunctionRef..': Emergency response for ground threats in a start position, iCurLZOrWZ='..iCurLZOrWZ..'; will look to add targets') end
                        AddEnemyGroundUnitsToTargetsSubjectToAA(iCurPlateauOrZero, iCurLZOrWZ, false)
                    end
                end

                if AiBotUtilities.IsTableEmpty(tEnemyGroundTargets) or not(bHaveTargetWhereShotIsntBlocked) then
                    --Check if want exp bomber to run to rally point if nearby enemy airAA (if give no targets for exp bomber then they will go to rally point or air staging
                    if bDebugMessages == true then LOG(sFunctionRef..': Checking if too great an enemy threat in zone IsThereAANearLandOrWaterZone='..tostring(IsThereAANearLandOrWaterZone(iTeam, iBomberPlateauOrZero, iBomberLandOrWaterZone, (iBomberPlateauOrZero == 0), -1, iMaxEnemyAirAA) or false)..'; IsThereNearbyAirAA='..tostring(IsThereNearbyAirAA(iTeam, iBomberPlateauOrZero, iBomberLandOrWaterZone, (iBomberPlateauOrZero == 0), 200, iMaxEnemyAirAA, oBomber:GetPosition()) or false)..'; Have air control='..tostring(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl])..'; iMaxEnemyAirAA='..iMaxEnemyAirAA..'; iBomberPlateauOrZero='..iBomberPlateauOrZero..'; iBomberLandOrWaterZone='..iBomberLandOrWaterZone) end
                    if ((AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl] and not(IsThereAANearLandOrWaterZone(iTeam, iBomberPlateauOrZero, iBomberLandOrWaterZone, (iBomberPlateauOrZero == 0), -1, iMaxEnemyAirAA))) or (not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) and not(IsThereNearbyAirAA(iTeam, iBomberPlateauOrZero, iBomberLandOrWaterZone, (iBomberPlateauOrZero == 0), 200, iMaxEnemyAirAA, oBomber:GetPosition()))))
                            --If there is enemy groundAA in the zone we are currently in and we are facing the rally point and are more than 20 from it, then keep moving to the rally point
                            and ((tBomberLandOrWaterZoneTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) + (tBomberLandOrWaterZoneTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) < 1000 or AiBotUtilities.GetAngleDifference(AiBotUnitInfo.GetUnitFacingAngle(oBomber), AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(),AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])) >= 25) then

                        --no nearby enemy air threat so can just evaluate each land zone or water zone on its own merits - cycle through each in order of distance, but first consider adjacent locations
                        --First consider the land/water zone the bomber is in at the moment and any nearby zones
                        AddEnemyGroundUnitsToTargetsSubjectToAA(iBomberPlateauOrZero, iBomberLandOrWaterZone, true)


                        local tFirstZoneWithTargetsMidpoint
                        local iZonesConsideredAfterFirstTarget = 0
                        local iDistFromFirstZoneToBomber

                        local iCurBombDamage, iTargetSegmentX, iTargetSegmentZ

                        function RemoveRecentBombTargets(tBombLZOrWZTeamData, iBombPlateauOrZero, iBombLandOrWaterZone)
                            local bDontCheckForShields = (tBombLZOrWZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) > 2000
                            --Are we close to a recent bomb?
                            for _, tRecentTarget in tiRecentExpBomberTargets do
                                iTargetSegmentX, iTargetSegmentZ = AiBotMap.GetPathingSegmentFromPosition(tRecentTarget)
                                if (iBombPlateauOrZero == 0 and AiBotMap.tWaterZoneBySegment[iTargetSegmentX][iTargetSegmentZ] == iBombLandOrWaterZone)
                                        or (not(iBombPlateauOrZero == 0) and AiBotMap.tLandZoneBySegment[iTargetSegmentX][iTargetSegmentZ] == iBombLandOrWaterZone and NavUtils.GetLabel(AiBotMap.refPathingTypeHover, tRecentTarget) == iBombPlateauOrZero) then
                                    --Target is close, so limit to only considering high value targets here
                                    -- = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryExperimentalLevel + categories.COMMAND + AiBotUnitInfo.refCategoryNavalSurface * categories.TECH3, tEnemyGroundTargets)
                                    iCurBombDamage = 0 --will update later
                                    for iEnemyCount = table.getn(tEnemyGroundTargets), 1, -1 do
                                        if AiBotUtilities.GetDistanceBetweenPositions(tEnemyGroundTargets[iEnemyCount]:GetPosition(), tRecentTarget) <= iAOE and (AiBotUnitInfo.IsUnitUnderwater(tEnemyGroundTargets[iEnemyCount]) or (tEnemyGroundTargets[iEnemyCount]:GetHealth() <= iDamage and not(EntityCategoryContains(AiBotUnitInfo.refCategoryExperimentalLevel + categories.COMMAND, tEnemyGroundTargets[iEnemyCount].UnitId)))) then
                                            --Check if under shield
                                            if bDontCheckForShields or AiBotLogic.IsTargetUnderShield(aiBrain, tEnemyGroundTargets[iEnemyCount], iDamage - 1000, false, true, true, false, false) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Removing the target '..tEnemyGroundTargets[iEnemyCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEnemyGroundTargets[iEnemyCount])..' as it is too close to a recent bomb') end
                                                table.remove(tEnemyGroundTargets, iEnemyCount)
                                            end
                                        end
                                    end
                                end
                            end
                        end


                        if bDebugMessages == true then LOG(sFunctionRef..': Is tEnemyGroundTargets empty after considering enemies in the same LZ/WZ as experimental bomber='..tostring(AiBotUtilities.IsTableEmpty(tEnemyGroundTargets))) end
                        if bAvoidRecentLowHealthBomberTargets and AiBotUtilities.IsTableEmpty(tEnemyGroundTargets) == false then
                            RemoveRecentBombTargets(tBomberLandOrWaterZoneTeamData, iBomberPlateauOrZero, iBomberLandOrWaterZone)
                        end
                        if AiBotUtilities.IsTableEmpty(tEnemyGroundTargets) == false and bHaveTargetWhereShotIsntBlocked then
                            --Check if already firing bomb here
                            tFirstZoneWithTargetsMidpoint = tBomberZoneMidpoint
                            iDistFromFirstZoneToBomber = 0
                        end
                        --if AiBotUtilities.IsTableEmpty(tEnemyGroundTargets) then
                        --Is there groundAA in the current plateau/water zone (i.e. there are enemies but we have chosen not to attack due to the threat)?
                        if (tBomberLandOrWaterZoneData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) > 0 or (tBomberLandOrWaterZoneData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) > 0 then
                            --Enemy has AA in the same LZ as our exp bomber and we dont want to attack enemies, so retreat (if no targets)
                            if bDebugMessages == true then LOG(sFunctionRef..': Enemy GroundAA threat exists in same zone as exp bomber so want to retreat if not already got targets') end
                        else

                            if bDebugMessages == true then LOG(sFunctionRef..': oBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; iBomberPlateauOrZero='..(iBomberPlateauOrZero or 'nil')..'; iBomberLandOrWaterZone='..(iBomberLandOrWaterZone or 'nil')..'; tBomberZoneMidpoint='..repru(tBomberZoneMidpoint)) end
                            RecordOtherLandAndWaterZonesByDistance(tBomberLandOrWaterZoneData)
                            if AiBotUtilities.IsTableEmpty(tBomberLandOrWaterZoneData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                                if bDebugMessages == true then LOG(sFunctionRef..': About to cycle through each other zone by distance and consider the best target, tFirstZoneWithTargetsMidpoint='..repru(tFirstZoneWithTargetsMidpoint)) end
                                local bZoneIsCloseToFirstTargetZone
                                --local tiFirstPlateauAndZone
                                for iEntry, tSubtable in tBomberLandOrWaterZoneData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                                    if tFirstZoneWithTargetsMidpoint then
                                        iZonesConsideredAfterFirstTarget = iZonesConsideredAfterFirstTarget + 1
                                        if iZonesConsideredAfterFirstTarget >= 6 then
                                            if iZonesConsideredAfterFirstTarget >= 20 or (tSubtable[AiBotMap.subrefiDistance] or 0) - (iDistFromFirstZoneToBomber or 50) >= 90 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Already considered '..(iZonesConsideredAfterFirstTarget - 1)..' zones after the first, dist threshold vs dist from first zone to bomber='..tSubtable[AiBotMap.subrefiDistance] - iDistFromFirstZoneToBomber..' so will stop searching for more, dist to bomber zone='..tSubtable[AiBotMap.subrefiDistance]) end
                                                break
                                            end
                                        end
                                    end

                                    bZoneIsCloseToFirstTargetZone = true
                                    if tFirstZoneWithTargetsMidpoint then
                                        local tOtherZoneLZOrWZData
                                        if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                            tOtherZoneLZOrWZData = AiBotMap.tPondDetails[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                        else
                                            tOtherZoneLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                        end

                                        bZoneIsCloseToFirstTargetZone = false

                                        if AiBotUtilities.GetDistanceBetweenPositions(tFirstZoneWithTargetsMidpoint, tOtherZoneLZOrWZData[AiBotMap.subrefMidpoint]) <= 100 then
                                            bZoneIsCloseToFirstTargetZone = true
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Considering if potential zone P'..tSubtable[AiBotMap.subrefiPlateauOrPond]..'Z'..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..' is close enough to the first zone target to warrant considering, dist to zone midpoint='..AiBotUtilities.GetDistanceBetweenPositions(tFirstZoneWithTargetsMidpoint, tOtherZoneLZOrWZData[AiBotMap.subrefMidpoint])..'; bZoneIsCloseToFirstTargetZone='..tostring(bZoneIsCloseToFirstTargetZone)..'; Dist to bomber zone='..tSubtable[AiBotMap.subrefiDistance]) end
                                    end
                                    if bZoneIsCloseToFirstTargetZone then
                                        if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                            AddEnemyGroundUnitsToTargetsSubjectToAA(0, tSubtable[AiBotMap.subrefiLandOrWaterZoneRef],  true)
                                        else
                                            AddEnemyGroundUnitsToTargetsSubjectToAA(tSubtable[AiBotMap.subrefiPlateauOrPond], tSubtable[AiBotMap.subrefiLandOrWaterZoneRef],  true)
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': Have just finished calling AddEnemyGroundUnitsToTargetsSubjectToAA for bombers for zone '..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..', Is table of enemy targets empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyGroundTargets))..'; tSubtable='..repru(tSubtable)..'; bHaveTargetWhereShotIsntBlocked='..tostring(bHaveTargetWhereShotIsntBlocked)) end
                                        if not(tFirstZoneWithTargetsMidpoint) and AiBotUtilities.IsTableEmpty(tEnemyGroundTargets) == false and bHaveTargetWhereShotIsntBlocked then
                                            if bAvoidRecentLowHealthBomberTargets then
                                                local tOtherZoneLZOrWZData
                                                local tOtherZoneLZOrWZTeamData
                                                local iOtherPlateauOrZero
                                                local iTargetSegmentX, iTargetSegmentZ
                                                if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                                    tOtherZoneLZOrWZData = AiBotMap.tPondDetails[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                                    tOtherZoneLZOrWZTeamData = tOtherZoneLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                                    iOtherPlateauOrZero = 0
                                                else
                                                    tOtherZoneLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                                    tOtherZoneLZOrWZTeamData = tOtherZoneLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                                    iOtherPlateauOrZero = tSubtable[AiBotMap.subrefiPlateauOrPond]
                                                end

                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering if we should ignore this zone due to recently targeting it with another ahwassa, enemy shield='..(tOtherZoneLZOrWZTeamData[AiBotMap.subrefThreatEnemyShield] or 'nil')..'; GroundAA='..(tOtherZoneLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')) end
                                                RemoveRecentBombTargets(tOtherZoneLZOrWZTeamData, iOtherPlateauOrZero, tSubtable[AiBotMap.subrefiLandOrWaterZoneRef])

                                            end
                                            if AiBotUtilities.IsTableEmpty(tEnemyGroundTargets) == false then
                                                --Check we have at least 1 target where the bomb will deal damage of at least 100
                                                for iEnemyCount = table.getn(tEnemyGroundTargets), 1, -1 do
                                                    --GetDamageFromBomb(aiBrain, tBaseLocation,                                 iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, bCumulativeShieldHealthCheck, iOptionalSizeAdjust, iOptionalModIfNeedMultipleShots, iMobileValueOverrideFactorWithin75Percent, bT3ArtiShotReduction, iOptionalShieldReductionFactor, bIncludePreviouslySeenEnemies, iOptionalSpecialCategoryDamageFactor, iOptionalSpecialCategory, iOptionalReclaimFactor, bCheckIfUnderwater, iOptionalGunshipFactor)
                                                    iCurBombDamage = AiBotLogic.GetDamageFromBomb(aiBrain, tEnemyGroundTargets[iEnemyCount]:GetPosition(), iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor,    nil,                            nil,                nil,                            iMobileUnitInnerDamageFactor,                nil,               iOptionalShieldReductionFactor,     true,                    4,                              AiBotUnitInfo.refCategoryGroundAA,    nil,                    nil,                0.5)
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Damage for iEnemyCount='..iEnemyCount..'; Enemy='..tEnemyGroundTargets[iEnemyCount].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEnemyGroundTargets[iEnemyCount])..' is iCurBombDamage='..iCurBombDamage) end
                                                    if iCurBombDamage >= 200 then
                                                        break
                                                    elseif iCurBombDamage <= 40 then
                                                        table.remove(tEnemyGroundTargets, iEnemyCount)
                                                    end
                                                end
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Finished removing nil damage enemy ground targets, is table empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyGroundTargets))) end
                                            if AiBotUtilities.IsTableEmpty(tEnemyGroundTargets) == false then
                                                local tOtherZoneLZOrWZData
                                                if tSubtable[AiBotMap.subrefbIsWaterZone] then
                                                    tOtherZoneLZOrWZData = AiBotMap.tPondDetails[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                                else
                                                    tOtherZoneLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                                                end
                                                tFirstZoneWithTargetsMidpoint = tOtherZoneLZOrWZData[AiBotMap.subrefMidpoint]
                                                iDistFromFirstZoneToBomber = (tSubtable[AiBotMap.subrefiDistance] or AiBotUtilities.GetDistanceBetweenPositions(tFirstZoneWithTargetsMidpoint, oBomber:GetPosition()))

                                                --tiFirstPlateauAndZone = {tSubtable[AiBotMap.subrefiPlateauOrPond], tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]}
                                                if bDebugMessages == true then LOG(sFunctionRef..': Have the first zone to target, tFirstZoneWithTargetsMidpoint='..repru(tFirstZoneWithTargetsMidpoint)..'; Dist to bomber zone='..tSubtable[AiBotMap.subrefiDistance]) end
                                            end
                                        end
                                        --if AiBotUtilities.IsTableEmpty(tEnemyGroundTargets) == false then break end
                                    end
                                end
                                if AiBotUtilities.IsTableEmpty(tFirstZoneWithTargetsMidpoint) == false then
                                    --We have a target, so consider SAMs and T3 MAA in nearby zones that we haven't already considered that are near here
                                    local tMidpoint = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), tFirstZoneWithTargetsMidpoint), iDistFromFirstZoneToBomber * 0.7)
                                    local tNearbyDangerousAA = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryGroundAA + AiBotUnitInfo.refCategoryCruiser, tMidpoint, math.min(175, iDistFromFirstZoneToBomber * 0.5), 'Enemy')
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will cycle through each nearby T3 SAM, MAA or cruiser near the target and make sure that zone has been included in the table of potentail targets, is tNearbyDangerousAA empty='..tostring(AiBotUtilities.IsTableEmpty(tNearbyDangerousAA))) end
                                    if AiBotUtilities.IsTableEmpty(tNearbyDangerousAA) == false then
                                        for iUnit, oUnit in tNearbyDangerousAA do
                                            if oUnit:GetFractionComplete() >= 1 then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Assessing enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Assigned Plateau and LZ='..repru(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam])) end
                                                if AiBotUtilities.IsTableEmpty(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam]) == false then
                                                    --AddEnemyGroundUnitsToTargetsSubjectToAA(iPlateauOrZero, iLandOrWaterZone, bCheckForAirAA)
                                                    AddEnemyGroundUnitsToTargetsSubjectToAA(oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1], oUnit[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2],  true)
                                                elseif oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam] then
                                                    AddEnemyGroundUnitsToTargetsSubjectToAA(0, oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam],  true)
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                        --end
                    else
                        if bDebugMessages == true then LOG(sFunctionRef..': We want to run to rally point so wont consider further targets, subjcet to exception when down to last base, time of last bomb='..GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastBombFired] or 0)..'; Bomber refiModDistancePercent='..tBomberLandOrWaterZoneTeamData[AiBotMap.refiModDistancePercent]..'; Dist from bomber to rally='..AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])..'; Dist from rally to closest friendly base='..AiBotUtilities.GetDistanceBetweenPositions(tBomberLandOrWaterZoneTeamData[AiBotMap.reftClosestFriendlyBase], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])) end
                        --If bomber hasnt fired any bombs for a while, is within 175 of the rally point, rally point mod dist is low, and are enemies near the rally point, then consider ignoring enemy AA to target enemies adjacent to core base if we are the last 1-2 AiBot players, and last on our air subteam
                        if GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastBombFired] or 0) >= 60 and not(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbHaveAirControl]) and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiActiveAiBotBrainCount] <= 2 and  tBomberLandOrWaterZoneTeamData[AiBotMap.refiModDistancePercent] <= 0.4 and AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]) <= 175 and AiBotUtilities.GetDistanceBetweenPositions(tBomberLandOrWaterZoneTeamData[AiBotMap.reftClosestFriendlyBase], AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]) <= 125
                                and AiBotUtilities.IsTableEmpty(tEnemyGroundTargets) then
                            local iAirSubteamCount = 0
                            for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
                                if not(oBrain.AiBotIsDefeated) and not(oBrain:IsDefeated()) then iAirSubteamCount = iAirSubteamCount + 1 end
                            end
                            if iAirSubteamCount <= 1 then
                                local iClosestBasePlateauOrZero, iClosestBaseZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tBomberLandOrWaterZoneTeamData[AiBotMap.reftClosestFriendlyBase])
                                if iClosestBasePlateauOrZero > 0 and iClosestBaseZone > 0 and iClosestBasePlateauOrZero and iClosestBaseZone then
                                    local tClosestBaseLZData = AiBotMap.tAllPlateaus[iClosestBasePlateauOrZero][AiBotMap.subrefPlateauLandZones][iClosestBaseZone]
                                    local tClosestBaseLZTeamData = tClosestBaseLZData[AiBotMap.subrefLZTeamData][iTeam]
                                    if bDebugMessages == true then LOG(sFunctionRef..': Are there enemies adjacent to reftClosestFriendlyBase iClosestBasePlateauOrZero P'..iClosestBasePlateauOrZero..'Z'..iClosestBaseZone..'='..tostring(tClosestBaseLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] or false)) end
                                    if tClosestBaseLZTeamData[AiBotMap.subrefbEnemiesInThisOrAdjacentLZ] then
                                        if AiBotUtilities.IsTableEmpty(tClosestBaseLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                            AddEnemyGroundUnitsToTargetsSubjectToAA(iClosestBasePlateauOrZero, iClosestBaseZone, false)
                                        end
                                        if AiBotUtilities.IsTableEmpty(tClosestBaseLZData[AiBotMap.subrefLZAdjacentLandZones]) == false then
                                            for _, iAdjLZ in tClosestBaseLZData[AiBotMap.subrefLZAdjacentLandZones] do
                                                local tAdjLZData = AiBotMap.tAllPlateaus[iClosestBasePlateauOrZero][AiBotMap.subrefPlateauLandZones][iAdjLZ]
                                                local tAdjLZTeamData = tAdjLZData[AiBotMap.subrefLZTeamData][iTeam]
                                                if  AiBotUtilities.IsTableEmpty(tAdjLZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Will add enemy units in the adjacent zone '..iAdjLZ) end
                                                    AddEnemyGroundUnitsToTargetsSubjectToAA(iClosestBasePlateauOrZero, iAdjLZ, false)
                                                end
                                            end
                                            --Remove any targets that are too far away
                                            if AiBotUtilities.IsTableEmpty(tEnemyGroundTargets) == false then
                                                local iMaxTargetDistFromBase = 175
                                                for iCurEntry = table.getn(tEnemyGroundTargets, 1), 1, -1 do
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering cur target if too far away from base, target='..tEnemyGroundTargets[iCurEntry].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tEnemyGroundTargets[iCurEntry])..'; dist to closest base='..AiBotUtilities.GetDistanceBetweenPositions(tEnemyGroundTargets[iCurEntry]:GetPosition(), tBomberLandOrWaterZoneTeamData[AiBotMap.reftClosestFriendlyBase])) end
                                                    if AiBotUtilities.GetDistanceBetweenPositions(tEnemyGroundTargets[iCurEntry]:GetPosition(), tBomberLandOrWaterZoneTeamData[AiBotMap.reftClosestFriendlyBase]) > iMaxTargetDistFromBase then
                                                        table.remove(tEnemyGroundTargets, iCurEntry)
                                                        if bDebugMessages == true then LOG(sFunctionRef..': Removing from potential targets') end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end

                if AiBotUtilities.IsTableEmpty(tEnemyGroundTargets) then
                    --Return bomber to nearest rally point (NOTE: if changing this appraoch then need to rethink above appraoch that determines bomber angle to rally point to decide whether to keep moving)
                    --Exception (for cases where e.g. enemy has large airaa threat) - check if we fire a bomb now if that will do damage
                    local bReturnToRally = true
                    if not(oBomber[refbExpBomberRecentlyTriedFiringAtRange]) and (oBomber[AiBotUnitInfo.refiBomberRange] or 0) > 0 then
                        local iBomberAngle = AiBotUnitInfo.GetUnitFacingAngle(oBomber)
                        local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint])
                        if bDebugMessages == true then LOG(sFunctionRef..': iBomberAngle='..iBomberAngle..'; iAngleToRally='..iAngleToRally..'; AngleDif='..AiBotUtilities.GetAngleDifference(iBomberAngle, iAngleToRally)..'; Bomber range='..oBomber[AiBotUnitInfo.refiBomberRange]..'; Bomber speed='..AiBotUnitInfo.GetUnitSpeed(oBomber)) end
                        if AiBotUtilities.GetAngleDifference(iBomberAngle, iAngleToRally) >= 90 then
                            --NOTE: Doing some basic logging of distance of bomb target vs bomber speed, out of 16 bombs dropped by an ahwassa with speed ranging from 8-24, in 1 case the distance was more than the bomber range; hence will try just doing at bomber range
                            local tPotentialTarget = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iBomberAngle, (oBomber[AiBotUnitInfo.refiBomberRange] or 30) - 1, true, false, AiBotMap.bIsCampaignMap)
                            if tPotentialTarget then
                                local iTargetDamage = AiBotLogic.GetDamageFromBomb(aiBrain, tPotentialTarget, iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor,    nil,                            nil,                nil,                            iMobileUnitInnerDamageFactor,                nil,               iOptionalShieldReductionFactor,     true,                   4,                          AiBotUnitInfo.refCategoryGroundAA,        nil,                nil,                0.5)
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering firing our bomb at our range, iTargetDamage='..iTargetDamage) end
                                if iTargetDamage >= 600 then --Will lose 0.5s in turning around (waiting to see if the bomb will drop) so want to do some damage to do this
                                    --Attack move here
                                    bReturnToRally = false
                                    oBomber[refbExpBomberRecentlyTriedFiringAtRange] = true
                                    AiBotUtilities.DelayChangeVariable(oBomber, refbExpBomberRecentlyTriedFiringAtRange, false, 5)
                                    AiBotOrders.IssueTrackedGroundAttack(oBomber, tPotentialTarget, 0, false, 'BmAtRetr', false, nil)
                                    if bDebugMessages == true then
                                        LOG(sFunctionRef..': Will try dropping bomb at our range')
                                        AiBotUtilities.DrawLocation(tPotentialTarget)
                                    end
                                    ForkThread(ReturnBomberToRallyIfBombNotDropped, oBomber, 9)
                                end
                            end
                        end
                    end
                    if bReturnToRally then
                        --Check micro not active
                        if not(oBomber[AiBotUnitInfo.refbSpecialMicroActive]) then
                            if bDebugMessages == true then LOG(sFunctionRef..': will return to air sub rally point') end
                            --Consider microing to turn
                            local tMovePoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
                            local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), tMovePoint)
                            local iFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oBomber)
                            if AiBotUtilities.GetAngleDifference(iAngleToRally, iFacingAngle) > 45 and not(oBomber[AiBotUnitInfo.refbEasyBrain]) then
                                ForkThread(AiBotMicro.TurnAirUnitAndMoveToTarget,oBomber, tMovePoint, 15, nil)
                                if bDebugMessages == true then LOG(sFunctionRef..': Doing micro turn to rally') end
                            else
                                AiBotOrders.IssueTrackedMove(oBomber, tMovePoint, 10, false, 'ExBIdle', false)
                            end
                        elseif bDebugMessages == true then LOG(sFunctionRef..': Want to go to rally but micro active so wont give new order')
                        end
                    end
                else
                    --Have targets for bomber, send orders for targeting - if enemy has dangerous AA then target the closest such AA, otherwise pick the target that will deal the most damage
                    bGivenDifOrderToReturnToRally = true

                    local oBestEnemyTarget
                    local iCurDamage
                    local iHighestDamage = 0
                    local aiBrain = oBomber:GetAIBrain()
                    local iBomberFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oBomber)
                    local iAngleDif

                    local tDangerousAATargets = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryGroundAA - categories.TECH1, tEnemyGroundTargets)
                    if AiBotUtilities.IsTableEmpty( tDangerousAATargets) == false then
                        --Only include if almost complete
                        local iCurDist, iModDist
                        local iDistOfBestTarget = 100000
                        local iAngleFromBomberToUnit
                        local iDistThresholdForFurtherAwayAA = 25
                        local iDamageThresholdForReducedDistance = 4000 --i.e. if cur target will deal at least this much damage value, then only consider other targets up to iReducedDistanceThreshold further away
                        local iReducedDistanceThreshold
                        if AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbFarBehindOnAir] then iReducedDistanceThreshold = 15 --i.e. if we are far behind on air then want to focus more on damage from the bomb we fire, as we are unlikely to survive to fire lots of bombs
                        else iReducedDistanceThreshold = 8
                        end
                        local iDamageFactorForFurtherAwayTarget = 1.5
                        if iTotalExpBombers >= 3 then
                            if iTotalExpBombers >= 4 then
                                iDamageFactorForFurtherAwayTarget = 1.25
                                iReducedDistanceThreshold = math.max(iReducedDistanceThreshold, math.min(iDistThresholdForFurtherAwayAA - 5, iReducedDistanceThreshold + 12))
                                iDamageThresholdForReducedDistance = iDamageThresholdForReducedDistance * 1.5
                            else
                                iDamageFactorForFurtherAwayTarget = 1.35
                                iReducedDistanceThreshold = math.max(iReducedDistanceThreshold, math.min(iDistThresholdForFurtherAwayAA - 4, iReducedDistanceThreshold + 8))
                                iDamageThresholdForReducedDistance = iDamageThresholdForReducedDistance * 1.3
                            end
                        end

                        for iUnit, oUnit in tDangerousAATargets do
                            if oUnit:GetFractionComplete() >= 0.8 then
                                --Add increase in distance if we arent facing the target
                                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oBomber:GetPosition())
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to target AA oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurDist='..iCurDist..'; iDistOfBestTarget='..iDistOfBestTarget) end
                                if iCurDist <= iDistOfBestTarget + iDistThresholdForFurtherAwayAA then
                                    iModDist = iCurDist
                                    iAngleFromBomberToUnit = AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), oUnit:GetPosition())
                                    iAngleDif = AiBotUtilities.GetAngleDifference(iBomberFacingAngle, iAngleFromBomberToUnit)
                                    if iAngleDif >= 15 then
                                        iModDist = iCurDist + (iAngleDif / 180) * 90
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': iAngleDif='..iAngleDif..'; iCurDist after angle adjustment='..iCurDist) end
                                    if iModDist <= iDistOfBestTarget + iDistThresholdForFurtherAwayAA then
                                        --Get damage from a bomb - increase by 400% for AA targets so will prioritise taking out enemy groundAA
                                        --GetDamageFromBomb(aiBrain, tBaseLocation,         iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, bCumulativeShieldHealthCheck, iOptionalSizeAdjust, iOptionalModIfNeedMultipleShots, iMobileValueOverrideFactorWithin75Percent, bT3ArtiShotReduction, iOptionalShieldReductionFactor, bIncludePreviouslySeenEnemies, iOptionalSpecialCategoryDamageFactor, iOptionalSpecialCategory, iOptionalReclaimFactor, bCheckIfUnderwater, iOptionalGunshipFactor)
                                        iCurDamage = AiBotLogic.GetDamageFromBomb(aiBrain, oUnit:GetPosition(), iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor,    nil,                            nil,                nil,                            iMobileUnitInnerDamageFactor,                nil,               iOptionalShieldReductionFactor,     true,                   4,                          AiBotUnitInfo.refCategoryGroundAA,        nil,                nil,                0.5)
                                        if bDebugMessages == true then LOG(sFunctionRef..': iCurDamage='..iCurDamage..'; iHighestDamage='..iHighestDamage..'; iModDist='..iModDist..'; iDistOfBestTarget='..iDistOfBestTarget) end
                                        if iModDist < iDistOfBestTarget - iDistThresholdForFurtherAwayAA or (iModDist < iDistOfBestTarget and iCurDamage >= iHighestDamage) or ((iModDist < iDistOfBestTarget + iReducedDistanceThreshold or iHighestDamage < iDamageThresholdForReducedDistance) and iCurDamage > iHighestDamage * iDamageFactorForFurtherAwayTarget) then
                                            --Do we think our  bomb will hit? if not, then reduce damage to 1% of current estimate
                                            local tEstFiringPosition
                                            if iCurDist <= oBomber[AiBotUnitInfo.refiBomberRange] then
                                                tEstFiringPosition = oBomber:GetPosition()
                                            else
                                                tEstFiringPosition = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), oUnit:GetPosition()), iCurDist - (oBomber[AiBotUnitInfo.refiBomberRange] or 30))
                                                tEstFiringPosition[2] = oBomber:GetPosition()[2]
                                            end
                                            if AiBotLogic.IsLineBlocked(aiBrain, tEstFiringPosition, oUnit:GetPosition(), iAOE) then
                                                oUnit[AiBotUnitInfo.refbExpBomberShotBlocked] = true
                                                iCurDamage = iCurDamage * 0.01
                                                if bDebugMessages == true then LOG(sFunctionRef..': Shot blocked so reducing damage to 1%, Bomber position='..repru(oBomber:GetPosition())..'; Unit position='..repru(oUnit:GetPosition())..'; iCurDist='..iCurDist..'; Angle to unit='..AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), oUnit:GetPosition())..'; Bomber range='..(oBomber[AiBotUnitInfo.refiBomberRange] or 'nil')) end
                                            else
                                                oUnit[AiBotUnitInfo.refbExpBomberShotBlocked] = false
                                            end
                                            if iCurDamage > iHighestDamage or (iModDist < iDistOfBestTarget and iCurDamage > iHighestDamage / iDamageFactorForFurtherAwayTarget) then
                                                iHighestDamage = iCurDamage
                                                oBestEnemyTarget = oUnit
                                                iDistOfBestTarget = iCurDist
                                                if bDebugMessages == true then LOG(sFunctionRef..': Recording unit as the newest best target, oUnit[AiBotUnitInfo.refbExpBomberShotBlocked]='..tostring(oUnit[AiBotUnitInfo.refbExpBomberShotBlocked])) end
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Finished considering if we have nearby dangerous groundAA that we want to target, is oBestEnemyTarget nil='..tostring(oBestEnemyTarget == nil)..'; iHighestDamage='..iHighestDamage..'; Bomber speed='..AiBotUnitInfo.GetUnitSpeed(oBomber)) end
                    if not(oBestEnemyTarget) or iHighestDamage <= 2000 then --we are multiplying AA value by 4, so this is equivalent to 1 T2 flak
                        for iUnit, oUnit in tEnemyGroundTargets do
                            --Pick the target that will deal the most damage
                            --GetDamageFromBomb(aiBrain, tBaseLocation,         iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, bCumulativeShieldHealthCheck, iOptionalSizeAdjust, iOptionalModIfNeedMultipleShots, iMobileValueOverrideFactorWithin75Percent, bT3ArtiShotReduction, iOptionalShieldReductionFactor, bIncludePreviouslySeenEnemies, iOptionalSpecialCategoryDamageFactor, iOptionalSpecialCategory, iOptionalReclaimFactor, bCheckIfUnderwater, iOptionalGunshipFactor)
                            iCurDamage = AiBotLogic.GetDamageFromBomb(aiBrain, oUnit:GetPosition(), iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor,    nil,                            nil,                nil,                            iMobileUnitInnerDamageFactor,                nil,               iOptionalShieldReductionFactor,     true, 4, AiBotUnitInfo.refCategoryGroundAA,nil,nil,0.5)
                            if bDebugMessages == true then LOG(sFunctionRef..': Damage if target unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'='..iCurDamage..'; iHighestDamage='..iHighestDamage) end
                            if iCurDamage > iHighestDamage then
                                iAngleDif = AiBotUtilities.GetAngleDifference(iBomberFacingAngle, AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), oUnit:GetPosition()))
                                if iAngleDif >= 15 then
                                    --Reudce value by up to 30% depending on how big a difference in bomber angle targets there is
                                    iCurDamage = iCurDamage * (1 - 0.3 * (iAngleDif / 180))
                                end
                                iHighestDamage = iCurDamage
                                oBestEnemyTarget = oUnit
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': oBestEnemyTarget='..(oBestEnemyTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oBestEnemyTarget) or 'nil')..'; iHighestDamage='..iHighestDamage)
                        if AiBotUnitInfo.IsUnitValid(oBestEnemyTarget) and AiBotUnitInfo.IsUnitValid(oBomber) then
                            LOG(sFunctionRef..': oBestEnemyTarget is valid, Dist to target='..AiBotUtilities.GetDistanceBetweenPositions(oBestEnemyTarget:GetPosition(), oBomber:GetPosition())..'; oBestEnemyTarget='..oBestEnemyTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBestEnemyTarget))
                        end
                    end
                    if AiBotUnitInfo.IsUnitValid(oBestEnemyTarget) then
                        --Units under heavy shield with AA - land the bomb so the aoe just hits the unit, unless have lots of experimental bombers nearby
                        local iDamageForIfUnderShield = iDamage - 1000
                        if iTotalExpBombers >= 2 and AiBotUtilities.IsTableEmpty(oBestEnemyTarget[AiBotBuilding.reftoShieldsProvidingCoverage]) == false then
                            local iNearbyBomberCount = 0
                            local tNearbyBombers = aiBrain:GetUnitsAroundPoint(categories.BOMBER * categories.EXPERIMENTAL, oBomber:GetPosition(), 100, 'Ally')
                            if AiBotUtilities.IsTableEmpty(tNearbyBombers) == false then
                                for iNearbyBomber, oNearbyBomber in tNearbyBombers do
                                    if oNearbyBomber == oBomber then
                                        iNearbyBomberCount = iNearbyBomberCount + 1
                                        --Include bombers who have fired recently
                                    elseif oNearbyBomber:GetFractionComplete() == 1 and GetGameTimeSeconds() - (oNearbyBomber[AiBotUnitInfo.refiLastWeaponEvent] or -100) <= 6 and oNearbyBomber[AiBotUnitInfo.refbSpecialMicroActive] then
                                        iNearbyBomberCount = iNearbyBomberCount + 1
                                    end
                                end
                            end
                            if iNearbyBomberCount >= 2 then
                                iDamageForIfUnderShield = math.max(1000, iDamage - 1000) + iDamage * (iNearbyBomberCount - 1)
                            end
                        end

                        local bUseAOEForTargetIfNotTooClose = false
                        local bGivenOrderAlready = false
                        local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oBestEnemyTarget:GetPosition(), oBomber:GetPosition())
                        local iAngleToTarget = AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), oBestEnemyTarget:GetPosition())
                        local iBomberFacingAngle = AiBotUnitInfo.GetUnitFacingAngle(oBomber)
                        local iAngleDifToTarget = AiBotUtilities.GetAngleDifference(iBomberFacingAngle, iAngleToTarget)
                        local iTimeUntilReadyToFire = AiBotUnitInfo.GetTimeUntilReadyToFireBomb(oBomber)
                        local iBomberSpeed = AiBotUnitInfo.GetUnitSpeed(oBomber)
                        if bDebugMessages == true then LOG(sFunctionRef..': Dist to target='..AiBotUtilities.GetDistanceBetweenPositions(oBestEnemyTarget:GetPosition(), oBomber:GetPosition())..'; Unit facing angle='..AiBotUnitInfo.GetUnitFacingAngle(oBomber)..'; Angle to target='..AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), oBestEnemyTarget:GetPosition())..'; oBomber[refiTimeBetweenBombs]='..(oBomber[AiBotUnitInfo.refiTimeBetweenBombs] or 'nil')..'; Bomber range='..oBomber[AiBotUnitInfo.refiBomberRange]..'; Bomber speed='..AiBotUnitInfo.GetUnitSpeed(oBomber)..'; iTimeUntilReadyToFire='..iTimeUntilReadyToFire) end

                        --If bomber is facing the wrong direction and isnt that far from the target, and is ready to fire, then consider using micro to turn around and fire at it
                        if iDistToTarget <= 85 and iAngleDifToTarget > 30 and (iTimeUntilReadyToFire <= 0 or (iDistToTarget <= 60 and iTimeUntilReadyToFire <= 5 and (iDistToTarget <= 40 or iTimeUntilReadyToFire <= 3))) and not(oBomber[AiBotUnitInfo.refbEasyBrain]) then
                            --Want to turn to face the target and shoot it
                            if bDebugMessages == true then LOG(sFunctionRef..': Will use micro to turn where we are to fire a bomb at oBestEnemyTarget='..oBestEnemyTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBestEnemyTarget)) end
                            ForkThread(AiBotMicro.TurnAirUnitAndAttackTarget, oBomber, oBestEnemyTarget)
                            bGivenOrderAlready = true
                            --If we are already in range of the target, at the right angle, but moving very fast, then hover to slow down and then attack
                            --One example of this - bomber angle =226.13159179688; Angle to target=218.21295166016; Bomber speed=25.403442382813; Dist to target=38.182476043701; We wouldnt fire the bomb
                        elseif iDistToTarget < (oBomber[AiBotUnitInfo.refiBomberRange] or 0) - 10 and iAngleDifToTarget <= 15 and iBomberSpeed >= 15 and iTimeUntilReadyToFire <= -2 then
                            --If we are still close to being in range then try and adjust the target
                            if iDistToTarget - iBomberSpeed > (oBomber[AiBotUnitInfo.refiBomberRange] or 0) - iAOE + 3 then
                                local tPotentialGroundFireTarget = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iBomberFacingAngle, iDistToTarget + iAOE - 3, true)
                                if tPotentialGroundFireTarget and AiBotUtilities.GetDistanceBetweenPositions(tPotentialGroundFireTarget, oBestEnemyTarget:GetPosition()) < iAOE then
                                    bGivenOrderAlready = true
                                    AiBotOrders.IssueTrackedGroundAttack(oBomber, tPotentialGroundFireTarget, 1, false, 'TooCloseGrndFr', false, oBestEnemyTarget)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will try and ground fire to hit the unit') end
                                end
                            end
                            if not(bGivenOrderAlready) then
                                --Just fire the bomb if it will do some damage; otherwise abort
                                local tFiringAtBomberRange = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iBomberFacingAngle, (oBomber[AiBotUnitInfo.refiBomberRange] or 30) - 0.5, true)
                                if tFiringAtBomberRange then
                                    --Get damage, assuming we ignore any shields (by treating damage as 100k)
                                    --GetDamageFromBomb(aiBrain, tBaseLocation, iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, bCumulativeShieldHealthCheck, iOptionalSizeAdjust, iOptionalModIfNeedMultipleShots, iMobileValueOverrideFactorWithin75Percent, bT3ArtiShotReduction, iOptionalShieldReductionFactor, bIncludePreviouslySeenEnemies, iOptionalSpecialCategoryDamageFactor, iOptionalSpecialCategory, iOptionalReclaimFactor, bCheckIfUnderwater)
                                    local iDamageFromNewTarget = AiBotLogic.GetDamageFromBomb(aiBrain, tFiringAtBomberRange, iAOE, 100000, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor,    nil,                            nil,                nil,                            iMobileUnitInnerDamageFactor,                nil,               iOptionalShieldReductionFactor,     true, 4, AiBotUnitInfo.refCategoryGroundAA)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Damage if dealt 100k at bombers current range='..iDamageFromNewTarget) end
                                    if iDamageFromNewTarget > 0 then
                                        bGivenOrderAlready = true
                                        AiBotOrders.IssueTrackedGroundAttack(oBomber, tFiringAtBomberRange, 1, false, 'TooCloseGndFr', false, oBestEnemyTarget)
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will just try and fire our bomb so we can t urn around and abort') end
                                    else
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will abort target and turn around') end
                                        if not(oBomber[AiBotUnitInfo.refbEasyBrain]) then
                                            bGivenOrderAlready = true
                                            ForkThread(AiBotMicro.TurnAirUnitAndMoveToTarget, oBomber, AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint], 15, 3)
                                        end
                                    end
                                end
                            end
                        else
                            if bDebugMessages == true then LOG(sFunctionRef..': Deciding whether to make use of bomber AOE, bHaveTargetWhereShotIsBlocked='..tostring(bHaveTargetWhereShotIsBlocked or false)..'; Is target under shield='..tostring(AiBotLogic.IsTargetUnderShield(aiBrain, oBestEnemyTarget, iDamageForIfUnderShield, false, true, false, false))..'; iTotalExpBombers='..iTotalExpBombers..'; [AiBotUnitInfo.refbExpBomberShotBlocked]='..tostring(oBestEnemyTarget[AiBotUnitInfo.refbExpBomberShotBlocked] or false)) end
                            if not(bHaveTargetWhereShotIsBlocked) and AiBotLogic.IsTargetUnderShield(aiBrain, oBestEnemyTarget, iDamageForIfUnderShield, false, true, false, false) then
                                bUseAOEForTargetIfNotTooClose = true
                                --If only have 1 exp bomber and targeting a fixed unit be more cautious if significant enemy groundAA threat near the target
                            elseif not(bHaveTargetWhereShotIsBlocked) and iTotalExpBombers <= 2 and (iTotalExpBombers <= 1 or iHighestDamage <= 20000) and (EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oBestEnemyTarget.UnitId) or (oBestEnemyTarget[refiExpBomberShotCount] or 0) <= 1) then
                                local iTargetPlateau, iTargetZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oBestEnemyTarget:GetPosition())
                                if iTargetZone then
                                    local tTargetLZOrWZData
                                    local tTargetLZOrWZTeamData
                                    if (iTargetPlateau or 0) == 0 then
                                        tTargetLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iTargetZone]][AiBotMap.subrefPondWaterZones][iTargetZone]
                                        tTargetLZOrWZTeamData = tTargetLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                                    else
                                        tTargetLZOrWZData = AiBotMap.tAllPlateaus[iTargetPlateau][AiBotMap.subrefPlateauLandZones][iTargetZone]
                                        tTargetLZOrWZTeamData = tTargetLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                                    end

                                    if bDebugMessages == true then LOG(sFunctionRef..': Only have 1 exp bomber, target is unshielded, but will consider if ground AA threat so great we want to do aoe attack on the AOE, (tTargetLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)='..(tTargetLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)..'; iTargetPlateau='..(iTargetPlateau or 'nil')..'; iTargetZone='..(iTargetZone or 'nil')) end
                                    if (tTargetLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) >= 4500 * iTotalExpBombers then --Equiv of x.3 SAMs per bomber
                                        bUseAOEForTargetIfNotTooClose = true
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will use aoe to attack target due to significant enemy ground threat') end
                                    end
                                end
                            end
                            if not(bUseAOEForTargetIfNotTooClose) and bHaveTargetWhereShotIsBlocked and not(oBestEnemyTarget[AiBotUnitInfo.refbExpBomberShotBlocked]) and AiBotUtilities.IsTableEmpty(oBestEnemyTarget[AiBotBuilding.reftoShieldsProvidingCoverage]) == false and iTotalExpBombers <= 2 and EntityCategoryContains(AiBotUnitInfo.refCategoryStructureAA, oBestEnemyTarget.UnitId) then
                                bUseAOEForTargetIfNotTooClose = true
                            end
                            if bUseAOEForTargetIfNotTooClose then
                                if iDistToTarget >= 40 then
                                    --Just try to target the unit with our aoe, provided there aren't friendly units near it
                                    local iMinValueWanted = 0
                                    local tTarget
                                    --If only have 1 bomber and target is a SAM under fixed shields, then consider choosing a ground fire location that damages the shield but is further away from the AA
                                    if iTotalExpBombers <= 2 and EntityCategoryContains(AiBotUnitInfo.refCategoryStructureAA * categories.TECH3, oBestEnemyTarget.UnitId) and AiBotUtilities.IsTableEmpty(oBestEnemyTarget[AiBotBuilding.reftoShieldsProvidingCoverage]) == false then
                                        local iMinShieldExtendDistance = 1000
                                        local iAngleFromTargetToBomber = AiBotUtilities.GetAngleFromAToB(oBestEnemyTarget:GetPosition(), oBomber:GetPosition())
                                        local iAngleFromTargetToShield, iDistFromTargetToShield
                                        local iRadianAngleA, iRadianAngleB, iRadianAngleC
                                        local iShieldRadius, iDistFromShieldToBomberPath
                                        local oFurthestShieldForDebug
                                        for iShield, oShield in oBestEnemyTarget[AiBotBuilding.reftoShieldsProvidingCoverage] do
                                            if AiBotUnitInfo.IsUnitValid(oShield) and oShield.MyShield.GetHealth and oShield.MyShield:GetHealth() >= iDamage - 500 then
                                                --Enemy shield can likely absorb our full bomb blast, so no point getting too close to the enemy; want to do a triangle between the shield, the target, and the bomber, so if move along the line from the target to the bomber we find the point at which we need the aoe to hit, and then we increase the dist to travel a bit more than this
                                                iAngleFromTargetToShield = AiBotUtilities.GetAngleFromAToB(oBestEnemyTarget:GetPosition(), oShield:GetPosition())
                                                iDistFromTargetToShield = AiBotUtilities.GetDistanceBetweenPositions(oBestEnemyTarget:GetPosition(), oShield:GetPosition())
                                                iShieldRadius = (oShield:GetBlueprint().Defense.Shield.ShieldSize or 13) * 0.5
                                                if iAngleFromTargetToShield > iAngleFromTargetToBomber then iRadianAngleA = AiBotUtilities.ConvertAngleToRadians(iAngleFromTargetToShield - iAngleFromTargetToBomber)
                                                else iRadianAngleA = AiBotUtilities.ConvertAngleToRadians(iAngleFromTargetToBomber - iAngleFromTargetToShield)
                                                end
                                                iRadianAngleB = math.asin(iDistFromTargetToShield * math.sin(iRadianAngleA)/iShieldRadius)
                                                iRadianAngleC = 180 - AiBotUtilities.ConvertRadiansToAngle(iRadianAngleA) - AiBotUtilities.ConvertRadiansToAngle(iRadianAngleB)
                                                iDistFromShieldToBomberPath = math.sqrt(iShieldRadius * iShieldRadius + iDistFromTargetToShield * iDistFromTargetToShield - 2 * iDistFromTargetToShield * iShieldRadius * math.cos(iRadianAngleC))
                                                if iMinShieldExtendDistance > iDistFromShieldToBomberPath then
                                                    iMinShieldExtendDistance = iDistFromShieldToBomberPath
                                                    if bDebugMessages == true then oFurthestShieldForDebug = oShield end
                                                end
                                                if bDebugMessages == true then LOG(sFunctionRef..': Considering shield '..oShield.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oShield)..'; Shield health='..oShield.MyShield:GetHealth()..'; iShieldRadius='..iShieldRadius..'; iDistFromTargetToShield='..iDistFromTargetToShield..'; iAngleFromTargetToShield='..iAngleFromTargetToShield..'; AngleA='..AiBotUtilities.ConvertRadiansToAngle(iRadianAngleA)..'; AngleB='..AiBotUtilities.ConvertRadiansToAngle(iRadianAngleB)..'; AngleC='..AiBotUtilities.ConvertRadiansToAngle(iRadianAngleC)..'; iDistFromShieldToBomberPath='..iDistFromShieldToBomberPath) end
                                            end
                                        end
                                        if iMinShieldExtendDistance >= 2 and iMinShieldExtendDistance <= 50 then
                                            tTarget = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), oBestEnemyTarget:GetPosition()), math.max(1, iDistToTarget - iAOE + math.max(iAOE * 0.1, 3) -math.max(0, math.min(iMinShieldExtendDistance - 3, iMinShieldExtendDistance * 0.8, 12))), true, false, true)
                                            if iTotalExpBombers == 1 then iMinValueWanted = -300 end --i.e. we will be damaging an enemy shield, which may well be covering significant enemy forces, so we can accept a small amount of friendly fire (as the bomb itself could register as 0 damage since in theory it is hitting nothing - only the shield bubble)

                                            if bDebugMessages == true then
                                                LOG(sFunctionRef..': tTarget to try and hit the shield aoe='..repru(tTarget)..'; oFurthestShieldForDebug='..oFurthestShieldForDebug.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFurthestShieldForDebug)..'; Dist from target to shield='..AiBotUtilities.GetDistanceBetweenPositions(oFurthestShieldForDebug:GetPosition(), tTarget)..'; Dist from tTarget to enemy target='..AiBotUtilities.GetDistanceBetweenPositions(tTarget, oBestEnemyTarget:GetPosition()))
                                                --AiBotUtilities.DrawPath({ oFurthestShieldForDebug:GetPosition(), oBestEnemyTarget:GetPosition(), AiBotUtilities.MoveInDirection(oBestEnemyTarget:GetPosition(), AiBotUtilities.GetAngleFromAToB(oBestEnemyTarget:GetPosition(), oBomber:GetPosition()), iMinShieldExtendDistance, true, false, true) })
                                            end
                                            --Check shot not blocked
                                            local tEstFiringPosition
                                            local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(tTarget, oBomber:GetPosition())
                                            if iDistToTarget <= oBomber[AiBotUnitInfo.refiBomberRange] then
                                                tEstFiringPosition = oBomber:GetPosition()
                                            else
                                                tEstFiringPosition = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), tTarget), iDistToTarget - (oBomber[AiBotUnitInfo.refiBomberRange] or 30))
                                                tEstFiringPosition[2] = oBomber:GetPosition()[2]
                                            end
                                            if AiBotLogic.IsLineBlocked(aiBrain, tEstFiringPosition, tTarget, iAOE) then
                                                if bDebugMessages == true then LOG(sFunctionRef..': Planned shield AOE position is blocked, will just target the enemy directly') end
                                                tTarget = oBestEnemyTarget:GetPosition()
                                            end
                                        end
                                    end
                                    local iInsideAOEWanted
                                    if EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oBestEnemyTarget.UnitId) then iInsideAOEWanted = math.max(iAOE * 0.1, 3)
                                    else iInsideAOEWanted = math.max(iAOE * 0.2, 6) * (1 + (oBestEnemyTarget[refiExpBomberShotCount] or 0))
                                    end
                                    if not(tTarget) then tTarget = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), oBestEnemyTarget:GetPosition()), iDistToTarget - iAOE + iInsideAOEWanted, true, false, true) end
                                    --Double-check we wont damage friendly units as a result (have done >= 0 in case we dont think we are dealing any damage due to only damage being to shields)
                                    if AiBotLogic.GetDamageFromBomb(aiBrain, tTarget, iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor,    nil,                            nil,                nil,                            iMobileUnitInnerDamageFactor,                nil,               iOptionalShieldReductionFactor,     true, 4, AiBotUnitInfo.refCategoryGroundAA,nil,nil,0.5) >= iMinValueWanted then
                                        AiBotOrders.IssueTrackedGroundAttack(oBomber, tTarget, iAOE * 0.5, false, 'ExpAG', false, oBestEnemyTarget)
                                        bGivenOrderAlready = true
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if we want to ground fire near the shielded target, tTarget='..repru(tTarget)..'; bUseAOEForTargetIfNotTooClose='..tostring(bUseAOEForTargetIfNotTooClose)..'; Damage from bomb='..AiBotLogic.GetDamageFromBomb(aiBrain, tTarget, iAOE, iDamage, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor,    nil,                            nil,                nil,                            iMobileUnitInnerDamageFactor,                nil,               iOptionalShieldReductionFactor,     true, 4, AiBotUnitInfo.refCategoryGroundAA)..'; iMinValueWanted='..iMinValueWanted..'; iInsideAOEWanted='..iInsideAOEWanted..'; oBestEnemyTarget[refiExpBomberShotCount]='..(oBestEnemyTarget[refiExpBomberShotCount] or 'nil')) end
                                else
                                    bUseAOEForTargetIfNotTooClose = false
                                    if bDebugMessages == true then LOG(sFunctionRef..': Target is too close to bomber so wont use aoe attack') end
                                end
                            end
                        end

                        if not(bGivenOrderAlready) then
                            if bDebugMessages == true then LOG(sFunctionRef..': Will ground fire the location that deals the most damage if targeting a structure, is the target a structure='..tostring(EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oBestEnemyTarget.UnitId))) end
                            --Structures - get best aoe target
                            if not(bHaveTargetWhereShotIsBlocked) and EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oBestEnemyTarget.UnitId) then
                                local tTarget = AiBotLogic.GetBestAOETarget(oBomber:GetAIBrain(), oBestEnemyTarget:GetPosition(), iAOE, iDamage, false, nil, nil, nil, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, nil, iMobileUnitInnerDamageFactor, iOptionalShieldReductionFactor)
                                if bDebugMessages == true then LOG(sFunctionRef..': Best AOE target='..repru(tTarget)..'; Angle to this='..AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), tTarget)..'; Dist to this='..AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tTarget)) end
                                AiBotOrders.IssueTrackedGroundAttack(oBomber, tTarget, iAOE * 0.5, false, 'ExpAG', false)
                            elseif AiBotUnitInfo.IsUnitUnderwater(oBestEnemyTarget) or EntityCategoryContains(categories.AIR * categories.MOBILE, oBestEnemyTarget.UnitId) then
                                AiBotOrders.IssueTrackedGroundAttack(oBomber, oBestEnemyTarget:GetPosition(), iAOE * 0.5, false, 'ExpAG', false)
                                if bDebugMessages == true then LOG(sFunctionRef..': Attacking underwater target so will ground fire it') end
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Will attack the unit itself') end
                                AiBotOrders.IssueTrackedAttack(oBomber, oBestEnemyTarget, false, 'ExpAU', false)
                            end
                        end
                    end
                end

                iCurBomberPerTick = iCurBomberPerTick + 1
                if iCurBomberPerTick >= iBombersPerTick then
                    iCurBomberPerTick = 0
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitTicks(1)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                end
            end
        end
        --Consider skipping the next cycle
        if iTotalExpBombers >= 5 or (iTotalExpBombers >= 3 and AiBotUtilities.bCPUPerformanceMode) then
            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoRecentExpBomberAttackOrders] = true
        elseif bGivenDifOrderToReturnToRally or iTotalExpBombers <= 2 then
            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoRecentExpBomberAttackOrders] = false
        else
            AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.refbNoRecentExpBomberAttackOrders] = true
        end
    end
    AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurExpBomberThreat] = iOurExpBomberThreat


    --Send retreating bombers to rally
    if AiBotUtilities.IsTableEmpty(tBombersForRetreating) == false then
        for iBomber, oBomber in tBombersForRetreating do
            if AiBotUnitInfo.IsUnitValid(oBomber) then
                local tMovePoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
                AiBotOrders.IssueTrackedMove(oBomber, tMovePoint, 10, false, 'ExBRetr', false)
            end
        end
    end

    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GiveOrderToSpaceship(iTeam, oUnit)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GiveOrderToSpaceship'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oUnit) then
        local aiBrain = oUnit:GetAIBrain()
        --Retreat if have shield and low shield
        local iCurShield, iMaxShield = AiBotUnitInfo.GetCurrentAndMaximumShield(oUnit, true)
        local iCheckForSMDBuildDelay = 120 --Normally will try and kill newly constructed SMD if not low health
        local iSMDRangeMod = 10
        local bRunIfNoTarget = false
        if iMaxShield > 0 and iCurShield / iMaxShield < 0.5 then
            --Retreat if nearby SMD
            bRunIfNoTarget = true
            iCheckForSMDBuildDelay = 60
            iSMDRangeMod = 30
            if iCurShield / iMaxShield < 0.1 or AiBotUnitInfo.GetUnitHealthPercent(oUnit) < 1 then
                iCheckForSMDBuildDelay = 0
                iSMDRangeMod = 50
            end
        end

        --First get current location - if not valid, then continue with last order (unless we are almost at destination, in which case switch toa ttack-move, and then if very close return to base)
        local tStartLZOrWZData, tStartLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, iTeam)
        local bConsiderBackupOrder = false
        --If this is a valid plateau+LZ then look for a target:
        if not(tStartLZOrWZTeamData) then
            bConsiderBackupOrder = true
        else
            --Find nearest significant enemy building that isnt underwater and attack it:
            RecordOtherLandAndWaterZonesByDistance(tStartLZOrWZData)
            if AiBotUtilities.IsTableEmpty(tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance]) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': About to cycle through each other zone by distance and consider the best target') end
                local tGroundTarget
                local iHighestStructureZoneMass = 0
                local iCurDamage, tCurTarget, oBestTarget
                local iBestDamage = 0
                local iAOE, iDamage = AiBotUnitInfo.GetBomberAOEAndStrikeDamage(oUnit)
                local bNoSMDToAvoid = true
                for iEntry, tSubtable in tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                    local tOtherZoneLZOrWZData
                    local tOtherZoneLZOrWZTeamData
                    if tSubtable[AiBotMap.subrefbIsWaterZone] then
                        tOtherZoneLZOrWZData = AiBotMap.tPondDetails[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPondWaterZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                        tOtherZoneLZOrWZTeamData = tOtherZoneLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                    else
                        tOtherZoneLZOrWZData = AiBotMap.tAllPlateaus[tSubtable[AiBotMap.subrefiPlateauOrPond]][AiBotMap.subrefPlateauLandZones][tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]]
                        tOtherZoneLZOrWZTeamData = tOtherZoneLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                    end

                    if (tOtherZoneLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass] or 0) > iHighestStructureZoneMass then
                        --Check for a high mass building to target that isnt underwater (if dealing with water zone)
                        if AiBotUtilities.IsTableEmpty(tOtherZoneLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                            local tEnemyBuildings = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryStructure, tOtherZoneLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])
                            if AiBotUtilities.IsTableEmpty(tEnemyBuildings) == false then
                                --Is there SMD covering hte midpoint of this zone?
                                bNoSMDToAvoid = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Checking if there is SMD that would prevent us targeting target zone PlatOrPond='..tSubtable[AiBotMap.subrefiPlateauOrPond]..'; Zone='..tSubtable[AiBotMap.subrefiLandOrWaterZoneRef]..'; Is SMD blocking='..tostring(AiBotBuilding.IsSMDBlockingTarget(aiBrain, tOtherZoneLZOrWZData[AiBotMap.subrefMidpoint], oUnit:GetPosition(), 240, 80, false))) end
                                if AiBotBuilding.IsSMDBlockingTarget(aiBrain, tOtherZoneLZOrWZData[AiBotMap.subrefMidpoint], oUnit:GetPosition(), iCheckForSMDBuildDelay, iSMDRangeMod, false) then
                                    bNoSMDToAvoid = false
                                end
                                if bNoSMDToAvoid then
                                    for iBuilding, oBuilding in tEnemyBuildings do
                                        if not(oBuilding.Dead) and AiBotUnitInfo.GetUnitMassCost(oBuilding) >= 100 and (not(tSubtable[AiBotMap.subrefbIsWaterZone]) or not(AiBotUnitInfo.IsUnitUnderwater(oUnit))) then
                                            --GetBestAOETarget(aiBrain, tBaseLocation, iAOE, iDamage, bOptionalCheckForSMD, tSMLLocationForSMDCheck, iOptionalTimeSMDNeedsToHaveBeenBuiltFor, iSMDRangeAdjust, iFriendlyUnitDamageReductionFactor, iFriendlyUnitAOEFactor, iOptionalMaxDistanceCheckOptions, iMobileValueOverrideFactorWithin75Percent, iOptionalShieldReductionFactor, iOptionalReclaimFactor)
                                            tCurTarget, iCurDamage = AiBotLogic.GetBestAOETarget(aiBrain, oBuilding:GetPosition(), iAOE, iDamage, false, nil, nil, nil, 0, 0, nil, nil, nil, nil)
                                            if iCurDamage > iBestDamage then
                                                iBestDamage = iCurDamage
                                                tGroundTarget = {tCurTarget[1], tCurTarget[2], tCurTarget[3]}
                                                oBestTarget = oBuilding
                                            end
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to target oBuilding='..oBuilding.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBuilding)..'; Mass cost='..AiBotUnitInfo.GetUnitMassCost(oBuilding)..'; iDamage='..iDamage..'; iBestDamage='..iBestDamage) end
                                        end
                                    end
                                    iHighestStructureZoneMass = tOtherZoneLZOrWZTeamData[AiBotMap.subrefThreatEnemyStructureTotalMass]
                                    if iHighestStructureZoneMass >= 2000 and tGroundTarget and iBestDamage > 0 then break end
                                end
                            end
                        end

                    end
                end
                if tGroundTarget then
                    local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tGroundTarget)
                    if bDebugMessages == true then LOG(sFunctionRef..': Have a target, iDistToTarget='..iDistToTarget..'; Unit DF range='..(oUnit[AiBotUnitInfo.refiDFRange] or 0)..'; iAOE='..iAOE..'; iDamage='..iDamage) end
                    if iDistToTarget <= math.max(30, (oUnit[AiBotUnitInfo.refiDFRange] or 0) + 5) then
                        AiBotOrders.IssueTrackedGroundAttack(oUnit, tGroundTarget, 1, false, 'SpcshAG', false, oBestTarget)
                    else
                        AiBotOrders.IssueTrackedMove(oUnit, tGroundTarget, 5, false, 'SpcshMv', false)
                    end
                else
                    bConsiderBackupOrder = true
                end
            else
                bConsiderBackupOrder = true
            end
        end
        if bConsiderBackupOrder then
            if bRunIfNoTarget then
                --Retreat to rally point
                if bDebugMessages == true then LOG(sFunctionRef..': Will retreat so can heal up') end
                AiBotOrders.IssueTrackedMove(oUnit, AiBotTeam.tAirSubteamData[oUnit:GetAIBrain().AiBotAirSubteam][AiBotTeam.reftAirRallyPoint], 5, false, 'SpcshRt', false)
            else
                local tLastOrderPosition = oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition]
                if AiBotUtilities.IsTableEmpty(tLastOrderPosition) or AiBotUtilities.GetDistanceBetweenPositions(tLastOrderPosition, oUnit:GetPosition()) <= 10 then
                    --Go to enemy base
                    AiBotOrders.IssueTrackedAttackMove(oUnit, AiBotMap.GetPrimaryEnemyBaseLocation(oUnit:GetAIBrain()), 5, false, 'SpcshEnB', false)
                else
                    --Just let it continue with last order
                end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ManageSpaceship(iTeam, oUnit)
    while AiBotUnitInfo.IsUnitValid(oUnit) do
        ForkThread(GiveOrderToSpaceship, iTeam, oUnit)
        WaitTicks(AiBotLand.iTicksPerLandCycle)
    end
end


function ManageOtherAir(iTeam, iAirSubteam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ManageOtherAir'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    local tAvailableBombers, tBombersForRefueling, tUnavailableUnits = GetAvailableLowFuelAndInUseAirUnits(iTeam, iAirSubteam, AiBotUnitInfo.refCategoryMercy)

    if AiBotUtilities.IsTableEmpty(tAvailableBombers) == false then
        --Simple logic for now as placeholder in case we get given bombers - attack nearest enemy to rally point in up to a 300 range

        local aiBrain
        for iBrain, oBrain in AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains] do
            aiBrain = oBrain
            break
        end
        local tRallyPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
        local tNearbyEnemyUnits = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryLandExperimental + AiBotUnitInfo.refCategoryStructure - categories.TECH1 + categories.COMMAND, tRallyPoint, 300, 'Enemy')
        if AiBotUtilities.IsTableEmpty(tNearbyEnemyUnits) == false then
            local iClosestUnitDist = 10000
            local oClosestUnit
            local iCurDist

            for iUnit, oUnit in tNearbyEnemyUnits do
                if oUnit:GetFractionComplete() >= 0.8 and not(oUnit:IsUnitState('Attached')) and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) then
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, oUnit:GetPosition())
                    if iCurDist < iClosestUnitDist then
                        iClosestUnitDist = iCurDist
                        oClosestUnit = oUnit
                    end
                end
            end
            if oClosestUnit then
                for iBomber, oBomber in tAvailableBombers do
                    AiBotOrders.IssueTrackedAttack(oBomber, oClosestUnit, false, 'PlaceholderMA', false)
                end
            end
        end
    end

    --Send units for refueling
    if bDebugMessages == true then LOG(sFunctionRef..': Finished giving bomber orders, is table of air for refueling empty='..tostring(AiBotUtilities.IsTableEmpty(tBombersForRefueling))) end
    --Run the function even if no units wanting refueling so already attached untis can be sent on their way
    SendUnitsForRefueling(tBombersForRefueling, iTeam, iAirSubteam)
    if bDebugMessages == true and AiBotUtilities.IsTableEmpty(tBombersForRefueling) == false then
        LOG(sFunctionRef..': Will send '..table.getn(tBombersForRefueling)..' units to refuel')
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DelayedNovaxUnloadCheck(oUnit)
    --Redundancy to try and ensure a satellite is launched
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DelayedNovaxUnloadCheck'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if oUnit.Satellite then
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        function CheckAndReleaseIfRelevant()
            if bDebugMessages == true then LOG(sFunctionRef..': Checking for novax '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at time='..GetGameTimeSeconds()..'; reprs='..reprs(oUnit)) end
            if oUnit.Satellite and AiBotUnitInfo.IsUnitValid(oUnit.Satellite) then
                DetachSatellite(oUnit.Satellite, nil)
            end

        end
        if AiBotUnitInfo.IsUnitValid(oUnit) then
            if not(oUnit[refbActiveNovaxUnloadCheck]) then
                oUnit[refbActiveNovaxUnloadCheck] = true
                while AiBotUnitInfo.IsUnitValid(oUnit) do
                    CheckAndReleaseIfRelevant()
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitSeconds(30)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                end
            else
                --Check as a 1-off
                CheckAndReleaseIfRelevant()
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function DetachSatellite(oNovaxSatellite, iOptionalDelayInSeconds)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'DetachSatellite'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if (iOptionalDelayInSeconds or 0) > 0 then
        WaitSeconds(iOptionalDelayInSeconds)
    end
    if AiBotUnitInfo.IsUnitValid(oNovaxSatellite) then
        if bDebugMessages == true then LOG(sFunctionRef..': Unit state of satellite='..AiBotUnitInfo.GetUnitState(oNovaxSatellite)..'; Time='..GetGameTimeSeconds()) end
        if oNovaxSatellite:IsUnitState('Attached') then
            oNovaxSatellite:DetachFrom()
            local tMoveLocation = oNovaxSatellite:GetPosition()
            tMoveLocation[1] = tMoveLocation[1] - 1
            tMoveLocation[3] = tMoveLocation[3] - 1
            tMoveLocation[2] = GetSurfaceHeight(tMoveLocation[1], tMoveLocation[3])
            IssueMove({oNovaxSatellite}, tMoveLocation)
            oNovaxSatellite:Open()
        end
        --self.Satellite:DetachFrom()
        --IssueToUnitMove(self.Satellite, self:GetRallyPoint())
        --self.Satellite:Open()
    end
end

function ConsiderRecordingStratBomberToSuicideInto(oBomber, bBomberKilledMex)
    --E.g. if enemy strat bomber fires a bomb, and we dont have it recorded as a 'suicide into' target, consider adding it
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderRecordingStratBomberToSuicideInto'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(oBomber[refiAssignedSuicideASF]) then
        --Is bomber on our side of the map, or we have air control, or did ut kill a mex?
        if bDebugMessages == true then LOG(sFunctionRef..': Considering bomber '..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..' owned by brain '..oBomber:GetAIBrain().Nickname..'; bBomberKilledMex='..tostring(bBomberKilledMex or false)..'; Our AirAA='..AiBotTeam.tTeamData[oBomber:GetAIBrain().AiBotTeam][AiBotTeam.subrefiOurAirAAThreat]..'; Time='..GetGameTimeSeconds()) end
        local iBomberTeam = oBomber:GetAIBrain().AiBotTeam
        local bHaveNoAiBotEnemies = true
        local tbTeamsConsidered = {}
        local bIncludeForAirSubteam
        for iBrain, oBrain in AiBotOverseer.tAllActiveAiBotBrains do
            if not(oBrain.AiBotTeam == iBomberTeam) then
                bHaveNoAiBotEnemies = false
                if not(tbTeamsConsidered[oBrain.AiBotTeam]) then
                    tbTeamsConsidered[oBrain.AiBotTeam] = true

                    --How close is the bomber to closest friendly base vs closest enemy base?
                    bIncludeForAirSubteam = false
                    if bBomberKilledMex then
                        bIncludeForAirSubteam = true
                    else
                        --Is the bomber on our side of the map or about to go onto our side?
                        local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oBomber:GetPosition(), true, oBrain.AiBotTeam)
                        if tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.5 then
                            bIncludeForAirSubteam = true
                        elseif tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.65 and (((tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) + (tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) < 800 and AiBotTeam.tAirSubteamData[oBrain.AiBotAirSubteam][AiBotTeam.refbHaveAirControl])) or
                                (tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.6 and (AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subrefiOurAirAAThreat] >= 10000 or (tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.55 and AiBotTeam.tTeamData[oBrain.AiBotTeam][AiBotTeam.subrefiOurAirAAThreat] >= 5000 and AiBotUtilities.GetAngleDifference(AiBotUnitInfo.GetUnitFacingAngle(oBomber), AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase])) <= 50))) then
                            bIncludeForAirSubteam = true
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Mod dist%='..tLZOrWZTeamData[AiBotMap.refiModDistancePercent]..'; Enemy groundAA='..(tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) + (tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0)..'; Have air control='..tostring(AiBotTeam.tAirSubteamData[oBrain.AiBotAirSubteam][AiBotTeam.refbHaveAirControl])..'; bIncludeForAirSubteam='..tostring(bIncludeForAirSubteam)) end
                    end
                    if bIncludeForAirSubteam then
                        if bDebugMessages == true then LOG(sFunctionRef..': Will add bomber to potential suicide targets') end
                        AddBomberToPotentialSuicideTargets(oBomber, oBrain.AiBotTeam)
                    end
                end
            end
        end
        if bHaveNoAiBotEnemies then
            oBomber[refiAssignedSuicideASF] = 0 --Dont want to consider this logic again
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AddBomberToPotentialSuicideTargets(oBomber, iTeam)
    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSuicideTargets]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSuicideTargets] = {} end
    table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSuicideTargets], oBomber)
end

function AssignASFsToEnemyStrats(tAvailableAirAA, iTeam, iAirSubteam)
    --Checks if we have any asfs or swifties in tAvailableAirAA, and if so assigns them to target enemy strats
    local toASFs = EntityCategoryFilterDown(categories.TECH2 + categories.TECH3, tAvailableAirAA)

    if AiBotUtilities.IsTableEmpty(toASFs) == false then
        --For simplicity will just consider the closest enemy strat (since we will be running this logic every second if we have more available asfs)
        local oClosestStratToRallyPoint
        local iCurDist
        local iClosestDist = 10000
        local tRally = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
        for iStrat, oStrat in AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSuicideTargets] do
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tRally, oStrat:GetPosition())
            if iCurDist < iClosestDist then
                iClosestDist = iCurDist
                oClosestStratToRallyPoint = oStrat
            end
        end
        --Get closest (available) asfs to the strat
        local iClosest1Dist = 10000
        local iClosest2Dist = 10000
        local oClosest1, oClosest2
        for iUnit, oUnit in toASFs do
            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oClosestStratToRallyPoint:GetPosition(), oUnit:GetPosition())
            if iCurDist < iClosest2Dist then
                if iCurDist < iClosest1Dist then
                    iClosest2Dist = iClosest1Dist
                    oClosest2 = oClosest1
                    iClosest1Dist = iCurDist
                    oClosest1 = oUnit
                else
                    oClosest2 = oUnit
                    iClosest2Dist = iCurDist
                end
            end
        end


        if oClosestStratToRallyPoint[refiAssignedSuicideASF] < 1 and oClosest2 then
            --Assign both asfs
            ForkThread(SuicideASFIntoStrat, oClosestStratToRallyPoint, oClosest1)
            ForkThread(SuicideASFIntoStrat, oClosestStratToRallyPoint, oClosest2)
            for iUnit, oUnit in tAvailableAirAA do
                if oUnit == oClosest1 or oUnit == oClosest2 then
                    table.remove(tAvailableAirAA, iUnit)
                end
            end
        else
            ForkThread(SuicideASFIntoStrat, oClosestStratToRallyPoint, oClosest1)
            for iUnit, oUnit in tAvailableAirAA do
                if oUnit == oClosest1 then
                    table.remove(tAvailableAirAA, iUnit)
                end
            end
        end
    end
end

function SuicideASFIntoStrat(oStrat, oASF, bNoLimitOnASFToAssign)
    --WARNING: Call via fork thread due to waitseconds logic in below
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'SuicideASFIntoStrat'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oStrat) and AiBotUnitInfo.IsUnitValid(oASF) then
        if bDebugMessages == true then LOG(sFunctionRef..': will suicide asf '..oASF.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oASF)..' into oStrat '..oStrat.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oStrat)..'; bNoLimitOnASFToAssign='..tostring(bNoLimitOnASFToAssign or false)..'; Start of code, time='..GetGameTimeSeconds()) end
        local iASFValue = 1
        if EntityCategoryContains(categories.TECH2, oASF.UnitId) then
            iASFValue = 0.5
        end
        oStrat[refiAssignedSuicideASF] = (oStrat[refiAssignedSuicideASF] or 0) + iASFValue
        AiBotMicro.EnableUnitMicroUntilManuallyTurnOff(oASF)
        --oASF[AiBotUnitInfo.refbSpecialMicroActive] = true
        local iTeam = oASF:GetAIBrain().AiBotTeam
        if oStrat[refiAssignedSuicideASF] >= 2 and not(bNoLimitOnASFToAssign) then
            for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSuicideTargets] do
                if oUnit == oStrat then
                    if bDebugMessages == true then LOG(sFunctionRef..': Will remove strat from list of suicide targets as we now have at least 2 ASFs assigned to it') end
                    table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSuicideTargets], iUnit)
                    break
                end
            end
        end
        --Move into range
        while AiBotUtilities.GetDistanceBetweenPositions(oStrat:GetPosition(), oASF:GetPosition()) > 30 do
            if bDebugMessages == true then LOG(sFunctionRef..': Will try and move asf '..oASF.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oASF)..' into position as are far away from the strat '..oStrat.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oStrat)) end
            AiBotOrders.IssueTrackedMove(oASF, oStrat:GetPosition(), 10, false, 'SuicM', true)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            if not(AiBotUnitInfo.IsUnitValid(oStrat)) or not(AiBotUnitInfo.IsUnitValid(oASF)) then break end
        end
        --Issue attack, and dont stop until either asf or strat is dead
        while AiBotUnitInfo.IsUnitValid(oStrat) and AiBotUnitInfo.IsUnitValid(oASF) do
            if bDebugMessages == true then LOG(sFunctionRef..': Will try and give attack order to asf '..oASF.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oASF)..' to attack strat '..oStrat.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oStrat)..'; Is ASF special micro still true='..tostring(oASF[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
            AiBotOrders.IssueTrackedAttack(oASF, oStrat, false, 'SuicA', true)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
        if bDebugMessages == true then LOG(sFunctionRef..': Either asf or strat is no longer valid, clearing asf special micro flag') end
        oASF[AiBotUnitInfo.refbSpecialMicroActive] = false
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function RemoveFirstExpBomberTarget(iDelayBeforeRemoving)
    WaitSeconds(iDelayBeforeRemoving)
    if tiRecentExpBomberTargets[1] then table.remove(tiRecentExpBomberTargets, 1) end
end

function EnemyT1BomberTracker(oBomber, iTeam)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'EnemyT1BomberTracker'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --For the first 15m track enemy t1 bomber and get nearby engineers to the target
    if bDebugMessages == true then LOG(sFunctionRef..': oBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; reprs='..reprs(oBomber)) end
    --For simplicity will just do a square (not as accurate but avoids neeidng to do moveindirection multiple times)
    --bomber has range of 40; allowing for targeting of enemies within slightly shorter dist than this, and speed of bomber and delay in unit response, go with 30 min 60 max which equals 45 average
    local iAvDist = 45
    --[[local iMinDist = 30
local iMaxDist = 60
local iWidth = 20
local iAvDist = (iMinDist + iMaxDist)*0.5--]]
    local iRadius = 20

    local iCurFacingDirection
    while AiBotUnitInfo.IsUnitValid(oBomber) and GetGameTimeSeconds() <= 900 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestFriendlyAirFactoryTech] < 3 do
        --Get bomber facing direction, and then get any friendly engineers in this area
        iCurFacingDirection = AiBotUnitInfo.GetUnitFacingAngle(oBomber)
        local tMidpoint = AiBotUtilities.MoveInDirection(oBomber:GetPosition(), iCurFacingDirection, iAvDist)
        local rPotentialTargetRect = AiBotUtilities.GetRectAroundLocation(tMidpoint, iRadius)
        local tUnitsInRect = GetUnitsInRect(rPotentialTargetRect)
        if bDebugMessages == true then
            LOG(sFunctionRef..': Checking if have units in rPotentialTargetRect='..repru(rPotentialTargetRect)..'; Is table empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsInRect))..'; oBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; Time='..GetGameTimeSeconds())
            AiBotUtilities.DrawRectangle(rPotentialTargetRect)
        end
        if AiBotUtilities.IsTableEmpty(tUnitsInRect) == false then
            local tEngisInArea = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer - categories.AIR, tUnitsInRect)
            if bDebugMessages == true then LOG(sFunctionRef..': Considering enemy engineers near bomber '..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; Is table empty='..tostring(AiBotUtilities.IsTableEmpty(tEngisInArea))) end
            if AiBotUtilities.IsTableEmpty(tEngisInArea) == false then
                for iEngi, oEngi in tEngisInArea do
                    if bDebugMessages == true then LOG(sFunctionRef..': Engi '..oEngi.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEngi)..' owned by '..oEngi:GetAIBrain().Nickname..' on team '..oEngi:GetAIBrain().AiBotTeam..' - is special micro active='..tostring(oEngi[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Backup dist='..(oEngi:GetBlueprint().Physics.BackUpDistance or 'nil')) end
                    if oEngi:GetAIBrain().AiBotAI and oEngi:GetAIBrain().AiBotTeam == iTeam and not(oEngi[AiBotUnitInfo.refbEasyBrain]) then
                        --Have an AiBotAI engineer on our team that is near to the enemy t1 bomber; if special micro isn't active then have the engi move towards the bomber and flag a 'special micro flag that can be ignored if want to dodge shot'
                        if not(oEngi[AiBotUnitInfo.refbSpecialMicroActive]) or oEngi[AiBotUnitInfo.refbLowerPriorityMicroActive] then
                            local iCurBackupDist = oEngi:GetBlueprint().Physics.BackUpDistance
                            if (iCurBackupDist or 0) > 0 then
                                local iEngiFacingDist =  AiBotUnitInfo.GetUnitFacingAngle(oEngi)
                                local iAngleFromEngiToBomber = AiBotUtilities.GetAngleFromAToB(oEngi:GetPosition(), oBomber:GetPosition())
                                local iAngleDifBetweenEngineerAndBomber = AiBotUtilities.GetAngleDifference(iEngiFacingDist, iAngleFromEngiToBomber)
                                local tPotentialMoveLocation
                                --want the engineer to move away from the bomber, either by moving forwards, or backwards (and would then hopefully move towards it via the normal dodge logic), since if the bomber is approaching us and is cybran/uef then the later missiles are moelikely to hit us
                                if iAngleDifBetweenEngineerAndBomber >= 90 then
                                    --Engi facing direction means it should move away from the bomber if going forwards
                                    tPotentialMoveLocation = AiBotUtilities.MoveInDirection(oEngi:GetPosition(), iEngiFacingDist, iCurBackupDist - 1) --tried with -0.5 but engi would turn around instead of moving there
                                else
                                    --Engi facing direction means it should move away from the bomber if going backwards
                                    tPotentialMoveLocation = AiBotUtilities.MoveInDirection(oEngi:GetPosition(), iEngiFacingDist - 180, iCurBackupDist - 1) --tried with -0.5 but engi would turn around instead of moving there
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering whether to backup, iEngiFacingDist='..iEngiFacingDist..'; tPotentialMoveLocation='..repru(tPotentialMoveLocation)..'; Engi position='..repru(oEngi:GetPosition())..'; Plateau of tPotentialMoveLocation='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tPotentialMoveLocation) or 'nil')..'; Engi plateau='..(NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oEngi:GetPosition()) or 'nil')) end
                                if AiBotUtilities.IsTableEmpty(tPotentialMoveLocation) == false and NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tPotentialMoveLocation) == NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oEngi:GetPosition()) then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will move in opposite direction of engi cur facing dist, as a backup move, as there is an appraoching bomber (so hopefully it is easier to dodge the bomber shot when dodge bomb micro triggers), Time='..GetGameTimeSeconds()) end
                                    AiBotOrders.IssueTrackedMove(oEngi, tPotentialMoveLocation, math.min(3, iCurBackupDist - 2), false, 'PreemDodB', true)
                                    AiBotMicro.TrackTemporaryUnitMicro(oEngi, 2, nil, true) --will reduce by 0.001ish as part of the function
                                end
                            end
                        end
                    end
                end
            end
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function LoadCombatUnitOntoTransport(oJustBuilt)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'LoadCombatUnitOntoTransport'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oJustBuilt) then
        local iTeam = oJustBuilt:GetAIBrain().AiBotTeam
        oJustBuilt[AiBotEngineer.refiAssignedAction] = AiBotEngineer.refActionLoadOntoTransport
        local iPlateau, iLandZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oJustBuilt:GetPosition())
        if iPlateau and iLandZone and iPlateau > 0 then
            local tLZData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone]
            local tLZTeamData = tLZData[AiBotMap.subrefLZTeamData][iTeam]
            if not(tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport]) then
                tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport] = {}
            end
            table.insert(tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport], oJustBuilt)
            oJustBuilt[reftCombatDropPlateauAndZone] = {iPlateau, iLandZone}

            local oNearestTransportToLoadInto, oCombatUnitToLoad
            local iNearestTransportDist
            local iCurDist

            if not(tLZTeamData[AiBotMap.refbActiveCombatUnitLoader]) then
                if bDebugMessages == true then LOG(sFunctionRef..': Starting loop to load combat units onto transport, unti htat prompted this='..oJustBuilt.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oJustBuilt)..'; time='..GetGameTimeSeconds()) end
                tLZTeamData[AiBotMap.refbActiveCombatUnitLoader] = true
                local bHaveTransportWantingCombatUnits = false
                local bHaveAttachedUnits
                while AiBotConditions.IsTableOfUnitsStillValid(tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport]) and AiBotConditions.IsTableOfUnitsStillValid(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits]) do
                    oNearestTransportToLoadInto = nil
                    bHaveTransportWantingCombatUnits = false
                    if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits]) == false then
                        for iTransport, oTransport in tLZTeamData[AiBotMap.reftoTransportsWaitingForUnits] do
                            if (oTransport[refiCombatUnitsWanted] or 0) > 0 and AiBotUnitInfo.IsUnitValid(oTransport) then
                                bHaveTransportWantingCombatUnits = true
                                if bDebugMessages == true then LOG(sFunctionRef..': Considering oTransport='..oTransport.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oTransport)..'; oTransport[refiCombatUnitsWanted]='..(oTransport[refiCombatUnitsWanted] or 'nil')..'; refoTransportUnitTryingToLoad='..(oTransport[refoTransportUnitTryingToLoad].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTransport[refoTransportUnitTryingToLoad]) or 'nil')..' at time='..(oTransport[refoTransportUnitTryingToLoad][refiTimeLastGivenOrderToLoadOntoTransport] or 'nil')) end
                                if not(AiBotUnitInfo.IsUnitValid(oTransport[refoTransportUnitTryingToLoad])) or oTransport[refoTransportUnitTryingToLoad]:IsUnitState('Attached') or GetGameTimeSeconds() - (oTransport[refoTransportUnitTryingToLoad][refiTimeLastGivenOrderToLoadOntoTransport] or 0) >= 15 then
                                    --Load nearest unit onto this
                                    iNearestTransportDist = 10000
                                    oNearestTransportToLoadInto = oTransport
                                    oCombatUnitToLoad = nil
                                    bHaveAttachedUnits = false
                                    for iCombatUnit, oCombatUnit in tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport] do
                                        if oCombatUnit:IsUnitState('Attached') then
                                            bHaveAttachedUnits = true
                                        else
                                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oCombatUnit:GetPosition(), oTransport:GetPosition())
                                            if iCurDist < iNearestTransportDist then
                                                iNearestTransportDist = iCurDist
                                                oCombatUnitToLoad = oCombatUnit
                                            end
                                        end
                                    end
                                    if bHaveAttachedUnits then
                                        for iCurEntry = table.getn(tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport]), 1, -1 do
                                            if tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport][iCurEntry]:IsUnitState('Attached') then
                                                tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport][iCurEntry][AiBotEngineer.refiAssignedAction] = nil
                                                table.remove(tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport], iCurEntry)
                                            end
                                        end
                                    end

                                    if oCombatUnitToLoad then
                                        if bDebugMessages == true then LOG(sFunctionRef..': Will tell unit '..oCombatUnitToLoad.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oCombatUnitToLoad)..' to load onto transport '..oNearestTransportToLoadInto.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oNearestTransportToLoadInto)) end
                                        AiBotOrders.IssueTrackedTransportLoad(oCombatUnitToLoad, oNearestTransportToLoadInto, false, 'TrCombLd', false)
                                    end
                                end
                            end
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Finished loop at time='..GetGameTimeSeconds()..'; bHaveTransportWantingCombatUnits='..tostring(bHaveTransportWantingCombatUnits or false)..'; Is table of combat units loading onto transport empty='..tostring(AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport]))) end
                    if not(bHaveTransportWantingCombatUnits) then
                        --Clear all units
                        if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport]) == false then
                            for iCombatUnit, oCombatUnit in tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport] do
                                oCombatUnit[AiBotEngineer.refiAssignedAction] = nil
                                AiBotOrders.IssueTrackedClearCommands(oCombatUnit)
                            end
                            tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport] = {}
                        end
                        break
                    end
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                    WaitSeconds(1)
                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                end
                tLZTeamData[AiBotMap.refbActiveCombatUnitLoader] = false
                --Redundancy:
                if AiBotUtilities.IsTableEmpty(tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport]) == false then
                    for iCombatUnit, oCombatUnit in tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport] do
                        oCombatUnit[AiBotEngineer.refiAssignedAction] = nil
                        AiBotOrders.IssueTrackedClearCommands(oCombatUnit)
                    end
                    tLZTeamData[AiBotMap.reftoCombatUnitsLoadingOntoTransport] = {}
                end
                if bDebugMessages == true then LOG(sFunctionRef..': Finishing the unit loader logic, time='..GetGameTimeSeconds()) end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ConsiderIfBomberTargetingACUShouldReassign(oUnit, oCurTarget)
    --Should be called where a t1 bomber is targeting an ACU that has decent health
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ConsiderIfBomberTargetingACUShouldReassign'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if not(oUnit[refbReassessingTarget]) then
        oUnit[refbReassessingTarget] = true
        local iTimeToWaitToReassess = 0
        local tWeapons = oUnit:GetBlueprint().Weapon
        if tWeapons then
            for iWeapon, tCurWeapon in tWeapons do
                if (tCurWeapon.MuzzleSalvoSize or 1) > 1 then
                    iTimeToWaitToReassess = math.max(iTimeToWaitToReassess, tCurWeapon.MuzzleSalvoSize * tCurWeapon.MuzzleSalvoDelay)
                end
            end
        end
        if iTimeToWaitToReassess > 0 then
            WaitSeconds(iTimeToWaitToReassess)
        end
        if AiBotUnitInfo.IsUnitValid(oUnit) and AiBotUnitInfo.IsUnitValid(oCurTarget) then
            local bReassess = false
            local oPrioritySwitchTarget
            local iTeam = oUnit:GetAIBrain().AiBotTeam
            --case 1 - there's a groundAA threat in this land zone that means we likely want to retreat
            local tTargetLZOrWZData, tTargetLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oCurTarget:GetPosition(), true, iTeam)
            if bDebugMessages == true then LOG(sFunctionRef..': Deciding if we want to reassign bomber '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at time='..GetGameTimeSeconds()..'; Enemy groundAA in target zone='..(tTargetLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')..'; Target unit state='..AiBotUnitInfo.GetUnitState(oCurTarget)) end
            if tTargetLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] > 0 then
                bReassess = true
            else
                --Case 2 - ACU is building AA - target the AA
                if oCurTarget:IsUnitState('Building') or oCurTarget:IsUnitState('Repairing') then
                    local oACUConstruction = oCurTarget:GetFocusUnit()
                    if EntityCategoryContains(AiBotUnitInfo.refCategoryAntiAir + AiBotUnitInfo.refCategoryFixedShield, oACUConstruction.UnitId) then
                        bReassess = true
                        oPrioritySwitchTarget = oACUConstruction
                    end
                end
                if not(bReassess) then
                    --Case 3 - engis are in the zone building AA
                    if AiBotUtilities.IsTableEmpty(tTargetLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                        local tEnemyGroundAA = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryAntiAir * AiBotUnitInfo.refCategoryStructure, tTargetLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])

                        if AiBotUtilities.IsTableEmpty(tEnemyGroundAA) == false then
                            local bEnemyIsBuildingAABuilding = false
                            for iEnemyFixedAA, oEnemyFixedAA in tEnemyGroundAA do
                                if AiBotUnitInfo.IsUnitValid(oEnemyFixedAA) and oEnemyFixedAA:GetFractionComplete() < 1 then
                                    bEnemyIsBuildingAABuilding = true
                                    break
                                end
                            end
                            if bDebugMessages == true then LOG(sFunctionRef..': bEnemyIsBuildingAABuilding='..tostring(bEnemyIsBuildingAABuilding)) end
                            if bEnemyIsBuildingAABuilding then
                                --Search for enemy engis in the zone
                                local tEnemyEngis = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tTargetLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])
                                if AiBotUtilities.IsTableEmpty(tEnemyEngis) == false then
                                    local iClosestEnemyEngi = 10000
                                    local iCurEngiDist
                                    for iEngi, oEngi in tEnemyEngis do
                                        if AiBotUnitInfo.IsUnitValid(oEngi) and oEngi:GetFractionComplete() >= 0.75 then
                                            iCurEngiDist = AiBotUtilities.GetDistanceBetweenPositions(oEngi:GetPosition(), oUnit:GetPosition())
                                            if iCurEngiDist < iClosestEnemyEngi then
                                                iClosestEnemyEngi = iCurEngiDist
                                                oPrioritySwitchTarget = oEngi
                                                bReassess = true
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Finished considering cases where we want to reassess, bReassess='..tostring(bReassess)..'; oPrioritySwitchTarget='..(oPrioritySwitchTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oPrioritySwitchTarget) or 'nil')) end
            if bReassess then
                RemoveAssignedAttacker(oCurTarget, oUnit)
                if oPrioritySwitchTarget then
                    --Switch targets to this
                    AddAssignedAttacker(oPrioritySwitchTarget, oUnit)
                    AiBotOrders.IssueTrackedAttack(oUnit, oPrioritySwitchTarget, false, 'PrioSwitch', false)
                else
                    --Just move back to base (so can be treated as available for new orders)
                    AiBotOrders.IssueTrackedMove(oUnit, AiBotTeam.tAirSubteamData[oUnit:GetAIBrain().AiBotAirSubteam][AiBotTeam.reftAirRallyPoint], 3, false, 'PrioReassess', false)
                end
            end
        end
        oUnit[refbReassessingTarget] = false
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)

end

function RecordPlateauForHighTechEngineerDrop(iPlateau, iLandZone, iTeam, iEngiTechLevelWanted)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'RecordPlateauForHighTechEngineerDrop'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local bAlreadyRecorded = false
    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiHighTechEngiDropPlateauAndZones]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiHighTechEngiDropPlateauAndZones] = {}
    elseif AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiHighTechEngiDropPlateauAndZones]) == false then
        for iEntry, tPlateauAndZone in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiHighTechEngiDropPlateauAndZones] do
            if tPlateauAndZone[1] == iPlateau and tPlateauAndZone[2] == iLandZone and iEngiTechLevelWanted <= tPlateauAndZone[3] then
                bAlreadyRecorded = true
                break
            end
        end
    end
    if not(bAlreadyRecorded) then
        table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiHighTechEngiDropPlateauAndZones], {iPlateau, iLandZone, iEngiTechLevelWanted})
    end
    if bDebugMessages == true then LOG(sFunctionRef..': Finished recording iPlateau='..iPlateau..'; iLandZone='..iLandZone..'; iEngiTechLevelWanted='..iEngiTechLevelWanted..'; Time='..GetGameTimeSeconds()) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function PlanBomberSnipe(tAvailableBombers, oSnipeTarget, iTeam)
    --Holds bombers at rally point until they are ready to snipe the target
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'PlanBomberSnipe'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if bDebugMessages == true then
        if AiBotUnitInfo.IsUnitValid(oSnipeTarget) then
            LOG(sFunctionRef..': Start of code, oSnipeTarget='..(oSnipeTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oSnipeTarget) or 'nil')..'; iTeam='..iTeam..'; Owner of snipe target='..oSnipeTarget:GetAIBrain().Nickname..'; Is tAvailableBombers empty='..tostring(AiBotUtilities.IsTableEmpty(tAvailableBombers)))
        end
    end
    if AiBotUnitInfo.IsUnitValid(oSnipeTarget) and (oSnipeTarget[AiBotUnitInfo.refiRecentBomberSnipeAttempts] or 0) == 0 then --redundancy since call vai fork thread
        local iBomberCountThreshold = 30 --Will launch a snipe attempt when bomber count reaches this value - used to also check for failed loop
        if bDebugMessages == true then LOG(sFunctionRef..': Is table of bombers planning a snipe empty='..tostring(AiBotUtilities.IsTableEmpty(oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe]))) end
        if AiBotUtilities.IsTableEmpty(oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe]) then
            local tRallyPointOverride
            --50% chance to go to rally point, 50% to go to base
            if math.random(1, 2) == 1 then
                local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oSnipeTarget:GetPosition(), true, iTeam)
                tRallyPointOverride = {tLZTeamData[AiBotMap.reftClosestFriendlyBase][1], tLZTeamData[AiBotMap.reftClosestFriendlyBase][2], tLZTeamData[AiBotMap.reftClosestFriendlyBase][3]}
            end
            oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe] = {}
            for iBomber, oBomber in tAvailableBombers do
                if bDebugMessages == true then LOG(sFunctionRef..': will add bomber '..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..' to table of bombers planning snipe if it is still valid, is it valid='..tostring(AiBotUnitInfo.IsUnitValid(oBomber))) end
                if AiBotUnitInfo.IsUnitValid(oBomber) then table.insert(oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe], oBomber) end
            end
            --Plan the snipe attempt
            --Decide on health threshold for aborting snipe
            local iCurHealth = AiBotUnitInfo.GetUnitCurHealthAndShield(oSnipeTarget)
            local iMaxHealth = AiBotUnitInfo.GetUnitMaxHealthIncludingShield(oSnipeTarget)
            local iAbortCurHealthThreshold = math.min(math.max(iCurHealth * 1.4, iCurHealth + 2000), iMaxHealth * 1.25)
            local iCurStrikePotential, iBomberCount
            local iAttackCurHealthThreshold = iAbortCurHealthThreshold * 0.9
            local iCurFactorWanted
            if bDebugMessages == true then LOG(sFunctionRef..': About to start main loop, is table of bombers planning to snipe this unit valid='..tostring(AiBotConditions.IsTableOfUnitsStillValid(oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe]))..'; iAbortCurHealthThreshold='..iAbortCurHealthThreshold..'; Cur health='..AiBotUnitInfo.GetUnitCurHealthAndShield(oSnipeTarget)..'; oSnipeTarget='..oSnipeTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSnipeTarget)..' owned by '..oSnipeTarget:GetAIBrain().Nickname) end
            local bAbortAndClearBomberMicroFlag
            while AiBotConditions.IsTableOfUnitsStillValid(oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe]) do
                if not(AiBotUnitInfo.IsUnitValid(oSnipeTarget)) then
                    bAbortAndClearBomberMicroFlag = true
                else
                    iCurHealth = AiBotUnitInfo.GetUnitCurHealthAndShield(oSnipeTarget)
                    if iCurHealth >= iAbortCurHealthThreshold then
                        bAbortAndClearBomberMicroFlag = true
                        if bDebugMessages == true then LOG(sFunctionRef..': Cur health above threshold for aborting the snipe attempt') end
                        --Clear micro flag on all bombers
                    end
                end
                if bAbortAndClearBomberMicroFlag then
                    if bDebugMessages == true then LOG(sFunctionRef..': Aborting snipe attempt and clearing flag off any bombers') end
                    for iBomber, oBomber in oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe] do
                        ForkThread(AiBotMicro.ForkedResetMicroFlag,oBomber, 0)
                    end
                    break
                else
                    --Wait until either have lots of bombers, or enough to 1-shot by a bit
                    iCurStrikePotential = 0
                    iBomberCount = 0
                    for iBomber, oBomber in oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe] do
                        iCurStrikePotential = iCurStrikePotential + (oBomber[AiBotUnitInfo.refiStrikeDamage] or 0)
                        iBomberCount = iBomberCount + 1
                        --Make sure micro is enabled
                        if not(oBomber[AiBotUnitInfo.refbSpecialMicroActive]) then
                            AiBotMicro.EnableUnitMicroUntilManuallyTurnOff(oBomber, false)
                        end
                    end
                    iCurFactorWanted = 1
                    local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oSnipeTarget:GetPosition(), true, iTeam)
                    if tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.6 then
                        if tLZTeamData[AiBotMap.subrefThreatEnemyShield] == 0 and tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] <= 1000 then
                            iCurFactorWanted = 0.6
                        end
                    end
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering bomber snipe, iCurStrikePotential='..iCurStrikePotential..'; iMaxHealth='..iMaxHealth..'; iBomberCount='..iBomberCount..'; iCurHealth='..iCurHealth..'; iAbortCurHealthThreshold='..iAbortCurHealthThreshold..'; bAbortAndClearBomberMicroFlag='..tostring(bAbortAndClearBomberMicroFlag)) end
                    if iCurStrikePotential >= iMaxHealth * iCurFactorWanted * 1.1 or iBomberCount >= iBomberCountThreshold * iCurFactorWanted or iCurStrikePotential >= math.max(iCurHealth * 1.1, iAttackCurHealthThreshold) or (iBomberCount >= 18 and iCurStrikePotential >= iCurHealth * iCurFactorWanted * 1.05 and iCurStrikePotential >= iMaxHealth * 0.6) then
                        --Attack with the bombers, and flag to no longer try and snipe this target
                        oSnipeTarget[AiBotUnitInfo.refiRecentBomberSnipeAttempts] = (oSnipeTarget[AiBotUnitInfo.refiRecentBomberSnipeAttempts] or 0)
                        AiBotUtilities.DelayChangeVariable(oSnipeTarget, AiBotUnitInfo.refiRecentBomberSnipeAttempts, -1, 600, nil, nil, nil, nil, true)
                        for iBomber, oBomber in oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe] do
                            AiBotOrders.IssueTrackedAttack(oBomber, oSnipeTarget, false, 'BomSn', true)
                        end
                        --If this is in the bomber snipe targets then remove it
                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets]) == false then
                            for iRecordedSnipeTarget, oRecordedSnipeTarget in AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets] do
                                if oRecordedSnipeTarget == oSnipeTarget then
                                    if bDebugMessages == true then LOG(sFunctionRef..': Removing from table of bomber snipe targets') end
                                    table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets], iRecordedSnipeTarget)
                                    break
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Ordered all bombers to attack target '..oSnipeTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oSnipeTarget)..' owned by brain '..oSnipeTarget:GetAIBrain().Nickname..' at time='..GetGameTimeSeconds()) end

                        --Wait until either the target is dead or the bombers are dead
                        while AiBotConditions.IsTableOfUnitsStillValid(oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe]) and AiBotUnitInfo.IsUnitValid(oSnipeTarget) and not(oSnipeTarget:IsUnitState('Attached')) and not(AiBotUnitInfo.IsUnitUnderwater(oSnipeTarget)) do
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                            WaitSeconds(1)
                            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                        end
                        --Clear any units that are still alive
                        if AiBotUtilities.IsTableEmpty(oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe]) == false then
                            for iBomber, oBomber in oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe] do
                                ForkThread(AiBotMicro.ForkedResetMicroFlag,oBomber, 0)
                            end
                        end
                        if oSnipeTarget then
                            oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe] = nil
                        end
                        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets]) == false then
                            for iRecordedSnipeTarget, oRecordedSnipeTarget in AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets] do
                                if oRecordedSnipeTarget == oSnipeTarget then
                                    table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets], iRecordedSnipeTarget)
                                    break
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': Exiting loop as have issued the attack and either lost all bombers or lost the snipe target, is snipe target valid='..tostring(AiBotUnitInfo.IsUnitValid(oSnipeTarget))..'; Time='..GetGameTimeSeconds()) end
                        break
                    else
                        --Dont want to attack yet - make sure bombers are all at their air subteam's rally point
                        for iBomber, oBomber in oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe] do
                            AiBotOrders.IssueTrackedMove(oBomber, (tRallyPointOverride or AiBotTeam.tAirSubteamData[oBomber:GetAIBrain().AiBotAirSubteam][AiBotTeam.reftAirRallyPoint]), 5, false, 'BombPrepSnipeR', true)
                        end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitSeconds(1)
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    end
                end
            end
        else
            if bDebugMessages == true then LOG(sFunctionRef..': We already have code for planning a snipe active with some bombers assigned so will add available bombers to the table of bombers planning a snipe') end
            --Add these to existing table
            local bIncluded
            for iBomber, oBomber in tAvailableBombers do
                bIncluded = false
                if AiBotUtilities.IsTableEmpty(oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe]) == false then
                    for iExistingBomber, oExistingBomber in oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe] do
                        if oExistingBomber == oBomber then bIncluded = true break end
                    end
                end
                if not(bIncluded) then
                    if not(oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe]) then oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe] = {} end --redundancy as got error in a game from this sometimes
                    table.insert(oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe], oBomber)
                else
                    --Redundancy - this shouldnt have happened, a risk that an error occurred with the main loop and all the bombers are stuck; if size of table is 2 more than threshold for attacking then abort
                    if table.getn(oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe]) > iBomberCountThreshold then
                        local bHaveValidAttackOrder = false
                        for iBomber, oBomber in oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe] do
                            AiBotOrders.UpdateRecordedOrders(oBomber)
                            if (oBomber[AiBotOrders.refiOrderCount] or 0) > 0 and (oBomber[AiBotOrders.reftiLastOrders][oBomber[AiBotOrders.refiOrderCount]] == AiBotOrders.refiOrderIssueAttack) then
                                bHaveValidAttackOrder = true
                                break
                            end
                        end
                        if not(bHaveValidAttackOrder) then
                            AiBotUtilities.ErrorHandler('Have too many bombers and some already included so will abort the snipe attempt if none of them have an attack order on a unit recorded')
                            for iBomber, oBomber in oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe] do
                                if bDebugMessages == true then LOG(sFunctionRef..': resetting micro flag for oBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)) end
                                ForkThread(AiBotMicro.ForkedResetMicroFlag,oBomber, 0)
                            end
                            oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe] = nil
                            if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets]) == false then
                                for iRecordedSnipeTarget, oRecordedSnipeTarget in AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets] do
                                    if oRecordedSnipeTarget == oSnipeTarget then
                                        table.remove(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets], iRecordedSnipeTarget)
                                        break
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, time='..GetGameTimeSeconds()..'; Is oSnipeTarget valid='..tostring(AiBotUnitInfo.IsUnitValid(oSnipeTarget))..'; Is table of bombers planning snipe empty='..tostring(AiBotUtilities.IsTableEmpty(oSnipeTarget[AiBotUnitInfo.toBombersPlanningSnipe]))) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function AssessPotentialBomberSnipeTargetsNowReachedT2Air(iTeam)
    --Decide if we want to consider doing a T2 air snipe; if not, then flag all brains on the team that we no longer want to have snipe mode enabled
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AssessPotentialBomberSnipeTargetsNowReachedT2Air'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    --First check that the snipe table is nil (meaning we havent considered before)
    --High level - only consider T2 snipe if enemy doesnt have lots of air units; they ahve an ACU outside of their main base; and we arent into the late-game
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code for team '..iTeam..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech]..'; is if AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets] = nil='..tostring(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets] == nil)..'; Time='..GetGameTimeSeconds()) end
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets] == nil and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] <= 2500 and AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] < 3 and GetGameTimeSeconds() <= 1200 then
        --Are there any ACUs on the enemy team out of position and with low max health?
        local toPotentialACUsByTeam = {}
        local iCurTeam
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs]) == false then
            for iACU, oACU in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftEnemyACUs] do
                if bDebugMessages == true then LOG(sFunctionRef..': Considering ACU owned by player '..oACU:GetAIBrain().Nickname..'; Is underwater='..tostring(AiBotUnitInfo.IsUnitUnderwater(oACU))..'; Recent bomber snipe attempts='..(oACU[AiBotUnitInfo.refiRecentBomberSnipeAttempts] or 'nil')..'; Unit max health incl shield='..AiBotUnitInfo.GetUnitMaxHealthIncludingShield(oACU)) end
                if AiBotUnitInfo.IsUnitValid(oACU) and not(AiBotUnitInfo.IsUnitUnderwater(oACU)) and (oACU[AiBotUnitInfo.refiRecentBomberSnipeAttempts] or 0) == 0 then
                    local iMaxHealth = AiBotUnitInfo.GetUnitMaxHealthIncludingShield(oACU)
                    if iMaxHealth <= 16000 or ((AiBotUtilities.bLoudModActive or AiBotUtilities.bQuietModActive) and iMaxHealth <= 26000) then
                        local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oACU:GetPosition(), true, iTeam)
                        if bDebugMessages == true then LOG(sFunctionRef..': ACU mod dist='..tLZTeamData[AiBotMap.refiModDistancePercent]..'; Enemy groundAA='..tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]..'; Enemy shield threat='..tLZTeamData[AiBotMap.subrefThreatEnemyShield]) end
                        if (tLZTeamData[AiBotMap.refiModDistancePercent] <= 0.8 or AiBotMap.iMapSize <=512) and tLZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] <= 2000 and tLZTeamData[AiBotMap.subrefThreatEnemyShield] <= 400 then
                            iCurTeam = oACU:GetAIBrain().AiBotTeam
                            if not(toPotentialACUsByTeam[iCurTeam]) then toPotentialACUsByTeam[iCurTeam] = {} end
                            table.insert(toPotentialACUsByTeam[iCurTeam], oACU)
                            if bDebugMessages == true then LOG(sFunctionRef..': Adding ACU to table of potential snipe targets') end
                        end
                    end

                end
            end
        end
        if AiBotUtilities.IsTableEmpty(toPotentialACUsByTeam) == false then
            --Only include 1 ACU from each enemy team (to be fair if in a scenario with 2+ enemy human teams)
            local iCurDist
            local iClosestDist
            local oClosestACU
            for iEnemyTeam, toACUs in toPotentialACUsByTeam do
                iClosestDist = 100000
                oClosestACU = nil
                for iACU, oACU in toACUs do
                    local tLZData, tLZTeamData = AiBotMap.GetLandOrWaterZoneData(oACU:GetPosition(), true, iTeam)
                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(tLZTeamData[AiBotMap.reftClosestFriendlyBase], oACU:GetPosition())
                    if iCurDist < iClosestDist then
                        iClosestDist = iCurDist
                        oClosestACU = oACU
                    end
                end
                if oClosestACU then
                    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets] = {} end
                    table.insert(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets], oClosestACU)
                    if bDebugMessages == true then LOG(sFunctionRef..': Adding ACU owned by '..oClosestACU:GetAIBrain().Nickname..' to table of snipe targets for team='..iTeam..'; iEnemyTeam='..iEnemyTeam) end
                end
            end
        end
    end
    if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets]) then
        --Clear the bomber snipe flag
        for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
            oBrain[AiBotOverseer.refbBomberSnipe] = nil
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, is AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets] empty='..tostring(AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets]))) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function ReturnBomberToRallyIfBombNotDropped(oBomber, iTicksToWait)
    --Called if we want bomber to drop bomb and immediately return to rally
    WaitTicks(iTicksToWait)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ReturnBomberToRallyIfBombNotDropped'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, is Bomber valid='..tostring( AiBotUnitInfo.IsUnitValid(oBomber))..'; Is special micro active='..tostring(oBomber[AiBotUnitInfo.refbSpecialMicroActive])..'; Time since last fired bomb='..GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastBombFired] or 0)..'; Time='..GetGameTimeSeconds()) end
    if AiBotUnitInfo.IsUnitValid(oBomber) and not(oBomber[AiBotUnitInfo.refbSpecialMicroActive]) and GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastBombFired] or 0) >= math.max(1, iTicksToWait * 0.1 + 0.1) then
        AiBotOrders.IssueTrackedMove(oBomber, AiBotTeam.tAirSubteamData[oBomber:GetAIBrain().AiBotAirSubteam][AiBotTeam.reftAirRallyPoint], 10, false, 'FailBmR', false)
        if bDebugMessages == true then LOG(sFunctionRef..': will send bomber to rally') end
    end
end

function IsTargetValidForMexHunter(aiBrain, oTarget)
    --Checks target isnt underwater, and isnt covered by a shield
    if AiBotUnitInfo.IsUnitValid(oTarget) and not(AiBotUnitInfo.IsUnitUnderwater(oTarget)) and (oTarget:GetFractionComplete() >= 0.9 or oTarget:GetFractionComplete() * (oTarget[AiBotUnitInfo.refiUnitMassCost] or AiBotUnitInfo.GetUnitMassCost(oTarget)) >= 800) then
        if not(AiBotLogic.IsTargetUnderShield(aiBrain, oTarget, 1000, false, false, false, false, false)) then
            return true
        end
    end
    return false
end

function DoesEnemyHaveASFOrLargeAirForceOrDoWeHaveSnipeTargets(aiBrain)
    local iTeam = aiBrain.AiBotTeam
    local iAirSubteam = aiBrain.AiBotAirSubteam
    local bEnemyHasASFOrLargeAirForceOrSnipeTarget = false
    if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 and AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] >= 350 then
        if AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] >= 5000 or (AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] >= 2500 and AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subrefiOurAirAAThreat] <= AiBotTeam.tTeamData[iTeam][AiBotTeam.refiEnemyAirAAThreat] * 0.7) then
            bEnemyHasASFOrLargeAirForceOrSnipeTarget = true
        elseif AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirAA]) == false then
            for iUnit, oUnit in AiBotTeam.tTeamData[iTeam][AiBotTeam.reftoEnemyAirAA] do
                if AiBotUnitInfo.IsUnitValid(oUnit) and EntityCategoryContains(AiBotUnitInfo.refCategoryAirAA * categories.TECH3, oUnit.UnitId) then
                    bEnemyHasASFOrLargeAirForceOrSnipeTarget = true
                end
            end
        end
    end
    if not(bEnemyHasASFOrLargeAirForceOrSnipeTarget) then
        if AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toActiveSnipeTargets]) == false or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[iTeam][AiBotTeam.toBomberSnipeTargets]) == false then
            bEnemyHasASFOrLargeAirForceOrSnipeTarget = true
        end
    end
    return bEnemyHasASFOrLargeAirForceOrSnipeTarget
end

function ApplyMexHuntingLogicToBomber(oBomber)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'ApplyMexHuntingLogicToBomber'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oBomber) and not(oBomber[refbBomberUsingMexHunterLogic]) and not(AiBotMap.bIsCampaignMap) and not(AiBotUnitInfo.DoesBomberFireSalvo(oBomber)) then
        --Do we want to apply mex hunting logic? If enemy has asfs then just use normal logic
        local aiBrain = oBomber:GetAIBrain()
        if not(DoesEnemyHaveASFOrLargeAirForceOrDoWeHaveSnipeTargets(aiBrain)) then

            oBomber[refbBomberUsingMexHunterLogic] = true
            local bFoundTarget
            local iAirSubteam = aiBrain.AiBotAirSubteam
            local iDistToRally, iAngleDif, iDistToTarget, iAngleToTarget, iBomberDirection
            while AiBotUnitInfo.IsUnitValid(oBomber) and oBomber[refbBomberUsingMexHunterLogic] do
                if not(oBomber[AiBotUnitInfo.refbSpecialMicroActive]) then
                    if not(IsTargetValidForMexHunter(aiBrain, oBomber[refoStrikeDamageAssigned])) then
                        if not(oBomber[AiBotUnitInfo.refbSpecialMicroActive]) then
                            --AttackTargetForMexHuntingBomber(oBomber, bCalledFromOnBombFired, oOptionalTargetOverride, bRetryIfNoTargetFound)
                            bFoundTarget = AttackTargetForMexHuntingBomber(oBomber, false, nil, AiBotUnitInfo.GetUnitHealthPercent(oBomber) >= 0.6)
                            if bDebugMessages == true then LOG(sFunctionRef..': Tried attacking target with bomber, bFoundTarget='..tostring(bFoundTarget)) end
                            if not(bFoundTarget) then
                                --clear target and return to rally
                                if AiBotUnitInfo.IsUnitValid(oBomber[refoStrikeDamageAssigned]) then
                                    RemoveAssignedAttacker(oBomber[refoStrikeDamageAssigned], oBomber)
                                end
                                --Return to air rally point
                                local tRallyPoint = AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.reftAirRallyPoint]
                                iDistToRally = AiBotUtilities.GetDistanceBetweenPositions(tRallyPoint, oBomber:GetPosition())
                                iAngleDif = AiBotUtilities.GetAngleDifference(AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), tRallyPoint), AiBotUnitInfo.GetUnitFacingAngle(oBomber))
                                if not(oBomber[AiBotUnitInfo.refbEasyBrain]) and iDistToRally >= 75 and iAngleDif >= 15 and (iDistToRally >= 150 or iAngleDif >= 30) then
                                    ForkThread(AiBotMicro.TurnAirUnitAndMoveToTarget, oBomber, tRallyPoint, 10, 3)
                                else
                                    AiBotOrders.IssueTrackedMove(oBomber, tRallyPoint, 5, false, 'BombMxMv', false)
                                    --Make bomber available for normal logic if we have good intel or a small map and are now close to rally
                                    if iDistToRally <= 40 then
                                        if AiBotMap.iMapSize <= 256 or AiBotTeam.tLandSubteamData[aiBrain.AiBotLandSubteam][AiBotTeam.refiEnemyMobileDFThreatNearOurSide] >= 5000 or AiBotUtilities.IsTableEmpty(AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.reftEnemyLandExperimentals]) == false or AiBotTeam.tTeamData[aiBrain.AiBotTeam][AiBotTeam.refiConstructedExperimentalCount] > 0 then
                                            oBomber[refbBomberUsingMexHunterLogic] = false
                                            if bDebugMessages == true then LOG(sFunctionRef..': Will abort mex hunting logic') end
                                            break
                                        else
                                            local tBomberLZData, tBomberLZTeamData = AiBotMap.GetLandOrWaterZoneData(tRallyPoint, true, aiBrain.AiBotTeam)
                                            if tBomberLZTeamData[AiBotMap.refiRadarCoverage] > AiBotUnitInfo.iT2RadarSize then
                                                oBomber[refbBomberUsingMexHunterLogic] = false
                                                if bDebugMessages == true then LOG(sFunctionRef..': Will abort mex hunting logic') end
                                                break
                                            end
                                        end
                                    end
                                end
                            end
                        end
                    else
                        --We have an appropriate target, since we already ahve it recorded as a target we shouldnt need any new orders

                        --Have we likely overshot the target and want to turn around and attack it?
                        if bDebugMessages == true then LOG(sFunctionRef..': Have we likely overshot target and want to turn around? Ignore if we have active micro though, oBomber[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oBomber[AiBotUnitInfo.refbSpecialMicroActive])) end
                        if not(oBomber[AiBotUnitInfo.refbSpecialMicroActive]) then
                            iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), oBomber[refoStrikeDamageAssigned]:GetPosition())
                            iAngleToTarget = AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), oBomber[refoStrikeDamageAssigned]:GetPosition())
                            iBomberDirection = AiBotUnitInfo.GetUnitFacingAngle(oBomber)
                            iAngleDif = AiBotUtilities.GetAngleDifference(iAngleToTarget, iBomberDirection)
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if we have overshot our target and want to micro-turn to attack it,  oBomber[refoStrikeDamageAssigned]='.. oBomber[refoStrikeDamageAssigned].UnitId..AiBotUnitInfo.GetUnitLifetimeCount( oBomber[refoStrikeDamageAssigned])..'; iDistToTarget='..iDistToTarget..'; iAngleToTarget='..iAngleToTarget..'; iBomberDirection='..iBomberDirection..'; iAngleDif='..iAngleDif..'; Time since last fired bomb='..(GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastBombFired] or 0))..'; Cur time='..GetGameTimeSeconds()) end
                            --recently fired and target is close (so we wont be able to fire a bomb on a normal attack path)
                            if GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastBombFired] or 0) <= 2 and iDistToTarget <= 125 and (iAngleDif >= 10 or iDistToTarget <= 100) then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will try and hoverbomb') end
                                ForkThread(AiBotMicro.T1OrT3HoverBombTarget, oBomber, oBomber[refoStrikeDamageAssigned], false, true, false, true)
                                --Not recently fired, and want to turn:
                            elseif (((iAngleDif >= 45 and iDistToTarget <= 200) or (iDistToTarget <= (oBomber[AiBotUnitInfo.refiBomberRange] or 30) * 0.4)) and GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastBombFired] or 0) >= 1)
                                    --However, if we are facing almost the opposite direction we dont want to turn until there is enough distance that we will be able to fire a bomb when we turn
                                    and (iAngleDif <= 60 or iDistToTarget >= 20)
                            then
                                if bDebugMessages == true then LOG(sFunctionRef..': Will turn around and attack the target, or hover bomb if we are close and fired recently') end
                                ForkThread(AiBotMicro.TurnAirUnitAndAttackTarget, oBomber, oBomber[refoStrikeDamageAssigned], false, false, true)
                            else
                                --We just want to attack target as normal - check we have an active order
                                AiBotOrders.UpdateRecordedOrders(oBomber)
                                if AiBotUtilities.IsTableEmpty(oBomber[AiBotOrders.reftiLastOrders][1]) then
                                    --Redundancy - issue attack order
                                    AttackTargetForMexHuntingBomber(oBomber, false, oBomber[refoStrikeDamageAssigned])
                                end
                            end
                        end
                    end
                end

                WaitTicks(AiBotLand.iTicksPerLandCycle) --done as proxy for air cycle time
                if bDebugMessages == true then LOG(sFunctionRef..': About to start new cycle, is bomber valid='..tostring(AiBotUnitInfo.IsUnitValid(oBomber))..'; oBomber[refbBomberUsingMexHunterLogic]='..tostring((oBomber[refbBomberUsingMexHunterLogic] or false))..'; oBomber[refoStrikeDamageAssigned]='..(oBomber[refoStrikeDamageAssigned].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oBomber[refoStrikeDamageAssigned]) or 'nil')..'; Is this valid='..tostring(AiBotUnitInfo.IsUnitValid(oBomber[refoStrikeDamageAssigned]))..'; Special micro active='..tostring(oBomber[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Time='..GetGameTimeSeconds()) end
            end
        end
    end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end
function AttackTargetForMexHuntingBomber(oBomber, bCalledFromOnBombFired, oOptionalTargetOverride, bRetryIfNoTargetFound, bIsThisTheSecondCycle)
    --Searches for a target for the bomber, and gives an order to attack the target, considering microing to turn where relevant
    --returns true if found a target
    --bCalledFromOnBombFired - e.g. if this is called from the bomber on-bomb fired event, this should be true (so if we expect the bomb to kill the target we can ignore this and pick a new one)
    --bIsThisTheSecondCycle - if this is true then we called this once and failed to find a target, so are callign again with looser conditions

    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'AttackTargetForMexHuntingBomber'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local oTarget
    local oClosestLowerPriorityTarget --e.g. T3 mexes and pgens - in case dont find a main target
    local oTargetToAvoid
    local iStrikeDamage = oBomber[AiBotUnitInfo.refiStrikeDamage] or AiBotUnitInfo.RecordUnitRange(oBomber)
    local aiBrain = oBomber:GetAIBrain()
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oBomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; bCalledFromOnBombFired='..tostring(bCalledFromOnBombFired)..'; oOptionalTargetOverride='..(oOptionalTargetOverride.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oOptionalTargetOverride) or 'nil')..'; Bomber health%='..AiBotUnitInfo.GetUnitHealthPercent(oBomber)..'; Bomber fuel%='..oBomber:GetFuelRatio()..'; Does enemy have large air force='..tostring(DoesEnemyHaveASFOrLargeAirForceOrDoWeHaveSnipeTargets(aiBrain) or false)..'; Is special micro active='..tostring(oBomber[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Does bomber have a valid target='..tostring(AiBotUnitInfo.IsUnitValid(oBomber[refoStrikeDamageAssigned]))..'; Nearby enemy AirAA threat='..AiBotUnitInfo.GetAirThreatLevel(aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryAirAA, oBomber:GetPosition(), 50, 'Enemy'), true, true)..'; Time='..GetGameTimeSeconds()) end
    if oOptionalTargetOverride then
        oTarget = oOptionalTargetOverride
    elseif bCalledFromOnBombFired and (AiBotUnitInfo.GetUnitHealthPercent(oBomber) <= 0.55 or oBomber:GetFuelRatio() <= 0.2 or DoesEnemyHaveASFOrLargeAirForceOrDoWeHaveSnipeTargets(aiBrain) or (AiBotUnitInfo.GetUnitHealthPercent(oBomber) <= 0.75 and AiBotUnitInfo.GetAirThreatLevel(aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryAirAA, oBomber:GetPosition(), 50, 'Enemy'), true, true) >= 200)) then
        if bDebugMessages == true then LOG(sFunctionRef..': Will abort mex hunter logic and retreat') end
        --Abort
        oBomber[refbBomberUsingMexHunterLogic] = false
        if AiBotUnitInfo.IsUnitValid(oBomber[refoStrikeDamageAssigned]) then
            RemoveAssignedAttacker(oBomber[refoStrikeDamageAssigned], oBomber)
        end
        local tRetreatLocation = GetRetreatLocationForBomberThatJustFired(oBomber)
        if not(oBomber[AiBotUnitInfo.refbSpecialMicroActive]) then
            ForkThread(AiBotMicro.TurnAirUnitAndMoveToTarget, oBomber, tRetreatLocation, 15, 3)
        end
    elseif bCalledFromOnBombFired and AiBotUnitInfo.IsUnitValid(oBomber[refoStrikeDamageAssigned]) and AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), oBomber[refoStrikeDamageAssigned]:GetPosition()) <= (oBomber[AiBotUnitInfo.refiBomberRange] or 30) + 20 then --basic redundancy incase we have already chosen a new target in he same tick
        local iTargetHealth = AiBotUnitInfo.GetUnitCurHealthAndShield(oBomber[refoStrikeDamageAssigned])
        if bDebugMessages == true then LOG(sFunctionRef..': Have existing target, iTargetHealth='..iTargetHealth..'; iStrikeDamage='..iStrikeDamage..'; Is target valid for mex hunter='..tostring(IsTargetValidForMexHunter(aiBrain, oBomber[refoStrikeDamageAssigned]) or false)) end
        if iTargetHealth <= iStrikeDamage or not(IsTargetValidForMexHunter(aiBrain, oBomber[refoStrikeDamageAssigned])) then
            oTargetToAvoid = oBomber[refoStrikeDamageAssigned]
        else
            --Want to do turn around micro as we arent expecting to kill the unit with a single shot
            local tRetreatLocation = GetRetreatLocationForBomberThatJustFired(oBomber)
            if not(oBomber[AiBotUnitInfo.refbSpecialMicroActive]) and AiBotUtilities.IsTableEmpty(tRetreatLocation) == false then
                if bDebugMessages == true then LOG(sFunctionRef..': Will move towards retreat location as expect we need another shot to kill the target') end
                ForkThread(AiBotMicro.TurnAirUnitAndMoveToTarget, oBomber, tRetreatLocation, 15, 3)
                return true
            end
        end
    end
    if not(oTarget) then
        local iTeam = aiBrain.AiBotTeam
        local iAirSubteam = aiBrain.AiBotAirSubteam
        local bDontCheckForPacifism = not(AiBotOverseer.bPacifistModeActive)
        local bAbort = false
        local iStartPlateauOrZero, iStartLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oBomber:GetPosition())
        local tStartLZOrWZData, tStartLZOrWZTeamData
        if iStartPlateauOrZero == 0 then
            tStartLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iStartLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iStartLandOrWaterZone]
            tStartLZOrWZTeamData = tStartLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
        else
            tStartLZOrWZData = AiBotMap.tAllPlateaus[iStartPlateauOrZero][AiBotMap.subrefPlateauLandZones][iStartLandOrWaterZone]
            tStartLZOrWZTeamData = tStartLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
        end
        local iGroundAAThreshold = 1100
        local iAirAAThreshold = 325
        if bIsThisTheSecondCycle then
            iGroundAAThreshold = 2000
            iAirAAThreshold = 600
        end

        local iCurDist, iClosestDistToBomber, bCheckForAltTarget, iClosestDistForAltTarget, iCurHealth
        iClosestDistForAltTarget = 10000
        function ConsiderZoneForPotentialTargets(iEndPlateauOrZero, iEndLandOrWaterZone, iMexHunterCategories)
            local tLZOrWZData, tLZOrWZTeamData
            if iStartPlateauOrZero == 0 then
                tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iEndLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iEndLandOrWaterZone]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
            else
                tLZOrWZData = AiBotMap.tAllPlateaus[iEndPlateauOrZero][AiBotMap.subrefPlateauLandZones][iEndLandOrWaterZone]
                tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
            end
            if bDebugMessages == true then LOG(sFunctionRef..': Considering P'..iEndPlateauOrZero..'Z'..iEndLandOrWaterZone..'; Enemy groundAA in this zone='..(tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')..'; Is table of enemy units empty='..tostring(AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]))) end
            if AiBotUtilities.IsTableEmpty(tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits]) == false and tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] <= 3000 then
                if bDontCheckForPacifism or not(tLZOrWZData[AiBotMap.subrefbPacifistArea]) then
                    local tUnitsOfInterest = EntityCategoryFilterDown(iMexHunterCategories, tLZOrWZTeamData[AiBotMap.subrefTEnemyUnits])
                    if bDebugMessages == true then LOG(sFunctionRef..': Is tUnitsOfInterest empty='..tostring(AiBotUtilities.IsTableEmpty(tUnitsOfInterest))..'; Does enemy have groundAA along path='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, true, iGroundAAThreshold, 100000, false, iAirSubteam, true, false, oBomber:GetPosition(),                      false,                                      nil,                                  nil,                                nil,                                bIsThisTheSecondCycle))..'; Does enemy have too much AirAA along path='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, false, 1000000, iAirAAThreshold, false, iAirSubteam, true, false, oBomber:GetPosition(), false, nil))..'; Does enemy have too much threat (combined)='..tostring(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, false, iGroundAAThreshold, iGroundAAThreshold, false, iAirSubteam, true, false, oBomber:GetPosition(),                      false,                                      nil,                                  nil,                                nil,                                bIsThisTheSecondCycle))) end
                    if AiBotUtilities.IsTableEmpty(tUnitsOfInterest) == false then
                        --DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, bIgnoreAirAAThreat, iGroundAAThreatThreshold, iAirAAThreatThreshold, bUsingTorpBombers, iAirSubteam, bDoDetailedCheckForAA, bReturnGroundAAThreatInstead, tOptionalStartMidpointAdjustForDetailedCheck, bReturnGroundAAUnitsAlongsideAAThreat, tOptionalEndMidpointAdjustForDetailedCheck, bOptionalIgnoreOppositeDirectionZones, bIncludeEnemyGroundAAInAirAAThreat, bAssumeWontTargetInterimAAForDetailedCheck)
                        if not(DoesEnemyHaveAAThreatAlongPath(iTeam, iStartPlateauOrZero, iStartLandOrWaterZone, iEndPlateauOrZero, iEndLandOrWaterZone, false,             iGroundAAThreshold,   iAirAAThreshold,                    false,          iAirSubteam,    true,               false,                          oBomber:GetPosition(),                      false,                                      nil,                                  nil,                                nil,                                bIsThisTheSecondCycle)) then
                            --Pick the closest target that we can kill
                            iClosestDistToBomber = 10000
                            if oClosestLowerPriorityTarget then bCheckForAltTarget = false else bCheckForAltTarget = true end
                            for iUnit, oUnit in tUnitsOfInterest do
                                if bDebugMessages == true then LOG(sFunctionRef..'; Considering enemy unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; iCurDist='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oBomber:GetPosition())..'; iClosestDistToBomber='..iClosestDistToBomber..'; Target health='..AiBotUnitInfo.GetUnitCurHealthAndShield(oUnit)..'; Is target suitable='..tostring(IsTargetValidForMexHunter(aiBrain, oUnit))..'; oUnit[refiStrikeDamageAssigned] ='..(oUnit[refiStrikeDamageAssigned]  or 'nil')) end
                                if IsTargetValidForMexHunter(aiBrain, oUnit) and not(oTargetToAvoid == oUnit) then
                                    iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oBomber:GetPosition())
                                    if iCurDist < iClosestDistToBomber then
                                        iCurHealth = AiBotUnitInfo.GetUnitCurHealthAndShield(oUnit)
                                        if (oUnit[refiStrikeDamageAssigned] or 0) < iCurHealth and iCurHealth <= iStrikeDamage + (oUnit[refiStrikeDamageAssigned] or 0) then
                                            oTarget = oUnit
                                            iClosestDistToBomber = iCurDist
                                            if bDebugMessages == true then LOG(sFunctionRef..': Updating target to this unit') end
                                        elseif bCheckForAltTarget and iCurDist < iClosestDistForAltTarget and (oUnit[refiStrikeDamageAssigned] or 0) < iCurHealth then
                                            iClosestDistForAltTarget = iCurDist
                                            oClosestLowerPriorityTarget = oUnit
                                        end
                                        --[[elseif bCheckForAltTarget and iCurDist < iClosestDistForAltTarget and (oUnit[refiStrikeDamageAssigned] or 0) < AiBotUnitInfo.GetUnitCurHealthAndShield(oUnit) then
                            iClosestDistForAltTarget = iCurDist
                            oClosestLowerPriorityTarget = oUnit--]]
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end

        local iMexHunterCategories = AiBotUnitInfo.refCategoryMex + AiBotUnitInfo.refCategoryPower - categories.TECH1 + AiBotUnitInfo.refCategoryT3Radar
        if bDebugMessages == true then LOG(sFunctionRef..': About to start main consideration of targets for bomber='..oBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oBomber)..'; Position='..repru(oBomber:GetPosition())..'; iStartPlateauOrZero='..(iStartPlateauOrZero or 'nil')..'; iStartLandOrWaterZone='..(iStartLandOrWaterZone or 'nil')..'; GameTime='..GetGameTimeSeconds()) end
        if (iStartLandOrWaterZone or 0) > 0 then
            ConsiderZoneForPotentialTargets(iStartPlateauOrZero, iStartLandOrWaterZone, iMexHunterCategories)
            if not(oTarget) and not(bAbort) then
                RecordOtherLandAndWaterZonesByDistance(tStartLZOrWZData, tStartLZOrWZData[AiBotMap.subrefMidpoint])
                local iOtherPlateauOrZero, iOtherLZOrWZ
                for iEntry, tPathingDetails in tStartLZOrWZData[AiBotMap.subrefOtherLandAndWaterZonesByDistance] do
                    iOtherPlateauOrZero = tPathingDetails[AiBotMap.subrefiPlateauOrPond]
                    iOtherLZOrWZ = tPathingDetails[AiBotMap.subrefiLandOrWaterZoneRef]
                    if tPathingDetails[AiBotMap.subrefbIsWaterZone] then iOtherPlateauOrZero = 0 end
                    ConsiderZoneForPotentialTargets(iOtherPlateauOrZero, iOtherLZOrWZ, iMexHunterCategories)
                    if oTarget or bAbort then break end
                end
            end
        else
            --Dont know where we are so just abort this special logic to avoid risk of getting stuck in a cycle
            oBomber[refbBomberUsingMexHunterLogic] = false
        end

        --Pick lower vlaue but still decent target if we couldnt find any decent targets
        if bDebugMessages == true then LOG(sFunctionRef..': Finsihed searching for target, oTarget='..(oTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTarget) or 'nil')..'; oClosestLowerPriorityTarget='..(oClosestLowerPriorityTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oClosestLowerPriorityTarget) or 'nil')..'; oTargetToAvoid='..(oTargetToAvoid.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oTargetToAvoid) or 'nil')) end
        if not(oTarget) and oClosestLowerPriorityTarget and not(oClosestLowerPriorityTarget == oTargetToAvoid) then
            oTarget = oClosestLowerPriorityTarget
        end
    end
    if oTarget then
        AddAssignedAttacker(oTarget, oBomber)
        --Will use micro in the main loop if we consider it necessary
        --If are too close to target and fired recently then hoverbomb (also have similar logic in the main loop, but having here allows for quicker reaction)
        local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), oTarget:GetPosition())
        local iAngleToTarget = AiBotUtilities.GetAngleFromAToB(oBomber:GetPosition(), oTarget:GetPosition())
        local iBomberDirection = AiBotUnitInfo.GetUnitFacingAngle(oBomber)
        local iAngleDif = AiBotUtilities.GetAngleDifference(iAngleToTarget, iBomberDirection)
        if bDebugMessages == true then LOG(sFunctionRef..': Considering if watn to hoverbomb target due to its proximity, iDistToTarget='..iDistToTarget..'; iAngleToTarget='..iAngleToTarget..'; iBomberDirection='..iBomberDirection..'; iAngleDif='..iAngleDif..'; Time since last fired bomb='..(GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastBombFired] or 0))..'; Cur time='..GetGameTimeSeconds()) end
        --recently fired and target is close (so we wont be able to fire a bomb on a normal attack path)
        if bCalledFromOnBombFired and GetGameTimeSeconds() - (oBomber[AiBotUnitInfo.refiLastBombFired] or 0) <= 2 and iDistToTarget <= 125 then
            if bDebugMessages == true then LOG(sFunctionRef..': Will try and hoverbomb') end
            --T1OrT3HoverBombTarget(oBomber, oTarget, bDontAdjustMicroFlag, bContinueAttackingUntilTargetDead, bAbortForGroundAAUnlessTargetIsEngineer)
            ForkThread(AiBotMicro.T1OrT3HoverBombTarget, oBomber, oTarget, false,                 true,                               false, true)

            --Get the best aoe location if attacking a structure
        elseif EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oTarget.UnitId) or oTarget:GetFractionComplete() < 1 then
            local iAOE, iDamage = AiBotUnitInfo.GetBomberAOEAndStrikeDamage(oBomber)
            local tGroundTarget = AiBotLogic.GetBestAOETarget(oBomber:GetAIBrain(), oTarget:GetPosition(), iAOE, iDamage, false, nil, nil, nil, 1, 2, nil, nil, nil, nil, false)
            if AiBotUtilities.IsTableEmpty(tGroundTarget) then tGroundTarget = oTarget:GetPosition() end --redundancy
            AiBotOrders.IssueTrackedGroundAttack(oBomber, tGroundTarget, 1, false, 'MexHuntG', false, oTarget)
            if bDebugMessages == true then LOG(sFunctionRef..': Will do ground attack') end
        else
            --Manual attack as mobile target
            if bDebugMessages == true then LOG(sFunctionRef..': Will do manual attack') end
            IssueTrackedAttack(oBomber, oTarget, false, 'MexHuntM', false)
        end
    else
        --Do nothing
    end

    --return true if found a target
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    if oTarget then return true else
        if bRetryIfNoTargetFound then return AttackTargetForMexHuntingBomber(oBomber, bCalledFromOnBombFired, oOptionalTargetOverride, false, true)
        else
            return false
        end
    end
end


function GetRetreatLocationForBomberThatJustFired(oUnit)
    local aiBrain = oUnit:GetAIBrain()
    local tNearestFriendlyBase
    local bCloseToDangerousFriendlyBase = false
    local tLZOrWZData, tLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, aiBrain.AiBotTeam)
    if tLZOrWZTeamData then
        tNearestFriendlyBase = {tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][1], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][2], tLZOrWZTeamData[AiBotMap.reftClosestFriendlyBase][3]}
        if tLZOrWZTeamData[AiBotMap.refiModDistancePercent] <= 0.3 and tLZOrWZTeamData[AiBotMap.subrefLZSValue] < 1000 and (tLZOrWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) > 0 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tNearestFriendlyBase) <= 250 then bCloseToDangerousFriendlyBase = true end --if are close to base then is a risk enemy has overrun it
    end
    if not(tNearestFriendlyBase) then tNearestFriendlyBase = AiBotMap.GetPlayerStartPosition(aiBrain) end

    local tAirRallyPoint = AiBotTeam.tAirSubteamData[aiBrain.AiBotAirSubteam][AiBotTeam.reftAirRallyPoint]
    local tRallyLZOrWZData, tRallyLZOrWZTeamData = AiBotMap.GetLandOrWaterZoneData(oUnit:GetPosition(), true, aiBrain.AiBotTeam)
    local tRetreatLocation
    if not(bCloseToDangerousFriendlyBase) and tRallyLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.3 then
        if AiBotUtilities.IsTableEmpty(tAirRallyPoint) == false then
            local iAngleToBase = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tNearestFriendlyBase)
            local iAngleToRally = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), tAirRallyPoint)
            if AiBotUtilities.GetAngleDifference(iAngleToBase, iAngleToRally) >= 35 and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tNearestFriendlyBase) >= 60 then
                if tRallyLZOrWZTeamData[AiBotMap.refiModDistancePercent] >= 0.5 then
                    tRetreatLocation = {tNearestFriendlyBase[1], tNearestFriendlyBase[2], tNearestFriendlyBase[3]}
                else
                    local iRallyPlateauOrZero, iRallyZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tAirRallyPoint)
                    local iUnitPlateauOrZero, iUnitZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
                    if iRallyPlateauOrZero and iUnitPlateauOrZero and iRallyZone and iUnitZone then
                        CalculateAirTravelPath(iUnitPlateauOrZero, iUnitZone, iRallyPlateauOrZero, iRallyZone)
                        if DoesEnemyHaveAAThreatAlongPath(aiBrain.AiBotTeam, iUnitPlateauOrZero, iUnitZone, iRallyPlateauOrZero, iRallyZone, false, 1000, 1000, false, aiBrain.AiBotAirSubteam, true, false, oUnit:GetPosition(), false) then
                            tRetreatLocation = {tNearestFriendlyBase[1], tNearestFriendlyBase[2], tNearestFriendlyBase[3]}
                        end
                    end
                end
            end
            --elseif GetGameTimeSeconds() >= 60 and (not(AiBotMap.bIsCampaignMap) or tonumber(ScenarioInfo.Options.CmpAIDelay) < GetGameTimeSeconds() + 1) then
            --AiBotUtilities.ErrorHandler('No valid air rally point, AI delay='..tonumber(ScenarioInfo.Options.CmpAIDelay))
        end
    end
    if not(tRetreatLocation) then tRetreatLocation = {tAirRallyPoint[1], tAirRallyPoint[2], tAirRallyPoint[3]} end
    return tRetreatLocation
end

function GetHealthRunThreshold(iMaxHealth, oUnit)
    if not(oUnit[refiProjectileHealthOverridePercent]) then
        if iMaxHealth <= 1800 and iProjectileLowHealthThreshold <= 0.75 then --T1-t2 gunships - be more cautious
            local iOverride
            if iMaxHealth <= 850 then
                iOverride = 0.75
            else
                iOverride = math.max(0.6, iProjectileLowHealthThreshold + 0.075)
            end
            oUnit[refiProjectileHealthOverridePercent] = iOverride
            return math.max(iOverride, iProjectileLowHealthThreshold)
        end
    else
        return math.max(oUnit[refiProjectileHealthOverridePercent], iProjectileLowHealthThreshold)
    end

    return iProjectileLowHealthThreshold
end

function MonitorEnemyACUForScoutPrioritisation(oACU, iTeam)
    --E.g. call if enemy has stealth upgrade
    local bCurrentlyAssignedScout = false
    local iTimeToReassess = 10
    local iPlateau, iLandZone
    local bWantScoutAssigned
    local tbAirSubteams = {} --[x] is the air subteam, returns true
    for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
        tbAirSubteams[oBrain.AiBotAirSubteam] = true
    end
    while AiBotUnitInfo.IsUnitValid(oACU) do
        --If enemy has cloak then ensure a priority for scouting
        bWantScoutAssigned = true
        if AiBotUnitInfo.IsUnitUnderwater(oACU) then
            bWantScoutAssigned = false
        else
            iPlateau = oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][1]
            iLandZone = oACU[AiBotUnitInfo.reftAssignedPlateauAndLandZoneByTeam][iTeam][2]
            local tCurLZTeamData = AiBotMap.tAllPlateaus[iPlateau][AiBotMap.subrefPlateauLandZones][iLandZone][AiBotMap.subrefLZTeamData][iTeam]
            if tCurLZTeamData[AiBotMap.refiOmniCoverage] >= 50 or tCurLZTeamData[AiBotMap.refiModDistancePercent] >= 0.45 then
                bWantScoutAssigned = false
            end
        end
        if bWantScoutAssigned then
            if bCurrentlyAssignedScout then
                --Do nothing
            else
                for iAirSubteam, bTrue in tbAirSubteams do
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains]) == false then
                        AddUnitWantingPriorityScout(oACU, false, iAirSubteam)
                    end
                end
            end
        else
            if bCurrentlyAssignedScout then
                for iAirSubteam, bTrue in tbAirSubteams do
                    if AiBotUtilities.IsTableEmpty(AiBotTeam.tAirSubteamData[iAirSubteam][AiBotTeam.subreftoFriendlyAiBotBrains]) == false then
                        RemoveUnitFromPriorityScoutTable(oACU, iAirSubteam)
                    end
                end
            end
        end
        WaitSeconds(iTimeToReassess)
    end
end

function MonitorNavalFacForBomberTarget(oUnit, aiBrain)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'MonitorNavalFacForBomberTarget'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iTeam = aiBrain.AiBotTeam
    local iWaterZone = oUnit[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam]
    if bDebugMessages == true then LOG(sFunctionRef..': Start of code, oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; aiBrain='..aiBrain.Nickname..' on team '..iTeam..'; iWaterZone='..(iWaterZone or 'nil')..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis][iWaterZone]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis][iWaterZone] or 'nil')) end
    if not(AiBotUtilities.bLoudModActive) and iWaterZone and AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis][iWaterZone] == nil then
        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis] = {} end
        AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis][iWaterZone] = 0
        local iDelayBetweenCycles = 20 --How frequently to check for engineer targets
        local iRadius = 7
        local oBP = oUnit:GetBlueprint()
        if not(oBP.SizeX) then oBP = __blueprints[oUnit.UnitId] end
        local tPosition = oUnit:GetPosition()
        local rRectAroundFactory = Rect(tPosition[1] - iRadius - oBP.SizeX, tPosition[3] - iRadius, tPosition[1] + iRadius + oBP.SizeX, tPosition[3] + iRadius + oBP.SizeZ)
        local tTargetWZTeamData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone][AiBotMap.subrefWZTeamData][iTeam]
        while AiBotUnitInfo.IsUnitValid(oUnit) do
            --Do we still want to consider attacking? Abort if enemy has t3 navy, t3 air, or a cruiser or significant AA
            if bDebugMessages == true then LOG(sFunctionRef..': Start of loop for factory '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..', AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech]..'; AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech]='..AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech]..'; tTargetWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA]='..(tTargetWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 'nil')..'; tTargetWZTeamData[AiBotMap.subrefThreatEnemyShield]='..(tTargetWZTeamData[AiBotMap.subrefThreatEnemyShield] or 'nil')..'; Time='..GetGameTimeSeconds()) end
            if AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyAirTech] >= 3 or AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] >= 3 or (tTargetWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) >= 1000 or (tTargetWZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) >= 100 then
                if bDebugMessages == true then LOG(sFunctionRef..': Enemy reached t3 or has shields so want to abort') end
                break
            elseif AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefiHighestEnemyNavyTech] >= 2 then
                if bDebugMessages == true then LOG(sFunctionRef..': Enemy has T2 navy, cruiser count of factory owner '..oUnit:GetAIBrain().Nickname..'='..oUnit:GetAIBrain():GetCurrentUnits(AiBotUnitInfo.refCategoryCruiser)) end
                if oUnit:GetAIBrain():GetCurrentUnits(AiBotUnitInfo.refCategoryCruiser) > 0 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Enemy has cruiser so aborting') end
                    break
                end
            end
            local toUnitsInRect = GetUnitsInRect(rRectAroundFactory)
            if bDebugMessages == true then LOG(sFunctionRef..': Is toUnitsInRect empty='..tostring(AiBotUtilities.IsTableEmpty(toUnitsInRect))) end
            if AiBotUtilities.IsTableEmpty(toUnitsInRect) == false then
                local toEngisInRect = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, toUnitsInRect)
                if bDebugMessages == true then LOG(sFunctionRef..': Is toEngisInRect empty='..tostring(AiBotUtilities.IsTableEmpty(toEngisInRect)))
                    if AiBotUtilities.IsTableEmpty(toEngisInRect) == false then LOG(sFunctionRef..': Table size='..table.getn(toEngisInRect)) end
                end
                if AiBotUtilities.IsTableEmpty(toEngisInRect) == false and table.getn(toEngisInRect) >= 4 then
                    if bDebugMessages == true then LOG(sFunctionRef..': Want to try and bomb this WZ, iWaterZone='..iWaterZone) end
                    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis][iWaterZone] = 1
                    break
                end
            end
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(iDelayBetweenCycles)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        end
    end
    if bDebugMessages == true then LOG(sFunctionRef..': End of code, AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis][iWaterZone]='..(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiWaterZonesForBomberToKillEngis][iWaterZone] or 'nil')..' for iWaterZone='..(iWaterZone or 'nil')..' and naval fac '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function EnemyNavalEngineerBomber(oBomber)
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'EnemyNavalEngineerBomber'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    if AiBotUnitInfo.IsUnitValid(oBomber) and oBomber[refiBomberTargetNavalEngiWZ] then
        local aiBrain = oBomber:GetAIBrain()
        local iTeam = aiBrain.AiBotTeam
        local iAirSubteam = aiBrain.AiBotAirSubteam
        local iWaterZone = oBomber[refiBomberTargetNavalEngiWZ]
        local tEnemyBaseWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iWaterZone]][AiBotMap.subrefPondWaterZones][iWaterZone]
        local tEnemyBaseWZTeamData = tEnemyBaseWZData[AiBotMap.subrefWZTeamData][iTeam]
        if AiBotUtilities.IsTableEmpty(tEnemyBaseWZTeamData[AiBotMap.subrefTEnemyUnits]) == false and (tEnemyBaseWZTeamData[AiBotMap.subrefiThreatEnemyGroundAA] or 0) <= 1000 or (tEnemyBaseWZTeamData[AiBotMap.subrefThreatEnemyShield] or 0) >= 100 then
            --Get closest naval fac in this WZ as our initial destination
            local toEnemyFactories = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryNavalFactory, tEnemyBaseWZTeamData[AiBotMap.subrefTEnemyUnits])
            if AiBotUtilities.IsTableEmpty(toEnemyFactories) == false then
                local oClosestFactory
                local iClosestFactoryDist = 10000
                local iCurDist
                for iFactory, oFactory in toEnemyFactories do
                    if not(oFactory.Dead) then
                        iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), oFactory:GetPosition())
                        if iCurDist < iClosestFactoryDist then
                            iClosestFactoryDist = iCurDist
                            oClosestFactory = oFactory
                        end
                    end
                end
                if oClosestFactory then
                    local tClosestFactory = oClosestFactory:GetPosition()
                    local iAOE, iStrikeDamage = AiBotUnitInfo.GetBomberAOEAndStrikeDamage(oBomber)
                    iStrikeDamage = math.max(150, iStrikeDamage) --assume we can 1-shot all engineers in case it gives strange results if we cant


                    AiBotMicro.TrackTemporaryUnitMicro(oBomber, 0)

                    local bReachedInitialLocation = false
                    local iTicksToWait
                    local bDontConsiderPlayableArea = not(AiBotMap.bIsCampaignMap)
                    local tEnemyTargets
                    local oEnemyToTarget
                    local iBestDamageFromBomb, iCurDamageFromBomb
                    local oBestDamageFromBomb
                    local iRadius = 7

                    if bDebugMessages == true then LOG(sFunctionRef..': About to start main loop, iWaterZone='..iWaterZone..'; oClosestFactory='..oClosestFactory.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oClosestFactory)..'; About to start main loop') end
                    --Start main loop
                    while AiBotUnitInfo.IsUnitValid(oBomber) and oBomber[refiBomberTargetNavalEngiWZ] do
                        --Remove any existing assigned strike damage (will re-add if we retain target)
                        local tLastOrder = oBomber[AiBotOrders.reftiLastOrders][oBomber[AiBotOrders.refiOrderCount]]
                        local oExistingValidAttackTarget
                        if tLastOrder and tLastOrder[AiBotOrders.subrefoOrderUnitTarget] and (tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueAttack or tLastOrder[AiBotOrders.subrefiOrderType] == AiBotOrders.refiOrderIssueGroundAttack) and AiBotUnitInfo.IsUnitValid(tLastOrder[AiBotOrders.subrefoOrderUnitTarget]) then
                            oExistingValidAttackTarget = tLastOrder[AiBotOrders.subrefoOrderUnitTarget]
                            RemoveAssignedAttacker(oExistingValidAttackTarget, oBomber)
                        end
                        iTicksToWait = 10
                        --Have we got near closest factory? if not, travel to it
                        if not(bReachedInitialLocation) then
                            iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), tClosestFactory)
                            if iCurDist <= 100 then
                                bReachedInitialLocation = true
                            else
                                AiBotOrders.IssueTrackedMove(oBomber, tClosestFactory, 5, false, 'NvBmbM', true)
                            end
                        end
                        if bReachedInitialLocation then
                            --Look for engineer target
                            iTicksToWait = 1
                            oEnemyToTarget = nil
                            if oExistingValidAttackTarget then
                                oEnemyToTarget = oExistingValidAttackTarget
                            else
                                if bDebugMessages == true then LOG(sFunctionRef..': Searching for enemy engineers and pgens to attack, Is table of enemy units in the LZ empty='..tostring(AiBotUtilities.IsTableEmpty(tEnemyBaseWZTeamData[AiBotMap.subrefTEnemyUnits]))) end
                                iBestDamageFromBomb = 0
                                --For some reason doing FilterToAvailableTargets doesnt work, so having to manually reproduce here
                                if AiBotUtilities.IsTableEmpty(tEnemyBaseWZTeamData[AiBotMap.subrefTEnemyUnits]) == false then
                                    local tEnemyEngineers = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, tEnemyBaseWZTeamData[AiBotMap.subrefTEnemyUnits])
                                    if AiBotUtilities.IsTableEmpty(tEnemyEngineers) == false then
                                        for iUnit, oUnit in tEnemyBaseWZTeamData[AiBotMap.subrefTEnemyUnits] do
                                            if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..(oUnit.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oUnit) or 'nil')..'; Is unit valid='..tostring(AiBotUnitInfo.IsUnitValid(oUnit))) end
                                            if AiBotUnitInfo.IsUnitValid(oUnit) and not(AiBotUnitInfo.IsUnitUnderwater(oUnit)) and (bDontConsiderPlayableArea or AiBotConditions.IsLocationInPlayableArea(oUnit:GetPosition())) and oUnit:GetFractionComplete() == 1 then
                                                iCurDamageFromBomb = AiBotLogic.GetDamageFromBomb(aiBrain, oUnit:GetPosition(), iAOE, iStrikeDamage, nil, nil, false, nil, nil, 1, false, nil, true, nil, nil, nil, false, nil)
                                                if bDebugMessages == true then LOG(sFunctionRef..': iCurDamageFromBomb='..iCurDamageFromBomb) end
                                                if iCurDamageFromBomb > iBestDamageFromBomb then
                                                    iBestDamageFromBomb = iCurDamageFromBomb
                                                    oBestDamageFromBomb = oUnit
                                                    if bDebugMessages == true then LOG(sFunctionRef..': Updating oBestDamageFromBomb to be this unit, iBestDamageFromBomb='..iBestDamageFromBomb) end
                                                end
                                            end
                                        end
                                    end
                                end
                                if bDebugMessages == true then LOG(sFunctionRef..': Finished searching for engineer targets, iBestDamageFromBomb='..iBestDamageFromBomb) end
                                if iBestDamageFromBomb <= 60 then --expect to only get 1 engineer with a bomb; check if reason we havent found good targets is we havent had intel near the enemy main naval fac (since this logic has been called we know the factory is there though)
                                    local oFactoryWeWantIntelOf
                                    local iCurEngineersWeLackIntelOf
                                    local bCanSeeSomeEngineers
                                    for iFactory, oFactory in toEnemyFactories do
                                        if not(oFactory.Dead) then
                                            local tPosition = oFactory:GetPosition()
                                            local oBP = oFactory:GetBlueprint()
                                            if not(oBP.SizeX) then oBP = __blueprints[oFactory.UnitId] end

                                            local rRectAroundFactory = Rect(tPosition[1] - iRadius - oBP.SizeX, tPosition[3] - iRadius, tPosition[1] + iRadius + oBP.SizeX, tPosition[3] + iRadius + oBP.SizeZ)
                                            local toUnitsInRect = GetUnitsInRect(rRectAroundFactory)
                                            if AiBotUtilities.IsTableEmpty(toUnitsInRect) == false then
                                                local toEngisInRect = EntityCategoryFilterDown(AiBotUnitInfo.refCategoryEngineer, toUnitsInRect)
                                                if AiBotUtilities.IsTableEmpty(toEngisInRect) == false and table.getn(toEngisInRect) >= 4 then
                                                    iCurEngineersWeLackIntelOf = 0
                                                    for iEngi, oEngi in toEngisInRect do
                                                        if not(oEngi.Dead) then
                                                            if not(oEngi[AiBotUnitInfo.reftAssignedWaterZoneByTeam][iTeam]) and not(AiBotUnitInfo.CanSeeUnit(aiBrain, oEngi)) then
                                                                iCurEngineersWeLackIntelOf = iCurEngineersWeLackIntelOf + 1
                                                            else
                                                                iCurDamageFromBomb = 20 + AiBotLogic.GetDamageFromBomb(aiBrain, oEngi:GetPosition(), iAOE, iStrikeDamage, nil, nil, false, nil, nil, 1, false, nil, true, nil, nil, nil, false, nil)
                                                                if iCurDamageFromBomb > iBestDamageFromBomb then
                                                                    oBestDamageFromBomb = oEngi
                                                                    iBestDamageFromBomb = iCurDamageFromBomb
                                                                    bCanSeeSomeEngineers = true
                                                                end
                                                            end
                                                        end
                                                    end
                                                    if bCanSeeSomeEngineers or iCurEngineersWeLackIntelOf == 0 then
                                                        oEnemyToTarget = oBestDamageFromBomb
                                                        if bDebugMessages == true then LOG(sFunctionRef..': oEnemyToTarget='..oEnemyToTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToTarget)) end
                                                        break
                                                    elseif iCurEngineersWeLackIntelOf >= 3 then
                                                        if not(oFactoryWeWantIntelOf) or AiBotUtilities.GetDistanceBetweenPositions(oFactoryWeWantIntelOf:GetPosition(), oBomber:GetPosition()) > AiBotUtilities.GetDistanceBetweenPositions(oFactory:GetPosition(), oBomber:GetPosition()) then
                                                            oFactoryWeWantIntelOf = oFactory
                                                        end
                                                    end
                                                end
                                            end
                                        end
                                    end
                                    if bDebugMessages == true then LOG(sFunctionRef..': oFactoryWeWantIntelOf='..(oFactoryWeWantIntelOf.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oFactoryWeWantIntelOf) or 'nil')) end
                                    if oFactoryWeWantIntelOf then
                                        AiBotOrders.IssueTrackedMove(oBomber, tClosestFactory, 5, false, 'NvBmbM', true)
                                    else
                                        if AiBotUnitInfo.IsUnitValid(oBestDamageFromBomb) then
                                            oEnemyToTarget = oBestDamageFromBomb
                                        elseif not(AiBotUnitInfo.IsUnitValid(oEnemyToTarget)) then
                                            --We dont seem to have any suitable targets so abort the logic altogether
                                            if bDebugMessages == true then LOG(sFunctionRef..': Aborting logic as dont seem to be any engineer clumps to target and no engineers to target either') end
                                            break
                                        end
                                    end
                                else
                                    oEnemyToTarget = oBestDamageFromBomb
                                end
                            end

                            if bDebugMessages == true then LOG(sFunctionRef..': Finished searching for enemy targets, oEnemyToTarget='..(oEnemyToTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToTarget) or 'nil')) end
                            if AiBotUnitInfo.IsUnitValid(oEnemyToTarget) then
                                --Target enemies, hover-bombing if the target is close
                                local iClosestDist = AiBotUtilities.GetDistanceBetweenPositions(oBomber:GetPosition(), oEnemyToTarget:GetPosition())
                                iStrikeDamage = math.max(150, iStrikeDamage) --assume we can 1-shot all engineers in case it gives strange results if we cant

                                --Hover-bomb if we have fired relatively recently
                                if bDebugMessages == true then LOG(sFunctionRef..': Deciding whether to hover-bomb, iClosestDist='..iClosestDist) end
                                if iClosestDist <= 50 and ((oBomber[AiBotUnitInfo.refiLastBombFired] and GetGameTimeSeconds() - oBomber[AiBotUnitInfo.refiLastBombFired] <= 10) or (not(oBomber[AiBotUnitInfo.refiLastBombFired]) and not(AiBotUnitInfo.IsUnitValid(oExistingValidAttackTarget)) and iClosestDist <= 30)) then
                                    --AiBotMicro.HoverBombTarget(oBomber, oNearestEnemy)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Will call hoverbomb logic to target '..oEnemyToTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oEnemyToTarget)) end
                                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                                    --NOTE: Dont call via fork thread, as otherwise we end up calling the same logic multiple times and it overriding orders
                                    AiBotMicro.T1OrT3HoverBombTarget(oBomber, oEnemyToTarget, true, (EntityCategoryContains(AiBotUnitInfo.refCategoryStructure, oEnemyToTarget.UnitId) or oEnemyToTarget:GetFractionComplete() < 1), true) --Dont do via fork thread, as want this logic to be dleayed so we dont rerun it
                                    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                                    if bDebugMessages == true then LOG(sFunctionRef..': Finished hoverbomb attempt') end
                                    iTicksToWait = 1 --Just to avoid infinite loop risk
                                else
                                    if bDebugMessages == true then LOG(sFunctionRef..': WIll use normal bomber attack logic, but just with oEnemyToTarget') end
                                    AssignTorpOrBomberTargets({ oBomber}, { oEnemyToTarget }, iAirSubteam, false, false, true)
                                end
                            end
                        end
                        if bDebugMessages == true then LOG(sFunctionRef..': End of loop, will wait '..iTicksToWait..' ticks') end
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
                        WaitTicks(iTicksToWait)
                        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
                    end
                end
            end
        end
    end

    if oBomber[AiBotUnitInfo.refbSpecialMicroActive] then
        oBomber[AiBotUnitInfo.refbSpecialMicroActive] = false
        ForkThread(AiBotMicro.ForkedResetMicroFlag, oBomber, 0) --redundancy
    end
    oBomber[refiBomberTargetNavalEngiWZ] = nil
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
end

function GetTimeForExpBomberToTurnToRally(oUnit, oWeapon, oProjectile)
    --Assumes we are calling this when bomb is fired, whereas tiRecentExpBomberTargets should be updated from AiBotMicro which is via forked thread so should take place after bomb fired
    --i.e. if cycle through tiRecentExpBomberTargets it should only show other bombs, not this unit's bomb
    local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
    local sFunctionRef = 'GetTimeForExpBomberToTurnToRally'
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

    local iTimeToWait = 15
    if AiBotUtilities.IsTableEmpty(tiRecentExpBomberTargets) == false then
        local tOurTarget = (oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition] or AiBotMicro.GetBombTarget(oWeapon, oProjectile))
        if AiBotUtilities.IsTableEmpty(tOurTarget) == false then
            --Is our bomb firing at the same place as another bomb, yet the enemy lacks shields here, and we fired within 2 seconds of the last bomb?
            local bMultipleBombs = false
            for _, tTarget in tiRecentExpBomberTargets do
                if bDebugMessages == true then LOG(sFunctionRef..': Dist to tTarget='..AiBotUtilities.GetDistanceBetweenPositions(tTarget, tOurTarget)) end
                if AiBotUtilities.GetDistanceBetweenPositions(tTarget, tOurTarget) <= 19 then
                    bMultipleBombs = true
                    break
                end
            end
            if bMultipleBombs then
                --Are there any bombers other than this that have fired in the last 1.5 seconds?
                local iMostRecentNearbyBombFired = 0
                local iTeam = oUnit:GetAIBrain().AiBotTeam
                for iBrain, oBrain in AiBotTeam.tTeamData[iTeam][AiBotTeam.subreftoFriendlyActiveAiBotBrains] do
                    local tAhwassas = oBrain:GetListOfUnits(categories.xsa0402, false, true)
                    if AiBotUtilities.IsTableEmpty(tAhwassas) == false then
                        for _, oFriendlyBomber in tAhwassas do
                            if bDebugMessages == true then LOG(sFunctionRef..': Considering oFriendlyBomber='..oFriendlyBomber.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oFriendlyBomber)..' owned by oBrain='..oBrain.Nickname..'; Dist to oUnit='..AiBotUtilities.GetDistanceBetweenPositions(oFriendlyBomber:GetPosition(), oUnit:GetPosition())..'; Time since last fired bomb='..(GetGameTimeSeconds() - (oFriendlyBomber[AiBotUnitInfo.refiLastBombFired] or 0))) end
                            if oFriendlyBomber:GetFractionComplete() == 1 and not(oFriendlyBomber == oUnit) and oFriendlyBomber[AiBotUnitInfo.refiLastBombFired] and AiBotUtilities.GetDistanceBetweenPositions(oFriendlyBomber:GetPosition(), oUnit:GetPosition()) <= 60 then
                                if not(iMostRecentNearbyBombFired) then iMostRecentNearbyBombFired = oFriendlyBomber[AiBotUnitInfo.refiLastBombFired]
                                else iMostRecentNearbyBombFired = math.max(iMostRecentNearbyBombFired, oFriendlyBomber[AiBotUnitInfo.refiLastBombFired])
                                end
                            end
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': iMostRecentNearbyBombFired='..iMostRecentNearbyBombFired..'; Time since this='..GetGameTimeSeconds() - iMostRecentNearbyBombFired) end
                if GetGameTimeSeconds() - iMostRecentNearbyBombFired <= 3 then
                    iTimeToWait = iTimeToWait + math.max(0.5, 3 - (GetGameTimeSeconds() - iMostRecentNearbyBombFired))
                end
            end
        end
    end

    if bDebugMessages == true then LOG(sFunctionRef..': end of code for obmber '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' owned by '..oUnit:GetAIBrain().Nickname..' at time='..GetGameTimeSeconds()..'; iTimeToWait='..iTimeToWait..'; Is tiRecentExpBomberTargets empty='..tostring(AiBotUtilities.IsTableEmpty(tiRecentExpBomberTargets))..'; oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition]='..repru(oUnit[AiBotOrders.reftiLastOrders][1][AiBotOrders.subreftOrderPosition])) end
    AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    return iTimeToWait
end

function InRangeOfEnemyAirAA(oFrontAAGunship)
    --Idea being we dont want to retreat if enemy isnt in range of us in some scenarios, and we arnet in range of them
    local aiBrain = oFrontAAGunship:GetAIBrain()
    local iSearchRange = math.max((oFrontAAGunship[AiBotUnitInfo.refiAARange] or 0) - 1, 40)
    local tEnemyAirAA = aiBrain:GetUnitsAroundPoint(AiBotUnitInfo.refCategoryAirAA + AiBotUnitInfo.refCategoryCzar + AiBotUnitInfo.refCategoryRestorer, oFrontAAGunship:GetPosition(), iSearchRange, 'Enemy')
    if AiBotUtilities.IsTableEmpty(tEnemyAirAA) == false then
        for iUnit, oUnit in tEnemyAirAA do
            if not(oUnit.Dead) and oUnit:GetFractionComplete() == 1 then
                return true
            end
        end
    end
    return false
end
